_SAFE_SLUG_RE = re.compile(r"^(?!\.\.?$)[A-Za-z0-9._-]+$")  # a run folder name: no path separators, not . or ..
_STATE_LOCK_HELD = False  # set by main() while this process holds the state lock for its whole command


class Ctx:
    def __init__(self, root: Path):
        self.root = root
        self.ratchet = root / RATCHET_DIR

    # --- config
    @property
    def config_path(self):
        return self.ratchet / "config.json"

    def config(self):
        return config_from_user(read_json(self.config_path, {}) or {})

    # --- active run
    def active_slug(self):
        """The active run's slug from active.json. A damaged active.json names the run this project registered in the
        per-user folder (active-runs.json, written with it at init) when that run's folder is here; otherwise no run.
        accept-state writes it again."""
        p = self.ratchet / "active.json"
        a, why = _read_record(p)
        if why is None:
            return a.get("slug")
        slug = (_active_marker(self.root) or {}).get("slug")
        if not (isinstance(slug, str) and _SAFE_SLUG_RE.match(slug) and (self.ratchet / "runs" / slug).is_dir()):
            slug = None
        _note_unreadable(p, why, f"Ratchet uses the active run recorded in its per-user folder, '{slug}'" if slug
                         else "Ratchet finds no active run recorded for this project in its per-user folder either")
        return slug

    def run_dir(self, slug=None) -> Path:
        slug = slug or self.active_slug()
        if not slug:
            die("No active Ratchet run. Start one with: ratchet.py init \"<feature>\"")
        return self.ratchet / "runs" / slug

    def state_path(self, slug=None):
        return self.run_dir(slug) / "state.json"

    def state(self, slug=None):
        """The run's state. Every command that changes a run holds the state lock from before this read to after its
        last save (see main), so nothing else changes state.json in between. A chat the prompt hook recorded for a
        run no chat owned yet becomes its owner here (the hook itself never writes state.json); a command holding
        the lock saves that at once."""
        p = self.state_path(slug)
        verify_chain(p, "state.json")
        st, why = _read_record(p, missing=None)
        if why is not None:
            die(f"The run's state.json ({p}) can't be read ({why}), so nothing was done. Tell the user; restore it "
                "from a backup or their git history, or, to start the feature over, they can run "
                "`RATCHET_HUMAN_OVERRIDE=1 ratchet.py init --force \"<feature>\"` from their own terminal.")
        if st is None:
            die("state.json missing for active run")
        if _bind_prompt_owner(self, st) and _STATE_LOCK_HELD:
            self.save_state(st)
        return st

    def save_state(self, st):
        st["updated_at"] = now()
        if st.get("hooks_waived") and not _waiver_applies(self.root, self.config(), st):
            st.pop("hooks_waived", None)
            st["hooks_waive_n"] = int(st.get("hooks_waive_n", 0)) + 1  # hooks are installed or fired: the old consent must not resurface later
            self.log(st, "hooks_waive_cleared", note="enforcement hooks are active")
        _write_record(self.state_path(st["slug"]), st, pretty=True)
        record_chain(self.state_path(st["slug"]))

    def plan(self, slug=None):
        return read_json(self.run_dir(slug) / "checkpoints.json")

    def evidence(self, cp_id: str, slug=None) -> Path:
        d = self.run_dir(slug) / "evidence" / cp_id
        d.mkdir(parents=True, exist_ok=True)
        return d

    def log(self, st, event: str, **data):
        st.setdefault("history", []).append({"at": now(), "event": event, **data})
        # a PROGRESS_EVENTS entry also restarts the stop hook's count of stops without progress (_stop_blocks), and
        # ends a wait set with `ratchet.py wait` (the agent carries on from the progress instead)
        if (event in PROGRESS_EVENTS or event in WAIT_ENDING_EVENTS) and st.pop("wait", None) is not None:
            st["history"].append({"at": now(), "event": "wait_cleared", "by": event})


# --------------------------------------------------------------------------- fingerprint
#
# _is_git/_LookFailed/_git_tree_id/fingerprint/_head_sha/_commit_reviewed/_head_commit_named/changed_files/
# touches_ui now live in fingerprint.py, imported by name above, along with JUNK_PATHSPECS and
# FINGERPRINT_EXCLUDES; RATCHET_DIR lives in engine_utils.py. All are imported by name above.


# --------------------------------------------------------------------------- quick path (`ratchet.py changes`)

def _glob_hit(f: str, globs: list[str]) -> bool:
    """True when f's basename or full repo-relative path matches one of globs — touches_ui's own rule. A
    directory-shaped glob (one containing "/", e.g. "agents/*.md") also matches at any depth below the repo
    root (e.g. "apps/bot/agents/x.md"), not only directly under a root-level directory of that name, so a
    per-package instruction-file layout is a normal, expected match rather than a silent gap."""
    name = os.path.basename(f)
    return any(fnmatch.fnmatch(name, g) or fnmatch.fnmatch(f, g) or ("/" in g and fnmatch.fnmatch(f, "*/" + g))
               for g in globs)


def _project_files(root: Path, fp: dict) -> list[str]:
    """Every file in fp's tree (tracked and untracked, minus .ratchet) — not just what git has staged or
    committed — so a doc-naming test file still counts even before anyone runs `git add`."""
    if fp.get("kind") == "git-tree":
        r = subprocess.run(["git", "ls-tree", "-r", "--name-only", "--full-tree", fp["id"]], cwd=root,
                           capture_output=True, text=True)
        return [l for l in r.stdout.splitlines() if l]
    return sorted(read_json(root / RATCHET_DIR / "manifests" / f"{fp['id']}.json", {},
                            record="Ratchet treats it as naming no files (the fingerprint manifest cache, named "
                                   "by its own hash)") or {})


def _code_size(ctx: "Ctx", from_id: str, to_id: str, code_files: list[str]) -> tuple[int | None, list[str]]:
    """git diff --numstat added+removed line count for code_files between two tree ids. Git prints "-\t-\tpath"
    for a file it can't diff as text (binary): that size is unknown, not zero, so the total is reported as
    `None` (never a partial sum that silently drops the unknown files) whenever any code file is uncountable.
    Returns (total_or_None, the uncountable file paths)."""
    if not code_files:
        return 0, []
    r = subprocess.run(["git", "diff", "--numstat", from_id, to_id, "--", *code_files], cwd=ctx.root,
                       capture_output=True, text=True)
    total, unknown = 0, []
    for line in r.stdout.splitlines():
        parts = line.split("\t")
        if len(parts) < 3:
            continue
        try:
            total += int(parts[0]) + int(parts[1])
        except ValueError:
            unknown.append(parts[2])  # binary file: numstat prints "-\t-\tpath"; size can't be counted
    return (None if unknown else total), unknown


_PY_EXT = (".py",)
_JS_EXT = (".js", ".jsx", ".ts", ".tsx", ".mjs", ".cjs")


def _import_forms(path: str) -> list[re.Pattern]:
    """The import shapes under which a test names the code file `path` without spelling its path or file name:
    for Python, its dotted module path and the `from <package> import <module>` statement (`src/app/billing.py`:
    `src.app.billing`, `app.billing`, `src/app/billing`, `app/billing`, `from app import billing`; a top-level
    `billing.py`: `import billing`, `from billing import`); for JS/TS, its extension-less repo path and a quoted
    module specifier ending in `/<stem>` (`src/billing.ts`: `src/billing`, `'../billing'`, `'./billing.js'`).
    Never a bare stem on its own, which would pull in the whole suite. Empty for any other file kind."""
    stem, ext = os.path.splitext(path)
    parts = stem.split("/")
    forms: list[re.Pattern] = []
    if ext in _PY_EXT and parts[-1] != "__init__":
        for i in range(len(parts) - 1):
            tail = parts[i:]
            forms.append(re.compile(r"(?<![\w.])" + r"\.".join(map(re.escape, tail)) + r"(?!\w)"))
            forms.append(re.compile(re.escape("/".join(tail)) + r"(?!\w)"))
            forms.append(re.compile(r"\bfrom\s+" + r"\.".join(map(re.escape, tail[:-1])) + r"\s+import\s+[^\n]*\b"
                                    + re.escape(tail[-1]) + r"\b"))
        if len(parts) == 1:
            forms.append(re.compile(r"^\s*(?:import\s+" + re.escape(stem) + r"\b|from\s+" + re.escape(stem)
                                    + r"\s+import\b)", re.M))
    elif ext in _JS_EXT:
        forms.append(re.compile(re.escape(stem) + r"(?![\w$])"))  # src/billing, never src/billing2
        forms.append(re.compile(r"/" + re.escape(parts[-1]) + r"(?:\.(?:js|jsx|ts|tsx|mjs|cjs))?['\"]"))
    return forms


def _names_file(text: str, path: str) -> bool:
    """Whether `text` names the file `path`: its repo-relative path or file name as a plain substring, or one of
    the import shapes `_import_forms` lists for its kind (so a test that imports a changed module counts)."""
    if path in text or os.path.basename(path) in text:
        return True
    return any(p.search(text) for p in _import_forms(path))


def _tests_naming(ctx: "Ctx", cfg: dict, fp: dict, docs: list[str]) -> list[str]:
    """Which test files (test_globs) name any of `docs` by its repo-relative path or file name (a plain
    substring match, never guessed), or import it (`_names_file`: a Python module's dotted path, a JS/TS module's
    extension-less path). Shared by both of classify_changes's ranges (base_tree and since_approval)
    so a doc that is changed and then restored in one range, but not the other, still gets the tests that name
    it from whichever range actually lists it as changed."""
    if not docs:
        return []
    out = []
    candidates = [t for t in _project_files(ctx.root, fp) if _glob_hit(t, cfg.get("test_globs") or [])]
    for t in sorted(set(candidates)):
        try:
            text = (ctx.root / t).read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        if any(_names_file(text, d) for d in docs):
            out.append(t)
    return out


def classify_changes(ctx: "Ctx", cp_id: str) -> dict:
    """Read-only report of what changed since cp_id's base_tree: which files are docs (doc_globs, minus
    doc_exclude_globs plus the configured design_md and standards files), which are code, how many code lines
    changed in the code files (git diff --numstat, added+removed), which test files (test_globs) name a changed
    doc by its repo-relative path or file name, and whether doc_test_command is configured at all. A code file
    git can't diff as text (binary) makes `code_lines_changed` None and `code_lines_unknown` True: an unknown
    size is reported plainly, never as zero, so it can never read as a small change. `since_approval` repeats
    the same report (its own `doc_test_files` included, matched independently against its own `doc_files` so a
    doc changed then restored in one range but not the other still gets the tests naming it from whichever
    range actually lists it) for the narrower range from the adversarial gate's last recorded approval
    fingerprint (when that gate has one) to now, plus a plain `docs_only`; when there is no recorded approval
    yet (gate not required, or required but not yet passed), `approved` is False with a plain reason and the
    rest are empty.
    Never writes, and never gates: a locked reference file (DESIGN.md, standards) drifting since approval is
    still just reported here as a changed file, not refused (that refusal is every other command's, not this
    read-only report's). Which check (docs quick path, small fix, or full) applies to either range is not this
    report's decision."""
    st = ctx.state()
    cps = (st.get("checkpoints") or {}).get(cp_id)
    if cps is None:
        die(f"{cp_id} is not a checkpoint in this run.")
    cfg = ctx.config()
    base = cps.get("base_tree")
    fp = fingerprint(ctx.root)
    files = sorted(changed_files(ctx.root, {"kind": "git-tree", "id": base}, fp)) if base else []
    doc_files, code_files = _classify_doc_code(cfg, files)
    code_lines, code_unknown = _code_size(ctx, base, fp["id"], code_files) if base else (0, [])
    doc_test_files = _tests_naming(ctx, cfg, fp, doc_files)
    doc_cmd = cfg.get("doc_test_command")
    adv = (cps.get("gates") or {}).get("adversarial") or {}
    approval_fp = adv.get("fingerprint")
    if not approval_fp:
        since_approval = {
            "approved": False,
            "reason": ("the adversarial gate is not required for this checkpoint" if not adv.get("required")
                      else "the adversarial gate has not been approved yet for this checkpoint"),
            "doc_files": [], "code_files": [], "code_lines_changed": 0, "code_lines_unknown": False,
            "doc_test_files": [], "docs_only": None,
        }
    else:
        a_files = sorted(changed_files(ctx.root, approval_fp, fp))
        a_doc_files, a_code_files = _classify_doc_code(cfg, a_files)
        a_lines, a_unknown = _code_size(ctx, approval_fp["id"], fp["id"], a_code_files)
        since_approval = {
            "approved": True,
            "reason": None,
            "doc_files": a_doc_files,
            "code_files": a_code_files,
            "code_lines_changed": a_lines,
            "code_lines_unknown": bool(a_unknown),
            "doc_test_files": _tests_naming(ctx, cfg, fp, a_doc_files),
            "docs_only": len(a_code_files) == 0,
        }
    return {
        "docs_only": len(code_files) == 0,
        "doc_files": doc_files,
        "code_files": code_files,
        "code_lines_changed": code_lines,
        "code_lines_unknown": bool(code_unknown),
        "doc_test_files": doc_test_files,
        "doc_quick_path": {"enabled": bool(doc_cmd),
                            "reason": None if doc_cmd else "doc_test_command is not configured"},
        "since_approval": since_approval,
    }


def cmd_changes(args):
    """`ratchet.py changes CPn [--json]`: classify_changes, read-only (not in STATE_LOCKED_CMDS)."""
    ctx = Ctx(find_root())
    data = classify_changes(ctx, args.cp)
    if getattr(args, "json", False):
        print(json.dumps(data, indent=2))
        return
    print(f"docs only: {data['docs_only']}")
    print(f"doc files: {', '.join(data['doc_files']) or '(none)'}")
    print(f"code files: {', '.join(data['code_files']) or '(none)'}")
    print(f"code lines changed: {'unknown (binary code change)' if data['code_lines_unknown'] else data['code_lines_changed']}")
    print(f"doc test files: {', '.join(data['doc_test_files']) or '(none)'}")
    qp = data["doc_quick_path"]
    print(f"docs quick path: {'on' if qp['enabled'] else 'off'}" + (f" ({qp['reason']})" if qp["reason"] else ""))
    sa = data["since_approval"]
    if not sa["approved"]:
        print(f"since approval: not approved yet ({sa['reason']})")
    else:
        sa_lines = "unknown (binary code change)" if sa["code_lines_unknown"] else sa["code_lines_changed"]
        print(f"since approval: docs only={sa['docs_only']}, doc files: {', '.join(sa['doc_files']) or '(none)'}, "
              f"code files: {', '.join(sa['code_files']) or '(none)'}, code lines changed: {sa_lines}, "
              f"doc test files: {', '.join(sa['doc_test_files']) or '(none)'}")


# --------------------------------------------------------------------------- doc quick path at `complete` (CP2)
# Doc edits made after a gate's own approval never reopen a review round: when every file changed since that
# gate's recorded fingerprint is a doc (the one doc/code split in `_classify_doc_code`, also used by
# classify_changes above so the two can never disagree) and doc_test_command is configured, `cmd_complete` runs
# just the test files naming those docs instead of marking the gate stale. The same rule also lets a passing
# full suite stay valid across a doc-only edit (`_skip_full_suite`), and every doc edit skipped this way is
# recorded on the checkpoint (`doc_edits_unreviewed`) so the commit message, `status` and the final review can
# all say so.

def _classify_doc_code(cfg: dict, files: list[str]) -> tuple[list[str], list[str]]:
    """The one doc/code split (doc_globs, minus doc_exclude_globs plus the configured design_md and standards
    files) for an arbitrary file list. `classify_changes` above and `cmd_complete`'s quick path both call this
    so what counts as a doc can never drift between the read-only report and the gate that skips review."""
    exclude = [g for g in [*(cfg.get("doc_exclude_globs") or []), cfg.get("design_md"),
                           *(cfg.get("standards") or [])] if g]
    doc_globs = cfg.get("doc_globs") or []
    doc_files = [f for f in files if _glob_hit(f, doc_globs) and not _glob_hit(f, exclude)]
    code_files = [f for f in files if f not in doc_files]
    return doc_files, code_files


def _run_doc_test_command(ctx: "Ctx", cfg: dict, files: list[str], log_path: Path) -> tuple[int, str]:
    """Runs doc_test_command with its {files} placeholder filled in by `files` (shlex-quoted, space-joined),
    logged the same way _run_cmd logs regression_command. Returns (exit code, combined stdout+stderr)."""
    cmd = cfg["doc_test_command"].replace("{files}", " ".join(shlex.quote(f) for f in files))
    code, out, _ = _run_cmd(ctx, cmd, log_path, cfg["test_timeout_sec"])
    return code, out


def _skip_full_suite(ctx: "Ctx", cfg: dict, st: dict, fp: dict) -> tuple[bool, list[str]]:
    """(True, the doc files involved) when regression_command already passed on a tree recorded at
    st['regression_passed_fp'] that differs from `fp` only in docs (and doc_test_command is configured), so
    `complete` can run just those docs' naming tests instead of the full suite again. (False, []) when there is
    no recorded pass yet, the doc quick path is off, or anything that changed since is code."""
    passed_fp = st.get("regression_passed_fp")
    if not passed_fp or not cfg.get("doc_test_command"):
        return False, []
    changed = [f for f in changed_files(ctx.root, passed_fp, fp)
              if f != RATCHET_DIR and not f.startswith(RATCHET_DIR + "/")]
    if not changed:
        return True, []
    doc_files, code_files = _classify_doc_code(cfg, changed)
    return (not code_files), doc_files


# --------------------------------------------------------------------------- related tests before the full suite
# Right before `complete` runs regression_command, it runs the few test files related to what the step changed
# since its base_tree (related_test_command with {files}): the step's own planned test files ("planned test"),
# the test files it changed ("changed test"), and the test files that name a changed file, deleted ones included,
# by its path or file name or by importing it ("names <file>", _tests_naming's match through _names_file), ranked
# by the function names the step changed and capped at related_tests_max. A
# failure stops the step at once, naming the file, and the full suite is never started; it is not a suite
# failure, so it spends no flaky re-run and leaves every gate as it was. The files in related_always join the
# list outside the cap whenever the step adds a test file, changes a doc, or adds or changes a code line holding
# a quoted string ("doc check: <trigger>"). The pass runs only when the full suite is about to run.

_RELATED_LABEL_PLANNED = "planned test"
_RELATED_LABEL_CHANGED = "changed test"
_NO_FILES_PLACEHOLDER_MSG = ("related_test_command has no {files} placeholder, so it cannot run only the related "
                             "files (it would run the whole suite twice); set it to a command with {files} (for "
                             "example 'pnpm vitest run {files}') or unset it to turn the related pass off.")
_DEF_LINE_RE = re.compile(r"^\s*(?:(?:export|default|async|static|public|private|protected|pub|abstract|override|"
                          r"final|unsafe|extern)\s+)*(?:def|function|fn|func|class|struct|interface|trait|impl|enum|"
                          r"sub|proc|method)\b")
_DEF_SKIP_WORDS = {"export", "default", "async", "static", "public", "private", "protected", "pub", "abstract",
                   "override", "final", "unsafe", "extern", "def", "function", "fn", "func", "class", "struct",
                   "interface", "trait", "impl", "enum", "sub", "proc", "method", "const", "let", "var", "type",
                   "import", "from", "if", "else", "for", "while", "return", "switch", "case", "try", "catch",
                   "with", "as", "new", "this", "self", "module", "package", "use", "require"}
_STRING_LITERAL_RE = re.compile(r'"[^"\n]*"|\'[^\'\n]*\'|`[^`\n]*`')


def _related_tests_max(cfg: dict) -> tuple[int, str | None]:
    """(the cap on the related list, a note when the configured value was ignored): related_tests_max must be a
    whole number of 1 or more; anything else (0, a word, a fraction) falls back to the default so the pass is
    never run with no files by accident."""
    default = int(DEFAULT_CONFIG["related_tests_max"])
    raw = cfg.get("related_tests_max", default)
    try:
        v = int(raw) if not isinstance(raw, bool) and float(raw) == int(raw) else None
    except (TypeError, ValueError):
        v = None
    if v is None or v < 1:
        return default, (f"related_tests_max is {json.dumps(raw)}, not a whole number of 1 or more; "
                         f"ignored, using the default {default}")
    return v, None


def _defined_name(line: str) -> str | None:
    """The name a definition-shaped line defines (git's own funcname rule, a line starting in column 0 with a
    letter, `_` or `$`, plus indented def/function/class/fn lines so a Python method or a nested function
    counts too): its first word that is not a keyword or modifier. None for any other line."""
    if not line or not (line[0].isalpha() or line[0] in "_$" or _DEF_LINE_RE.match(line)):
        return None
    for m in re.finditer(r"[A-Za-z_$][\w$]*", line):
        if m.group(0) not in _DEF_SKIP_WORDS:
            return m.group(0)
    return None


def _enclosing_names(text: str) -> list[str | None]:
    """For every line of `text` (by index), the name of the nearest definition-shaped line at or above it."""
    out, cur = [], None
    for line in text.splitlines():
        name = _defined_name(line)
        if name:
            cur = name
        out.append(cur)
    return out


def _changed_lines(ctx: "Ctx", base: str, fp: dict, files: list[str]) -> dict:
    """Per file (git diff -U0 between the step's base tree and `fp`): {"added": [(line number in the new file,
    text)], "removed": [line numbers in the old file]}. Only the files given are diffed."""
    out: dict = {}
    if not files:
        return out
    r = subprocess.run(["git", "diff", "-U0", "--no-color", "--no-renames", "--src-prefix=a/", "--dst-prefix=b/",
                        base, fp["id"], "--", *files], cwd=ctx.root, capture_output=True, text=True, errors="replace")
    cur, new_no, old_no, in_header = None, 0, 0, False
    for line in r.stdout.splitlines():
        # `--- `/`+++ ` are file headers only between a `diff --git` line and the first hunk; inside a hunk a
        # removed `-- note` or an added `++ x` line looks the same and must count as content.
        if line.startswith("diff --git "):
            in_header, cur = True, None
            continue
        if in_header and line.startswith("+++ "):
            path = line[4:]
            cur = path[2:] if path.startswith("b/") else (None if path == "/dev/null" else path)
            if cur is not None:
                out.setdefault(cur, {"added": [], "removed": []})
            in_header = False
            continue
        if in_header or cur is None:
            continue
        m = re.match(r"@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@", line)
        if m:
            old_no, new_no = int(m.group(1)), int(m.group(2))
            continue
        if line.startswith("+"):
            out[cur]["added"].append((new_no, line[1:]))
            new_no += 1
        elif line.startswith("-"):
            out[cur]["removed"].append(old_no)
            old_no += 1
    return out


def _changed_function_names(ctx: "Ctx", base: str, lines: dict) -> set[str]:
    """The names of the functions (definition-shaped lines, `_defined_name`) that hold an added or changed line
    in the working tree, or a removed line in the base tree, for the files in `lines` (`_changed_lines`)."""
    names: set[str] = set()
    for path, d in lines.items():
        if d["added"]:
            try:
                encl = _enclosing_names((ctx.root / path).read_text(encoding="utf-8", errors="replace"))
            except OSError:
                encl = []
            for no, _ in d["added"]:
                if 0 < no <= len(encl) and encl[no - 1]:
                    names.add(encl[no - 1])
        if d["removed"]:
            r = subprocess.run(["git", "show", f"{base}:{path}"], cwd=ctx.root, capture_output=True, text=True,
                               errors="replace")
            encl = _enclosing_names(r.stdout) if r.returncode == 0 else []
            for no in d["removed"]:
                if 0 < no <= len(encl) and encl[no - 1]:
                    names.add(encl[no - 1])
    return names


def _related_tests(ctx: "Ctx", cfg: dict, cp: dict, cps: dict, fp: dict) -> dict:
    """Which test files `complete` runs before the full suite, and why: {"picked": [(file, reason)], "notes":
    [plain lines for the output], "candidates": how many files beyond the step's own planned ones were found,
    "cap": the cap in force}. The step's own planned test files come first ("planned test"), then the test files
    (test_globs) it changed ("changed test"), then the test files naming a file it changed ("names <file>"),
    those mentioning a changed function name before the rest; the cap (related_tests_max) keeps the first N of
    that order. Each file in related_always is then added once, outside the cap, when the step added a test file,
    changed a doc, or added or changed a code line (not a test, not a doc) holding a quoted string, with a reason
    naming the trigger(s) ("doc check: new test file"); a file already picked keeps its first reason; one that
    does not exist is skipped with a note. A deleted file is never handed to the command."""
    base = cps.get("base_tree")
    cap, cap_note = _related_tests_max(cfg)
    notes = [cap_note] if cap_note else []
    test_globs = cfg.get("test_globs") or []
    exists = set(_project_files(ctx.root, fp))
    picked: list[tuple[str, str]] = []
    seen: set[str] = set()

    def add(f, reason):
        if f not in seen:
            seen.add(f)
            picked.append((f, reason))

    for f in _as_list((cp.get("tests") or {}).get("files") or []):
        if f in exists:
            add(f, _RELATED_LABEL_PLANNED)
        else:
            notes.append(f"planned test file {f} is not in the project; not run")
    status: dict = {}
    if base:
        r = subprocess.run(["git", "diff-tree", "-r", "-z", "--no-renames", "--name-status", base, fp["id"]],
                           cwd=ctx.root, capture_output=True)
        parts = r.stdout.decode("utf-8", "surrogateescape").split("\0") if r.returncode == 0 else []
        for s, f in zip(parts[0::2], parts[1::2]):
            if f and f != RATCHET_DIR and not f.startswith(RATCHET_DIR + "/"):
                status[f] = s[:1]
    changed = sorted(status)
    changed_tests = [f for f in changed if _glob_hit(f, test_globs) and f in exists]
    for f in changed_tests:
        add(f, _RELATED_LABEL_CHANGED)
    doc_files, code_files = _classify_doc_code(cfg, changed)
    code_files = [f for f in code_files if not _glob_hit(f, test_globs)]
    # Deleted and renamed-away files stay search keys: a test naming a module the step removed is the one most
    # likely to break. Only the test files handed to the command must exist.
    named = [f for f in changed if not _glob_hit(f, test_globs)]
    naming = [t for t in _tests_naming(ctx, cfg, fp, named) if t not in seen]
    lines = _changed_lines(ctx, base, fp, code_files) if base else {}
    hot = _changed_function_names(ctx, base, lines) if base else set()
    ranked = []
    for t in naming:
        try:
            text = (ctx.root / t).read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        names_it = [f for f in named if _names_file(text, f)]
        hits = sum(1 for n in hot if re.search(r"\b" + re.escape(n) + r"\b", text))
        ranked.append((-hits, t, names_it))
    for _, t, names_it in sorted(ranked):
        add(t, "names " + ", ".join(names_it[:3]) + (", ..." if len(names_it) > 3 else ""))
    candidates = len(picked) - sum(1 for _, r in picked if r == _RELATED_LABEL_PLANNED)
    picked = picked[:cap]
    triggers = []
    if any(status.get(f) == "A" for f in changed_tests):
        triggers.append("new test file")
    if doc_files:
        triggers.append("doc file changed")
    if any(_STRING_LITERAL_RE.search(text) for d in lines.values() for _, text in d["added"]):
        triggers.append("user-facing text")
    always = _as_list(cfg.get("related_always") or [])
    if triggers:
        kept = {f for f, _ in picked}
        for f in always:
            if f in kept:
                continue
            if f not in exists:
                notes.append(f"{f} is named in related_always but was not found in the project; skipped")
                continue
            kept.add(f)
            picked.append((f, "doc check: " + ", ".join(triggers)))
    return {"picked": picked, "notes": notes, "candidates": candidates, "cap": cap}


def _failing_files(out: str, files: list[str]) -> list[str]:
    """The picked files the runner's output reports as failed: each file whose repo-relative path or bare file
    name (word-bounded, as tests/run_all.py prints `FAILED (exit 1)  test_x.py` and `Failed: test_x.py`) sits on
    a failure line: one carrying a failure status token (the whole word FAIL/FAILED/failed in any case, or a
    ✗/✕/× mark, never `fails` inside a test title) and no pass mark (PASS/PASSED/passed/ok, ✓/√), so a passing
    test whose title says "fails" (vitest `✓ ... > login fails`, pytest `::test_login_fails PASSED`) is never
    named."""
    lines = [l for l in out.splitlines()
             if re.search(r"\bfail(?:ed)?\b|[✗✕×]", l, re.I) and not re.search(r"\b(?:pass(?:ed)?|ok)\b|[✓√]", l, re.I)]
    hit = []
    for f in files:
        name = re.escape(os.path.basename(f))
        if any(f in l or re.search(r"(?<![\w/.-])" + name + r"(?![\w-])", l) for l in lines):
            hit.append(f)
    return hit


def _run_related_tests(ctx: "Ctx", cfg: dict, cp: dict, cps: dict, fp: dict, watch: "_Watch | None" = None) -> None:
    """The related pass at `complete`, right before the full suite: says which files were picked and why, runs
    related_test_command on them (evidence/CPn/related-tests.log) and dies, naming the failing file(s), when it
    fails, without saving state (same as the full suite's failure branch); the full suite is then never started
    and no gate, attempt count or flaky allowance changes. With related_test_command unset it only says the pass
    is off; a value without {files} is refused before anything runs. `watch` is `complete`'s code watch: an edit
    during the related run stops it the same way (code changed, nothing saved, run `complete` again)."""
    cp_id = cp["id"]
    if not cfg.get("related_test_command"):
        print("Related tests: off (related_test_command is not configured); running the full suite directly.")
        return
    if "{files}" not in str(cfg["related_test_command"]):
        die(_NO_FILES_PLACEHOLDER_MSG, 2)
    sel = _related_tests(ctx, cfg, cp, cps, fp)
    picked, notes, cap = sel["picked"], sel["notes"], sel["cap"]
    for n in notes:
        print(f"Related tests: {n}")
    ranked = [f for f, r in picked if not r.startswith("doc check")]
    own = sum(1 for _, r in picked if r == _RELATED_LABEL_PLANNED)
    if sel["candidates"] + own > cap:
        print(f"Related tests: picked {len(ranked)} of {sel['candidates']} other candidate(s) and {own} planned test "
              f"file(s) together (cap related_tests_max={cap})"
              + ("; the doc check is added on top of the cap" if len(picked) > len(ranked) else ""))
    if not picked:
        print("Related tests: nothing to run before the full suite (no planned, changed or naming test file).")
        return
    print(f"Related tests (before the full suite), {len(picked)} file(s):")
    for f, reason in picked:
        print(f"  - {f}: {reason}")
    files = [f for f, _ in picked]
    cmd = cfg["related_test_command"].replace("{files}", " ".join(shlex.quote(f) for f in files))
    code, out, _ = _run_cmd(ctx, cmd, ctx.evidence(cp_id) / "related-tests.log", cfg["test_timeout_sec"], watch=watch)
    if code != 0:
        # Like the full suite's failure branch below in `complete`: print the tail and die without saving state,
        # so nothing from this failed call (a doc quick-path record above it) is persisted.
        print(_tail(out))
        failing = _failing_files(out, files)
        die(f"{cp_id} cannot complete: a related test failed (exit {code}) before the full suite, which was not "
            f"started" + (f"; failing: {', '.join(failing)}" if failing else "") + ". Fix it and run complete again; "
            f"this was not a suite failure, so no flaky re-run was spent and no gate changed. Files run:\n  - "
            + "\n  - ".join(f"{f} ({r})" for f, r in picked), 2)
    if fingerprint(ctx.root)["id"] != fp["id"]:
        die("The related test command changed files in the project. Those changes were never reviewed; find out "
            "what wrote them (generated files? snapshots?) and either add them to .gitignore or re-run the gates.", 2)


def _doc_edit_status_lines(st: dict) -> list[str]:
    """One plain line per checkpoint whose doc edit(s) after review were never re-reviewed (CP2's quick path),
    for `status`, the commit message and the final review to all say the same thing about the same files."""
    lines = []
    for cid, c in (st.get("checkpoints") or {}).items():
        docs = c.get("doc_edits_unreviewed")
        if docs:
            lines.append(f"{cid}: edited after review and not re-reviewed (doc quick path): {', '.join(docs)}.")
    return lines


# --------------------------------------------------------------------------- small-fix one-reviewer round (CP3)
# After a checkpoint's adversarial gate has a clean, approved round, a small code fix made since that approval
# (since_approval.code_lines_changed, the same measurement classify_changes/`changes --json` reports, at or
# under config small_edit_lines) in a step that is not high risk opens its next review round with exactly one
# reviewer instead of the step's normal full set, told to look only at the file(s) changed since approval
# (review_rules' existing focus_files mechanism for round > 1 — unchanged). A fix over the limit, a code change
# of unknown size (binary), or any fix in a high-risk step still opens the normal full round; a doc-only edit is
# never downgraded here (docs_only stays on CP2's zero-reviewer quick path at `complete`, which runs before
# `reviewers` would ever be called for it). `cmd_reviewers` sets `small_fix` on the round it opens;
# `cmd_adv_record` records who did it on the checkpoint (`small_fix_review`) once that round is approved, so the
# commit message and `status` can both say the fix was reviewed as a small fix by one reviewer, naming it.
# The size is measured against the checkpoint's last FULL (non-small-fix) approval, not simply the gate's latest
# one, so several small fixes in a row still add up: `cmd_adv_record` only updates `last_full_review_fingerprint`
# on a full-round approval, never on a small-fix one, so the baseline stays put across a run of small fixes.

def _is_small_fix_round(ctx: "Ctx", cfg: dict, cp_id: str, cp: dict, cps: dict, g: dict) -> bool:
    if cp.get("risk", "normal") == "high":
        return False
    if cp.get("reviewers"):
        return False  # the checkpoint pins its own reviewer list; that override always gets a normal full round
    full_fp = cps.get("last_full_review_fingerprint")
    if not full_fp:
        return False  # no FULL-round approval recorded yet to measure a fix against (a user accept sets the
        # gate fingerprint but never last_full_review_fingerprint, so it does not qualify): a "stale" status,
        # set by `complete` once it detects the fix, does not disqualify it -- the approval itself still stands
    fp = fingerprint(ctx.root)
    files = sorted(changed_files(ctx.root, full_fp, fp))
    doc_files, code_files = _classify_doc_code(cfg, files)
    if not code_files:
        return False  # nothing but docs changed since the last full review: not this round's concern
    code_lines, code_unknown = _code_size(ctx, full_fp["id"], fp["id"], code_files)
    if code_unknown:
        return False
    return code_lines <= cfg.get("small_edit_lines", 20)


def _small_fix_reviewers(ctx: "Ctx", cfg: dict, cp: dict, exclude=None, share=None) -> list[dict] | None:
    """Resolve a small-fix round's reviewer the one way it is ever allowed to be resolved: review_depth["low"],
    accepted only when it comes back as exactly one both-lens reviewer. Used both when a small-fix round opens
    and when cmd_reviewers re-resolves an already-open small-fix round (CP3 round-04 fix: the re-resolution
    branch used to fall back to the step's own, possibly single-lens, risk instead of this). Returns None when
    low-risk resolution can't produce a single both-lens reviewer, so the caller falls back to a normal round.
    `share` is resolve_reviewers' provider-share view, so a small-fix round is picked and reserved like any other."""
    low_resolved = resolve_reviewers(ctx, cfg, dict(cp, risk="low"), exclude=exclude, share=share)
    if len(low_resolved) == 1 and (_roster_spec(cfg, low_resolved[0]["id"]) or {}).get("lens") == "both":
        return low_resolved
    return None


def _small_fix_review_line(cid: str, cps: dict) -> str | None:
    sf = cps.get("small_fix_review")
    if not sf:
        return None
    who = sf.get("reviewer") or "a reviewer"
    return f"{cid}: round {sf.get('round')} was reviewed as a small fix by one reviewer ({who})."


def _small_fix_review_lines(st: dict) -> list[str]:
    """One plain line per checkpoint whose last approved adversarial round was a one-reviewer small-fix review,
    naming that reviewer, for `status` and the commit message to say the same thing about the same round."""
    lines = []
    for cid, c in (st.get("checkpoints") or {}).items():
        line = _small_fix_review_line(cid, c)
        if line:
            lines.append(line)
    return lines


# ------------------------------------------------------------------- the fix round after a block (CP5, lane H)
# The second trigger on the one-reviewer round: once a review round has BLOCKED and the fixer has run (the code
# changed since the tree that round reviewed, and at least one of its blocking findings was triaged `fix`), the
# next round opens with exactly ONE reviewer, whatever the fix's size and whatever the step's risk. It is the
# same `small_fix` round lane B opens after an approval, told apart by `kind`: FIX_AFTER_BLOCK here,
# FIX_AFTER_APPROVAL for lane B's own small fix. Only the reviewer resolution differs: never review_depth["low"]
# (host-both would be the host checking another company's finding), but the reviewer whose blocking finding was
# fixed -- same provider, same lens -- chosen only among the blocked round's own reviewers, preferring a company
# other than the host's and then the lowest slot number. When that reviewer cannot run (benched, or at its share
# of review starts), its slot's own stand-in for the same lens takes the round through resolve_reviewers (lane
# G's logic, nothing re-implemented), so no provider that never reviewed the step is ever added.
FIX_AFTER_BLOCK = "after a block"
FIX_AFTER_APPROVAL = "after approval"


def _is_fix_after_block(rnd: dict | None) -> bool:
    return bool(rnd) and bool(rnd.get("small_fix")) and (rnd.get("kind") or "") == FIX_AFTER_BLOCK


def _round_blocking_findings(ctx, cp_id: str, round_no: int, cps: dict) -> list:
    """The findings that actually BLOCKED one recorded round and are still open: its own open-findings.json,
    which `adv-record` wrote as exactly what was left blocking after every one of the round's own rules ran
    (the severity bar for the step's risk, the later-round scope rule and `converge_after_round`, all applied by
    `split_findings` then), so a round that blocked only on minor findings -- an ordinary first round at normal
    or high risk, where every severity blocks -- counts here too, and a minor one the round itself deferred
    never does. No severity rule is re-applied here: re-deciding it would risk a different answer than the gate
    gave. The findings the user has accepted since are filtered out, the same way `_adv_open_findings` does for
    the latest round: state is the authoritative record of an acceptance, the file only its mirror."""
    accepted = {_finding_key(f) for f in _round_deferred(cps, round_no) if f.get("accepted")}
    return [f for f in _read_findings_file(_adv_round_dir(ctx, cp_id, round_no) / "open-findings.json")
            if _finding_key(f) not in accepted]


def _fix_round_pick(ctx, cfg, cp_id: str, cp: dict, cps: dict, g: dict, fp_id: str) -> dict | None:
    """{"round", "reviewer", "slot"} when this round follows a blocked round whose fix has been made, else None.

    The blocked round is the step's own last RECORDED round (`gates.adversarial.rounds`, which only a recorded
    round is ever added to): it blocked when it recorded findings, and the fixer has run when the tree is no
    longer the one that round reviewed. The reviewer is picked from that round's own reviewers, and only from
    those with a finding that blocked that round, whatever its severity (`_round_blocking_findings`), and that
    the orchestrator triaged `fix` (a rebutted finding, or one the user accepted, is not a fix to re-check),
    preferring a company other than the host's, then the lowest slot number. A
    checkpoint that pins its own `reviewers` list keeps that list, as it does for lane B's small fix."""
    if cp.get("reviewers"):
        return None
    last = (g.get("rounds") or [])[-1:]
    if not last:
        return None
    last = last[0]
    if not last.get("findings"):
        return None  # that round was approved, not blocked
    if last.get("fingerprint") == fp_id:
        return None  # the code is still the tree that round reviewed: the fixer has not run yet
    round_no = last.get("round")
    rows = last.get("reviewers") or []
    slots = {r.get("id"): r.get("slot") or i + 1 for i, r in enumerate(rows) if r.get("id")}
    triage = _read_triage(_adv_round_dir(ctx, cp_id, round_no))
    blocking = _round_blocking_findings(ctx, cp_id, round_no, cps)
    if (any(names_done_means(f) for f in blocking)
            and _dm_findings_block(ctx, ctx.state(), ctx.plan() or {})):
        return None  # done-means CP3: a still-open finding naming a line brings back every lens it narrows to
    fixing = {f.get("reviewer") for f in blocking
              if (triage.get(_finding_key(f)) or {}).get("decision") == "fix"}
    host = detect_host(cfg)

    def host_company(rid):  # 0 for another company (preferred), 1 for the host's own
        spec = _roster_spec(cfg, rid) or {}
        return 0 if spec.get("kind") == "command" and spec.get("vendor") and spec["vendor"] != host else 1
    cands = sorted((rid for rid in slots if rid in fixing), key=lambda rid: (host_company(rid), slots[rid]))
    if not cands:
        return None
    pick = {"round": round_no, "reviewer": cands[0], "slot": slots[cands[0]]}
    if pick["slot"] not in {r["slot"] for r in resolve_reviewers(ctx, cfg, cp)}:
        return None  # the step's review slots changed since that round: the normal full round applies
    return pick


def _fix_round_reviewers(ctx, cfg, cp: dict, pick: dict, share=None) -> list[dict]:
    """The one reviewer a post-block fix round opens with: the reviewer whose blocking finding was fixed when it
    can run now (resolved as a pinned one-slot list, so reviewer_availability and the provider share decide the
    same way they do for any other round), else that slot's own same-lens stand-in through resolve_reviewers'
    existing fallback for the slot, with the reviewer it stands in for and the reason named on the row."""
    rid, slot = pick["reviewer"], pick["slot"]
    own = resolve_reviewers(ctx, cfg, dict(cp, reviewers=[rid]), share=share)
    if len(own) == 1 and own[0]["id"] == rid:
        own[0]["slot"] = slot  # the slot it held in the blocked round, so a same-round refill replaces that slot
        return own
    return resolve_reviewers(ctx, cfg, cp, exclude={rid}, only_slots={slot}, share=share)


def _record_fix_round(cps: dict, rnd: dict, approved: bool) -> None:
    """Keep what each post-block fix round was and who reviewed it, so `status`, `status --json` and the commit
    message can all name the same round and the same reviewer, blocked or approved."""
    entry = {"round": rnd["round"], "reviewer": (rnd.get("reviewers") or [None])[0],
             "outcome": "approved" if approved else "blocked"}
    kept = [x for x in cps.get("fix_rounds") or [] if x.get("round") != entry["round"]]
    cps["fix_rounds"] = kept + [entry]


def _fix_round_lines_for(cid: str, cps: dict) -> list[str]:
    lines = []
    for e in cps.get("fix_rounds") or []:
        who = e.get("reviewer") or "a reviewer"
        tail = ("and approved it" if e.get("outcome") == "approved"
                else "and still found something to fix (it blocked again)")
        lines.append(f"{cid}: round {e.get('round')} was a fix round after a block: one reviewer, {who}, "
                     f"re-checked the fix {tail}.")
    return lines


def _fix_round_lines(st: dict) -> list[str]:
    """One plain line per post-block fix round of the run, naming its round, its one reviewer and how it ended."""
    lines = []
    for cid, c in (st.get("checkpoints") or {}).items():
        lines.extend(_fix_round_lines_for(cid, c))
    return lines


# --------------------------------------------------------------------------- docs-only step skips review (CP4)
# When a checkpoint's own change since its base_tree (never the plan's claim -- the same real diff
# `classify_changes` reports) is docs only, the step is not high risk, and doc_test_command is configured,
# opening the checkpoint's adversarial review never opens a reviewer round: it runs the test files naming
# those doc(s) instead (a failure names the test file and leaves the gate's status untouched) and, on success,
# marks the adversarial gate passed directly, recording the skip (`docs_only_review_skip`) so the commit
# message, `status` and the final review can all say which files were never reviewed and why. Reuses CP1's
# `_classify_doc_code`/`_tests_naming` and CP2's `_run_doc_test_command` so the doc/code rule and the
# doc-test-running logic never duplicate.

def _docs_only_review_skip(ctx: "Ctx", st: dict, cfg: dict, cp: dict, cps: dict, cp_id: str,
                           json_out: bool = False) -> bool:
    """True once this call has handled the adversarial gate for a docs-only step (the caller returns without
    opening a round); False when the normal full round still applies (code changed, high risk, a pinned
    reviewer list, the docs quick path is off, or, CP3, the step's latest RECORDED round still has an open
    finding that names a done-means line (`names_done_means`, while `_dm_findings_block` applies to this plan):
    a miss against what done means is fixed, re-reviewed or accepted by the user, never passed over because the
    diff that remains is docs only). That round is read from the gate's own `rounds` list, not from
    `cps['adv_round']`: `reviewers` replaces that pointer with a newer, unrecorded round the moment one opens
    (and again after a reviewer times out and it is re-run), and the earlier round's finding is still open
    until a later round records it fixed or the user accepts it."""
    if cp.get("risk", "normal") == "high" or not cfg.get("doc_test_command"):
        return False
    recorded = ((cps.get("gates") or {}).get("adversarial") or {}).get("rounds") or []
    last_no = recorded[-1].get("round") if recorded else None
    last_rec = {"round": last_no, "recorded": True} if last_no is not None else None
    if last_rec and _dm_findings_block(ctx, st, ctx.plan() or {}) \
            and any(names_done_means(f) for f in _adv_open_findings(ctx, cp_id, last_rec, cps)):
        return False
    if cp.get("reviewers"):
        return False  # the checkpoint pins its own reviewer list; that override always gets a normal full
        # round, same as _is_small_fix_round
    base = cps.get("base_tree")
    if not base:
        return False
    fp = fingerprint(ctx.root)
    files = sorted(changed_files(ctx.root, {"kind": "git-tree", "id": base}, fp))
    if not files:
        return False
    doc_files, code_files = _classify_doc_code(cfg, files)
    if code_files or not doc_files:
        return False
    doc_test_files = _tests_naming(ctx, cfg, fp, doc_files)
    if doc_test_files:
        dcode, dout = _run_doc_test_command(ctx, cfg, doc_test_files, ctx.evidence(cp_id) / "docs-only-review.log")
        if dcode != 0:
            die(f"{cp_id}: docs-only review check failed for {', '.join(doc_test_files)}:\n{_tail(dout)}", 2)
        if fingerprint(ctx.root)["id"] != fp["id"]:
            die("The doc test command changed files in the project. Those changes were never reviewed — find "
                "out what wrote them (generated files? snapshots?) and either add them to .gitignore or "
                "re-run the gates.", 2)
    cps["gates"]["adversarial"].update(status="passed", fingerprint=fp, passed_at=now())
    cps["docs_only_review_skip"] = {"files": doc_files, "doc_test_files": doc_test_files}
    cps["step"] = _earliest_open_step(cps)
    ctx.log(st, "adversarial_docs_only_skip", cp=cp_id, files=",".join(doc_files))
    ctx.save_state(st)
    build_viewer(ctx)
    if json_out:
        print(json.dumps({"checkpoint": cp_id, "docs_only_skip": {"files": doc_files,
                                                                    "doc_test_files": doc_test_files}}, indent=2))
    else:
        print(f"{cp_id}: review skipped -- this step's change is docs only ({', '.join(doc_files)}); not reviewed. "
              f"Doc test(s) run instead: {', '.join(doc_test_files) or '(no test file names these docs)'}")
    return True


def _docs_only_quick_path_off_note(ctx: "Ctx", cfg: dict, cp: dict, cps: dict) -> str | None:
    """A plain note for `reviewers`' text output when this checkpoint's diff since base_tree is docs only but
    doc_test_command is not configured, so the docs quick path is off and the normal full round still applies
    -- visibility for why no skip happened, mirroring `changes`'s own doc_quick_path report."""
    if cfg.get("doc_test_command") or cp.get("risk", "normal") == "high":
        return None
    base = cps.get("base_tree")
    if not base:
        return None
    fp = fingerprint(ctx.root)
    files = sorted(changed_files(ctx.root, {"kind": "git-tree", "id": base}, fp))
    if not files:
        return None
    doc_files, code_files = _classify_doc_code(cfg, files)
    if code_files or not doc_files:
        return None
    return (f"Docs quick path is off (doc_test_command is not configured): the changed file(s) "
            f"({', '.join(doc_files)}) would otherwise skip review, so this round is the normal full review.")


def _docs_only_skip_line(cid: str, cps: dict) -> str | None:
    skip = cps.get("docs_only_review_skip")
    if not skip:
        return None
    return (f"{cid}: review skipped because the step changed only docs ({', '.join(skip.get('files') or [])}); "
            "not reviewed.")


def _docs_only_skip_lines(st: dict) -> list[str]:
    """One plain line per checkpoint whose adversarial review was skipped as docs only (CP4), naming the
    file(s) never reviewed, for `status`, the commit message and the final review to all say the same thing."""
    lines = []
    for cid, c in (st.get("checkpoints") or {}).items():
        line = _docs_only_skip_line(cid, c)
        if line:
            lines.append(line)
    return lines


# ----------------------------------------------------------- a full review clears skipped-review notes (CP5)
# A record that a step's review was skipped or lightened (CP2's doc_edits_unreviewed, CP3's small_fix_review,
# CP4's docs_only_review_skip) says less review happened than the step's history actually shows once a later
# FULL round (every reviewer the step's own risk names) is recorded approved. `cmd_adv_record` calls this once,
# on that full-round-approval branch only, next to where it sets `last_full_review_fingerprint` -- a small-fix
# approval or a docs-only skip never clears any of these (they are not a full round), and a round that is not
# approved is never reached here at all.

def _clear_lighter_review_records(cps: dict) -> None:
    cps.pop("docs_only_review_skip", None)
    cps.pop("doc_edits_unreviewed", None)
    cps.pop("small_fix_review", None)


# --------------------------------------------------------------------------- tamper evidence
# ratchet.py records a hash of every file it owns after each write, in RATCHET_HOME (outside the repo and off-limits
# to agents). A write by any other route — a helper script, an editor, a "quick fix" — is detected on the next read.

def _chain_path() -> Path:
    return ratchet_home() / "file-hashes.json"


_ABSENT = object()  # pass as _read_record's `missing` to tell a file that is not there from an empty one
_FRESH = object()  # _read_record's default for `missing`: a new empty record ({}, or [] for lines)


def _read_record(path: Path, kind=dict, missing=_FRESH, lines: bool = False, tail: int | None = None, data=None):
    """The one reader of Ratchet's records (every file under .ratchet/ and in RATCHET_HOME that the hooks or the
    engine read for state, approvals, crashes, notes, hashes, director folders, stop errors or active runs).
    Returns (data, None), or (None, why) when the file can't be read, is not valid JSON, or is not a `kind` (a JSON
    object by default; None accepts any JSON value). A file that does not exist yet returns (`missing`, None): a new
    empty record unless the caller passes its own marker. With `lines`, a JSON-lines file: (the JSON objects on its
    lines, None), skipping lines that are not one; `tail` reads only its last `tail` bytes.
    It never exits or raises, so no hook or command can crash on a damaged record: each caller fails safe on its own
    terms (a damaged record that grants trust grants nothing), and says so with _note_unreadable.
    With `data` (bytes): parse those bytes instead of reading `path` (for a file's content taken from git)."""
    try:
        if data is not None:
            raw = data
        elif tail is None:
            raw = path.read_bytes()
        else:
            with open(path, "rb") as f:
                f.seek(max(0, os.fstat(f.fileno()).st_size - tail))
                raw = f.read()
    except FileNotFoundError:
        return (([] if lines else {}) if missing is _FRESH else missing), None
    except OSError as e:  # a folder or a link loop where the file goes, no permission, a parent that is a file
        return None, f"{type(e).__name__}: {e}"
    except Exception as e:  # never raise, whatever the file system does
        return None, f"{type(e).__name__}: {e}"
    if lines:
        out = []
        for line in raw.decode("utf-8", "replace").splitlines():
            try:
                e = json.loads(line)
            except ValueError:
                continue
            if isinstance(e, dict):
                out.append(e)
        return out, None
    try:
        data = json.loads(raw.decode("utf-8-sig"))  # a leading byte-order mark is not damage
    except ValueError as e:  # invalid JSON, or bytes that are not UTF-8
        return None, f"{type(e).__name__}: {e}"
    except RecursionError:
        return None, "RecursionError: nested too deeply"
    if kind is not None and not isinstance(data, kind):
        return None, "not a JSON object" if kind is dict else f"not a JSON {getattr(kind, '__name__', kind)}"
    return data, None


def _write_record(path: Path, data, pretty: bool = False, raw: bool = False):
    """The one writer of Ratchet's records: replace the file in one rename, through a temp file of this process's
    own (pid plus a random token), flushed to disk first, so two writers never share a temp file, a reader never
    sees half a write, and a crash never leaves a half-written record. The temp file is removed on failure.
    Raises OSError when it can't write; every caller handles that on its own terms.
    raw=True: `data` is already the text to write, not a JSON value to encode (for a non-JSON generated
    artifact such as ci-export's workflow file); `pretty` is ignored in that case. When `data` is `bytes`
    (raw=True only), the temp file is opened in binary mode and those exact bytes are written, with no
    newline translation or re-encoding, so a caller that already computed its own encoded bytes (so a
    comparison, a write and a printed preview can never disagree) gets exactly those bytes on disk."""
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(f"{path.name}.{os.getpid()}-{secrets.token_hex(4)}.tmp")
    text = data if raw else ((json.dumps(data, indent=2, ensure_ascii=False) + "\n") if pretty else json.dumps(data))
    try:
        if raw and isinstance(text, bytes):
            with open(tmp, "wb") as f:
                f.write(text)
                f.flush()
                os.fsync(f.fileno())
        else:
            # backslashreplace: a lone surrogate (from a reviewer's reply) is written as its own JSON escape,
            # "\ud83d", which reads back as the same string; every other character encodes as UTF-8 unchanged
            with open(tmp, "w", encoding="utf-8", errors="backslashreplace") as f:
                f.write(text)
                f.flush()
                os.fsync(f.fileno())
        os.replace(tmp, path)
    finally:
        try:
            tmp.unlink()
        except OSError:
            pass


def _append_record(path: Path, text: str):
    """The one appender for Ratchet's append-only records (human_log.jsonl, the run's .jsonl records, hook-errors.log,
    hook-crashes-unsaved.log): whole lines, added at the end, never rewriting what is there. Raises OSError."""
    with open(path, "a", encoding="utf-8") as f:
        f.write(text)


_NOTED_UNREADABLE = set()


def _note_unreadable(path: Path, why: str, outcome: str):
    """Say plainly, on stderr, that a damaged record was set aside and what Ratchet did instead (once per file and
    cause in a process)."""
    try:
        key = (str(path), why, outcome)
        if key in _NOTED_UNREADABLE:
            return
        _NOTED_UNREADABLE.add(key)
        print(f"ratchet: {path} could not be read ({why}); {outcome}", file=sys.stderr)
    except Exception:
        pass


class _BreakerLock:
    """The lock protocol both of Ratchet's lock files share (_ChainLock and its per-user siblings, and _StateLock), so
    they behave the same and a fix is made once. The lock file is created with O_CREAT|O_EXCL and holds this
    process's own token. It is only ever removed (a stale one, or the holder releasing its own) while holding a second
    O_CREAT|O_EXCL file, `<lock>.break`, and judged again under it, so two processes clearing one stale lock can't
    remove each other's fresh lock, and a release never removes another process's lock. Only a regular file is ever
    judged stale or removed (a folder or a link in its place is left alone). A breaker file older than BREAKER_STALE
    seconds was left by a process that died while holding it (it is held for a few system calls) and is removed, so
    a crash there can't disable the lock for good; only the very file judged stale is removed (_remove_stale_breaker),
    and a holder checks that its breaker is still in place before it removes anything under it (_holds_breaker), so
    two waiters behind one stale breaker can't both hold it. Subclasses say how old a lock must be to be stale (_stale_after)
    and how long to pause between tries (_pause)."""

    BREAKER_STALE = 30

    def __init__(self, path: Path, token: str):
        self.path = path
        self.token = token
        self.held = False
        self._breaker_id = None  # (device, inode) of the breaker file this process created, while it holds it

    @property
    def breaker(self) -> Path:
        return self.path.with_name(self.path.name + ".break")

    def _stale_after(self) -> float:
        raise NotImplementedError

    def _pause(self):
        time.sleep(0.005)

    def _create(self, path: Path):
        fd = os.open(str(path), os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.write(self.token)

    def _is_stale(self, st) -> bool:
        """Whether a lock file with this lstat() result was left by a command that stopped: a regular file older
        than _stale_after() seconds, or one whose owner is provably gone (_owner_gone)."""
        return stat.S_ISREG(st.st_mode) and (time.time() - st.st_mtime > self._stale_after() or self._owner_gone())

    def _owner_gone(self) -> bool:
        """Whether the process that made the lock file is provably gone. False unless a subclass can tell."""
        return False

    def _take_breaker(self, wait: float) -> bool:
        """True once this process holds the breaker file; False when another process holds it for longer than
        `wait`. Raises OSError when it can't be created at all (the caller decides what that means)."""
        deadline = time.monotonic() + wait
        while True:
            try:
                self._create(self.breaker)
                try:  # the file this process created: what _holds_breaker checks later
                    st = os.lstat(self.breaker)
                except OSError:  # moved away at once by a waiter clearing a stale breaker: try again
                    continue
                self._breaker_id = (st.st_dev, st.st_ino)
                return True
            except FileExistsError:
                try:  # held for a few system calls: one this old was left by a process that died holding it
                    st = os.lstat(self.breaker)
                    if stat.S_ISREG(st.st_mode) and time.time() - st.st_mtime > self.BREAKER_STALE:
                        self._remove_stale_breaker(st)
                        continue
                except OSError:
                    pass
            if time.monotonic() >= deadline:
                return False
            self._pause()

    def _remove_stale_breaker(self, st):
        """Remove the breaker file judged stale (its lstat() result is `st`), and only that file. Another waiter may
        have removed it and taken a fresh breaker since it was judged, so it is never unlinked by path: it is first
        renamed to a name of this process's own, and only removed when the renamed file is the one judged (same
        device, inode and modification time). Otherwise it is a fresh breaker another process holds, and it is put
        back at once (a hard link that never replaces a newer breaker). Raises OSError when the rename fails (the
        file is gone already: the caller tries to create the breaker again)."""
        mine = self.breaker.with_name(f"{self.breaker.name}.{os.getpid()}-{secrets.token_hex(4)}.stale")
        os.rename(self.breaker, mine)
        try:
            got = os.lstat(mine)
            if (got.st_dev, got.st_ino, got.st_mtime_ns) != (st.st_dev, st.st_ino, st.st_mtime_ns):
                try:  # a live breaker taken by mistake: give it back
                    os.link(mine, self.breaker)
                except OSError:
                    pass
        finally:
            try:
                os.unlink(mine)
            except OSError:
                pass

    def _holds_breaker(self) -> bool:
        """Whether the breaker file in place is still the one this process created (a waiter clearing a stale
        breaker may have moved it away for a moment). Checked right before removing anything under it."""
        try:
            st = os.lstat(self.breaker)
        except OSError:
            return False
        return self._breaker_id is not None and (st.st_dev, st.st_ino) == self._breaker_id

    def _drop_breaker(self):
        try:
            if self._holds_breaker():  # never another process's breaker
                os.unlink(self.breaker)
        except OSError:
            pass
        self._breaker_id = None

    def _clear_stale(self) -> bool:
        """Remove the lock file if it is still stale when judged again while holding the breaker file. True when
        the lock file is gone now (removed, or already released), so the caller can try to take it at once; False
        when another process holds the breaker or the lock is live. Raises OSError for a file-system error."""
        if not self._take_breaker(0):
            return False  # another process is clearing or releasing the lock right now: try again shortly
        try:
            if not self._holds_breaker():
                return False  # moved away by a waiter clearing a stale breaker: judge again later
            if self._is_stale(os.lstat(self.path)):
                os.unlink(self.path)
                return True
            return False  # a newer, live lock (or not a lock file): wait for it
        except FileNotFoundError:
            return True
        finally:
            self._drop_breaker()

    def _release_own(self, wait: float):
        """Remove the lock file if it still holds this process's token, under the breaker file. When the breaker
        can't be had within `wait` seconds the lock is left in place (it goes stale and is cleared later): a lock
        that might not be ours is never removed."""
        try:
            if not self._take_breaker(wait):
                return
        except OSError:
            return
        try:
            if self._holds_breaker() and self.path.read_text(encoding="utf-8") == self.token:
                os.unlink(self.path)
        except OSError:
            pass
        finally:
            self._drop_breaker()


class _ChainLock(_BreakerLock):
    """A short lock (milliseconds) around the hash record: its read-modify-write, an append to a recorded file
    together with its new hash, and a check of a file against its hash. The prompt hook appends to human_log.jsonl
    without the state lock (it never waits on a long command), so a reader must never see that file between the
    append and its new hash, and two writers must never drop each other's hash. Best effort: when it can't be had
    within a few seconds (an unwritable per-user folder, say) the caller goes on without it, as before.
    The breaker protocol is _BreakerLock's; a lock older than STALE seconds was left by a process that died."""

    STALE = 30

    def __init__(self, wait: float = 5.0):
        super().__init__(ratchet_home() / "file-hashes.lock", f"{os.getpid()} {secrets.token_hex(8)}")
        self.wait = wait

    def _stale_after(self) -> float:
        return self.STALE

    def __enter__(self):
        deadline = time.monotonic() + self.wait
        while True:
            try:  # no per-user folder yet: there is no hash record to protect
                self._create(self.path)
                self.held = True
                return self
            except FileExistsError:
                try:  # held for milliseconds: one older than half a minute was left by a process that died
                    if self._is_stale(os.lstat(self.path)) and self._clear_stale():
                        continue
                except OSError:
                    pass
            except OSError:
                return self
            if time.monotonic() >= deadline:
                return self
            time.sleep(0.01)

    def __exit__(self, *exc):
        if self.held:
            self.held = False
            self._release_own(1.0)  # can't be had: leave the lock; it goes stale and is cleared later
        return False


def _record_lock_path(record: Path) -> Path:
    """The lock file a shared record is protected by: named after the record, next to it (`active-runs.lock` for
    active-runs.json, `enrolled.lock`, `hook-heartbeat.lock`, ...). The one place that name is built, so _RecordLock
    and every busy message that names the lock stay in step."""
    return record.with_name(record.stem + ".lock")


class _RecordLock(_ChainLock):
    """The short lock update_record holds by default around one shared record's read-modify-write: a lock file named
    after the record, next to it (`active-runs.lock` for active-runs.json, `enrolled.lock`, `hook-heartbeat.lock`,
    ...). Built like file-hashes.lock: the breaker protocol is _BreakerLock's, it is held for milliseconds, and one
    older than STALE seconds was left by a process that died and is cleared."""

    def __init__(self, record: Path, wait: float = 5.0):
        super().__init__(wait)
        self.path = _record_lock_path(record)


KEEP = object()  # update_record: `fn` or `damaged` returns it to leave the record exactly as it is


def update_record(path: Path, fn, lock=None, damaged=None, pretty: bool = False, need_lock: bool = True,
                  wait: float = 5.0) -> str:
    """The one read-modify-write of a shared record: a file more than one process can update at once (every record in
    RATCHET_HOME, and in .ratchet/ the ones hooks or commands outside the state lock rewrite). Two unlocked writers
    would each read the file, add their own entry and write the whole file back, and the later write would silently
    drop the other's entry. So this holds a _BreakerLock-based lock for that file from the read to the write: it reads
    with _read_record, applies `fn(data)` and writes the result with _write_record. The lock is a _RecordLock next to
    the record, taken here, unless the caller passes `lock`: one it has already entered (its own lock file for this
    record, or a wider step under the same lock), used as it is. The default lock is waited for at most `wait`
    seconds.
    `fn(data)` returns the new data, or KEEP to leave the file as it is.
    `damaged` is the file's own rule for a record that can't be read: a sentence (it reads as empty through read_json,
    which says so on stderr with that sentence, and is replaced), or a function of the reason returning the data to
    start from (the file is then replaced) or KEEP. Default: it is left as it is, and stderr says so.
    Returns "written", "kept" (fn kept it), "damaged" (left as it is) or "busy" (the lock could not be had in time:
    nothing was read or written, unless need_lock is False, when it goes on without it, best effort as before).
    Raises OSError when the folder or the write fails; every caller handles that on its own terms."""
    with contextlib.ExitStack() as stack:
        if lock is None:
            path.parent.mkdir(parents=True, exist_ok=True)  # the lock file goes in this folder
        lk = lock if lock is not None else stack.enter_context(_RecordLock(path, wait))
        if not lk.held and need_lock:
            return "busy"
        if isinstance(damaged, str):
            data = read_json(path, {}, record=damaged)
        else:
            data, why = _read_record(path)
            if why is not None:
                if damaged is None:
                    _note_unreadable(path, why, "Ratchet left it as it is and did not write over it")
                    return "damaged"
                data = damaged(why)
                if data is KEEP:
                    return "damaged"
        new = fn(data)
        if new is KEEP:
            return "kept"
        _write_record(path, new, pretty=pretty)
        return "written"


_CHAIN_REBUILD = False  # set by accept-state (a person confirmed at their terminal): an unreadable record is rebuilt


def _chain_record():
    """(the hash record, None), or (None, why) when it can't be read or is not a JSON object."""
    return _read_record(_chain_path())


def _record_chain_now(p: Path, lock: _ChainLock):
    """Record p's hash, under `lock` (the caller's _ChainLock, already entered; best effort as ever: when it could
    not be had, the hash is still recorded). An unreadable hash record is never replaced here (a fresh record would
    drop every other file's hash, and a file with no recorded hash is trusted): it is left as it is, so every check
    against it keeps refusing, until accept-state, run by a person at their own terminal, rebuilds it. Never exits."""
    cp = _chain_path()

    def damaged(why):
        if not _CHAIN_REBUILD:
            _note_unreadable(cp, why, "the new hash was not recorded and the file was left as it is; every check "
                             "against it refuses until the user runs accept-state")
            return KEEP
        _note_unreadable(cp, why, "accept-state replaces it with a new record")
        return {}

    def add(data):
        raw = p.read_bytes()
        key = str(p.resolve())
        data[key] = hashlib.sha256(raw).hexdigest()
        return data
    try:
        _ = update_record(cp, add, lock=lock, damaged=damaged, need_lock=False)  # need_lock=False: never "busy"
    except OSError:
        pass


def record_chain(p: Path):
    with _ChainLock() as lock:
        _record_chain_now(p, lock)


def append_recorded(p: Path, line: str):
    """Append one line to a file Ratchet keeps a hash of and record its new hash, as one step for every reader."""
    with _ChainLock() as lock:
        _append_record(p, line)
        _record_chain_now(p, lock)


ACCEPT_STATE_CMD = "`RATCHET_HUMAN_OVERRIDE=1 ratchet.py accept-state`"


def chain_problem(p: Path, label: str) -> str | None:
    """Why `p` can't be trusted against Ratchet's record of file hashes (None when it can). Never exits, so a hook can
    use it: a damaged record vouches for nothing (it is a problem, never permission), and so does a file that can't
    be read."""
    try:
        with _ChainLock():
            record, why = _chain_record()
            known = (record or {}).get(str(p.resolve()))
            same = why is None and (not known or not p.exists()
                                    or hashlib.sha256(p.read_bytes()).hexdigest() == known)
    except OSError as e:
        return (f"{label} ({p}) can't be read ({type(e).__name__}: {e.strerror or e}), so Ratchet can't confirm it "
                "was not changed outside ratchet.py, and won't trust it. Tell the user; check that it is a file "
                "Ratchet can read.")
    if why is not None:  # a damaged record vouches for nothing: refuse rather than trust the file
        return (f"Ratchet's record of file hashes ({_chain_path()}) can't be read ({why}), so it can't confirm that "
                f"{label} ({p}) was not changed outside ratchet.py, and won't trust it. Tell the user; only if they "
                f"are sure the file is right, they can rebuild the record from their own terminal with "
                f"{ACCEPT_STATE_CMD} (it asks them to type back a short code).")
    if not same:
        return (f"{label} was changed outside ratchet.py ({p}). Ratchet won't trust it. Tell the user; restore the "
                "file, or, only if they are sure, they can accept it from their own terminal with "
                f"{ACCEPT_STATE_CMD} (it asks them to type back a short code).")
    return None


def verify_chain(p: Path, label: str):
    if not _IN_HOOK:  # the record of hashes lives in the per-user folder: only trust the one the hooks use
        for cand in p.resolve().parents:
            if cand.name == RATCHET_DIR:
                require_hook_env(cand.parent)
                break
    why = chain_problem(p, label)
    if why:
        die(why)


# ---- the human override: a person at their own terminal ------------------------------------------------------
# RATCHET_HUMAN_OVERRIDE=1 alone proves nothing: any agent can set an environment variable. So the override also
# opens the real terminal (/dev/tty; CONIN$/CONOUT$ on Windows), prints a short random code there and reads it back
# in the same process. A command with no terminal (an agent's shell tool runs on pipes) or a wrong or missing
# answer is refused. This is best-effort: an agent that can start its own pseudo-terminal and read the code from it
# can still answer; the PreToolUse guard refuses commands that set the variable, which covers the usual route.

_OVERRIDE_CONFIRMED = False
OVERRIDE_TIMEOUT = 300  # seconds a person has to type the code back
NO_TERMINAL_MSG = ("RATCHET_HUMAN_OVERRIDE is for a person at their own terminal, and this command has no terminal "
                   "attached (an agent's shell tool runs without one), so nothing was approved. If you are the "
                   "person, run the command yourself in a terminal window and type back the code it shows.")


def _read_line_with_timeout(readline, timeout):
    """One line from a blocking `readline` (the Windows console has no select()), or None when nothing arrives
    within `timeout` seconds, at end of input, or when the read fails. The reader thread is a daemon: a refusal
    exits the process even while it still waits on the console."""
    import threading
    box = []

    def run():
        try:
            box.append(readline())
        except Exception:
            box.append(None)
    t = threading.Thread(target=run, daemon=True)
    t.start()
    t.join(timeout)
    if t.is_alive() or not box:
        return None
    return box[0] or None


def _open_terminal():
    """(read, write) callables bound to the real terminal, or None when there is none."""
    if os.name == "nt":
        try:
            fin = open("CONIN$", "r", encoding="utf-8", errors="replace")
            fout = open("CONOUT$", "w", encoding="utf-8", errors="replace")
        except OSError:
            return None

        def w(s):
            fout.write(s)
            fout.flush()
        return (lambda: _read_line_with_timeout(fin.readline, OVERRIDE_TIMEOUT)), w
    try:
        fd = os.open("/dev/tty", os.O_RDWR | getattr(os, "O_NOCTTY", 0))
    except OSError:
        return None
    if not os.isatty(fd):
        os.close(fd)
        return None

    def r():
        import select
        import time
        buf, deadline = b"", time.time() + OVERRIDE_TIMEOUT
        while b"\n" not in buf and b"\r" not in buf:
            left = deadline - time.time()
            if left <= 0:
                return None
            try:
                ready, _, _ = select.select([fd], [], [], left)
                if not ready:
                    return None
                chunk = os.read(fd, 256)
            except OSError:
                return None  # the terminal went away
            if not chunk:
                return None  # end of input before an answer
            buf += chunk
        return buf.decode("utf-8", "replace")

    def w(s):
        os.write(fd, s.encode("utf-8", "replace"))
    return r, w


def human_override(purpose: str, ctx=None, action: str | None = None) -> bool:
    """False when RATCHET_HUMAN_OVERRIDE is not set. When it is set, the person must type back a printed code at a
    real terminal in this same process; anything else dies with a plain message (never falls back to the bare
    variable). Asked at most once per process.
    The audit line is part of the override itself: before it returns True, it appends `action` to human_log.jsonl
    (log_override) and dies when that line can't be written. Callers check it BEFORE they change anything, so no
    caller can use a confirmed override without its audit line, and a refusal leaves everything unchanged. A caller
    that passes no ctx/action is refused too (fail closed), never approved unaudited."""
    global _OVERRIDE_CONFIRMED
    if os.environ.get("RATCHET_HUMAN_OVERRIDE") != "1":
        return False
    if not _OVERRIDE_CONFIRMED:
        _confirm_override(purpose)
    if ctx is None or not action:
        die("The override was confirmed, but this command did not say what to record in the audit log, so nothing "
            "was approved or changed: an override is only used when it is recorded.")
    log_override(ctx, action)
    return True


def _confirm_override(purpose: str):
    """Ask for the printed code at the real terminal; dies unless it is typed back correctly."""
    global _OVERRIDE_CONFIRMED
    term = _open_terminal()
    if term is None:
        die(NO_TERMINAL_MSG)
    read, write = term
    code = f"{secrets.randbelow(10 ** 6):06d}"
    try:
        write(f"RATCHET: RATCHET_HUMAN_OVERRIDE is set, to {purpose}.\n"
              f"To confirm you are a person at this terminal, type this code and press Enter: {code}\n> ")
        answer = read()
    except OSError:
        answer = None
    if answer is None:
        die("No code was typed back at the terminal, so nothing was approved. RATCHET_HUMAN_OVERRIDE only works "
            "when a person types back the code Ratchet shows.")
    if not hmac.compare_digest(answer.strip().encode(), code.encode()):
        die("The code typed back does not match the one shown, so nothing was approved. Run the command again "
            "and type the new code it shows.")
    _OVERRIDE_CONFIRMED = True


def log_override(ctx, action: str):
    """Leave an audit line in human_log.jsonl. It is not a chat message, so it never answers a question.
    Only human_override calls this (the audit is part of the override), and every caller of human_override checks
    it BEFORE it changes anything, so an override that can't be recorded is refused (die) and
    nothing is approved, accepted or replaced: a confirmed override is never used without its audit line."""
    log = ctx.ratchet / "human_log.jsonl"
    try:
        append_recorded(log, json.dumps({"at": now(), "by": "human", "override": True, "action": action,
                                         "via": "RATCHET_HUMAN_OVERRIDE, code typed back at the terminal"}) + "\n")
    except OSError as e:
        die(f"The override was confirmed, but Ratchet could not write its audit line to {log} "
            f"({type(e).__name__}: {e.strerror or e}), so nothing was approved or changed: an override is only used "
            "when it is recorded. Make that file (and .ratchet/) writable, then run the command again.")


ACCEPT_STATE_PURPOSE = "accept the current state.json and human_log.jsonl as the new baseline"


def _refuse_damaged_baseline(ctx):
    """accept-state's refusal of a damaged state.json (it can't be a baseline): says how to get out and changes
    nothing. Read-only, so main runs it before it asks the person for the code."""
    sp = ctx.state_path()
    _st, why = _read_record(sp, missing=None)
    if why is not None:
        die(f"The run's state.json ({sp}) can't be read ({why}), so it can't be accepted as the new baseline, and "
            "nothing was changed. Restore it (from a backup or your git history) and run accept-state again; or, to "
            "start the feature over, run `RATCHET_HUMAN_OVERRIDE=1 ratchet.py init --force \"<feature>\"` yourself "
            "in a terminal window.")


def cmd_accept_state(args):
    if os.environ.get("RATCHET_HUMAN_OVERRIDE") != "1":
        die("accept-state is for a person at their own terminal: run `RATCHET_HUMAN_OVERRIDE=1 ratchet.py "
            "accept-state` yourself in a terminal window and type back the code it shows.")
    ctx = Ctx(find_root())
    sp = ctx.state_path()
    _refuse_damaged_baseline(ctx)  # main already checked, before asking for the code; checked again under the lock
    purpose = ACCEPT_STATE_PURPOSE
    if not _OVERRIDE_CONFIRMED:  # main confirms first; this keeps any other caller from going on unconfirmed
        _confirm_override(purpose)  # dies unless the person types the code back
    global _CHAIN_REBUILD
    _CHAIN_REBUILD = True  # the person confirmed: an unreadable hash record is rebuilt from these files, starting
    # with the audit line's own write below (so it never says the record waits for the accept-state running now)
    human_override(purpose, ctx, "accept-state")
    _act, act_why = _read_record(ctx.ratchet / "active.json")
    if act_why is not None and ctx.active_slug():  # named again from the per-user marker (Ctx.active_slug)
        try:
            _write_record(ctx.ratchet / "active.json", {"slug": ctx.active_slug()}, pretty=True)
            print(f"RATCHET: {ctx.ratchet / 'active.json'} was damaged; it names run '{ctx.active_slug()}' again.")
        except OSError:
            pass
    for p in (sp, ctx.ratchet / "human_log.jsonl"):
        if p.exists():
            record_chain(p)
    ok("Current state.json and human_log.jsonl accepted as the new baseline.")


# --------------------------------------------------------------------------- run bookkeeping

def _set_blocked(st, reason):
    """Block the run and remember where it was, so an unblock returns to the same place."""
    if st.get("phase") != "blocked":
        st["blocked_from"] = st.get("phase")
    st["phase"] = "blocked"
    st["blocked_reason"] = reason
    st["awaiting_since"] = now()


def ratchet_home() -> Path:
    """Per-user Ratchet data OUTSIDE any repository (director key, active-run markers)."""
    return Path(os.environ.get("RATCHET_HOME") or Path.home() / ".config" / "ratchet")


# ---- the per-user folder the hooks use ------------------------------------------------------------------------
# A hook runs with the agent CLI's own environment, not the environment of a shell the agent controls. So every hook
# records which per-user folder (RATCHET_HOME) and director key file it sees, in .ratchet/hook-env.json (written by
# ratchet.py only; the guard refuses agent writes there). Any other ratchet.py command then refuses to run when its
# own RATCHET_HOME or RATCHET_DIRECTOR_KEY_FILE points somewhere else: a folder an agent made up would hold no
# integrity record and could hold a director key of its own making. The guard also records the role of the session
# that last ran a command here (see "who counts as the director").

_IN_HOOK = False  # set while a hook runs: its own environment is the one that counts


def _hook_env_path(root: Path) -> Path:
    return root / RATCHET_DIR / "hook-env.json"


def _same_path(a, b) -> bool:
    return os.path.normcase(os.path.realpath(str(a))) == os.path.normcase(os.path.realpath(str(b)))


def _current_hook_env() -> dict:
    return {"home": os.path.realpath(str(ratchet_home())), "key_file": os.path.realpath(str(director_key_path()))}


def _hook_role() -> str:
    """The role of the agent CLI a hook runs for, from the hook's own (launch-time) environment."""
    return "director" if os.environ.get("RATCHET_ROLE") == "director" else "builder"


HOOK_ENV_RECORDS = "hook-env"  # a folder of per-run hook records; hook-env.json is their combined view
_HOOK_ENV_REC_RE = re.compile(r"^hook-env\.json\.(guard|env)\.(\d+)\.(director|builder|-)\.[A-Za-z0-9_-]+$")
_HOOK_ENV_CORE = ("home", "key_file", "guard_role")
_HOOK_ENV_TIE_RANK = {"director": 0, "-": 1, "builder": 2}  # same start time: the higher rank is the newer record


def _hook_env_records(root: Path):
    """[(microseconds, kind, role, name, path)] for every per-run hook record in .ratchet/hook-env/, oldest first
    ([] when there is none; None when the folder can't be listed). The start time of the hook run and, for a guard,
    the session role live in the name, so the role is read without opening a file another hook may be deleting."""
    folder = root / RATCHET_DIR / HOOK_ENV_RECORDS
    try:
        names = os.listdir(folder)
    except FileNotFoundError:
        return []
    except OSError:
        return None
    out = []
    for name in names:
        m = _HOOK_ENV_REC_RE.match(name)
        if m:
            out.append((int(m.group(2)), m.group(1), m.group(3), name, folder / name))
    # Same start microsecond: the less privileged role counts as the newer one, so on an exact tie between a director
    # and a builder guard the builder wins (never a random pick by the name's token, which would favour the director
    # half the time). Only then the name, so the order is always the same.
    return sorted(out, key=lambda r: (r[0], _HOOK_ENV_TIE_RANK.get(r[2], 1), r[3]))


def _combined_hook_env(recs) -> dict | None:
    """hook-env.json as the records say: `home` and `key_file` from the newest record, `guard_role` from the newest
    guard record (newest by when each hook run started). None when a listed record vanished while it was read (a
    newer hook removed it): the caller lists again."""
    view = None
    for _us, _kind, _role, _name, path in reversed(recs):
        data, why = _read_record(path, missing=_ABSENT)
        if data is _ABSENT:
            return None
        if why is not None:
            continue  # not a record Ratchet wrote (records are renamed into place whole): skip it
        if data.get("home") and data.get("key_file"):
            view = {"home": data["home"], "key_file": data["key_file"], "at": data.get("at"), "host": data.get("host")}
            break
    if view is None:
        return None
    guards = [r for r in recs if r[1] == "guard"]
    if guards:
        view["guard_role"] = guards[-1][2]
    return view


def record_hook_env(root: Path, host: str, event: str = "", started: str | None = None) -> bool:
    """Called by every hook: remember the per-user folder and key file this agent CLI uses, and (guard only: it runs
    right before every command a session runs) the role of the session that last ran a command here.
    No file is read, changed and written back, so concurrent hooks cannot drop each other's newer values (the same
    design as the crash markers): each run only creates its own uniquely named record in .ratchet/hook-env/ (the
    run's start time and, for a guard, its role in the name; renamed into place whole), removes the records its own
    supersedes, and then makes hook-env.json (rewritten in one rename, so a reader never sees half a file) agree
    with the records: the newest record gives `home` and `key_file`, the newest guard record gives `guard_role`.
    Each writer checks again after its rewrite and repeats while the records say something else, so once the hooks
    finish the file matches the newest records whatever order they finished in (_recorded_guard_role also reads the
    role from the records directly). Returns False when the record could not be saved: run_hook then reports it as
    a hook error (never silently), and the readers refuse instead of reading a missing record as permission
    (hook_env_problem, director_session_problem)."""
    p = _hook_env_path(root)
    folder = root / RATCHET_DIR / HOOK_ENV_RECORDS
    cur = _current_hook_env()
    us = _iso_us(started or now()) or _iso_us(now())
    kind = "guard" if event == "guard" else "env"
    role = _hook_role() if kind == "guard" else "-"
    tag = f"{os.getpid()}-{secrets.token_hex(4)}"
    try:
        folder.mkdir(exist_ok=True)
        _write_record(folder / f"{p.name}.{kind}.{us}.{role}.{tag}", dict(cur, at=now(), host=host))
    except OSError:
        return False
    for r_us, r_kind, _r, _n, path in _hook_env_records(root) or []:
        if r_us < us and (kind == "guard" or r_kind == "env"):  # a guard record supersedes every older record
            try:
                path.unlink()
            except OSError:
                pass  # another run removed it first, or (Windows) it is busy: an old record changes nothing
    for _ in range(50):
        recs = _hook_env_records(root)
        if recs is None:
            return False
        view = _combined_hook_env(recs)
        if view is None:
            continue  # a record vanished while it was read: list again
        disk, _why = _read_record(p, missing=None)  # missing or damaged: rewritten below
        if isinstance(disk, dict) and all(disk.get(k) == view.get(k) for k in _HOOK_ENV_CORE):
            return True
        try:
            _write_record(p, {k: v for k, v in view.items() if v is not None})
        except OSError:
            return False
    return False


def hooks_installed_anywhere(*roots) -> bool:
    """True when Ratchet's hooks are installed for ANY agent CLI, at user scope or in the project scope of any of
    `roots`. Any host, not just the detected one: host detection reads environment variables a builder's script
    can set, so it must not be able to make installed hooks look absent."""
    return any(installed_hook_files(h, Path(r)) for h in HOOK_HOSTS for r in roots if r is not None)


def hooks_in_use(*roots) -> bool:
    """True when Ratchet's hooks are in use for any of these projects: installed for any agent CLI (user scope or a
    project's own config), or delivered some other way (a plugin) and seen working: a guard or stop hook (the ones
    that enforce) has run in one of these projects, or a hook failure there is still unresolved. A prompt hook
    alone does not count (it enforces nothing, as in hooks_status)."""
    if hooks_installed_anywhere(*roots):
        return True
    for r in roots:
        if r is None or not (Path(r) / RATCHET_DIR).is_dir():
            continue
        hb = read_heartbeat(Path(r))
        if isinstance(hb.get("guard"), dict) or isinstance(hb.get("stop"), dict) or unresolved_hook_crashes(Path(r),
                                                                                                         "unknown"):
            return True
    return False


def _hook_record_may_have_failed(root: Path) -> bool:
    """True when a missing hook-env record here may be a failed write rather than "no hook has run yet": a hook that
    cannot save its record records that as a crash (_hook_record_failed), which stays unresolved until a later run
    saves the record cleanly; and while Ratchet cannot read or save its crash state, a failure could go unrecorded."""
    return bool(hook_crash_state_problem(root) or unresolved_hook_crashes(root, "unknown"))


def _hook_record_doubt(root: Path) -> str | None:
    """Why the hook record of this project may be out of date (None when it can be trusted): a hook failure here is
    still unresolved (a crash, or a record it could not save: run_hook records both the same way), or Ratchet can't
    read or save its crash state. A failed write leaves the OLD record in place, which may name a director that no
    longer runs commands here, so no existing record is trusted while any such failure stands."""
    problem = hook_crash_state_problem(root)
    if problem:
        return f"Ratchet can't trust its hook crash records ({problem})"
    crashes = unresolved_hook_crashes(root, "unknown")
    if crashes:
        c = crashes[0]
        return (f"the {c['event']} hook on {c['host']} failed at {c['at'][:19]}Z (it crashed or could not save its "
                "record) and has not run cleanly since")
    return None


def hook_env_problem(root: Path, doubt: bool = True) -> str | None:
    """A plain reason when this process's per-user folder or director key file differs from what the hooks of
    this project recorded; None when they agree. A missing record is accepted only while it can mean "no hook has
    run here yet": hooks not installed, or installed but not yet run here (the agent CLI was not restarted). When a
    hook may have failed to save it (an unresolved hook crash, which is how run_hook records that failure, or crash
    state Ratchet can't read or save), the missing record is refused, never read as "anything goes". With `doubt`
    (the default), an existing record that agrees is refused too while such a failure stands (_hook_record_doubt):
    the failed write may have left it out of date."""
    rec, why = _read_record(_hook_env_path(root), kind=None, missing=_ABSENT)
    if rec is _ABSENT:
        if not (root / RATCHET_DIR).is_dir() or not hooks_in_use(root):
            return None  # no Ratchet state here, or no hooks in use: nothing records (or enforces) anything
        if not _hook_record_may_have_failed(root):
            return None  # hooks installed but none has run here yet (the agent CLI needs a restart)
        return (f"Refused: Ratchet's hooks are installed, but {_hook_env_path(root)} is missing and a hook may have "
                "failed to save it, so Ratchet can't confirm which per-user folder and director key file its hooks "
                "use, or whether this is the director's session. Every command here is refused until a hook saves "
                "it, director commands included (RATCHET_ROLE=director counts for nothing without that record); "
                f"only {', '.join(RECOVERY_CMDS)} still run, to show what is wrong. "
                "Make sure .ratchet/ is writable, then restart your agent CLI (or send it any message) so its hooks "
                "write the record again.")
    if why is not None:
        return (f"{_hook_env_path(root)} is unreadable, so Ratchet can't tell which per-user folder its hooks use. "
                "Delete it; the next hook run (send any message in your agent CLI) writes it again.")
    if not isinstance(rec, dict) or not rec.get("home") or not rec.get("key_file"):
        return (f"{_hook_env_path(root)} is not a complete record (a JSON object with `home` and `key_file`). "
                "Delete it; the next hook run writes it again.")
    cur = _current_hook_env()
    if rec.get("home") and not _same_path(rec["home"], cur["home"]):
        return (f"Ratchet's per-user folder here is {cur['home']}, but the hooks for this project use "
                f"{rec['home']}. The folders do not match, so Ratchet won't trust state, integrity records or "
                "approvals under this one. Unset RATCHET_HOME (or set it back to the hooks' folder). If you moved "
                "the folder on purpose, restart your agent CLI with the new RATCHET_HOME so its hooks record it.")
    if rec.get("key_file") and not _same_path(rec["key_file"], cur["key_file"]):
        return (f"The director key file here is {cur['key_file']}, but the hooks for this project use "
                f"{rec['key_file']}. They do not match, so Ratchet won't use this director key. Unset "
                "RATCHET_DIRECTOR_KEY_FILE (or set it to the same file the agent CLI uses).")
    why = _hook_record_doubt(root) if doubt else None
    if why:
        return (f"Refused: {why}, so {_hook_env_path(root)} may be out of date (a failed write leaves the old "
                "record, which may name a director that no longer runs commands here). Ratchet won't trust it, or "
                "the per-user folder and director key file it names, so every command here is refused until that "
                f"hook runs cleanly, director commands included; only {', '.join(RECOVERY_CMDS)} still run, to show "
                "what is wrong, and accept-state, the repair a person runs at their own terminal when Ratchet names "
                "it. Run the doctor command to see the "
                "failure, make sure .ratchet/ is writable, then send any message or run any command in your agent "
                "CLI so the hook runs again.")
    return None


# Commands that only read, or only repair hooks: they still run when the hook record can't be trusted, so a user
# locked out by it can see what is wrong (doctor, status, next, view) and reinstall the hooks (install-hooks).
# accept-state (the repair Ratchet names for a file or hash record it won't trust) also runs while a hook failure is
# unresolved, so a person is never locked out of it: it needs their code typed back at the terminal, and it is still
# refused when the hook record is missing, damaged or names another per-user folder (see main).
RECOVERY_CMDS = ("doctor", "status", "next", "view", "install-hooks")
_HOOK_ENV_ADVISORY = False  # set by main for a recovery command: a hook-record problem is said, not fatal


def require_hook_env(root: Path):
    why = None if _IN_HOOK else hook_env_problem(root)
    if why and not _HOOK_ENV_ADVISORY:
        die(why)


def _markers_path() -> Path:
    return ratchet_home() / "active-runs.json"


def _restriction_record_damaged(p: Path, holds: str, repair: str):
    """update_record's `damaged` rule for a per-user record `p` that holds a restriction for other projects or lanes
    too (`holds`). Such a record is never replaced by a write that would keep only the writer's entry: that would
    drop every other entry's restriction without a word. The damaged file is left as it is (KEEP) and the person is
    told, on stderr, how to repair it (`repair`)."""
    def keep(why):
        _note_unreadable(p, why, f"it holds {holds}, so Ratchet left it as it is and did not write over it. To "
                                 f"repair it: {repair}")
        return KEEP
    return keep


def _active_runs_repair(p: Path) -> str:
    return (f"restore it from a backup or fix the JSON by hand; or, if you accept that until then deleting a "
            f"project's .ratchet/ folder is not noticed, move it aside (mv \"{p}\" \"{p}.damaged\"): each project's "
            "entry is written again when its next run starts")


def register_active(root: Path, slug: str | None):
    """Remember active runs outside the repo, so deleting .ratchet/ is noticed instead of silently ending the loop.
    A damaged active-runs.json is never written over (it holds other projects' runs): see
    _restriction_record_damaged. It is shared by every project on this machine, so it is only changed through
    update_record, under its own lock: two runs starting or ending at once never drop each other's entry. When the
    lock can't be had, nothing is written and stderr says so."""
    try:
        p = _markers_path()
        key = str(root.resolve())

        def change(data):
            if slug:
                data[key] = {"slug": slug, "since": now()}
            else:
                data.pop(key, None)
            return data
        done = update_record(p, change, pretty=True, damaged=_restriction_record_damaged(
            p, "the active runs of other projects on this machine", _active_runs_repair(p)))
        if done == "busy":
            print(f"ratchet: the per-user record of active runs ({p}) was busy (its lock "
                  f"{_record_lock_path(p)} could not be had), so "
                  + ("this run was not registered there: deleting this project's .ratchet/ folder would not be "
                     "noticed. Run `ratchet.py pause` and then `ratchet.py resume` to register it again."
                     if slug else "this project's entry was not removed; the next run that starts here replaces it."),
                  file=sys.stderr)
    except Exception:
        pass


def _active_marker(root: Path) -> dict | None:
    """This project's entry in the per-user active-runs.json ({"slug", "since"}), or None. The record does two
    things: the stop hook uses it to notice a deleted Ratchet folder (decide_stop), and Ctx.active_slug uses it to
    name the active run when active.json is damaged. A damaged file names no run for either (so it never picks a
    run), and it is never written over until a person repairs it (register_active)."""
    data = read_json(_markers_path(), {}, record="Ratchet treats it as naming no active run, and leaves it as it is "
                     "until it is repaired: " + _active_runs_repair(_markers_path())) or {}
    marker = data.get(str(root.resolve()))
    return marker if isinstance(marker, dict) and marker.get("slug") else None


# A bare "ok", "sure", "great" or thumbs-up is NOT a yes (it is often just an acknowledgement); those words are
# allowed only as fillers around a real approval ("ok, go ahead").
APPROVAL_PHRASES = [
    "approved", "approve", "approval granted", "lgtm", "looks good to me", "looks good", "looks great", "sounds good",
    "go ahead", "go for it", "good to go", "ship it", "build it", "do it", "let's go", "lets go", "proceed", "continue",
    "carry on", "confirmed", "confirm", "yes", "yep", "yeah", "yup", "yes please", "works for me", "that works",
    "that's fine", "thats fine", "fine by me", "happy with it", "happy with that", "moveon"]
BENIGN_PHRASES = [
    "no changes needed", "no changes", "no further changes", "no comments", "nothing to change", "nothing else",
    "i don't have any comments", "i don't have comments", "i dont have comments", "no notes", "all good",
    "thanks", "thank you", "thx", "please", "pls", "awesome", "nice", "cool", "for now", "from me", "as is",
    "without changes", "without any changes"]
HEDGE_WORDS = {"no", "not", "don't", "dont", "wait", "hold", "stop", "but", "however", "except", "instead", "rather",
               "maybe", "probably", "guess", "think", "hmm", "unsure", "also", "add", "change", "remove", "drop",
               "after", "before", "first", "later", "read", "sec", "second", "minute", "moment", "lunch", "brb",
               "what", "why", "how", "who", "whom", "when", "which", "where", "if", "unless", "until",
               "otherwise", "kill", "fix", "tweak", "make", "move", "rename", "replace", "update", "adjust", "swap",
               "delete", "less", "more", "bigger", "smaller", "cancel", "abandon", "abort", "scrap", "pause",
               "restart", "redo", "revert", "undo", "reset", "over", "start", "nah", "nope", "never", "disagree",
               "wrong", "bad", "hate", "dislike", "reject", "rejected", "decline", "declined"}
# Words that may surround an approval without changing its meaning. Anything else left over makes the reply unclear.
APPROVAL_FILLERS = {"it", "the", "plan", "this", "that", "all", "then", "go", "on", "ahead", "and", "a", "i", "me", "we",
                    "you", "can", "now", "ok", "okay", "sure", "great", "perfect", "right", "alright", "fine", "is",
                    "please", "so", "just", "yes", "to", "with", "let's", "lets", "that's",
                    "thats", "👍", "✅", "good", "fully", "totally", "definitely", "absolutely"}


CHOICE_RE = re.compile(r"^(?:(?:option|choice|go with|let'?s go with|let'?s do|i choose|i pick|i'?ll take|choose|pick|take)\s+)?"
                       r"(?:option\s+)?\(?([a-z])\)?(?:\s+(?:please|thanks|thank you))?$")


def choice_letter(text: str, options) -> str | None:
    """The option a reply picks, if the reply is nothing but a pick ("A", "b.", "option C", "go with A please").
    Anything more ("A, but keep the old colour", "A or B?") is not a clear choice."""
    t = unicodedata.normalize("NFKC", text or "").strip().lower().replace("\u2019", "'")
    t = re.sub(r"[.!\s]+$", "", t)
    t = re.sub(r"\s+", " ", t.replace(",", " "))
    m = CHOICE_RE.match(t)
    if not m:
        return None
    letter = m.group(1).upper()
    return letter if letter in options else None


def message_intent(text: str) -> str:
    """approve | unclear. Used only to word the prompt hook's hint; it never decides an approval (an approval needs
    the user's first reply after `ask <action>` to be a listed yes: is_listed_yes).
    A reply only reads as an approval if it is nothing BUT an approval: it must contain a real
    approval phrase ("yes", "go ahead", "approved"...), and every other word must be a filler. No question, no hedge,
    no extra request ("yes, and also add X" or "ok cancel it" is not a yes). A bare "ok" / "sure" / thumbs-up is not
    a yes either."""
    t = " " + (text or "").strip().lower().replace("’", "'") + " "
    if not t.strip() or "?" in t:
        return "unclear"
    for ph in sorted(BENIGN_PHRASES, key=len, reverse=True):
        t = t.replace(" " + ph + " ", " ").replace(" " + ph + ",", " ").replace(" " + ph + ".", " ").replace(" " + ph + "!", " ")
    t = re.sub(r"\b(let's |lets )?move on\b", " moveon ", t)  # "move" alone asks for a change; "move on" is a go-ahead
    # Only plain letters, digits and ordinary punctuation are understood. Anything else (another script, another
    # emoji, full-width letters, a full-width question mark) could carry a "no" we can't read, so it is unclear.
    residue = re.sub("[a-z0-9'\\s.,!;:()\"\\-\u2014\u2013\u2026\ufe0f\U0001F3FB-\U0001F3FF\U0001F44D\u2705]", "", t)
    if residue:
        return "unclear"
    words = re.findall("[a-z0-9']+|\U0001F44D|\u2705", t)
    if any(w in HEDGE_WORDS for w in words):
        return "unclear"
    rest = " " + " ".join(words) + " "
    found = False
    for ph in sorted(APPROVAL_PHRASES, key=len, reverse=True):
        if " " + ph + " " in rest:
            found = True
            rest = rest.replace(" " + ph + " ", " ")
    leftover = [w for w in rest.split() if w not in APPROVAL_FILLERS]
    return "approve" if found and not leftover else "unclear"


# The ONLY replies that waive hooks (compared after normalising: lowercase, punctuation and extra spaces dropped,
# a trailing "please" dropped). Each one says what is being waived. Anything else is not consent, however it is worded.
HOOKS_WAIVE_PHRASES = frozenset({
    "yes go ahead without hooks", "yes skip the hooks", "yes build without hooks",
    "go ahead without hooks", "skip the hooks", "proceed without hooks",
})
HOOKS_WAIVE_REPLY = "yes, go ahead without hooks"


def _norm_reply(text: str) -> str:
    """NFKC + casefold, then drop only ASCII punctuation (except '?') and extra spaces and a trailing "please".
    Anything else (non-ASCII letters, emoji, CJK, '?') is kept, so it can never equal an allow-listed phrase."""
    t = unicodedata.normalize("NFKC", text or "").casefold().replace("\u2019", "'").replace("'", "")
    t = re.sub(r"[!-/:->@-`{-~\[-\]]+", " ", t)   # ASCII punctuation; '?' (0x3f) is deliberately not in this set
    t = " ".join(t.split())
    return re.sub(r"( please)+$", "", t).strip()


def hooks_waive_intent(text: str) -> str:
    """Strict allow-list for the hooks question: approve only when the whole reply is a listed waiver phrase."""
    return "approve" if _norm_reply(text) in HOOKS_WAIVE_PHRASES else "unclear"


# The ONLY replies that say yes to a question Ratchet asked (`ask <action>`): plan approval, a step or final review,
# unblocking, cancel, set-review, approve-changes, claim and ui-respec. Case, commas, extra spaces and a trailing "."
# or "!" are ignored; nothing else may be attached. Only the user's FIRST reply after the question counts.
APPROVAL_REPLIES = ("yes", "yes, go ahead", "go ahead", "approved")


def _norm_yes(text: str) -> str:
    t = unicodedata.normalize("NFKC", text or "").casefold().strip()
    t = re.sub(r"[.!]+$", "", t).replace(",", " ")
    return " ".join(t.split())


def is_listed_yes(text: str) -> bool:
    return _norm_yes(text) in {_norm_yes(p) for p in APPROVAL_REPLIES}


def listed_yes_text() -> str:
    """The accepted replies, quoted, for the printed question and the refusals."""
    q = [f'"{p}"' for p in APPROVAL_REPLIES]
    return ", ".join(q[:-1]) + " or " + q[-1]


CANCEL_HINT_RE = re.compile(r"\b(cancel|abandon|scrap|kill)\b[^.?!]*\b(run|build|feature|ratchet|loop|work|whole thing|everything)\b"
                            r"|\bforget (it|the whole thing)\b|\bstart over\b", re.I)


RULE_KEYS = ["review_depth", "reviewers", "max_adversarial_rounds", "max_adversarial_rounds_run", "max_ui_rounds",
             "max_behavior_attempts", "ui_block_on_nits", "ui_globs", "regression_command", "standards",
             "fingerprint_include", "approver", "ui_single_reviewer_ok", "min_review_timeout_sec", "test_timeout_sec",
             "host_provider", "ui_reviewers", "design_md", "max_stop_blocks", "unavailable_ttl_hours",
             "verify_transcripts", "min_review_seconds", "commit_per_checkpoint", "blocking_severities",
             "scope_later_rounds", "host_models", "role_models", "checks", "checkin_round", "converge_after_round",
             "doc_globs", "doc_exclude_globs", "test_globs", "doc_test_command", "related_test_command",
             "related_tests_max", "related_always", "small_edit_lines", "load_stretch_max", "suite_watch_seconds"]

# config.json keys that belong to the checkout they are set in (which reviewers and providers a run uses, the
# developer's consent to paid ones, and its own review limits): `integrate` never takes a lane's value for them,
# main's is kept and the lane's is listed as not taken. Every other key, and any unknown one, is project-wide.
LANE_LOCAL_CONFIG_KEYS = ["review_depth", "reviewers", "providers", "host_provider", "host_models", "role_models",
                          "ui_reviewers", "approver", "human_review", "max_adversarial_rounds",
                          "max_adversarial_rounds_run", "unavailable_ttl_hours", "probe_providers", "probe_ttl_minutes",
                          "probe_timeout_sec", "quota_retest_minutes", "provider_share"]


def _file_sha(p: Path) -> str | None:
    try:
        return hashlib.sha256(p.read_bytes()).hexdigest()[:16]
    except OSError:
        return None


def _reference_files(ctx) -> dict:
    """Files that define what 'correct' means: the standards reviewers enforce, the design system, the prototype."""
    cfg = ctx.config()
    files = {f: ctx.root / f for f in cfg.get("standards") or []}
    files[cfg.get("design_md") or "DESIGN.md"] = ctx.root / (cfg.get("design_md") or "DESIGN.md")
    try:
        files["reference/prototype.html"] = ctx.run_dir() / "reference" / "prototype.html"
    except SystemExit:
        pass
    return {k: _file_sha(v) for k, v in files.items()}


def _sha(obj) -> str:
    return hashlib.sha256(json.dumps(obj, sort_keys=True, ensure_ascii=False).encode()).hexdigest()[:16]


def _custom_providers_sha(cfg) -> str:
    """Reviewers that run an arbitrary command are trusted code: adding or changing one after approval needs the
    user's yes. Preset tools (and their model choice) are just availability and stay free to add."""
    rows = sorted((pv["id"], json.dumps(pv.get("command")), bool(pv.get("stdin")), norm_company(pv.get("company")))
                  for pv in providers(cfg) if pv.get("command"))
    return _sha(rows)


def approval_snapshot(ctx, st) -> dict:
    plan = ctx.plan() or {"checkpoints": []}
    cfg = ctx.config()
    return {"plan": _plan_hash(plan, ctx),
            "objective": plan.get("objective"),
            # Same fallback as _plan_hash: a checkpoint missing "id" must not crash the snapshot every
            # command's integrity check runs; validate_plan is what names that as a plan problem.
            "cps": {c.get("id", f"#{i}"): _sha(c) for i, c in enumerate(plan["checkpoints"])},
            # the checkpoint's own reviewers-pin FIELD as it stood at this approval (the raw value, not a hash): lets
            # approve-changes tell a genuine pin change (the field itself differs) apart from narrowing or substitution
            # (which never touch this field), with no guessing from resolved reviewers.
            "reviewers": {c.get("id", f"#{i}"): c.get("reviewers") for i, c in enumerate(plan["checkpoints"])},
            "tests": {c.get("id", f"#{i}"): _sha(test_plan(ctx, c.get("id", f"#{i}")))
                     for i, c in enumerate(plan["checkpoints"])},
            "rules": {k: _sha(cfg.get(k)) for k in RULE_KEYS},
            "files": _reference_files(ctx),
            "custom_providers": _custom_providers_sha(cfg),
            "spec": _spec_snapshot(ctx),
            "host": detect_host(cfg),
            "human_review": st.get("human_review"),
            # the planned test files as they stood at the red run (checkpoints.CPn.red_tests), as approved: a
            # record of the baseline approve-changes moved to (weakened_tests judges against red_tests itself)
            "red_tests": {cid: c.get("red_tests") for cid, c in (st.get("checkpoints") or {}).items()
                          if c.get("red_tests")}}


def integrity_problems(ctx, st) -> list[str]:
    """What changed since the human approved the plan (plan, test plans, or the loop's rules)."""
    snap = st.get("approved")
    if not snap:
        return []
    now_ = approval_snapshot(ctx, st)
    out = []
    for cid, h in snap.get("cps", {}).items():
        if now_["cps"].get(cid) != h:
            out.append(f"checkpoint {cid} in checkpoints.json")
    for cid, h in snap.get("tests", {}).items():
        if now_["tests"].get(cid) != h:
            out.append(f"test plan tests/{cid}.json")
    extra = set(now_["cps"]) - set(snap.get("cps", {}))
    if extra:
        out.append(f"new checkpoints {sorted(extra)} (use feedback + plan-extend)")
    user = read_json(ctx.config_path, {}) or {}
    for k, h in snap.get("rules", {}).items():
        if now_["rules"].get(k) != h:
            old_defaults = [_sha(v) for v in SHIPPED_DEFAULT_HISTORY.get(k, [])]
            if h in old_defaults and (k not in user or _sha(user.get(k)) in old_defaults):
                continue  # only Ratchet's shipped default changed (an update), not anything the user or agent set
            out.append(f"config rule '{k}'")
    for f, h in snap.get("files", {}).items():
        if now_["files"].get(f) != h:
            out.append(f"reference file {f}")
    if "custom_providers" in snap and snap["custom_providers"] != now_["custom_providers"]:
        out.append("custom review commands in config 'providers' (a reviewer defined by its own command, or its "
                   "company, was added or changed)")
    if snap.get("spec") and snap["spec"] != now_.get("spec"):
        out.append("the spec this run was built from (" + ", ".join(
            f"{r['tool']} {r['id']}" for r in (spec_source(ctx) or {}).get("items") or []) + ")")
    out += weakened_tests(ctx, st)
    if snap.get("host") and snap["host"] != now_["host"]:
        out.append(f"host provider ({snap['host']} → {now_['host']})")
    if snap.get("human_review") != st.get("human_review"):
        out.append("human_review mode")
    return out


def verify_integrity(ctx, st):
    probs = integrity_problems(ctx, st)
    if probs:
        if approval_mode(ctx) == "director":  # an enrolled lane: the director approves, nobody is asked in chat
            die("These changed after the user approved the plan: " + _problems_for_director(probs) + ". This lane is "
                "director-enrolled, so either undo the change, or have the director approve it in one step with "
                f"`{_director_apply_cmd(ctx, 'approve-changes')}` (or sign it for a token this lane applies with "
                "`ratchet.py approve-changes --director-token <t>`). End your turn saying what you are waiting for.")
        die("These changed after the user approved the plan: " + "; ".join(probs) + ". "
            "Either undo the change, or show the user exactly what changed and — only after they confirm — "
            "run `ratchet.py approve-changes`.")


# --------------------------------------------------------------------------- plan validation

OBJECTIVE_EXAMPLE = ('{"users": "who will use the result", "goal": "what they are trying to do", '
                      '"done_means": ["what done means to them, one line per point"], '
                      '"out_of_scope": ["what this run deliberately will not build or chase"]}')


def objective_problems(plan) -> list[str]:
    """What is missing from the plan's top-level 'objective' (who it is for, what they want, what done means,
    what is out of scope). Checked at plan-submit, not in validate_plan (shared with plan-extend, which instead
    refuses a feedback plan that drops an objective the approved plan had)."""
    obj = plan.get("objective") if isinstance(plan, dict) else None
    if not isinstance(obj, dict) or not obj:
        return [f"objective: missing. Every plan needs one, e.g. {OBJECTIVE_EXAMPLE}"]
    errs = []
    if not str(obj.get("users") or "").strip():
        errs.append("objective.users: missing or empty (who will use the result)")
    if not str(obj.get("goal") or "").strip():
        errs.append("objective.goal: missing or empty (what they are trying to do)")
    dm = obj.get("done_means")
    if not isinstance(dm, list) or not any(str(x or "").strip() for x in dm):
        errs.append("objective.done_means: missing or empty (what done means to them, as a non-empty list)")
    oos = obj.get("out_of_scope")
    if not isinstance(oos, list) or not any(str(x or "").strip() for x in oos):
        errs.append("objective.out_of_scope: missing or empty (what this run deliberately will not build or "
                    "chase, as a non-empty list)")
    errs += _objective_fill_ins(obj)
    return errs


def _proves_values(case) -> list:
    """Normalize one test-plan case's "proves" field for every consumer (proves_problems, _done_means_links,
    _done_means_proof): a missing value is [] (nothing to prove), a scalar int counts as [int] (the common
    planner slip of writing "proves": 1 instead of [1]), a list is used as-is. Any other shape is not a number
    or a list of numbers, so there is nothing valid to normalize here; plan-submit's proves_problems is the one
    place that refuses it outright, naming the case, before plan-summary or receipt ever reads it."""
    proves = case.get("proves")
    if proves is None:
        return []
    if isinstance(proves, list):
        return proves
    if isinstance(proves, int) and not isinstance(proves, bool):
        return [proves]
    return []


def proves_problems(ctx, plan) -> list[str]:
    """CP3: a test-plan case's optional "proves" (the spec_ref precedent's sibling) names, 1-based, the lines
    of the objective's done_means it proves. plan-submit refuses any number that is not really a done_means
    line, naming the offending case (plan-extend applies the same check to the appended checkpoints' cases only,
    passing a plan holding just those); a plan with no objective or no done_means lines (objective_problems
    already refuses that on its own) simply has nothing valid to name, so every number is refused. "proves" may
    be a single integer (normalized to a one-item list, see _proves_values) or a list; any other shape (a
    string, a dict, a list containing one) is refused here by name, so plan-summary and receipt never have to
    guess at it."""
    obj = plan.get("objective") if isinstance(plan, dict) else None
    dm = obj.get("done_means") if isinstance(obj, dict) else None
    n = len(dm) if isinstance(dm, list) else 0
    errs = []
    for cp in plan.get("checkpoints") or []:
        for case in (test_plan(ctx, cp["id"]) or {}).get("cases") or []:
            if case.get("layer") == "shortcuts":  # names a shortcut table that exists (tests/shortcuts/<table>.json)
                t = case.get("table")
                if not isinstance(t, str) or not re.fullmatch(r"[A-Za-z0-9_.-]+", t):
                    errs.append(f"{case.get('id', '?')}: a shortcuts case must name its table in \"table\" "
                                f"(tests/shortcuts/<table>.json)")
                elif not (ctx.root / SHORTCUT_DIR / f"{t}.json").is_file():
                    errs.append(f"{case.get('id', '?')}: shortcut table {t!r} does not exist "
                                f"({SHORTCUT_DIR}/{t}.json)")
                else:
                    try:
                        tdef, twhy = _sc_parse((ctx.root / SHORTCUT_DIR / f"{t}.json").read_text(errors="replace"))
                    except OSError as e:
                        tdef, twhy = None, f"unreadable: {e}"
                    gone = _sc_watch_missing(ctx, None, tdef["watches"]) if tdef else []
                    if twhy or gone:
                        errs.append(f"{case.get('id', '?')}: shortcut table {t!r} cannot be used: "
                                    + (twhy or f"it watches {', '.join(gone)}, which does not exist"))
            proves = case.get("proves")
            if proves is None:
                continue
            if not isinstance(proves, list) and not (isinstance(proves, int) and not isinstance(proves, bool)):
                errs.append(f"{case.get('id', '?')}: proves {proves!r} must be a done_means line number or a "
                            f"list of them (objective.done_means has {n} line(s))")
                continue
            for p in _proves_values(case):
                if not isinstance(p, int) or isinstance(p, bool) or p < 1 or p > n:
                    errs.append(f"{case.get('id', '?')}: proves {p!r} is not a done_means line "
                                f"(objective.done_means has {n} line(s))")
    return errs


NO_OBJECTIVE_NOTE = "no objective was stated for this run (an older plan, approved before this feature existed)"


def objective_brief(plan, proof_notes=None) -> str:
    """Plain text of the plan's objective, for the top of every reviewer prompt and every sub-agent's brief: who
    the result is for, what they want, what done means, what is out of scope. With `proof_notes` (the dict
    `_done_means_proof_notes` builds: {1-based done_means line number: one note line}), each done-means bullet is
    followed by its note (`Proved by: <case ids>`, or the plain `Heads up` for a line no case proves yet); this is
    the one rendering `plan-summary`, `brief` and the launch guard share, so a brief's objective matches
    plan-summary's word for word. Done-means lines are numbered 1..N (`  - 1. <line>`, still a "- " bullet so
    the objective block reads the same as the other bullets), the same 1-based numbers a test case's "proves"
    and a review finding's `done_means` (CP3) use, so a reviewer can name the line a finding contradicts. A
    plan with no objective at all (a run approved before CP1's
    objective_problems() existed) gets a plain note instead of a crash, so a legacy run keeps reviewing normally."""
    obj = plan.get("objective") if isinstance(plan, dict) else None
    if not isinstance(obj, dict) or not obj:
        return f"Objective: {NO_OBJECTIVE_NOTE}."
    lines = ["Objective", f"Who it's for: {obj.get('users', '')}", f"What they want: {obj.get('goal', '')}"]
    dm = obj.get("done_means") or []
    if dm:
        lines.append("Done means:")
        for i, x in enumerate(dm, 1):
            lines.append(f"  - {i}. {x}")
            if proof_notes and proof_notes.get(i):
                lines.append(f"    {proof_notes[i]}")
    oos = obj.get("out_of_scope") or []
    if oos:
        lines.append("Out of scope:")
        lines += [f"  - {x}" for x in oos]
    return "\n".join(lines)


# Each Ratchet sub-agent role's own standing rules, short and plain, printed by `brief` right after the objective
# so the orchestrator never has to remember or retype them. One dict, one source, instead of scattered strings in
# each agent file: keep an agent's own .md file (e.g. agents/ratchet-fixer.md) worded consistently with its entry
# here, but this dict is what every spawn prompt actually gets.
ROLE_BRIEFS = {
    "implementer": ("Rules: make the smallest change that makes this checkpoint's planned tests pass. Add no new "
                     "mechanism or file beyond what this checkpoint needs. Don't run the full test suite unless "
                     "asked; run only this checkpoint's own tests. Never edit, skip or weaken a test."),
    "fixer": ("Rules: make the smallest change that resolves each finding you were handed. Add no new mechanism or "
              "file unless the finding itself needs it. If a proper fix needs a redesign, stop and say so instead "
              "of improvising one. Never weaken, skip or delete a planned test, a test that existed before "
              "the run, or anything a planned test uses; a Python test this lane added that no planned test uses may be "
              "adjusted. Don't run the full test suite unless asked."),
    "test-writer": ("Rules: turn the checkpoint's planned test cases into real, runnable tests tagged with their "
                     "case ids, written before the implementation exists, so at least one fails on an assertion. "
                     "Test behavior through public entry points, not internals. Never write a test that can't fail. "
                     "An extra Python test you add that no planned test uses may be adjusted later; planned "
                     "tests, what they use and tests from before the run stay locked."),
    "reviewer": ("Rules: judge every finding against the realistic-use bar: this project's users run a cooperative "
                 "agent, not an attacker, and a finding must describe real harm to them in realistic, normal use, "
                 "not a case no real user would hit. Every blocking finding (blocker or major) must say who is hurt "
                 "and how; leave that out and it does not block. The one exception: a finding that names a done-means "
                 "line of the objective (done_means) blocks at any severity and any round, with no separate "
                 "user_impact needed, so name a line only when that line is not met in normal use; a plan approved "
                 "before that rule keeps the older severity and round rules, and the round's review rules say so when "
                 "that is the case. Approve only when you genuinely find nothing."),
    "scout": ("Rules: verify the app, its tests and its dev server actually run before anyone else relies on your "
              "report; don't guess. Record what's already green, what's already broken, and what's missing, so a "
              "later checkpoint is never blamed for a problem that was there before the build started."),
    "planner": ("Rules: write the plan's objective first. Slice the work into small checkpoints of increasing "
                "complexity a human can approve in minutes. Ask a question instead of guessing on anything that "
                "changes the plan's shape. A high-risk step needs its own risk_reason naming who could be harmed."),
    "test-planner": ("Rules: plan this checkpoint's test cases before any code exists, through public entry "
                     "points, with every done_when line covered. Every objective done-means line above needs at "
                     "least one case, in some step's tests/CPn.json, whose \"proves\" names it by its 1-based "
                     "number; plan-submit refuses a plan that leaves a done-means line unlinked, naming the line. "
                     "Don't write test code."),
}

ROLE_ORDER = ["implementer", "fixer", "test-writer", "reviewer", "scout", "planner"]

# Every other agent in agents/ gets this same short generic line instead of a custom rule set: it still points the
# agent back at the objective and the smallest-change discipline every role shares, without inventing bespoke
# wording per agent (the fix this round deliberately keeps smaller than a custom brief for each one).
_GENERIC_ROLE_RULES = ("Rules: follow your own agent instructions for this role. Serve the objective above. Make "
                        "the smallest change for the job. Don't run the full test suite unless asked.")
for _generic_role in ("behavior-reviewer", "design-system", "prototyper", "test-runner", "variant-writer",
                      "visual-reviewer"):
    ROLE_BRIEFS[_generic_role] = _GENERIC_ROLE_RULES

# agents/*.md names that don't match a ROLE_BRIEFS key directly (the rest of the agents/ file stems -- adversary,
# behavior-reviewer, checkpoint-planner, design-system, fixer, implementer, prototyper, test-planner (its own
# entry above: the done-means link rule), test-runner,
# test-writer, variant-writer, visual-reviewer, app-scout -- already equal a ROLE_BRIEFS key once the optional
# `ratchet-` prefix is stripped). Keep this to just the renames so `--role` accepts every agent the orchestrator
# spawns without a bespoke rule set per agent.
ROLE_ALIASES = {"adversary": "reviewer", "app-scout": "scout", "checkpoint-planner": "planner"}


def _normalize_role(raw: str) -> str | None:
    """`--role` accepts a ROLE_BRIEFS key directly, any agents/*.md file stem (with or without its `ratchet-`
    prefix), and the ROLE_ALIASES renames for the three agents whose file name doesn't match a role name. Returns
    None for anything else, so `cmd_brief` can refuse it with a plain message instead of argparse's own."""
    tok = raw[len("ratchet-"):] if raw.startswith("ratchet-") else raw
    tok = ROLE_ALIASES.get(tok, tok)
    return tok if tok in ROLE_BRIEFS else None


# ------------------------------------------------------------------------------------------------- earlier-work digest
# So a new feature builds on what earlier work in this project already learned, instead of rediscovering or
# contradicting it, the planner's own brief ends with a short "What earlier work says" section built entirely
# from records already on disk; the orchestrator never has to collect this by hand. Entirely read-only: every
# OTHER run's state.json is read with _read_record directly, never ctx.state() (which verifies the chain and
# binds an owner -- right for the run this process is actually working on, wrong for history it only reads), and
# a damaged or missing record is skipped, never fatal. CP2 adds a recorded-specs section to the same list this
# helper returns, so cmd_brief only ever has one block to print.

DIGEST_HEADING = "What earlier work says"
DIGEST_ITEM_CAP = 5  # a few items per section; the rest are named by count and pointed at their file, not printed
DIGEST_ITEM_MAX_CHARS = 200  # a fixed length per printed item, so one long or multi-line item can't break the list
DIGEST_SPEC_HEAD = "Related specs:"
DIGEST_SPEC_PATH_NOTE = "openspec/specs/, specs/ (Spec Kit) and docs/stories/ (BMAD)"

_BULLET_HEAD_RE = re.compile(r"^-\s*\([^)]*\)\s*(.*)$")  # strips a learnings.md bullet's "(date, source)" head, leaving the text
_BULLET_DATE_RE = re.compile(r"^-\s*\((\d{4}-\d{2}-\d{2})\b")  # the date at the start of that same head, for ranking
_ACCEPTED_FINDING_MARKER_RE = re.compile(r"^Accepted finding (\S+) \(", re.I)  # the marker _append_learning writes


def _digest_words(text: str) -> set:
    return specsrc._words(text or "")


def _digest_clean_item(text: str) -> str:
    """One printed digest item, made safe for the short, plain list `_digest_cap_lines` prints: whitespace (including
    embedded newlines) collapsed to single spaces, non-ASCII replaced, and truncated to DIGEST_ITEM_MAX_CHARS with a
    trailing "..." when cut, so a multi-line or very long description can never break the list or defeat "stays
    short"."""
    one_line = " ".join(str(text or "").split())
    ascii_text = one_line.encode("ascii", "replace").decode("ascii")
    if len(ascii_text) > DIGEST_ITEM_MAX_CHARS:
        ascii_text = ascii_text[:DIGEST_ITEM_MAX_CHARS - 3].rstrip() + "..."
    return ascii_text


def _digest_cp_order(cp) -> int:
    """A checkpoint id ('CP1', 'CP12', ...) as a plain int for ordering, so 'later checkpoint first' is a number
    comparison rather than a string one (where 'CP2' would wrongly sort after 'CP10')."""
    m = re.search(r"(\d+)\s*$", str(cp or ""))
    return int(m.group(1)) if m else 0


def _digest_epoch(text) -> float | None:
    """`text` parsed as an ISO-8601 timestamp (what `now()` writes, e.g. an `accepted_at`) into epoch seconds, or
    None when it isn't one."""
    if not text:
        return None
    try:
        return _dt.datetime.fromisoformat(str(text)).timestamp()
    except (ValueError, TypeError):
        return None


def _digest_recency(epoch: float, cp: str = "", round_no=0) -> tuple:
    """One comparable recency key, in the same unit (epoch seconds) for every item in a digest section, whatever
    its source: a learnings.md bullet's own date, a finding's own recorded time, or (falling back) the run file's
    mtime as a date. `cp`/`round_no` are a secondary, same-run tie-break only: many findings in one run share that
    run's single mtime, so without this every one of them ties and a stable sort keeps the oldest five instead of
    the newest; a later checkpoint and later round sort as newer when the timestamp itself ties."""
    return (epoch, _digest_cp_order(cp), int(round_no or 0))


def _digest_rank(words: set, relevant_to: set, recency) -> tuple:
    """Sort key for one digest item: an item sharing a word with the active run's feature request comes before
    everything else; within each of those two groups, the newest comes first (the run's own assumption: relevance
    first, newest as the tie-break and the only order left once there is no feature to match against). `recency` is
    a single comparable number or a `_digest_recency` tuple; either way every component sorts newest-first."""
    relevant = bool(relevant_to) and bool(words & relevant_to)
    if not isinstance(recency, tuple):
        recency = (recency,)
    return (0 if relevant else 1, tuple(-r for r in recency))


def _learnings_bullets(ctx) -> list[str]:
    """Every '- (...)' bullet line in learnings.md, oldest first (the file's own append order; age itself is read
    from each bullet's own "(YYYY-MM-DD, ...)" head, see _digest_bullet_epoch, not from this order)."""
    return [l.strip() for l in _learnings_text(ctx).splitlines() if l.strip().startswith("-")]


def _digest_bullet_epoch(raw: str, fallback_index: int) -> float:
    """A learnings.md bullet's own recency, in the same epoch-seconds unit every other digest item uses: the date
    in its "(YYYY-MM-DD, ...)" head, read as UTC midnight. A bullet with no such date (malformed, or hand-edited)
    falls back to its position in the file so it still sorts somewhere instead of crashing the brief."""
    m = _BULLET_DATE_RE.match(raw)
    if m:
        try:
            return _dt.datetime.strptime(m.group(1), "%Y-%m-%d").replace(tzinfo=_dt.timezone.utc).timestamp()
        except ValueError:
            pass
    return float(fallback_index)


def _digest_cap_lines(items: list[tuple], header: str, path_note: str) -> list[str]:
    """`items` is a list of (sort_key, one-line text) already gathered for one section; prints the best
    DIGEST_ITEM_CAP of them under `header`, then one line always naming the file this section's items come from
    (plus how many more there are, when some were cut), so the planner knows where to read the rest even when
    nothing was cut. Nothing is printed for an empty section (no header with nothing under it). Each item's text is
    passed through _digest_clean_item first, so a multi-line or very long description can't break the list."""
    if not items:
        return []
    items = sorted(items, key=lambda it: it[0])
    shown, rest = items[:DIGEST_ITEM_CAP], items[DIGEST_ITEM_CAP:]
    out = [header] + [f"  - {_digest_clean_item(line)}" for _, line in shown]
    if rest:
        out.append(f"  ... and {len(rest)} more - see {path_note}")
    else:
        out.append(f"  ... see {path_note}")
    return out


def _earlier_runs(ctx, active_slug):
    """(slug, state, path) for every OTHER run folder under .ratchet/runs/: read with _read_record so a damaged
    state.json, or a run folder with none at all, is skipped instead of failing the brief. Never the active run,
    and never through ctx.state()."""
    out = []
    try:
        slugs = sorted(p.name for p in (ctx.ratchet / "runs").iterdir() if p.is_dir())
    except OSError:
        return out
    for slug in slugs:
        if slug == active_slug:
            continue
        p = ctx.ratchet / "runs" / slug / "state.json"
        st, why = _read_record(p, missing=_ABSENT)
        if why is not None or st is _ABSENT or not isinstance(st, dict):
            continue
        out.append((slug, st, p))
    return out


def _spec_digest_entry(title: str, purpose: str, path: str) -> str:
    """One printed 'Related specs:' line: "<title>: <purpose> (<path>)". The path is reserved its own room and
    appended last, after the title/purpose head is truncated to fit -- so a long title can never push the path
    past _digest_clean_item's length cap and drop the one thing the planner needs to open the full spec."""
    title = str(title or "").strip()
    purpose = str(purpose or "").strip()
    path = str(path or "").strip()
    tail = f" ({path})"
    budget = max(DIGEST_ITEM_MAX_CHARS - len(tail), 0)
    head = title + (f": {purpose}" if purpose else "")
    if len(head) > budget:
        head = head[:budget - 3].rstrip() + "..." if budget > 3 else head[:budget]
    return f"{head}{tail}"


def _related_spec_items(ctx, relevant_to: set) -> list[tuple]:
    """(sort_key, line) for every recorded spec worth telling the planner about, ranked with the same
    relevance-then-recency rule as every other digest section so no one spec tool is favoured over another:
    OpenSpec's living records under openspec/specs/ (including Ratchet's own running records written by
    living_spec_text), a finished Spec Kit feature (every task in tasks.md ticked) and a done BMAD story (its
    status is exactly "done", ignoring case and surrounding whitespace). An open or unfinished one is left
    out -- `spec detect` already covers those. Each
    source is read the tolerant way (a bad or missing file is skipped, never fatal), since a brief must never
    fail to print over a spec file someone is still editing."""
    items = []
    try:
        openspec = specsrc.openspec_specs(ctx.root)
    except (OSError, ValueError):
        openspec = []
    for s in openspec:
        words = _digest_words(f"{s['title']} {s['purpose']}")
        line = _spec_digest_entry(s["title"], s["purpose"], s["path"])
        items.append((_digest_rank(words, relevant_to, _digest_recency(s["mtime"])), line))
    try:
        features = specsrc.speckit_features(ctx.root)
    except (OSError, ValueError):
        features = []
    for f in features:
        tasks = f.get("tasks") or []
        if not tasks or not all(t.get("done") for t in tasks):
            continue
        path = f"{f['path']}/spec.md"
        try:
            mtime = (ctx.root / path).stat().st_mtime
        except OSError:
            mtime = 0.0
        purpose = f.get("why") or ""
        words = _digest_words(f"{f['title']} {purpose}")
        line = _spec_digest_entry(f["title"], purpose, path)
        items.append((_digest_rank(words, relevant_to, _digest_recency(mtime)), line))
    try:
        stories = specsrc.bmad_stories(ctx.root)
    except (OSError, ValueError):
        stories = []
    for s in stories:
        if str(s.get("status") or "").strip().lower() != "done":
            continue
        try:
            mtime = (ctx.root / s["path"]).stat().st_mtime
        except OSError:
            mtime = 0.0
        purpose = s.get("why") or ""
        words = _digest_words(f"{s['title']} {purpose}")
        line = _spec_digest_entry(s["title"], purpose, s["path"])
        items.append((_digest_rank(words, relevant_to, _digest_recency(mtime)), line))
    return items


def _earlier_work_lines(ctx) -> list[str]:
    """Everything the planner's brief shows about earlier work: the project's recent learnings, the findings
    earlier (non-active) runs saved for later that nobody accepted yet, and the limits the user already
    accepted (an accepted finding, or a learnings.md "Accepted limit (...)" bullet) -- most relevant to the new
    feature first, newest after that, each section capped. A project with no earlier work of any kind gets one
    plain line instead of empty sub-headings. Takes no lock and writes nothing."""
    active_slug = ctx.active_slug()
    active_feature = ""
    if active_slug:
        # Read with _read_record, the same tolerant path _earlier_runs uses for every OTHER run -- never
        # ctx.state(), which verifies the chain and can die() on a mismatch; a brief must never fail to print
        # over the active run's own record, so any problem here just leaves relevance empty.
        st, why = _read_record(ctx.ratchet / "runs" / active_slug / "state.json", missing=_ABSENT)
        if why is None and st is not _ABSENT and isinstance(st, dict):
            active_feature = st.get("feature") or ""
    relevant_to = _digest_words(active_feature)

    learn_items, open_items, accepted_items = [], [], []
    accepted_keys = set()  # "{slug}/{cp}/round-{round}/{reviewer-or-bare-id}" already shown from a state.json,
                            # so the matching learnings.md marker line for the same finding is never shown twice

    for slug, st, path in _earlier_runs(ctx, active_slug):
        try:
            mtime = path.stat().st_mtime
        except OSError:
            mtime = 0
        for cp, c in (st.get("checkpoints") or {}).items():
            if not isinstance(c, dict):
                continue
            for f in c.get("deferred") or []:
                if not isinstance(f, dict):
                    continue
                desc = str(f.get("description", "")).strip()
                if not desc:
                    continue
                round_no = f.get("round")
                if f.get("accepted"):
                    who = f.get("accepted_by") or "a human"
                    reason = str(f.get("reason", "")).strip()
                    line = f"{cp} {_finding_key(f)} ({f.get('severity', '?')}), accepted by {who}: {desc}"
                    if reason:
                        line += f" - reason: {reason}"
                    epoch = _digest_epoch(f.get("accepted_at")) or mtime
                    recency = _digest_recency(epoch, cp, round_no)
                    accepted_items.append((_digest_rank(_digest_words(desc), relevant_to, recency), line))
                    accepted_keys.add(f"{slug}/{cp}/round-{round_no}/{_finding_key(f)}")
                else:
                    line = f"{cp} {_finding_key(f)} ({f.get('severity', '?')}): {desc}"
                    epoch = _digest_epoch(f.get("at")) or mtime
                    recency = _digest_recency(epoch, cp, round_no)
                    open_items.append((_digest_rank(_digest_words(desc), relevant_to, recency), line))

    for i, raw in enumerate(_learnings_bullets(ctx)):
        m = _BULLET_HEAD_RE.match(raw)
        rest = m.group(1) if m else raw
        display = raw[1:].strip() if raw.startswith("-") else raw
        recency = _digest_recency(_digest_bullet_epoch(raw, i))
        fm = _ACCEPTED_FINDING_MARKER_RE.match(rest)
        if fm:
            if fm.group(1) in accepted_keys:
                continue  # the matching finding already shown from its own run's state.json
            accepted_items.append((_digest_rank(_digest_words(display), relevant_to, recency), display))
        elif re.match(r"^Accepted limit\b", rest, re.I):
            accepted_items.append((_digest_rank(_digest_words(display), relevant_to, recency), display))
        else:
            learn_items.append((_digest_rank(_digest_words(display), relevant_to, recency), display))

    lines = _digest_cap_lines(learn_items, "Learnings:", ".ratchet/learnings.md")
    lines += _digest_cap_lines(open_items, "Open findings (not fixed):",
                               "each run's state.json under .ratchet/runs/")
    lines += _digest_cap_lines(accepted_items, "Accepted limits:",
                               "each run's state.json under .ratchet/runs/, and .ratchet/learnings.md")
    lines += _digest_cap_lines(_related_spec_items(ctx, relevant_to), DIGEST_SPEC_HEAD, DIGEST_SPEC_PATH_NOTE)
    if not lines:
        return [DIGEST_HEADING, "There is no earlier work recorded for this project yet."]
    return [DIGEST_HEADING] + lines


def cmd_brief(args):
    """`brief [CPn] --role <role>`: the one place every Ratchet sub-agent's opening text comes from, so the
    orchestrator spawns a sub-agent with `ratchet.py brief CPn --role <role>` instead of retyping or half-remembering
    the objective and that role's rules. Prints the plan's objective exactly as `objective_brief` renders it (the
    same text reviewer prompts already open with), then that role's own standing rules (ROLE_BRIEFS). `--role` takes
    the agent's name (any file stem under agents/, with or without the `ratchet-` prefix) as well as the six
    original role names; see `_normalize_role`. CPn is optional: the scout and the planner are briefed before any
    checkpoint exists, before checkpoints.json even exists (that die is only reached when a CPn is given, since a
    CPn can't be looked up with no plan at all). Under each done-means line it prints the same `Proved by` or
    `Heads up` note plan-summary prints (`_done_means_proof_notes`), so the two stay word for word the same and the
    launch guard (`_brief_guard`) compares against this same rendering. A plan with no
    stated objective (approved before that rule existed)
    gets the plain NO_OBJECTIVE_NOTE instead of a crash. An unknown CPn is refused by `cp_by_id`, the same shared
    lookup every other command uses. The planner's brief, and only the planner's, ends with one more block: the
    "What earlier work says" section from `_earlier_work_lines` (see there), so the plan builds on what earlier
    work in this project already learned instead of rediscovering or contradicting it."""
    role = _normalize_role(args.role)
    if role is None:
        die(f"'{args.role}' is not a valid role for brief. Valid roles: {', '.join(ROLE_ORDER)} (or an agent name "
            f"from agents/, with or without the 'ratchet-' prefix).")
    ctx = Ctx(find_root())
    plan = ctx.plan()
    if args.cp:
        if not plan or not plan.get("checkpoints"):
            die("There is no plan yet. Finish planning first, then ask again.")
        cp = cp_by_id(plan, args.cp)
        header = f"{args.cp}: brief for the {role} — {cp.get('title', '')}".rstrip(" —")
    else:
        header = f"Brief for the {role} (no checkpoint yet)"
    print(header)
    print("")
    st, _why = _read_record(ctx.state_path())
    plan = _plan_for_briefs(plan, st)  # the approved done-means lines once approved (CP4), see _plan_for_briefs
    print(objective_brief(plan, _done_means_proof_notes(ctx, plan, st)))
    print("")
    print(ROLE_BRIEFS[role])
    if role == "planner":
        print("")
        print("\n".join(_earlier_work_lines(ctx)))


def _final_review_lines(ctx, st, plan) -> list[str]:
    """What `status` opens the finish pause with (`_finish_pending`: the final review, or the last step's review
    in human_review `each` mode): the objective's goal and users, then a table of every
    done_means line marked proven or unproven (`done_means_table`, the same verdicts `status --json` and the
    receipt carry): the tests behind the line with their results, and for an unproven line why (no test linked,
    a linked test failed or has no result, a browser test no UI gate checked, or an open finding that names the
    line). A line the user accepted (CP5, verdict "accepted") shows who accepted it, what held the line (its
    real `reasons`, which the acceptance covered) and their reason in place of its tests, never the word unproven;
    a line held again after an acceptance (`_apply_accepted_lines`: a new reason, or a new open finding naming it)
    reads unproven with a "held again" reason that names the earlier acceptance. Completing every checkpoint never
    proves a line is met, so the verdict comes from the recorded test results and findings, not from the agent's
    judgment. The objective and its lines are the APPROVED ones
    (`_plan_as_approved`), so an edit to checkpoints.json after approval never changes the table. `status`
    prints the findings accepted along the way (`_accepted_findings_lines`) and anything left for later right
    after, and (cmd_status_text) the finish block or the older-run note. A plan with no stated objective, or
    whose tests are linked to no line (approved before that existed), gets a plain note instead of a table, and
    never a crash."""
    plan = _plan_as_approved(plan, st)
    obj = plan.get("objective") if isinstance(plan, dict) else None
    if not isinstance(obj, dict) or not obj:
        return [f"Objective: {NO_OBJECTIVE_NOTE}."]
    out = [f"Objective: {obj.get('goal', '')}", f"Who it's for: {obj.get('users', '')}"]
    table = done_means_table(ctx, plan, st)
    if not isinstance(table, list):
        if not obj.get("done_means"):
            out.append(f"Done means: {table}.")
            return out
        out.append("Done means:")
        out += [f"  - {dm}" for dm in obj.get("done_means") or []]
        out.append(table)
        return out
    n_ok = sum(1 for e in table if e["verdict"] == "proven")
    n_acc = sum(1 for e in table if e["verdict"] == "accepted")
    n_un = len(table) - n_ok - n_acc
    out.append(f"Done means ({n_ok} of {len(table)} lines proven" + (f", {n_acc} accepted" if n_acc else "") + (
        f", {n_un} unproven" if n_un else "") +
        "; a line is proven only when every test linked to it passed and no open finding names it):")
    for e in table:
        out.append(f"  {e['number']}. {e['text']}: {e['verdict']}")
        if e["verdict"] == "accepted":
            out.append(f"     {_accepted_line_text(e)}")
            continue
        out += [f"     - {c['id']}: {c['result']}" for c in e["cases"]]
        if e["reasons"]:
            out.append(f"     Why unproven: {'; '.join(e['reasons'])}")
    return out


def _accepted_line_text(e: dict, with_ids: bool = True) -> str:
    """The one line `status` and the receipt print under a done-means line the user accepted (CP5): who accepted
    it, what held the line (the entry's real `reasons`: a failed or missing test result, an open finding naming
    it, no test linked; all of them covered by the acceptance, `_apply_accepted_lines`) and their reason, on one
    line (a multi-line reason is collapsed), in place of its tests. Never a fixed cause: a line held by an open
    finding alone must not read as if its tests failed. The receipt (cmd_receipt) passes `with_ids=False`: there
    an accepted line is shown apart from the proven lines, without its test ids, so each test reason reads "a
    linked test failed" / "a linked test has no result" instead of naming the case (`receipt --json` keeps the
    full `reasons`); an open finding is named either way."""
    a = e.get("accepted") or {}
    who = "the director" if a.get("accepted_by") == "director" else "the user"
    reasons = [str(r) for r in e.get("reasons") or []]
    if not with_ids:
        for c in e.get("cases") or []:
            cid = str(c.get("id") or "")
            # by slice on a space boundary, never `replace`: with ids CP1-T1 and CP1-T10 on one line, a prefix
            # replace would leave "a linked test0 failed"
            reasons = ["a linked test" + r[len(cid):] if cid and (r == cid or r.startswith(cid + " ")) else r
                       for r in reasons]
    held = "; ".join(reasons) or "not judged"
    return (f"Accepted by {who}. What held it: {held}. Their reason: "
            f"{' '.join(str(a.get('reason') or '').split())}")


def _objective_fill_ins(obj: dict) -> list[str]:
    """Every objective part that still starts with the spec draft's placeholder (specsrc.FILL_IN_PREFIX,
    e.g. 'FILL IN: who will use this?') instead of a real answer, named so the planner or user must fill it in
    before the plan can be submitted. A draft never guesses an audience from a story's title or invents one;
    this is what catches it if one slips through unfilled."""
    out = []
    for key in ("users", "goal"):
        v = str(obj.get(key) or "")
        if v.startswith(specsrc.FILL_IN_PREFIX):
            out.append(f"objective.{key}: still the draft placeholder ({v!r}) — fill it in before submitting")
    for key in ("done_means", "out_of_scope"):
        v = obj.get(key)
        if not isinstance(v, list):
            continue  # objective_problems already reports the invalid shape
        for i, x in enumerate(v):
            if str(x or "").startswith(specsrc.FILL_IN_PREFIX):
                out.append(f"objective.{key}[{i}]: still the draft placeholder ({x!r}) — fill it in before submitting")
    return out


REQUIRED_CP_FIELDS = ["id", "title", "summary", "done_when", "gates"]


def validate_plan(plan: dict) -> list[str]:
    errs = []
    if not isinstance(plan, dict):
        return ["checkpoints.json must be an object"]
    cps = plan.get("checkpoints")
    if not isinstance(cps, list) or not cps:
        return ["checkpoints.json needs a non-empty 'checkpoints' array"]
    seen = set()
    for i, cp in enumerate(cps):
        tag = cp.get("id", f"#{i}")
        for f in REQUIRED_CP_FIELDS:
            if f not in cp:
                errs.append(f"{tag}: missing '{f}'")
        if cp.get("id") in seen:
            errs.append(f"{tag}: duplicate id")
        seen.add(cp.get("id"))
        if not re.fullmatch(r"CP\d+", str(cp.get("id", ""))):
            errs.append(f"{tag}: id must look like CP1, CP2, ...")
        title = str(cp.get("title", ""))
        if len(title.split()) > 8:
            errs.append(f"{tag}: title should be a few words (≤8), got {len(title.split())}")
        g = cp.get("gates", {})
        if not isinstance(g, dict):
            errs.append(f"{tag}: gates must be an object")
            continue
        if g.get("adversarial") is not True:
            errs.append(f"{tag}: adversarial gate cannot be skipped")
        if not g.get("behavior") and not g.get("ui"):
            errs.append(f"{tag}: at least one of behavior/ui gates must be on")
        if g.get("behavior") is False and not cp.get("behavior_skip_reason"):
            errs.append(f"{tag}: behavior gate off requires 'behavior_skip_reason'")
        if g.get("ui"):
            if not cp.get("ui_scope"):
                errs.append(f"{tag}: ui gate on requires 'ui_scope' (what the reviewer may judge)")
            if not cp.get("ui_states"):
                errs.append(f"{tag}: ui gate on requires at least one entry in 'ui_states'")
        if g.get("behavior"):
            t = cp.get("tests") or {}
            if not t.get("command"):
                errs.append(f"{tag}: behavior gate on requires tests.command")
            if "report" in t and t["report"] not in ("junit", "json", "none"):
                errs.append(f"{tag}: tests.report must be junit, json or none")
            if t.get("report") == "none" and not str(t.get("report_reason") or "").strip():
                errs.append(f"{tag}: tests.report none requires tests.report_reason")
        for dep in cp.get("depends_on", []) or []:
            if dep not in seen:
                errs.append(f"{tag}: depends_on {dep} must refer to an EARLIER checkpoint")
        if cp.get("risk", "normal") not in ("low", "normal", "high"):
            errs.append(f"{tag}: risk must be low, normal or high")
        if cp.get("reviewers") is not None and not (isinstance(cp["reviewers"], list) and cp["reviewers"]):
            errs.append(f"{tag}: reviewers, if set, must be a non-empty list of review slots "
                        "(an id, or a list of ids in order of preference)")
        if not isinstance(cp.get("done_when"), list) or not cp.get("done_when"):
            errs.append(f"{tag}: done_when must be a non-empty list of plain-language criteria")
    return errs


def risk_reason_problems(checkpoints) -> list[str]:
    """CP1: a 'high'-risk checkpoint must say which users could be harmed and how. Checked only where a
    checkpoint is newly registered — `cmd_plan_submit` for every checkpoint in a plan, `cmd_plan_extend` for only
    the ones it appends — so an already-approved plan's existing high-risk checkpoint, built before this rule
    existed, keeps working untouched."""
    return [f"{cp.get('id', '?')}: risk \"high\" needs risk_reason naming which users could be harmed and how"
            for cp in checkpoints if cp.get("risk") == "high" and not str(cp.get("risk_reason") or "").strip()]


def cp_by_id(plan, cp_id):
    for cp in plan.get("checkpoints", []):
        if cp["id"] == cp_id:
            return cp
    die(f"Unknown checkpoint {cp_id}")


def test_plan(ctx: Ctx, cp_id: str):
    return read_json(ctx.run_dir() / "tests" / f"{cp_id}.json")


def new_cp_state(cp):
    g = cp.get("gates", {})
    gates = {}
    for name in ["behavior", "ui", "adversarial"]:
        gates[name] = {"required": bool(g.get(name)), "status": "pending" if g.get(name) else "skipped",
                       "attempts": 0}
    gates["human"] = {"required": False, "status": "pending", "attempts": 0}
    return {"status": "pending", "step": "tests", "gates": gates, "started_at": None,
            "completed_at": None, "commit": None}


# --------------------------------------------------------------------------- next action

MERGED_FIRST = ("A merge of main landed in this lane that Ratchet has not checked yet. Run ratchet.py merged first: "
                "it re-runs the earlier steps' tests on the merged code and keeps main's changes out of this step's "
                "review. Nothing was changed.")


SECOND_MERGE = ("An earlier merge of main in this step was resolved by hand, and that resolution is still waiting for "
                "this step's review, so a second merge cannot be accepted yet.")


def _same_commit(short, full) -> bool:
    return bool(short) and bool(full) and str(full).startswith(str(short))


def _fast_forwarded(g, last, ref, since=None):
    """The short id HEAD stood at before a `git merge` / `git pull` of this run fast-forwarded it (no merge commit),
    else "". Read from HEAD's reflog, newest first, back to the commit the last finished step or accepted merge
    made, or to the commit whose tree is the step's starting tree (`ref`), or to a reflog entry that was made before
    the run was created (`since`, a unix time; the entry's own time, which is when HEAD moved, never a commit's date:
    main's tip is often older than the run). The entry's own text tells a merge or pull fast-forward from anything
    else. The oldest fast-forward in that stretch wins. None when the reflog cannot be read (the caller then flags,
    the safe side)."""
    r = g("log", "-g", "--date=unix", "--format=%H%x09%T%x09%gs%x09%gd", "HEAD")
    log = r.stdout.splitlines()
    if r.returncode != 0 or not log:
        return None
    old = ""
    for i, line in enumerate(log):
        h, tree, subj, sel = (line.split("\t", 3) + ["", "", ""])[:4]
        when = re.search(r"@\{(\d+)\}$", sel)
        if _same_commit(last and last.get("commit"), h) or tree == ref or (
                since is not None and when and int(when.group(1)) < since):
            break
        if subj.endswith(": Fast-forward") and subj.startswith(("merge", "pull")) and i + 1 < len(log):
            old = log[i + 1].split("\t")[0][:7]
    return old


def _merge_unaccepted(ctx: Ctx, st: dict) -> str:
    """The refusal text when HEAD holds main's changes that `merged` has not accepted, else "". Either HEAD is a merge
    commit made during this run (not the last commit a step finished or `merged` accepted), or a fast-forward of this
    run left HEAD on main's commits with no merge commit; and in both cases HEAD's tree differs from the step's
    starting tree in something added, changed or removed outside the run folder (a removed git-ignored file is left
    out: it is what a file named in fingerprint_include looks like). A lane that never merges gets "". Any doubt
    gets ""."""
    try:
        cur = st.get("current")
        ref = ((st.get("checkpoints") or {}).get(cur) or {}).get("base_tree") if cur else None
        if st.get("phase") != "building" or not ref:
            return ""
        g = lambda *a: subprocess.run(["git", *a], cwd=ctx.root, capture_output=True, text=True, timeout=30)
        parts = g("rev-list", "--parents", "-n", "1", "HEAD").stdout.split()
        if len(parts) not in (2, 3):
            return ""
        last = next((e for e in reversed(st.get("history") or [])
                     if e.get("event") in ("checkpoint_complete", "merged_main")), None)
        if _same_commit(last and last.get("commit"), parts[0]):
            return ""
        old = ""
        if len(parts) == 3:
            made = _dt.datetime.fromisoformat(g("show", "-s", "--format=%cI", "HEAD").stdout.strip())
            if made < _dt.datetime.fromisoformat(st["created_at"]) - _dt.timedelta(seconds=2):
                return ""
        else:
            old = _fast_forwarded(g, last, ref, int(_dt.datetime.fromisoformat(st["created_at"]).timestamp()))
            if old == "":
                return ""
        prefix = g("rev-parse", "--show-prefix").stdout.strip() + RATCHET_DIR + "/"
        top = g("rev-parse", "--show-toplevel").stdout.strip()
        diff = g("diff-tree", "-r", "--no-renames", "--name-only", "--diff-filter=ACMRT", ref, f"{parts[0]}^{{tree}}")
        gone = g("diff-tree", "-r", "--no-renames", "--name-only", "--diff-filter=D", ref, f"{parts[0]}^{{tree}}")
        if diff.returncode != 0 or gone.returncode != 0:
            return ""
        changed = any(f and not f.startswith(prefix) for f in diff.stdout.split("\n"))
        names = [f for f in gone.stdout.split("\n") if f and not f.startswith(prefix)]
        start = old or (parts[1] if len(parts) == 3 else "") or (last or {}).get("commit") or ""
        if names:   # a path that was not in the commit HEAD stood at when the step began was only uncommitted then
            tracked = g("ls-tree", "-r", "--full-tree", "--name-only", start) if start else None
            there = set(tracked.stdout.split("\n")) if tracked is not None and tracked.returncode == 0 else set()
            names = [f for f in names if f in there]
        if names and not changed:
            ig = subprocess.run(["git", "check-ignore", "-z", "--stdin"], cwd=top, capture_output=True, text=True,
                                input="\0".join(names) + "\0", timeout=30)
            changed = bool(set(names) - set(ig.stdout.split("\0")))
        if not changed:
            return ""
        if old is None:
            return MERGED_FIRST
        if old:
            return (f"Main was fast-forwarded into this lane (HEAD moved on from {old} with no merge commit), so "
                    "Ratchet cannot tell main's changes from this step's own and its reviewers would see them as "
                    f"the step's work. Undo it with `git reset --keep {old}`, merge again with `git merge --no-ff "
                    "main` (use `git fetch`, then `git merge --no-ff <branch>`, instead of `git pull`), then run "
                    "ratchet.py merged. Nothing was changed.")
        if last and last["event"] == "merged_main" and last.get("by_hand"):
            return (SECOND_MERGE + f" Undo this second merge with `git reset --keep {parts[1][:7]}` (its first "
                    "parent), finish this step through complete, then merge main again. Nothing was changed.")
        return MERGED_FIRST
    except Exception:
        return ""


def next_action(ctx: Ctx, st=None, compute_accept_note: bool = True) -> dict:
    """`compute_accept_note=False` skips `_blocked_accept_note` (and the working-tree fingerprint it can trigger
    via `_code_changed_since_round`) for callers that never read `accept_note` from the result: the Stop hook
    (`decide_stop`, which only reads `stop_ok`) and the viewer (`viewer_data`, whose `next` the UI never shows
    `accept_note` from). `ratchet.py next` and `status --json`, the only places this line is ever printed, always
    pass the default so their behavior is unchanged."""
    st = st or ctx.state()
    phase = st["phase"]
    if phase == "planning":
        missing = []
        if not (ctx.run_dir() / "app-scout.json").exists():
            missing.append("app scout report (.ratchet/runs/<slug>/app-scout.json) from ratchet-app-scout")
        if not (ctx.run_dir() / "checkpoints.json").exists():
            missing.append("checkpoints.json from ratchet-checkpoint-planner")
        if missing:
            return {"phase": phase, "action": "Spawn in parallel: " + "; ".join(missing),
                    "stop_ok": False}
        missing_tp = [c["id"] for c in (ctx.plan() or {}).get("checkpoints", [])
                      if c.get("gates", {}).get("behavior") and not test_plan(ctx, c["id"])]
        if missing_tp:
            return {"phase": phase, "action": "Spawn ratchet-test-planner for " + ", ".join(missing_tp)
                    + " (in parallel). When every test plan exists, run ratchet.py plan-submit.", "stop_ok": False}
        return {"phase": phase, "action": "Run ratchet.py plan-submit (validates the plan and test plans, "
                "prints the viewer link), then show the user the plan.", "stop_ok": False}
    if phase == "awaiting_plan_approval":
        missing = [c["id"] for c in ctx.plan()["checkpoints"]
                   if c["gates"].get("behavior") and not test_plan(ctx, c["id"])]
        extra = (f" (test plans still missing for {', '.join(missing)} — spawn ratchet-test-planner, then run "
                 "ratchet.py plan-submit again)") if missing else ""
        asked = (st.get("pending") or {}).get("action") == "approve-plan"
        how = _director_next(ctx, st) or (
              "The approval question is printed: wait for the user's reply. Run ratchet.py approve-plan only if "
               "their first reply after it is one of the listed yes replies; otherwise answer them or make their "
               "change, then print the question again (ratchet.py ask approve-plan)." if asked else
               "Waiting for the user to approve the plan. " + _after_next(PLAN_ASK_NEXT))
        return {"phase": phase, "action": how + extra, "stop_ok": not missing}
    if phase in ("awaiting_checkpoint_review", "awaiting_final_review"):
        blockers = _finish_blockers(ctx, st) if _finish_pending(st) else []
        if blockers:  # CP4: the finish is held; the agent is never told to put the approval question
            return {"phase": phase, "action": "\n".join(_finish_block_lines(ctx, st, blockers)), "stop_ok": True}
        changed = _finish_integrity_lines(ctx, st) if _finish_pending(st) else []
        if changed:  # CP4: a checkpoint or test plan changed after approval; approve-changes first, no approval question
            return {"phase": phase, "action": "\n".join(changed), "stop_ok": True}
        asked = (st.get("pending") or {}).get("action") == "human-approve"
        how = _director_next(ctx, st) or (
              "The review question is printed: wait for the user's reply. Run ratchet.py human-approve only if "
               "their first reply after it is one of the listed yes replies; if they ask for changes, run "
               "ratchet.py feedback." if asked else "Waiting for the human to review. " + REVIEW_ASK_NEXT)
        return {"phase": phase, "action": how, "stop_ok": True}
    if phase == "planning_feedback":
        return {"phase": phase, "action": "Spawn ratchet-checkpoint-planner in EXTEND mode with the human's feedback "
                "(append new checkpoints, never edit completed ones), ratchet-test-planner for each new checkpoint, "
                "then run ratchet.py plan-extend", "stop_ok": False}
    if phase in ("blocked", "paused", "done", "cancelled"):
        na = {"phase": phase, "action": st.get("blocked_reason") or phase, "stop_ok": True}
        if phase == "blocked":
            director = _director_next(ctx, st)
            if director:  # an enrolled lane: the next action is the director's, named here, never a chat question
                na["action"] = f"{na['action']}. {director}"
            na["options"] = blocked_options(st)
            na["reason_plain"] = plain_reason(st.get("blocked_reason"))
            note = _blocked_accept_note(ctx, st) if compute_accept_note else None
            if note:
                na["accept_note"] = note
        return na

    # building
    cur = st.get("current")
    if not cur:
        return {"phase": phase, "action": "No current checkpoint — run ratchet.py status", "stop_ok": False}
    cps = st["checkpoints"][cur]
    step = cps["step"]
    plan = ctx.plan()
    cp = cp_by_id(plan, cur)
    msgs = {
        "tests": f"{cur}: spawn ratchet-test-writer to write the planned tests (tagged [{cur}-Txx]) "
                 f"into {', '.join(cp.get('tests', {}).get('files', []) or ['the files in tests.files'])}, "
                 f"then run: ratchet.py tests-written {cur}",
        "red": f"{cur}: run ratchet.py red {cur}  (tests must FAIL before implementation)",
        "implement": f"{cur}: spawn ratchet-implementer for this checkpoint only, then run: ratchet.py implemented {cur}",
        "behavior": f"{cur}: run ratchet.py behavior {cur}. If it fails, spawn ratchet-implementer with the failure log, then re-run.",
        "ui": f"{cur}: run the ratchet-ui-compare skill (capture matched states → 2 isolated reviewers → combined.json), "
              f"then ratchet.py ui-record {cur} --review <combined.json>",
        "adversarial": f"{cur}: run the ratchet-adversarial-loop skill (adversary review → ratchet.py adv-record → fixer → repeat)",
        "complete": f"{cur}: run ratchet.py complete {cur}",
    }
    gr = cp.get("guardrail") or {}
    if step == "tests" and gr.get("high_risk") and not gr.get("strengthen"):
        msgs["tests"] = (f"{cur}: first spawn ratchet-variant-writer with ONLY the kind '{gr['kind']}', its why and the "
                         f"output of `ratchet.py occurrences {gr['kind']}` (never the check) to write disguised bad "
                         f"variants in {gr['variants_dir']}/bad and look-alike good code in {gr['variants_dir']}/good; "
                         "then " + msgs["tests"].split(": ", 1)[1])
    na = {"phase": phase, "checkpoint": cur, "step": step, "action": msgs.get(step, step), "stop_ok": False}
    held = _merge_unaccepted(ctx, st) if step == "tests" else ""
    if held:
        na["action"] = "First: " + held + " Then: " + na["action"]
    reps = repeat_candidates(ctx, st) if approval_mode(ctx) != "director" else []
    if reps:
        na["guardrail_candidates"] = reps
        na["action"] = (f"First offer the user a guardrail for the repeated finding '{reps[0]['kind']}' (ratchet.py ask "
                        f"choice --guardrail ...; see the orchestrator skill). Then: " + na["action"])
    return na


def _director_next(ctx: Ctx, st) -> str | None:
    """In a director-enrolled lane, what the lane waits for at a pause (plan approval, a review, a block), naming
    the director's command: the one-step `director-sign <action> ... --apply` for a routine approval, or the token
    the lane applies with `--director-token`. None in a lane the developer approves, or in any other phase. Used by
    `next`, `status` and `status --json` so an enrolled lane's agent is never told to ask the user."""
    if approval_mode(ctx) != "director":
        return None
    phase = st.get("phase")
    eng = f"ratchet.py --root {ctx.root}"
    tail = (" A chat reply approves nothing here, so put no question in chat; end your turn saying what you are "
            "waiting for.")
    if phase == "awaiting_plan_approval":
        return (f"Waiting for the director to approve the plan: the director runs `{eng} director-sign approve-plan` "
                "and the token is applied with `ratchet.py approve-plan --director-token <t>`." + tail)
    if phase in ("awaiting_checkpoint_review", "awaiting_final_review"):
        return (f"Waiting for the director to review: the director runs `{eng} director-sign human-approve` (applied "
                "with `ratchet.py human-approve --director-token <t>`), or `director-sign feedback` for changes "
                "(applied with `ratchet.py feedback --director-token <t>`)." + tail)
    if phase == "blocked":
        cur = st.get("current")
        cps = ((st.get("checkpoints") or {}).get(cur) or {}) if cur else {}
        g = (cps.get("gates") or {}).get("adversarial") or {}
        ways = []
        if cur and _adv_block_kind(st, cur) in ("own", "run_wide"):
            ways.append(f"accept the open findings with `{_director_apply_cmd(ctx, 'accept-finding', cur)}`")
            if not g.get("cap_raised_to"):
                ways.append(f"raise this step's review limit once with `{_director_apply_cmd(ctx, 'raise-limit', cur)}`")
        ways.append(f"resume the run with `{eng} director-sign human-approve` (applied with `ratchet.py human-approve "
                    "--director-token <t>`), after a lettered option if one is wanted (`ratchet.py ask choice "
                    f"--options ...` here, then `{_director_apply_cmd(ctx, 'choice')}`)")
        return "Waiting for the director, who can " + "; or ".join(ways) + "." + tail
    return None


# --------------------------------------------------------------------------- plain language

STEP_PLAIN = {"tests": "writing the tests", "red": "checking the new tests fail before any code exists",
              "implement": "building it", "behavior": "running the tests", "ui": "checking how it looks",
              "adversarial": "getting a second opinion", "complete": "wrapping up"}


PHASE_PLAIN = {"planning": "planning", "awaiting_plan_approval": "waiting for your approval of the plan",
               "building": "building", "awaiting_checkpoint_review": "waiting for your review",
               "awaiting_final_review": "waiting for your final review", "planning_feedback": "updating the plan",
               "blocked": "stuck, needs your decision", "paused": "paused", "done": "done", "cancelled": "cancelled"}


def plain_reason(reason):
    """The block reason in plain words for the user. Unknown reasons pass through unchanged; the raw text stays
    in `status --json` (blocked_reason)."""
    if not reason:
        return reason
    m = re.match(r"(CP\d+): behavior gate failed (\d+) times", reason)
    if m:
        return f"The tests for {m.group(1)} still fail after {m.group(2)} tries."
    m = re.match(r"(CP\d+): UI gate failed (\d+) rounds", reason)
    if m:
        return f"The look-and-feel check for {m.group(1)} still is not passing after {m.group(2)} rounds."
    m = re.match(r"(CP\d+): adversarial review still has (\d+) finding\(s\) after (\d+) rounds", reason)
    if m:
        return (f"The reviewers still have {m.group(2)} open concern(s) about {m.group(1)} after "
                f"{m.group(3)} rounds of fixes, which is the limit.")
    m = re.match(r"(CP\d+): (\d+) adversarial rounds used without approval", reason)
    if m:
        return f"The reviewers have not signed off on {m.group(1)} after {m.group(2)} rounds, which is the limit."
    m = re.match(r"Run-wide adversarial round cap reached \((\d+)/(\d+)\)", reason)
    if m:
        return f"The reviewers have used all the review rounds allowed for this run ({m.group(1)} of {m.group(2)})."
    if reason.startswith("The agent tried to stop"):
        return "The work kept stopping without making progress, so it was halted for you to look at."
    return reason


def _adv_base_cap(cfg, g) -> int:
    """The round limit before any check-in round-limit grant: this step's raised cap, once the user has raised
    it (CP1's one-time `raise-limit`, recorded as `gates.adversarial.cap_raised_to`), else the run's configured
    `max_adversarial_rounds`. A later `config --set max_adversarial_rounds=...` only ever changes the fallback,
    so it never lifts a cap this step already has recorded. Kept separate from `_adv_round_cap` (which also adds
    `round_limit_grants`) so raising the limit always adds exactly one round on top of the CONFIGURED cap,
    whichever order a raise and a round-limit grant happen in, instead of compounding on top of each other."""
    return g.get("cap_raised_to") or cfg["max_adversarial_rounds"]


def _adv_round_cap(cfg, cps) -> int:
    """The round limit THIS checkpoint's adversarial gate blocks at: `_adv_base_cap` plus however many one-time
    round-limit grants this step has used (`round_limit_grants`: at most one from `check-in --decision simplify`
    and one from `check-in --decision change`, each reusing check-in's own simplify record to hand back exactly
    one more round at the step's own round-limit block, never more than once each — see `cmd_check_in`)."""
    g = (cps.get("gates") or {}).get("adversarial") or {}
    return _adv_base_cap(cfg, g) + int(g.get("round_limit_grants", 0))


def blocked_options(st) -> list:
    """2-4 lettered choices for the user, fitted to why the run is blocked. Offered by the agent, not typed.
    Only offers things that can work. Accepting an open finding is never one of these: it is never a lettered
    pick (so a pick followed by `human-approve` can never stand in for the user's own `accept: <reason>` reply).
    When that is a real option here, `next`/`status` add it as its own plain line instead (see
    `_blocked_accept_note`). At a step's own round-limit block the menu leads with simplify, then change the
    step, then stop; raising the limit (CP1: at most once per step, ever) comes last, and only while this step's
    own `cap_raised_to` (on the blocked checkpoint's adversarial gate) is still unset. The older, run-wide cap
    (a different mechanism: a config change plus `approve-changes`, not scoped to one step) keeps offering raise
    every time, just reordered the same way."""
    reason = st.get("blocked_reason")
    r = (reason or "").lower()
    cur = st.get("current")
    cps = (st.get("checkpoints") or {}).get(cur) if cur else None
    raise_used = bool(((cps or {}).get("gates") or {}).get("adversarial", {}).get("cap_raised_to")) if cps else False
    if "round cap" in r or "run-wide" in r:
        texts = ["Simplify the step so the reviewers can approve it in the rounds already allowed.",
                 "Stop here and keep what is already finished.",
                 "Raise the review limit so the reviewers can keep going."]
    elif "rounds used" in r or ("adversarial" in r and re.search(r"after \d+ rounds", r)):
        texts = ["Simplify the step, then let the reviewers look at it once more.",
                 "Change the step so the review notes no longer apply.",
                 "Stop here and keep what is already finished."]
        if not raise_used:
            texts.append("Raise the review limit so the reviewers can keep going.")
    elif "behavior gate failed" in r:
        texts = ["Try again with a different approach.", "Change or revise this step (its tests or its scope).",
                 "Stop here and keep what is already finished."]
    elif "adversarial" in r or "review" in r:
        texts = ["Change the step so the review notes no longer apply.",
                 "Stop here and keep what is already finished."]
    else:
        texts = ["Try again.", "Change the plan for this step.", "Stop here and keep what is already finished."]
    return [{"letter": "ABCD"[i], "text": t} for i, t in enumerate(texts)]


ACCEPT_NOTE_CACHE_NAME = ".accept-note-cache.json"  # see _cached_code_changed_since_round: a performance cache only


def _blocked_accept_note(ctx, st) -> str | None:
    """One plain line (never a lettered option) for `next`/`status` when the run is blocked on an adversarial
    round limit, per-checkpoint or run-wide, and the current checkpoint's last recorded round still has open
    findings: either the user can accept them with their own reason (`ask accept-finding` + their own
    `accept: <reason>` reply, never a lettered pick or `human-approve`, which never accepts anything), or, when
    the code changed since that round, those findings need a fresh review round instead (point at raising the
    limit, option A). None when the block is some other kind, there is no current checkpoint, no round was ever
    recorded for it, or the recorded round simply has nothing open (an approved round, or one already fully
    accepted): a presence check against the round's own open findings always runs FIRST, before the code-change
    check, so neither line is ever printed about findings that do not exist."""
    if st.get("phase") != "blocked":
        return None
    cur = st.get("current")
    cps = (st.get("checkpoints") or {}).get(cur) if cur else None
    if not cur or cps is None or _adv_block_kind(st, cur) not in ("own", "run_wide"):
        return None
    rnd = cps.get("adv_round")
    if not rnd or not _adv_open_findings(ctx, cur, rnd, cps):
        return None
    director = approval_mode(ctx) == "director"
    if _cached_code_changed_since_round(ctx, st, rnd):
        if director:
            return ("The last fix changed the code, so these findings need a fresh look: the director raises the "
                    f"limit for one more round with `{_director_apply_cmd(ctx, 'raise-limit', cur)}`.")
        return ("The last fix changed the code, so these findings need a fresh look; raise the limit (A) for one "
                "more round.")
    if director:
        return (f"The director can accept the open findings with `{_director_apply_cmd(ctx, 'accept-finding', cur)}`; "
                "a chat reply accepts nothing here.")
    return ("You can also accept open findings yourself: the agent asks with `ask accept-finding`, and only "
            "your reply `accept: <reason>` closes them.")


def _cached_code_changed_since_round(ctx, st, rnd) -> bool:
    """Same answer as `_code_changed_since_round`, but skips its working-tree fingerprint (a `git add -A` into a
    fresh temp index, re-hashing every file) when nothing that could change it has happened since the last time
    THIS exact round was checked. Only `_blocked_accept_note` calls this: while a run sits `blocked` waiting on
    the user, the Stop hook re-runs `next_action` on every turn end, each a fresh process with no memory of the
    last one, so without this the fingerprint was being recomputed on every single stop. The cache key is the
    round's own number and fingerprint plus state.json's own mtime: every command that could add a new round or
    change the code also saves state (standards #12, the one atomic write), so a cache entry still matching all
    three was computed after the same state.json this call is reading, and the working tree cannot have changed
    code Ratchet would recognise since then without some command also updating one of those three. A mismatch
    (a new/replaced round, or state.json touched since) always recomputes rather than trust a stale entry; a
    write race between two callers only costs an extra recompute, never a wrong answer. `ask accept-finding` and
    `accept-finding` never call this cached wrapper: they call `_code_changed_since_round` directly, uncached,
    for their own authoritative, must-be-fresh refusal check."""
    slug = st.get("slug")
    try:
        state_mtime = ctx.state_path(slug).stat().st_mtime
    except OSError:
        state_mtime = None
    key = {"round": rnd.get("round"), "fingerprint": rnd.get("fingerprint"), "state_mtime": state_mtime}
    cache_path = ctx.run_dir(slug) / ACCEPT_NOTE_CACHE_NAME
    cached, why = _read_record(cache_path, missing=None)
    if why is None and isinstance(cached, dict) and all(cached.get(k) == v for k, v in key.items()):
        return bool(cached.get("changed"))
    changed = _code_changed_since_round(ctx, rnd)
    try:
        _write_record(cache_path, dict(key, changed=changed))
    except OSError:
        pass  # a performance cache only: a failed write just means the next call recomputes too
    return changed


def plain_now(ctx: Ctx, st, plan=None) -> str:
    """One plain sentence about what is happening now (no phase ids, no commands). At the finish pause
    (`_finish_pending`) while the finish is held (`_finish_held`, CP4: an unproven line, or a checkpoint or test
    plan edited after approval) it says so instead of inviting an approval, so the sentence the agent relays never
    contradicts the block printed under it."""
    phase = st.get("phase")
    plan = plan if plan is not None else (ctx.plan() or {})
    if phase in ("awaiting_final_review", "awaiting_checkpoint_review") and _finish_pending(st):
        held = _finish_blockers(ctx, st)
        if held:
            n = len(held)
            return (f"Everything is built, but {n} done-means line{'s are' if n != 1 else ' is'} unproven, so the "
                    "run cannot be approved as done yet.")
        if _finish_integrity_lines(ctx, st):
            return ("Everything is built, but a checkpoint or test plan changed after the plan was approved, so the "
                    "run cannot be approved as done yet (the change must be confirmed or undone first).")
    # c.get("id", f"#{i}"): a checkpoint missing "id" must not crash `status`; validate_plan is what names it.
    titles = {c.get("id", f"#{i}"): c.get("title", c.get("id", f"#{i}"))
              for i, c in enumerate(plan.get("checkpoints", []))}
    fixed = {
        "planning": "Planning: splitting the feature into steps.",
        "awaiting_plan_approval": "The plan is ready and waiting for your approval. Say yes to start building, "
                                  "or tell me what to change.",
        "awaiting_final_review": "Everything is built. Please look it over, then approve or tell me what should change.",
        "planning_feedback": "Turning your feedback into new steps.",
        "paused": "The work is paused until you say to continue.",
        "cancelled": "This run was cancelled.",
        "done": "Finished.",
        "blocked": "The work is stuck and needs your decision.",
    }
    if phase in fixed:
        return fixed[phase]
    if phase == "awaiting_checkpoint_review":
        t = titles.get(st.get("review_target"), "the last step")
        return f"\"{t}\" is ready for you to review. Try it, then approve or tell me what should change."
    cur = st.get("current")
    cps = st.get("checkpoints") or {}
    if not cur or cur not in cps:
        return "Getting the next step ready."
    n = list(cps).index(cur) + 1
    return (f"Working on step {n} of {len(cps)}, \"{titles.get(cur, cur)}\": "
            + STEP_PLAIN.get(cps[cur].get("step"), "in progress") + ".")


HOOK_EVENT_PLAIN = {"guard": "the check that runs before each edit or command",
                    "stop": "the check that runs when the agent finishes a turn",
                    "prompt": "the hook that records your replies"}


def _plain_ago(at) -> str:
    t = _parse_iso(at)
    secs = (_dt.datetime.now(_dt.timezone.utc) - t).total_seconds() if t else 0
    if secs < 60:
        return "less than a minute ago"
    if secs < 3600:
        n = int(secs // 60)
        return f"{n} minute{'s' if n != 1 else ''} ago"
    n = int(secs // 3600)
    return f"{n} hour{'s' if n != 1 else ''} ago"


def _plain_hook_tail(event: str) -> str:
    return ("so Ratchet's checks are not enforced right now" if event in ("guard", "stop")
            else "so your replies may not be recorded")


def plain_hook_errors(root: Path, host: str) -> list:
    """Plain lines for `status` about hook crashes: the last 24 hours of the log, plus every hook that has not run
    cleanly since its last crash, each named by its own event and crash time (none when there are none). Never shows
    the raw error text: that is in `status --json` / `next` (`hook_errors`) and `doctor` for the agent."""
    errs = read_hook_errors(root, host)
    broken = broken_hooks(root, host, errors=errs)  # newest first, one entry per (host, event)
    ask = "Ask the agent to run the doctor check and fix it."
    lines, last, others, asked = [], None, broken, False
    if errs:
        last = errs[0]
        what = HOOK_EVENT_PLAIN.get(last["event"], "one of its checks")
        if len(errs) == 1:
            lines.append(f"A Ratchet safety hook failed {_plain_ago(last['at'])} ({what}), so it let that action "
                         "through without checking it.")
        else:
            lines.append(f"Ratchet safety hooks failed {len(errs)} times in the last day, most recently "
                         f"{_plain_ago(last['at'])} ({what}), so those actions went through without being checked.")
        last_broken = any((b["host"], b["event"]) == (last["host"], last["event"]) for b in broken)
        others = [b for b in broken if (b["host"], b["event"]) != (last["host"], last["event"])
                  and not (last_broken and b["event"] == last["event"])]
        if last_broken:
            lines.append(f"It has not run cleanly since, {_plain_hook_tail(last['event'])}. {ask}")
            asked = True
        elif not others:
            lines.append("It has run cleanly since then. If it happens again, ask the agent to run the doctor check.")
        else:
            lines.append("It has run cleanly since then.")
    seen = set()
    for b in others:  # a different hook that is still broken: name it, and its own crash time
        if b["event"] in seen:
            continue  # the same check on another host (unknown-host view): one line is enough
        seen.add(b["event"])
        lines.append(f"{'Separately, a' if last else 'A'} Ratchet safety hook failed {_plain_ago(b['at'])} "
                     f"({HOOK_EVENT_PLAIN.get(b['event'], 'one of its checks')}) and has not run cleanly since, "
                     f"{_plain_hook_tail(b['event'])}.")
    if seen and not asked:
        lines[-1] += " " + ask
    if hook_crash_state_unreadable(root):
        lines.append("Ratchet cannot read its record of safety hook failures, so it counts its checks as not "
                     "enforced right now. " + ask)
    elif hook_crash_state_problem(root):
        lines.append("Ratchet cannot save its record of safety hook failures, so a failed check could go unnoticed "
                     "and it counts its checks as not enforced right now. " + ask)
    return lines


def exit_code_only_line(cp):
    """A plain line when a step's tests are checked by exit code only: its plan says it writes no per-test report
    (`tests.report` none), or the plan does not say (no `report` key, e.g. a plan from before reports existed)."""
    t = (cp or {}).get("tests") or {}
    if not ((cp or {}).get("gates") or {}).get("behavior") or t.get("report") in ("junit", "json"):
        return None
    if t.get("report") == "none":
        return (f"{cp['id']} has no per-test report, so its tests are checked by exit code only. "
                f"Reason: {t.get('report_reason')}")
    return (f"{cp['id']}'s plan does not say how its tests report each result, so they are checked by exit code "
            "only.")


def exit_code_only_note(plan, st):
    """exit_code_only_line for the step being built now, or None."""
    if st.get("phase") != "building":
        return None
    return exit_code_only_line(next((c for c in (plan or {}).get("checkpoints") or []
                                     if c.get("id") == st.get("current")), None))


QUESTION_WORDS = {"approve-plan": "the plan", "human-approve": "an approval", "approve-changes": "changes to the approved plan files",
                  "cancel": "cancelling the run", "set-review": "how often to review", "claim": "continuing the run in this chat",
                  "hooks-waive": "building without the hooks", "ui-respec": "a change to the UI check",
                  "choice": "a choice between options", "accept-finding": "accepting a review finding as a known limit",
                  "raise-limit": "raising the review limit by one round",
                  "accept-line": "accepting an unproven done-means line"}


GATING_QUESTIONS = ("approve-plan", "human-approve", "choice")  # while the run is at a pause or blocked
ALWAYS_GATING_QUESTIONS = ("accept-finding", "raise-limit", "accept-line")  # a blocked review round, or the held
                                                                               # finish (CP5), waits on them
GATING_PHASES = ("awaiting_plan_approval", "awaiting_checkpoint_review", "awaiting_final_review", "blocked",
                 "paused")
CARRY_ON_QUESTIONS = ("cancel", "set-review", "claim", "hooks-waive", "ui-respec", "choice")


def _question_waiter(ctx: Ctx, claim=False) -> str:
    """Who a waiting question is put to: 'director' in a director-enrolled lane, else 'user'. Read-only: unlike
    approval_mode it never exits and never writes a note, so a damaged enrollment file cannot break `status`; any
    problem reading it counts as enrolled ('director'). A claim has no director action (a director cannot sign
    it), so it is always put to the 'user'."""
    if claim:
        return "user"
    try:
        enr, why = _read_record(ctx.ratchet / "director.json", missing=None)
        if why is not None or enr:
            return "director"
        data, why = _read_record(_enrolled_path())
        if why is not None or data.get(str(ctx.root.resolve())):
            return "director"
        return "director" if ctx.config().get("approver", "human") == "director" else "user"
    except Exception:
        return "director"


def _question_answered(ctx: Ctx, st, p) -> bool:
    """The user has already replied in the question's own chat (the same recorded replies `ask` counts), so it is no
    longer waiting for an answer, whether or not the agent has acted on the reply yet. Read-only: a human log that
    can't be read or vouched for holds no reply."""
    try:
        return bool(_replies(ctx, st, p.get("asked_at"), p))
    except (Exception, SystemExit):
        return False


def waiting_question(ctx: Ctx, st):
    """The question that has been asked (`ratchet.py ask ...`) and not yet answered or withdrawn, or None. Read-only.
    A question asked in an earlier phase no longer applies (as in `_asked_reply`), so it is None. In a user lane a
    question the user has replied to is answered, so it is dropped even before the agent runs the command that
    clears `pending`; in a director lane a chat reply answers nothing, so the question shows until `pending`
    clears. `stops_run` says whether the run really waits for it: only the approval pauses, a blocked run's
    questions, the accept-a-finding / raise-the-limit questions of a blocked review round and the accept-a-line
    question of a held finish (CP5, `about` names its lines) do (True); the others
    (a review-frequency or cancel question, a building-phase choice...) leave a building run building (False);
    approve-changes and the like, and the carry-on kinds outside the building phase, are left unsaid (None)."""
    p = st.get("pending")
    if not isinstance(p, dict) or not p.get("action") or not p.get("asked_at"):
        return None
    if p.get("phase") and p["phase"] != st.get("phase"):
        return None
    if p.get("overtook"):  # printed as NOT ASKED: it never reached the user, and the question it replaced is gone too
        return None
    if p["action"] == "human-approve" and _finish_held(ctx, st):
        return None  # CP4: the finish is held, so a question asked before it was held no longer waits
    waiting_on = _question_waiter(ctx, p["action"] == "claim")
    if waiting_on == "user" and _question_answered(ctx, st, p):
        return None
    _m, _t = _pq(p)
    about = (_t or _m) if p["action"] in ("accept-finding", "raise-limit", "ui-respec") else None
    if p["action"] == "accept-line":
        about = _lines_word([int(x) for x in str(_t or "").split(",") if x.strip().isdigit()]) or None
    stops = None
    if p["action"] in ALWAYS_GATING_QUESTIONS or (p["action"] in GATING_QUESTIONS and st.get("phase") in GATING_PHASES):
        stops = True
    elif p["action"] in CARRY_ON_QUESTIONS and st.get("phase") == "building":
        stops = False
    return {"kind": p["action"], "since": p["asked_at"], "waiting_on": waiting_on, "about": about,
            "stops_run": stops}


def question_line(q):
    """The one plain-status line for a waiting question."""
    t = _dt.datetime.fromisoformat(q["since"]).astimezone(_dt.timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    who = "the director's" if q["waiting_on"] == "director" else "the user's"
    about = f" for {q['about']}" if q.get("about") else ""
    tail = {True: " The run will not move until it is answered.",
            False: " The run can carry on meanwhile."}.get(q.get("stops_run"), "")
    return (f"Waiting for {who} answer: a question about {QUESTION_WORDS.get(q['kind'], q['kind'])}{about} "
            f"was asked at {t}.{tail}")


def cmd_status_text(ctx: Ctx):
    st = ctx.state()
    plan = ctx.plan() or {"checkpoints": []}
    if _finish_pending(st):  # the final review, or the last step's review in `each` mode: the same table either way
        for line in _final_review_lines(ctx, st, plan):
            print(line)
        left = [f for c in (st.get("checkpoints") or {}).values() for f in left_for_later(c)]
        if left:
            print(f"{len(left)} finding(s) were left for later (never accepted or fixed): run `ratchet.py "
                  "deferred` to see them.")
        flaky_steps = [cid for cid, c in (st.get("checkpoints") or {}).items()
                       if any((g or {}).get("flaky") for g in (c.get("gates") or {}).values())
                       or c.get("regression_flaky")]
        if flaky_steps:
            print(f"Flaky (a test run failed once, then passed on an immediate automatic re-run): "
                  f"{', '.join(flaky_steps)}.")
        print("")
    sc_lines = _sc_block_lines(_sc_saved(ctx))  # CP6: the shortcut tables that ran (none: nothing is printed)
    if sc_lines:  # part of the final review at the finish pause; otherwise shown as it stands (stale if the code moved)
        for line in sc_lines:
            print(line)
        print("")
    cps = plan.get("checkpoints", [])
    total = len(cps)
    # c.get("id"): a checkpoint missing "id" (a malformed hand-edit) was never registered in state under any
    # key, so it is correctly treated as not done here, instead of crashing `status`.
    done = [c for c in cps if (st["checkpoints"].get(c.get("id")) or {}).get("status") == "done"]
    if not total:
        print("No plan yet.")
    elif len(done) == total:
        print(f"All {total} steps are done.")
    elif done:
        print(f"Step {len(done)} of {total} done: {done[-1].get('title', done[-1]['id'])}")
    else:
        print(f"Step 0 of {total} done. Not started yet.")
    print(f"Run: {st['slug']}  -  {st['feature']}")
    print(f"Phase: {PHASE_PLAIN.get(st.get('phase'), st.get('phase'))}")
    print(plain_now(ctx, st, plan))
    director = _director_next(ctx, st)
    if director:
        print(director)
    q = waiting_question(ctx, st)
    if q:
        print(question_line(q))
    if _finish_pending(st):
        # CP4: the finish is held while an approved done-means line is unproven (never for a plan approved before
        # this rule, which gets the plain note instead), or while a checkpoint or test plan changed after approval
        # (`_finish_integrity_lines`: the table would otherwise read links the user never approved). Printed after
        # the table and the step count, so the table's own lines stay as they are.
        blockers = _finish_blockers(ctx, st)
        for line in _finish_block_lines(ctx, st, blockers) if blockers else []:
            print(line)
        if blockers and not q:
            print("Nothing is waiting on a reply from the user for this: the approval question is not asked while a "
                  "line is unproven.")
        for line in _finish_integrity_lines(ctx, st):
            print(line)
        note = _finish_legacy_note(ctx, st) if not blockers else ""
        if note:
            print(note)
    cur = (st.get("checkpoints") or {}).get(st.get("current")) or {}
    if st.get("phase") == "building" and any(g.get("status") in ("stale", "invalid")
                                             for g in (cur.get("gates") or {}).values()):
        print("The code changed since the checks last passed, so they must be re-run.")
    ci_open = (cur.get("checkin") or {}).get("open")
    if ci_open:
        print(f"A check-in is open for {st.get('current')} (round {ci_open.get('round')}): run "
              f"`ratchet.py check-in {st.get('current')}` to see it, then `--decision simplify|stop` to resolve it.")
    note = exit_code_only_note(plan, st)
    if note:
        print(note)
    for line in _accepted_findings_lines(st):
        print(line)
    for line in _doc_edit_status_lines(st):
        print(line)
    for line in _small_fix_review_lines(st):
        print(line)
    for line in _fix_round_lines(st):
        print(line)
    for line in _docs_only_skip_lines(st):
        print(line)
    w = live_wait(st)
    if w:
        print(f"Waiting on: {w['reason']} (until {w['until'][:16].replace('T', ' ')} UTC).")
    for cid, c in (st.get("checkpoints") or {}).items():
        for gate, what in (("ui", "UI review"), ("adversarial", "review")):
            for line in ((c.get("gates") or {}).get(gate) or {}).get("unconfirmed") or []:
                print(f"{cid} {what} {line}.")
    if st.get("phase") == "blocked":
        print(f"Why: \"{plain_reason(st.get('blocked_reason')) or 'no reason was recorded'}\"")
        print("What would you like to do?")
        for o in blocked_options(st):
            print(f"  {o['letter']}) {o['text']}")
        note = _blocked_accept_note(ctx, st)
        if note:
            print(note)
    hs = hooks_view(ctx, st)
    if hs.get("waived"):
        print("Hooks were skipped at your request, so the checks are only advice.")
    for line in plain_hook_errors(ctx.root, hs.get("host", "unknown")):
        print(line)
    url = viewer_link(ctx)["url"]
    if url:
        print(f"Live view: {url}")


PLAIN_LENS = {"both": "code standards and bugs", "standards": "code standards", "correctness": "bugs and security"}
PLAIN_MODEL = {"inherit": "your session's model"}


def _plain_model(m) -> str:
    return PLAIN_MODEL.get(str(m), str(m)) if m else "its default model"


def plain_reviewer(cfg, rid, model=None) -> str:
    """'Codex, gpt-5 (bugs and security)' / 'this agent on a different model, sonnet or opus (code standards)'."""
    spec = _roster_spec(cfg, rid) or {}
    lens = PLAIN_LENS.get(spec.get("lens", "both"), spec.get("lens", "review"))
    if spec.get("kind") == "agent":
        if spec.get("alt"):
            alts = host_model_map(cfg).get("alternates") or []
            return f"this agent on a different model, {' or '.join(alts)} ({lens})"
        return f"this agent, {_plain_model(role_model(cfg, 'ratchet-adversary'))} ({lens})"
    name = spec.get("provider") or rid.rsplit("-", 1)[0]
    shown = {"claude": "Claude", "codex": "Codex", "gemini": "Gemini", "copilot": "Copilot", "cursor": "Cursor",
             "opencode": "OpenCode"}.get(name, name)
    return f"{shown}, {_plain_model(spec.get('model') or model)} ({lens})"


def models_table(cfg) -> list[tuple[str, str]]:
    return [(role, role_model(cfg, role)) for role in sorted(set(ROLE_PLAIN) | set(cfg.get("role_models") or {}))]


ROLE_PLAIN = {"ratchet-checkpoint-planner": "planning the steps", "ratchet-implementer": "writing the code",
              "ratchet-fixer": "fixing review findings", "ratchet-adversary": "this agent's own code reviews",
              "ratchet-visual-reviewer": "visual UI review", "ratchet-behavior-reviewer": "UI behaviour review",
              "ratchet-app-scout": "checking the app runs", "ratchet-test-planner": "planning tests",
              "ratchet-test-writer": "writing tests", "ratchet-design-system": "the design file",
              "ratchet-prototyper": "the prototype", "ratchet-test-runner": "running tests",
              "ratchet-variant-writer": "disguised examples for high-risk checks"}


def cmd_models(args):
    """Which model each role uses on this host, so the orchestrator can pass it when it spawns a sub-agent."""
    cfg = Ctx(find_root()).config()
    rows = models_table(cfg)
    if args.json:
        print(json.dumps({"host": detect_host(cfg), "roles": dict(rows),
                          "alternates": host_model_map(cfg).get("alternates") or []}, indent=2))
        return
    print(f"Host: {detect_host(cfg)}. Spawn each role's sub-agent with this model (inherit = your own model):")
    for role, m in rows:
        print(f"  {role:<28} {m}")


def _review_preview(ctx, cfg, cp) -> tuple[list[str], bool]:
    """(plain names of who would review this step right now, every reviewer is the host's own company?)"""
    try:
        res = resolve_reviewers(ctx, cfg, cp)
    except SystemExit:
        return ["(no reviewer available)"], True
    names = [plain_reviewer(cfg, r["id"], r.get("model")) for r in res]
    host_only = all((_roster_spec(cfg, r["id"]) or {}).get("kind") == "agent" for r in res)
    return names, host_only


def _done_means_links(ctx, plan) -> dict:
    """{1-based line number: [case id, ...]} for every objective.done_means line, across every checkpoint's
    test plan (a step with no tests/CPn.json contributes nothing): the case ids whose "proves" names that line,
    in plan order. Empty when the plan has no objective or no done_means list at all. Shared by
    _done_means_proof_notes (the Proved by / Heads up note under each line in plan-summary, brief, the
    reviewers `how` line and the launch guard) and _unproven_done_means."""
    obj = plan.get("objective") if isinstance(plan, dict) else None
    dm = obj.get("done_means") if isinstance(obj, dict) else None
    if not isinstance(dm, list) or not dm:
        return {}
    links = {i: [] for i in range(1, len(dm) + 1)}
    for cp in plan.get("checkpoints") or []:
        for case in (test_plan(ctx, cp["id"]) or {}).get("cases") or []:
            for p in _proves_values(case):
                if isinstance(p, int) and not isinstance(p, bool) and p in links:
                    links[p].append(str(case.get("id", "?")))
    return links


def _unproven_done_means(ctx, plan) -> list[tuple]:
    """[(1-based line number, its own text), ...] for every objective.done_means line that no test-plan
    case's "proves" names, across every checkpoint. Empty when the plan has no objective or no done_means at
    all (nothing to flag). One consumer: unlinked_done_means_problems, the refusal plan-submit applies to every
    line and plan-extend applies to the lines feedback added since the approval snapshot. The Proved by / Heads
    up notes plan-summary and brief print come from _done_means_proof_notes, not from here, and CP3's
    `_dm_findings_block` reads the approval marker (`_approved_after_dm`), never today's links."""
    links = _done_means_links(ctx, plan)
    dm = (plan.get("objective") or {}).get("done_means") if links else []
    return [(i, t) for i, t in enumerate(dm, 1) if not links.get(i)]


def unlinked_done_means_problems(ctx, plan, approved_lines=()) -> list[str]:
    """The "Plan invalid" refusal for unlinked done-means lines: one message per objective.done_means line that
    no test-plan case's "proves" names, naming the line by its 1-based number and its exact text and telling the
    agent what to add. Only that line is named (two lines with the same wording are told apart by number). A
    plan with no objective or no done_means list has nothing to link, so this is empty and objective_problems
    does the refusing. plan-submit calls it next to proves_problems for every line. plan-extend passes
    approved_lines=_approved_done_means(st): a line whose text the approved plan already had is skipped, so a run
    whose plan was approved before this rule keeps taking feedback and new steps, while a line feedback added
    after the approval is refused like a new plan's."""
    return [f"done_means line {i} (\"{t}\") has no test case proving it. Add a case to a step's tests/CPn.json "
            f"whose \"proves\" names line {i}."
            for i, t in _unproven_done_means(ctx, plan) if t not in approved_lines]


def _approved_done_means(st) -> list[str]:
    """The objective.done_means lines the approved plan had, read from the approval snapshot
    (st["approved"]["objective"], written by approve-plan and refreshed only by plan-extend, which may append
    lines but never change one; approve-changes and merged carry the lines forward unchanged). [] for a run that
    has no approval yet or whose approved plan had no objective or no done_means list. Used by plan-extend (which
    lines feedback added, and its append-only check), _unlinked_done_means_note and `_finish_block_lines`; CP3's
    `_dm_findings_block` does not read it (it reads the `done_means_rules` marker through `_approved_after_dm`)."""
    obj = (st.get("approved") or {}).get("objective")
    dm = obj.get("done_means") if isinstance(obj, dict) else None
    return [t for t in dm if isinstance(t, str)] if isinstance(dm, list) else []


def _unlinked_done_means_note(st, line) -> str:
    """Why the Heads up note under an unlinked done_means line (plan-summary, brief, the reviewers `how` line and
    the launch guard, via _done_means_proof_notes) says what it says, from the run's state and never assumed: while the plan is still being planned, plan-submit is what refuses it; a line the approved
    plan already had predates the rule (the only way an approved plan has one) and keeps working; any other line
    was added after the approval and plan-extend refuses the extension until a case proves it."""
    if st.get("phase") in ("planning", "awaiting_plan_approval"):
        return "plan-submit refuses the plan until a case's \"proves\" names it"
    if line in _approved_done_means(st):
        return "this plan was approved before every line needed one; it keeps working"
    return "it was added after the plan was approved; plan-extend refuses the extension until a case's \"proves\" names it"


def _done_means_proof_notes(ctx, plan, st) -> dict:
    """{1-based done_means line number: the one note line objective_brief prints under that line}: `Proved by:
    <case ids>` from _done_means_links, or the plain `Heads up` (worded by _unlinked_done_means_note from the run's
    state `st`, which may be {} when it can't be read) for a line no case proves yet. {} when the plan has no
    objective or no done_means list. Shared by plan-summary, brief and the sub-agent launch guard, so all three
    render the objective the same way."""
    links = _done_means_links(ctx, plan)
    dm = (plan.get("objective") or {}).get("done_means") if links else []
    notes = {}
    for i, line in enumerate(dm, 1):
        if links.get(i):
            notes[i] = f"Proved by: {', '.join(links[i])}"
        else:
            notes[i] = (f"Heads up: done_means line {i} (\"{line}\") has no test case proving it yet "
                        f"({_unlinked_done_means_note(st or {}, line)}).")
    return notes


def cmd_plan_summary(args):
    ctx = Ctx(find_root())
    st = ctx.state()
    plan = ctx.plan()
    if not plan or not plan.get("checkpoints"):
        die("There is no plan yet. Finish planning first, then ask again.")
    cfg = ctx.config()
    print(f"Plan: {plan.get('feature') or st.get('feature')} ({len(plan['checkpoints'])} steps)")
    obj = plan.get("objective")
    if isinstance(obj, dict) and obj:
        print("")
        # the same rendering brief prints (minus its "Objective" heading), so the two match word for word; the
        # approved done-means lines once approved (CP4), see _plan_for_briefs
        shown = _plan_for_briefs(plan, st)
        print("\n".join(objective_brief(shown, _done_means_proof_notes(ctx, shown, st)).splitlines()[1:]))
    for line in spec_summary_lines(ctx, plan):
        print(line)
    all_host = True
    for i, cp in enumerate(plan["checkpoints"], 1):
        risk = cp.get("risk", "normal")
        who, host_only = _review_preview(ctx, cfg, cp)
        all_host &= host_only
        bar = (cfg.get("blocking_severities") or {}).get(risk, "all")
        print(f"\n{i}. {cp['title']}")
        print(f"   Done when: {(cp.get('done_when') or [''])[0]}")
        print(f"   UI review: {'yes' if (cp.get('gates') or {}).get('ui') else 'no'}")
        print(f"   Risk: {risk}" + ("" if bar == "all" else f" (only {' and '.join(bar)} findings block; minor ones are noted for later, "
                                                             "unless one names a done-means line, which always blocks)"))
        print(f"   Reviewed by: {'; '.join(who)}")
        ecl = exit_code_only_line(cp)
        if ecl:
            print(f"   Tests: {ecl}")
        sl = _step_spec_line(cp)
        if sl:
            print(f"   From the spec: {sl}")
    converge_after = int(cfg.get("converge_after_round", 2))
    print(f"\nReview rules: after round 1, only the kind of review (bugs or standards) that still has an open "
          f"blocker or major finding is asked again; two reviewers that turn out to be the same company, model "
          f"and kind of review count once, not twice; a round nobody reviewed yet costs nothing to replace; and "
          f"from round {converge_after + 1} on, a minor finding alone no longer blocks (it is still recorded, see "
          f"`ratchet.py deferred`).")
    print(f"\nQuick paths: a step whose actual changes are docs only skips its review round entirely "
          f"(the test files naming those docs run instead); once a step's review has approved, a doc edit "
          f"made after that approval re-runs the test files naming that doc instead of opening a new review "
          f"round; a small code fix (at or under {cfg.get('small_edit_lines', 20)} changed lines) in a step "
          f"that is not high risk gets a one-reviewer check instead of the full round. A high-risk step, or "
          f"any change that also touches code, always gets the normal full review and tests.")
    if not cfg.get("doc_test_command"):
        print("Note: doc_test_command is not configured, so the docs quick path is off right now: every step, "
              "docs-only ones included, gets the normal full review and tests.")
    if not cfg.get("related_test_command"):
        print("Note: related_test_command is not configured, so the related pass before the full suite is off: a "
              "break is found only when the full suite runs at the end of each step. To turn it on, set it to the "
              "project's test command with a {files} placeholder (for example 'pnpm vitest run {files}').")
    rows = dict(models_table(cfg))
    groups = {}
    for role, m in rows.items():
        groups.setdefault(m, []).append(role)
    print("\nModels: " + "; ".join(f"{_plain_model(m)} for " + ", ".join(ROLE_PLAIN.get(r, r.replace('ratchet-', ''))
                                                                         for r in roles)
                                   for m, roles in groups.items()))
    if all_host:
        print("\nNote: no other provider is available right now, so every review will come from this agent's own "
              "company's models. If you have other agent tools installed (Codex, Gemini, Copilot, Cursor, OpenCode "
              "and so on), I can check them and use them for reviews.")
    if hooks_view(ctx, st).get("waived"):
        print("\nNote: hooks were skipped at your request, so the checks are only advice.")
    acc = _accepted_findings_lines(st)
    if acc:
        print("")
        for line in acc:
            print(line)
    ci_lines = _checkin_decisions_lines(st)
    if ci_lines:
        print("")
        for line in ci_lines:
            print(line)


# ---- providers: discover, test and register other agent CLIs ------------------------------------------------

PROBE_TOKEN = "RATCHET-PROBE-OK"


def _status_path(ctx):
    return ctx.ratchet / "provider-status.json"


_STATUS_DAMAGED = "Ratchet treats every provider as not yet tested"
_HEALTH_DAMAGED = "Ratchet treats every provider as not yet tested and rebuilds it from the next test results"
_PROBE_CLAIM_SLACK = 30.0  # seconds a test-request claim lasts beyond the request's own timeout (and a waiter waits)
_HEALTH_LOCK_WAIT = 20.0  # seconds every writer of provider-health.json waits for its lock (a lost result costs every lane)


def _health_path() -> Path:
    """The shared provider health record: one per-user file (provider_health.py), the same for every project."""
    return ratchet_home() / phealth.FILE


def provider_health() -> dict:
    """Every provider's last test result and bench, as every lane on this machine sees it."""
    return read_json(_health_path(), {}, record=_HEALTH_DAMAGED) or {}


def _health_key(pv) -> str:
    """The provider's one key in the shared record: its tool plus its model. A hand-written command provider has no
    preset, so its program is its tool (and its id tells two providers run through one program apart)."""
    tool = pv.get("preset") or Path(provider_binary(pv) or str(pv.get("id"))).name
    label = pv.get("model")
    if not label and not pv.get("preset") and pv.get("id") not in (None, tool):
        label = pv["id"]
    return phealth.entry_key(tool, label)


def _reviewer_health_key(cfg, rid) -> str | None:
    """The shared-record key of the provider behind reviewer `rid` (or of provider id `rid` itself); None for a
    host sub-agent or a hand-written reviewer that has no provider."""
    pv = provider_by_id(cfg, rid)
    if pv is None:
        spec = _roster_spec(cfg, rid) or {}
        if spec.get("provider"):
            pv = provider_by_id(cfg, spec["provider"])
        elif spec.get("kind") == "command" and spec.get("preset"):
            return phealth.entry_key(spec["preset"], spec.get("model"))
    return _health_key(pv) if pv is not None else None


def same_provider_reviewers(cfg, rid) -> list[str]:
    """`rid` and every other reviewer id that runs the same provider (the same tool plus model), so one failing
    model is benched on its own: opencode-glm failing leaves opencode-kimi, on the same program, working. A
    reviewer with no provider identity (a hand-written command) stands alone."""
    key = _reviewer_health_key(cfg, rid)
    if key is None:
        return [rid]
    return [r for r in roster(cfg) if r == rid or _reviewer_health_key(cfg, r) == key]


def _update_health(change, note: bool = True, lock=None) -> str:
    """Change the shared provider health record (`change(data)` edits it in place). Every lane on the machine updates
    it, so it is changed only through update_record, under its own lock (or `lock`, that lock already held by the
    caller); a damaged one holds nothing and is rebuilt. Waits longer for the lock than most records
    (_HEALTH_LOCK_WAIT): a result lost here makes every lane test, or keep using, a provider that is out. Returns update_record's result; a caller that
    must not claim the change was saved checks for "busy" and refuses with _die_record_busy (note=False)."""
    p = _health_path()

    def fn(data):
        change(data)
        return data
    res = update_record(p, fn, lock=lock, damaged=_HEALTH_DAMAGED, pretty=True, wait=_HEALTH_LOCK_WAIT)
    if res == "busy" and note:
        _note_record_busy(p, "this provider check")
    return res


def _start_id(nonce, rid) -> str:
    """The id of one review start: the round's nonce plus the reviewer id, so it belongs to that reviewer in that round
    of that lane and no other, and a refund takes back exactly it."""
    return f"{nonce}:{rid}"


def _start(data, key, at, sid) -> None:
    """Record one review start on a provider and note when a round picked it (`picked`: the rotation tie-break, kept
    when a replaced unreviewed round gives its starts back)."""
    phealth.record_start(data, key, at, sid)
    phealth.mark_picked(data, key, at)


def update_review_starts(cfg, nonce, add=(), give_back=()) -> None:
    """Change the shared provider health record's review starts in one save, without choosing anything: the unlocked,
    best-effort recorder. Opening and refilling a round reserve their starts through _reserve_under_lock (which also
    checks provider_share); this is used for those only when that lock was busy (the starts are recorded afterwards, with
    no share check), for releasing a reservation whose provider was never tested, and for external_review's refunds.
    `add` are the reviewer ids a round (`nonce`) starts with: each reviewer's provider gets a start (a host reviewer has
    no provider), so the next round, in this project or any other on the machine, spreads to the providers used least.
    `give_back` are reviewer ids of this round that never really used their provider: exactly the start recorded for
    that reviewer in that round is taken back, once. A busy lock prints a note naming the review start and the round
    goes on."""
    adds = [(k, _start_id(nonce, r)) for r in add for k in [_reviewer_health_key(cfg, r)] if k]
    backs = [(k, _start_id(nonce, r)) for r in give_back for k in [_reviewer_health_key(cfg, r)] if k]
    if not adds and not backs:
        return
    at = _dt.datetime.now(_dt.timezone.utc)

    def change(data):
        for k, sid in backs:
            phealth.refund_start(data, k, sid)
        for k, sid in adds:
            _start(data, k, at, sid)
    if _update_health(change, note=False) == "busy":
        _note_record_busy(_health_path(), "a review start" if adds else "the give-back of a review start")


def _reserve_under_lock(cfg, ignore, pick, refunds, adds, keep_picked=False):
    """Choose reviewers and reserve their starts as ONE step under the shared provider record's lock, so lanes
    opening rounds at the same moment can never take more than provider_share.max starts on one provider in the window:
    the second lane's choice is made after the first lane's reservation is saved. Inside the lock this calls
    `pick(share)` (resolve_reviewers with the record read under the lock; `share` = {"data", "ignore"} where `ignore`
    are start ids about to be given back and so not counted), then gives back the starts `refunds(picked)` lists and
    records the starts `adds(picked)` lists, both as [(reviewer id, round nonce)], and saves them together
    (`keep_picked`: the given-back starts keep their pick time, for a round replaced unreviewed). Returns what
    `pick` returned, or None when the lock could not be had (a note says the starts could not be reserved under the
    lock; the caller goes on without a reservation and records its starts afterwards, best effort). What it then
    goes on with differs: a round being opened keeps the read-only share pick it made just before (the share was
    checked on an unlocked read, only the atomic reservation is lost); a same-round refill picks with no share."""
    out = []

    def change(data):
        picked = pick({"data": data, "ignore": set(ignore)})
        at = _dt.datetime.now(_dt.timezone.utc)
        for rid, nonce in refunds(picked):
            key = _reviewer_health_key(cfg, rid)
            if key:
                phealth.refund_start(data, key, _start_id(nonce, rid), keep_picked)
        for rid, nonce in adds(picked):
            key = _reviewer_health_key(cfg, rid)
            if key:
                _start(data, key, at, _start_id(nonce, rid))
        out.append(picked)
    if _update_health(change, note=False) == "busy":
        p = _health_path()
        print(f"ratchet: {p} was being updated by another Ratchet command (its lock {_record_lock_path(p)} could not be "
              "had), so this round's review starts could not be reserved under the lock (the provider share was checked "
              "on an unlocked read, or not at all for a same-round refill); they are recorded afterwards if the lock "
              "frees up.", file=sys.stderr)
        return None
    return out[0]


def refund_review_start(cfg, nonce, rid) -> None:
    """The review by `rid` in the round `nonce` never used its provider (the CLI failed before it answered): take back
    exactly the start that round recorded for it (see update_review_starts). Once only: a second call finds none."""
    update_review_starts(cfg, nonce, give_back=[rid])


def provider_bench(cfg, rid) -> dict | None:
    """The live bench ({reason, since, until}) of the provider behind reviewer `rid`, as every lane sees it."""
    key = _reviewer_health_key(cfg, rid)
    if key is None:
        return None
    return phealth.live_bench(provider_health(), key, _dt.datetime.now(_dt.timezone.utc))


def shared_unavailable(cfg) -> dict:
    """Every roster reviewer whose provider is benched in the shared health record, as {reviewer id: {reason, since,
    until}}: the same shape as unavailable-reviewers.json, so `status --json` shows a provider any lane benched."""
    data, at, out = provider_health(), _dt.datetime.now(_dt.timezone.utc), {}
    for rid in roster(cfg):
        key = _reviewer_health_key(cfg, rid)
        bench = phealth.live_bench(data, key, at) if key else None
        if bench:
            out[rid] = {k: bench.get(k) for k in ("reason", "since", "until")}
    return out


def _note_record_busy(p: Path, lost: str):
    """Say on stderr that a shared record's lock could not be had, so `lost` was not saved. Only for a best-effort
    caller that goes on regardless (e.g. probe_provider): a caller that then refuses outright uses
    _die_record_busy instead, which says this once, accurately, in its own refusal; the two are never both printed
    for the same busy write."""
    print(f"ratchet: {p} was being updated by another Ratchet command (its lock {_record_lock_path(p)} "
          f"could not be had), so {lost} was not saved.", file=sys.stderr)


def _retry_command() -> str:
    """The command this process was run as (this interpreter, this ratchet.py and every argument it was given, each
    quoted for a POSIX shell), so a refusal can say exactly what to run again and running it as written works."""
    import shlex
    args = list(_ENGINE_ARGV) if _ENGINE_ARGV is not None else list(sys.argv[1:])
    return shlex.join([sys.executable or "python3", str(Path(__file__).resolve()), *args])


def _die_record_busy(p: Path, lost: str):
    """The one refusal every update_record caller that must not claim its change was saved uses: names the record
    and the lock update_record itself takes for it (_record_lock_path, so the two can't drift apart), says what
    `lost`, and gives the user's own whole command to run again (_retry_command: every flag kept). Exits non-zero
    through die(); never returns."""
    die(f"{p} is being updated by another Ratchet command right now (its lock {_record_lock_path(p)} could not be "
        f"had), so {lost}. Run the same command again in a moment: `{_retry_command()}`")


def _update_provider_status(ctx, change, note: bool = True, lock=None) -> str:
    """Change provider-status.json (`change(data)` edits it in place). Only `providers --add` writes it now (nothing
    reads it for a decision; the shared provider-health.json does that), but it can still be updated by two
    commands at once, so it is changed only through update_record, under its own lock (or
    `lock`, that lock already held by the caller); a damaged one holds no result and is replaced. Returns
    update_record's result. A caller that must not then claim the change was saved checks for "busy" itself and
    refuses with _die_record_busy, passing note=False so this does not also print a stderr note for the same busy
    write: `providers --add --no-check` does this, and a checked `providers --add` takes this lock itself first
    (see _record_probe). A best-effort caller leaves note=True, so the stderr note below speaks for it."""
    p = _status_path(ctx)

    def fn(data):
        change(data)
        return data
    res = update_record(p, fn, lock=lock, damaged=_STATUS_DAMAGED, pretty=True)
    if res == "busy" and note:
        _note_record_busy(p, "this provider check")
    return res


_EVENT_TYPES = ("step_start", "step_finish", "text", "reasoning", "tool_use", "tool_result", "error")


def event_stream(stdout) -> dict | None:
    """Read the output of `opencode run --format json`: one JSON event per line ({"type", "part": {...}} with type
    step_start, text, reasoning, tool_use, step_finish or error). Returns {"text": the text events' answer text only,
    "errors": the error events' messages, "length": a step finished with reason "length" (the model ran out of
    output room)}, or None when the output holds no event (an older CLI or a plain-text program), which callers read
    as plain text. A reasoning or tool event, and the request echoed in either, is never part of the answer."""
    text, errors, length, seen = [], [], False, False
    for line in str(stdout or "").splitlines():
        line = line.strip()
        if not line.startswith("{"):
            continue
        try:  # a line of a program's output, not a record Ratchet keeps (so not _read_record)
            ev = json.loads(line)
        except ValueError:
            continue
        if not isinstance(ev, dict) or ev.get("type") not in _EVENT_TYPES:
            continue
        seen = True
        part = ev["part"] if isinstance(ev.get("part"), dict) else {}
        if ev["type"] == "text":
            text.append(str(part.get("text") or ""))
        elif ev["type"] == "step_finish" and part.get("reason") == "length":
            length = True
        elif ev["type"] == "error":
            err = ev["error"] if isinstance(ev.get("error"), dict) else {}
            data = err.get("data") if isinstance(err.get("data"), dict) else {}
            errors.append(str(data.get("message") or err.get("message") or err.get("name") or "error"))
    return {"text": "\n".join(text), "errors": errors, "length": length} if seen else None


def probe_provider(ctx, cfg, pv, bench=True, note: bool = True, record: bool = True,
                   by: str | None = None) -> tuple[bool, str, bool]:
    """Send a tiny request through the provider as a review would go (the same command with the variant arguments),
    plus the preset's `probe_args` (opencode: --title=connectivity check, which replaces the review's title); a JSON
    event stream in its output is read with event_stream (only the answer text can hold the token, and an error
    event reads like stderr). The result is recorded (_record_probe: the shared provider-health.json, then this
    project's unavailable-reviewers.json), dated when the request was
    sent; `by` is the claim this lane holds on the provider (probe_shared), ended with the result.
    Returns (good, detail, saved): `saved` is False when either of those writes could not be made because its lock
    was busy (True when both were saved, or when nothing was sent because the provider has no command or isn't
    installed, so there was nothing to record). Every recording caller is best effort and leaves note=True, so a
    stderr line speaks for a busy write. A caller that must not claim anything was saved unless all of it was (a
    checked `providers --add`) passes record=False (nothing is written, and `saved` is False once a request was
    sent), then takes the three records' locks (provider-status, provider-health, unavailable-reviewers) itself and
    calls _record_probe."""
    if per_use_unapproved(pv):  # costs money per use and no recorded OK: not even a test request
        return False, "costs money per use and the developer has not given the exact OK; no request sent", True
    cmd_t, use_stdin = provider_command(pv)
    if not cmd_t:
        return False, "no command", True
    if not shutil.which(cmd_t[0]):
        return False, f"'{cmd_t[0]}' is not installed or not on PATH", True
    prompt = f"This is a connectivity check. Reply with exactly this and nothing else: {PROBE_TOKEN}"
    work = Path(tempfile.mkdtemp(prefix="ratchet-probe-"))
    out_file = work / "last-message.txt"
    subs = {"{prompt_file}": str(work / "prompt.md"), "{prompt}": prompt, "{out_file}": str(out_file),
            "{root}": str(ctx.root), "{model}": str(pv.get("model") or "")}
    (work / "prompt.md").write_text(prompt)
    cmd = []
    for part in cmd_t:
        for k, v in subs.items():
            part = part.replace(k, v)
        cmd.append(part)
    if not pv.get("command"):  # a preset may label its test request (opencode titles the session)
        extra = list((PRESETS.get(pv.get("preset", "")) or {}).get("probe_args") or [])
        names = tuple(a.split("=", 1)[0] + "=" for a in extra if a.startswith("--") and "=" in a)
        cmd = [c for c in cmd if not c.startswith(names)] + extra  # its own value replaces the preset's, never doubled
    sent = _dt.datetime.now(_dt.timezone.utc)  # the result is dated by this, not by when the answer came back
    quota_until = None  # set when the provider said it is out of credits: the time it said it is back
    try:
        r = subprocess.run(cmd, cwd=work, input=prompt if use_stdin else None, capture_output=True, text=True,
                           stdin=None if use_stdin else subprocess.DEVNULL,  # a CLI waiting on stdin must not hang
                           timeout=int(cfg.get("probe_timeout_sec", 120)),
                           env=dict(os.environ, RATCHET_NESTED_REVIEW="1"))
        ev = event_stream(r.stdout)
        if ev:  # a JSON event stream: only its answer text can hold the token (not the request echoed in an event)
            r.stdout, r.stderr = ev["text"], (r.stderr or "") + "\n".join(ev["errors"])
        text = (out_file.read_text() if out_file.exists() else "") + (r.stdout or "") + (r.stderr or "")
        good = PROBE_TOKEN in text.replace("\n", "")
        detail = "answered the test request" if good else (
            f"exit {r.returncode}: " + ((r.stderr or r.stdout or "no output").strip().splitlines() or ["no output"])[-1][:200])
        if not good:
            quota = quota_failure([r.stderr, r.stdout, out_file.read_text() if out_file.exists() else ""], cfg, sent)
            if quota:
                quota_until, detail = quota[0], f"out of credits: {quota[1]}"
    except subprocess.TimeoutExpired:
        good, detail = False, f"no answer within {cfg.get('probe_timeout_sec', 120)}s"
    except OSError as e:
        good, detail = False, str(e)[:200]
    shutil.rmtree(work, ignore_errors=True)
    if not record:
        return good, detail, False
    busy = _record_probe(ctx, pv, good, detail, bench=bench, note=note, sent=sent, by=by, quota_until=quota_until)
    return good, detail, not busy


def _record_probe(ctx, pv, good: bool, detail: str, bench: bool = True, note: bool = True, locks=None,
                  local_copy: bool = False, sent=None, by: str | None = None, quota_until=None) -> list:
    """Record a probe's result in the shared provider health record (a failing provider is benched for every lane
    when `bench`), then clear this project's reviewer marks for a provider that passed or is not benched. `sent` is
    when the request was sent (default: now): a result older than the one already recorded is dropped. `by` is the
    claim this lane holds on the provider, ended with the result. `quota_until`: the provider said it is out of
    credits and is back then: its bench is a quota bench to that time (a passing test request does not end it).
    `local_copy`: a checked `providers --add` also keeps its result in this project's own provider-status.json, as
    it always has (nothing reads that file for a decision any more). Returns the records whose write was busy, in
    the order tried (empty when every write was saved). `locks` maps a record's path to its _RecordLock the caller
    already holds: a caller that takes them all first can't have one written and then find another busy."""
    locks = locks or {}
    hp, sp, up = _health_path(), _status_path(ctx), _unavailable_path(ctx)
    busy = []
    if local_copy and _update_provider_status(
            ctx, lambda data: data.__setitem__(pv["id"], {"ok": good, "at": now(), "detail": detail}),
            note=note, lock=locks.get(sp)) == "busy":
        busy.append(sp)
    at = _dt.datetime.now(_dt.timezone.utc)
    sent = sent or at
    benched = not good and bench
    quota = benched and quota_until is not None
    until = quota_until if quota else (
        at + _dt.timedelta(hours=float(ctx.config().get("unavailable_ttl_hours", 6))) if benched else None)
    if _update_health(lambda data: phealth.record_probe(data, _health_key(pv), good, detail, sent,
                                                        f"test request failed: {detail}", until, now=at, by=by,
                                                        quota=quota),
                      note=note, lock=locks.get(hp)) == "busy":
        busy.append(hp)
    if not benched:
        def clear(live):
            for lens in LENSES:
                k = f"{pv['id']}-{lens}"
                if not (live.get(k) or {}).get("quota"):  # a quota wait ends at its time or by a real review only
                    live.pop(k, None)
        if _update_unavailable(ctx, clear, note=note, lock=locks.get(up)) == "busy":
            busy.append(up)
    return busy


def quota_failure(texts, cfg, now=None):
    """(the time the provider is back, the line that said so) when a provider's own output says it is out of credits,
    else None (provider_health.quota_failure). A reset time it did not give, or one already past, becomes
    quota_retest_minutes (default 20) from now."""
    return phealth.quota_failure(texts, now or _dt.datetime.now(_dt.timezone.utc), quota_retest_minutes(cfg))


def quota_retest_minutes(cfg) -> float:
    """The quota_retest_minutes setting: a positive number, else a plain error naming the setting and its value (a
    zero or negative wait would end a quota bench the moment it begins)."""
    v = cfg.get("quota_retest_minutes", 20)
    try:
        n = float(v)
    except (TypeError, ValueError):
        n = 0.0
    if isinstance(v, bool) or not 0 < n < float("inf"):
        die(f"quota_retest_minutes must be a positive number of minutes, but it is {json.dumps(v)}. Set it with "
            "`ratchet.py config --set quota_retest_minutes=20`.")
    return n


def provider_share(cfg) -> tuple[int, float]:
    """The provider_share setting as (max, minutes): at most `max` review starts on one provider in any `minutes`
    minutes, across every lane on the machine. `max` is a positive whole number and `minutes` a positive number
    (decimals accepted); anything else is a plain error naming the setting and its value."""
    v = cfg.get("provider_share", {"max": 3, "minutes": 15})
    if not isinstance(v, dict):
        die(f"provider_share must be {{\"max\": <whole number>, \"minutes\": <number>}}, but it is {json.dumps(v)}. "
            "Set it with `ratchet.py config --set provider_share.max=3 provider_share.minutes=15`.")
    mx, mins = v.get("max", 3), v.get("minutes", 15)
    if isinstance(mx, bool) or not isinstance(mx, int) or mx < 1:
        die(f"provider_share.max must be a positive whole number of review starts, but it is {json.dumps(mx)}. Set it "
            "with `ratchet.py config --set provider_share.max=3`.")
    ok_mins = isinstance(mins, (int, float)) and not isinstance(mins, bool) and 0 < mins < float("inf")
    if not ok_mins:
        die(f"provider_share.minutes must be a positive number of minutes, but it is {json.dumps(mins)}. Set it with "
            "`ratchet.py config --set provider_share.minutes=15`.")
    return mx, float(mins)


def _minutes_text(m: float) -> str:
    return f"{m:g} minute" + ("" if m == 1 else "s")


def bench_quota(cfg, rid, reason, until) -> bool:
    """A review by reviewer `rid` found its provider out of credits: bench the provider for every lane until `until`
    (a datetime) in the shared record. False when it could not be saved (no provider behind `rid`, or the record's
    lock was busy), so the caller marks the reviewer in its own project instead."""
    key = _reviewer_health_key(cfg, rid)
    if key is None:
        return False
    at = _dt.datetime.now(_dt.timezone.utc)
    return _update_health(lambda data: phealth.record_probe(data, key, False, reason, at, reason, until, now=at,
                                                            quota=True), note=False) != "busy"


def record_round_failure(ctx, cfg, cp_id, round_no, rids, own=None) -> bool:
    """A real review in round `round_no` of `cp_id` failed: record the provider behind each reviewer in `rids` in that
    round's `failed_providers` at once, so a test request that passes before the next `reviewers` call (it clears a
    plain bench) can't put the provider back in the round. Done under the state lock, like every other change to the
    run; the round is left alone when it has moved on (another round, or already recorded). `own` is the reviewer whose
    own run failed: it goes in the round's `failed_reviewers`, so a sibling swapped out without running is told apart.
    False when the lock could
    not be had in about 10 seconds (it is tried five times, so a long command holding it briefly does not lose the record): the bench still keeps the provider out until `reviewers` records it."""
    lock = _StateLock(ctx.root, cmd="review-failure")
    for _ in range(5):  # behind a long command (reviewers) one try waits only ~2s; this is a short write: ~10s in all
        if not lock.acquire():
            break
    else:
        return False
    try:
        st = ctx.state()
        rnd = (st.get("checkpoints", {}).get(cp_id) or {}).get("adv_round") or {}
        if not rnd or rnd.get("round") != round_no or rnd.get("recorded"):
            return True
        failed = set(rnd.get("failed_providers") or [])
        failed |= {_reviewer_health_key(cfg, r) or r for r in rids}
        own_failed = set(rnd.get("failed_reviewers") or []) | ({own} if own else set())
        if sorted(failed) != sorted(rnd.get("failed_providers") or []) or sorted(own_failed) != sorted(rnd.get("failed_reviewers") or []):
            rnd["failed_providers"] = sorted(failed)
            rnd["failed_reviewers"] = sorted(own_failed)
            ctx.save_state(st)
        return True
    finally:
        lock.release()


def review_succeeded(cfg, rid, sent, ctx=None) -> bool:
    """A real review by `rid`, sent at `sent` (a datetime), succeeded: its provider is back, so a quota bench that
    began before the review was sent (kept through passing test requests) ends now; a review already under way when
    another lane found the provider out of credits does not end that newer bench. With `ctx` (the project), the
    project's own quota marks (the fallback when the shared record was busy) for the same CLI end the same way; its
    other marks stay. Reads first, so an ordinary review writes nothing. False when a bench could not be ended (a
    record's lock was busy): it then ends at its own time."""
    done = True
    binary = reviewer_binary(cfg, rid)
    if ctx is not None and binary:
        def began_before(m):
            t = phealth._time(m.get("since"))
            return t is not None and t < sent

        def clear(live):
            for r in [r for r, m in live.items() if m.get("quota") and reviewer_binary(cfg, r) == binary
                      and began_before(m)]:
                live.pop(r)
        if any(m.get("quota") and reviewer_binary(cfg, r) == binary and began_before(m)
               for r, m in unavailable_reviewers(ctx).items()):
            done = _update_unavailable(ctx, clear, note=False) != "busy"
    key = _reviewer_health_key(cfg, rid)
    entry = provider_health().get(key) if key else None
    b = entry.get("bench") if isinstance(entry, dict) else None
    if isinstance(b, dict) and b.get("quota"):
        done = (_update_health(lambda data: phealth.end_quota_bench(data, key, sent), note=False) != "busy") and done
    return done


def probe_due(ctx, cfg, pid) -> bool:
    """Whether provider `pid` needs a test request now: not while any lane's recent test passed (inside
    probe_ttl_minutes) or while the provider is benched (it is tried again when the bench ends)."""
    pv = provider_by_id(cfg, pid)
    if not cfg.get("probe_providers", True) or pv is None:
        return False
    key, at, data = _health_key(pv), _dt.datetime.now(_dt.timezone.utc), provider_health()
    if phealth.live_bench(data, key, at):
        return False
    return not phealth.fresh_ok(data, key, at, float(cfg.get("probe_ttl_minutes", 120)))


def probe_shared(ctx, cfg, pv) -> tuple[bool, str]:
    """The automatic test request before a review round relies on provider `pv`: one lane sends it, the others use
    its result. Under the shared record's lock this looks at the record again and either finds a fresh pass or a
    bench (use it, send nothing), finds another lane's live claim (wait for that lane's result, polling, no longer
    than the claim lasts, then look again), or takes the claim itself and sends the request (probe_provider records
    the result and ends the claim; a claim whose lane died ends on its own). When the record's lock can't be had or
    the wait runs out, it sends its own request as it always did. Returns (good, detail)."""
    key, by = _health_key(pv), f"{os.getpid()}-{secrets.token_hex(4)}"
    timeout = float(cfg.get("probe_timeout_sec", 120))
    ttl = float(cfg.get("probe_ttl_minutes", 120))
    hold = timeout + _PROBE_CLAIM_SLACK  # the claim outlives the request: it starts a little after, and lands after
    give_up = time.monotonic() + hold
    while time.monotonic() < give_up:
        got = []
        res = _update_health(lambda data: got.append(phealth.claim(data, key, by, _dt.datetime.now(_dt.timezone.utc),
                                                                   ttl, hold)), note=False)
        if res == "busy":
            break
        what, _claim = got[0]
        if what == "claimed":
            try:
                return probe_provider(ctx, cfg, pv, by=by)[:2]
            finally:  # an early return (no command, not installed) records nothing: don't hold the claim
                _update_health(lambda data: phealth.release(data, key, by), note=False)  # busy: ends at its `until`
        if what in ("fresh", "benched"):
            e = provider_health().get(key)
            e = e if isinstance(e, dict) else {}
            return bool(e.get("ok")) and what == "fresh", str(e.get("detail") or "")
        while time.monotonic() < give_up:  # another lane's request is on its way
            time.sleep(0.5)
            if phealth.live_claim(provider_health(), key, _dt.datetime.now(_dt.timezone.utc)) is None:
                break
    return probe_provider(ctx, cfg, pv)[:2]


def _write_providers(ctx, plist):
    user = read_json(ctx.config_path, {}) or {}
    user["providers"] = plist
    write_json(ctx.config_path, user)


def _paid_provider_reply(model) -> str:
    """The one exact reply that pays for a per-use (or unknown-cost) model, named in `ask paid-provider`'s
    question. Never a generic listed yes (APPROVAL_REPLIES): this spends the developer's money, so the reply
    must name the model it pays for, the same rule the learnings set for hooks-waive and accept-finding."""
    return f"pay per use: {model}"


def _needs_paid_ok(pv) -> str | None:
    """'per-use' / 'unknown' when this `--add`'ed provider's model is billed per use (or its cost is
    unknown, treated the same way) and so needs the developer's OK before it is probed; None when the
    preset has no model lister (the cost check doesn't apply to it, e.g. a hand-written --command) or the
    model is flat-rate."""
    preset = pv.get("preset")
    model = pv.get("model")
    if not preset or preset not in MODEL_LISTERS or not model:
        return None
    cost = _listed_model_cost(model)
    return cost if cost != "flat" else None


def _paid_ok_refusal(tool, model) -> str:
    return (f"{model} (via {tool}) costs money per use (or its cost is unknown, which Ratchet treats the same "
            "way), including this one test request, so it was not added and nothing was sent to it. Ask the "
            f"developer first: run `ratchet.py ask paid-provider {tool} {model}`, show them the question it "
            "prints word for word, and wait for their exact reply before adding it.")


def _consume_paid_ok(ctx, st, pv) -> str:
    """The developer's one exact reply to `ask paid-provider <tool> <model>` for this exact tool and model,
    consumed once (`providers --add` is state-locked whenever it may need this, so nothing else can spend it
    at the same time). Dies, with nothing added and no request sent, when no such reply is on record, when
    this lane is director-enrolled (a chat reply never counts as the developer's own OK to spend money, the
    same rule as every other approval here), or when another question overtook this one before it was
    answered."""
    tool, model = pv.get("preset"), pv.get("model")
    if approval_mode(ctx) == "director":
        die(f"{model} (via {tool}) costs money per use (or its cost is unknown, treated the same way), and "
            "this lane is director-enrolled: a chat reply here never counts as the developer's own OK to "
            "spend money (unlike every other approval, paid-provider takes no director token). Nothing was "
            "added and nothing was sent to it. The developer must give this OK themselves, in a lane that "
            "isn't director-enrolled.")
    p = st.get("pending") or {}
    refusal = _paid_ok_refusal(tool, model)
    if p.get("action") != "paid-provider" or p.get("tool") != tool or p.get("model") != model:
        die(refusal)
    if p.get("overtook"):
        _clear_pending(st)
        ctx.log(st, "paid_provider_unclear", tool=tool, model=model)
        ctx.save_state(st)
        die(f"This question was printed while another one (shall I "
            f"{_question_what(p['overtook'], p.get('overtook_mode'), p.get('overtook_target'))}?) was still waiting for the user's first "
            "reply, so their reply could be meant for either. Nothing was added. Run `ratchet.py ask "
            f"paid-provider {tool} {model}` again on its own.")
    msgs = _replies(ctx, st, p.get("asked_at"), p)
    if not msgs:
        die(refusal)
    entry = msgs[0]  # only the first reply after the question answers it
    reply = entry.get("prompt", "")
    exact = _paid_provider_reply(model)
    if reply.strip().casefold() != exact.strip().casefold():
        _spend_question(ctx, st, reply)
        die(f"The user's first reply after the paid-provider question was not the exact reply \"{exact}\" (it "
            f"was \"{reply[:120]}\"). Nothing was added. If they still want this, run `ratchet.py ask "
            f"paid-provider {tool} {model}` again and show them the question word for word.")
    if ctx.config().get("verify_transcripts", True):
        good, why = _transcript_ok(entry, p.get("asked_at"))
        if not good:
            _spend_question(ctx, st, reply)
            die(f"Couldn't confirm that reply came from the user ({why}). Nothing was added. Run `ratchet.py "
                f"ask paid-provider {tool} {model}` again and ask them to reply again in this chat.")
    _clear_pending(st)
    ctx.log(st, "paid_provider_ok", tool=tool, model=model)
    ctx.save_state(st)
    return entry.get("at") or now()


def cmd_providers(args):
    ctx = Ctx(find_root())
    ctx.ratchet.mkdir(exist_ok=True)
    cfg = ctx.config()
    host = detect_host(cfg)
    plist = providers(cfg)
    if args.remove:
        plist = [pv for pv in plist if pv["id"] != args.remove]
        _write_providers(ctx, plist)
        ok(f"Removed provider {args.remove}.")
        return
    if args.add:
        if not (args.preset or args.command):
            die("--add needs --preset <" + "|".join(PRESETS) + "> or --command '<json list>'")
        pv = {"id": args.add}
        if args.preset:
            if args.preset not in PRESETS:
                die(f"unknown preset {args.preset}; known: {', '.join(PRESETS)}. Use --command for anything else.")
            pv["preset"] = args.preset
        if args.command:
            try:
                pv["command"] = json.loads(args.command)
                assert isinstance(pv["command"], list) and pv["command"]
            except (ValueError, AssertionError):
                die("--command must be a JSON list, e.g. '[\"mycli\", \"run\", \"{prompt}\"]'")
            pv["stdin"] = bool(args.stdin)
        if args.model:
            pv["model"] = args.model
        if args.company:
            pv["company"] = args.company
        if args.for_risk:
            pv["for_risk"] = [x.strip() for x in args.for_risk.split(",") if x.strip()]
        if args.variant:
            if not PRESETS.get(args.preset or "", {}).get("variant_flag") or args.command:
                die("--variant sets the thinking level of the opencode preset (for example low or high; none turns "
                    "the cap off). Nothing was added.")
            pv["variant"] = args.variant
        elif PRESETS.get(args.preset or "", {}).get("variant_flag") and not args.command:  # adding again keeps it
            was = next((x.get("variant") for x in plist if x["id"] == pv["id"] and x.get("variant")), None)
            if was:
                pv["variant"] = was
        if args.prefer_for:
            lenses = [x.strip() for x in args.prefer_for.split(",") if x.strip()]
            bad = [x for x in lenses if x not in LENSES]
            if bad or not lenses:
                die(f"--prefer-for takes a comma list of lenses from {', '.join(LENSES)}; "
                    f"{', '.join(repr(x) for x in bad) or repr(args.prefer_for)} is not one of them. Nothing was added.")
            pv["prefer_for"] = list(dict.fromkeys(lenses))
        if not provider_company(pv):
            die(f"Can't tell which company's model '{args.add}' runs. Give --model (a model name from that tool) "
                "or --company.")
        paid_cost = _needs_paid_ok(pv)
        if paid_cost:
            # Never probed, checked or not, without the developer's own exact yes to THIS tool and model first
            # (the paid-provider question); this runs before any request is sent, flat-rate adds are unaffected.
            pv["paid_ok_at"] = _consume_paid_ok(ctx, ctx.state(), pv)
            pv["cost"] = "per-use"
        elif args.preset in MODEL_LISTERS and pv.get("model"):
            pv["cost"] = "flat"  # a listed model that needed no OK is flat-rate (discovery labels its picks the same way)
        else:  # adding an id again (for example to set --prefer-for) keeps the cost label it already had
            was = next((x.get("cost") for x in plist if x["id"] == pv["id"] and x.get("cost")), None)
            if was:
                pv["cost"] = was
        if args.no_check:
            # an earlier result was about whatever had this id before
            p = _status_path(ctx)
            if _update_provider_status(ctx, lambda data: data.pop(pv["id"], None), note=False) == "busy":
                _die_record_busy(p, f"{args.add}'s old status entry was not cleared and it was not added")
        else:
            # A refused add changes nothing: a failed test request records nothing (an older provider with this id
            # keeps its own status), and a passing one is recorded only once all three records' locks are held, so
            # a busy lock on any leaves provider-status.json, provider-health.json, unavailable-reviewers.json and
            # config.json as they were
            sent = _dt.datetime.now(_dt.timezone.utc)
            good, detail = probe_provider(ctx, cfg, pv, record=False)[:2]
            if not good:
                die(f"{args.add} didn't pass the test request ({detail}). Not added. Fix the command or model and "
                    "try again (or add --no-check to add it anyway).")
            busy, locks = None, {}
            with contextlib.ExitStack() as stack:
                for rec in (_status_path(ctx), _health_path(), _unavailable_path(ctx)):
                    lk = stack.enter_context(_RecordLock(rec, _HEALTH_LOCK_WAIT if rec == _health_path() else 5.0))
                    if not lk.held:
                        busy = rec
                        break
                    locks[rec] = lk
                if busy is None:
                    left = _record_probe(ctx, pv, good, detail, bench=False, note=False, locks=locks,
                                         local_copy=True, sent=sent)
                    busy = left[0] if left else None
            if busy is not None:
                _die_record_busy(busy, f"nothing was changed and {args.add} was not added")
        plist = [x for x in plist if x["id"] != pv["id"]] + [pv]
        _write_providers(ctx, plist)
        ok(f"Added provider {args.add} ({provider_company(pv)}, {_plain_model(pv.get('model'))}). It can now review.")
        return
    if args.discover or args.check:
        want = args.check
        if want and want != "all" and not any(pv["id"] == want for pv in plist):
            # a reviewer name is <provider id>-<lens>: test that reviewer's provider only
            for lens in ("correctness", "standards", "both"):
                if want.endswith("-" + lens) and any(pv["id"] == want[:-len(lens) - 1] for pv in plist):
                    want = want[:-len(lens) - 1]
                    break
            else:
                die(f"'{args.check}' is not a known provider or reviewer name. Known provider ids: "
                    f"{', '.join(pv['id'] for pv in plist) or 'none'}. A reviewer name is a provider id plus a lens, "
                    "for example codex-correctness (lens: correctness, standards or both).")
        targets = [pv for pv in plist if not want or want in ("all", pv["id"])]
        for pv in targets:
            company = provider_company(pv)
            if company == host:
                continue
            if shutil.which(provider_binary(pv) or "") and company:
                probe_provider(ctx, cfg, pv)
    status = provider_health()
    rows = []
    for pv in plist:
        company = provider_company(pv)
        st_ = status.get(_health_key(pv))
        st_ = st_ if isinstance(st_, dict) else {}
        installed = bool(shutil.which(provider_binary(pv) or ""))
        if company == host:
            state = "same company as this agent, so not used as an independent reviewer"
        elif not company:
            state = "needs a model (which company's model it runs is unknown)"
        elif per_use_unapproved(pv):
            state = "costs money per use and has no recorded OK from the developer, so it is never used"
        elif not installed:
            state = f"not installed ('{provider_binary(pv)}' not found)"
        elif "ok" not in st_:
            state = "installed, not tested yet"
        else:
            state = ("working" if st_.get("ok") else "failing") + f": {st_.get('detail')} ({str(st_.get('at'))[:16]}Z)"
        rows.append({"id": pv["id"], "company": company, "model": pv.get("model"), "installed": installed,
                     "ok": bool(st_.get("ok")) and company not in (None, host) and not per_use_unapproved(pv),
                     "state": state, **({"prefer_for": pv["prefer_for"]} if pv.get("prefer_for") else {})})
    found = []
    paid_options = []
    if args.discover:
        known = {provider_binary(pv) for pv in plist}
        for name, pr in PRESETS.items():
            if pr["bin"] in known or not shutil.which(pr["bin"]):
                continue
            if pr["company"] and pr["company"] != host:
                pv = {"id": name, "preset": name}
                good, detail, _saved = probe_provider(ctx, cfg, pv)
                if good:
                    plist.append(pv)
                    _write_providers(ctx, plist)
                    rows.append({"id": name, "company": pr["company"], "model": None, "installed": True, "ok": True,
                                 "state": "working: added"})
                else:
                    rows.append({"id": name, "company": pr["company"], "model": None, "installed": True, "ok": False,
                                 "state": f"installed but failing: {detail}"})
            elif not pr["company"] and name not in MODEL_LISTERS:
                found.append(name)
            elif not pr["company"]:
                lines, fmt, raw = _list_tool_models(name)
                if fmt == "json" and raw:
                    try:
                        catalog = json.loads(raw)
                    except (ValueError, TypeError):
                        catalog = None
                    lines = _model_catalog_lines(catalog) if isinstance(catalog, dict) else []
                if not lines:
                    found.append(name)
                    continue
                have = {r["company"] for r in rows if r.get("ok")}
                picked = _pick_capable_listed_model(lines, host, have)
                if picked:
                    pv = {"id": f"{name}-{_model_family(_listed_model_name(picked))}", "preset": name,
                          "model": picked, "cost": "flat"}
                    good, detail, _saved = probe_provider(ctx, cfg, pv)
                    if good:
                        plist.append(pv)
                        _write_providers(ctx, plist)
                        rows.append({"id": pv["id"], "company": company_of_model(picked), "model": picked,
                                     "installed": True, "ok": True, "cost": "flat",
                                     "state": "working: added (flat-rate)"})
                    else:
                        rows.append({"id": pv["id"], "company": company_of_model(picked), "model": picked,
                                     "installed": True, "ok": False, "cost": "flat",
                                     "state": f"a flat-rate {name} model failed its test request: {detail}"})
                else:
                    # Every listed line was same-company, unmappable or a small/preview variant: nothing to
                    # probe, but the tool is still installed and signed in, so keep it reachable by hand.
                    found.append(name)
                for (provider, company), group_lines in _paid_candidate_groups(lines, host).items():
                    rep = _paid_pick(group_lines)
                    if not rep:
                        continue
                    cost = _listed_model_cost(rep)
                    label = "costs money per use" if cost == "per-use" else "cost unknown, treated as paid"
                    paid_options.append({"tool": name, "provider": provider,
                                         "model": _listed_model_name(rep), "add_model": rep, "cost": cost,
                                         "text": f"{label}; ask the developer before this is used."})
    if args.json:
        print(json.dumps({"host": host, "providers": rows, "needs_model": found, "paid_options": paid_options},
                         indent=2))
        return
    print(f"This agent runs on: {host}.")
    for r in rows:
        print(f"  {'✓' if r['ok'] else '·'} {r['id']:<10} {str(r['company'] or '?'):<10} {r['state']}")
    for name in found:
        print(f"  + {name:<10} {'?':<10} installed; it can run several companies' models. Pick a capable model from "
              f"a company other than {host} (the tool's own help lists them), then: "
              f"ratchet.py providers --add {name} --preset {name} --model <model>")
    for p in paid_options:
        print(f"  $ {p['tool']}/{p['provider']} {p['model']}: {p['text']}")
    if not any(r["ok"] for r in rows):
        print(f"No working provider from another company: reviews will come from {host}'s own models.")


# --------------------------------------------------------------------------- commands

# Which chat is running an engine command. The guard hook sees the chat (session id) of every shell call. When the
# command it is about to let run really invokes `ratchet.py init` or `ratchet.py ask` (parsed as shell words: the
# ratchet.py call must be a command of its own, never text inside quotes, an echo, a commit message, a comment or a
# heredoc), it notes that chat together with that call's exact arguments in the per-user folder (outside the repo,
# where agents can't write). The engine accepts a note only when the arguments equal its own, it is under
# ENGINE_NOTE_SECONDS old, and no other chat noted the same call; the note is then used up. `init` makes that chat
# the run's owner (on a repo's first run there is no human log yet to go by), and an `ask` while no chat owns the run
# makes the chat that asked the owner, so the user's reply in another chat can't answer the question or take the run.
# Without a usable note the engine falls back to the human log / prompt-hook owner rule (see _bind_owner).
ENGINE_NOTE_SECONDS = 60
_ENGINE_ARGV: list | None = None  # this process's own arguments (set by main)
_SHELL_OPS = set(";&|<>")
_ASSIGNMENT_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*=")


def _shell_words(cmd: str):
    """Split a shell command into ("word", text) and ("op", text) tokens the way a POSIX shell would for plain
    commands. None when it can't be read safely: unbalanced quotes, a heredoc or here-string, a command
    substitution (`...` / $(...)), or bash's $'...' quoting, whose contents this simple reader doesn't follow."""
    out, cur, i, n = [], None, 0, len(cmd)

    def flush():
        nonlocal cur
        if cur is not None:
            out.append(("word", cur))
        cur = None

    while i < n:
        c = cmd[i]
        if c in " \t\r":
            flush()
            i += 1
        elif c == "\\":
            if i + 1 < n and cmd[i + 1] != "\n":
                cur = (cur or "") + cmd[i + 1]
            i += 2
        elif c == "'":
            j = cmd.find("'", i + 1)
            if j < 0:
                return None
            cur = (cur or "") + cmd[i + 1:j]
            i = j + 1
        elif c == '"':
            j, buf = i + 1, ""
            while j < n and cmd[j] != '"':
                if cmd[j] == "\\" and j + 1 < n and cmd[j + 1] in '$`"\\\n':
                    buf += "" if cmd[j + 1] == "\n" else cmd[j + 1]
                    j += 2
                    continue
                if cmd[j] == "`" or cmd.startswith("$(", j):
                    return None
                buf += cmd[j]
                j += 1
            if j >= n:
                return None
            cur = (cur or "") + buf
            i = j + 1
        elif c == "`" or cmd.startswith("$(", i) or cmd.startswith("$'", i):
            return None  # $'...' (bash ANSI-C quoting) ends at an unescaped quote only: never read inside it
        elif c == "#" and cur is None:
            while i < n and cmd[i] != "\n":
                i += 1
        elif c in "\n()":
            flush()
            out.append(("op", c))
            i += 1
        elif c in _SHELL_OPS:
            if c in "<>" and cur is not None and cur.isdigit():
                cur = None  # `2>&1`: the digits name a file descriptor, not an argument
            flush()
            j = i
            while j < n and cmd[j] in _SHELL_OPS:
                j += 1
            op = cmd[i:j]
            if "<<" in op:
                return None
            out.append(("op", op))
            i = j
        else:
            cur = (cur or "") + c
            i += 1
    flush()
    return out


def _simple_commands(words) -> list:
    """The word lists of each simple command in `_shell_words` output (split at operators; redirection targets
    are left out)."""
    cmds, cur, skip = [], [], False
    for kind, text in words:
        if kind == "op" and ("<" in text or ">" in text):
            skip = True  # a redirection: the next word is its target, not an argument
        elif kind == "op":
            cmds.append(cur)
            cur, skip = [], False
        elif skip:
            skip = False
        else:
            cur.append(text)
    cmds.append(cur)
    return cmds


def _engine_invocations(cmd: str) -> list:
    """The argument lists of every `ratchet.py ...` call `cmd` would actually run as a command of its own
    (`python3 .../ratchet.py ...`, `.../ratchet.py ...` or `$RATCHET ...`). Text that only mentions ratchet.py (in
    quotes, after echo or grep, in a comment or heredoc) is not a call. An argument the shell would still expand
    ($VAR) makes the call unknowable, so it is left out."""
    words = _shell_words(cmd or "")
    if not words:
        return []
    found = []
    for w in _simple_commands(words):
        while w and _ASSIGNMENT_RE.match(w[0]):
            w = w[1:]
        if w and re.fullmatch(r"python[0-9.]*", Path(w[0]).name):
            w = w[1:]
            while w and w[0].startswith("-"):
                w = w[1:]
            if not (w and Path(w[0]).name == "ratchet.py"):
                continue
        elif not (w and (Path(w[0]).name == "ratchet.py" or w[0] in ("$RATCHET", "${RATCHET}"))):
            continue
        argv = w[1:]
        if argv and not any("$" in a for a in argv):
            found.append(argv)
    return found


def _engine_subcommand(argv) -> str | None:
    a = list(argv)
    while a and (a[0] == "--root" or a[0].startswith("--root=")):
        a = a[2:] if a[0] == "--root" else a[1:]
    return a[0] if a else None


def _engine_notes_path() -> Path:
    return ratchet_home() / "engine-call-sessions.json"


class _EngineNotesLock(_RecordLock):
    """A _RecordLock on engine-call-sessions.json, named the same way _record_lock_path names every other record's
    lock. update_record takes this lock itself (via its own _RecordLock) when _note_engine_call / _noted_session call
    it without a lock=; this class exists only so a lock on this one record can also be taken directly, the same way
    _RecordLock(path) does for any other record."""

    def __init__(self, wait: float = 2.0):
        super().__init__(_engine_notes_path(), wait)


def _note_fresh(note) -> bool:
    fresh = (_dt.datetime.now(_dt.timezone.utc) - _dt.timedelta(seconds=ENGINE_NOTE_SECONDS)).isoformat(
        timespec="microseconds")
    return (isinstance(note, dict) and isinstance(note.get("argv"), list) and isinstance(note.get("session"), str)
            and bool(note["session"]) and fresh < str(note.get("at", "")) <= _in_a_minute())


def _note_engine_call(root: Path, cmd: str, session: str | None, tool_input: dict | None = None):
    """Guard hook: for every `ratchet.py init` / `ask` / `wait` / `complete` / `integrate` call `cmd` really runs, note
    which chat is about to run it here, with its exact arguments. A `complete` or `integrate` note also carries the
    host's run_in_background and timeout for the call (`bg`, `timeout`), which that command reads to warn about a
    foreground run. Best effort;
    never blocks the call."""
    if not session:
        return
    calls = [a for a in _engine_invocations(cmd) if _engine_subcommand(a) in ("init", "ask", "wait", "complete", "integrate")]
    if not calls:
        return
    try:
        p = _engine_notes_path()

        def add(notes):
            for argv in calls:
                key = f"{root.resolve()}|{_engine_subcommand(argv)}"
                kept = [x for x in (notes.get(key) if isinstance(notes.get(key), list) else []) if _note_fresh(x)]
                note = {"session": session, "argv": argv, "at": now()}
                if _engine_subcommand(argv) in ("complete", "integrate"):
                    ti = tool_input if isinstance(tool_input, dict) else {}
                    note["bg"] = ti.get("run_in_background") is True
                    note["timeout"] = ti.get("timeout") if isinstance(ti.get("timeout"), (int, float)) else None
                notes[key] = kept + [note]
            return notes
        # can't be had: note nothing (the owner rules without a note apply); damaged (a crash mid-write, say): no
        # note in it counts, and this write replaces it
        _ = update_record(p, add, wait=2.0,
                          damaged="Ratchet treats it as holding no notes and replaces it with this call's note")
    except Exception:
        pass


def _noted_session(root: Path, which: str, whole: bool = False):
    """The chat the guard hook saw run exactly this `ratchet.py <which> ...` call (same arguments) in this project in
    the last ENGINE_NOTE_SECONDS. A matching note is used up; stale or malformed notes are dropped. None when there
    is no such note, or when more than one chat noted the same call (Ratchet can't tell which one this is).
    whole=True gives the whole note (a dict) instead of just its chat."""
    mine = list(_ENGINE_ARGV) if _ENGINE_ARGV is not None else list(sys.argv[1:])
    try:
        p = _engine_notes_path()
        key = f"{root.resolve()}|{which}"
        match = []

        def damaged(why):  # it names no chat; the guard hook's next note replaces it
            _note_unreadable(p, why, "Ratchet uses no note for this call (the rules without a note apply); the next "
                             "note the guard hook takes replaces the file")
            return KEEP

        def use(notes):
            if key not in notes:
                return KEEP
            raw = notes.get(key)
            live = [x for x in (raw if isinstance(raw, list) else []) if _note_fresh(x)]
            match.extend(x for x in live if [str(a) for a in x["argv"]] == mine)
            rest = [x for x in live if x not in match]
            if rest:
                notes[key] = rest
            else:
                notes.pop(key, None)
            return notes
        # can't be had: use no note and change nothing (the rules without a note)
        _ = update_record(p, use, wait=2.0, damaged=damaged)
    except Exception:
        return None
    sessions = {x["session"] for x in match}
    note = match[-1] if len(sessions) == 1 else None
    return note if whole or note is None else note["session"]


def cmd_init(args):
    root = find_root()
    ctx = Ctx(root)
    ctx.ratchet.mkdir(exist_ok=True)
    if not ctx.config_path.exists():
        cfg = {k: DEFAULT_CONFIG[k] for k in ["human_review", "host_provider", "ui_reviewers", "regression_command",
                                               "commit_per_checkpoint", "design_md", "standards", "app"]}
        write_json(ctx.config_path, cfg)
        full = ctx.config()
        host = detect_host(full)
        found = [pv["id"] for pv in providers(full) if provider_company(pv) not in (None, host)
                 and shutil.which(provider_binary(pv) or "")]
        print(f"Host provider: {host}" + (" (set host_provider in .ratchet/config.json)" if host == "unknown" else "")
              + ". Other providers installed: " + (", ".join(found) if found else "none found")
              + ". Run `ratchet.py providers --discover` to test them and add other agent CLIs.")
    learn = ctx.ratchet / "learnings.md"
    if not learn.exists():
        learn.write_text("# Ratchet learnings\n\nEvery Ratchet agent reads this file before starting work. "
                         "Entries come from human reviews and repeated gate failures.\n\n")
    gi = ctx.ratchet / ".gitignore"
    if not gi.exists() or gi.read_text(encoding="utf-8").startswith("manifests/"):
        # runtime state stays out of git: git stash/checkout/reset can't roll it back, and checkpoint commits
        # don't carry it. Only the files people edit and share are tracked.
        gi.write_text("*\n!.gitignore\n!config.json\n!standards.md\n!learnings.md\n", encoding="utf-8")
        if _is_git(root):
            tracked = subprocess.run(["git", "ls-files", RATCHET_DIR], cwd=root, capture_output=True,
                                     text=True).stdout.split()
            runtime = [f for f in tracked if f.split("/", 1)[-1] not in (".gitignore", "config.json", "standards.md",
                                                                        "learnings.md")]
            if runtime:
                subprocess.run(["git", "rm", "--cached", "-q", "--", *runtime], cwd=root, capture_output=True)
    existing = ctx.active_slug()
    if existing:
        old_st, why = _read_record(ctx.state_path(existing), missing=None)
        if why is not None:  # a damaged run is still the active one: it is only replaced with --force, by a person
            _note_unreadable(ctx.state_path(existing), why, "Ratchet treats that run as still active")
            old_st = {"phase": "unknown: its state.json can't be read"}
        if old_st and old_st.get("phase") not in ("done", "cancelled"):
            if not (args.force and human_override("replace the run that is still active", ctx,
                                                  f"init --force (replaced run {existing})")):
                die(f"Run '{existing}' is still active (phase {old_st['phase']}). Ask the user whether to resume it "
                    f"(ratchet.py resume) or cancel it (ratchet.py cancel, after they confirm). "
                    "A run is never replaced silently.")
    slug = args.slug or slugify(args.feature)
    rd = ctx.ratchet / "runs" / slug
    if rd.exists() and not args.force:
        die(f"Run {slug} already exists. Use --slug to pick another name.")
    dirty = []
    branch = None
    if _is_git(root):
        dirty = [l[3:] for l in subprocess.run(["git", "status", "--porcelain"], cwd=root, capture_output=True,
                                               text=True).stdout.splitlines() if l and not l[3:].startswith(RATCHET_DIR)]
        if args.branch:
            branch = f"ratchet/{slug}"
            r = subprocess.run(["git", "checkout", "-b", branch], cwd=root, capture_output=True, text=True)
            if r.returncode != 0:
                die(f"Could not create branch {branch}: {r.stderr.strip()}")
    (rd / "tests").mkdir(parents=True, exist_ok=True)
    (rd / "evidence").mkdir(exist_ok=True)
    human = [e for e in _human_since(ctx, "0") if e.get("session")]
    st = {
        "slug": slug, "feature": args.feature, "phase": "planning", "created_at": now(),
        "human_review": args.human_review or ctx.config()["human_review"],
        "current": None, "checkpoints": {}, "plan_hash": None, "awaiting_since": None,
        "history": [], "branch": branch, "dirty_at_start": dirty[:50],
        "owner_session": _noted_session(root, "init") or (human[-1]["session"] if human else None),
        "base_tree": fingerprint(root)["id"],
    }
    _write_record(rd / "state.json", st, pretty=True)
    record_chain(rd / "state.json")
    _write_record(ctx.ratchet / "active.json", {"slug": slug}, pretty=True)
    register_active(root, slug)
    ok(f"Initialised run '{slug}' at {rd.relative_to(root)}" + (f" on new branch {branch}" if branch else ""))
    if dirty:
        print(f"WARNING: {len(dirty)} uncommitted change(s) already in the working tree (e.g. {', '.join(dirty[:3])}). "
              "Checkpoint commits would include them — ask the user whether to commit, stash or keep them first.")
    print("NEXT: run `ratchet.py doctor` now to confirm this agent CLI's Ratchet hooks are firing.")
    print(json.dumps(next_action(ctx), indent=2))


OLD_DEFAULT_REVIEWERS = {
    "host-standards": {"kind": "agent", "lens": "standards", "vendor": "host"},
    "host-correctness": {"kind": "agent", "lens": "correctness", "vendor": "host"},
    "host-both": {"kind": "agent", "lens": "both", "vendor": "host"},
    **{f"{p}-{lens}": {"kind": "command", "preset": p, "lens": lens, "vendor": v}
       for p, v in [("claude", "anthropic"), ("codex", "openai"), ("gemini", "google"), ("copilot", "github")]
       for lens in ("correctness", "standards")},
}
# OLD_DEFAULT_REVIEW_DEPTH now lives in engine_utils.py, imported by name above.

# How to run each known agent CLI non-interactively. "company" is None for CLIs that can run several companies'
# models: for those the company comes from the chosen model. Flags differ between CLI versions; a provider entry
# can always give its own "command" instead ({prompt} {prompt_file} {out_file} {root} {model} are filled in).
PRESETS = {
    "claude": {"bin": "claude", "company": "anthropic", "stdin": True, "model_flag": ["--model"], "model_at": 1,
               "command": ["claude", "-p", "--no-session-persistence", "--setting-sources", ""]},
    "codex": {"bin": "codex", "company": "openai", "stdin": True, "model_flag": ["-m"], "model_at": 2,
              "command": ["codex", "exec", "--sandbox", "read-only", "--skip-git-repo-check",
                          "--output-last-message", "{out_file}", "-"]},
    "gemini": {"bin": "gemini", "company": "google", "stdin": True, "model_flag": ["-m"], "model_at": 1,
               "command": ["gemini", "-p", "Carry out the task described on stdin. Reply with only what it asks for."]},
    "copilot": {"bin": "copilot", "company": None, "stdin": False, "model_flag": ["--model"], "model_at": 1,
                "command": ["copilot", "-p", "{prompt}"]},
    "cursor": {"bin": "cursor-agent", "company": None, "stdin": False, "model_flag": ["--model"], "model_at": 1,
               # --trust: no workspace-trust prompt in headless runs; --mode ask: read-only, cannot edit files
               "command": ["cursor-agent", "-p", "{prompt}", "--output-format", "text", "--trust", "--mode", "ask"]},
    # The review prompt goes on stdin (opencode joins piped stdin to the message), so its size never meets the
    # command-line limit; the short message only says what to do with it. --format json prints an event stream, of
    # which only the text events are the answer; --variant (the provider's own `variant`, default low) asks for low
    # thinking, which opencode applies only to models that define that variant (it ignores it for the others, such as
    # GLM and Kimi). The fixed --title keeps opencode from sending the whole prompt a second time, in the background,
    # just to name the session.
    "opencode": {"bin": "opencode", "company": None, "stdin": True, "model_flag": ["-m"], "model_at": 2,
                 "command": ["opencode", "run", "Carry out the task described on stdin. Reply with only what it asks for.",
                             "--format", "json", "--title=ratchet review"],
                 "variant_flag": "--variant", "variant_default": "low",
                 # the test request's session is titled for what it is, so it is told apart in OpenCode's session list
                 # (probe_provider drops the review title when it adds this one, so --title is given once)
                 "probe_args": ["--title=connectivity check"]},
    "omp": {"bin": "omp", "company": None, "stdin": False, "model_flag": ["--model"], "model_at": 1,
            "command": ["omp", "-p", "--no-session", "{prompt}"]},
    "pi": {"bin": "pi", "company": None, "stdin": False, "model_flag": ["--model"], "model_at": 1,
           "command": ["pi", "-p", "--no-session", "{prompt}"]},
}
SHIPPED_DEFAULT_HISTORY = {"review_depth": [OLD_DEFAULT_REVIEW_DEPTH], "reviewers": [OLD_DEFAULT_REVIEWERS]}
PRESET_BINARIES = {k: v["bin"] for k, v in PRESETS.items()}
PRESET_VENDORS = {k: v["company"] for k, v in PRESETS.items()}
_B = r"(?:^|[^a-z0-9])"   # start of a name part
_E = r"(?:$|[^a-z])"      # end of a name part (digits may follow, as in gpt5 or o3)
MODEL_COMPANIES = [
    (_B + r"(claude|opus|sonnet|haiku|anthropic)" + _E, "anthropic"),
    (_B + r"(gpt|codex|chatgpt|openai)" + _E + r"|" + _B + r"o[1-9](?:$|[^a-z0-9]|-)", "openai"),
    (_B + r"(gemini|gemma|google)" + _E, "google"), (_B + r"(grok|xai)" + _E, "xai"),
    (_B + r"(glm|zhipu|z-ai|zai)" + _E, "zhipu"), (_B + r"(qwen|alibaba)" + _E, "alibaba"),
    (_B + r"deepseek" + _E, "deepseek"), (_B + r"(kimi|moonshot)" + _E, "moonshot"),
    (_B + r"(llama|meta)" + _E, "meta"), (_B + r"(mistral|codestral|devstral|magistral)" + _E, "mistral"),
]
COMPANY_ALIASES = {"claude": "anthropic", "claude-code": "anthropic", "codex": "openai", "gpt": "openai",
                   "chatgpt": "openai", "gemini": "google", "deepmind": "google", "google deepmind": "google",
                   "copilot": "github", "grok": "xai", "x.ai": "xai", "mistral ai": "mistral", "z.ai": "zhipu",
                   "meta ai": "meta"}


def norm_company(c) -> str | None:
    if not c:
        return None
    c = str(c).strip().lower()
    return COMPANY_ALIASES.get(c, c)
LENSES = ("correctness", "standards", "both")


def company_of_model(model) -> str | None:
    m = str(model or "").lower()
    if not m:
        return None
    for rx, company in MODEL_COMPANIES:
        if re.search(rx, m):
            return company
    return None


# A multi-company preset (today: opencode, omp) can list what it can reach without spending anything, so discovery
# can pick a capable other-company model itself instead of leaving it to "needs_model". MODEL_LISTERS: preset
# name -> the read-only command that prints "provider/model" lines, one per line. PROVIDER_COST: the service
# namespace before a listed model's first "/" -> "flat" (a subscription already paid for) or "per-use" (billed
# per request); a namespace missing from this table is unknown and is treated as paid, never probed without the
# developer's OK. Both are small fixed tables, not a live price lookup (out of scope for this checkpoint).
MODEL_LISTERS = {
    "opencode": (["opencode", "models"], 20),
    "omp": (["omp", "models", "--json"], 20, "json"),
}
PROVIDER_COST = {
    "opencode-go": "flat",     # OpenCode Go: flat-rate subscription
    "opencode": "per-use",     # OpenCode Zen: billed per request
    "openrouter": "per-use",   # OpenRouter: billed per request
    "openai-codex": "flat",    # Codex via omp: the developer's own signed-in subscription, already paid for
}
# When more than one other-company flat model is available, these families win: GLM and Kimi have been this
# project's working reviewers so far. A short ordered tuple of name substrings, not a live quality ranking;
# any company whose models don't match one just ties at "no preference" and falls back to the existing
# "no working reviewer yet, then listing order" rule.
FAMILY_PREFERENCE = ("glm", "kimi")
# Words that mark a listed model as never-pick, whatever picker is asking: a speed/preview/open-weight
# sibling of a company's flagship (flash, mini, nano, lite, small, haiku, free, preview, oss, gemma) or a
# model that cannot write a text review at all (guard: safety classifier; image/vision: image generation;
# embed/tts/audio: not a chat model). A table, not one hand-built regex, so it stays easy to extend. Matched
# as a name token with _B/_E (so "5-small-2603" matches but "smaller-than-life" as a whole word wouldn't
# apply here since these are name tokens, not prose) and prefixes included: "[a-z]*" after the word lets a
# suffix like "flashx" or "liteweight" still match on its "flash"/"lite" prefix.
REJECT_WORDS = ("flash", "mini", "nano", "lite", "small", "haiku", "free", "preview", "oss", "gemma",
                "guard", "image", "vision", "embed", "tts", "audio")
_REJECT_VARIANT_RX = re.compile(_B + r"(?:" + "|".join(REJECT_WORDS) + r")[a-z]*" + _E)


def _is_rejected_variant(line: str) -> bool:
    return bool(_REJECT_VARIANT_RX.search(line.lower()))


def _is_model_line(line: str) -> bool:
    """True for a line shaped like 'provider/model' (non-empty text on both sides of the first '/'), the
    shape every real model-listing command prints, one per line. A banner, warning or table line on stdout
    has no such shape and is never a model candidate, flat or paid."""
    provider, sep, rest = line.partition("/")
    return bool(sep) and bool(provider.strip()) and bool(rest.strip())


def _model_catalog_lines(data) -> list[str]:
    """Pull 'provider/model' lines out of an already-parsed {"models": [{"provider": ..., "id": ...,
    "selector": "<provider>/<id>"}, ...]} catalog (omp's `models --json` shape). Falls back to building
    "<provider>/<id>" when a model has no selector of its own. A shape without a usable models list, or no
    line shaped like 'provider/model', is just an empty list, the same contract as the plain-lines listing.
    Takes already-parsed data, never text: the one place that may parse that text into JSON is
    cmd_providers, the only caller of _list_tool_models (see _CP5R11_JSON_PARSE in test_trust_cp5_d.py)."""
    models = data.get("models") if isinstance(data, dict) else None
    if not isinstance(models, list):
        return []
    lines = []
    for m in models:
        if not isinstance(m, dict):
            continue
        sel = m.get("selector")
        if not sel:
            provider, mid = m.get("provider"), m.get("id")
            sel = f"{provider}/{mid}" if provider and mid else None
        if sel and _is_model_line(str(sel)):
            lines.append(str(sel))
    return lines


def _list_tool_models(preset_name) -> tuple[list[str], str, str]:
    """Run a multi-company preset's read-only model-listing command. Returns (lines, fmt, raw).
    When the MODEL_LISTERS entry names the "lines" format, `lines` already holds its 'provider/model' lines
    (dropping any line that isn't shaped like one) and `raw` is "". When it names the "json" format (omp's
    catalog), `lines` is [] and `raw` carries the raw stdout text for the caller (cmd_providers) to parse
    with _model_catalog_lines, because cmd_providers is the sanctioned place to parse JSON that is not one
    of Ratchet's own records. A listing failure (not installed, times out, non-zero exit, no output) is
    just ([], fmt, ""): the caller falls back to today's needs_model line, never a crash and never a
    garbage candidate."""
    spec = MODEL_LISTERS.get(preset_name)
    if not spec:
        return [], "lines", ""
    cmd, timeout = spec[0], spec[1]
    fmt = spec[2] if len(spec) > 2 else "lines"
    if not shutil.which(cmd[0]):
        return [], fmt, ""
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, stdin=subprocess.DEVNULL)
    except (OSError, subprocess.TimeoutExpired):
        return [], fmt, ""
    if r.returncode != 0:
        return [], fmt, ""
    if fmt == "json":
        return [], fmt, r.stdout or ""
    lines = [ln.strip() for ln in (r.stdout or "").splitlines() if ln.strip()]
    return [ln for ln in lines if _is_model_line(ln)], fmt, ""


def _listed_model_cost(line: str) -> str:
    """flat / per-use / unknown for one listed 'provider/model' line, by its service namespace (PROVIDER_COST).
    Missing from the table means unknown, treated as paid."""
    return PROVIDER_COST.get(line.split("/", 1)[0], "unknown")


def _listed_model_name(line: str) -> str:
    """The model name shown to the developer for a listed line, its service namespace stripped: 'opencode/
    gpt-5.1-codex' -> 'gpt-5.1-codex', 'openrouter/z-ai/glm-5' -> 'z-ai/glm-5' (only the first '/' is removed)."""
    return line.split("/", 1)[1] if "/" in line else line


def _model_family(model_name: str) -> str:
    """The short family name used to build a new provider id ('glm-5.3' -> 'glm'): the first non-numeric token
    of the model name, so 'opencode-glm' reads naturally next to 'opencode-glm-flash' etc."""
    for part in re.split(r"[^a-z0-9]+", model_name.lower()):
        if part and not part[0].isdigit():
            return part
    return "model"


def _family_rank(line: str) -> int:
    """Where a listed line's model name falls in FAMILY_PREFERENCE (0 = most preferred); a name matching
    none of the preferred families ranks after all of them, at len(FAMILY_PREFERENCE)."""
    name = line.lower()
    for i, fam in enumerate(FAMILY_PREFERENCE):
        if fam in name:
            return i
    return len(FAMILY_PREFERENCE)


def _model_version_key(model_name: str) -> tuple:
    """The "newest version" ranking key, shared by every picker that compares a company's models
    (_best_capable_line, used by both the flat auto-pick and each paid entry): every number in the model
    name (after the namespace), as a flat tuple of per-component integers, so '5.10' sorts above '5.9'
    (comparing them as floats would do the opposite). A number stuck to a unit letter ('120b', '31b', a
    parameter count) is dropped, and so is a date-shaped number (a lone 4-digit group such as '2507' or
    '2603', or a 6-8 digit date) -- neither is a version, and left in, a date reliably outranks a real,
    smaller version number."""
    stripped = re.sub(r"\d+(?:\.\d+)?[bmkt](?=$|[^a-z0-9])", "", model_name, flags=re.I)
    stripped = re.sub(r"(?<!\d)\d{4}(?!\d)|(?<!\d)\d{6,8}(?!\d)", "", stripped)
    return tuple(int(p) for n in re.findall(r"\d+(?:\.\d+)?", stripped) for p in n.split("."))


def _best_capable_line(lines) -> str | None:
    """The one line among a single company's listed lines that discovery may offer as a reviewer, flat or
    paid: this is the ONE shared ranking used by both the flat auto-pick and each paid entry, so a company
    is never offered a weaker model one way than the other. A line matching the reject-words table
    (_is_rejected_variant) is never a candidate, full stop -- there is no fallback to a rejected line, so a
    company whose only listed models are all rejected variants is simply not offered, flat or paid. Among
    the survivors, the highest real version wins (_model_version_key); there is no further tie-break (in
    particular, no name-length tie-break: a longer, suffixed name must never win just by being longer).
    None if every line was rejected."""
    survivors = [ln for ln in lines if not _is_rejected_variant(ln)]
    if not survivors:
        return None
    return max(survivors, key=lambda line: _model_version_key(_listed_model_name(line)))


def _pick_capable_listed_model(lines, host, have_companies=()) -> str | None:
    """The one listed 'provider/model' line discovery may itself test and add: flat-rate, a company Ratchet's
    patterns recognise (company_of_model) that isn't the host's own, and capable (_best_capable_line). An
    unknown company or an unknown/per-use cost is never a candidate here. Prefers a company with no working
    reviewer yet (`have_companies`), then the preferred family order (FAMILY_PREFERENCE), then falls back to
    listing order; within one company, _best_capable_line picks the representative."""
    by_company: dict[str, list[str]] = {}
    for line in lines:
        if _listed_model_cost(line) != "flat":
            continue
        company = company_of_model(line)
        if not company or company == host:
            continue
        by_company.setdefault(company, []).append(line)
    reps = {c: _best_capable_line(ls) for c, ls in by_company.items()}
    reps = {c: rep for c, rep in reps.items() if rep}
    if not reps:
        return None
    order = list(reps)
    company = min(order, key=lambda c: (
        c in have_companies, min(_family_rank(ln) for ln in by_company[c]), order.index(c)))
    return reps[company]


def _paid_candidate_groups(lines, host) -> dict:
    """Non-flat ('per-use' or unknown-cost) listed lines, grouped by (provider namespace, company), so a
    provider with many listed models (hundreds of OpenRouter lines, say) collapses to one representative
    per company instead of flooding paid_options. The host's own company is dropped (never offered as a
    paid option to pay for a model the host already runs for free). In a namespace PROVIDER_COST already
    prices (a known paid service such as opencode/ or openrouter/), a model whose company Ratchet can't map
    is skipped: Ratchet never uses an unknown-company model as a reviewer, so naming one here would just ask
    the developer to pay for something the engine would then refuse. A namespace PROVIDER_COST doesn't know
    at all (an unlisted provider) still lists its unmappable models as before, grouped under "", so an
    unknown provider isn't silently dropped."""
    groups: dict[tuple[str, str], list[str]] = {}
    for line in lines:
        if _listed_model_cost(line) == "flat":
            continue
        namespace = line.split("/", 1)[0]
        company = company_of_model(line) or ""
        if company and company == host:
            continue
        if not company and namespace in PROVIDER_COST:
            continue
        groups.setdefault((namespace, company), []).append(line)
    return groups


def _paid_pick(group_lines) -> str | None:
    """The one line from a (provider, company) group to show as that group's paid option: the same shared
    ranking the flat picker uses (_best_capable_line), so a paid entry is never named for a model the flat
    picker itself would have rejected. None if the whole group was rejected variants, in which case the
    caller must show no paid option for that group rather than suggest paying for a rejected model."""
    return _best_capable_line(group_lines)


def providers(cfg) -> list[dict]:
    return [pv for pv in (cfg.get("providers") or []) if isinstance(pv, dict) and pv.get("id")]


def provider_by_id(cfg, pid) -> dict | None:
    return next((pv for pv in providers(cfg) if pv["id"] == pid), None)


def per_use_unapproved(pv) -> bool:
    """True for a provider whose cost label is anything but flat-rate (per-use, or any label Ratchet cannot call
    free) and that carries no paid_ok_at: the developer never gave the exact OK for its model, so it is never chosen
    for a review and never sent a request, not even a test request. A provider with no cost label is not in this
    class (it keeps working as it always did)."""
    return bool(pv) and pv.get("cost") not in (None, "", "flat") and not pv.get("paid_ok_at")


def _cost_tier(pv) -> int:
    """0 for a provider that is not per-use (flat-rate, or no cost label: a subscription CLI such as codex has none),
    1 for a per-use provider (reached only with the developer's recorded OK, always after every tier 0 one)."""
    return 0 if pv.get("cost") in (None, "", "flat") else 1


def _reviewer_cost_tier(cfg, spec) -> int:
    """The cost tier of the provider behind a roster spec (0 for a reviewer with no provider: a host reviewer, or a
    hand-written one)."""
    pv = provider_by_id(cfg, spec.get("provider")) if spec.get("provider") else None
    return _cost_tier(pv) if pv is not None else 0


def ranked_provider_ids(cfg, lens, health=None) -> list[str]:
    """Every provider id, best first for a slot of `lens`: any that is not per-use (flat-rate or no cost label) before
    a per-use one, and inside that first tier a provider that prefers the lens (`prefer_for`, set with providers --add
    --prefer-for) before one that does not, then the fewest review starts in the shared record's recent hours (any
    lane, any project), then flat-rate before no cost label, then the one picked longest ago (a round replaced
    unreviewed gives its starts back but keeps this time), then the order written in config. This is only an order:
    whether a provider can be used right now (installed, not out, per-use with the developer's OK) is
    reviewer_availability's call."""
    health = provider_health() if health is None else health
    at = _dt.datetime.now(_dt.timezone.utc)

    def key(item):
        i, pv = item
        starts = phealth.recent_starts(health, _health_key(pv), at)
        last = phealth.last_picked(health, _health_key(pv), at)  # a replaced unreviewed round keeps it: rotation goes on
        return (_cost_tier(pv), 0 if lens in (pv.get("prefer_for") or []) else 1, len(starts),
                0 if pv.get("cost") == "flat" else 1, last, i)
    return [pv["id"] for _i, pv in sorted(enumerate(providers(cfg)), key=key)]


def provider_company(pv) -> str | None:
    if pv.get("company"):
        return norm_company(pv["company"])
    from_model = company_of_model(pv.get("model"))
    if from_model:
        return from_model
    return (PRESETS.get(pv.get("preset", "")) or {}).get("company")


def provider_binary(pv) -> str | None:
    if pv.get("command"):
        return str(pv["command"][0])
    return (PRESETS.get(pv.get("preset", "")) or {}).get("bin")


def provider_command(pv) -> tuple[list[str], bool]:
    """(command template, prompt on stdin?) of a provider: its own `command` (or its preset's) with the model filled
    in. A preset's command also gets the model flag and the thinking-cap arguments appended (_variant_args: the
    provider's `variant`, else the preset's default, "none" sends nothing); an own `command` is used as written."""
    preset = PRESETS.get(pv.get("preset", "")) or {}
    if pv.get("command"):
        cmd = [str(c).replace("{model}", str(pv.get("model") or "")) for c in pv["command"]]
        return cmd, bool(pv.get("stdin", False))
    cmd = list(preset.get("command") or [])
    if pv.get("model") and cmd:
        at = preset.get("model_at", 1)
        cmd = cmd[:at] + list(preset.get("model_flag") or ["--model"]) + [str(pv["model"])] + cmd[at:]
    return cmd + _variant_args(preset, pv), bool(preset.get("stdin", False))


def _variant_args(preset, pv) -> list[str]:
    """The thinking-cap arguments of a preset that has one (opencode): the provider's `variant`, else the preset's
    default (low); the value "none" sends nothing."""
    flag = preset.get("variant_flag")
    value = str((pv or {}).get("variant") or preset.get("variant_default") or "none")
    return [flag, value] if flag and value != "none" else []


def roster(cfg) -> dict:
    """Every reviewer id: the host's own sub-agents, any reviewer written in config 'reviewers', and three per
    provider (<id>-correctness / -standards / -both)."""
    out = dict(cfg.get("reviewers") or {})
    for pv in providers(cfg):
        for lens in LENSES:
            out.setdefault(f"{pv['id']}-{lens}", {"kind": "command", "provider": pv["id"], "lens": lens,
                                                  "vendor": provider_company(pv), "model": pv.get("model"),
                                                  "for_risk": pv.get("for_risk")})
    return out


def _roster_spec(cfg, rid):
    r = roster(cfg)
    if rid in r:
        return r[rid]
    m = re.fullmatch(r"([a-z0-9_.-]+)-(correctness|standards|both)", rid or "")
    if m and m.group(1) in PRESETS:  # an older config naming a preset reviewer that isn't a provider any more
        return {"kind": "command", "preset": m.group(1), "lens": m.group(2), "vendor": PRESETS[m.group(1)]["company"]}
    return None


def reviewer_command(cfg, rid) -> tuple[list[str], bool]:
    """(command template, prompt on stdin?) of a reviewer: its provider's (provider_command), a reviewer's own
    `command` as written, or an older preset reviewer's preset command with the preset's default variant added."""
    spec = _roster_spec(cfg, rid) or {}
    if spec.get("provider"):
        return provider_command(provider_by_id(cfg, spec["provider"]) or {})
    if spec.get("command"):
        return [str(c) for c in spec["command"]], bool(spec.get("stdin", False))
    preset = PRESETS.get(spec.get("preset", "")) or {}
    return list(preset.get("command") or []) + _variant_args(preset, None), bool(preset.get("stdin", False))


def host_model_map(cfg) -> dict:
    return ((cfg.get("host_models") or {}).get(detect_host(cfg)) or {})


def role_model(cfg, role) -> str:
    tier = (cfg.get("role_models") or {}).get(role, "inherit")
    if tier in ("strong", "standard", "light"):
        return host_model_map(cfg).get(tier) or "inherit"
    if tier == "alternate":  # a different model from the session's, for work that must not share its blind spots
        return (host_model_map(cfg).get("alternates") or ["inherit"])[0]
    return tier or "inherit"
HOST_HINTS = [  # environment variables the common agent CLIs set for the tools they run
    ("anthropic", ("CLAUDECODE", "CLAUDE_CODE_ENTRYPOINT")),
    ("openai", ("CODEX_SANDBOX", "CODEX_THREAD_ID", "CODEX_SANDBOX_NETWORK_DISABLED")),
    ("google", ("GEMINI_CLI",)),
    ("github", ("COPILOT_CLI", "GITHUB_COPILOT_CLI")),
]


HOST_ALIASES = {"claude": "anthropic", "claude-code": "anthropic", "codex": "openai", "gpt": "openai",
                "gemini": "google", "copilot": "github"}


def detect_host(cfg=None) -> str:
    explicit = os.environ.get("RATCHET_HOST_PROVIDER") or (cfg or {}).get("host_provider", "auto")
    if explicit and explicit != "auto":
        return norm_company(explicit)
    for vendor, keys in HOST_HINTS:
        if any(os.environ.get(k) for k in keys):
            return vendor
    return "unknown"


def default_review_depth():  # noqa: E302
    return json.loads(json.dumps(DEFAULT_CONFIG["review_depth"]))


def _unavailable_path(ctx):
    return ctx.ratchet / "unavailable-reviewers.json"


_UNAVAILABLE_DAMAGED = "Ratchet treats every reviewer as available"


def _live_unavailable(data: dict) -> dict:
    t = now()
    return {k: v for k, v in data.items() if isinstance(v, dict) and str(v.get("until", "")) > t}


def unavailable_reviewers(ctx) -> dict:
    return _live_unavailable(read_json(_unavailable_path(ctx), {}, record=_UNAVAILABLE_DAMAGED) or {})


def _update_unavailable(ctx, change, note: bool = True, lock=None) -> str:
    """Change unavailable-reviewers.json (`change(live)` edits its unexpired entries in place; expired ones are
    dropped). More than one command can update it (`reviewer-status`, a probe, a failed review), so it is changed
    only through update_record, under its own lock (or `lock`, that lock already held by the caller); a damaged
    one marks no reviewer and is replaced. Returns update_record's result. A caller that must not then claim the
    change was saved checks for "busy" itself and refuses with _die_record_busy, passing note=False so this does not
    also print a stderr note for the same busy write: reviewer-status --reset and --mark (through mark_unavailable)
    do this, and a checked `providers --add` takes this lock itself first (see _record_probe). A best-effort caller
    leaves note=True, so the stderr note below speaks for it."""
    p = _unavailable_path(ctx)

    def fn(data):
        live = _live_unavailable(data)
        change(live)
        return live
    res = update_record(p, fn, lock=lock, damaged=_UNAVAILABLE_DAMAGED, pretty=True)
    if res == "busy" and note:
        _note_record_busy(p, "this change to the unavailable reviewers")
    return res


def mark_unavailable(ctx, rid, reason, hours=None, note: bool = True, lock=None, quota: bool = False):
    """Marks `rid` unavailable until `hours` from now (returns that time), unless unavailable-reviewers.json's lock
    is busy, when nothing is saved and this returns None (reviewer_status's --mark checks for that and dies, with
    note=False so _update_unavailable's own stderr note does not also print). `lock`: as _update_unavailable.
    `quota`: the mark is a wait for a provider out of credits (a passing test request does not clear it)."""
    hours = hours if hours is not None else float(ctx.config().get("unavailable_ttl_hours", 6))
    until = (_dt.datetime.now(_dt.timezone.utc) + _dt.timedelta(hours=hours)).isoformat(timespec="microseconds")
    mark = {"reason": reason[:300], "since": now(), "until": until}
    if quota:
        mark["quota"] = True
    res = _update_unavailable(ctx, lambda live: live.__setitem__(rid, mark), note=note, lock=lock)
    return None if res == "busy" else until


def reviewer_availability(ctx, cfg, rid, risk=None) -> tuple[bool, str]:
    spec = _roster_spec(cfg, rid)
    if spec is None:
        return False, "not defined (config 'providers' or 'reviewers')"
    if spec.get("kind") == "agent":
        if spec.get("alt"):
            alts = host_model_map(cfg).get("alternates") or []
            if not alts:
                return False, f"this agent can't pick a different model here (no host_models.alternates for {detect_host(cfg)})"
            return True, f"sub-agent of the host on a different model ({' or '.join(alts)})"
        return True, f"sub-agent of the host ({detect_host(cfg)})"
    host = detect_host(cfg)
    if not spec.get("vendor"):
        return False, "which company's model it runs is unknown — give it a model or a company"
    if spec.get("vendor") == host:
        return False, f"same company as the host ({host}) — not an independent reviewer"
    if risk and spec.get("for_risk") and risk not in spec["for_risk"]:
        return False, f"not set up for {risk}-risk steps (for_risk: {', '.join(spec['for_risk'])})"
    if per_use_unapproved(provider_by_id(cfg, spec.get("provider"))):
        return False, ("costs money per use and the developer has not given the exact OK for this model "
                       "(no paid_ok_at), so it is never used or sent a request")
    binary = reviewer_binary(cfg, rid) or ""
    if not binary or not shutil.which(binary):
        return False, f"'{binary or spec.get('preset')}' CLI not installed"
    down = unavailable_reviewers(ctx).get(rid) if ctx else None
    if down is None:  # a provider another lane found failing is out here too, until its bench ends
        down = provider_bench(cfg, rid)
    if down:
        return False, f"failed recently ({down['reason']}); retry after {down['until'][:16]}Z"
    return True, f"{binary} on PATH"


def _host_fallbacks(cfg, rid) -> list[str]:
    """The host's company on a different model first, then the host itself; same lens first, then the others,
    so a fallback keeps the reviewer COUNT."""
    lens = (_roster_spec(cfg, rid) or {}).get("lens", "both")
    order = [lens] + [x for x in ("both", "correctness", "standards") if x != lens]
    r = roster(cfg)
    return [f"host-alt-{x}" for x in order if f"host-alt-{x}" in r] + [f"host-{x}" for x in order if f"host-{x}" in r]


def expand_slot(cfg, slot, health=None) -> list[str]:
    """The reviewer ids a slot may use, in the order they are tried. An explicit id keeps the place it was written
    in; any-<lens> becomes the providers' reviewers for that lens in ranked_provider_ids order (cost tier, lens
    preference, fewest recent starts), then the host's own."""
    alts = list(slot) if isinstance(slot, list) else [slot]
    out = []
    for a in alts:
        m = re.fullmatch(r"any-(correctness|standards|both)", str(a))
        if m:
            out += [f"{pid}-{m.group(1)}" for pid in ranked_provider_ids(cfg, m.group(1), health)]
            out += [f"host-alt-{m.group(1)}", f"host-{m.group(1)}"]
        else:
            out.append(a)
    return out


def reviewer_binary(cfg, rid):
    spec = _roster_spec(cfg, rid) or {}
    if spec.get("kind") != "command":
        return None
    cmd, _ = reviewer_command(cfg, rid)
    return cmd[0] if cmd else None


def _dup_key(spec):
    """(vendor, model, lens) for a command-kind reviewer, so two slots that resolve to the same company, model
    and lens collapse into one reviewer instead of running twice. When no explicit model is set, the provider/tool
    id is folded into the key instead, so two different CLIs from the same company (each picking its own default
    model) are never collapsed as duplicates — only the same tool, with the same unspecified model and lens,
    collapses. None for a host (`agent`) reviewer, or an unknown one, which never collapses this way."""
    if not spec or spec.get("kind") != "command":
        return None
    model = spec.get("model")
    return (spec.get("vendor"), model if model else ("tool", spec.get("provider") or spec.get("preset")),
            spec.get("lens"))


def resolve_reviewers(ctx, cfg, cp, exclude=None, taken=None, only_slots=None, share=None) -> list[dict]:
    """Turn review slots into concrete reviewer ids for THIS round.

    Returns [{"id", "slot", "fallback_for": [ids skipped], "reasons": {...}}]. An any-<lens> slot tries the
    providers best first (ranked_provider_ids: not per-use, then per-use with the developer's recorded OK; the provider
    that prefers the lens; the fewest recent review starts machine-wide; flat-rate before no cost label); an explicit
    slot list keeps the order it was written in. A provider of a company not yet reviewing this round comes before a
    repeat, but only inside the first candidate's cost tier (it never lifts a per-use provider); a
    per-use provider with no recorded OK is never picked; the host's own sub-agents fill any slot whose other
    providers are unavailable, after every other working provider (ranked the same way). A slot whose own pick turns out to be the
    same company, model and lens as a reviewer an earlier slot already chose collapses (no entry): that review
    already runs once, not twice, under a different id.

    `exclude`: reviewer ids never picked even though reviewer_availability still calls them okay — a reply cut
    off mid-answer twice this round falls back only its own slot, without the long-lived unavailable_ttl_hours
    mark a genuine quota/auth/timeout failure gets (see cmd_reviewers' same-round branch).

    `taken`: reviewer ids that other slots of the round already run (the surviving slots of a same-round refill).
    They count as already chosen, so a refilled slot never repeats one of them, nor the same company, model and
    lens under another id.

    `only_slots`: slot numbers to resolve; every other slot is skipped (a same-round refill resolves only the slots it
    replaces, so a kept slot's own pick can't use up a provider a replaced slot needs).

    `share`: {"data": the shared provider record, "ignore": start ids not to count}. A provider that already has
    provider_share.max review starts inside the last provider_share.minutes (read from that record, any lane, plus the
    picks this call has made) is skipped for the slot, with a plain reason, and the slot goes to the next working
    provider. Pass the record read under its lock (_reserve_under_lock) when the picks are about to be reserved; None
    applies no share (a round already open is only shown, never counted again).
    """
    exclude = exclude or set()
    health = share["data"] if share is not None else provider_health()  # the shared record: starts spread the slots
    cap, tentative, at = (provider_share(cfg) if share is not None else None), {}, _dt.datetime.now(_dt.timezone.utc)

    def over_share(rid_):  # why the provider behind rid_ takes no more starts right now, else None
        key = _reviewer_health_key(cfg, rid_) if cap else None
        if key is None:
            return None
        n = phealth.starts_within(health, key, at, cap[1], share["ignore"]) + tentative.get(key, 0)
        if n < cap[0]:
            return None
        win = _minutes_text(cap[1])
        return (f"it already has {n} review start{'' if n == 1 else 's'} in the last {win}, and a provider takes at "
                f"most {cap[0]} per {win} across all lanes on this machine")
    if cp.get("reviewers"):
        slots = list(cp["reviewers"])
    else:
        depth = cfg.get("review_depth") or {}
        slots = depth.get(cp.get("risk", "normal")) or depth.get("normal")
        if not slots:  # legacy config: "adversaries": N
            slots = ["host-both"] if int(cfg.get("adversaries", 2)) == 1 else ["host-standards", "host-correctness"]
    roster_ = {rid: _roster_spec(cfg, rid) for rid in set(roster(cfg)) | {a for sl in slots for a in expand_slot(cfg, sl, health)}}
    roster_ = {k: v for k, v in roster_.items() if v is not None}
    risk = cp.get("risk", "normal")
    chosen, chosen_keys, out = set(), set(), []
    for t in taken or ():
        chosen.add(t)
        if _dup_key(_roster_spec(cfg, t)) is not None:
            chosen_keys.add(_dup_key(_roster_spec(cfg, t)))
    for n, slot in enumerate(slots, 1):
        if only_slots is not None and n not in only_slots:
            continue
        alts = expand_slot(cfg, slot, health)
        unknown = [a for a in alts if a not in roster_]
        if unknown:
            die(f"review_depth/checkpoint names unknown reviewer(s) {unknown}; add them under config 'providers' "
                "or 'reviewers'.")
        if all(roster_[a].get("kind") == "command" for a in alts):
            if not any(a not in exclude and reviewer_availability(ctx, cfg, a, risk)[0] and not over_share(a)
                       for a in alts):
                # every provider the slot lists is out: other working providers (same lens) before the host
                lens = roster_[alts[0]].get("lens", "both")
                for pid_ in ranked_provider_ids(cfg, lens, health):
                    rid_ = f"{pid_}-{lens}"
                    if (rid_ in roster_ and rid_ not in alts and rid_ not in exclude
                            and reviewer_availability(ctx, cfg, rid_, risk)[0] and not over_share(rid_)):
                        alts.append(rid_)
            alts += _host_fallbacks(cfg, alts[0])
        skipped, reasons, pick, candidates = [], {}, None, []
        for a in alts:
            if a in chosen:
                continue
            okay, why = reviewer_availability(ctx, cfg, a, risk)
            if okay and a in exclude:
                okay, why = False, "failed a review earlier this round"
            if okay and over_share(a):
                okay, why = False, over_share(a)
            if okay:
                candidates.append(a)
            else:
                skipped.append(a)
                reasons[a] = why
        used_vendors = {roster_[c].get("vendor") for c in chosen if roster_[c].get("kind") == "command"}
        # A company not yet reviewing is preferred only among candidates of the first candidate's cost tier, so it never
        # lifts a per-use provider over a usable one that is not (the candidates are already in ranked order)
        best = _reviewer_cost_tier(cfg, roster_[candidates[0]]) if candidates else None
        fresh = [c for c in candidates if roster_[c].get("kind") == "command" and roster_[c].get("vendor") not in used_vendors
                 and _reviewer_cost_tier(cfg, roster_[c]) == best]
        pick = fresh[0] if fresh else (candidates[0] if candidates else None)
        if pick and candidates and pick != candidates[0]:
            skipped.append(candidates[0])
            reasons[candidates[0]] = "provider already reviewing this round; preferring a different one"
        if pick is not None:
            dup_key = _dup_key(roster_[pick])
            if dup_key is not None and dup_key in chosen_keys:
                skipped.append(pick)
                reasons[pick] = "same company, model and lens as a reviewer already chosen this round; runs once"
                pick = None
        if pick is None:
            continue  # every alternative already used, down, or a duplicate: slot collapses into the others
        chosen.add(pick)
        dup_key = _dup_key(roster_[pick])
        if dup_key is not None:
            chosen_keys.add(dup_key)
        if cap and _reviewer_health_key(cfg, pick):  # this pick takes one start of its provider's share
            tentative[_reviewer_health_key(cfg, pick)] = tentative.get(_reviewer_health_key(cfg, pick), 0) + 1
        spec = roster_[pick]
        model = spec.get("model") if spec.get("kind") == "command" else (
            "a different model: " + " or ".join(host_model_map(cfg).get("alternates") or []) if spec.get("alt")
            else role_model(cfg, "ratchet-adversary"))
        out.append({"id": pick, "slot": n, "vendor": spec.get("vendor"), "model": model,
                    "fallback_for": [x for x in skipped if x in alts and alts.index(x) < alts.index(pick)],
                    "reasons": reasons})
    if not out and not taken:
        die("No adversarial reviewer is available for this checkpoint — check config 'providers' and 'reviewers'.")
    return out


def required_reviewers(cfg, cp, ctx=None) -> list[str]:
    return [r["id"] for r in resolve_reviewers(ctx, cfg, cp)]


def _plan_hash(plan, ctx=None):
    body = {"cps": plan.get("checkpoints")}
    if ctx is not None:  # the test plans are part of what the user approves
        # A checkpoint missing "id" is a plan problem (caught by validate_plan), not a reason to crash here:
        # fall back to its position so every other command that hashes the plan can still run.
        body["tests"] = {c.get("id", f"#{i}"): test_plan(ctx, c.get("id", f"#{i}"))
                         for i, c in enumerate(plan.get("checkpoints", []) or [])}
    return hashlib.sha1(json.dumps(body, sort_keys=True).encode()).hexdigest()[:12]


PLAN_ASK_NEXT = ("NEXT: settle any other question or offer with the user first, in its own turn. Then show them the "
                 "whole plan, run `ratchet.py ask approve-plan` and end that message with the question it prints, word "
                 "for word, as the only question in it. End your turn. Only their first reply after that question "
                 "counts, and only a listed yes approves; a yes from before the question does not count. Ratchet "
                 "can't see your message, so a yes meant for another question in it would still count.")
def _after_next(text: str) -> str:
    """A `NEXT: ...` line as a sentence of its own (for next_action, which says what is waiting first)."""
    body = text[len("NEXT: "):] if text.startswith("NEXT: ") else text
    return body[:1].upper() + body[1:]


REVIEW_ASK_NEXT = ("Settle any other question or offer first, in its own turn. Then run `ratchet.py ask human-approve` "
                   "and end your message with the question it prints, word for word, as the only question in it, then "
                   "end your turn. Only their first reply after that question counts: run `ratchet.py human-approve` "
                   "only if it is one of the listed yes replies. If they ask for changes instead, run "
                   "`ratchet.py feedback`.")


def cmd_plan_submit(args):
    """Validates a new plan and moves the run to awaiting_plan_approval. Refused as "Plan invalid" (nothing
    saved, so approve-plan has nothing to approve) for a shape error, a missing objective, a spec gap, a missing
    risk_reason, a bad "proves" number, or, since the done-means-proven run, an objective.done_means line that no
    test-plan case's "proves" names (unlinked_done_means_problems: each such line named by number and text).
    plan-extend applies that last check only to the lines feedback added since the approval snapshot, so a plan
    approved before it keeps working."""
    ctx = Ctx(find_root())
    st = ctx.state()
    if st["phase"] not in ("planning", "awaiting_plan_approval"):
        die(f"plan-submit only allowed while planning (phase is {st['phase']}). Use plan-extend for feedback.")
    plan = ctx.plan()
    if plan is None:
        die("checkpoints.json not found in the run folder")
    errs = (validate_plan(plan) + objective_problems(plan) + spec_plan_problems(ctx, plan)
            + risk_reason_problems(plan.get("checkpoints", [])) + proves_problems(ctx, plan)
            + unlinked_done_means_problems(ctx, plan))
    if errs:
        die("Plan invalid:\n  - " + "\n  - ".join(errs))
    st["phase"] = "awaiting_plan_approval"
    st["awaiting_since"] = now()
    if (st.get("pending") or {}).get("action") == "approve-plan":
        st.pop("pending", None)  # a question about an earlier version of the plan no longer applies
    st["plan_hash"] = _plan_hash(plan, ctx)
    st["checkpoints"] = {cp["id"]: st["checkpoints"].get(cp["id"]) or new_cp_state(cp)
                         for cp in plan["checkpoints"]}
    ctx.log(st, "plan_submitted", hash=st["plan_hash"], count=len(plan["checkpoints"]))
    ctx.save_state(st)
    path = build_viewer(ctx)
    link = viewer_link(ctx)
    ok(f"Plan valid ({len(plan['checkpoints'])} checkpoints).")
    print(f"VIEWER: {link['url']}" + ("" if link["live"] else "   (static; `ratchet.py view --serve` for a live link)"))
    print(PLAN_ASK_NEXT)
    if args.open:
        webbrowser.open(link["url"]) if link["live"] else open_viewer(path)


def _in_a_minute():
    return (_dt.datetime.now(_dt.timezone.utc) + _dt.timedelta(minutes=1)).isoformat(timespec="microseconds")


def _human_since(ctx: Ctx, since_iso: str | None):
    log = ctx.ratchet / "human_log.jsonl"
    if not log.exists() or not since_iso:
        return []
    if _IN_HOOK:  # a hook never exits over it: a log Ratchet can't vouch for holds no message (it grants nothing)
        if chain_problem(log, "human_log.jsonl"):
            return []
    else:
        verify_chain(log, "human_log.jsonl")
    out = []
    recs, _why = _read_record(log, lines=True)  # can't be read: no message (it grants nothing)
    for e in recs or []:
        if e.get("override"):
            continue  # an override audit line is not something the user typed in the chat
        at = e.get("at", "")
        if isinstance(at, str) and since_iso < at <= _in_a_minute():  # a timestamp from the future is forged
            out.append(e)
    return out


def _chat_transcript_paths(ctx: Ctx, since_iso: str | None) -> set[str]:
    """Repo-relative paths a genuine, Ratchet-recorded human reply (human_log.jsonl, hash-chained: not a bare
    claim) used as its transcript since `since_iso`. The agent CLI's own chat transcript is never the code under
    review, so a gate must not go stale only because it changed (a reply recorded between a gate passing and
    `complete` otherwise would, if the transcript happens to live inside the project, as the CLI chooses, not
    Ratchet)."""
    out = set()
    for e in _human_since(ctx, since_iso or "0"):
        tp = e.get("transcript_path")
        if not tp:
            continue
        try:
            rel = str(Path(tp).resolve().relative_to(ctx.root.resolve())).replace("\\", "/")
        except (OSError, ValueError):
            continue
        out.add(rel)
    return out


# ---- director-signed approvals -------------------------------------------------------
# A director (an orchestrator running many lanes) holds a secret key OUTSIDE every repo.
# It signs one specific pause of one specific run; the lane verifies the signature.
# Builder sessions cannot read the key or call the signing commands (PreToolUse guard),
# and an enrolled lane stops accepting chat messages as approvals — because in a
# director setup the "user" messages a builder receives come from the director.

def director_key_path() -> Path:
    return Path(os.environ.get("RATCHET_DIRECTOR_KEY_FILE") or ratchet_home() / "director.key")


def _director_key(required=True) -> bytes | None:
    p = director_key_path()
    if not p.exists():
        if required:
            die(f"No director key at {p}. The director creates it with: ratchet.py director-key")
        return None
    try:
        return p.read_bytes().strip()
    except OSError as e:  # a folder where the key goes, say: no key (chat approvals stay refused for enrolled lanes)
        if required:
            die(f"The director key at {p} can't be read ({type(e).__name__}: {e.strerror or e}). The director "
                "creates a new one with: ratchet.py director-key --rotate")
        return None


def _is_director_session() -> bool:
    """The bare environment check. Trusted as is only inside a hook (whose environment is the agent CLI's own);
    director commands go through require_director_session, which also asks what the hooks recorded."""
    return os.environ.get("RATCHET_ROLE") == "director"


# ---- who counts as the director ---------------------------------------------------------------------------
# RATCHET_ROLE=director in the environment proves nothing on its own: a builder can write a script that sets it and
# run that script with a clean-looking command the guard can't see into. The guard hook, which runs right before
# every command any session runs and has that agent CLI's own launch-time environment, records the role of the
# session that last ran a command in each project (.ratchet/hook-env.json, `guard_role`) and, for a director whose
# folder holds no .ratchet/, that folder in the per-user folder (director-folders.json). Director commands then
# need the hooks to agree.

def _director_folders_path() -> Path:
    return ratchet_home() / "director-folders.json"


def record_director_folder(folder: Path) -> bool:
    """Called by the guard of a director session whose folder has no .ratchet/: remember that folder. Returns False
    when it could not be saved (run_hook then says so; the director commands refuse without the record)."""
    try:
        key = os.path.realpath(str(folder))
        p = _director_folders_path()

        def damaged(why):  # invalid JSON, or not a JSON object: it grants nothing; this write replaces it (other
            # folders are recorded again the next time their director's guard runs there)
            _note_unreadable(p, why, "Ratchet treats it as naming no director folder and replaces it now")
            return {}

        def add(data):
            if key in data:
                return KEEP
            data[key] = now()
            return data
        # shared by every director session on this machine: under its own lock, so none drops another's folder; when
        # the lock can't be had, nothing is saved and the hook reports it like any record it could not save
        return update_record(p, add, damaged=damaged) in ("written", "kept")
    except (OSError, ValueError):
        return False


def _recorded_guard_role(root: Path | None) -> str | None:
    """'director' / 'builder' as the guard last recorded for `root`, None when no guard has run a command there
    (or there is no project), 'unreadable' when the record can't be read."""
    if root is None:
        return None
    rec, why = _read_record(_hook_env_path(root), missing=None)
    if rec is None and why is None:
        return None
    if why is not None:  # damaged (or not a JSON object): it confirms no role
        return "unreadable"
    recs = _hook_env_records(root)  # the newest guard record at the moment of reading (record_hook_env)
    if recs is None:
        return "unreadable"
    guards = [r for r in recs if r[1] == "guard"]
    role = guards[-1][2] if guards else rec.get("guard_role")
    return role if role in ("director", "builder") else (None if role is None else "unreadable")


DIRECTOR_NO_HOOKS_NOTE = (
    "RATCHET: note: Ratchet's hooks are not installed for any agent CLI here (and none has enforced anything here), "
    "so nothing records which session is the director and RATCHET_ROLE=director is taken at its word. Nothing else "
    "is enforced without hooks either; install them (the install-hooks command) so director commands need a "
    "hook-recorded director session.")


def director_session_problem(what: str) -> str | None:
    """None when this process may act as the director; otherwise a plain reason. Fail closed: RATCHET_ROLE=director
    counts only with a positive record from a director session's own guard hook. The one exception is when Ratchet's
    hooks are not installed at all (for any agent CLI), because then nothing is recorded or enforced anyway
    (require_director_session says so on stderr). Installed hooks with a missing record (none has run yet, or its
    write failed) are refused."""
    return _director_session_check(what)[0]


def _director_session_check(what: str):
    """(problem or None, note or None) for director_session_problem / require_director_session."""
    if not _is_director_session():
        return f"{what} must be run from the director's session (RATCHET_ROLE=director).", None
    if _IN_HOOK:
        return None, None
    here = Path.cwd().resolve()
    own = _ratchet_root_of(here)
    for r in (own, find_root()):  # a failed record write leaves the OLD role in place: trust no record meanwhile
        doubt = _hook_record_doubt(r) if r is not None and (r / RATCHET_DIR).is_dir() else None
        if doubt:
            return (f"{what} refused: {doubt} in {r}, so the role its hooks recorded may be out of date (a failed "
                    "write leaves the old record, which may name a director that no longer runs commands there). "
                    "Director commands are refused until that hook runs cleanly. Run the doctor command to see the "
                    "failure, make sure .ratchet/ is writable, then send any message or run any command in the "
                    "director's agent CLI so its hooks record the role again."), None
    if own is not None:
        own_role, where = _recorded_guard_role(own), own
    else:
        folders, _why = _read_record(_director_folders_path())  # damaged: it names no director folder
        own_role = "director" if isinstance(folders, dict) and os.path.realpath(str(here)) in folders else None
        where = here
    if own_role == "director":
        return None, None
    target = find_root()
    if own_role is None:
        own_role, where = _recorded_guard_role(target), target
        if own_role is None:
            if not hooks_in_use(here, own, target):
                return None, DIRECTOR_NO_HOOKS_NOTE  # no hooks at all: nothing is recorded or enforced anyway
            return (f"{what} refused: RATCHET_ROLE=director is set, and Ratchet's hooks are installed (or have run "
                    "here), but no hook "
                    f"has recorded a director session in {here} (or in {target}): the record is missing, either "
                    "because the director's agent CLI has not run a command here since its hooks were installed, "
                    "or because a hook could not save it. Ratchet does not take the variable at its word while "
                    "hooks are installed. Restart the director's agent CLI (started with RATCHET_ROLE=director) "
                    "so its hooks record the role, and run director commands from it in its own folder, reaching "
                    "a lane with --root <lane>. If it keeps failing, check that .ratchet/ (or, for a folder with no "
                    ".ratchet/, the per-user folder) is writable: the hook says so when it can't save the record."), None
    if own_role == "unreadable":
        return (f"{what} refused: {_hook_env_path(where)} can't be read, so Ratchet can't confirm this is the "
                "director's session. Delete it; the next hook run (send any message in your agent CLI) writes it "
                "again."), None
    return (f"{what} refused: RATCHET_ROLE=director is set, but Ratchet's guard hook last ran a command in {where} "
            "for a session that was not started as the director, so this is not treated as the director's session "
            "(a builder setting the variable, for example in a script, gets nothing from it). Run director commands "
            "from the director's own agent CLI, started with RATCHET_ROLE=director and with Ratchet's hooks "
            "installed, in its own folder, and reach a lane with --root <lane>."), None


def require_director_session(what: str):
    why, note = _director_session_check(what)
    if why:
        die(why)
    if note:
        print(note, file=sys.stderr)


def _approval_payload(ctx, st, action, bind=()) -> str:
    """What a director token signs: this lane, run, phase and pause (`awaiting_since`, which every `ask` moves, so
    a token signed before a re-ask is stale), the plan, the action, and `bind`: the details the action must match
    exactly (raise-limit binds the step and the reason, choice binds the letter), so a token for one step, reason
    or letter can never be applied to another."""
    parts = [str(ctx.root.resolve()), st["slug"], st["phase"], str(st.get("awaiting_since")),
             str(st.get("plan_hash")), action]
    if action == "hooks-waive":  # single use: the counter moves on every waive/clear, so a spent token is dead
        parts.append(str(st.get("hooks_waive_n", 0)))
    parts.extend(str(b) for b in bind)
    return "|".join(parts)


def _sign(key: bytes, payload: str) -> str:
    return hmac.new(key, payload.encode(), hashlib.sha256).hexdigest()


def _enrolled_path() -> Path:
    return ratchet_home() / "enrolled.json"


def _enrolled_repair(p: Path) -> str:
    return (f"restore it from a backup or fix the JSON by hand; or move it aside (mv \"{p}\" \"{p}.damaged\") and "
            "have the director run director-enroll again for every lane it drives")


def _enrolled_outside(ctx) -> str | None:
    """When this lane was enrolled with a director, from the per-user enrolled.json (the backstop that keeps a lane
    enrolled when its own director.json is removed). A damaged file holds a restriction Ratchet can no longer read,
    so it keeps it: while a director key exists on this machine, every project without a director.json of its own
    counts as possibly enrolled (chat replies approve nothing) until a person repairs the file; director-enroll
    never writes over it. With no director key there is no director to approve anything, so it names no lane."""
    p = _enrolled_path()
    data, why = _read_record(p)
    if why is None:
        return data.get(str(ctx.root.resolve()))
    try:
        key_here = director_key_path().exists()
    except OSError:  # can't tell: keep the restriction
        key_here = True
    if key_here:
        _note_unreadable(p, why, "it holds which lanes a director enrolled, so Ratchet treats this project as "
                         "enrolled (chat replies approve nothing; a director token still does) until it is "
                         "repaired. To repair it: " + _enrolled_repair(p))
        return "unreadable"
    _note_unreadable(p, why, "no director key exists on this machine, so Ratchet treats it as naming no enrolled "
                     "lane. To repair it: " + _enrolled_repair(p))
    return None


def approval_mode(ctx) -> str:
    p = ctx.ratchet / "director.json"
    enr, why = _read_record(p, missing=None)
    if why is not None:  # it exists, so this lane was enrolled: a damaged enrollment keeps refusing chat approvals
        _note_unreadable(p, why, "Ratchet still treats this lane as enrolled with a director (chat replies approve "
                         "nothing); the director enrolls it again with director-enroll")
        return "director"
    if not enr and _enrolled_outside(ctx):
        return "director"  # enrollment file deleted from the repo: still enrolled
    if enr:
        key = _director_key(required=False)
        if key and hmac.compare_digest(enr.get("sig", ""), _sign(key, "enroll|" + str(ctx.root.resolve()))):
            return "director"
        if key:
            die(".ratchet/director.json has an invalid signature — re-enroll this lane from the director.")
        return "director"  # enrolled, key not on this machine: still refuse chat approvals
    return ctx.config().get("approver", "human")


def _content_text(c) -> str:
    """Text of a message's content: a string, or a list of text parts (Claude, Codex, Gemini shapes)."""
    if isinstance(c, str):
        return c
    if isinstance(c, list):  # only text parts: tool results, images and the like are not something the user typed
        return "\n".join(_content_text(x) for x in c
                         if isinstance(x, str) or (isinstance(x, dict) and x.get("type", "text") in ("text", "input_text")))
    if isinstance(c, dict):
        for k in ("text", "input_text", "content", "message"):
            if isinstance(c.get(k), (str, list)):
                return _content_text(c[k])
    return ""


def _user_turns(obj):
    """Yield (text, timestamp) for every user turn in one parsed transcript record. Only records that clearly say
    they are the user's count; anything without a user role is ignored."""
    if isinstance(obj, list):
        for x in obj:
            yield from _user_turns(x)
        return
    if not isinstance(obj, dict):
        return
    for key in ("messages", "history", "items"):  # whole-file transcripts (e.g. Gemini's JSON session file)
        if isinstance(obj.get(key), list):
            yield from _user_turns(obj[key])
    msg = obj.get("message")
    ts = obj.get("timestamp") or obj.get("time") or (msg.get("timestamp") if isinstance(msg, dict) else None)
    if isinstance(msg, dict) and msg.get("role") == "user" and obj.get("type") in (None, "user"):  # Claude Code
        yield _content_text(msg.get("content")), ts
        return
    payload = obj.get("payload")
    if isinstance(payload, dict):  # Codex rollout
        if payload.get("type") == "user_message":
            yield _content_text(payload.get("message")), ts
        elif payload.get("type") == "message" and payload.get("role") == "user":
            yield _content_text(payload.get("content")), ts
        return
    if obj.get("role") in ("user", "human") or obj.get("type") in ("user", "human"):
        if "content" in obj or "text" in obj or isinstance(msg, str):
            yield _content_text(obj.get("content", obj.get("text", msg))), ts


def _norm_text(t: str) -> str:
    return " ".join((t or "").split())


def _transcript_ok(entry: dict, since: str | None) -> tuple[bool, str]:
    """Is this logged message a real user turn in the agent CLI's own transcript, typed after `since`?
    The transcript record must parse, say it is the user's, and hold the WHOLE message (whitespace aside)."""
    tp = entry.get("transcript_path")
    if entry.get("host") == "copilot" and not tp:
        return True, "copilot hooks carry no transcript"
    if not tp or not Path(tp).exists():
        return False, "no transcript to check it against"
    try:
        with open(tp, "rb") as f:
            f.seek(0, 2)
            size = f.tell()
            f.seek(max(0, size - 8_000_000))
            text = f.read().decode("utf-8", "replace")
    except OSError as e:
        return False, f"transcript unreadable ({e})"
    want = _norm_text(entry.get("prompt") or "")
    if not want:
        return False, "empty message"
    records = []
    try:
        records.append(json.loads(text))  # a whole-file JSON transcript
    except json.JSONDecodeError:
        for line in text.splitlines():
            try:
                records.append(json.loads(line))
            except json.JSONDecodeError:
                continue  # a line that is not a record proves nothing
    seen = False
    for rec in records:
        for said, ts in _user_turns(rec):
            if _norm_text(said) != want:
                continue
            seen = True
            if ts and since and _iso(ts) < _iso(since) - 90:
                continue  # an old message replayed as a new one
            return True, "found in transcript"
    return False, ("only an older copy is in the transcript" if seen
                   else "not found as a user turn in the transcript")


def _iso(ts) -> float:
    try:
        if isinstance(ts, (int, float)):
            return ts / 1000 if ts > 1e12 else float(ts)
        return _dt.datetime.fromisoformat(str(ts).replace("Z", "+00:00")).timestamp()
    except ValueError:
        return 0.0


def _require_approval(ctx, st, action, token=None, bind=()):
    """Returns {"by": "human"|"director", "detail": ...} or dies. `bind` is what the director token must also
    match (see _approval_payload): a token signed for another step, reason or letter is refused as not matching."""
    mode = approval_mode(ctx)
    if token:
        if mode == "human":
            die("This lane only accepts human approvals (approver=human). A director must enroll it first.")
        key = _director_key()
        if not hmac.compare_digest(token, _sign(key, _approval_payload(ctx, st, action, bind))):
            die("Director token does not match this run's current pause (wrong lane, wrong action, stale token, "
                "or the run moved on" + (", or it was signed for a different step, reason or letter" if bind else "")
                + "). Ask the director to sign again.")
        return {"by": "director", "detail": f"director-signed {action}"}
    if mode == "director":
        sign = f"director-sign {action}"  # the command that actually signs this action, whole
        if action == "raise-limit":
            sign += f" {bind[0] if bind else '<CPn>'} --reason \"<why>\""
        elif action == "choice":
            opts = (st.get("pending") or {}).get("options") or []
            sign += " <one of " + ", ".join(opts) + ">" if opts else " <letter>"
        die("This lane is director-enrolled: approvals need a director token "
            f"(director runs: ratchet.py --root {ctx.root} {sign}"
            + (f", or signs and applies it in one step with `{_director_apply_cmd(ctx, action, bind[0] if action != 'choice' and bind else None)}`"
               if action in DIRECTOR_APPLY_ACTIONS else "")
            + "). Chat messages do not count as approvals here.")
    if human_override(f"approve this pause ({action})", ctx, action):
        return {"by": "human", "detail": "(RATCHET_HUMAN_OVERRIDE, code typed back at the terminal)"}
    p = st.get("pending") or {}
    if action in ASKED_APPROVALS:
        return _asked_reply(ctx, st, action, p)
    # what is left: hooks-waive (its own exact list, first reply only) and feedback (any text). Either way only the
    # run's own chat counts (the hooks question's chat for hooks-waive).
    msgs = _replies(ctx, st, st.get("awaiting_since"), p if p.get("action") == action else None)
    if action == "feedback":
        # When the review question was asked at this pause, the reply that answered (or spent) it is the feedback,
        # not whatever the user typed later.
        q = p if p.get("action") == "human-approve" else (st.get("spent_question") or {})
        if q.get("action") == "human-approve" and q.get("asked_at") and (
                q is p or q["asked_at"] == st.get("awaiting_since")):
            msgs = _replies(ctx, st, q["asked_at"], q)[:1]
    if p.get("action") == "hooks-waive" and action != "hooks-waive":
        # the first reply after the hooks question is its answer, whatever it says ("Any other reply means no"),
        # so it can never double as anything else
        after = [m for m in msgs if m.get("at", "") > p.get("asked_at", "")]
        if after:
            msgs = [m for m in msgs if m is not after[0]]
    if action == "hooks-waive":
        msgs = msgs[:1]  # only the FIRST reply after the hooks question answers it
    if msgs:
        entry = msgs[-1]
        last = entry.get("prompt", "")
        if action == "hooks-waive" and hooks_waive_intent(last) != "approve":
            st.pop("pending", None)  # spent: a later yes must not turn this no into consent
            ctx.save_state(st)
            die(f"The user's reply to the hooks question was not a clear yes: \"{last[:120]}\". Nothing was "
                "recorded. Only the exact reply \"" + HOOKS_WAIVE_REPLY + "\" (or a listed equivalent) counts. If they "
                "still want to skip hooks, run `ratchet.py ask hooks-waive` again and show them the question it "
                "prints word for word.")
        if ctx.config().get("verify_transcripts", True):
            good, why = _transcript_ok(entry, st.get("awaiting_since"))
            if not good:
                die(f"Couldn't confirm that reply came from the user ({why}). Ask the user to reply again in this "
                    "chat; if it keeps failing, `ratchet.py doctor` shows whether the prompt hook is installed.")
        return {"by": "human", "detail": last[:200], "session": entry.get("session")}
    die("No human message recorded since Ratchet started waiting for the user. Ask them, end your turn and wait "
        "for their reply; approval must come from them. If they have already replied, Ratchet's prompt hook is not "
        "running in this agent CLI, so their reply could not be recorded: run `ratchet.py doctor --json` and follow "
        "the hooks steps in the orchestrator skill.")


# Approvals that answer a question Ratchet printed (`ratchet.py ask <action>`). The user's FIRST reply after that
# question is the answer, and only a listed yes (APPROVAL_REPLIES) approves. hooks-waive has its own exact list,
# feedback takes any text and a lettered choice takes a letter, so they are not in here.
ASKED_APPROVALS = ("approve-plan", "human-approve", "cancel", "set-review", "approve-changes", "claim", "ui-respec")


def _pq(p):
    """(mode, target) of a pending question. `mode` is the argument the follow-up command takes; `target` is what
    the question is about (accept-line: the line numbers, sorted and comma-joined). A pending written before
    `target` existed kept accept-line's line numbers in `mode`: read them as the target."""
    if "target" not in p and p.get("action") == "accept-line":
        return None, p.get("mode") or None
    return p.get("mode") or None, p.get("target") or None


def _ask_cmd(action, mode=None, eng="ratchet.py", target=None) -> str:
    """The `ask` command that prints this question again: it takes the target when there is one, else the mode."""
    if action == "paid-provider" and mode and ":" in mode:
        tool, model = mode.split(":", 1)  # `mode` is stored as "tool:model"; the real command takes two args
        return f"`{eng} ask paid-provider {tool} {model}`"
    arg = target or mode
    return f"`{eng} ask {action}{' ' + str(arg) if arg else ''}`"


def _ask_now(ctx, st, action) -> str:
    """The `ask` command that prints `action`'s question now, for a hint where no question of it is waiting.
    `ask accept-line` needs line numbers, so a bare one would die: name the lines unproven right now."""
    if action == "accept-line":
        try:
            nums = [e["number"] for e in (done_means_table(ctx, ctx.plan() or {"checkpoints": []}, st) or [])
                    if e.get("verdict") == "unproven"]
        except Exception:
            nums = []
        if nums:
            return _ask_cmd(action, target=",".join(str(i) for i in nums))
    return _ask_cmd(action)


def _question_what(action, mode=None, target=None) -> str:
    """The question `ask <action>` put to the user, in the words it used ("shall I <this>?")."""
    if action == "set-review":
        return f"change how often they review to: {REVIEW_MODE_WORDS.get(mode, mode)}"
    if action == "paid-provider" and mode and ":" in mode:
        tool, model = mode.split(":", 1)
        return (f"use {tool}'s {model} (costs money per use, or whose cost is unknown, treated the same way) "
                "for reviews instead of only flat-rate ones")
    if action == "accept-line" and target:
        nums = [int(t) for t in str(target).split(",") if t.strip().isdigit()]
        if nums:
            return (f"accept done-means {_lines_word(nums)} as unproven, with your own reason, so "
                    f"{'they' if len(nums) != 1 else 'it'} no longer {'hold' if len(nums) != 1 else 'holds'} the finish")
    return ASKABLE.get(action, action)


def _question_session(st, p=None):
    """The chat whose replies can answer a question: the one recorded when it was asked (for `claim`, the chat that
    asked to take the run over), else the run's owner chat. None while no chat owns the run yet."""
    return (p or {}).get("session") or st.get("owner_session")


def _replies(ctx, st, since, p=None):
    """Human messages after `since` typed in the question's own chat. A message from another chat never answers (or
    spends) a question asked here, and so never moves the run to that chat: only `resume --claim` does that. There is
    no fallback to every chat: while no chat is known, only a message that carries no chat id at all counts (from an
    agent CLI that sends none, where Ratchet can't tell chats apart); a message from any identified chat makes that
    chat the owner first (the prompt hook records it, and Ctx.state binds it under the command's lock), so it never
    answers a question unbound."""
    sess = _question_session(st, p)
    return [m for m in _human_since(ctx, since) if m.get("session") == sess]


def _spend_question(ctx, st, reply=""):
    """The question got its one answer and it was not a yes: close it, so a later yes can't count. awaiting_since is
    left at the question, so `feedback` can still record the change request in that same reply."""
    p = st.pop("pending", None) or {}
    st["spent_question"] = {"action": p.get("action"), "asked_at": p.get("asked_at"), "session": p.get("session")}
    ctx.log(st, "question_not_approved", action=p.get("action"), reply=reply[:200])
    ctx.save_state(st)


def _asked_reply(ctx, st, action, p):
    """The user's answer to the question `ask <action>` printed, or die. Only their first reply after it counts."""
    want = p.get("action")
    if want != action:
        if want:
            wm, wt = _pq(p)
            what = _question_what(want, wm, wt)
            die(f"A different question is waiting for the user's answer: shall I {what}? Their reply answers THAT "
                f"question, not this one. If they said yes to it, run `ratchet.py {_pending_followup(want, wm)}"
                "`. If they said no or moved on, run `ratchet.py ask withdraw`. Then print this question "
                f"with {_ask_now(ctx, st, action)}, show it to them word for word, and wait for their reply.")
        die(f"Ratchet has not asked the user this question yet, so no reply counts as their answer. Run "
            f"{_ask_now(ctx, st, action)}, show them the question it prints word for word, and end your turn. Only their first "
            "reply after the question counts; a yes from before it does not.")
    asked = p.get("asked_at")
    again = _ask_cmd(action, _pq(p)[0], target=_pq(p)[1])
    if p.get("phase") and p["phase"] != st.get("phase"):
        _spend_question(ctx, st)
        die(f"That question was asked while the run was {PHASE_PLAIN.get(p['phase'], p['phase'])}; it is now "
            f"{PHASE_PLAIN.get(st.get('phase'), st.get('phase'))}, so it no longer applies. Nothing was approved. If "
            f"you still need their yes, print the question again ({again}).")
    if p.get("overtook"):
        _spend_question(ctx, st)
        die(f"This question was printed while another one (shall I {_question_what(p['overtook'], p.get('overtook_mode'), p.get('overtook_target'))}"
            "?) was still waiting for the user's first reply, so their reply could be meant for either. Nothing was "
            f"approved and the question is closed. Print it again on its own ({again}), with no other question or "
            "offer in that message, and wait for their reply.")
    msgs = _replies(ctx, st, asked, p)  # only the chat the question was asked in can answer it
    if not msgs:
        die("No human message recorded in this run's chat since the question was printed (a message typed in another "
            "chat never answers it). End your turn and wait for the user's reply; approval must come from them. If "
            "they have already replied, Ratchet's prompt hook is not running in this agent CLI, so their reply could "
            "not be recorded: run `ratchet.py doctor --json` and follow the hooks steps in the orchestrator skill.")
    entry = msgs[0]  # the first reply answers the question; later messages never do
    reply = entry.get("prompt", "")
    if not is_listed_yes(reply):
        _spend_question(ctx, st, reply)
        die(f"The user's first reply after the question was not one of the listed yes replies ({listed_yes_text()}): "
            f"\"{reply[:120]}\". Nothing was approved, and the question is closed, so a later yes does not count. "
            "Answer what they said or make the change they asked for. If you still need their yes, print the question "
            f"again ({again}), show it to them word for word, and wait for their reply.")
    if ctx.config().get("verify_transcripts", True):
        good, why = _transcript_ok(entry, asked)
        if not good:
            _spend_question(ctx, st, reply)
            die(f"Couldn't confirm that reply came from the user ({why}). Nothing was approved. Print the question "
                f"again ({again}) and ask them to reply in this chat; if it keeps failing, `ratchet.py doctor` shows "
                "whether the prompt hook is installed.")
    return {"by": "human", "detail": reply[:200], "session": entry.get("session")}


def _require_human(ctx, st, action="human-approve", token=None):
    a = _require_approval(ctx, st, action, token)
    return {"prompt": a["detail"], "by": a["by"], "session": a.get("session")}


def cmd_director_key(args):
    require_director_session("director-key")
    p = director_key_path()
    if p.exists() and not args.rotate:
        ok(f"Director key exists: {p}")
        return
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(secrets.token_hex(32) + "\n")
    os.chmod(p, 0o600)
    ok(f"Director key {'rotated' if args.rotate else 'created'}: {p}  (re-enroll lanes after a rotation)")


def _enroll_lane(root: Path):
    """Enrolls the lane folder `root` with the director: its signature into RATCHET_HOME/enrolled.json (under that
    file's lock; never over a file that can't be read) and .ratchet/director.json in the lane. Dies with the reason
    when it cannot (nothing is then written)."""
    ep = _enrolled_path()
    lane = str(root.resolve())
    bad, signed = [], []

    def damaged(why):  # it holds other lanes' enrollment: never replace it with this lane's alone
        bad.append(why)
        return KEEP

    def add(outside):
        signed.append(_sign(_director_key(), "enroll|" + lane))
        outside[lane] = signed[0]
        return outside
    # shared by every lane on this machine: changed only under its own lock, so two lanes enrolled at once both stay
    done = update_record(ep, add, damaged=damaged, pretty=True)
    if bad:
        die(f"Ratchet's record of enrolled lanes ({ep}) can't be read ({bad[0]}). It keeps every lane a director "
            "enrolled in director mode even if that lane's .ratchet/director.json is removed, so Ratchet won't write "
            f"over it, and nothing was changed. Tell the user; to repair it: {_enrolled_repair(ep)}.")
    if done == "busy":
        _die_record_busy(ep, "nothing was changed")
    (root / RATCHET_DIR).mkdir(exist_ok=True)
    _write_record(root / RATCHET_DIR / "director.json", {"enrolled_at": now(), "sig": signed[0]}, pretty=True)


def cmd_director_enroll(args):
    require_director_session("director-enroll")
    ctx = Ctx(find_root())
    _enroll_lane(ctx.root)
    ok(f"Lane {ctx.root} enrolled: approvals now require a director token.")


_LANE_NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._-]*$")
_LANE_PLACEHOLDERS = ("{worktree}", "{brief}", "{name}")


def _lanes_start_template(cfg: dict):
    """The developer's lane_start_command (a non-empty list of strings using only {worktree}, {brief} and {name}), or
    None when none is set. Dies, before anything is created, when it is not usable."""
    t = cfg.get("lane_start_command")
    if t is None:
        return None
    what = ("lane_start_command in .ratchet/config.json must be a list of words (an argument list such as "
            "[\"mycli\", \"--cwd\", \"{worktree}\"]) using only the placeholders {worktree}, {brief} and {name}. "
            "Fix or remove it, then run lanes-start again. Nothing was changed.")
    if not isinstance(t, list) or not t or not all(isinstance(x, str) and x for x in t):
        die(what)
    for x in t:
        if any(m not in _LANE_PLACEHOLDERS for m in re.findall(r"\{[^{}]*\}", x)):
            die(what)
    return t


def cmd_lanes_start(args):
    """`lanes-start --request "<text>" --lane NAME=FEATURE [--lane ...] [--name N] [--json]` (director only): from one
    request, makes for each lane a branch named NAME (from the main checkout's HEAD), a plain git worktree next to the
    main checkout, the lane's enrollment with the director (no run: the lane's agent runs init itself), and a brief
    file; records the request in .ratchet/requests/<name>.json and prints each lane's start command (the developer's
    lane_start_command template filled in, which Ratchet only prints, or plain words). main's uncommitted Ratchet
    settings (MERGE_SHARED) are copied into each worktree as uncommitted changes; main itself gains no commit and no
    byte changes. Every refusal comes before anything is created; a failure part-way removes what was made."""
    require_director_session("lanes-start")
    main = find_root()
    if not _is_git(main):
        die("lanes-start needs a git project: each lane is a branch and a git worktree. Nothing was changed.")
    top = _git_top_problem(main, "lanes-start", "Start the lanes by hand (git worktree add, then director-enroll in each).")
    if top:
        die(top)
    # one lanes-start or integrate at a time per repository: integrate's lock, so two calls for the same lane name
    # can never both pass the preflight and the loser's rollback can never remove the winner's lane
    cd = subprocess.run(["git", "rev-parse", "--git-common-dir"], cwd=main, capture_output=True, text=True, timeout=60)
    common = Path(cd.stdout.strip() or ".git")
    common = common if common.is_absolute() else main / common
    lk = _IntegrateLock(main, common, "lanes-start")
    why = lk.acquire()
    try:
        if why:
            die((f"Ratchet is busy running {lk.holder}; try lanes-start again when it finishes. Nothing was changed.")
                if why.startswith("Ratchet is busy") else why)
        _lanes_start_run(args, main)
    finally:
        lk.release()


def _lanes_start_run(args, main: Path):
    """The body of cmd_lanes_start, run while it holds the repository's integrate lock."""
    request = (args.request or "").strip()
    if not request:
        die("lanes-start needs the request text (--request \"...\"). Nothing was changed.")
    if not args.lane:
        die("lanes-start needs at least one lane (--lane NAME=FEATURE). Nothing was changed.")

    def git(d, *a):
        return subprocess.run(["git", *a], cwd=d, capture_output=True, text=True, timeout=120)

    lanes = []
    for spec in args.lane:
        n, _eq, feat = spec.partition("=")
        n, feat = n.strip(), feat.strip()
        if not _LANE_NAME_RE.match(n) or ".." in n or git(main, "check-ref-format", "--branch", n).returncode != 0:
            die(f"'{n}' is not a usable lane name (it becomes a branch and a folder name: letters, digits, . _ -). "
                "Pick another name. Nothing was changed.")
        if not feat:
            die(f"Lane '{n}' has no feature text. Give each lane NAME=FEATURE. Nothing was changed.")
        lanes.append({"name": n, "feature": feat})
    names = [x["name"] for x in lanes]
    if len(set(names)) != len(names):
        die("Each lane name must be distinct: a name is used twice. Pick another name for one. Nothing was changed.")
    name = args.name if args.name is not None else slugify(request)
    if not re.fullmatch(r"[a-z0-9]+(-[a-z0-9]+)*", name):
        die(f"The request name '{name}' must be lowercase letters, digits and hyphens. Pick another --name. "
            "Nothing was changed.")
    rdir = main / RATCHET_DIR / "requests"
    if (rdir / f"{name}.json").exists() or (rdir / name).exists():
        die(f"A request named '{name}' is already recorded. Give this one another --name. Nothing was changed.")
    template = _lanes_start_template(Ctx(main).config())
    _director_key()
    ep = _enrolled_path()
    _d, why = _read_record(ep)
    if why:
        die(f"Ratchet's record of enrolled lanes ({ep}) can't be read ({why}); it is not valid or unreadable, so "
            f"Ratchet won't write over it. Tell the user; to repair it: {_enrolled_repair(ep)}. Nothing was changed.")
    base = main.resolve()
    for x in lanes:
        if git(main, "rev-parse", "--verify", "-q", f"refs/heads/{x['name']}").returncode == 0:
            die(f"A branch named '{x['name']}' already exists. Pick another lane name (a different name), then "
                "run lanes-start again. Nothing was changed.")
        x["branch"] = x["name"]
        x["worktree"] = str(base.parent / f"{base.name}-{x['name']}")
        if os.path.lexists(x["worktree"]):
            die(f"The folder {x['worktree']} already exists, so lane '{x['name']}' cannot get a worktree there. "
                "Move it away or pick another lane name. Nothing was changed.")
    if git(main, "rev-parse", "-q", "--verify", "MERGE_HEAD").returncode == 0:
        die("The main checkout has a merge in progress. Finish or abort it before starting lanes. Nothing was changed.")
    carried, bad = [], []
    for path in _integrate_dirty(main, False):
        (carried if path in MERGE_SHARED else bad).append(path)
    if bad:
        die(f"The main checkout has uncommitted changes to project files ({', '.join(bad[:5])}). Ask the developer "
            "to commit or stash them (lanes-start does not touch them), then run lanes-start again. Nothing was "
            "changed.")
    copies = {}
    for path in carried:
        f = main / path
        copies[path] = f.read_bytes() if f.is_file() else None

    made = {"worktrees": [], "enrolled": [], "briefs": rdir / name}
    try:
        for x in lanes:
            made["worktrees"].append(x)   # neither existed above: whatever is there after git runs, this attempt made
            r = git(main, "worktree", "add", "-q", "-b", x["branch"], x["worktree"], "HEAD")
            if r.returncode != 0:   # git can fail after making both (a post-checkout hook that exits non-zero)
                die(f"git could not create the worktree for lane '{x['name']}' (a git hook of this project may have "
                    f"failed): {(r.stderr or r.stdout).strip()[:200]}. Everything this attempt made was removed.")
            for path, data in copies.items():
                t = Path(x["worktree"]) / path
                if data is None:
                    t.unlink()
                else:
                    _write_record(t, data, raw=True)
            k = str(Path(x["worktree"]).resolve())
            if k not in (_read_record(ep)[0] or {}):   # a pre-existing entry is never dropped by the rollback
                made["enrolled"].append(k)             # tracked before the step that writes it
            _enroll_lane(Path(x["worktree"]))
            brief = made["briefs"] / f"{x['name']}.md"
            _write_record(brief, (
                f"# Lane {x['name']}\n\nThe developer's request: {request}\n\nYour part of it, lane '{x['name']}': "
                f"{x['feature']}\n\nYou work only in {x['worktree']} (branch {x['branch']}). Run Ratchet's init "
                "yourself there to plan this feature, and ask for the developer's approvals through your own "
                "director as usual. When the lane is finished, the director merges it with integrate.\n"), raw=True)
            x["brief"] = str(brief)
        _write_record(rdir / f"{name}.json", {"request": request, "name": name, "created_at": now(),
                                              "lanes": [{k: x[k] for k in ("name", "feature", "branch", "worktree", "brief")}
                                                        for x in lanes]}, pretty=True)
    except BaseException:
        def attempt(fn, *a, **kw):   # one failed cleanup action never skips the rest
            try:
                return fn(*a, **kw)
            except Exception:
                return None

        for x in made["worktrees"]:
            attempt(git, main, "worktree", "remove", "--force", x["worktree"])
            attempt(shutil.rmtree, x["worktree"], ignore_errors=True)
            attempt(git, main, "worktree", "prune")
            attempt(git, main, "branch", "-D", x["branch"])
        attempt(shutil.rmtree, made["briefs"], ignore_errors=True)
        attempt(os.unlink, rdir / f"{name}.json") if (rdir / f"{name}.json").exists() else None

        def drop(outside):
            for k in made["enrolled"]:
                outside.pop(k, None)
            return outside
        if made["enrolled"]:
            res = attempt(update_record, ep, drop, damaged=lambda why: KEEP, pretty=True)
            if res not in ("written", "kept"):
                print(f"ratchet: {ep} still lists these removed lanes: {', '.join(made['enrolled'])}. Remove those "
                      "entries from it (or run director-enroll only for lanes that exist).", file=sys.stderr)
        raise
    out = []
    for x in lanes:
        if template:
            fill = {"{worktree}": x["worktree"], "{brief}": x["brief"], "{name}": x["name"]}
            parts = []
            for w in template:
                for k, v in fill.items():
                    w = w.replace(k, v)
                parts.append(w)
            start = shlex.join(parts)
        else:
            start = f"Open your agent CLI in {x['worktree']} and give it the brief {x['brief']}"
        out.append(dict({k: x[k] for k in ("name", "branch", "worktree", "brief")}, start=start))
    if args.json:
        print(json.dumps({"request": name, "lanes": out}, indent=2))
        return
    ok(f"Request '{name}' recorded: {len(out)} lane(s) ready. Lanes are enrolled with no run; each lane's agent runs "
       "init itself.")
    for x in out:
        print(f"Lane {x['name']}: branch {x['branch']}, worktree {x['worktree']}, brief {x['brief']}")
        if template:
            print(f"Start command for {x['name']} (Ratchet only prints it; run it yourself):")
        print(x["start"])


def _git_top_problem(main: Path, command: str, by_hand: str):
    """The plain refusal (or None) for a Ratchet project that sits below the top of its git repository: `command`
    (integrate, lanes-start) assumes the project is the repository top. `by_hand` says what to do instead."""
    where = subprocess.run(["git", "rev-parse", "--show-prefix"], cwd=main, capture_output=True, text=True, timeout=60)
    if where.stdout.strip():
        return (f"{command} supports a Ratchet project at the top of its git repository only, and this project sits "
                f"at '{where.stdout.strip()}' inside its repository. {by_hand} Nothing was changed.")
    return None


def _integrate_lane(main: Path, target: str, fail=None):
    """(lane folder, branch or None) for a lane named by folder or by branch, from git's list of this project's
    worktrees. Ends with a plain line (through `fail`, which the real merge uses to record the refusal; die when none
    is given) when the name is neither."""
    fail = fail or die
    r = subprocess.run(["git", "worktree", "list", "--porcelain"], cwd=main, capture_output=True, text=True, timeout=60)
    trees, cur = [], None
    for ln in r.stdout.splitlines():
        if ln.startswith("worktree "):
            cur = {"path": os.path.realpath(ln[9:]), "branch": None}
            trees.append(cur)
        elif ln.startswith("branch ") and cur:
            cur["branch"] = ln[7:][len("refs/heads/"):] if ln[7:].startswith("refs/heads/") else ln[7:]
    p = Path(target).expanduser()
    if p.is_dir():
        hit = next((t for t in trees if t["path"] == os.path.realpath(p)), None)
        if hit:
            return Path(hit["path"]), hit["branch"]
        fail(f"{target} is not a git worktree of this project, so it is not a lane. Give the lane's folder (a git "
            "worktree of this project) or its branch name. Nothing was changed.")
    hit = next((t for t in trees if t["branch"] == target), None)
    if hit:
        return Path(hit["path"]), hit["branch"]
    fail(f"No lane found for '{target}': no worktree has that branch checked out, and it is not a folder. Give the "
        "lane's folder or its branch name (the lane's branch must be checked out in a worktree). Nothing was changed.")


def _integrate_line(info: dict, result: str, suite: str, detail: str, commits=None) -> dict:
    """One record line for .ratchet/integrations.jsonl: time, lane, run, commits, suite (passed | failed | not-run),
    result (merged | rolled-back | refused | no-op) and a plain detail; a merged line where the lane changed
    config.json settings that main kept (by Ratchet's rules) also carries not_taken, the list of those settings (the
    key is left out when there are none, so the line keeps its seven fields); a merged line where a carried file had
    staged changes before the merge also carries `unstaged`, the list of those paths (they come back unstaged)."""
    line = {"time": now(), "lane": info.get("lane"), "run": info.get("run"),
            "commits": list(commits if commits is not None else info.get("commits") or []), "suite": suite,
            "result": result, "detail": detail}
    if result == "merged" and info.get("not_taken"):
        line["not_taken"] = list(info["not_taken"])
    if result == "merged" and info.get("unstaged"):
        line["unstaged"] = list(info["unstaged"])
    if info.get("staged_saved"):   # {path: file}: a staged version unlike the working copy, saved before main moved
        line["staged_saved"] = dict(info["staged_saved"])
    return line


def _integrate_record(main: Path, info: dict = None, result: str = "", suite: str = "", detail: str = "", commits=None,
                      line: dict = None) -> bool:
    """Append one line (built from the arguments, or `line` as it is) to .ratchet/integrations.jsonl in the main
    checkout (run state, git-ignored). Never rewrites what is there. Returns whether the line was written; a record
    that cannot be written is said on stderr and never changes the outcome (the caller keeps the journal so the next
    integrate records it)."""
    try:
        (main / RATCHET_DIR).mkdir(exist_ok=True)
    except OSError:
        pass
    line = line if line is not None else _integrate_line(info or {}, result, suite, detail, commits)
    if not _append_jsonl(main / RATCHET_DIR / "integrations.jsonl", line):
        print("ratchet: could not write the integration record (.ratchet/integrations.jsonl); the outcome stands",
              file=sys.stderr)
        return False
    return True


def _integrate_drop_scratch(tmp):
    """Remove an integrate scratch copy: the links to the project's installed dependencies as links (never followed),
    then the folder. It is a clone of its own, not a registered worktree, so main's git has nothing to prune."""
    tmp = Path(tmp)
    for dep in DEP_DIRS:
        try:
            if (tmp / dep).is_symlink():
                (tmp / dep).unlink()
        except OSError:
            pass
    shutil.rmtree(tmp, ignore_errors=True)


def _integrate_clear_leftovers(prefix: str):
    """Called with the integrate lock held: a scratch copy left in the temp folder by an integrate of this repository
    that was killed (named with this repository's prefix) is removed. No other repository's copy has this prefix."""
    tmpdir = Path(tempfile.gettempdir())
    try:
        old = [p for p in tmpdir.iterdir() if p.name.startswith(prefix) and p.is_dir() and not p.is_symlink()]
    except OSError:
        return
    for p in old:
        _integrate_drop_scratch(p)


def _integrate_dirty(d, exclude):
    """Paths with uncommitted changes to tracked files in the checkout `d` (untracked files are not listed), relative
    to the project folder; `exclude`: leave out Ratchet's own folder."""
    def git(*a):
        return subprocess.run(["git", *a], cwd=d, capture_output=True, text=True, timeout=60)
    top = Path(git("rev-parse", "--show-toplevel").stdout.strip() or d)
    prefix = git("rev-parse", "--show-prefix").stdout.strip()
    r = subprocess.run(["git", "--no-optional-locks", "status", "--porcelain", "-z", "--no-renames",
                        "--untracked-files=no", "--", prefix or ".", *([f":(exclude){prefix}{RATCHET_DIR}"] if exclude else [])],
                       cwd=top, capture_output=True, text=True, timeout=60)
    return [x[3:][len(prefix):] if prefix and x[3:].startswith(prefix) else x[3:] for x in r.stdout.split("\0") if x]


def _integrate_untracked(d):
    """Files in the checkout `d` that git does not track, ignored ones included (paths from the repository top): a
    merge may not overwrite any of them."""
    out = []
    for extra in ((), ("--ignored",)):
        r = subprocess.run(["git", "--no-optional-locks", "ls-files", "--others", "--exclude-standard", "--full-name",
                            "-z", *extra], cwd=d, capture_output=True, text=True, timeout=60)
        out += [x for x in r.stdout.split("\0") if x and x not in out]
    return out


def _integrate_run_problem(main: Path, mctx):
    """Why the main checkout's own run stops a merge right now (a plain sentence ending in what to do), or None. The
    same rule as lane F's merge guard: only a run that is building mid-step (or blocked), or paused from building or
    blocked, stops it; done, cancelled, not-yet-approved plan phases and a run paused from a waiting phase do not."""
    mslug = mctx.active_slug()
    if mslug and mctx.state_path(mslug).is_file():
        mst, why = _read_record(mctx.state_path(mslug))
        if why:
            return (f"The main checkout's run state ({mctx.state_path(mslug)}) can't be read ({why}), so integrate "
                    "can't tell if its run is between steps. Check it with status first.")
        if mst.get("phase") in ("building", "blocked") and not _between_steps(mst, main):
            return (f"The main checkout's own run '{mslug}' is in phase '{mst.get('phase')}', in the middle of a step. "
                    "Wait for the step to finish (or for the run to be unblocked), then run integrate again.")
        if mst.get("phase") == "paused" and mst.get("paused_from") in ("building", "blocked"):
            # like `merged`: a run paused from building keeps its step's starting tree, which a merge now would
            # leave behind the lane's work
            return (f"The main checkout's own run '{mslug}' is paused from phase '{mst.get('paused_from')}', in the "
                    "middle of a step. Resume it (resume) until it is between steps, then run integrate again.")
    return None


def _integrate_check(main: Path, target: str, info: dict, fail):
    """Everything integrate checks before it changes anything, for the dry run and the real merge alike. `fail(msg)`
    ends the command with a plain message (the real merge records it as refused first). Reads only. Returns the
    facts: lane folder, name, run slug, main's tip, the lane's tip, the branch main is on, the commits the lane would
    bring (as "<hash> <subject>" lines), the uncommitted Ratchet files on main, and main's context."""
    info["lane"] = target
    # known limit: the scratch clone, the suite and the file checks all assume the project is the repository top
    top = _git_top_problem(main, "integrate", "Merge this lane by hand (git merge in the main checkout, then run the suite there).")
    if top:
        fail(top)
    wt = subprocess.run(["git", "config", "--get", "core.worktree"], cwd=main, capture_output=True, text=True, timeout=60)
    if wt.stdout.strip():
        # known limit: the scratch clone takes main's local config, and a core.worktree there would point its git
        # commands at main's own files
        fail(f"integrate does not support a main checkout whose git config sets core.worktree ({wt.stdout.strip()}): "
             "the scratch copy would work on main's files. Merge this lane by hand (git merge in the main checkout, "
             "then run the suite there). Nothing was changed.")
    if subprocess.run(["git", "cat-file", "-e", "HEAD:.gitmodules"], cwd=main, capture_output=True, text=True,
                      timeout=60).returncode == 0:
        # known limit: the scratch copy would have empty submodule folders, and the suite would blame the lane
        fail("integrate cannot test a project with git submodules yet (main's tree has a .gitmodules file): the "
             "scratch copy's submodule folders would be empty. Merge this lane by hand (git merge in the main checkout, "
             "then run the suite there). Nothing was changed.")
    lane, branch = _integrate_lane(main, target, fail)
    if lane == main.resolve():
        fail("That folder is the main checkout itself, not a lane. Give the lane's folder or its branch name. "
             "Nothing was changed.")
    lctx, mctx = Ctx(lane), Ctx(main)
    name = branch or str(lane)
    info["lane"] = name
    slug = lctx.active_slug()
    if not slug or not lctx.state_path(slug).is_file():
        fail(f"The lane '{name}' has no active run, so there is nothing finished to integrate. Give the folder or "
             "branch of a lane whose agent ran its work through Ratchet. Nothing was changed.")
    info["run"] = slug
    lst, why = _read_record(lctx.state_path(slug))
    if why:
        fail(f"The lane's run state ({lctx.state_path(slug)}) can't be read ({why}), so integrate can't tell if the "
             "run is finished. Have the lane's agent check it with status. Nothing was changed.")
    phase = lst.get("phase")
    if phase != "done":
        fail(f"The lane's run '{slug}' is not finished (it is in phase '{phase}'). Have the lane's agent finish it, "
             "then run integrate again. Nothing was changed.")

    def git(d, *a):
        return subprocess.run(["git", *a], cwd=d, capture_output=True, text=True, timeout=60)

    dirty = _integrate_dirty

    if git(lane, "rev-parse", "-q", "--verify", "MERGE_HEAD").returncode == 0:
        fail(f"A merge is in progress in the lane '{name}'. Have the lane's agent finish or abort it there first, "
             "then run integrate again. Nothing was changed.")
    bad = dirty(lane, True)
    if bad:
        fail(f"The lane '{name}' has uncommitted changes ({', '.join(bad[:5])}). Have the lane's agent commit or "
             "discard them, then run integrate again. Nothing was changed.")
    if git(main, "rev-parse", "-q", "--verify", "MERGE_HEAD").returncode == 0:
        fail("The main checkout has a merge in progress. Finish or abort it before integrating. Nothing was changed.")
    carried = []
    for path in dirty(main, False):
        (carried if path in MERGE_SHARED else bad).append(path)
    if bad:
        fail(f"The main checkout has uncommitted changes to project files ({', '.join(bad[:5])}). Ask the developer "
             "to commit or stash them (integrate does not touch them), then run integrate again. Nothing was changed.")
    problem = _integrate_run_problem(main, mctx)
    if problem:
        fail(problem + " Nothing was changed.")
    head = git(main, "rev-parse", "HEAD").stdout.strip()
    lhead = git(lane, "rev-parse", "HEAD").stdout.strip()
    tip = git(main, "rev-parse", "--abbrev-ref", "HEAD").stdout.strip() or "HEAD"
    commits = git(main, "log", "--format=%h %s", f"{head}..{lhead}").stdout.splitlines()
    hashes = git(main, "log", "--format=%H", f"{head}..{lhead}").stdout.split()
    info["commits"] = [lhead]
    return {"lane": lane, "name": name, "slug": slug, "head": head, "lhead": lhead, "target": tip, "commits": commits,
            "hashes": hashes, "carried": carried, "mctx": mctx}


def cmd_integrate(args):
    """`integrate <lane>` (director only): merges a finished lane into the main checkout. The merge is made and the
    regression_command is run in a scratch clone of main (in the temp folder, borrowing main's objects, at main's tip);
    only when the suite passes on that exact commit and main has not moved is the commit fetched into main and main
    fast-forwarded to it. Ratchet's own shared files (MERGE_SHARED) are merged by Ratchet's rules in the scratch copy
    (_integrate_resolve_shared), and main's uncommitted copies of them are carried across the merge and re-applied by
    the same rules, still uncommitted (_integrate_carry_plan). Any failure removes the scratch clone and leaves main
    exactly as it was (it never resets or cleans main's files; the only checkout is of the carried Ratchet files, for
    the fast-forward, and they get their bytes back on any failure; it never commits anything but the merge). Every
    attempt is appended to .ratchet/integrations.jsonl. Nothing is pushed.
    `--dry-run` only checks the lane and says what integrate would do; it reads only and writes nothing."""
    require_director_session("integrate")
    main = find_root()
    if not _is_git(main):
        die("integrate needs a git project: it merges a lane's branch. Nothing was changed.")
    if args.dry_run:
        try:
            _integrate_dry_run(main, _integrate_check(main, args.lane, {}, die))
        except subprocess.TimeoutExpired as e:
            die("A git command timed out while integrate checked the lane "
                f"({' '.join(str(a) for a in e.cmd)[:80]}). Nothing was changed. Run integrate again.")
        return
    info = {"lane": args.lane, "run": None, "commits": []}

    held = {"lock": False}  # only the integrate that holds the lock (and so wrote the journal) may remove the journal

    def finish(result, suite, msg, detail=None, commits=None):
        line = _integrate_line(info, result, suite, detail or msg, commits)
        if held["lock"]:  # the outcome goes into the journal first, so a record that cannot be written now is not lost
            try:
                j, why = _read_record(_integrate_journal(common))
                j = j if not why and isinstance(j, dict) else {}
                j["outcome"] = line
                _write_record(_integrate_journal(common), j)
            except Exception:
                pass
        wrote = _integrate_record(main, line=line)
        if held["lock"]:
            if wrote:
                try:
                    _integrate_journal(common).unlink()  # the attempt is on record: nothing left to recover
                except OSError:
                    pass
            else:
                print("ratchet: the attempt's outcome is kept in the integrate journal; the next integrate records it "
                      "once the record can be written", file=sys.stderr)
        if result in ("merged", "no-op"):
            ok(msg)
            return
        die(msg)

    cd = subprocess.run(["git", "rev-parse", "--git-common-dir"], cwd=main, capture_output=True, text=True, timeout=60)
    common = Path(cd.stdout.strip() or ".git")
    common = common if common.is_absolute() else main / common
    lk = _IntegrateLock(main, common, f"integrate {args.lane}")
    why = lk.acquire()
    try:
        if why:
            busy = (f"Another integrate is already running (Ratchet is busy running {lk.holder}). Try again when it "
                    "finishes. Nothing was changed.")
            finish("refused", "not-run", busy if why.startswith("Ratchet is busy") else why)
        held["lock"] = True
        info["prefix"] = "ratchet-integrate-" + hashlib.sha1(os.path.realpath(common).encode()).hexdigest()[:10] + "-"
        _integrate_recover(main, common)
        # this attempt's journal from here on (after recover, so an old one is never overwritten): a kill during the
        # checks is recorded by the next integrate too
        _write_record(_integrate_journal(common), {"lane": args.lane, "run": None, "head": None, "lhead": None,
                                                   "target": None, "sha": None, "suite": "not-run", "started": now()})
        _integrate_clear_leftovers(info["prefix"])
        try:
            f = _integrate_check(main, args.lane, info, lambda m: finish("refused", "not-run", m))
        except subprocess.TimeoutExpired as e:
            finish("refused", "not-run", "A git command timed out while integrate checked the lane "
                   f"({' '.join(str(a) for a in e.cmd)[:80]}). Nothing was changed. Run integrate again.")
        _integrate_merge(main, f, info, finish)
    finally:
        lk.release()


def _integrate_dry_run(main: Path, f: dict):
    name, slug, head, lhead, target, commits = f["name"], f["slug"], f["head"], f["lhead"], f["target"], f["commits"]

    def git(d, *a):
        return subprocess.run(["git", *a], cwd=d, capture_output=True, text=True, timeout=60)

    if not commits:
        ok(f"Dry run: the lane '{name}' (run '{slug}') has nothing new to bring to {target}, so there is nothing to "
           "merge. Nothing was changed.")
        return
    layout = _integrate_layout_problem(main, head, lhead)
    if layout:
        die("Dry run: integrate would refuse this lane. " + layout)
    base = git(main, "merge-base", head, lhead).stdout.strip()
    differ = [x for x in sorted(MERGE_SHARED)
              if any(git(main, "diff", "--name-only", base, side, "--", x).stdout.strip() for side in (lhead, head))]
    # the two standards.md stops the real run would make (before any clone): both sides changed it since the lane
    # branched, or main's uncommitted copy and the lane's change clash
    std = f"{RATCHET_DIR}/standards.md"

    def blob(rev):
        r = subprocess.run(["git", "show", f"{rev}:{std}"], cwd=main, capture_output=True, timeout=60)
        return r.stdout if r.returncode == 0 else None

    b, o, t = blob(base), blob(head), blob(lhead)
    merged, _nt, problem = _integrate_merge_shared(std, b, o, t)   # the one rule the real run applies
    if problem or merged is None:
        die(f"Dry run: integrate would refuse this lane. Both sides changed {std} since the lane branched (the lane "
            f"'{name}' and main), and integrate does not merge two versions of the standards. Decide which wording to "
            "keep, change one side to match (commit it on main or in the lane), then run integrate again. Nothing was "
            "changed.")
    if std in f["carried"] and merged != o:   # the merge changes it: the uncommitted copy is re-applied by the rule
        try:
            mine = (main / std).read_bytes()
        except OSError:
            mine = None
        res, _nt, problem = _integrate_merge_shared(std, o, mine, merged, lane_local=False) if mine is not None else (o, [], None)
        if problem or res is None:
            die(f"Dry run: integrate would refuse this lane. Main's uncommitted {std} and the merge both change it "
                "differently, and integrate does not merge two versions of the standards. Ask the developer to commit "
                f"or undo the uncommitted {std} on main (or change the lane's version to match), then run integrate "
                "again. Nothing was changed.")
    suite = f["mctx"].config().get("regression_command")
    lines = [f"Dry run: integrate would merge the lane '{name}' (run '{slug}', finished) into {target}.",
             f"Commits it would bring to {target} ({len(commits)}):", *[f"  {c}" for c in commits],
             "Ratchet's own files that differ since the lane branched (merged by Ratchet's rules): "
             + (", ".join(differ) if differ else "none differ."),
             "Uncommitted Ratchet files on main it would carry across (never committed): "
             + (", ".join(sorted(f["carried"])) if f["carried"] else "none."),
             "Suite it would run on the merged code before main moves: "
             + (suite if suite else "none (no regression_command is set)."),
             "This was a dry run: nothing was changed, no merge was made and nothing was pushed."]
    ok("\n".join(lines))


def _integrate_linked_deps(main: Path) -> list:
    """Installed-dependency folders (DEP_DIRS) of the main checkout whose contents point back into the main checkout
    itself, outside that dependency folder: workspace links in node_modules or vendor, and a Python editable install
    (a .pth, .egg-link or __editable__ file, or an editable direct_url.json, naming main's path). The scratch copy
    borrows those folders by link, so the suite would load main's code from before the merge through them. Returns
    short "where -> what" strings (at most three); [] when none."""
    from urllib.parse import unquote, urlparse
    roots = sorted({os.path.realpath(main), os.path.abspath(main)})
    found = []

    def inside(path, dep_real):
        path = os.path.normpath(path)
        return any(path == r or path.startswith(r + os.sep) for r in roots) and not (
            path == dep_real or path.startswith(dep_real + os.sep))

    def links(dep, dep_real, d, level):
        try:
            names = sorted(os.listdir(d))
        except OSError:
            return
        for n in names:
            p = os.path.join(d, n)
            if os.path.islink(p):
                t = os.path.realpath(p)
                if inside(t, dep_real):
                    found.append(f"{os.path.relpath(p, main)} -> {os.path.relpath(t, main)}")
            elif level == 1 and os.path.isdir(p) and (dep != "node_modules" or n.startswith("@") or n == ".bin"):
                links(dep, dep_real, p, 2)

    pat = re.compile("(?:" + "|".join(re.escape(r) for r in roots) + r")(?![\w.\-])[^\s'\"\\]*")

    def text_of(p):
        try:
            if os.path.getsize(p) > 1000000:
                return ""
            with open(p, encoding="utf-8", errors="replace") as fh:
                return fh.read()
        except OSError:
            return ""

    def python_installs(dep_real, dep_dir):
        sites = []
        for lib in ("lib", "lib64", "Lib"):
            base = os.path.join(dep_dir, lib)
            try:
                sites += [os.path.join(base, n, "site-packages") for n in sorted(os.listdir(base)) if n.startswith("python")]
            except OSError:
                pass
            sites.append(os.path.join(base, "site-packages"))
        for site in sites:
            try:
                names = sorted(os.listdir(site))
            except OSError:
                continue
            for n in names:
                p = os.path.join(site, n)
                if n.endswith((".pth", ".egg-link")) or n.startswith("__editable__"):
                    hit = next((m.group(0) for m in pat.finditer(text_of(p)) if inside(m.group(0), dep_real)), None)
                    if hit:
                        found.append(f"{os.path.relpath(p, main)} -> {os.path.relpath(hit, main)}")
                elif n.endswith(".dist-info"):
                    try:
                        # direct_url.json is the installer's own file, not a Ratchet record: unreadable or
                        # invalid means not an editable install, never an exit
                        du, _why = _read_record(Path(p) / "direct_url.json", kind=dict, missing={})
                        url = (du or {}).get("url") or ""
                        loc = unquote(urlparse(url).path)
                        if (du.get("dir_info") or {}).get("editable") and url.startswith("file:") and inside(loc, dep_real):
                            found.append(f"{os.path.relpath(p, main)} -> {os.path.relpath(loc, main)}")
                    except (ValueError, AttributeError):
                        pass

    for dep in DEP_DIRS:
        dep_dir = os.path.join(main, dep)
        if not os.path.isdir(dep_dir):
            continue
        dep_real = os.path.realpath(dep_dir)
        links(dep, dep_real, dep_dir, 1)
        if dep in (".venv", "venv"):
            python_installs(dep_real, dep_dir)
        if dep == "vendor":
            # Composer's autoloader maps the project's own classes through __DIR__ . '/../..', which resolves the
            # linked folder back into this checkout
            try:
                auto = sorted(n for n in os.listdir(os.path.join(dep_dir, "composer"))
                              if n.startswith("autoload_") and n.endswith(".php"))
            except OSError:
                auto = []
            for rel in ["vendor/autoload.php"] + ["vendor/composer/" + n for n in auto]:
                if os.path.isfile(os.path.join(main, rel)):
                    found.append(f"{rel} -> this checkout's classes (Composer's autoloader)")
                    break
    return found[:3]


def _integrate_rules_snapshot(mctx):
    """Main's own run's approval snapshot (rules and reference files) as they stand now, taken right before main moves
    so _integrate_move_base can tell what the integrate itself changed; None when main has no run with an approved
    plan, or its state can't be read."""
    mslug = mctx.active_slug()
    if not (mslug and mctx.state_path(mslug).is_file()):
        return None
    mst, why = _read_record(mctx.state_path(mslug))
    if why or not isinstance(mst.get("approved"), dict):
        return None
    try:
        return approval_snapshot(mctx, mst)
    except (SystemExit, OSError, ValueError, KeyError, TypeError):
        return None


def _integrate_move_base(main: Path, mctx, sha: str, lane: str, run: str, before: dict = None):
    """Called holding main's state lock, right after main was fast-forwarded to the merge commit `sha` (and main's
    uncommitted Ratchet files were re-applied). When main's own run is building at step 'tests' (between steps: the
    only building state integrate allows), its current step's starting tree and commit are moved to the merge, the way
    `merged` does for a lane, so the step's reviewers and its commit see only the step's own changes and not the
    lane's. Other phases set a fresh starting tree when their next step begins. With `before` (the run's rules and
    reference files as they were right before main moved, _integrate_rules_snapshot), every config rule and reference
    file that matched the approved baseline before and that the integrate changed (a shared file merged by Ratchet's
    rules) becomes the new approved baseline, so main's run never asks approve-changes for it; one that was already
    changed before stays as it is. Logged as `integrated_lane` (`commit`, `lane`, `run`, `accepted`). A run state that
    can't be read is left alone (the merge stands)."""
    mslug = mctx.active_slug()
    if not (mslug and mctx.state_path(mslug).is_file()):
        return
    mst, why = _read_record(mctx.state_path(mslug))
    if why:
        return
    cur, changed, accepted = mst.get("current"), False, []
    if cur and mst.get("phase") == "building" and (mst.get("checkpoints") or {}).get(cur, {}).get("step") == "tests":
        base = fingerprint(main)["id"]
        mst["base_tree"] = base
        mst["checkpoints"][cur]["base_tree"] = base
        mst["checkpoints"][cur]["base_head"] = sha
        changed = True
    snap = mst.get("approved")
    if before and isinstance(snap, dict):
        now_ = approval_snapshot(mctx, mst)
        for section, what in (("rules", "config rule '{}'"), ("files", "reference file {}")):
            for k, h in list((snap.get(section) or {}).items()):
                if h == (before.get(section) or {}).get(k) and now_.get(section, {}).get(k) != h:
                    snap[section][k] = now_[section][k]
                    accepted.append(what.format(k))
        changed = changed or bool(accepted)
    if not changed:
        return
    mctx.log(mst, "integrated_lane", commit=sha, lane=lane, run=run, accepted=accepted)
    mctx.save_state(mst)


def _integrate_layout_problem(main: Path, head: str, lhead: str):
    """The known layout limits the real merge refuses before any clone, as one plain line (or None), so the dry run
    can report them too: the lane changes a dependency manifest or lockfile (the suite would run with main's installed
    dependencies, linked in, which cannot match the lane's), or main's installed dependencies link back into main."""
    manifests = {"package.json", "package-lock.json", "npm-shrinkwrap.json", "yarn.lock", "pnpm-lock.yaml", "bun.lock",
                 "bun.lockb", "pyproject.toml", "setup.py", "setup.cfg", "Pipfile", "Pipfile.lock", "uv.lock",
                 "poetry.lock", "Gemfile", "Gemfile.lock", "composer.json", "composer.lock", "Cargo.toml", "Cargo.lock",
                 "go.mod", "go.sum"}
    base = subprocess.run(["git", "merge-base", head, lhead], cwd=main, capture_output=True, text=True, timeout=60)
    changed = subprocess.run(["git", "diff", "--name-only", base.stdout.strip() or head, lhead], cwd=main,
                             capture_output=True, text=True, timeout=60).stdout.split()
    deps = [p for p in changed if os.path.basename(p) in manifests
            or (os.path.basename(p).startswith("requirements") and p.endswith(".txt"))]
    if deps:
        return (f"The lane changes the project's dependencies ({', '.join(deps[:5])}). integrate runs the suite with "
                "main's installed dependencies, which do not match the lane's, and cannot install the lane's yet. Merge "
                "this lane by hand (git merge in the main checkout, install, then run the suite there). Nothing was "
                "changed.")
    linked = _integrate_linked_deps(main)
    if linked:
        return ("integrate cannot test this project layout yet: its installed dependencies link back into the main "
                f"checkout ({'; '.join(linked)}; workspace links or an editable install), so a suite run on the merged "
                "copy would load main's code from before the merge. Merge this lane by hand (git merge in the main "
                "checkout, then run the suite there). Nothing was changed.")
    return None


def _integrate_journal(common: Path) -> Path:
    """The journal of the integrate attempt under way (next to the integrate lock): what the next integrate needs to
    record the attempt if this one is killed before it records itself."""
    return common / "ratchet-integrate.journal"


def _integrate_recover(main: Path, common: Path):
    """Called with the integrate lock held, before a new attempt starts: an attempt that ended without its record line
    (killed mid-run, or its record could not be written) left its journal. First, when the journal names carried
    files (main's uncommitted Ratchet files set back to the tip for the fast-forward), a carried file still at the
    journaled tip gets the developer's saved bytes back, unstaged, and the carry folder is removed; once main holds
    the merge (or moved on) nothing is written, the folder is set aside under a name of its own and the note says
    how to re-add the developer's own edits (_integrate_carry_restore). Then the attempt is recorded: the journaled
    outcome as it is when there is one; else merged with a note when main's history holds that attempt's merge
    commit (killed after the fast-forward; main's run is not touched, so a step in progress shows the lane's changes
    in its own diff), else rolled back (killed during the suite or before). The journal is removed only once the
    record line is written; when it cannot be, the command stops with a plain line and the journal stays."""
    journal = _integrate_journal(common)
    if not journal.is_file():
        return
    j, why = _read_record(journal)
    j = j if not why and isinstance(j, dict) else {}
    lane, run, sha, head, lhead = j.get("lane"), j.get("run"), j.get("sha"), j.get("head"), j.get("lhead")
    info = {"lane": lane, "run": run}

    def git(*a):
        return subprocess.run(["git", *a], cwd=main, capture_output=True, text=True, timeout=60)

    names = j.get("carried") if isinstance(j.get("carried"), dict) else {}
    if names:
        # the killed attempt had set main's uncommitted Ratchet files back to the tip to move main: while main is
        # still at that tip, a file still at it (not edited since) gets the developer's saved bytes back, unstaged;
        # once main holds the merge the saved copy predates it and is only set aside and named
        folder = Path(j["carry_folder"]) if isinstance(j.get("carry_folder"), str) and j["carry_folder"] else None
        jstaged = j.get("staged") if isinstance(j.get("staged"), dict) else {}
        jsaved = j.get("staged_saved") if isinstance(j.get("staged_saved"), dict) else {}
        info["staged_saved"] = jsaved
        back = _integrate_carry_restore(main, common, names, head=head, only_clean=True, staged=jstaged, folder=folder)
        print(f"RATCHET: note: an earlier integrate of the lane '{lane}' was interrupted while carrying main's "
              f"uncommitted {', '.join(sorted(names))} across the merge; "
              + _integrate_carry_said(back, names, head, jstaged, jsaved)
              + (" A change the merge brought to a restored file is not re-applied." if back[0] else ""),
              file=sys.stderr, flush=True)

    if isinstance(j.get("outcome"), dict):
        line = j["outcome"]
    elif sha and git("merge-base", "--is-ancestor", sha, "HEAD").returncode == 0:  # main took it (and may have moved on)
        lane_commits = git("rev-list", f"{head}..{lhead}").stdout.split() if head and lhead else []
        note = (f"An earlier integrate of the lane '{lane}' (run '{run}') was interrupted after {j.get('target') or 'main'} "
                f"took its merge commit {sha[:9]}; it is recorded now. Main's run was not changed: if it is in the "
                "middle of a step, that step's diff also shows the lane's changes.")
        line = _integrate_line(info, "merged", j.get("suite") or "passed", note, [sha] + lane_commits)
        print(f"RATCHET: note: {note}", file=sys.stderr, flush=True)
    else:
        line = _integrate_line(info, "rolled-back", j.get("suite") or "not-run",
                               f"An earlier integrate of the lane '{lane}' (run '{run}') was interrupted (killed) before "
                               "it finished; main did not take the merge.", [lhead] if lhead else [])
    if not _integrate_record(main, line=line):
        die(f"The record of an earlier interrupted integrate (of the lane '{lane}') could not be written to "
            f"{RATCHET_DIR}/integrations.jsonl in the main checkout. Fix that (the file and its folder must be "
            "writable), then run integrate again: it records that attempt first. Nothing was changed.")
    try:
        journal.unlink()
    except OSError:
        pass


_ABSENT = object()   # a config.json key one side does not have, in the three-way rules below


def _integrate_merge_checks(base, ours, theirs):
    """The guardrail `checks` rule, three-way against the base, matched by `kind` (how _finish_guardrail identifies a
    check: a strengthen step replaces its kind's check with a new command), by `command` for an entry without one:
    main's entries in main's order, plus every lane entry main lacks, so no guardrail is lost; an entry the lane
    changed or removed while main left it as the base takes the lane's change (including the removal); one both sides
    changed differently keeps main's and is listed; one main removed stays removed, listed only when the lane changed
    it. Returns (merged list, not_taken)."""
    def key(c):
        if isinstance(c, dict) and norm_kind(c.get("kind")):
            return norm_kind(c.get("kind"))
        return c.get("command") if isinstance(c, dict) and isinstance(c.get("command"), str) else json.dumps(c, sort_keys=True)
    bm = {key(c): c for c in base}
    om = {key(c): c for c in ours}
    tm = {key(c): c for c in theirs}
    out, not_taken = [], []
    for c in ours:
        k = key(c)
        if k in tm:
            if tm[k] == c or not (k in bm and bm[k] == c):
                out.append(c)                   # same on both sides, or main changed it: main's
                if tm[k] != c and (k not in bm or tm[k] != bm[k]):   # listed only when the lane changed it too
                    not_taken.append(f"checks ({k})")
            else:
                out.append(tm[k])               # main left it as the base; the lane changed it
        elif k in bm and bm[k] == c:
            continue                            # the lane removed it; main left it as the base
        else:
            out.append(c)                       # main added or changed it; the lane lacks it
            if k in bm:
                not_taken.append(f"checks ({k})")
    for c in theirs:
        k = key(c)
        if k in om:
            continue
        if k in bm:                             # main removed it since the base
            if bm[k] != c:
                not_taken.append(f"checks ({k})")
        else:
            out.append(c)
    return out, not_taken


def _integrate_merge_config(base: dict, ours: dict, theirs: dict, lane_local: bool = True):
    """The config.json rule, three-way per top-level key against `base`: a key only `theirs` changed takes theirs; a
    key both changed keeps ours and is listed; a lane-local key (LANE_LOCAL_CONFIG_KEYS, when `lane_local`) always
    keeps ours and is listed when theirs differs; `checks` merges by _integrate_merge_checks. Keys keep ours' order,
    theirs' new keys follow. Returns (result, not_taken). With lane_local off (re-applying main's uncommitted copy over
    the merged result: ours is the uncommitted copy) the uncommitted value wins every clash."""
    out, not_taken = dict(ours), []
    for k in dict.fromkeys(list(ours) + list(theirs) + list(base)):
        ov, tv, bv = ours.get(k, _ABSENT), theirs.get(k, _ABSENT), base.get(k, _ABSENT)
        if tv == ov or tv == bv:
            continue                          # no difference, or theirs did not change it: ours stands
        if lane_local and k in LANE_LOCAL_CONFIG_KEYS:
            not_taken.append(k)
        elif ov == bv:                        # only theirs changed it (`checks` too: the lane's list whole)
            if tv is _ABSENT:
                out.pop(k, None)
            else:
                out[k] = tv
        elif k == "checks" and isinstance(ov, list) and isinstance(tv, list) and (isinstance(bv, list) or bv is _ABSENT):
            out[k], nt = _integrate_merge_checks(bv if isinstance(bv, list) else [], ov, tv)
            not_taken += nt
        else:                                 # both changed it differently
            not_taken.append(k)
    return out, not_taken


def _integrate_union_lines(base, ours: bytes, theirs: bytes) -> bytes:
    """The learnings.md and .ratchet/.gitignore rule, a line merge against the base (None when neither side had the
    file before): every line of ours, in ours' order, except a base line theirs removed; then each line theirs added
    (not in the base, not in ours), once, in theirs' order. Every line either side added is kept; a line one side
    deleted stays deleted."""
    bl = set(base.decode("utf-8", "surrogateescape").splitlines()) if base else set()
    tl = theirs.decode("utf-8", "surrogateescape").splitlines()
    ts = set(tl)
    o = ours.decode("utf-8", "surrogateescape")
    kept = [ln for ln in o.splitlines() if ln in ts or ln not in bl]
    seen = set(kept)
    add = []
    for ln in tl:
        if ln not in seen and ln not in bl:
            seen.add(ln)
            add.append(ln)
    if not add and len(kept) == len(o.splitlines()):
        return ours
    return "".join(ln + "\n" for ln in kept + add).encode("utf-8", "surrogateescape")


def _integrate_merge_shared(path: str, base, ours, theirs, lane_local: bool = True):
    """Ratchet's rule for one shared file (a MERGE_SHARED path), given the three versions as bytes (None when that
    side has no such file). Returns (result bytes, not_taken, problem): `problem` is a plain sentence when the rule
    cannot decide (standards.md changed on both sides, a config.json that is not a JSON object), with result None.
    A side that deleted the file counts as unchanged (the other side's version is kept)."""
    name = path.rsplit("/", 1)[-1]
    if theirs is None or theirs == ours or theirs == base:
        return ours if ours is not None else theirs, [], None
    if name == "config.json":   # always key by key: a lane-local key is kept even when only the lane changed the file
        sides = {}
        for tag, raw_ in (("base", base), ("ours", ours), ("theirs", theirs)):
            data, why = _read_record(Path(path), data=raw_ if raw_ is not None else b"{}")
            if why:
                where = {"base": "in the merge base (the commit the lane branched from)", "ours": "on main",
                         "theirs": "in the lane"}[tag]
                return None, [], (f"{path} is not a JSON object {where} ({why}), so integrate cannot merge it by its "
                                  "rules. " + ("Have the lane's agent merge main into the lane (git merge main, then "
                                               "`ratchet.py merged`), so the lane branches from a newer base, then run "
                                               "integrate again." if tag == "base" else
                                               "Fix that file, then run integrate again."))
            sides[tag] = data
        res, not_taken = _integrate_merge_config(sides["base"], sides["ours"], sides["theirs"], lane_local)
        if res == sides["ours"]:
            return ours, not_taken, None
        if res == sides["theirs"]:
            return theirs, not_taken, None
        return (json.dumps(res, indent=2, ensure_ascii=False) + "\n").encode("utf-8"), not_taken, None
    if ours is None or ours == base:
        return theirs, [], None
    if name in ("learnings.md", ".gitignore"):
        return _integrate_union_lines(base, ours, theirs), [], None
    return None, [], None   # standards.md (and any other shared file): both sides changed it differently


def _integrate_resolve_shared(tmp: Path, head: str, lhead: str, name: str, git):
    """Inside the scratch copy, right after `git merge --no-commit` of the lane: Ratchet's shared files are merged by
    Ratchet's rules, not git's. Every MERGE_SHARED path the lane changed since the merge base is run through its rule,
    whether git conflicted on it (then from its index stages: :1: base, :2: main, :3: lane) or merged it cleanly (from
    the base, main and lane versions), and `git add`ed: a lane-local config key never reaches main, a learnings line
    one side removed stays removed, and standards.md changed on both sides stops integrate even when git would merge
    the two cleanly. Returns (not_taken, problem): `problem` is a plain sentence to roll back with (main untouched)."""
    conflicted = set(git(tmp, "diff", "--name-only", "--diff-filter=U").stdout.split())
    base = git(tmp, "merge-base", head, lhead).stdout.strip()
    not_taken = []

    def blob(spec):
        r = subprocess.run(["git", "show", spec], cwd=tmp, capture_output=True, timeout=120)
        return r.stdout if r.returncode == 0 else None

    for path in sorted(MERGE_SHARED):
        if path in conflicted:
            b, o, t = blob(f":1:{path}"), blob(f":2:{path}"), blob(f":3:{path}")
        elif git(tmp, "diff", "--quiet", base, lhead, "--", path).returncode != 0:
            b, o, t = blob(f"{base}:{path}"), blob(f"{head}:{path}"), blob(f"{lhead}:{path}")
        else:
            continue
        res, nt, problem = _integrate_merge_shared(path, b, o, t)
        if problem:
            return not_taken, problem
        if res is None:
            return not_taken, (f"Both sides changed {path} since the lane branched (the lane '{name}' and main), and "
                               "integrate does not merge two versions of the standards. Decide which wording to keep, "
                               "change one side to match (commit it on main or in the lane), then run integrate again.")
        not_taken += nt
        _write_record(tmp / path, res, raw=True)
        r = git(tmp, "add", "--", path)
        if r.returncode != 0:
            return not_taken, f"git could not stage the merged {path} ({(r.stderr or r.stdout).strip()[:200]})."
    return not_taken, None


def _integrate_carry_plan(main: Path, scratch: Path, head: str, sha: str, carried: list):
    """What main's uncommitted Ratchet files (`carried`, MERGE_SHARED paths) become once main is at the merge commit
    `sha` (read from the scratch copy, where it exists before main takes it): each is re-applied by the same per-file
    rules, three-way with base = main's old HEAD version, ours = the uncommitted copy, theirs = the merged result; the
    uncommitted value wins a clash and is listed. Returns (saved {path: bytes as they are now}, writes {path: bytes to
    leave uncommitted}, not_taken, problem)."""
    saved, writes, not_taken = {}, {}, []

    def blob(rev, path):
        r = subprocess.run(["git", "show", f"{rev}:{path}"], cwd=scratch, capture_output=True, timeout=120)
        return r.stdout if r.returncode == 0 else None

    for path in sorted(carried):
        try:
            mine = (main / path).read_bytes()
        except OSError as e:
            return saved, writes, not_taken, (f"Main's uncommitted {path} could not be read ({e}), so integrate cannot "
                                              "carry it across the merge. Fix that, then run integrate again.")
        saved[path] = mine
        res, nt, problem = _integrate_merge_shared(path, blob(head, path), mine, blob(sha, path), lane_local=False)
        if problem:
            return saved, writes, not_taken, problem
        if res is None:
            return saved, writes, not_taken, (
                f"Main's uncommitted {path} and the merge both change it differently, and integrate does not merge two "
                f"versions of the standards. Ask the developer to commit or undo the uncommitted {path} on main (or "
                "change the lane's version to match), then run integrate again.")
        writes[path] = res
        not_taken += nt
    return saved, writes, not_taken, None


def _integrate_carry_dir(common: Path) -> Path:
    """Where integrate keeps the bytes of main's uncommitted Ratchet files while main moves (next to the lock and the
    journal), so a killed attempt can give them back."""
    return common / "ratchet-integrate-carry"


def _integrate_carry_save(common: Path, saved: dict) -> dict:
    """Writes each uncommitted file's working-tree bytes under the carry folder (the index is not saved: a carried
    file comes back unstaged, and a staged removal is staged again after the write-back). Returns {path: file name}
    for the journal."""
    names = {}
    for i, (path, data) in enumerate(sorted(saved.items())):
        fname = f"{i}-{path.rsplit('/', 1)[-1]}"
        _write_record(_integrate_carry_dir(common) / fname, data, raw=True)
        names[path] = fname
    return names


def _integrate_carry_staged(main: Path, paths) -> dict:
    """{path: 'D' | 'M'} for the carried paths whose index differs from HEAD: a staged removal (the working copy is
    still there) or a staged (or partly staged) edit. Read before the carried files are set back to the tip."""
    out = {}
    if not paths:
        return out
    r = subprocess.run(["git", "diff", "--cached", "--name-status", "-z", "--no-renames", "--", *sorted(paths)],
                       cwd=main, capture_output=True, text=True, timeout=60)
    parts = r.stdout.split("\0")
    for st, path in zip(parts[::2], parts[1::2]):
        if path:
            out[path] = "D" if st.startswith("D") else "M"
    return out


def _integrate_carry_staged_save(main: Path, common: Path, saved: dict):
    """Before the carried files are set back to the tip: every index blob of a carried path (stages 0, 2 and 3) that
    differs from both its saved working-tree bytes and the old tip's blob is content only the index holds, so it is
    written to `<common>/ratchet-integrate-staged-<timestamp>/<i>-<name>`, a folder integrate never removes. Returns
    ({path: saved file}, folder or None). Raises OSError when it cannot write."""
    out, folder, i = {}, None, 0

    def blob(spec):
        r = subprocess.run(["git", "cat-file", "blob", spec], cwd=main, capture_output=True, timeout=60)
        return r.stdout if r.returncode == 0 else None

    for path, data in sorted(saved.items()):
        tip = blob(f"HEAD:{path}")
        ls = subprocess.run(["git", "ls-files", "-s", "-z", "--", path], cwd=main, capture_output=True, text=True,
                            timeout=60).stdout
        for ent in ls.split("\0"):
            fields = ent.split("\t", 1)[0].split()
            if len(fields) < 3:
                continue
            staged = blob(fields[1])
            if staged is None or staged == data or staged == tip:
                continue
            if folder is None:
                folder = common / f"ratchet-integrate-staged-{_dt.datetime.now().strftime('%Y%m%d-%H%M%S-%f')}"
            dst = folder / f"{i}-{path.rsplit('/', 1)[-1]}"
            _write_record(dst, staged, raw=True)
            out[path] = str(dst)
            i += 1
            break
    return out, folder


def _integrate_carry_set_aside(common: Path, folder: Path = None) -> Path:
    """Moves the carry folder to `ratchet-integrate-carry-<timestamp>/` next to it, a name the next attempt never
    overwrites or removes, and returns the folder that holds the saved bytes (the old name when the move fails)."""
    src = folder or _integrate_carry_dir(common)
    if src.name != "ratchet-integrate-carry":
        return src   # already set aside
    dst = src.with_name(f"ratchet-integrate-carry-{_dt.datetime.now().strftime('%Y%m%d-%H%M%S-%f')}")
    try:
        os.rename(str(src), str(dst))
    except OSError:
        return src
    return dst


def _integrate_carry_restore(main: Path, common: Path, names: dict, head: str = None, only_clean: bool = False,
                             staged: dict = None, folder: Path = None):
    """Puts the saved bytes back in main's working tree, unstaged (a staged removal in `staged` is staged again with
    `git rm --cached`), but only while main is still at `head`, the tip the bytes were saved against: once main holds
    the merge (or moved on), a copy from before the merge must not be written over the file, so nothing is written
    and the saved copy is kept. With `only_clean` (recovery after a kill), a file that already equals its saved bytes
    was never reset (its copy is dropped) and one that differs from both the tip and the saved bytes changed since
    and keeps its current bytes. Returns (restored, could-not-write, left-alone, folder, at_tip): the carry folder is
    removed when every copy was written back or dropped, else set aside under a name of its own (`folder`)."""
    done, failed, kept = [], [], []
    src_dir = folder or _integrate_carry_dir(common)
    try:
        cur = subprocess.run(["git", "rev-parse", "HEAD"], cwd=main, capture_output=True, text=True,
                             timeout=60).stdout.strip()
    except subprocess.TimeoutExpired:
        cur = ""
    at_tip = head is None or cur == head
    for path, fname in sorted(names.items()):
        src = src_dir / fname
        if not src.is_file():
            continue
        data = src.read_bytes()
        if not at_tip:
            kept.append(path)
            continue
        if only_clean:
            try:
                now_ = (main / path).read_bytes()
            except OSError:
                now_ = None
            if now_ == data:
                continue   # never reset, or already restored: nothing to do
            if subprocess.run(["git", "diff", "--quiet", "HEAD", "--", path], cwd=main, capture_output=True,
                              timeout=120).returncode != 0:
                kept.append(path)
                continue
        try:
            _write_record(main / path, data, raw=True)
        except OSError:
            failed.append(path)
            continue
        if (staged or {}).get(path) == "D":
            subprocess.run(["git", "rm", "--cached", "-q", "--", path], cwd=main, capture_output=True, timeout=60)
        done.append(path)
    if failed or kept:
        out_folder = _integrate_carry_set_aside(common, src_dir)
    else:
        out_folder = None
        shutil.rmtree(src_dir, ignore_errors=True)
    return done, failed, kept, out_folder, at_tip


def _integrate_unstaged_said(paths, staged_saved: dict = None) -> str:
    """The sentence for carried files that had staged changes and come back unstaged: one whose staged version
    differed from its working copy names where that version is saved; "no bytes lost" only when none was saved."""
    parts = []
    for p in paths:
        at = (staged_saved or {}).get(p)
        if at:
            parts.append(f"{p} had a staged version different from its working copy; that staged version is saved at "
                         f"{at}; the file is now unstaged")
        else:
            parts.append(f"{p} had staged changes: now unstaged, no bytes lost")
    return "; ".join(parts)


def _integrate_carry_said(back, names: dict = None, head: str = None, staged: dict = None,
                          staged_saved: dict = None) -> str:
    """One plain sentence for what _integrate_carry_restore did: which files hold the developer's bytes again (and
    which of them are now unstaged, with where a staged version unlike the working copy is saved), which could not
    be written or were left alone, and where the saved bytes are, with the next step when a copy from before the
    merge must not be copied over the file."""
    done, failed, kept, folder, at_tip = back
    names = names or {}
    parts = []
    if done:
        now_un = [p for p in done if (staged or {}).get(p) == "M"]
        parts.append(f"the developer's bytes were put back into {', '.join(done)}, uncommitted"
                     + (f" ({_integrate_unstaged_said(now_un, staged_saved)})" if now_un else ""))
    if failed:
        parts.append(f"the developer's bytes could not be written back to {', '.join(failed)}")
    if not at_tip and kept:
        parts.append(f"main is no longer at {(head or '')[:9]}, the tip the uncommitted {', '.join(kept)} was saved "
                     f"against, so the saved copy (from before the merge) was not written over the file; it is in "
                     f"{folder}. Do not copy it over the file: to re-add only the developer's own edits, compare "
                     f"`git show {(head or '')[:9]}:<path>` with the saved copy "
                     f"({', '.join(str(folder / names[p]) if p in names else p for p in kept)}) and apply that "
                     "difference by hand")
    elif kept:
        parts.append(f"{', '.join(kept)} changed since and keeps its current bytes; the saved bytes are in {folder}: "
                     f"compare `git show {(head or 'HEAD')[:9]}:<path>` with the saved copy to see the developer's own "
                     "edits, and re-add them by hand")
    if failed and folder:
        parts.append(f"the saved bytes of {', '.join(failed)} are in {folder} (put them back by hand)")
    return "; ".join(parts) + "." if parts else "nothing needed restoring."


def _integrate_merge(main: Path, f: dict, info: dict, finish):
    """The real merge, after every check passed (see cmd_integrate). `finish(result, suite, message, detail, commits)`
    records the attempt and ends the command. A journal of the attempt (lane, run, main's tip, the merge commit once
    made, the suite's state) is kept next to the integrate lock until the record line is written, so an attempt killed
    mid-run is recorded by the next integrate (_integrate_recover)."""
    import types
    name, slug, head, lhead, target = f["name"], f["slug"], f["head"], f["lhead"], f["target"]
    if not f["commits"]:
        finish("no-op", "not-run", f"The lane '{name}' is already merged into {target} (its tip is in main's history), "
               "so nothing was changed.")
        return
    cfg = f["mctx"].config()
    suite = cfg.get("regression_command")
    if not suite:
        finish("refused", "not-run", "No regression_command is set, and integrate will not merge code that no suite "
               "has run on. Set one with `config --set regression_command=...`, then run integrate again. Nothing was "
               "changed.")
    timeout = int(cfg.get("test_timeout_sec") or DEFAULT_CONFIG["test_timeout_sec"])
    layout = _integrate_layout_problem(main, head, lhead)
    if layout:
        finish("refused", "not-run", layout)

    def git(d, *a):
        return subprocess.run(["git", *a], cwd=d, capture_output=True, text=True, timeout=120)

    state = {"suite": "not-run"}

    def rolled(msg, suite_state, detail=None, commits=None, clean=True):
        # `clean` is False when a carried file could not be put back: then main did change, and the message says how
        finish("rolled-back", suite_state, msg + (" Nothing was changed." if clean else ""), detail or msg, commits)

    def path_of(r):  # a path git printed for main, made absolute
        p = Path(r.stdout.strip())
        return p if p.is_absolute() else main / p

    common = path_of(git(main, "rev-parse", "--git-common-dir"))
    hooks = git(main, "config", "--get", "core.hooksPath").stdout.strip()
    if hooks and not hooks.startswith("~") and not os.path.isabs(hooks):
        hooks = str(Path(git(main, "rev-parse", "--show-toplevel").stdout.strip() or main) / hooks)
    hooks = hooks or str(path_of(git(main, "rev-parse", "--git-path", "hooks")))
    entry = {"lane": name, "run": slug, "head": head, "lhead": lhead, "target": target, "sha": None,
             "suite": "not-run", "started": now()}
    _write_record(_integrate_journal(common), entry)
    tmp = Path(tempfile.mkdtemp(prefix=info["prefix"]))
    try:
        # a clone of its own that borrows main's objects (so main's worktree list, refs and files are never touched
        # while the suite runs); its commits come back to main by a fetch once the suite has passed. It takes main's
        # own local git settings (identity, signing, merge drivers, filters, attributes) and runs main's hooks, so the
        # merge commit is made the way a merge in main would be
        who = []
        for k, d in (("user.name", "Ratchet"), ("user.email", "ratchet@localhost")):
            who += ["-c", f"{k}={git(main, 'config', k).stdout.strip() or d}"]
        r = git(main, "clone", "-q", "--shared", "--no-checkout", str(main), str(tmp))
        if r.returncode == 0:
            r = git(tmp, "config", "--local", "--add", "include.path", str(common / "config"))
        if r.returncode == 0:
            attrs = path_of(git(main, "rev-parse", "--git-path", "info/attributes"))
            try:
                if attrs.is_file():
                    (tmp / ".git" / "info").mkdir(exist_ok=True)
                    shutil.copyfile(str(attrs), str(tmp / ".git" / "info" / "attributes"))
            except OSError:
                pass
            # no hook runs for this checkout: nothing is checked out in main, so no checkout hook would run there
            r = git(tmp, "-c", f"core.hooksPath={tmp / '.git' / 'ratchet-no-hooks'}", "checkout", "-q", "--detach", head)
        if r.returncode != 0:
            rolled(f"Could not make the scratch copy of main to merge in ({(r.stderr or r.stdout).strip()[:300]}).",
                   "not-run")
        mcfg = ["-c", f"core.hooksPath={hooks}"]
        for dep in DEP_DIRS:
            if (main / dep).exists() and not (tmp / dep).exists():
                try:
                    (tmp / dep).symlink_to(main / dep)
                except OSError:
                    pass
        r = git(tmp, *who, *mcfg, "merge", "--no-ff", "--no-commit", lhead)
        if r.returncode != 0:
            files = git(tmp, "diff", "--name-only", "--diff-filter=U").stdout.split()
            project = [x for x in files if x not in MERGE_SHARED]
            if project:
                rolled(f"Merging the lane '{name}' into {target} conflicts in: {', '.join(project)}. Have the lane's "
                       "agent merge main into the lane (git merge main, resolve the files, commit, then run "
                       "`ratchet.py merged`), then run integrate again.", "not-run")
            if not files:
                rolled(f"git could not merge the lane '{name}' ({(r.stderr or r.stdout).strip()[:300]}).", "not-run")
        # Ratchet's own shared files are merged by Ratchet's rules, whether git conflicted on them or not
        info["not_taken"], problem = _integrate_resolve_shared(tmp, head, lhead, name, git)
        if problem:
            rolled(problem, "not-run")
        left = git(tmp, "diff", "--name-only", "--diff-filter=U").stdout.split()
        if left:
            rolled(f"Merging the lane '{name}' into {target} left conflicts in: {', '.join(left)}. Have the lane's "
                   "agent merge main into the lane (git merge main, resolve the files, commit, then run "
                   "`ratchet.py merged`), then run integrate again.", "not-run")
        r = git(tmp, *who, *mcfg, "commit", "-q", "-m", f"Merge lane '{name}' (run {slug})", "-m",
                f"Ratchet-Integrated: {name} {slug}")
        if r.returncode != 0:
            rolled(f"git could not commit the merge ({(r.stderr or r.stdout).strip()[:300]}).", "not-run")
        sha = git(tmp, "rev-parse", "HEAD").stdout.strip()
        git(tmp, "update-ref", "refs/heads/ratchet-integrate", sha)
        entry["sha"] = sha
        _write_record(_integrate_journal(common), entry)
        commits = [sha] + list(f["hashes"])  # recorded only once the merge commit is in main; until then the record
        # keeps the lane's tip, since the scratch merge commit exists nowhere else
        touched = set(git(tmp, "diff", "--name-only", head, sha).stdout.split())
        # main's uncommitted Ratchet files are carried across the merge: a re-apply the rules cannot do (the
        # uncommitted standards.md and the merge both change it) is found here, before the suite and before main
        # is touched; it is checked again under main's lock right before main moves
        _s, _w, _nt, problem = _integrate_carry_plan(main, tmp, head, sha, [x for x in f["carried"] if x in touched])
        if problem:
            rolled(problem, "not-run")
        # (a carried Ratchet file with a staged removal shows as untracked too: it is carried, not refused)
        loose = sorted(x for x in _integrate_untracked(main) if x in touched and x not in f["carried"])
        if loose:
            rolled(f"Main has a file git does not track yet ({', '.join(loose[:5])}) at a path the lane also adds, so "
                   "main cannot take the merge. Ask the developer to move or delete that file (or commit it), then run "
                   "integrate again.", "not-run")
        _warn_if_foreground(f["mctx"], cfg, what="integrate", rerun=False)
        code, out, _dur = _run_cmd(types.SimpleNamespace(root=tmp, config=lambda: cfg), suite, tmp / "integrate-suite.log", timeout)
        if code != 0:
            tail = "\n".join(out.strip().splitlines()[-40:])[-3000:]
            how = (f"timed out after {timeout}s" if code == 124 else f"failed (exit {code})")
            rolled(f"The suite {how} on the merged code, so main was not changed. Last output:\n{tail}\nHave the "
                   "lane's agent fix the failure in the lane and finish the lane again, then run integrate again.",
                   "failed", f"The suite {how} on the merged code.")
        state["suite"] = entry["suite"] = "passed"
        _write_record(_integrate_journal(common), entry)
        # what the suite tested must be the merge commit itself: a suite that rewrites tracked files first (a code
        # generator or formatter that runs before the tests) passed on something else
        st = subprocess.run(["git", "--no-optional-locks", "status", "--porcelain", "-z", "--no-renames",
                             "--untracked-files=no"], cwd=tmp, capture_output=True, text=True, timeout=120)
        moved = [x[3:] for x in st.stdout.split("\0") if x]
        if git(tmp, "rev-parse", "HEAD").stdout.strip() != sha or moved:
            rolled(f"The suite passed, but it changed tracked files in the merged copy ({', '.join(moved[:5]) or 'HEAD'}), "
                   "so what it tested is not the merge commit. Make the regression command leave tracked files as they "
                   "are (commit generated files in the lane, or generate them outside the tracked tree), then run "
                   "integrate again.", "passed", "The suite changed tracked files in the merged copy.")

        carry, saved = [], {}   # main's uncommitted Ratchet files the merge changes, as seen under main's lock

        def main_problem():
            """(message, short detail) for what changed in main while the suite ran, or None. Run holding main's state
            lock, right before the fast-forward: the same checks as before the suite, plus the tip and the branch."""
            cur = git(main, "rev-parse", "HEAD").stdout.strip()
            if cur != head:
                return (f"Main moved while the suite ran (it was at {head[:9]}, it is now at {cur[:9]}), so nothing "
                        "was merged. Run integrate again: it merges onto the new tip.", "Main moved while the suite ran.")
            br = git(main, "rev-parse", "--abbrev-ref", "HEAD").stdout.strip() or "HEAD"
            if br != target:
                return (f"Main's checkout was switched from {target} to {br} while the suite ran, so nothing was "
                        f"merged. Switch it back to {target}, then run integrate again.",
                        "Main's branch changed while the suite ran.")
            if git(main, "rev-parse", "-q", "--verify", "MERGE_HEAD").returncode == 0:
                return ("The suite passed, but a merge was started in the main checkout while it ran. Finish or abort "
                        "it, then run integrate again.", "A merge started in main while the suite ran.")
            run_why = _integrate_run_problem(main, f["mctx"])
            if run_why:
                return ("The suite passed, but main's own run changed while it ran. " + run_why,
                        "Main's run was in the middle of a step when the suite ended.")
            bad, carried = [], []
            for path in _integrate_dirty(main, False):
                (carried if path in MERGE_SHARED else bad).append(path)
            if bad:
                return (f"The suite passed, but main now has uncommitted changes to project files "
                        f"({', '.join(bad[:5])}). Ask the developer to commit or stash them (integrate does not touch "
                        "them), then run integrate again.", "Main got uncommitted changes while the suite ran.")
            carry[:] = sorted(x for x in carried if x in touched)
            loose_now = sorted(x for x in _integrate_untracked(main) if x in touched and x not in carried)
            if loose_now:
                return (f"The suite passed, but main now has a file git does not track yet ({', '.join(loose_now[:5])}) "
                        "at a path the lane also adds. Ask the developer to move or delete that file (or commit it), "
                        "then run integrate again.", "Main got an untracked file the lane adds.")
            return None

        # nothing in main may change between the last check and the fast-forward, so both happen holding main's
        # state lock (the lock every command that changes main's run takes); a developer's merge.autoStash setting
        # must never turn an edit made meanwhile into conflict markers, so the fast-forward is told not to stash
        slock = _StateLock(main, cmd="integrate")
        try:
            lwhy = slock.acquire()
            if lwhy:
                rolled("The suite passed, but Ratchet is busy in the main checkout, so integrate could not check main "
                       f"before moving it ({lwhy.split(' Nothing was done')[0]}). Try again when it finishes.",
                       "passed", "Main's state was busy when the suite ended.")
            problem = main_problem()
            if problem:
                rolled(problem[0], "passed", problem[1])
            # main's run's rules and reference files as they stand now, uncommitted edits included, so a rule the
            # developer changed before (not yet approved) is never taken for one the integrate changed
            before = _integrate_rules_snapshot(f["mctx"])
            # main's uncommitted Ratchet files the merge changes: their bytes are saved next to the journal, the
            # paths are set back to main's tip for the fast-forward only, and the saved copy is re-applied by the
            # per-file rules afterwards, still uncommitted. A re-apply the rules cannot do stops here, main untouched.
            saved, writes, carry_nt, problem = _integrate_carry_plan(main, tmp, head, sha, carry)
            if problem:
                rolled("The suite passed, but " + problem[0].lower() + problem[1:], "passed", problem)
            names, staged = {}, {}
            landed = False
            try:
                if saved:
                    staged = _integrate_carry_staged(main, saved)   # staged edits come back unstaged, listed; a
                    # staged removal is staged again after the write-back; a staged version unlike the working
                    # copy is kept in a folder of its own (never removed) and named
                    try:
                        names = _integrate_carry_save(common, saved)
                        info["staged_saved"], _sf = _integrate_carry_staged_save(main, common, saved)
                    except OSError as e:
                        rolled(f"The suite passed, but integrate could not save a copy of main's uncommitted "
                               f"{', '.join(saved)} before moving main ({e}). Make {common} writable, then run integrate "
                               "again.", "passed", "Main's uncommitted Ratchet files could not be saved.")
                    entry["carried"], entry["staged"], entry["staged_saved"] = names, staged, info["staged_saved"]
                    _write_record(_integrate_journal(common), entry)
                    r = git(main, "checkout", "-q", "HEAD", "--", *sorted(saved))
                    if r.returncode != 0:
                        rolled(f"The suite passed, but integrate could not set main's uncommitted {', '.join(saved)} "
                               f"aside for the fast-forward ({(r.stderr or r.stdout).strip()[:200]}). Run integrate "
                               "again.", "passed", "Main's uncommitted Ratchet files could not be set aside.")
                late = ""
                r = git(main, "fetch", "-q", str(tmp), "refs/heads/ratchet-integrate")  # only brings the commit's objects
                if r.returncode == 0:
                    try:
                        # main's hooks (post-merge, say) run inside this call, so it gets the suite's time limit; a hook
                        # still running after that does not undo a fast-forward that already happened
                        r = subprocess.run(["git", "-c", "merge.autoStash=false", "merge", "--ff-only",
                                            "--no-overwrite-ignore", sha], cwd=main, capture_output=True, text=True,
                                           timeout=max(120, timeout))
                    except subprocess.TimeoutExpired:
                        if git(main, "rev-parse", "HEAD").stdout.strip() != sha:
                            raise
                        r = types.SimpleNamespace(returncode=0, stdout="", stderr="")
                        late = (f" A git hook on main was still running after {max(120, timeout)}s, so integrate stopped "
                                "waiting for it; check its result yourself.")
                landed = r.returncode == 0 and git(main, "rev-parse", "HEAD").stdout.strip() == sha
            finally:
                # whatever stopped the fast-forward (a refusal, a git timeout), the carried files get their bytes
                # back while main is still at its old tip; once main holds the merge, the saved copy (from before
                # it) is never written over the file: it is set aside and named, with the next step
                if names and not landed:
                    back = _integrate_carry_restore(main, common, names, head=head, staged=staged)
                    state["carry"] = _integrate_carry_said(back, names, head, staged, info.get("staged_saved"))
                    state["carry_ok"] = not (back[1] or back[2])
                    if back[3]:   # the next integrate's recovery finds the set-aside copy by this name
                        entry["carry_folder"] = str(back[3])
                        try:
                            _write_record(_integrate_journal(common), entry)
                        except OSError:
                            pass
                    if sys.exc_info()[0] is SystemExit:   # a refusal already printed its message: add the note
                        print("RATCHET: note: main's uncommitted Ratchet files: " + state["carry"], file=sys.stderr,
                              flush=True)
            if landed:
                info["commits"] = commits
                folder = None
                if names:
                    # the saved copy is set aside under its own name before the write-back and named until every
                    # write succeeded, so a cut-off here (a git timeout) leaves it findable and never overwritten
                    folder = _integrate_carry_set_aside(common)
                    entry["carry_folder"] = str(folder)
                    _write_record(_integrate_journal(common), entry)
                    state["carry"] = (f"main holds the merge; the developer's uncommitted bytes of "
                                      f"{', '.join(sorted(names))} (from before it) are saved in {folder}. Do not copy "
                                      "them over the files: compare `git show "
                                      f"{head[:9]}:<path>` with the saved copy to see the developer's own edits, and "
                                      "re-add only those by hand.")
                failed, err = [], ""
                for path, data in sorted(writes.items()):   # plain file writes only: no git call in this loop
                    try:
                        _write_record(main / path, data, raw=True)   # the working tree only: never staged
                    except OSError as e:
                        failed, err = [path], str(e)
                        break
                if failed:
                    # main goes back to its old tip only while it is still at the merge just made: first the carried
                    # paths are set to the merge commit's own versions (what HEAD holds, so nothing is staged against
                    # it), then main is moved back; the developer's files get their saved bytes only once main is
                    # back at that tip. When main already moved on, nothing is written at all.
                    cur = git(main, "rev-parse", "HEAD").stdout.strip()
                    undo = types.SimpleNamespace(returncode=1, stdout="", stderr=f"main moved on to {cur[:9]}")
                    if cur == sha:
                        undo = git(main, "checkout", "-q", sha, "--", *sorted(saved))
                        if undo.returncode == 0:
                            undo = git(main, "reset", "-q", "--keep", head)
                    back = _integrate_carry_restore(main, common, names, head=head, staged=staged, folder=folder)
                    said = _integrate_carry_said(back, names, head, staged, info.get("staged_saved"))
                    if back[4]:   # main is back at its old tip
                        info["commits"] = [lhead]
                        rolled(f"Main took the merge, but main's uncommitted {failed[0]} could not be written back "
                               f"({err}). Main was moved back to {head[:9]} and {said} Make {failed[0]} writable, then "
                               "run integrate again.", "passed",
                               f"Main's uncommitted {failed[0]} could not be re-applied after the merge.",
                               clean=not (back[1] or back[2]))
                    finish("merged", "passed",
                           f"Main took the merge (merge commit {sha[:9]}), but main's uncommitted {failed[0]} could not "
                           f"be written back ({err}), and main could not be moved back "
                           f"({(undo.stderr or undo.stdout).strip()[:200]}); it stays at the merge with "
                           f"{', '.join(sorted(saved))} at the merge's version, nothing staged. {said} Make "
                           f"{failed[0]} writable first. Nothing was pushed.",
                           f"Main took the merge, but main's uncommitted {failed[0]} could not be re-applied: {err}",
                           commits)
                    return
                for path, how in sorted(staged.items()):
                    if how == "D" and path in writes:   # the developer's staged removal, staged again
                        git(main, "rm", "--cached", "-q", "--", path)
                info["unstaged"] = [p for p in sorted(writes) if staged.get(p) == "M"]
                if folder:
                    shutil.rmtree(str(folder), ignore_errors=True)
                    state.pop("carry", None)
                info["not_taken"] = list(dict.fromkeys(list(info.get("not_taken") or []) + carry_nt))
                _integrate_move_base(main, f["mctx"], sha, name, slug, before)
        finally:
            slock.release()
        if not landed:
            why = (r.stderr or r.stdout).strip()
            carry_note = (" Main's uncommitted Ratchet files: " + state["carry"]) if state.get("carry") else ""
            if "untracked" in why.lower() or "ignored" in why.lower():
                rolled(f"The suite passed, but main could not take the merge: a file git does not track yet would be "
                       f"overwritten ({why[:300]}). Ask the developer to move or delete that file (or commit it), then "
                       f"run integrate again.{carry_note}", "passed", "Main could not take the merge: " + why[:200],
                       clean=state.get("carry_ok", True))
            rolled(f"The suite passed, but main could not take the merge ({why[:300]}). Ask the developer to commit "
                   f"the uncommitted changes in main (or stash them), then run integrate again.{carry_note}", "passed",
                   "Main could not take the merge: " + why[:200], clean=state.get("carry_ok", True))
        nt = info.get("not_taken") or []
        finish("merged", "passed", f"Merged the lane '{name}' (run '{slug}') into {target}: {len(f['commits'])} "
               f"commit(s), merge commit {sha[:9]}. The suite passed on exactly that commit before {target} moved. "
               f"Nothing was pushed.{late}"
               + (f"\nLane settings in {RATCHET_DIR}/config.json not taken (main's kept, by Ratchet's rules): "
                  f"{', '.join(nt)}." if nt else "")
               + (f"\nMain's uncommitted {', '.join(sorted(saved))} carried across the merge, still uncommitted"
                  + (f" ({_integrate_unstaged_said(info['unstaged'], info.get('staged_saved'))})"
                     if info.get("unstaged") else "") + "." if saved else ""), None, commits)
    except subprocess.TimeoutExpired as e:
        cmd = " ".join(str(a) for a in (e.cmd if isinstance(e.cmd, (list, tuple)) else [e.cmd]))[:80]
        carry_note = (" Main's uncommitted Ratchet files: " + state["carry"]) if state.get("carry") else ""
        try:
            took = bool(entry.get("sha")) and subprocess.run(["git", "rev-parse", "HEAD"], cwd=main, capture_output=True,
                                                             text=True, timeout=60).stdout.strip() == entry["sha"]
        except subprocess.TimeoutExpired:
            took = False
        if took:
            finish("merged", state["suite"], f"A git command timed out ({cmd}) after main took the merge commit "
                   f"{entry['sha'][:9]}; integrate stopped there. Main's run was not changed: if it is in the middle of "
                   f"a step, that step's diff also shows the lane's changes. Nothing was pushed.{carry_note}",
                   "A git command timed out after main took the merge: " + cmd, [entry["sha"]] + list(f["hashes"]))
        finish("rolled-back", state["suite"], f"A git command timed out ({cmd}), so integrate stopped. Check "
               "`git status` and `git log -1` in main to see whether it took the merge, then run integrate again (it "
               f"says 'already merged' if it did).{carry_note}", "A git command timed out: " + cmd, info.get("commits"))
    finally:
        _integrate_drop_scratch(tmp)


# The routine approvals a director may sign AND apply in one call (`director-sign <action> ... --apply`). Everything
# else a director signs (plan approval, step and final review, cancel, set-review, hooks-waive, ui-respec, guardrail,
# feedback) stays a token the lane applies: --apply is refused there and approves nothing.
DIRECTOR_APPLY_ACTIONS = ("approve-changes", "accept-finding", "raise-limit", "choice")


def _director_apply_cmd(ctx, action, cp=None, eng="ratchet.py") -> str:
    """The one-step director command for a routine approval in this lane, with its arguments spelled out."""
    tail = {"accept-finding": f" {cp or '<CPn>'} --ids <ids> --reason \"<why>\"",
            "raise-limit": f" {cp or '<CPn>'} --reason \"<why>\"",
            "choice": " <letter>"}.get(action, "")
    return f"{eng} --root {ctx.root} director-sign {action}{tail} --apply"


def _director_apply_ask(ctx, st, action, target, ids):
    """The question step `--apply` runs itself, exactly as the lane's own `ask` records it (pending question,
    awaiting_since moved, `question_asked` logged), with the chat text it would print kept off stdout: nothing is
    put to anyone, the director's own command is the answer."""
    if action == "approve-changes":
        overtook = _overtake(ctx, st, "approve-changes", None)
        asked = now()
        st["pending"] = {"action": "approve-changes", "mode": None, "asked_at": asked,
                         "prev_awaiting": st.get("awaiting_since"),
                         "session": _asking_session(ctx, st, "approve-changes"), **overtook}
        st["awaiting_since"] = asked
        ctx.log(st, "question_asked", action="approve-changes", mode=None)
        ctx.save_state(st)
        return
    ns = argparse.Namespace(action=action, mode=target, ids=ids, options=None, locked=None, guardrail=None)
    with contextlib.redirect_stdout(io.StringIO()):
        if action == "raise-limit":
            _ask_raise_limit(ctx, st, ns)
        else:
            _ask_accept_finding(ctx, st, ns)


# ---- the developer's policy for routine approvals ------------------------------------------------------------------
# One file per user, next to the director key (RATCHET_HOME/director-policy.json), changed only by `director-policy`
# from the director session (the guard keeps builder sessions out of RATCHET_HOME). With no file, director-sign works
# as it always did. With a file, each of the four routine approvals is signed only when a rule covers it.
POLICY_FILE = "director-policy.json"
POLICY_SEVERITIES = {"major": 1, "minor": 2}
POLICY_NEVER = ("approve-plan", "human-approve", "feedback", "cancel", "set-review", "hooks-waive", "ui-respec",
                "guardrail", "paid-provider")
POLICY_MENU = ("approve-changes=test-files, raise-limit=max:<N> (N of 1 or more signed raises per run), "
               "choice=no-unlock, accept-finding=max:<minor|major>")


def _policy_path() -> Path:
    return ratchet_home() / POLICY_FILE


def _policy_rule_problem(action, rule) -> str | None:
    """None when `rule` is a rule the menu offers for `action`; otherwise a plain reason."""
    if action in POLICY_NEVER:
        return (f"{action} can never be covered by a policy: it is the developer's own approval (plans, scope, final "
                "approval, cancel, review settings, hooks waivers, paid providers). Nothing was changed.")
    if action not in DIRECTOR_APPLY_ACTIONS:
        return f"{action} is not a routine approval. A rule is for one of: {', '.join(DIRECTOR_APPLY_ACTIONS)}. Nothing was changed."
    rule = rule if isinstance(rule, str) else ""
    if action == "approve-changes" and rule != "test-files":
        return "approve-changes takes the rule test-files (changes to test files only). Nothing was changed."
    if action == "choice" and rule != "no-unlock":
        return "choice takes the rule no-unlock (lettered options that unlock no locked file). Nothing was changed."
    if action == "raise-limit" and not (re.fullmatch(r"max:[0-9]+", rule) and int(rule[4:]) >= 1):
        return "raise-limit takes max:N with N of 1 or more (signed raises per run). Nothing was changed."
    if action == "accept-finding" and not (rule.startswith("max:") and rule[4:] in POLICY_SEVERITIES):
        return "accept-finding takes max:minor or max:major (never blocker). Nothing was changed."
    return None


def _load_policy():
    """(policy or None when no file, problem or None). A policy is {"rules": {action: rule}, "changes": [...]};
    one that can't be read or holds a rule the menu does not offer is a problem (routine approvals fail closed)."""
    p = _policy_path()
    data, why = _read_record(p, missing=None)
    if why is None and data is not None:
        rules, changes = data.get("rules"), data.get("changes")
        if not isinstance(rules, dict) or not isinstance(changes, list) or any(
                _policy_rule_problem(a, r) for a, r in rules.items()):
            why = "it does not hold a valid policy"
    if why:
        return None, (f"The developer's policy file {p} (director-policy.json) is unreadable or damaged ({why}). "
                      "Routine approvals are refused until the developer resets it: ask the developer for their rules, then "
                      "`director-policy --set <action>=<rule>` rewrites the file from scratch (the repair is logged), or "
                      "`director-policy --clear <action>` deletes it. Nothing was signed.")
    return data, None


def cmd_director_policy(args):
    """`director-policy` (director session only): show (`--json`), `--set <action>=<rule>` or `--clear <action>` the
    developer's policy for routine approvals. Every change is logged in the file with its time."""
    require_director_session("director-policy")
    pol, bad = _load_policy()
    setting, clearing = getattr(args, "set", None), getattr(args, "clear", None)
    if getattr(args, "remove", False):  # the one way back to no policy at all, logged in its own record
        if pol is None and not bad:
            die("There is no policy file to remove. Nothing was changed.")
        try:
            _append_record(_policy_path().with_name("director-policy-removed.jsonl"), json.dumps(
                {"at": now(), "removed": True, "rules": (pol or {}).get("rules"), "damaged": bool(bad)}) + "\n")
            _policy_path().unlink()
        except OSError as e:
            die(f"Couldn't remove {_policy_path()} ({e.strerror or e}). Nothing was changed.")
        ok("The policy was removed (logged in director-policy-removed.jsonl): no policy is set, so director-sign works as it did before any policy.")
        return
    if bad and not (setting or clearing):
        die(bad)
    if setting or clearing:
        pol = pol or {"rules": {}, "changes": []}
        if bad:  # --set or --clear over a damaged file starts again from nothing, and says so in the change log
            pol["changes"].append({"at": now(), "action": "(policy file)", "repair": "damaged file replaced"})
            if clearing:  # a damaged file has no rule to clear: replacing it with an empty (fail-closed) policy is the repair
                _write_record(_policy_path(), pol, pretty=True)
                ok("The damaged policy file was replaced by a policy with no rules (logged): every routine approval asks the developer.")
                return
        if setting:
            action, _, rule = setting.partition("=")
            action, rule = action.strip(), rule.strip()
            why = _policy_rule_problem(action, rule)
            if why:
                die(f"{setting}: {why} The menu: {POLICY_MENU}.")
            pol["rules"][action] = rule
            pol["changes"].append({"at": now(), "action": action, "rule": rule})
        else:
            if clearing not in pol["rules"]:
                die(f"No rule is set for {clearing}. Nothing was changed.")
            del pol["rules"][clearing]
            pol["changes"].append({"at": now(), "action": clearing, "clear": True})
        try:
            _write_record(_policy_path(), pol, pretty=True)  # with the last rule gone it keeps only the history
        except OSError as e:
            die(f"Couldn't update {_policy_path()} ({e.strerror or e}). Nothing was changed.")
    if getattr(args, "json", False):
        print(json.dumps(pol or {"rules": {}, "changes": []}, indent=2))
        return
    rules = (pol or {}).get("rules") or {}
    if pol is not None and not rules:  # a policy file with no rules covers nothing
        print("A policy with no rules: every routine approval asks the developer. Add a rule with "
              f"`director-policy --set <action>=<rule>` (the menu: {POLICY_MENU}), or remove the policy with "
              "`director-policy --remove`.")
        return
    if not rules:
        print("No policy is set: routine approvals are signed as the director sees fit. Set a rule with "
              f"`director-policy --set <action>=<rule>`; the menu: {POLICY_MENU}.")
        return
    print(f"The developer's policy ({_policy_path()}); a routine approval no rule covers is refused:")
    for a, r in rules.items():
        print(f"  {a}: {r}")


def _policy_field(args) -> dict:
    """The log field naming the policy rule a director signature used (nothing for a chat approval or no policy)."""
    r = getattr(args, "policy_rule", None)
    return {"policy_rule": r} if r else {}


def _policy_test_edit_ok(ctx, st, problem: str) -> bool:
    """Whether an integrity problem on a test file is one the approve-changes=test-files rule covers."""
    mm = re.match(r"test file (\S+?)(:| \()", problem)
    if not mm or not (ctx.root / mm.group(1)).exists():
        return False  # not a test-file problem we can read, or the file is gone
    rel = mm.group(1)
    if not rel.endswith(".py"):
        # Ratchet cannot analyse other languages (an inserted `return;` or `process.exit(0)` above a planned test
        # looks like an addition); appended tests raise no problem at all, so they need no approval. Ask the developer.
        return False
    # Python: covered only when the whole module is unchanged apart from comments and formatting (the freeze proves
    # the planned tests' own defs, not helpers, imports or module-level code)
    old_p = ctx.run_dir() / "evidence" / str(st.get("current")) / "red-tests" / rel.replace("/", "__")
    try:
        old = ast.dump(ast.parse(old_p.read_text(errors="replace")))
        new = ast.dump(ast.parse((ctx.root / rel).read_text(errors="replace")))
    except (OSError, SyntaxError, ValueError, RecursionError):
        return False
    return old == new


def _policy_apply(args, ctx, st, action, target, ids=()):
    """A lane command applying a director token re-checks the policy against the lane as it is now, under the same
    state lock as the apply, and records the rule it finds (so a token signed apart from its apply, by the plain
    `director-sign`, still logs `policy_rule`, and a token the policy no longer covers is refused). `director-sign
    --apply` has checked already (policy_checked)."""
    if getattr(args, "policy_checked", False) or not getattr(args, "director_token", None):
        return
    args.policy_rule = _policy_rule_for(ctx, st, action, target, list(ids))


def _policy_refuse(what, ask=True):
    die(f"{what}" + (" Ask the developer; nothing was signed or changed." if ask else ""))


def _policy_rule_for(ctx, st, action, target, ids) -> str | None:
    """The rule text that covers this routine signature, or None when there is no policy file; dies (before anything
    is signed, asked or written) when a policy exists and no rule covers it, or the file is damaged."""
    pol, bad = _load_policy()
    if bad:
        die(bad)
    if pol is None:  # no file at all: director-sign works as it always did
        return None
    rule = (pol.get("rules") or {}).get(action)
    if not rule:
        _policy_refuse(f"The developer's policy has no {action} rule, so the director may not sign {action}.")
    if action == "approve-changes":
        errs = validate_plan(ctx.plan())
        if errs:
            die("Plan invalid:\n  - " + "\n  - ".join(errs))
        probs = integrity_problems(ctx, st)
        # covered: a test file that still exists and keeps every line it had at the red run (only lines added; a
        # non-Python file is compared line by line, so a skip, a deletion, an emptied body or a swapped assertion is
        # a replace or delete and is not covered); Python keeps the structural freeze's own refusals (a skipped,
        # ended-early, removed or re-declared planned test is not covered)
        frozen = [pr for pr in probs if pr.startswith("test file ") and not _policy_test_edit_ok(ctx, st, pr)]
        if frozen:
            _policy_refuse(f"The approve-changes rule covers edits that keep every planned test, but a planned test "
                           f"was skipped, removed, weakened or its file deleted: {'; '.join(frozen)[:300]}.")
        other = [pr for pr in probs if not pr.startswith("test file ")]
        if other:
            _policy_refuse(f"The approve-changes rule covers test files only, but these changed too: "
                           f"{_problems_for_director(other)}.")
    elif action == "raise-limit":
        n = int(rule[4:])
        used = sum(1 for e in st.get("history") or [] if e.get("event") == "round_limit_raised" and e.get("by") == "director")
        if used >= n:
            _policy_refuse(f"The raise-limit rule ({rule}) is used up: {used} of {n} raises are already signed in this run.")
        return f"raise-limit: {rule} ({used + 1} of {n})"
    elif action == "choice":
        p = st.get("pending") or {}
        letter = target.upper()
        files = (p.get("locked") or {}).get(letter) or []
        kind = (p.get("guardrail") or {}).get(letter)
        if files or kind:
            _policy_refuse(f"The choice rule ({rule}) covers options that unlock nothing, but option {letter} "
                           + (f"unlocks {', '.join(files)}" if files else f"adds a guardrail step for '{kind}'") + ".")
    elif action == "accept-finding":
        p = st.get("pending") or {}
        cp = target or p.get("mode") or ""
        ids = ids or p.get("ids") or []
        cps = (st.get("checkpoints") or {}).get(cp) or {}
        rnd = cps.get("adv_round")
        opened = _adv_open_findings(ctx, cp, rnd, cps) if rnd else []
        top = POLICY_SEVERITIES[rule[4:]]
        over = []  # (id as named, finding) for every named finding above the rule's severity
        for i in ids:
            f, _err = _resolve_finding_ref(i, opened)  # a bare id or 'reviewer/id'; unknown ids fail later, as today
            r = _SEVERITY_RANK.get(str((f or {}).get("severity", "")).strip().lower()) if f else top
            if r is None or r < top:
                over.append((i, f))
        if over:
            sev = ", ".join(f"{i} ({f.get('severity')})" for i, f in over)
            _policy_refuse(f"The accept-finding rule ({rule}) does not cover {sev}.")
    return f"{action}: {rule}"


def cmd_director_sign(args):
    """Sign the lane's current pause for `action` and print the token (stdout's last line) that the lane applies
    with `--director-token`. With `--apply`, for a routine approval (DIRECTOR_APPLY_ACTIONS) only: the question step
    the action needs is run here (`ask approve-changes`, `ask accept-finding CPn <ids>`, `ask raise-limit CPn`; a
    lettered choice is signed from the question the lane itself registered with `ask choice`), the token is signed
    and applied at once, all under one hold of the lane's state lock (see _changes_state), so the token cannot go
    stale between the ask and the apply; a refusal (a missing --reason, an unknown id, a letter not offered, the
    wrong phase, a lane that is not enrolled) comes before anything is asked or written. The old separate steps
    (the lane's ask, this command without --apply, the lane's command with the token) still work unchanged. When the
    developer has a policy file (`director-policy`), the four routine actions are policy-checked first, on both paths:
    one no rule covers (or a damaged policy file) is refused before anything is signed. A covered plain signature
    prints a token; the lane's command that applies it checks the policy again under its own lock and records the
    rule as `policy_rule`, the same as `--apply` does."""
    require_director_session("director-sign")
    action = args.action
    apply = bool(getattr(args, "apply", False))
    if apply and action not in DIRECTOR_APPLY_ACTIONS:
        die(f"director-sign {action} takes no --apply: only the routine approvals ({', '.join(DIRECTOR_APPLY_ACTIONS)}) "
            f"are signed and applied in one step. Nothing was signed or approved. Without --apply, director-sign "
            f"{action} prints a token the lane applies with `{action} --director-token <t>`.")
    ctx = Ctx(find_root())
    if apply and approval_mode(ctx) != "director":
        die(f"{ctx.root} is not director-enrolled: this lane takes the developer's own approval (its agent asks in "
            "chat and only the developer's reply counts), so there is nothing for --apply to do. Nothing was asked or "
            f"approved. To drive it, enroll it first: ratchet.py --root {ctx.root} director-enroll")
    st = ctx.state()
    want = {"approve-plan": ["awaiting_plan_approval"],
            "human-approve": ["awaiting_checkpoint_review", "awaiting_final_review", "blocked"],
            "feedback": ["awaiting_checkpoint_review", "awaiting_final_review", "done"],
            "approve-changes": ["building", "blocked", "paused", "awaiting_checkpoint_review", "awaiting_final_review"],
            "ui-respec": ["building", "blocked"],
            "guardrail": ["building", "blocked"],
            "accept-finding": ["building", "blocked"],
            "accept-line": ["awaiting_final_review", "awaiting_checkpoint_review"],  # the finish pause (CP5)
            "cancel": ["planning", "awaiting_plan_approval", "building", "blocked", "paused",
                       "awaiting_checkpoint_review", "awaiting_final_review", "planning_feedback"],
            "set-review": ["planning", "awaiting_plan_approval", "building", "blocked", "paused",
                           "awaiting_checkpoint_review", "awaiting_final_review"],
            "hooks-waive": ["planning", "awaiting_plan_approval", "building", "blocked", "paused",
                            "awaiting_checkpoint_review", "awaiting_final_review"],
            "raise-limit": ["blocked"],
            "choice": ["planning", "awaiting_plan_approval", "building", "blocked", "paused",
                       "awaiting_checkpoint_review", "awaiting_final_review", "planning_feedback"]}[args.action]
    pause = None  # a lane that paused itself for the director: the apply works through the pause (in memory
    # until every check passed), in the phase it paused from, and the lane is parked again afterwards
    if apply and st["phase"] == "paused":
        pause = _lift_pause(st)
    shown = f"paused (from {st['phase']})" if pause else st["phase"]
    target = (getattr(args, "target", None) or "").strip()
    if action == "raise-limit" and target:
        g = ((st.get("checkpoints") or {}).get(target) or {}).get("gates", {}).get("adversarial") or {}
        if g.get("cap_raised_to"):  # its one raise is spent: said first, since a raised step is rarely still blocked
            die(f"{target}'s review-round limit was already raised once (to {g['cap_raised_to']} rounds); it is never "
                "raised a second time. Nothing was " + ("changed." if apply else "signed."))
    if st["phase"] not in want:
        if action == "raise-limit":
            die(f"Run {st['slug']} is in phase {shown}, not blocked; director-sign raise-limit only applies "
                "when the step is blocked at its review-round limit" + (" (after the lane ran `ask raise-limit CPn`)."
                                                                       if not apply else "."))
        if action == "approve-changes" and st["phase"] == "awaiting_plan_approval":
            die(f"Run {st['slug']} is awaiting plan approval: nothing is approved yet, so there is no baseline for "
                "approve-changes to move. Approve the plan first (director-sign approve-plan). Nothing was changed.")
        die(f"Run {st['slug']} is in phase {shown}; {action} applies to {want}." + (" Nothing was changed."
                                                                                        if apply else ""))
    reason = (getattr(args, "reason", None) or "").strip()
    ids = [i.strip() for i in (getattr(args, "ids", None) or "").split(",") if i.strip()]
    bind = ()
    if action == "guardrail":
        if not args.kind:
            die("director-sign guardrail needs --kind <kind> (from ratchet.py repeats)")
        action = f"guardrail:{norm_kind(args.kind)}"
    elif action == "raise-limit":
        # Signed only for the step the lane asked about, while it is blocked at its review-round limit and its one
        # raise is unspent: the same checks `ask raise-limit` and `raise-limit` make, so a token is never signed for
        # a step it could not raise. The step and the reason are bound into the token (_approval_payload), so the
        # lane applies exactly this raise, with exactly this reason, and nothing else.
        if not target or not reason:
            die("director-sign raise-limit needs the step and the reason: director-sign raise-limit CPn --reason \"...\""
                + (" --apply. Nothing was asked or changed." if apply else ""))
        p = st.get("pending") or {}
        if not apply and (p.get("action") != "raise-limit" or p.get("mode") != target):
            die(f"No raise-limit question is waiting for {target}: the lane runs `ask raise-limit {target}` first "
                "(it is refused there unless the step is blocked at its review-round limit), then the director signs; "
                f"or sign and apply in one step with --apply.")
        g = ((st.get("checkpoints") or {}).get(target) or {}).get("gates", {}).get("adversarial") or {}
        if g.get("cap_raised_to"):
            die(f"{target}'s review-round limit was already raised once (to {g['cap_raised_to']} rounds); it is never "
                "raised a second time. Nothing was " + ("changed." if apply else "signed."))
        if _adv_block_kind(st, target) not in ("own", "run_wide"):
            die(f"{target} is not blocked at its review-round limit right now; director-sign raise-limit only applies "
                "when it is. Nothing was " + ("changed." if apply else "signed."))
        bind = (target, reason)
    elif action == "accept-finding" and apply:
        # The same refusals `ask accept-finding` and `accept-finding` give, made before anything is asked or written:
        # a missing --reason, an unknown step, an id already accepted (so a repeated --apply records nothing twice).
        if not target or target not in (st.get("checkpoints") or {}):
            die(f"director-sign accept-finding needs the step: director-sign accept-finding CPn --ids F1,F2 --reason "
                "\"...\" --apply" + (f" ({target} is no checkpoint of this run)" if target else "")
                + ". Nothing was asked or changed.")
        if not ids:
            die(f"director-sign accept-finding needs the finding ids: director-sign accept-finding {target} --ids F1,F2 "
                "--reason \"...\" --apply. Nothing was asked or changed.")
        if not reason:
            die(f"director-sign accept-finding needs --reason \"...\" (there is no chat reply to read a reason from): "
                f"director-sign accept-finding {target} --ids {','.join(ids)} --reason \"...\" --apply. Nothing was "
                "asked or changed.")
        cps = st["checkpoints"][target]
        rnd = cps.get("adv_round")
        if rnd:
            deferred_by_key = {_finding_key(f): f for f in _round_deferred(cps, rnd["round"])}
            already = [i for i in ids if (deferred_by_key.get(i) or {}).get("accepted")]
            if already:
                die(f"{', '.join(already)} already accepted earlier for {target}; nothing new to do. Nothing was "
                    "changed.")
    elif action == "choice":
        # Signed only for a letter the waiting question offers; the letter is bound into the token.
        p = st.get("pending") or {}
        if p.get("action") != "choice":
            die("No lettered question is waiting: the lane runs `ask choice --options ...` first, then the director "
                "signs one of its letters with `director-sign choice <letter>" + (" --apply`" if apply else "`")
                + ". Nothing was " + ("changed." if apply else "signed."))
        letter = target.upper()
        opts = p.get("options") or []
        if letter not in opts:
            die(f"director-sign choice needs one of the offered letters ({', '.join(opts)}), got "
                f"{target or '(none)'}. Nothing was " + ("changed." if apply else "signed."))
        bind = (letter,)
        # What the letter does, from the recorded question itself (not the lane's prose), on stderr so stdout
        # stays the bare token: the director never signs blind.
        files = (p.get("locked") or {}).get(letter) or []
        kind = (p.get("guardrail") or {}).get(letter)
        does = []
        if files:
            does.append(f"approves changing the locked file(s) {', '.join(files)} (approve-changes then needs no "
                        "further signature)")
        if kind:
            does.append(f"adds a guardrail step for '{kind}' right after the current step (it may add a tool)")
        if st["phase"] == "blocked":
            does.append("is the pick at a blocked run; resuming it still needs director-sign human-approve")
        print(f"Signing option {letter} of {', '.join(opts)}: it " + ("; ".join(does) if does else
              "unlocks nothing (it only records the letter)") + ".", file=sys.stderr)
    rule = _policy_rule_for(ctx, st, action, target, ids) if action in DIRECTOR_APPLY_ACTIONS else None
    if not apply:
        print(_sign(_director_key(), _approval_payload(ctx, st, action, bind)))
        return
    key = _director_key()  # before anything is asked: a missing key refuses with nothing changed
    if action == "approve-changes":
        errs = validate_plan(ctx.plan())  # as approve-changes itself checks first: a malformed plan is named, not asked
        if errs:
            die("Plan invalid:\n  - " + "\n  - ".join(errs))
        if not integrity_problems(ctx, st):
            ok("Nothing has changed since approval; there is nothing to approve.")
            return
    if pause and action == "choice":  # no ask step to save it: the lane is unparked here for the apply (parked
        ctx.save_state(st)  # again below); for the other three the ask saves the unparked run once its own checks pass
    try:
        if action != "choice":  # a lettered question is the lane's own `ask choice`; the other three are asked here
            _director_apply_ask(ctx, st, action, target, ",".join(ids))
            st = ctx.state()  # the ask moved awaiting_since: the token is signed for the pause as it now stands
        token = _sign(key, _approval_payload(ctx, st, action, bind))
        ns = argparse.Namespace(director_token=token, cp=target, reason=reason, letter=target.upper() or None,
                                 policy_rule=rule, policy_checked=True)
        {"approve-changes": cmd_approve_changes, "accept-finding": cmd_accept_finding, "raise-limit": cmd_raise_limit,
         "choice": cmd_choice}[action](ns)
    finally:
        if pause:  # parked again, whatever the apply did (its unblock, if any, is what `resume` now returns to)
            st = ctx.state()
            if st["phase"] != "paused":
                _enter_pause(st, pause["reason"])
                ctx.save_state(st)


def cmd_approve_plan(args):
    ctx = Ctx(find_root())
    st = ctx.state()
    if st["phase"] != "awaiting_plan_approval":
        die(f"Nothing to approve (phase {st['phase']})"
            + (". This lane is enrolled with the director, so its plan is approved only with a director token, "
               "never by a chat reply." if approval_mode(ctx) == "director" else ""))
    plan = ctx.plan()
    if _plan_hash(plan, ctx) != st["plan_hash"]:
        die("checkpoints.json changed since it was shown to the human. Run plan-submit again and re-review.")
    missing = [c["id"] for c in plan["checkpoints"] if c["gates"].get("behavior") and not test_plan(ctx, c["id"])]
    if missing:
        die(f"Test plans missing for {', '.join(missing)}. Spawn ratchet-test-planner first.")
    msg = _require_human(ctx, st, "approve-plan", getattr(args, "director_token", None))
    if (st.get("pending") or {}).get("action") == "approve-plan":
        st.pop("pending", None)  # answered
    _stamp_legacy_round_baselines(st, plan)
    st["approved"] = approval_snapshot(ctx, st)  # the owner chat is unchanged: only `resume --claim` moves a run
    links = _done_means_links(ctx, plan)
    if not links or any(links.values()):
        # written once, here: this plan is under the done-means rules. A plan with done-means lines that no case
        # anywhere links could not have passed plan-submit under those rules (it was submitted before they
        # existed), so it is approved as an older plan: no marker, the plain notes, no finish block (CP4 round 2).
        st["approved"]["done_means_rules"] = DM_RULES_VERSION
    st["phase"] = "building"
    st["current"] = plan["checkpoints"][0]["id"]
    first = st["checkpoints"][st["current"]]
    first["status"] = "in_progress"
    first["started_at"] = now()
    first["base_tree"] = fingerprint(ctx.root)["id"]
    first["base_head"] = _head_sha(ctx.root)  # the commit `merged` counts the lane's own commits from
    # where the run started, written once and never rewritten (`merged` moves the step's base_tree/base_head, not
    # this): the shortcut tables compare the current code with it (`_sc_old_version`)
    st.setdefault("run_start", {"tree": first["base_tree"], "head": first["base_head"]})
    st["awaiting_since"] = None
    ctx.log(st, "plan_approved", by=msg["by"], note=msg.get("prompt", "")[:200])
    ctx.save_state(st)
    build_viewer(ctx)
    ok(f"Plan approved. Building {st['current']}.")
    print(json.dumps(next_action(ctx, st), indent=2))


def _cur(ctx, st, cp_id):
    if st["phase"] != "building":
        die(f"Not building (phase {st['phase']})")
    if cp_id != st["current"]:
        die(f"{cp_id} is not the current checkpoint ({st['current']}). Checkpoints run strictly in order.")
    verify_integrity(ctx, st)
    return st["checkpoints"][cp_id]


def _expect_step(cps, allowed, cp_id):
    if cps["step"] not in allowed:
        die(f"{cp_id} is at step '{cps['step']}', expected one of {allowed}. Run ratchet.py next.")


def _planned_cases(ctx, cp_id):
    tp = test_plan(ctx, cp_id) or {}
    return [c for c in tp.get("cases", []) if c.get("layer", "code") not in ("browser", "shortcuts")]


def _coverage(ctx, cp):
    """Every planned (non-browser) case ID must appear in at least one test file (in a non-Python file, the id in
    any usual spelling on a test's opening line, such as Go's TestCP1_T01, counts too)."""
    files = (cp.get("tests") or {}).get("files") or []
    texts = [(p, p.read_text(errors="ignore")) for p in _test_paths(ctx, cp)]
    blob = "".join(t for _, t in texts)
    missing = [c["id"] for c in _planned_cases(ctx, cp["id"])
               if not re.search(r"(?<![A-Za-z0-9-])" + re.escape(c["id"]) + r"(?![0-9])", blob)
               and not _declared(texts, c["id"])]
    return files, missing, bool(blob)


def _declared(texts, cid) -> bool:
    """True when a non-Python test file has `cid` on a line that opens a test (see _test_decls)."""
    return any(_test_decls(t.splitlines(), _case_id_re(cid)) for p, t in texts if p.suffix != ".py")


def _undeclared(ctx, cp) -> str | None:
    """Why a planned test can't be told apart by name: a planned case id that, outside Python files, appears only in
    comments, so no test's opening line holds it (None when every id is placed)."""
    texts = [(p, p.read_text(errors="ignore")) for p in _test_paths(ctx, cp)]
    py = "".join(t for p, t in texts if p.suffix == ".py")
    bad = [c["id"] for c in _planned_cases(ctx, cp["id"])
           if not re.search(r"(?<![A-Za-z0-9-])" + re.escape(c["id"]) + r"(?![0-9])", py)
           and not _declared(texts, c["id"])]
    if not bad:
        return None
    cid = bad[0]
    return (f"Planned case {', '.join(bad)} appears in the test files only inside a comment (in a test's body or "
            f"above it). Outside Python, a planned case id must be on the line that opens its test: in the test's "
            f"name, such as it('[{cid}] ...', () => {{ or func Test{cid.replace('-', '_')}(t *testing.T) {{, or on "
            f"an annotation directly above it, such as @DisplayName(\"[{cid}] ...\"), so the test's own result "
            f"carries it. Have ratchet-test-writer move the id into the test's name.")


def cmd_tests_written(args):
    ctx = Ctx(find_root())
    st = ctx.state()
    cps = _cur(ctx, st, args.cp)
    _expect_step(cps, ["tests", "red"], args.cp)
    held = _merge_unaccepted(ctx, st)
    if held:
        die(held)
    cp = cp_by_id(ctx.plan(), args.cp)
    if not cp["gates"].get("behavior"):
        cps["step"] = "implement"
        ctx.save_state(st)
        ok(f"{args.cp}: behavior gate off ({cp.get('behavior_skip_reason')}); go implement.")
        return
    gr = cp.get("guardrail") or {}
    if gr.get("high_risk") and not gr.get("strengthen"):
        vd = ctx.root / (gr.get("variants_dir") or "")
        nb = len([p for p in (vd / "bad").rglob("*") if p.is_file()]) if (vd / "bad").is_dir() else 0
        ng = len([p for p in (vd / "good").rglob("*") if p.is_file()]) if (vd / "good").is_dir() else 0
        if nb < 3 or ng < 2:
            die(f"{args.cp} guards a high-risk kind of mistake: first spawn ratchet-variant-writer (it gets only the "
                f"kind, the why and `ratchet.py occurrences {gr['kind']}`, never the check) to write at least 3 "
                f"disguised bad variants in {gr.get('variants_dir')}/bad and 2 look-alike good examples in "
                f"{gr.get('variants_dir')}/good (found {nb} and {ng}).")
    files, missing, found = _coverage(ctx, cp)
    if not found:
        die(f"No test files found at {files}. Tests must be written to tests.files.")
    if missing:
        die(f"Planned cases not present in the test files: {', '.join(missing)}. "
            f"Each test must include its case ID (e.g. '[{args.cp}-T01] ...').")
    why = _undeclared(ctx, cp)
    if why:
        die(why)
    cps["step"] = "red"
    ctx.log(st, "tests_written", cp=args.cp, files=files)
    ctx.save_state(st)
    ok(f"{args.cp}: all {len(_planned_cases(ctx, args.cp))} planned cases are present. Next: ratchet.py red {args.cp}")


RUN_POLL_SECONDS = 0.25  # how often a running test command's deadline is recomputed from the machine load


def _read_load():
    """(one-minute load average, CPU count) right now, or None when there is no usable reading. The environment
    variables RATCHET_FAKE_LOADAVG ("unavailable", a number, or "@file" holding a number) and RATCHET_FAKE_CPUS
    replace the real values (the tests use them; tests/run_all.py reads the same two). Never raises."""
    fake = os.environ.get("RATCHET_FAKE_LOADAVG")
    try:
        if fake is not None:
            fake = fake.strip()
            if fake.startswith("@"):
                with open(fake[1:], "r", encoding="utf-8") as f:
                    fake = f.read().strip()
            load = float(fake)
        else:
            load = os.getloadavg()[0]
        cpus = int(os.environ.get("RATCHET_FAKE_CPUS") or 0) or (os.cpu_count() or 1)
    except (OSError, ValueError, AttributeError):
        return None
    if not (load == load and load < float("inf")) or load < 0 or cpus < 1:
        return None
    return load, cpus


def _stretch_factor(max_stretch: float):
    """(factor, load, cpus): how many times longer than test_timeout_sec a command may run right now. The factor is
    load / cpus, at least 1 and at most max_stretch; 1 when there is no usable reading."""
    reading = _read_load()
    if reading is None:
        return 1.0, None, None
    load, cpus = reading
    return min(max(1.0, load / cpus), max_stretch), load, cpus


def _load_stretch_max(cfg) -> float:
    """The configured ceiling on the stretch (load_stretch_max), a number of 1 or more; the default otherwise."""
    try:
        v = float(cfg.get("load_stretch_max"))
    except (TypeError, ValueError):
        return float(DEFAULT_CONFIG["load_stretch_max"])
    return v if 1.0 <= v < float("inf") else float(DEFAULT_CONFIG["load_stretch_max"])


def _suite_watch_seconds(cfg) -> float | None:
    """How often a running command's code is compared with the tree it started on (suite_watch_seconds): a number
    above 0, or None when the configured value is not one (then the default applies)."""
    v = cfg.get("suite_watch_seconds")
    if isinstance(v, bool) or not isinstance(v, (int, float)) or v != v or not (0 < v < float("inf")):
        return None
    return float(v)


def _watch_every(cfg) -> float:
    """The interval a _Watch uses: the configured suite_watch_seconds, or the default when it is not a usable one."""
    v = _suite_watch_seconds(cfg)
    return float(DEFAULT_CONFIG["suite_watch_seconds"]) if v is None else v


class _Watch:
    """The code-under-the-run watch for one command: the tree (`fp`) it started on, how often to look (`every`
    seconds), and the command the agent should run again if the code changes. `changed()` is the one check: a
    fingerprint, and only when its id differs, the list of files the run started with that were edited or deleted
    meanwhile, plus the new project source files that appeared (_new_source: any added file git would commit counts
    as new source unless a fixed generated list (build, cache, test-report, snapshot and scratch folders and file
    names) or the doc list names it; there is no extension allow-list, and a plain `report` or `reports` folder is
    not treated as generated). Ratchet's own folder and the agent's chat transcript never
    count, and neither does any other file that only appeared: suites write snapshots and reports of their own,
    and those are left to the command's own 'changed files' check. A periodic
    look (`final=False`) builds its tree in one private index kept across looks, so git rehashes only the files
    whose stat changed since the last look, and a look git cannot take (a file the command created and removed
    under git's walk, one it cannot read, a failed diff-tree) is skipped and noted in `skipped`, never fatal with
    the command still running; the last look (`final=True`, the command has ended) is the full fingerprint() and
    a git failure there dies as it does everywhere else. `found_at_end` says whether the change was found by that
    last look (the command ended on its own) rather than by a periodic one (the command was stopped)."""

    def __init__(self, ctx, fp: dict, every: float, again: str, extra: list | None = None):
        self.ctx, self.fp, self.every, self.again = ctx, fp, every, again
        self.extra = list(extra or [])   # the config's fingerprint_include, so a look's tree is fingerprint()'s
        self.skipped: list = []      # one reason per look that could not be taken (noted in the command's log)
        self.found_at_end = False
        self.added: list = []        # the changed files that are new source (not in the tree the run started on)
        self._index = None           # the private index for periodic looks (git projects only), seeded on first use

    def _look_fp(self) -> dict:
        """A periodic look's fingerprint: the same tree id fingerprint() gives, from the kept index."""
        root = self.ctx.root
        if not _is_git(root):
            return fingerprint(root)
        if self._index is None:
            self._index = tempfile.TemporaryDirectory()
            env = dict(os.environ, GIT_INDEX_FILE=str(Path(self._index.name) / "index"))
            subprocess.run(["git", "read-tree", "HEAD"], cwd=root, env=env, capture_output=True)
        env = dict(os.environ, GIT_INDEX_FILE=str(Path(self._index.name) / "index"))
        return {"kind": "git-tree", "id": _git_tree_id(root, env, strict=False, extra=self.extra)}

    def changed(self, final: bool = False) -> list:
        try:
            now_fp = fingerprint(self.ctx.root) if final else self._look_fp()
            if now_fp["id"] == self.fp["id"]:
                return []
            added = []
            files = _edited_or_deleted(self.ctx.root, self.fp, now_fp, added)
            self.added = added
        except _LookFailed as e:
            if final:  # the tree differs, so this is a change; what changed could not be listed: say so, never pass
                return [f"(the files could not be listed: {e})"]
            self.skipped.append(str(e))
            return []
        chat = _chat_transcript_paths(self.ctx, None)
        return [f for f in files if f != RATCHET_DIR and not f.startswith(RATCHET_DIR + "/") and f not in chat]


# A new file counts as a code change under a running suite when git would commit it and it is neither generated
# output nor a doc: no folder on its path that holds generated output (FINGERPRINT_EXCLUDES, _WATCH_GENERATED_DIRS,
# .NET's bin/<configuration>/, any dot folder), not a generated name, not a doc. There is no source-extension
# allow-list: a template, a stylesheet, a config file or a module in a folder called reports/ is project code.
_WATCH_GENERATED_DIRS = {
    "__snapshots__", "__generated__", "generated", "htmlcov", "lib-cov", "test-results", "test-reports", "junit",
    "logs", "log", "tmp", "temp", "scratch", "artifacts", "obj", "vendor", "bower_components", "jspm_packages",
}
# `bin` holds source in many projects (Rust's src/bin/, a package's bin/ scripts): it is build output only as .NET's
# bin/<configuration>/
_WATCH_BUILD_CONFIGS = {"debug", "release"}
_WATCH_GENERATED_NAMES = ("*.min.*", "*.map", "*.bundle.*", "*.pyc", "*.pyo", ".#*", "*~", "*.log", "*.lcov",
                          "coverage*", ".coverage*", "junit*.xml", "*results*.xml", "*.orig", "*.rej", "*.swp",
                          "*.tmp", "*.bak")
_WATCH_DOC_NAMES = (*DEFAULT_CONFIG["doc_globs"], "*.txt")  # a doc that appears is not a code change


def _new_source(path: str) -> bool:
    """Whether a file that appeared under a running suite is a new project source file (a change that stops the
    run) rather than generated build, cache, report, snapshot or scratch output, or a doc (never a change). Any
    file git would commit counts unless one of those fixed exclusions names it; there is no extension allow-list."""
    parts = path.split("/")
    name = parts[-1]
    if any(d in FINGERPRINT_EXCLUDES or d in _WATCH_GENERATED_DIRS or d.startswith(".") for d in parts[:-1]):
        return False
    if any(d == "bin" and nxt.lower() in _WATCH_BUILD_CONFIGS for d, nxt in zip(parts[:-2], parts[1:-1])):
        return False
    if any(fnmatch.fnmatch(name, g) for g in _WATCH_GENERATED_NAMES):
        return False
    return not any(fnmatch.fnmatch(name, g) for g in _WATCH_DOC_NAMES)


def _edited_or_deleted(root: Path, fp_a: dict, fp_b: dict, added: list | None = None) -> list:
    """The files in fp_a's tree that fp_b's tree changed or lacks, plus the files fp_b added that are new project
    source (_new_source; any other added file is left out), named relative to `root` (diff-tree's `--relative`:
    a project below the repository's top gets project-relative names, the way `.ratchet/` and the chat
    transcript paths are named). The new source files are also put in `added` when it is given. For two git
    trees a failed diff-tree raises _LookFailed: the trees are known to differ, so the answer is never 'nothing'; only two manifests are compared as manifests, and a manifest that is
    missing or damaged raises _LookFailed the same way (read through _read_record)."""
    if fp_a["kind"] == fp_b["kind"] == "git-tree":
        r = subprocess.run(["git", "diff-tree", "-r", "-z", "--no-renames", "--name-status",
                            "--relative", fp_a["id"], fp_b["id"]], cwd=root, capture_output=True)
        if r.returncode != 0:
            raise _LookFailed(f"git diff-tree failed: {r.stderr.decode('utf-8', 'replace').strip()}")
        parts = r.stdout.decode("utf-8", "surrogateescape").split("\0")
        pairs = [(parts[i], parts[i + 1]) for i in range(0, len(parts) - 1, 2) if parts[i]]
        if added is not None:
            added.extend(f for st, f in pairs if st == "A" and _new_source(f))
        return [f for st, f in pairs if st != "A" or _new_source(f)]
    mdir = root / RATCHET_DIR / "manifests"
    sides = []
    for fp in (fp_a, fp_b):  # a manifest that is missing or damaged cannot say 'nothing changed': a failed look
        data, why = _read_record(mdir / f"{fp['id']}.json", missing=None)
        if data is None:
            raise _LookFailed(f"fingerprint manifest {fp['id']} cannot be read ({why or 'missing'})")
        sides.append(data)
    a, b = sides
    new = [k for k in b if k not in a and _new_source(k)]
    if added is not None:
        added.extend(new)
    return sorted([k for k in a if b.get(k) != a[k]] + new)


def _signal_group(proc, sig) -> None:
    """Send `sig` to a command's whole process group (the command alone where there are no groups). Never raises."""
    try:
        if hasattr(os, "killpg"):
            os.killpg(proc.pid, sig)
        else:
            proc.send_signal(sig)
    except (ProcessLookupError, PermissionError, OSError):
        pass


def _group_alive(proc) -> bool:
    """Whether any process of the command's group is still there (the leader is reaped first, so an exited shell
    leader no longer counts; its children do until they are gone)."""
    if proc.poll() is None:
        return True
    if not hasattr(os, "killpg"):
        return False
    try:
        os.killpg(proc.pid, 0)
        return True
    except ProcessLookupError:
        return False
    except (PermissionError, OSError):
        return True


def _stop_group(proc, grace: float = 2.0) -> None:
    """Stop a command and everything it started, politely first: SIGTERM to its process group (a runner that
    manages helpers of its own, like tests/run_all.py, gets to stop them), then, once the whole group is gone or
    `grace` seconds have passed (the group, not only its leader: under `sh -c` the shell leader dies at once while
    the runner is still cleaning up), SIGKILL to whatever ignored it (_kill_group). Never raises."""
    _signal_group(proc, signal.SIGTERM)
    end = time.monotonic() + grace
    while time.monotonic() < end and _group_alive(proc):
        time.sleep(0.05)
    _kill_group(proc)


def _secs(x: float) -> str:
    """A number of seconds for a log line: whole when it is whole (`2s`), else one decimal (`2.5s`)."""
    return str(int(x)) if float(x) == int(x) else f"{x:.1f}"


def _kill_group(proc) -> None:
    """Stop a command and everything it started (its own process group), then reap it. Never raises."""
    _signal_group(proc, signal.SIGKILL)
    try:
        proc.wait(timeout=10)
    except subprocess.TimeoutExpired:
        pass


_STOP_SIGNALS = tuple(s for s in ("SIGTERM", "SIGINT", "SIGHUP") if hasattr(signal, s))


def _forward_stop(proc) -> list:
    """While `proc` runs, a SIGTERM, SIGINT or SIGHUP sent to ratchet.py (an agent's tool timeout cutting a
    foreground call off) first stops the command's whole process group, then takes its usual course (the previous
    handler, or the default exit), so no suite is left running behind a stopped ratchet.py. A signal the process
    ignores stays ignored. Returns the previous handlers for _restore_handlers; [] when handlers cannot be set
    (not the main thread)."""
    saved = []

    def on_stop(signum, frame):
        _kill_group(proc)
        _restore_handlers(saved)
        os.kill(os.getpid(), signum)

    for name in _STOP_SIGNALS:
        sig = getattr(signal, name)
        try:
            prev = signal.getsignal(sig)
            if prev == signal.SIG_IGN:
                continue
            signal.signal(sig, on_stop)
        except (ValueError, OSError):
            continue
        saved.append((sig, prev))
    return saved


def _restore_handlers(saved: list) -> None:
    for sig, prev in saved:
        try:
            signal.signal(sig, prev if prev is not None else signal.SIG_DFL)
        except (ValueError, OSError, TypeError):
            pass


def _wait_stretched(proc, timeout: float, max_stretch: float, watch: "_Watch | None" = None):
    """Wait for a command, polling. The deadline is `timeout` times the highest stretch factor read while the
    command runs (re-read every RUN_POLL_SECONDS, so a load spike while the command runs still extends it; a load
    drop never shortens a limit already granted), never earlier than `timeout` and never later than `timeout` times
    `max_stretch`. Stops the whole process group when the deadline passes. With a `watch`, every `watch.every`
    seconds the code is compared with the tree the command started on, and once more when the command ends on its
    own, so a quick command that finishes before the next look still never counts (a command killed by the time
    limit gets no last look: it is a timeout even when the tree also changed); a change
    stops the command and everything it started (_stop_group; on the last look too, so a helper the ended
    command left in its group never outlives the run), and `watch.found_at_end` says which look found it.
    A periodic look git cannot take is skipped (noted on the watch), never fatal; the last look is the full
    fingerprint and may die, which the caller (_run_cmd) turns into a kill of the group first. Returns
    (timed_out, limit, note, changed): the
    limit in force when the command ended, a line saying the limit was stretched (the highest reading taken during
    the run, or a fresh one when the command ended within one poll of passing `timeout`), or "" when the command
    ran within the configured limit, and the files the watch found edited or deleted ([] when none, or no watch)."""
    t0 = time.monotonic()
    peak = None  # the reading that set the highest limit so far: the limit in force never shrinks
    timed_out = False
    limit = float(timeout)
    next_look = t0 + watch.every if watch else None
    changed = []
    while True:
        factor, load, cpus = _stretch_factor(max_stretch)
        if timeout * factor > limit:
            limit = timeout * factor
            peak = (factor, load, cpus)
        elapsed = time.monotonic() - t0
        if elapsed >= limit:
            timed_out = True
            _kill_group(proc)
            break
        if watch and time.monotonic() >= next_look:
            changed = watch.changed()
            if changed:
                watch.found_at_end = False
                _stop_group(proc)
                break
            next_look = time.monotonic() + watch.every
        try:
            proc.wait(timeout=min(RUN_POLL_SECONDS, limit - elapsed))
            break
        except subprocess.TimeoutExpired:
            continue
    if watch and not changed and not timed_out:  # a kill by the time limit wins: a timeout, counted as one
        changed = watch.changed(final=True)  # the last look: the tree the command ended on
        watch.found_at_end = bool(changed)
        if changed:  # the leader has ended, but a helper it left in its group belongs to a run that no longer counts
            _stop_group(proc)
    ran_past = timed_out or time.monotonic() - t0 >= timeout
    if ran_past and not timed_out:
        fresh = _stretch_factor(max_stretch)  # ended within one poll of passing the configured limit
        if timeout * fresh[0] > limit:
            limit = timeout * fresh[0]
            peak = fresh
    if peak is None or not ran_past:
        return timed_out, (limit if timed_out else float(timeout)), "", changed
    factor, load, cpus = peak
    note = (f"time limit stretched {factor:.1f}x ({_secs(timeout)}s to {_secs(limit)}s) at load {load:.1f} "
            f"on {cpus} CPUs")
    return timed_out, limit, note, changed


# Vars that pin a subprocess to THIS run/session, not for a child test/regression/check command to inherit:
# RATCHET_ROOT redirects a child's own `ratchet.py` calls at the current run's worktree instead of its own
# project (the root cause of test_hooks/test_install/test_lanes_start_extra/test_shortcuts_extra failing when
# RATCHET_ROOT is exported in the launching shell); RATCHET_ROLE, RATCHET_HOME, RATCHET_HUMAN_OVERRIDE and
# RATCHET_DIRECTOR_KEY_FILE are the same names RESERVED_ENV (below) already treats as director/human-session-only,
# which a spawned command must never see either. RATCHET_RUN_ALL/RATCHET_RUN_ALL_SUITES/RATCHET_RUN_ALL_TAG are
# deliberately NOT here: tests/run_all.py sets those for its own children, and _run_cmd stripping them would be
# pointless (run_all re-sets them) and could disturb run_all's own dedupe logic.
_RUN_CMD_LEAK_VARS = ("RATCHET_ROOT", "RATCHET_ROLE", "RATCHET_HOME", "RATCHET_HUMAN_OVERRIDE",
                      "RATCHET_DIRECTOR_KEY_FILE")


def _run_cmd(ctx, command, log_path, timeout, report: Path | None = None, watch: "_Watch | None" = None):
    """Run a test or check command in its own process group and wait for it with _wait_stretched: on a busy machine
    its time limit is `timeout` (test_timeout_sec) times the load average over the CPU count, re-read while it runs
    (the highest reading wins: a load drop never shortens the limit), never below `timeout` and at most
    `load_stretch_max` times it; a command still running at that limit is stopped with its whole process group and
    logged as `TIMEOUT after <limit>s` (exit 124). When the limit was stretched the log header gets one line saying
    so, with the factor, both limits, the load and the CPU count. A SIGTERM, SIGINT or SIGHUP to ratchet.py while
    the command runs stops the command's process group first (_forward_stop). With `report`, the
    command gets that path in RATCHET_TEST_REPORT, and any file already there is deleted first, so a report left by
    an earlier run can never count for this one. With a `watch` (a _Watch: the tree the step's work started on and
    suite_watch_seconds), an edit to the code while the command runs stops it with everything it started, writes
    the log as `stopped: code changed` and dies through the normal path (the state lock is released, nothing is
    saved: no attempt, no gate status, no flaky allowance changes), telling the agent to run `watch.again`. Each
    such stop is recorded in `stopped-runs.json` next to the log, keyed by the command, and cleared when the same
    command next ends unstopped: when the previous call of this command was stopped on the same files, the message
    adds that the command itself may be the writer, with the restore guidance. A change found only by the last look
    (the command ended on its own, so the writer cannot be told: the command itself, or an edit while it ran) is
    not a stop but a refusal naming both causes (log header `# code changed under the run, found when it ended`),
    with the restore guidance (_restore_guidance: every named file is restored from the run's starting tree, a
    file the run started with is never deleted, and a new source file is kept if the agent added it), equally
    uncounted. A command killed by its time limit is reported as a timeout even when the tree also changed: the
    time-limit kill wins over the last look, so it gets the `TIMEOUT after <limit>s` log and is counted exactly
    like any other timeout.
    Anything that escapes the wait (a git failure on the last look, a signal) kills the command's group first.
    Output goes through temp files, so a command that prints a lot never stalls on a full pipe."""
    env = dict(os.environ, CI="1", FORCE_COLOR="0")
    for k in _RUN_CMD_LEAK_VARS:
        env.pop(k, None)
    env.pop("RATCHET_TEST_REPORT", None)
    if report is not None:
        try:
            report.unlink()
        except FileNotFoundError:
            pass
        except OSError as e:
            die(f"Could not delete the old test report at {report.relative_to(ctx.root)} ({e}); remove it and re-run.")
        env["RATCHET_TEST_REPORT"] = str(report)
    max_stretch = _load_stretch_max(ctx.config())
    if watch:  # one watch serves every command of a call: the per-command parts start clean
        watch.skipped = []
        watch.found_at_end = False
    t0 = _dt.datetime.now()
    with tempfile.TemporaryFile() as so, tempfile.TemporaryFile() as se:
        proc = subprocess.Popen(command, shell=True, cwd=ctx.root, stdout=so, stderr=se, env=env,
                                start_new_session=True)
        saved = _forward_stop(proc)
        try:
            timed_out, limit, note, changed = _wait_stretched(proc, float(timeout), max_stretch, watch)
        except BaseException:
            _kill_group(proc)  # whatever escapes the wait, the command never outlives ratchet.py
            raise
        finally:
            _restore_handlers(saved)
        so.seek(0)
        se.seek(0)
        stdout = so.read().decode("utf-8", errors="replace")
        stderr = se.read().decode("utf-8", errors="replace")
    skipped = ""
    if watch and watch.skipped:
        skipped = (f"# {len(watch.skipped)} look(s) at the code could not be taken and were skipped "
                   f"(last reason: {watch.skipped[-1]})\n")
    log_path.parent.mkdir(parents=True, exist_ok=True)
    dur = (_dt.datetime.now() - t0).total_seconds()
    if changed:
        names = ", ".join(changed[:5]) + (f" and {len(changed) - 5} more" if len(changed) > 5 else "")
        guidance = _restore_guidance(ctx.root, changed, watch.fp.get("id") if watch.fp.get("kind") == "git-tree" else None,
                                     added=watch.added)
        if watch.found_at_end:
            # the command ended on its own and the tree it ended on is not the one it started on: the writer cannot
            # be told (the command itself, or an edit while it ran), so name both and refuse; never a stop, never
            # a pass, never a counted failure
            log_path.write_text(f"$ {command}\n# exit={proc.returncode} duration={dur:.1f}s at {now()}\n"
                                f"# code changed under the run, found when it ended ({names})\n{skipped}\n"
                                f"{stdout}{stderr}")
            die(f"The code changed while this command ran, found only when it ended ({names}): either the "
                "command itself wrote these files (a regenerated snapshot, a tracked report, a formatter), or they "
                "were edited while it ran. Either way its result cannot count, and nothing was recorded: no "
                f"attempt, no gate status and no flaky re-run allowance changed. {guidance} Put the files right "
                f"first (a file left changed is a code change at the next command), then run `ratchet.py "
                f"{watch.again}` again. Log: {log_path.relative_to(ctx.root)}", 2)
        record = log_path.parent / "stopped-runs.json"
        stops = read_json(record, {}, record="Ratchet treats it as holding no earlier stop") or {}
        prev = stops.get(command) if isinstance(stops, dict) else None
        same = bool(prev) and sorted(prev.get("files") or []) == sorted(changed)
        stops = stops if isinstance(stops, dict) else {}
        stops[command] = {"files": changed, "again": watch.again, "at": now()}
        write_json(record, stops)
        hint = ""
        if same:
            hint = (" This is the second run in a row stopped on the same file(s): if you did not edit them, the "
                    "command itself rewrites them, and a test or check command must not change the files it started "
                    f"with. {guidance}")
        log_path.write_text(f"$ {command}\n# stopped: code changed under the run ({names}) duration={dur:.1f}s "
                            f"at {now()}\n{skipped}\n{stdout}{stderr}")
        die(f"Stopped: the code changed while this command was running ({names}), so its result cannot "
            "count. Nothing was recorded: no attempt, no gate status and no flaky re-run allowance changed. "
            f"Run `ratchet.py {watch.again}` again when the edit is finished.{hint} "
            f"Log: {log_path.relative_to(ctx.root)}", 2)
    if watch:
        record = log_path.parent / "stopped-runs.json"
        stops = read_json(record, {}, record="Ratchet treats it as holding no earlier stop") or {}
        if isinstance(stops, dict) and command in stops:  # this command ended unstopped: its stop record is spent
            del stops[command]
            write_json(record, stops)
    if timed_out:
        code, out = 124, f"TIMEOUT after {_secs(limit)}s\n{stdout}{stderr}"
    else:
        code, out = proc.returncode, stdout + "\n" + stderr
    header = f"$ {command}\n# exit={code} duration={dur:.1f}s at {now()}\n"
    if note:
        header += f"# {note}\n"
    log_path.write_text(f"{header}{skipped}\n{out}")
    return code, out, dur


def _restore_guidance(root: Path, files: list, tree: str | None, added: list | None = None) -> str:
    """What to do about files a watched command's tree lost, changed or gained, never at the cost of the agent's
    own work. A new source file (`added`: not in the tree the run started on) is kept if the agent added it, and
    removed or ignored if the command wrote it (_added_guidance). Every other named file was in the tree the run started on (`tree`, the git tree id `fingerprint()` wrote: the step's
    uncommitted work included, files untracked at HEAD included, never HEAD or the index), so the advice is the
    same for all of them: an edit the agent made is kept (run again); a file the command wrote is put back from
    that tree, and the command is fixed or the file taken out of the fingerprint (.gitignore, `git rm --cached`
    first when git tracks it). Nothing is ever told to be deleted. The `(the files could not be listed: ...)`
    marker gets no per-file advice."""
    new = [f for f in files if f in (added or [])]
    named = [f for f in files if not f.startswith("(") and f not in new]
    if new:
        tail = _added_guidance(new)
        return f"{_restore_guidance(root, named, tree)} {tail}" if named else tail
    if not named:
        return "Find out what wrote them, and restore the files before running again."
    if not _is_git(root):
        return ("Restore the files before running again; if the command wrote them, fix it so a test or check "
                "command never changes the files it started with.")
    q = " ".join(shlex.quote(f) for f in named)
    back = (f"git checkout {tree} -- {q}; that tree is the code the run started on, your uncommitted work and "
            "files untracked at HEAD included, not HEAD" if tree else "from the code the run started on, not from HEAD")
    return (f"{', '.join(named)} differ from when the run began. If you edited them, keep your edit and run again. "
            f"If the command wrote them, put them back as they were when the run began ({back}), then stop the "
            f"command writing into the tree, or take them out of the fingerprint: add them to .gitignore (and "
            f"git rm --cached {q} first if git tracks them). Never delete a file the run started with.")


def _added_guidance(files: list) -> str:
    """What to do about new source files that appeared while a watched command ran: they were not there when it
    began, so an edit is kept and a file the command wrote is taken out again (removed, or ignored)."""
    q = " ".join(shlex.quote(f) for f in files)
    return (f"{', '.join(files)} did not exist when the run began. If you added them, keep them and run again. If "
            f"the command wrote them, remove them (rm {q}) or add them to .gitignore, and stop the command writing "
            "source files into the project.")


def _report_path(ctx, cp):
    """Where the test command must write its per-test results, or None when the approved plan has none for this
    step (tests.report "none", or a plan from before reports existed): then the exit code alone decides."""
    fmt = (cp.get("tests") or {}).get("report")
    if fmt not in ("junit", "json"):
        return None
    return ctx.evidence(cp["id"]) / ("test-report.xml" if fmt == "junit" else "test-report.json")


def _read_test_report(ctx, path: Path):
    """The per-test results in a JUnit XML or Ratchet JSON report (told apart by content): ([(name, status)], None),
    or (None, why). status is passed, failed (a check failed), error (a crash) or skipped. Never raises."""
    rel = path.relative_to(ctx.root)
    try:
        raw = path.read_bytes()
    except FileNotFoundError:
        return None, f"no test report was written at {rel}"
    except Exception as e:
        return None, f"the test report at {rel} could not be read ({type(e).__name__}: {e})"
    if raw.startswith(b"\xef\xbb\xbf"):  # a UTF-8 byte-order mark, as some .NET loggers write
        raw = raw[3:]
    try:
        if raw.lstrip().startswith(b"<"):
            import xml.etree.ElementTree as ET
            out = []
            for tc in ET.fromstring(raw).iter("testcase"):
                kids = {k.tag for k in tc}
                status = ("error" if "error" in kids else "failed" if "failure" in kids
                          else "skipped" if "skipped" in kids else "passed")
                props = [pr.get("value") or "" for pr in tc.iter("property")]
                out.append((" ".join([tc.get("classname") or "", tc.get("name") or ""] + props).strip(), status))
            return out, None
        data, why = _read_record(path, kind=dict)  # the one JSON reader; it never raises
        cases = data.get("cases") if why is None else None
        if isinstance(cases, list) and all(isinstance(c, dict) and isinstance(c.get("id"), str) and c.get("status")
                                           in ("passed", "failed", "error", "skipped") for c in cases):
            return [(c["id"], c["status"]) for c in cases], None
        why = why or "it needs cases: [{id, status}] with status passed, failed, error or skipped"
    except Exception as e:  # invalid XML or JSON, bytes that are not UTF-8, nesting too deep
        why = f"{type(e).__name__}: {e}"
    return None, f"the test report at {rel} is malformed ({why})"


def _case_id_re(case_id: str):
    """Finds a case id in a reported test name in any usual spelling: CP1-T01, CP1_T01, cp1_t01 or CP1T01 (pytest,
    Go and Java names can't hold '-'), with no digit run on either side (so CP1-T01 never matches CP11-T01 or
    CP1-T011)."""
    head, _, tail = case_id.rpartition("-")
    body = re.escape(head) + "[-_]?" + re.escape(tail) if head else re.escape(case_id)
    return re.compile(r"(?<![0-9])" + body + r"(?![0-9])", re.I)


def _case_problems(ctx, cp, cases, red: bool):
    """(what stops the planned cases from counting, whether any of them failed a check). Every planned case must
    have run (its id in a comment proves nothing), no two of its results may have the same name, none may crash or be
    skipped, and after the build every one must pass."""
    out, failed = [], False
    for c in _planned_cases(ctx, cp["id"]):
        pat = _case_id_re(c["id"])
        got = sorted({s for name, s in cases if pat.search(name)})
        named = [name for name, _ in cases if pat.search(name)]
        twice = next((n for n in named if named.count(n) > 1), None)
        failed = failed or "failed" in got
        if twice is not None:
            out.append(f"planned case {c['id']} ran more than once (two results are named '{twice}'; give each "
                       f"test its own result name — a test.each/it.each title needs a placeholder such as %s, and "
                       f"a JSON report needs a distinct id per result — or, if a second test stands in for the "
                       f"planned one, give it its own case id and name)")
        elif not got:
            out.append(f"{c['id']} did not run (it has no result in the test report)")
        elif "error" in got:
            out.append(f"{c['id']} crashed with an error, which does not count as a failed check")
        elif "skipped" in got:  # red refuses a skipped planned case, so at behavior a skip is always new
            out.append(f"{c['id']} was skipped" + ("" if red else " (it was not skipped at the red run)"))
        elif not red and got != ["passed"]:
            out.append(f"{c['id']} did not pass")
    return out, failed


def _tail(text, n=60):
    lines = text.strip().splitlines()
    return "\n".join(lines[-n:])


def cmd_red(args):
    ctx = Ctx(find_root())
    st = ctx.state()
    cps = _cur(ctx, st, args.cp)
    _expect_step(cps, ["red"], args.cp)
    cp = cp_by_id(ctx.plan(), args.cp)
    _, missing, _ = _coverage(ctx, cp)
    if missing:
        die(f"Planned cases not present in the test files: {', '.join(missing)}. Each test must include its case ID "
            f"(e.g. '[{args.cp}-T01] ...'); have ratchet-test-writer put the missing tests back and re-run red.")
    why = _undeclared(ctx, cp)
    if why:
        die(why)
    cfg = ctx.config()
    rpath = _report_path(ctx, cp)
    code, out, _ = _run_cmd(ctx, cp["tests"]["command"], ctx.evidence(args.cp) / "red.log", cfg["test_timeout_sec"],
                            rpath)
    cps["red"] = {"exit": code, "at": now()}
    green = code == 0
    if rpath:
        cases, why = _read_test_report(ctx, rpath)
        bad, failed = ([why], False) if why else _case_problems(ctx, cp, cases, red=True)
        if bad:
            ctx.save_state(st)
            die(f"{args.cp}: the red run does not count: " + "; ".join(bad) + ". The test command must write each "
                "planned case's result to the file named in RATCHET_TEST_REPORT; have ratchet-test-writer fix the "
                "tests and re-run.")
        green = not failed  # the report, not the exit code, says whether a planned case failed a check
    if green and not args.allow_green_first:
        ctx.save_state(st)
        die(f"{args.cp}: tests PASSED before implementation — they don't prove anything yet. "
            f"Have ratchet-test-writer strengthen them, or if this checkpoint only preserves existing "
            f"behaviour re-run with --allow-green-first --reason '...'.")
    if green:
        if not args.reason:
            die("--allow-green-first needs --reason")
        if not cp.get("green_first_ok"):
            ctx.save_state(st)
            die(f"{args.cp} is not marked green_first_ok in the approved plan, so its tests must fail before "
                "implementation. (Pure refactors get green_first_ok from the planner, visible to the user at approval.)")
        cps["red"]["green_first_reason"] = args.reason
    cps["red_tests"] = _snapshot_tests(ctx, cp)
    cps["step"] = "implement"
    ctx.log(st, "red", cp=args.cp, exit=code)
    ctx.save_state(st)
    ok(f"{args.cp}: red run recorded (exit {code}). Next: implement.")


def _test_paths(ctx, cp) -> list[Path]:
    out = []
    for f in (cp.get("tests") or {}).get("files") or []:
        out += sorted(ctx.root.glob(f)) if any(ch in f for ch in "*?[") else [ctx.root / f]
    return [p for p in out if p.is_file()]


def _snapshot_tests(ctx, cp) -> dict:
    """Keep a copy of the tests exactly as they failed at the red run (in evidence/, which agents can't write)."""
    snap = {}
    d = ctx.evidence(cp["id"]) / "red-tests"
    d.mkdir(parents=True, exist_ok=True)
    for p in _test_paths(ctx, cp):
        rel = str(p.relative_to(ctx.root))
        (d / rel.replace("/", "__")).write_bytes(p.read_bytes())
        snap[rel] = _file_sha(p)
    return snap


def _additive(old: str, new: str) -> bool:
    """True if every non-blank line of `old` still appears, in order, in `new` (tests were only added to)."""
    it = iter([l.rstrip() for l in new.splitlines() if l.strip()])
    return all(any(line == n for n in it) for line in [l.rstrip() for l in old.splitlines() if l.strip()])


_PY_DEFS = (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)
_FROZEN_WHY = ("A planned test can't change after its first run: an edit that skips it or ends it early would let "
               "it pass without checking anything (if it really must change, ask the user: "
               "`ratchet.py ask approve-changes`)")
_FROZEN_WHY_DIRECTOR = _FROZEN_WHY.split(" (if it really must change")[0] + (
    " (if it really must change, the director approves it: `director-sign approve-changes --apply`)")


def _problems_for_director(probs) -> str:
    """The integrity problems joined for a director-enrolled lane's refusal: the frozen-test hint names the
    director's command instead of a chat question nobody there answers."""
    return "; ".join(probs).replace(_FROZEN_WHY, _FROZEN_WHY_DIRECTOR)


def _py_scope_items(body):
    """(name, node) for each definition in one Python scope: defs, classes and assignments, including those inside
    if, try, with and for blocks, but not those inside a nested function or class."""
    for s in body:
        if isinstance(s, _PY_DEFS):
            yield s.name, s
        elif isinstance(s, (ast.Assign, ast.AnnAssign, ast.AugAssign)):
            for t in (s.targets if isinstance(s, ast.Assign) else [s.target]):
                for n in ast.walk(t):
                    if isinstance(n, ast.Name):
                        yield n.id, s
        else:
            for f in ("body", "orelse", "finalbody", "handlers", "cases"):
                sub = getattr(s, f, None)
                if isinstance(sub, list):
                    yield from _py_scope_items(sub)


def _py_defs(body, path=()):
    """(path, node) for every def and class, nested ones too. A path is ((name, nth of that name in its scope), ...)."""
    seen = {}
    for name, n in _py_scope_items(body):
        if isinstance(n, _PY_DEFS):
            k = seen[name] = seen.get(name, -1) + 1
            yield path + ((name, k),), n
            yield from _py_defs(n.body, path + ((name, k),))


def _py_lookup(tree, path):
    """The defs along `path` in `tree`, outermost first, or None when one of them is missing."""
    body, nodes = tree.body, []
    for name, k in path:
        defs = [n for nm, n in _py_scope_items(body) if nm == name and isinstance(n, _PY_DEFS)]
        if k >= len(defs):
            return None
        nodes.append(defs[k])
        body = defs[k].body
    return nodes


def _py_start(n) -> int:
    return min([n.lineno] + [d.lineno for d in n.decorator_list])


def _py_place(lines, defs, ids):
    """Where each planned case id sits, the one way the freeze reads it (shared by the freeze and by the lane-added
    test check, so the two never disagree). Each id belongs to the innermost def or class around it (or right after
    its comment line). Returns ({def path: first case id}, ids found in no def or class at all, ids found at least
    once outside every def or class)."""
    starts = {_py_start(n): (p, n) for p, n in defs}
    units, module_ids, loose_ids = {}, [], []
    for cid in ids:
        pat, placed, loose = _case_id_re(cid), False, False
        for no, line in enumerate(lines, 1):
            if not pat.search(line):
                continue
            inside = [(p, n) for p, n in defs if _py_start(n) <= no <= (n.end_lineno or n.lineno)]
            if not inside and line.lstrip().startswith("#"):
                k = no + 1
                while k <= len(lines) and lines[k - 1].lstrip().startswith("#"):
                    k += 1
                inside = [starts[k]] if k in starts else []
            if inside:
                p, _n = max(inside, key=lambda pn: len(pn[0]))
                units.setdefault(p, cid)
                placed = True
            else:
                loose = True
        if loose:
            loose_ids.append(cid)
        if loose and not placed:  # only an id found in no def or class makes the top-level code the test
            module_ids.append(cid)
    return units, module_ids, loose_ids


def _py_frozen(old: str, new: str, ids) -> list[str] | None:
    """The structural freeze for a Python test file (None when the red snapshot is not Python). Each planned case
    id belongs to the innermost def or class around it (or right after its comment line); that definition, with its
    decorators and its enclosing classes' decorators, must be unchanged (compared as ast.dump) and no later
    definition in its scope may reuse its name. An id found in no def or class at all (only in a header comment,
    say) makes the file's top-level code the test:
    each old top-level statement must still be there, unchanged and in order, and no old def or class name may be
    defined again. New tests and helpers may be added anywhere else."""
    try:
        t_old = ast.parse(old)
    except (SyntaxError, ValueError):
        return None
    try:
        t_new = ast.parse(new)
    except (SyntaxError, ValueError) as e:
        return [f"it no longer parses as Python ({type(e).__name__}), so its planned tests can't be checked"]
    units, module_ids, _loose = _py_place(old.splitlines(), list(_py_defs(t_old.body)), ids)
    out = []

    def count(tree, nodes, name):
        body = nodes[-2].body if nodes and len(nodes) > 1 else tree.body
        return sum(1 for nm, _ in _py_scope_items(body) if nm == name)

    for p, cid in units.items():
        what = f"{'.'.join(x for x, _ in p)} ({cid})"
        olds, news = _py_lookup(t_old, p), _py_lookup(t_new, p)
        if news is None:
            out.append(f"planned test {what} is gone since the red run")
        elif any(count(t_new, news[:j + 1], p[j][0]) > count(t_old, olds[:j + 1], p[j][0]) for j in range(len(p))):
            out.append(f"planned test {what} is defined again since the red run (the later definition replaces it)")
        elif ast.dump(news[-1]) != ast.dump(olds[-1]) or [ast.dump(d) for a in news[:-1] for d in a.decorator_list] \
                != [ast.dump(d) for a in olds[:-1] for d in a.decorator_list]:
            out.append(f"planned test {what} changed since the red run")
    if module_ids:
        what = f"{', '.join(module_ids)} (named outside any function, so the file's existing top-level code is the test)"
        cur = iter([ast.dump(s) for s in t_new.body])
        changed = next((s for s in t_old.body if not any(ast.dump(s) == c for c in cur)), None)
        top = {nm for nm, n in _py_scope_items(t_old.body) if isinstance(n, _PY_DEFS)}
        again = sorted(nm for nm in top if count(t_new, None, nm) > count(t_old, None, nm))
        if changed is not None:
            out.append(f"planned test {what} changed since the red run (at red line {changed.lineno})")
        elif again:
            out.append(f"planned test {what} has {again[0]} defined again since the red run")
    return out


_COMMENT = ("//", "#", "/*", "*", "--")


def _in_comment(line: str, pos: int) -> bool:
    """True when position `pos` of `line` is inside a comment: the line is a comment line, or a //, /*, # or --
    (the last two after a space or at the start) comes before `pos` outside any quoted string. A Rust attribute
    (#[...]) is not a comment."""
    if line.strip().startswith(_COMMENT) and not line.strip().startswith("#["):
        return True
    q, k = None, 0
    while k < pos:
        c = line[k]
        if q:
            if c == "\\":
                k += 1
            elif c == q:
                q = None
        elif c in "\"'`":
            q = c
        elif line.startswith(("//", "/*"), k) or (c == "#" and not line.startswith("#[", k)
                                                   or line.startswith("--", k)) and (k == 0 or line[k - 1].isspace()):
            return True
        k += 1
    return False


def _test_decls(lines, pat):
    """The indexes of each line, in a non-Python test file, that holds the case id outside any comment: either the
    test's own opening line (its name, as in it('[CP1-T01] ...', or Go's func TestCP1_T01) or an annotation directly
    above it (such as @DisplayName("[CP1-T01] ...")). A line holding the id only inside a comment is never counted."""
    out = []
    for i, line in enumerate(lines):
        m = pat.search(line)
        if m and not _in_comment(line, m.start()):
            out.append(i)
    return out


def _planned_name(line: str, pat):
    """The name of the test a line declares with a case id: the quoted name holding the id, or the identifier holding
    it, such as a Go TestCP1T01 (None when it has neither)."""
    q = next((q.group(0) for q in re.finditer(r"([\"'`])(?:\\.|(?!\1).)*\1", line) if pat.search(q.group(0))), None)
    if q is not None:
        return q
    m = pat.search(line)
    if not m:
        return None
    a, b = m.start(), m.end()
    while a and (line[a - 1].isalnum() or line[a - 1] in "_$"):
        a -= 1
    while b < len(line) and (line[b].isalnum() or line[b] in "_$"):
        b += 1
    return line[a:b] if re.fullmatch(r"[A-Za-z_$][\w$]*", line[a:b]) else None


def _text_frozen(old: str, new: str, ids) -> list[str]:
    """The structural freeze for a test file in any other language that holds planned case ids: the file as it was at
    the red run must be an exact prefix of the file now, so new tests and helpers may only be added at its end. An
    added part may not declare a planned test's name again (in a language where a later definition replaces an
    earlier one, it would stand in for the planned test). No language syntax is parsed."""
    pats = [(cid, _case_id_re(cid)) for cid in ids]
    lines = old.splitlines()
    names, decl_lines = [], set()
    for cid, pat in pats:
        decl = _test_decls(lines, pat) or [i for i, l in enumerate(lines) if pat.search(l)]
        decl_lines.update(decl)
        for i in decl:
            names.append((cid, _planned_name(lines[i], pat)))
    if not names:
        return []
    tail = new[len(old):]
    if not new.startswith(old) or (old and not old.endswith("\n") and tail and tail[0] not in "\r\n"):
        cur = new.splitlines()
        at = next((k for k, l in enumerate(lines) if k >= len(cur) or cur[k] != l), len(lines) - 1)
        listed = ", ".join(f"{n} ({cid})" if n else cid for cid, n in names)
        if decl_lines and at < min(decl_lines):
            # The first change sits above any planned test's own line: an ordinary insertion (a new import, a new
            # helper), not an edit to a planned test. Say so plainly instead of pointing at approve-changes.
            return [f"content above the end of the file changed since the red run (first change at red line "
                    f"{at + 1}; this file holds planned tests: {listed}). Move the added lines to the end of the "
                    f"file, or put a test that needs a new import in a new test file"]
        return [f"content above the end of the file changed since the red run (first change at red line {at + 1}; "
                f"this file holds planned tests: {listed}). Outside Python, a test file that holds planned tests "
                f"may only have lines added at its end. {_FROZEN_WHY}"]
    for cid, n in names:
        if not n:
            continue
        rx_ = (re.compile(r"[\"'`]" + re.escape(n[1:-1]) + r"[\"'`]") if n[0] in "\"'`" else
               re.compile(r"(?<![\w$])" + re.escape(n) + r"(?![\w$])"))
        if rx_.search(tail):
            return [f"planned test {n} ({cid}) is declared again in lines added since the red run (a later "
                    f"definition with the same name could replace it; give a new test its own case id and name)"]
    return []


def _frozen_test_problems(rel: str, old: str, new: str, ids) -> list[str]:
    """Why a test file's planned tests no longer match the red run (empty when they all still do)."""
    got = _py_frozen(old, new, ids) if rel.endswith(".py") else None
    return _text_frozen(old, new, ids) if got is None else got


# --- tests the lane added: free to change after red (Python files only) -----------------------------------------
# A top-level def (or a test method in a class) is free when it was not in the file as the run started (the run's
# base tree), is no planned case of any step, and no planned case uses it, directly or through other code. Free defs
# are cut out of both the red snapshot and the file now before the usual freeze checks run, so those checks stay
# exactly as strict on everything else. Freedom comes from the base tree and the plan, never from the latest
# snapshot, so an approve-changes re-snapshot does not freeze a lane-added test.
_PY_IMPLICIT = frozenset({
    "setUp", "tearDown", "setUpClass", "tearDownClass", "setUpModule", "tearDownModule", "load_tests", "setup",
    "teardown", "setup_module", "teardown_module", "setup_function", "teardown_function", "setup_method",
    "teardown_method", "setup_class", "teardown_class", "conftest"})


def _all_planned_ids(ctx):
    plan = ctx.plan() or {}
    return [c["id"] for cp in plan.get("checkpoints") or [] for c in _planned_cases(ctx, cp["id"])]


def _file_at(ctx, rev, rel):
    """The file as it stands in the tree or commit `rev`: its text, "" when the file is not there, or None when it
    can't be read (no git, no such tree or commit)."""
    if not rev or not re.fullmatch(r"[0-9a-f]{40,64}", str(rev)) or not _is_git(ctx.root):
        return None
    try:
        t = subprocess.run(["git", "rev-parse", "-q", "--verify", f"{rev}^{{tree}}"], cwd=ctx.root,
                           capture_output=True, text=True, timeout=30)
        tree = t.stdout.strip()
        if t.returncode != 0 or not tree:
            return None
        # The tree is the whole repo's, so a Ratchet root below the repo root needs the repo-relative path.
        pre = subprocess.run(["git", "rev-parse", "--show-prefix"], cwd=ctx.root, capture_output=True, text=True,
                             timeout=30)
        if pre.returncode != 0:
            return None
        path = f"{pre.stdout.strip()}{rel}"
        ls = subprocess.run(["git", "ls-tree", "--full-tree", tree, "--", path], cwd=ctx.root, capture_output=True,
                            text=True, timeout=30)
        if ls.returncode != 0:
            return None
        if not ls.stdout.strip():
            return ""  # the file really was not there when the run started
        r = subprocess.run(["git", "cat-file", "blob", f"{tree}:{path}"], cwd=ctx.root, capture_output=True,
                           timeout=30)
    except (OSError, subprocess.SubprocessError):
        return None
    return r.stdout.decode("utf-8", "replace") if r.returncode == 0 else None


def _origin_file_texts(ctx, st, rel):
    """The texts of file `rel` that decide what the lane added: at the run's base tree, at the first step's starting
    tree (set when the plan was approved, so a merge or fast-forward made before that is in it), and at every
    non-first parent of a merge commit made on HEAD's history since the run began (what main brought in). None when
    any of them can't be read: nothing in the file then counts as lane-added (any doubt locks)."""
    first = ((ctx.plan() or {}).get("checkpoints") or [{}])[0].get("id")
    trees = [st.get("base_tree"), ((st.get("checkpoints") or {}).get(first) or {}).get("base_tree")]
    try:
        since = int(_dt.datetime.fromisoformat(st["created_at"]).timestamp()) - 2
        ml = subprocess.run(["git", "rev-list", "--parents", "--merges", f"--since={since}", "HEAD"], cwd=ctx.root,
                            capture_output=True, text=True, timeout=60)
    except (KeyError, ValueError, OSError, subprocess.SubprocessError):
        return None
    if ml.returncode != 0:
        return None
    for line in ml.stdout.splitlines():
        trees += line.split()[2:]
    texts = [_file_at(ctx, t, rel) for t in dict.fromkeys(trees)]
    if texts and texts[0] is not None and trees[1] and texts[1:2] == [None] and trees[1] != trees[0]:
        # The first step's tree is gone: it only matters if the lane fast-forwarded to main since the run began.
        g = lambda *a: subprocess.run(["git", *a], cwd=ctx.root, capture_output=True, text=True, timeout=30)
        if _fast_forwarded(g, None, None, since + 2) == "":
            texts.pop(1)
    return None if not texts or any(t is None for t in texts) else texts


def _py_uses(node, loads=False) -> set:
    """Every name a piece of code could use: names, attributes, parameter names, imported names and string
    constants that look like names (a fixture asked for by string). Over-counting only locks more, never less.
    With `loads`, a name the code only assigns (a Store) is not counted."""
    out = set()
    for n in ast.walk(node):
        if isinstance(n, ast.Name):
            if not (loads and isinstance(n.ctx, ast.Store)):
                out.add(n.id)
        elif isinstance(n, ast.Attribute):
            out.add(n.attr)
        elif isinstance(n, ast.arg):
            out.add(n.arg)
        elif isinstance(n, ast.Constant) and isinstance(n.value, str) and n.value.isidentifier():
            out.add(n.value)
        elif isinstance(n, (ast.Import, ast.ImportFrom)):
            out.update((a.asname or a.name).split(".")[0] for a in n.names)
    return out


def _py_top_names(tree) -> set:
    names = {nm for nm, _ in _py_scope_items(tree.body)}
    for s in ast.walk(tree):
        if isinstance(s, (ast.Import, ast.ImportFrom)):
            names.update((a.asname or a.name).split(".")[0] for a in s.names)
    return names


def _py_deco_kw(n, key):
    """The keyword arguments named `key` in a def's decorators (such as autouse=True or name="cart")."""
    return [k for d in n.decorator_list for k in ast.walk(d) if isinstance(k, ast.keyword) and k.arg == key]


def _py_aliases(n):
    """The def's own name plus any fixture name= alias in its decorators."""
    return [n.name] + [k.value.value for k in _py_deco_kw(n, "name")
                       if isinstance(k.value, ast.Constant) and isinstance(k.value.value, str)]


def _other_py_index(ctx):
    """{word: set of project .py files naming it} over the project's own .py files (git ls-files: tracked plus
    untracked, .gitignore respected; nothing under a dependency, build or dot folder), or None when git cannot list
    them (the caller then locks everything: Ratchet never walks the tree instead)."""
    try:
        r = subprocess.run(["git", "ls-files", "--cached", "--others", "--exclude-standard", "-z", "--", "*.py"],
                           cwd=ctx.root, capture_output=True, timeout=60)
    except (OSError, subprocess.SubprocessError):
        return None
    if r.returncode != 0:
        return None
    index = {}
    for raw in r.stdout.split(b"\0"):
        f = os.path.normpath(os.fsdecode(raw))
        parts = Path(f).parts
        if not raw or any(d in FINGERPRINT_EXCLUDES or d.startswith(".") for d in parts[:-1]):
            continue
        try:
            text = (Path(ctx.root) / f).read_text(errors="replace")
        except OSError:
            continue
        for w in set(re.findall(r"\w+", text)):
            index.setdefault(w, set()).add(f)
    return index


def _py_free_defs(ctx, st, rel, old):
    """(free top-level def names, free (class, test method) pairs, names a planned case reaches) in the red snapshot
    `old` of file `rel`. Any doubt locks: when nothing is free the names come back as None (the caller then guards
    every def and class name), and a file where a planned case id sits outside every def (module data, a header
    docstring, a comment not directly above a def) is not touched at all, exactly as the freeze reads it."""
    none = (set(), set(), None)
    bases = _origin_file_texts(ctx, st, rel)
    if bases is None or os.path.basename(rel) == "conftest.py" or not any(_case_id_re(i).search(old) for i in _all_planned_ids(ctx)):
        return none  # a file with no planned case id in it (a shared helper file) keeps the whole-file freeze
    try:
        t_old = ast.parse(old)
        t_bases = [ast.parse(b) for b in bases]
    except (SyntaxError, ValueError):
        return none
    base_names, base_members = set(), set()  # what was in the file before the lane: at the run's base or from main
    for t_base in t_bases:
        base_names |= _py_top_names(t_base)
        for s in t_base.body:
            if isinstance(s, ast.ClassDef):
                base_members.update((s.name, nm) for nm, _ in _py_scope_items(s.body))
    defs = list(_py_defs(t_old.body))
    units, _module_ids, loose = _py_place(old.splitlines(), defs, _all_planned_ids(ctx))
    if loose:
        return none
    by_path = dict(defs)
    planned = [by_path[p] for p in units]

    def span(n):
        return _py_start(n), n.end_lineno or n.lineno

    def has_planned(n):  # n holds a planned node, or sits inside one (every method of a planned class)
        a, b = span(n)
        return any((a <= span(p)[0] and span(p)[1] <= b) or (span(p)[0] <= a and b <= span(p)[1]) for p in planned)

    def special(n):  # an autouse fixture or a pytest_ hook (they run for planned tests unnamed), or a name we can't read
        return bool(_py_deco_kw(n, "autouse")) or n.name.startswith("pytest_") or any(not (isinstance(k.value, ast.Constant) and
                                                           isinstance(k.value.value, str))
                                                      for k in _py_deco_kw(n, "name"))

    src_defs, src_top, locked_tops = [], [], set()  # code whose names a planned test (or the run) leans on
    for s in t_old.body:
        if not isinstance(s, _PY_DEFS):
            src_top.append(s)
            continue
        if has_planned(s):
            locked_tops.add(s.name)
            if isinstance(s, ast.ClassDef):  # the class's setUp and helpers count, its other tests do not
                src_defs += s.bases + s.keywords + s.decorator_list
                for m in s.body:
                    if not (isinstance(m, (ast.FunctionDef, ast.AsyncFunctionDef)) and m.name.lower().startswith("test")
                            and not has_planned(m)):
                        src_defs.append(m)
            else:
                src_defs.append(s)
        elif special(s):
            src_defs.append(s)
        if isinstance(s, ast.ClassDef):
            src_defs += [m for m in s.body if isinstance(m, (ast.FunctionDef, ast.AsyncFunctionDef)) and special(m)]
    by_name = {}
    for nm, n in _py_scope_items(t_old.body):
        if isinstance(n, _PY_DEFS):
            for alias in _py_aliases(n):
                by_name.setdefault(alias, []).append(n)

    def closure(sources, loads):  # every name reachable from the sources, through the defs of those names
        reach, todo = set(), set(_PY_IMPLICIT).union(*[_py_uses(x, loads) for x in sources])
        while todo:
            nm = todo.pop()
            if nm in reach:
                continue
            reach.add(nm)
            for n in by_name.get(nm, []):
                todo |= _py_uses(n, loads) - reach
        return reach

    reach = closure(src_defs + src_top, False)  # what no lane-added def may be: used by a planned case or top-level code
    reached = closure(src_defs, True)  # the names a planned case reads (an assignment may not rebind these)

    skip, found = os.path.normpath(rel), []  # found: the index, built once and only when a def needs it

    def named_elsewhere(alias):  # another project .py file names it as a whole word (no index: assume it does)
        if not found:
            found.append(_other_py_index(ctx))
        if found[0] is None or not re.fullmatch(r"\w+", alias):
            return True
        return any(f != skip for f in found[0].get(alias, ()))

    def plain(n):  # a def nothing outside the lane can lean on, and no other .py file mentions by name
        return (not any(a in reach for a in _py_aliases(n)) and n.name not in _PY_IMPLICIT and not has_planned(n)
                and not special(n) and not any(named_elsewhere(a) for a in _py_aliases(n)))

    items = [nm for nm, _ in _py_scope_items(t_old.body)]
    free_top = {s.name for s in t_old.body if isinstance(s, _PY_DEFS) and s.name not in base_names
                and s.name not in locked_tops and plain(s) and items.count(s.name) == 1}
    free_meth = set()
    for s in t_old.body:
        if isinstance(s, ast.ClassDef) and s.name not in free_top:
            inner = [nm for nm, _ in _py_scope_items(s.body)]
            cand = {m.name for m in s.body if isinstance(m, (ast.FunctionDef, ast.AsyncFunctionDef))
                    and m.name.lower().startswith("test") and (s.name, m.name) not in base_members
                    and plain(m) and inner.count(m.name) == 1}
            if len(cand) < len(s.body):  # a class is never left with an empty body
                free_meth |= {(s.name, nm) for nm in cand}
    return free_top, free_meth, reached | locked_tops | {p.name for p in planned}


def _py_strip(text, free_top, free_meth):
    """`text` without the free defs (and the comment lines right above them), or None when it doesn't parse."""
    try:
        tree = ast.parse(text)
    except (SyntaxError, ValueError):
        return None
    lines = text.splitlines(keepends=True)
    drop = set()

    def cut(n):
        a = _py_start(n)
        while a > 1 and lines[a - 2].lstrip().startswith("#"):
            a -= 1
        drop.update(range(a, (n.end_lineno or n.lineno) + 1))

    for s in tree.body:
        if isinstance(s, _PY_DEFS) and s.name in free_top:
            cut(s)
        elif isinstance(s, ast.ClassDef):
            for m in s.body:
                if isinstance(m, (ast.FunctionDef, ast.AsyncFunctionDef)) and (s.name, m.name) in free_meth:
                    cut(m)
    out = "".join(l for i, l in enumerate(lines, 1) if i not in drop)
    try:
        ast.parse(out)
    except (SyntaxError, ValueError):
        return None
    return out


def _py_without_free(ctx, st, rel, old, new):
    """(old, new, names a planned case reaches) with the lane's free defs cut out of both; the texts are unchanged
    when there are none or anything is unclear (the names are None when the analysis was not possible)."""
    free_top, free_meth, locked = _py_free_defs(ctx, st, rel, old)
    if not (free_top or free_meth):
        return old, new, locked
    a, b = _py_strip(old, free_top, free_meth), _py_strip(new, free_top, free_meth)
    return (a, b, locked) if a is not None and b is not None else (old, new, locked)


def _py_name_reuse(old, new, locked=None):
    """Why `new` defines again a name `old` defines in the same scope, so that the later definition would replace
    the earlier one; None when it doesn't. Top-level scope and every class body. A def or class of any name counts;
    a plain assignment counts only for a name a planned case reaches (`locked`) or a name that is also a def or
    class in that scope, so rebinding an ordinary variable in a test the lane added stays allowed."""
    try:
        t_old, t_new = ast.parse(old), ast.parse(new)
    except (SyntaxError, ValueError):
        return None

    def stores(n, nm):  # n is an assignment that binds the plain name nm
        return isinstance(n, (ast.Assign, ast.AnnAssign)) and any(
            isinstance(x, ast.Name) and x.id == nm and isinstance(x.ctx, ast.Store)
            for t in (n.targets if isinstance(n, ast.Assign) else [n.target]) for x in ast.walk(t))

    def counts(body, watch):
        c = {}
        for nm, n in _py_scope_items(body):
            if isinstance(n, _PY_DEFS) or (nm in watch and stores(n, nm)):
                c[nm] = c.get(nm, 0) + 1
        return c

    scopes = [("", t_old.body, t_new.body)]
    for path, n in _py_defs(t_old.body):
        if isinstance(n, ast.ClassDef):
            got = _py_lookup(t_new, path)
            if got:
                scopes.append((".".join(x for x, _ in path) + ".", n.body, got[-1].body))
    for pre, b_old, b_new in scopes:
        watch = (locked or set()) | {nm for nm, n in _py_scope_items(b_old) if isinstance(n, _PY_DEFS)}
        c_old, c_new = counts(b_old, watch), counts(b_new, watch)
        again = next((nm for nm in c_old if c_new.get(nm, 0) > c_old[nm]), None)
        if again is not None:
            return f"{pre}{again} is defined again since the red run (the later definition replaces it)"
    return None


def weakened_tests(ctx, st) -> list[str]:
    cur = st.get("current")
    cps = (st.get("checkpoints") or {}).get(cur) or {}
    if not cps.get("red_tests"):
        return []
    out, ids = [], [c["id"] for c in _planned_cases(ctx, cur)]
    d = ctx.run_dir() / "evidence" / cur / "red-tests"
    for rel in cps["red_tests"]:
        old_p, new_p = d / rel.replace("/", "__"), ctx.root / rel
        if not old_p.exists():
            continue
        old = old_p.read_text(errors="replace")
        new = new_p.read_text(errors="replace") if new_p.exists() else None
        if new is None:
            out.append(f"test file {rel} (lines changed or removed since the red run)")
            continue
        if rel.endswith(".py"):  # tests this lane added are cut out of both sides first (see _py_free_defs)
            old, new, locked = _py_without_free(ctx, st, rel, old, new)
        frozen = _frozen_test_problems(rel, old, new, ids)
        if not frozen and rel.endswith(".py"):
            frozen = [w] if (w := _py_name_reuse(old, new, locked)) else []
        if frozen:
            # Non-Python messages (_text_frozen) already carry whatever guidance applies (the approve-changes
            # note only when a planned test itself is at risk); only Python messages (_py_frozen) need it added.
            out.append(f"test file {rel}: {frozen[0]}. {_FROZEN_WHY}" if rel.endswith(".py")
                        else f"test file {rel}: {frozen[0]}")
        elif not _additive(old, new):
            out.append(f"test file {rel} (lines changed or removed since the red run)")
    return out


def cmd_implemented(args):
    ctx = Ctx(find_root())
    st = ctx.state()
    cps = _cur(ctx, st, args.cp)
    _expect_step(cps, ["implement"], args.cp)
    cp = cp_by_id(ctx.plan(), args.cp)
    cps["step"] = "behavior" if cp["gates"].get("behavior") else ("ui" if cp["gates"].get("ui") else "adversarial")
    ctx.log(st, "implemented", cp=args.cp)
    ctx.save_state(st)
    ok(f"{args.cp}: implementation recorded. Next: {cps['step']} gate.")


def _record_behavior_failure(ctx, st, g: dict, cfg, cp_id: str, code: int, log: Path, check: dict | None = None):
    """The one record of a failed behavior attempt (the tests, their re-run, or an automatic check `check`): the
    gate's status and `last`, the attempt limit (`blocked` so a human decides), the `behavior_failed` history
    event, the saved state and the viewer. The caller prints the tail and dies with its own message."""
    g["status"] = "failed"
    g["last"] = {"exit": code, "log": str(log.relative_to(ctx.root)), "at": now()}
    if check:
        g["last"]["check"] = check.get("kind")
    if g["attempts"] >= cfg["max_behavior_attempts"]:
        _set_blocked(st, f"{cp_id}: behavior gate failed {g['attempts']} times — needs a human decision.")
    if check:
        ctx.log(st, "behavior_failed", cp=cp_id, attempt=g["attempts"], check=check.get("kind"))
    else:
        ctx.log(st, "behavior_failed", cp=cp_id, attempt=g["attempts"])
    ctx.save_state(st)
    build_viewer(ctx)


def cmd_behavior(args):
    ctx = Ctx(find_root())
    st = ctx.state()
    cps = _cur(ctx, st, args.cp)
    _expect_step(cps, ["behavior", "ui", "adversarial", "complete"], args.cp)
    cp = cp_by_id(ctx.plan(), args.cp)
    if not cp["gates"].get("behavior"):
        die(f"{args.cp} has no behavior gate")
    cfg = ctx.config()
    g = cps["gates"]["behavior"]
    g["attempts"] += 1
    g["runs"] = g.get("runs", 0) + 1  # a persistent invocation counter for evidence filenames: unlike `attempts`,
    # this never decrements for a forgiven flaky pass, so a later invocation can never reuse (and overwrite) an
    # earlier invocation's behavior log.
    files, missing, _ = _coverage(ctx, cp)
    if missing:
        g["status"] = "failed"
        ctx.save_state(st)
        die(f"Behavior gate FAILED: planned cases were removed from tests: {', '.join(missing)}. "
            "Tests may not be deleted or weakened to pass the gate.")
    rpath = _report_path(ctx, cp)
    # the code under the run: an edit to it while the tests, the re-run or a check runs stops that command and
    # ends here with nothing saved (see _run_cmd); the same watch covers every command of this call
    watch = _Watch(ctx, fingerprint(ctx.root), _watch_every(cfg), f"behavior {args.cp}",
                   extra=cfg.get("fingerprint_include") or [])

    def run_once(suffix):
        log_ = ctx.evidence(args.cp) / f"behavior-{g['runs']:02d}{suffix}.log"
        code_, out_, dur_ = _run_cmd(ctx, cp["tests"]["command"], log_, cfg["test_timeout_sec"], rpath, watch)
        bad_ = []
        if rpath:
            cases, why = _read_test_report(ctx, rpath)
            bad_ = [why] if why else _case_problems(ctx, cp, cases, red=False)[0]
        return code_, out_, dur_, bad_, log_

    code, out, dur, bad, log = run_once("")
    flaky = False
    if (code != 0 or bad) and not g.get("flaky_used"):
        # One immediate automatic re-run, once per step: a failure that passes on it is flaky, not a real
        # attempt. The allowance is spent the moment this retry is attempted, win or lose, so a second failing
        # call never gets a free retry of its own just because this one's retry also failed.
        g["flaky_used"] = True
        code2, out2, dur2, bad2, log2 = run_once("b")
        if code2 == 0 and not bad2:
            code, out, dur, bad, log = code2, out2, dur2, bad2, log2
            flaky = True
            g["attempts"] -= 1  # the retry spends no attempt of this step's own allowance
        # else: a second failure (genuine or another flaky-shaped one) is never forgiven — falls through below,
        # still counted as exactly one attempt.
    failed_check = None
    fp_tests = fingerprint(ctx.root)["id"] if code == 0 and not bad and cfg.get("checks") else None
    if code == 0 and not bad:
        for chk in cfg.get("checks") or []:
            if not isinstance(chk, dict) or not chk.get("command"):
                continue
            clog = ctx.evidence(args.cp) / f"check-{re.sub(r'[^a-z0-9]+', '-', str(chk.get('kind', 'x')))}-{g['runs']:02d}.log"
            ccode, cout, _ = _run_cmd(ctx, chk["command"], clog, cfg["test_timeout_sec"], watch=watch)
            if ccode != 0:
                code, out, log, failed_check = ccode, cout, clog, chk
                break
    fp = fingerprint(ctx.root)
    if fp_tests and fp["id"] != fp_tests and not failed_check:
        g["status"] = "failed"
        ctx.save_state(st)
        die(f"Behavior gate FAILED for {args.cp}: an automatic check changed files in the project. Checks must only read "
            "the code; restore the files (git) and fix the check's command.", 2)
    if code != 0 and failed_check:
        _record_behavior_failure(ctx, st, g, cfg, args.cp, code, log, check=failed_check)
        print(_tail(out))
        die(f"Behavior gate FAILED for {args.cp}: the automatic check '{failed_check.get('kind')}' "
            f"({failed_check.get('command')}) failed. Log: {log.relative_to(ctx.root)}. Give it to ratchet-implementer; "
            "the check stays as it is.", 2)
    if code != 0 or bad:
        _record_behavior_failure(ctx, st, g, cfg, args.cp, code, log)
        print(_tail(out))
        die(f"Behavior gate FAILED for {args.cp} (exit {code}" + ("; " + "; ".join(bad) if bad else "") +
            f"). Log: {log.relative_to(ctx.root)}. "
            "Give the failure to ratchet-implementer (do NOT edit the tests to make them pass) and re-run.", 2)
    g.update(status="passed", fingerprint=fp, passed_at=now(), flaky=flaky or bool(g.get("flaky")),
             last={"exit": 0, "log": str(log.relative_to(ctx.root)), "at": now(), "duration": dur})
    cps["step"] = _earliest_open_step(cps)
    ctx.log(st, "behavior_passed", cp=args.cp, attempt=g["attempts"], flaky=flaky)
    ctx.save_state(st)
    build_viewer(ctx)
    ok(f"Gate 1 (behavior) PASSED for {args.cp}{' (flaky: passed on an immediate re-run)' if flaky else ''}. "
       f"Next step: {cps['step']}")


def _ui_verdict(review: dict, cfg) -> tuple[str, list]:
    """Recompute the UI verdict from the differences list (don't trust a self-reported PASS)."""
    if str(review.get("verdict", "")).upper() == "INVALID":
        return "INVALID", []
    blockers = []
    for d in review.get("differences", []) or []:
        sev = str(d.get("severity", "")).lower()
        fixable = d.get("fixable_in_code", True)
        if not fixable and sev in ("minor", "nit"):  # only minor/nit rendering quirks may be exempt
            continue
        if sev == "nit" and not cfg["ui_block_on_nits"]:
            continue
        blockers.append(d)
    return ("PASS" if not blockers else "FAIL"), blockers


MAX_REVIEW_BYTES = 8 * 1024 * 1024  # a reviewer's output or combined UI review larger than this is refused outright


def _review_round_dir(ctx, cp_id: str, kind: str, n: int) -> Path:
    """The one folder a review round's files must sit in: reviews/<CP>/adv-round-NN/ (adversarial) or
    reviews/<CP>/round-NN/ (UI)."""
    return ctx.run_dir() / "reviews" / cp_id / f"{'adv-round' if kind == 'adv' else 'round'}-{n:02d}"


def _read_round_review(ctx, path, folder: Path, what: str, hint: str = ""):
    """Check a review file's location FIRST, then read it exactly once from the opened file.

    Refuses a file whose real location (symlinks and `..` resolved) is not directly inside this round's own folder,
    before anything in it is read, so a file from anywhere else always gets the folder message (even if it is
    malformed or stale). The file is then opened inside that folder without following links (relative to the
    opened folder where the platform allows), checked through the open descriptor to be the same regular,
    single-link file that was located, and read from that descriptor. Returns (resolved path, bytes, fstat): every
    later check and the evidence copy use these bytes, so swapping the file after the check changes nothing."""
    try:
        rel = folder.relative_to(ctx.root).as_posix()
    except ValueError:
        rel = folder.as_posix()
    where = (f"{what} must be written directly inside this round's own folder, {rel}/ "
             f"({folder}). Run the review again with its output in that folder.{hint}")
    try:
        real = Path(os.path.realpath(str(path)))
        base = Path(os.path.realpath(str(folder)))
    except (OSError, ValueError):
        die(f"Can't resolve {path}. {where}")
    if os.path.normcase(str(real.parent)) != os.path.normcase(str(base)):
        die(f"{path} is not in this round's folder (it resolves to {real}). {where}")
    try:
        lst = os.lstat(str(real))
        base_st = os.stat(str(base))
    except OSError:
        die(f"Review not found: {path}. {where}")
    if not stat.S_ISREG(lst.st_mode) or lst.st_nlink > 1:
        die(f"{path} is a link to another file, not a review written here. {where}")
    nofollow = getattr(os, "O_NOFOLLOW", 0)
    flags = os.O_RDONLY | nofollow | getattr(os, "O_BINARY", 0) | getattr(os, "O_NONBLOCK", 0)
    changed = f"{path} changed while it was being checked (replaced, or turned into a link). {where}"
    dfd = fd = None
    try:
        if os.open in os.supports_dir_fd and hasattr(os, "O_DIRECTORY"):
            dfd = os.open(str(base), os.O_RDONLY | os.O_DIRECTORY | nofollow)
            if not os.path.samestat(os.fstat(dfd), base_st):
                die(changed)
            fd = os.open(real.name, flags, dir_fd=dfd)
        else:  # e.g. Windows: no dir_fd; the descriptor identity check below still catches a swap
            fd = os.open(str(real), flags)
    except OSError as e:
        if fd is not None:
            os.close(fd)
        die(f"{changed} ({e.strerror or e})")
    finally:
        if dfd is not None:
            os.close(dfd)
    try:
        try:
            fst = os.fstat(fd)
        except OSError as e:
            die(f"Could not inspect {path} after opening it: {e.strerror or e}. {where}")
        if not stat.S_ISREG(fst.st_mode) or fst.st_nlink > 1 or not os.path.samestat(lst, fst):
            die(changed)
        if fst.st_size > MAX_REVIEW_BYTES:
            die(f"{path} is {fst.st_size} bytes, over the {MAX_REVIEW_BYTES}-byte review size limit. A real "
                f"reviewer output is never this large; trim it (or check it is the right file) and try again. {where}")
        chunks = []
        total = 0
        try:
            while True:
                b = os.read(fd, 1 << 20)
                if not b:
                    break
                total += len(b)
                if total > MAX_REVIEW_BYTES:
                    die(f"{path} grew past the {MAX_REVIEW_BYTES}-byte review size limit while it was being read "
                        f"(it changed size concurrently). {where}")
                chunks.append(b)
        except OSError as e:
            die(f"Could not read {path}: {e.strerror or e}. {where}")
    finally:
        os.close(fd)
    return real, b"".join(chunks), fst


def _parse_review(raw: bytes, path) -> dict:
    """Parse review bytes already read by _read_round_review (never re-read the file by name)."""
    try:
        data = json.loads(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as e:
        die(f"{path} is not valid JSON: {e}")
    if not isinstance(data, dict):
        die(f"{path} must hold a JSON object (see schemas.md).")
    return data


_SURROGATE_RE = re.compile("[\ud800-\udfff]")


def clean_review_text(v):
    """A parsed review with every lone surrogate (a reviewer's cut-off emoji escape, "\\ud83d") replaced by U+FFFD,
    in every string and key, so no later record, page or message fails to encode it. external_review.py cleans before
    it signs; adv-record and ui-record clean after the signature is checked."""
    if isinstance(v, str):
        return _SURROGATE_RE.sub("\ufffd", v)
    if isinstance(v, list):
        return [clean_review_text(x) for x in v]
    if isinstance(v, dict):
        return {clean_review_text(k): clean_review_text(x) for k, x in v.items()}
    return v


def _write_review_evidence(dst: Path, raw: bytes, fst):
    """Copy the review into evidence from the bytes that were checked, keeping the original timestamps."""
    try:
        dst.write_bytes(raw)
    except OSError as e:
        die(f"Could not write the evidence copy to {dst}: {e.strerror or e}. Check that the evidence folder "
            f"({dst.parent}) exists and is writable with room for the file, then try again.")
    try:
        os.utime(str(dst), ns=(fst.st_atime_ns, fst.st_mtime_ns))
    except OSError:
        pass


# ---- review signing ----------------------------------------------------------------------------------------------
# Every review round has its own secret, kept in Ratchet's per-user folder (never in the project, never printed) and
# removed once the round is recorded. external_review.py and ui_review.py sign what they write with it (HMAC-SHA256
# over the review's canonical JSON, the round's nonce or label, and the code fingerprint); adv-record and ui-record
# refuse a review that is unsigned or whose signature does not match. A review by the host's own reviewer sub-agent
# (ratchet-adversary, ratchet-visual-reviewer, ratchet-behavior-reviewer) is not signed: the guard hook records, in the
# same per-user record, who wrote the file. On Claude Code it names the sub-agent, and a file it did not see that
# sub-agent write with the Write tool is refused. On Codex, Gemini and Copilot, or with the hooks waived, the hook can't
# say who wrote it, so any file in the round folder with the right nonce and code version counts and is marked "not
# independently confirmed". The record is identified by the round itself (an adversarial round's own nonce; for a UI
# round, the run's creation time, its round number and how many UI rounds this step has recorded), so a record left
# by an abandoned run or an earlier round never speaks for a later one. This stops a different process on the same
# machine that has no access to the per-user folder (the guard keeps agents out of it); it is not an operating system
# boundary.

UNCONFIRMED = "not independently confirmed"
# Files the guard records the writer of: the REVIEW_OWNERS entries that name an owner sub-agent (an adversarial
# round's reviews, and a UI round's two per-role reviews). Their patterns carry named groups (slug, cp, n, name).
ADV_REVIEW_RE = re.compile(r"^runs/(?P<slug>[^/]+)/reviews/(?P<cp>[^/]+)/adv-round-(?P<n>\d+)/(?P<name>[^/]+\.json)$", re.I)
UI_ROLES = ("visual", "behavior")


def ui_round_number(st: dict, cp_id) -> int | None:
    """The UI round a checkpoint is on (one more than its recorded UI rounds), or None when it has no UI gate."""
    g = ((((st.get("checkpoints") or {}).get(cp_id) or {}).get("gates") or {}).get("ui")) or {}
    if not g.get("required"):
        return None
    return int(g.get("attempts") or 0) + 1


def _round_id(st: dict, cp_id: str, kind: str, n: int) -> str | None:
    """What makes this round unique, or None when there is no such round in this run."""
    cps = (st.get("checkpoints") or {}).get(cp_id) or {}
    if kind == "adv":
        rnd = cps.get("adv_round") or {}
        if rnd.get("nonce") and int(rnd.get("round") or 0) == int(n):
            return str(rnd["nonce"])
        return None
    g = (cps.get("gates") or {}).get("ui") or {}
    if kind == "ui" and g.get("required") and st.get("created_at"):
        return f"{st['created_at']}#{int(n)}#{int(g.get('rounds_recorded') or 0)}"
    return None


def review_key_file(root, st: dict, cp_id: str, kind: str, n: int) -> Path | None:
    """Where this round's signing record lives under Ratchet's per-user folder (None when there is no such round)."""
    rid = _round_id(st, cp_id, kind, n)
    if rid is None:
        return None
    ident = "|".join([os.path.realpath(str(root)), str(st.get("slug")), cp_id, kind, str(int(n)), rid])
    return ratchet_home() / "review-keys" / (hashlib.sha256(ident.encode()).hexdigest()[:32] + ".json")


def open_review_key(ctx, cp_id: str, kind: str, n: int, st: dict | None = None) -> tuple[dict | None, str]:
    """This round's signing record ({"secret", "writers"}), created when missing (a fresh secret and no writers).
    (None, why) when it can't be: why is "busy" (another Ratchet command holds the record) or a plain reason."""
    st = st if st is not None else ctx.state()
    p = review_key_file(ctx.root, st, cp_id, kind, n)
    if p is None:
        return None, f"{cp_id} has no open {'adversarial' if kind == 'adv' else 'UI'} review round {n} in this run"
    try:
        p.parent.mkdir(parents=True, exist_ok=True)
        os.chmod(str(p.parent), 0o700)
        res = update_record(p, lambda d: KEEP if d.get("secret") else {"secret": secrets.token_hex(32), "writers": {}},
                            damaged=lambda _why: {})
        if res == "busy":
            return None, "busy"
        os.chmod(str(p), 0o600)
    except OSError as e:
        return None, f"it could not be written ({e})"
    key = review_key(ctx, cp_id, kind, n, st=st)
    return (key, "") if key else (None, f"it could not be read back from {p}")


def review_key_problem(why: str, retry: str) -> str:
    """The plain message for a round secret that could not be created (open_review_key's reason)."""
    if why == "busy":
        return ("Another Ratchet command is using this round's review-signing record right now. Wait a moment, then "
                f"{retry}.")
    return (f"Could not create this round's review-signing secret under {ratchet_home() / 'review-keys'}: {why}. "
            f"Make that folder writable, then {retry}.")


def review_key(ctx, cp_id: str, kind: str, n: int, create: bool = False, st: dict | None = None) -> dict | None:
    """This round's signing record, created when `create` and missing. None when there is none (or it can't be read
    or written: a review then can't be signed, and is refused, which is the safe side)."""
    if create:
        return open_review_key(ctx, cp_id, kind, n, st)[0]
    p = review_key_file(ctx.root, st if st is not None else ctx.state(), cp_id, kind, n)
    if p is None:
        return None
    data, _why = _read_record(p, missing=None)
    return data if isinstance(data, dict) and data.get("secret") else None


def drop_review_key(p: Path | None):
    """Remove a round's record (from review_key_file, taken before the state changes) once the round is recorded and
    saved, or replaced, so its signatures and writer records can't be reused."""
    if p is None:
        return
    for f in (p, _record_lock_path(p)):
        try:
            f.unlink()
        except OSError:
            pass


def ui_round_label(cp_id: str, n: int) -> str:
    return f"{cp_id}/ui/round-{int(n):02d}"


def _review_mac(secret: str, review: dict, label: str) -> str:
    body = {k: v for k, v in review.items() if k != "signature"}
    # ASCII-escaped canonical JSON: a reviewer's lone surrogate ("\ud83d") can't make the encoding fail
    payload = "\n".join([json.dumps(body, sort_keys=True, separators=(",", ":"), ensure_ascii=True), str(label),
                         str(review.get("fingerprint"))])
    return hmac.new(secret.encode(), payload.encode("utf-8", "surrogatepass"), hashlib.sha256).hexdigest()


def sign_review(key: dict, review: dict, label: str, by: str) -> dict:
    review.pop("signature", None)
    review["signature"] = {"alg": "hmac-sha256", "by": by, "value": _review_mac(key["secret"], review, label)}
    return review


def signature_well_formed(sig) -> bool:
    """A signature shaped like one sign_review makes. Anything else is an incidental field, not a signing attempt."""
    return (isinstance(sig, dict) and sig.get("alg") == "hmac-sha256" and isinstance(sig.get("value"), str)
            and re.fullmatch(r"[0-9a-f]{64}", sig["value"]) is not None)


def review_signed(key: dict | None, review: dict, label: str) -> bool:
    sig = review.get("signature")
    if not key or not signature_well_formed(sig):
        return False
    return hmac.compare_digest(sig["value"], _review_mac(key["secret"], review, label))


def ui_manifest_label(cp_id: str, n: int) -> str:
    return f"{ui_round_label(cp_id, n)}/manifest"


def stamp_ui_manifest(ctx, st: dict, cp_id: str, n: int, key: dict, manifest: dict) -> str:
    """`ui_review.py review` / `stage`, before writing the capture manifest for this UI round: give it a fresh stamp,
    make that the round's current one (`manifest_stamp` in the round's record), and sign the manifest with the round's
    secret. Per-role reviews written for an earlier stamp stop counting. '' on success, else why (as open_review_key)."""
    p = review_key_file(ctx.root, st, cp_id, "ui", n)
    if p is None:
        return f"{cp_id} has no open UI review round {n} in this run"
    stamp = secrets.token_hex(16)

    def put(d):
        if not d.get("secret"):
            return KEEP
        d["manifest_stamp"] = stamp
        return d
    try:
        res = update_record(p, put)
    except OSError as e:
        return f"it could not be written ({e})"
    if res != "written":
        return "busy" if res == "busy" else f"its record could not be updated ({res})"
    key["manifest_stamp"] = stamp
    manifest.pop("signature", None)
    manifest["stamp"] = stamp
    sign_review(key, manifest, ui_manifest_label(cp_id, n), "ui_review.py")
    return ""


def ui_manifest_problem(key: dict | None, cp_id: str, n: int, man) -> str:
    """Why a capture manifest given to `ui_review.py combine` does not count for this UI round ('' when it does)."""
    if not isinstance(man, dict) or not review_signed(key, man, ui_manifest_label(cp_id, n)):
        return (f"it was not written by `ui_review.py review` or `stage` for {cp_id}'s UI round {n}; a capture manifest "
                "typed, copied or edited by hand, or one from another round, does not count. Run `ui_review.py review` "
                "(or `stage`) on the capture manifest, then have the reviewers review again")
    if man.get("stamp") != (key or {}).get("manifest_stamp"):
        return ("`ui_review.py review` or `stage` has stamped a newer capture manifest for this round since this one; "
                "use the manifest they wrote last, with reviews written after it")
    return ""


STALE_UI_INPUT = ("it was written for an earlier capture manifest (`ui_review.py review` or `stage` has stamped the "
                  "manifest again since), so it may be a review of other code; have that reviewer review again")


def _review_file_match(rel: str | None):
    """(kind, match, owner sub-agent) for a review file whose writer the guard records (a REVIEW_OWNERS entry that
    names an owner), or None."""
    for rx, owners in REVIEW_OWNERS:
        m = rx.match(rel or "")
        if m and owners:
            return ("adv" if rx is ADV_REVIEW_RE else "ui"), m, sorted(owners)[0]
    return None


def _note_writer_failure(root: Path, host: str, rel: str, detail: str):
    """A review file's writer could not be recorded: logged where hook failures go (hook-errors.log), so the later
    refusal and `doctor` can say why. Never raises (the hook fails open)."""
    try:
        _append_record(root / RATCHET_DIR / "hook-errors.log",
                       f"{now()} {host} guard: ReviewWriterNotRecorded: {rel}: {detail}\n")
    except Exception:
        pass


def _note_review_writer(n: dict):
    """Guard hook: remember who wrote a review file into an open review round's folder (Claude Code names the
    sub-agent; other CLIs don't, so their writes are recorded as not confirmed). Never breaks the hook; a write it
    could not record is logged to hook-errors.log."""
    host = n["host"]
    actor = (n.get("agent_type") or "").split(":")[-1]
    for p in n["paths"]:
        rel = root = hit = None
        try:
            rel = _ratchet_rel(p, n["cwd"])
            hit = _review_file_match(rel)
            if not hit:
                continue
            kind, m, owner = hit
            full = Path(os.path.normpath(os.path.join(n["cwd"], os.path.expanduser(p))))
            root = find_root(full.parent)
            st, _why = _read_record(root / RATCHET_DIR / "runs" / m.group("slug") / "state.json", missing=None)
            kp = review_key_file(root, st, m.group("cp"), kind, int(m.group("n"))) if isinstance(st, dict) else None
            if kp is None or not kp.exists():
                continue  # no open round with a record: nothing could ever be confirmed against it
            mine = _host_names_subagent(host) and actor == owner

            def add(data, name=m.group("name"), mine=mine, kind=kind):
                if not data.get("secret"):
                    return KEEP
                prev = (data.get("writers") or {}).get(name) or {}
                w = {"host": host, "agent": actor or None, "at": now(),
                     "confirmed": bool(mine and prev.get("confirmed", True))}
                other = prev.get("other_writer") or (None if mine else (actor or "main session"))
                if other:
                    w["other_writer"] = other
                if kind == "ui":  # the capture manifest it was written against: combine refuses an older one
                    w["manifest_stamp"] = data.get("manifest_stamp")
                data.setdefault("writers", {})[name] = w
                return data
            res = update_record(kp, add)
            if res in ("busy", "damaged"):
                _note_writer_failure(root, host, rel, f"its round's record was {res}")
        except Exception as e:
            if not hit:
                continue  # not a review file: there was no writer to record
            if root is None:
                try:
                    root = _ratchet_root_of(n.get("cwd"))
                except Exception:
                    root = None
            if root is not None:
                _note_writer_failure(Path(root), host, str(rel or p), f"{type(e).__name__}: {e}")


def host_writer_origin(ctx, cfg, st: dict, key: dict | None, name: str, owner: str) -> tuple[str, str]:
    """How an unsigned file written by a host reviewer sub-agent (`owner`) is known to be real: ('confirmed', ''),
    ('unconfirmed', why) or ('refused', why)."""
    w = ((key or {}).get("writers") or {}).get(name)
    if w:
        if w.get("confirmed"):
            return "confirmed", ""
        if _host_names_subagent(w.get("host") or ""):
            other = w.get("other_writer") or w.get("agent")
            who = "the main session (not a sub-agent)" if other in (None, "main session") else f"the {other} sub-agent"
            return "refused", f"Ratchet's guard saw it written or edited by {who}, not only by a {owner} sub-agent"
        return "unconfirmed", "this CLI's hook does not say which sub-agent wrote it"
    if _waiver_applies(ctx.root, cfg, st):
        return "unconfirmed", "Ratchet's hooks are waived for this run, so nothing recorded who wrote it"
    if not _host_names_subagent(VENDOR_TO_HOST.get(detect_host(cfg), "unknown")):
        return "unconfirmed", ("this CLI's hook did not record who wrote it; on this CLI any file in the round folder "
                               "with the right nonce and code version counts")
    return "refused", (f"Ratchet's guard did not see a {owner} sub-agent write it with the Write tool in this round "
                       "(a file written through the shell, or by the main session, is not recorded)")


def _writer_failure_note(root: Path, name: str) -> str:
    hits = [e for e in read_hook_errors(root) if "ReviewWriterNotRecorded" in e["message"] and name in e["message"]]
    return (" The guard could not record who wrote this file (see hook-errors.log in the project's Ratchet folder, "
            "and `ratchet.py doctor`)." if hits else "")


def check_review_origin(ctx, cfg, st: dict, cp_id: str, n: int, rp, rpath: Path, r: dict, rid: str,
                        label: str) -> tuple[str, str]:
    """How an adversarial review is known to be real: ('script-signed', ''), ('confirmed', '') for a host sub-agent
    the guard named, or ('unconfirmed', why) where the guard could not name the writer (Codex, Gemini, Copilot, or
    hooks waived). Dies when it is none of these."""
    key = review_key(ctx, cp_id, "adv", n, st=st)
    if signature_well_formed(r.get("signature")):
        if key is None:
            die(f"{rp} ({rid}) is signed, but this round's signing secret is gone, so no signature can be checked. Run "
                f"`ratchet.py reviewers {cp_id}` and run its reviewers again.")
        if review_signed(key, r, label):
            return "script-signed", ""
        die(f"{rp} ({rid}) has a signature that does not match this round: it was changed after it was signed, or it "
            f"was signed for another round. An edited or copied review does not count; run the reviewer again "
            f"(see `ratchet.py reviewers {cp_id}`).")
    why = "it has no signature from external_review.py for this round"
    if (_roster_spec(cfg, rid) or {}).get("kind") == "agent":
        origin, why = host_writer_origin(ctx, cfg, st, key, rpath.name, "ratchet-adversary")
        if origin != "refused":
            return origin, why
    die(f"{rp} ({rid}) is unsigned and does not count: {why}. Ratchet accepts a review signed by external_review.py "
        "for this round, or one the host's ratchet-adversary sub-agent wrote with the Write tool (not through the "
        "shell) while Ratchet's hooks run. A review typed, copied or edited by hand does not count. Launch the "
        f"reviewer again as `ratchet.py reviewers {cp_id}` says.{_writer_failure_note(ctx.root, rpath.name)}")


def ui_input_origin(ctx, cfg, st: dict, key: dict | None, cp_id: str, n: int, path: Path, r: dict) -> tuple[str, str]:
    """How a per-role UI review given to `ui_review.py combine` is known to be real: ('script-signed', '') when
    `ui_review.py review` signed it for this round, ('confirmed', '') or ('unconfirmed', why) for a host reviewer
    sub-agent's file in this round's folder, or ('refused', why)."""
    role = r.get("reviewer")
    current = (key or {}).get("manifest_stamp")
    if signature_well_formed(r.get("signature")):
        if role in UI_ROLES and review_signed(key, r, f"{ui_round_label(cp_id, n)}/{role}"):
            return ("script-signed", "") if r.get("manifest_stamp") == current else ("refused", STALE_UI_INPUT)
        return "refused", ("its signature does not match this UI round: it was changed after ui_review.py signed it, or "
                           "it was signed for another round")
    folder = _review_round_dir(ctx, cp_id, "ui", n)
    hit = None
    try:
        real = Path(os.path.realpath(str(path)))
        if real.parent == Path(os.path.realpath(str(folder))):
            hit = _review_file_match(real.relative_to(Path(os.path.realpath(str(ctx.ratchet)))).as_posix())
    except (OSError, ValueError):
        real = Path(str(path))
    if not hit or hit[0] != "ui":
        return "refused", (f"it is not signed by `ui_review.py review`, and it is not a reviewer's visual.json or "
                           f"behavior.json in this round's folder ({folder})")
    if role != real.stem.lower():
        return "refused", f"its reviewer field says {role!r}, but {real.name} is the {real.stem.lower()} reviewer's file"
    w = ((key or {}).get("writers") or {}).get(real.name)
    if w and w.get("manifest_stamp") != current:
        return "refused", STALE_UI_INPUT
    return host_writer_origin(ctx, cfg, st, key, real.name, hit[2])


def cmd_ui_record(args):
    ctx = Ctx(find_root())
    st = ctx.state()
    cps = _cur(ctx, st, args.cp)
    _expect_step(cps, ["ui", "adversarial", "complete"], args.cp)
    cp = cp_by_id(ctx.plan(), args.cp)
    if not cp["gates"].get("ui"):
        die(f"{args.cp} has no UI gate")
    cfg = ctx.config()
    g = cps["gates"]["ui"]
    n = g["attempts"] + 1
    review_path, raw, fst = _read_round_review(ctx, args.review, _review_round_dir(ctx, args.cp, "ui", n),
                                               f"The combined UI review for round {n}")
    review = _parse_review(raw, args.review)
    for key in ("reviewers", "differences"):
        if key not in review:
            die(f"combined review must contain '{key}' (see ratchet-ui-compare skill)")
    if len(review.get("reviewers", [])) < 2 and not cfg.get("ui_single_reviewer_ok"):
        die("UI gate needs both a visual and a behaviour reviewer in the combined review.")
    if review.get("checkpoint") not in (None, args.cp):
        die(f"combined review is for {review.get('checkpoint')}, not {args.cp}.")
    cur_fp = fingerprint(ctx.root)["id"]
    if review.get("fingerprint") != cur_fp:
        die("combined review is not stamped with the current code fingerprint (it was produced for other code, or by "
            "hand). Capture and review again with ui_review.py — it stamps the fingerprint itself.")
    ui_key = review_key(ctx, args.cp, "ui", n, st=st)
    if signature_well_formed(review.get("signature")) and ui_key is None:
        die(f"{args.review} is signed, but UI round {n} has no signing secret (ui_review.py has not opened this round, "
            "or its secret was removed), so the signature can't be checked and the review does not count; one signed "
            "for another round never does. Run ui_review.py (`review`, or `stage` and `combine`) for this round.")
    if not review_signed(ui_key, review, ui_round_label(args.cp, n)):
        die(f"{args.review} is unsigned, or was changed after ui_review.py signed it for round {n}. Only a combined "
            "review written by ui_review.py (`review`, or `combine`) for this round counts; a combined.json typed or "
            "edited by hand does not.")
    review = clean_review_text(review)  # its signature is checked: from here on it only feeds records and messages
    compared = review.get("compared") or {}
    if not compared.get("spec_sha256") or compared.get("scope") is None:
        die("The combined review doesn't say what was compared (capture spec and scope). Produce it with "
            "ui_review.py from a capture.mjs manifest: `review`, or `combine --manifest <manifest.json>`.")
    spec_file = ctx.run_dir() / "states" / f"{args.cp}.json"
    if spec_file.exists() and hashlib.sha256(spec_file.read_bytes()).hexdigest() != compared["spec_sha256"]:
        die(f"states/{args.cp}.json changed after this capture. Capture and review again.")
    frozen = g.get("frozen")
    if frozen and frozen != compared:
        die(f"The UI check found differences in {args.cp}, and since then the capture spec (states/{args.cp}.json) "
            "or the review scope has changed. Differences are fixed in the app's code, not by changing what is "
            "compared. Put the spec and scope back as they were and re-run the capture. If the spec itself was "
            f"wrong, explain to the user what you want to change and why, run `ratchet.py ask ui-respec {args.cp}`, "
            "end your message with the question it prints, word for word, as the only question in it, and end your "
            f"turn. Run `ratchet.py ui-respec {args.cp}` only if their first reply after it is one of the listed yes "
            "replies.")
    key_file = review_key_file(ctx.root, st, args.cp, "ui", n)  # dropped only once this round is saved as recorded
    g["attempts"] += 1
    g["rounds_recorded"] = int(g.get("rounds_recorded") or 0) + 1  # never reset: a later round never reuses a record
    unconfirmed = [x for x in review.get("unconfirmed") or [] if isinstance(x, str)]  # signed with the review
    if unconfirmed:
        g["unconfirmed"] = unconfirmed
    else:
        g.pop("unconfirmed", None)
    verdict, blockers = _ui_verdict(review, cfg)
    dest = ctx.evidence(args.cp) / "ui" / f"round-{g['attempts']:02d}"
    dest.mkdir(parents=True, exist_ok=True)
    if review_path.parent != dest:
        _write_review_evidence(dest / "combined.json", raw, fst)
    if verdict == "INVALID":
        g["status"] = "invalid"
        ctx.log(st, "ui_invalid", cp=args.cp, reason=review.get("invalid_reason"))
        ctx.save_state(st)
        drop_review_key(key_file)  # this round is recorded and saved: its secret goes
        die(f"UI comparison INVALID ({review.get('invalid_reason', 'states did not match')}). "
            "Re-capture prototype and app in the SAME state and review again.", 2)
    if verdict == "FAIL":
        g["status"] = "failed"
        g["blockers"] = len(blockers)
        g["frozen"] = compared  # from now on only the app's code may change until the gate passes
        if g["attempts"] >= cfg["max_ui_rounds"]:
            _set_blocked(st, f"{args.cp}: UI gate failed {g['attempts']} rounds — needs a human decision.")
        ctx.log(st, "ui_failed", cp=args.cp, blockers=len(blockers))
        ctx.save_state(st)
        drop_review_key(key_file)
        build_viewer(ctx)
        for b in blockers:
            print(f"  - [{b.get('severity')}] {b.get('location')}: {b.get('description')}")
        die(f"Gate 2 (UI) FAILED for {args.cp}: {len(blockers)} blocking difference(s). "
            "Send them to ratchet-implementer, then re-run behavior + UI.", 2)
    g.update(status="passed", fingerprint=fingerprint(ctx.root), passed_at=now(),
             evidence=str(dest.relative_to(ctx.root)), blockers=0)
    g.pop("frozen", None)
    cps["step"] = _earliest_open_step(cps)
    ctx.log(st, "ui_passed", cp=args.cp, round=g["attempts"])
    ctx.save_state(st)
    drop_review_key(key_file)
    build_viewer(ctx)
    ok(f"Gate 2 (UI) PASSED for {args.cp}. Next step: {cps['step']}")


def cmd_ui_respec(args):
    """The user agreed that the UI check itself (capture spec or scope) was wrong: allow one change to it."""
    ctx = Ctx(find_root())
    st = ctx.state()
    cps = _cur(ctx, st, args.cp)
    g = cps["gates"]["ui"]
    if not g.get("frozen"):
        ok(f"{args.cp}'s UI check isn't frozen; the spec can change freely until it finds a difference.")
        return
    _require_pending(st, "ui-respec", args.cp)
    msg = _require_human(ctx, st, "ui-respec", getattr(args, "director_token", None))
    g.pop("frozen", None)
    _clear_pending(st)
    ctx.log(st, "ui_respec_approved", cp=args.cp, by=msg["by"], note=msg.get("prompt", "")[:200])
    ctx.save_state(st)
    ok(f"{args.cp}: the capture spec and scope may be changed once; the next recorded round becomes the new baseline.")


def _dedupe_finding_ids(findings: list) -> list:
    """Gives every finding from ONE reviewer a usable, unique id before `reviewer` is stamped on it: a finding
    with no `id`, or one whose `id` repeats an earlier finding's from the SAME reviewer (two independent
    reviewers sharing an id is normal and handled elsewhere, by `_finding_key`'s 'reviewer/id'; this is about one
    reviewer's own list carrying a duplicate or a blank id), gets a synthetic one instead
    (`<id-or-'F'>-dup<n>`, counting only the repeats, so the first of each id is left exactly as the reviewer
    wrote it). The synthetic id is never just assumed unique: it is checked against every explicit (non-blank) id
    anywhere else in the SAME reviewer's list, and against every synthetic id already handed out, bumping the
    counter until it really is new. Without this, `_finding_key` could still collide for two DIFFERENT findings
    of the same reviewer (a blank id's synthetic default happening to match an id the reviewer wrote by hand,
    e.g. a blank id next to an explicit 'F'): the one the user was shown and asked about, and one they never
    saw, so accepting the shown one would silently also clear the other (and a blank id could never be named
    with `accept-finding` at all)."""
    explicit_ids = {f.get("id") for f in findings if f.get("id") not in (None, "")}
    seen: dict = {}
    assigned: set = set()
    out = []
    for f in findings:
        fid = f.get("id")
        key = fid if fid not in (None, "") else "\x00missing"
        seen[key] = seen.get(key, 0) + 1
        n = seen[key]
        if fid in (None, "") or n > 1:
            base = str(fid) if fid not in (None, "") else "F"
            candidate = base if (fid in (None, "") and n == 1) else f"{base}-dup{n}"
            while candidate in explicit_ids or candidate in assigned:
                n += 1
                candidate = f"{base}-dup{n}"
            assigned.add(candidate)
            f = dict(f, id=candidate)
        out.append(f)
    return out


def _checkin_state(cps) -> dict:
    """The checkpoint's own check-in record (state.json, never a separate file): whether each of the two triggers
    has already fired once for this step, the running count of rounds that hit the 'new kind in an already-flagged
    file' condition, the check-in that is currently open (or None), and every past decision. `cps` is the same
    dict object held inside `state.json`'s `checkpoints`, so mutating what this returns and saving state is enough;
    nothing here is written as its own file."""
    return cps.setdefault("checkin", {"round_count_fired": False, "new_kind_fired": False,
                                      "new_kind_repeats": 0, "open": None, "decided": []})


def _checkin_trigger(ctx, st, cp_id, cps, g, rnd, blocking_findings) -> str | None:
    """Call right after a round is recorded as still blocking (g['rounds'] already carries this round's own entry,
    last in the list). Opens a check-in (see cmd_check_in) at most once per trigger per step: either this is the
    `checkin_round`'th (default 2) round in a row to block, or this is the SECOND round where a finding kind never
    seen before in this step shows up in a file an earlier round already had a blocking finding in. Returns a short
    note for the adv-record refusal message when one just opened, else None. Mutates `cps` in place; the caller
    still has to `ctx.save_state(st)`."""
    ci = _checkin_state(cps)
    if ci.get("open"):
        return None  # already waiting on an earlier check-in; don't stack a second one on top
    cfg = ctx.config()
    # New-kind events are counted every round, whichever trigger (if any) ends up opening a check-in this round;
    # otherwise a round that also satisfies the round-count trigger would never have its own new-kind event
    # counted, undercounting new_kind_repeats for a later round.
    prior_blocking_files: set = set()
    for rr in (g.get("rounds") or [])[:-1]:
        prior_blocking_files |= set(rr.get("blocking_files") or [])
    seen_kinds_before = {k for k, hits in (st.get("finding_kinds") or {}).items()
                         if any(h.get("cp") == cp_id and h.get("round") is not None and h["round"] < rnd["round"]
                                for h in hits)}
    new_kind_hit = any(
        finding_kind(f) and finding_kind(f) not in seen_kinds_before
        and _norm_path(f.get("file") or f.get("path") or f.get("location"), ctx.root) in prior_blocking_files
        for f in blocking_findings)
    if new_kind_hit:
        ci["new_kind_repeats"] = int(ci.get("new_kind_repeats", 0)) + 1
    trigger = None
    consecutive_blocking = 0
    for rr in reversed(g.get("rounds") or []):
        if rr.get("findings", 0) > 0:
            consecutive_blocking += 1
        else:
            break  # an approved round (no blocking findings) resets the consecutive count
    if not ci.get("round_count_fired") and consecutive_blocking >= int(cfg.get("checkin_round", 2)):
        trigger = "round_count"
    elif new_kind_hit and not ci.get("new_kind_fired") and ci["new_kind_repeats"] >= 2:
        trigger = "new_kind_repeat"
    if not trigger:
        return None
    ci["open"] = {"round": rnd["round"], "trigger": trigger, "opened_at": now()}
    ci["round_count_fired" if trigger == "round_count" else "new_kind_fired"] = True
    return f"A check-in opened (reviews have been dragging): run `ratchet.py check-in {cp_id}` before fixing more."


def _checkin_all_open_findings(ctx, cp_id, cps, g) -> list:
    """The still-open (not accepted) findings for the check-in brief: the latest recorded round's own
    open-findings.json, the same current view `reviewers` and the fixer already use (`_adv_open_findings`). A
    finding fixed or withdrawn by a later round never reappears here, and a reviewer reusing an id (e.g. `A1`) for
    a different problem in a later round is never confused with an earlier round's now-resolved one, because only
    the latest round's file is read."""
    return _adv_open_findings(ctx, cp_id, cps.get("adv_round"), cps)


def _checkin_kinds_by_file(ctx, findings: list) -> dict:
    out: dict = {}
    for f in findings:
        where = _norm_path(f.get("file") or f.get("path") or f.get("location"), ctx.root) or "(unknown file)"
        kinds = out.setdefault(where, [])
        k = finding_kind(f) or "?"
        if k not in kinds:
            kinds.append(k)
    return out


CHECKIN_OPTIONS = [
    {"letter": "A", "text": "Simplify: narrow or change the step so the review notes stop applying; record why "
                            "with `ratchet.py check-in CPn --decision simplify --why \"...\"` (no user question)."},
    {"letter": "B", "text": "Accept the open findings as a known limit: only the user's own reply through `ask "
                            "accept-finding` / `accept-finding` does this; check-in can't accept anything itself."},
    {"letter": "C", "text": "Stop here and ask the user how to wrap up (`ratchet.py check-in CPn --decision stop`)."},
]


def _checkin_brief(ctx, plan, cp_id, cps, g, ci) -> dict:
    open_ci = ci.get("open") or {}
    findings = _checkin_all_open_findings(ctx, cp_id, cps, g)
    obj = plan.get("objective") if isinstance(plan, dict) else None
    return {"checkpoint": cp_id, "round": open_ci.get("round"), "trigger": open_ci.get("trigger"),
            "rounds_used": len(g.get("rounds") or []),
            "objective": obj if isinstance(obj, dict) and obj else NO_OBJECTIVE_NOTE,
            "findings": [{"id": _finding_key(f), "severity": f.get("severity"),
                          "file": f.get("file") or f.get("path") or f.get("location"), "kind": finding_kind(f),
                          "description": f.get("description"), "user_impact": f.get("user_impact"),
                          # CP3: the done-means line(s) the finding names, as written, so a line-naming minor is
                          # never read as a plain "(minor)" at a decision point
                          "done_means": f.get("done_means") if names_done_means(f) else None}
                         for f in findings],
            "kinds_by_file": _checkin_kinds_by_file(ctx, findings),
            "options": CHECKIN_OPTIONS, "decided": ci.get("decided") or []}


def _print_checkin_brief(brief: dict):
    print(f"Check-in for {brief['checkpoint']} (round {brief['round']}, rounds used: {brief['rounds_used']}, "
          f"trigger: {brief['trigger']}).")
    obj = brief["objective"]
    if isinstance(obj, dict):
        print(f"Who it's for: {obj.get('users', '')}")
        print(f"What they want: {obj.get('goal', '')}")
    else:
        print(f"Note: {obj}.")
    print("Open findings:")
    dm_lines = (obj.get("done_means") if isinstance(obj, dict) else None) or []
    for f in brief["findings"]:
        line = f"  - {f['id']} ({f.get('severity', '?')}) {f.get('file') or ''}: {f.get('description', '') or ''}"
        print(line.rstrip())
        if f.get("user_impact"):
            print(f"      user impact: {f['user_impact']}")
        if f.get("done_means") is not None:
            print(f"      {_dm_named_text(dm_lines, f).strip().strip('[]')}")
    if brief["kinds_by_file"]:
        print("Finding kinds by file:")
        for fl, kinds in brief["kinds_by_file"].items():
            print(f"  - {fl}: {', '.join(kinds)}")
    print("What next:")
    for o in brief["options"]:
        print(f"  {o['letter']}) {o['text']}")


def cmd_check_in(args):
    """`ratchet.py check-in CPn` (optionally `--decision simplify|change|accept|stop [--why "..."]`, `--json`).
    With no decision: prints (or returns as JSON) the open check-in's brief and changes nothing. `simplify` and
    `change` are recorded from the reasoning given in `--why` (no user question; the skill requires that
    reasoning come from a fresh strong-model consult, not the orchestrator's own continued reasoning, but this
    command itself only records whatever `--why` carries); `accept` is always refused, pointing at the
    accept-finding flow (CP3), which needs the user's own reply; `stop` hands the run to the existing
    blocked/ask flow for the user to decide how to wrap up.

    `simplify`/`change` also work with no check-in open, while `cp_id` is `blocked` on its OWN adversarial
    round-limit (`_adv_block_kind` returning "own"): CP1's lettered menu there leads with simplify, then change, so
    each reuses check-in's own simplify record to grant this step exactly one extra review round, at most once
    each (`gates.adversarial.round_limit_simplify_used` / `round_limit_change_used`, added to
    `round_limit_grants`, which `_adv_round_cap` adds on top of the step's cap) -- never a fresh budget, and
    never offered a second time for either. A plain `human-approve` (with or without a lettered pick) never
    grants this; only these two commands, and `raise-limit`, ever hand a step more review rounds."""
    ctx = Ctx(find_root())
    st = ctx.state()
    plan = ctx.plan() or {}
    cp_id = args.cp
    cps = (st.get("checkpoints") or {}).get(cp_id)
    if cps is None:
        die(f"No such checkpoint {cp_id}.")
    ci = _checkin_state(cps)
    g = ((cps.get("gates") or {}).get("adversarial")) or {}
    decision = getattr(args, "decision", None)
    if decision is None:
        if not ci.get("open"):
            if getattr(args, "json", False):
                print(json.dumps({"checkpoint": cp_id, "open": False}, indent=2))
            else:
                print(f"No check-in is open for {cp_id}.")
            return
        brief = _checkin_brief(ctx, plan, cp_id, cps, g, ci)
        if getattr(args, "json", False):
            print(json.dumps(brief, indent=2))
        else:
            _print_checkin_brief(brief)
        return
    decision = decision.strip().lower()
    open_ci = ci.get("open")
    if not open_ci:
        if decision in ("simplify", "change") and _adv_block_kind(st, cp_id) == "own":
            why = (getattr(args, "why", None) or "").strip()
            if not why:
                die(f"check-in --decision {decision} needs --why \"...\" explaining the reasoning. Nothing was "
                    "recorded.")
            used_key = f"round_limit_{decision}_used"
            if g.get(used_key):
                die(f"{cp_id}'s round-limit {decision} grant was already used once; it is never granted again "
                    f"for this step. Nothing was changed. Run `ratchet.py ask raise-limit {cp_id}` instead if "
                    "this step hasn't used its one raise yet.")
            g[used_key] = True
            g["round_limit_grants"] = int(g.get("round_limit_grants", 0)) + 1
            ci.setdefault("decided", []).append({"round": g.get("attempts"), "trigger": "round_limit",
                                                 "decision": decision, "why": why, "decided_at": now()})
            ctx.log(st, "checkin_round_limit_grant", cp=cp_id, decision=decision, why=why[:300])
            prev_attempts = g.get("attempts", 0)  # preserved across _unblock exactly like raise-limit: this
            # grants exactly one more round, not a fresh budget.
            _unblock(ctx, st, "agent", f"check-in {decision} granted {cp_id} one extra review round: {why}")
            g["attempts"] = prev_attempts
            ctx.save_state(st)
            build_viewer(ctx)
            ok(f"Recorded: {decision} ({why}). {cp_id} now has one extra review round. "
               f"`ratchet.py reviewers {cp_id}` can open it now.")
            return
        die(f"No check-in is open for {cp_id}, and it isn't blocked on its own round limit either. Nothing to "
            "decide.")
    if decision == "accept":
        die("check-in cannot accept an open finding itself: a cooperative agent must not wave its own findings "
            f"through here. That needs the user's own reply, through `ratchet.py ask accept-finding {cp_id} <ids>` "
            "then `ratchet.py accept-finding` (CP3's own flow). Nothing was changed.")
    if decision == "simplify":
        why = (getattr(args, "why", None) or "").strip()
        if not why:
            die("check-in --decision simplify needs --why \"...\" explaining the reasoning. Nothing was recorded.")
        ci.setdefault("decided", []).append({"round": open_ci["round"], "trigger": open_ci["trigger"],
                                             "decision": "simplify", "why": why, "decided_at": now()})
        ci["open"] = None
        ctx.log(st, "checkin_simplify", cp=cp_id, round=open_ci["round"], why=why[:300])
        ctx.save_state(st)
        ok(f"Recorded: simplify ({why}). `ratchet.py reviewers {cp_id}` can open the next round now.")
        return
    if decision == "stop":
        ci.setdefault("decided", []).append({"round": open_ci["round"], "trigger": open_ci["trigger"],
                                             "decision": "stop", "decided_at": now()})
        ci["open"] = None
        _set_blocked(st, f"{cp_id}: a check-in paused the review loop after reviews kept dragging — needs the "
                         "user's decision on how to wrap up.")
        ctx.log(st, "checkin_stop", cp=cp_id, round=open_ci["round"])
        ctx.save_state(st)
        ok("Recorded: stop. The run now waits for the user to say how to wrap up.")
        return
    if decision == "change":
        die(f"check-in --decision change only applies while {cp_id} is blocked on its own adversarial round "
            "limit, not during an open check-in; run `check-in --decision simplify` instead (it already covers "
            "narrowing or changing the step while reviews are dragging). Nothing was changed.")
    die("check-in --decision must be simplify, change, accept or stop.")


TRIAGE_DECISIONS = {"fix", "rebut"}
TRIAGE_REDIRECT = {"accept", "defer", "waive", "skip"}


def _read_triage(dest: Path) -> dict:
    return read_json(dest / "triage.json", {}, record="Ratchet treats a damaged triage file as empty")


def cmd_triage(args):
    """`ratchet.py triage CPn <ref>=fix:<reason> ...` or `<ref>=rebut:<reason> ...`, any number of decisions in one
    call, `ref` being a finding's key from the checkpoint's latest recorded (blocked) round's open findings (a bare
    id, or 'reviewer/id' when a bare id is ambiguous — the same keys `open-findings.json` lists). Only fix or rebut
    are accepted: the orchestrator can never defer, accept or waive a finding through triage, since that needs the
    user's own reply through the accept-finding flow (CP3). An empty reason is refused. Writes the round's own
    triage.json (every decision ever recorded for this round; a later call may change one) and fix-list.json (only
    the findings decided 'fix', for the fixer)."""
    ctx = Ctx(find_root())
    st = ctx.state()
    cps = (st.get("checkpoints") or {}).get(args.cp)
    if cps is None:
        die(f"No such checkpoint {args.cp}.")
    rnd = cps.get("adv_round")
    if not rnd or not rnd.get("recorded"):
        die(f"{args.cp} has no recorded blocking round to triage yet. Run `ratchet.py reviewers {args.cp}` and "
            "record a review first.")
    open_findings = _adv_open_findings(ctx, args.cp, rnd, cps)
    by_key = {_finding_key(f): f for f in open_findings}
    if not by_key:
        die(f"{args.cp}'s latest recorded round has no open findings to triage.")
    dest = _adv_round_dir(ctx, args.cp, rnd["round"])
    triage = _read_triage(dest)
    changed = []
    for item in args.decisions:
        ref, sep, rest = item.partition("=")
        ref = ref.strip()
        if not sep:
            die(f"{item!r}: use <id>=fix:<reason> or <id>=rebut:<reason>. Nothing was recorded.")
        # Resolved the same way accept-finding resolves a ref (`_resolve_finding_ref`): a bare id unique among this
        # round's open findings works directly; a bare id two reviewers both used is refused as ambiguous, naming
        # them, instead of silently failing the "not open" check below (by_key is keyed by the qualified
        # 'reviewer/id', so a bare ref never matched it on its own).
        f, err = _resolve_finding_ref(ref, open_findings)
        if err:
            die(f"{err} Nothing was recorded.")
        if f is None:
            die(f"{ref} is not an open finding of {args.cp}'s latest recorded round (open now: "
                f"{', '.join(sorted(by_key)) or '(none)'}). Nothing was recorded for it.")
        key = _finding_key(f)
        decision, _, reason = rest.partition(":")
        decision = decision.strip().lower()
        reason = reason.strip()
        if decision in TRIAGE_REDIRECT:
            die(f"{ref}={decision} is refused: the orchestrator can never {decision} a finding through triage. "
                f"That needs the user's own reply, through `ratchet.py ask accept-finding {args.cp} {ref}` and "
                "their `accept: <reason>`. Nothing was recorded.")
        if decision not in TRIAGE_DECISIONS:
            die(f"{ref}={decision or '(none)'}: triage decisions are 'fix' or 'rebut' only. Nothing was recorded.")
        if not reason:
            die(f"{ref}={decision} needs a one-line reason after ':' (e.g. {ref}={decision}:why this is, or is "
                "not, a real problem for the objective's users). Nothing was recorded for it.")
        triage[key] = {"decision": decision, "reason": reason, "at": now()}
        changed.append(key)
    write_json(dest / "triage.json", triage)
    fix_list = [dict(by_key[k], triage_reason=v["reason"]) for k, v in triage.items()
                if v.get("decision") == "fix" and k in by_key]
    write_json(dest / "fix-list.json", fix_list)
    ctx.log(st, "triage_recorded", cp=args.cp, round=rnd["round"], ids=changed)
    ctx.save_state(st)
    ok(f"Recorded triage for {', '.join(changed)} ({args.cp} round {rnd['round']}).")


def cmd_adv_record(args):
    ctx = Ctx(find_root())
    st = ctx.state()
    cps = _cur(ctx, st, args.cp)
    _expect_step(cps, ["adversarial", "complete"], args.cp)
    cfg = ctx.config()
    cp = cp_by_id(ctx.plan(), args.cp)
    g = cps["gates"]["adversarial"]
    fp = fingerprint(ctx.root)
    rnd = cps.get("adv_round")
    if not rnd or rnd.get("recorded"):
        die(f"No open review round for {args.cp}. Start one with `ratchet.py reviewers {args.cp}` — it lists who must "
            "review and gives each reviewer the round nonce to stamp.")
    if rnd["fingerprint"] != fp["id"]:
        die(f"The code changed after review round {rnd['round']} was opened. Run `ratchet.py reviewers {args.cp}` "
            "again so every reviewer looks at the current code.")
    required = rnd["reviewers"]
    subs = rnd.get("substitutions") or []
    reviews = {}
    round_dir = _review_round_dir(ctx, args.cp, "adv", rnd["round"])
    # Lane H CP6: a scoped round (fix_round or small_fix) was shown only the diff since the last round actually
    # reviewed, so both the minimum review time and the files_reviewed sanity check below are judged against
    # THAT scope, never the whole checkpoint's base_tree -- the reviewer could never list a file it was never
    # shown. Every other round (first, narrowed, full) is unaffected: scope is None and both checks fall back to
    # the pre-CP6 behavior exactly.
    scope = _scope_for_round(ctx, args.cp, rnd, cps, fp["id"])
    min_seconds = (_scoped_min_review_seconds(ctx, cfg, scope["since_tree"], fp["id"], scope["changed_files"])
                  if scope is not None else cfg.get("min_review_seconds", 20))
    scoped_changed = set(scope["changed_files"]) if scope is not None else None
    for rp in args.reviews:
        rpath, raw, fst = _read_round_review(
            ctx, rp, round_dir, f"Adversarial reviews for round {rnd['round']}",
            f" `ratchet.py reviewers {args.cp}` gives each reviewer this folder and the round nonce to stamp.")
        r = _parse_review(raw, rp)
        rid = r.get("reviewer") or Path(rp).stem
        if r.get("fingerprint") != fp["id"]:
            die(f"{rp} ({rid}) is not stamped with the current fingerprint {fp['id'][:10]}. Re-run that reviewer.")
        if r.get("round_nonce") != rnd["nonce"]:
            die(f"{rp} ({rid}) does not carry this round's nonce. Reviews must come from reviewers launched for "
                f"round {rnd['round']} (see `ratchet.py reviewers {args.cp}`).")
        if r.get("checkpoint") not in (None, args.cp):
            die(f"{rp} is a review of {r.get('checkpoint')}, not {args.cp}.")
        origin = check_review_origin(ctx, cfg, st, args.cp, rnd["round"], rp, rpath, r, rid, rnd["nonce"])
        r = clean_review_text(r)  # its signature is checked: from here on it only feeds records and messages
        age = fst.st_mtime - _iso(rnd["opened_at"])
        if age < min_seconds:
            die(f"{rp} ({rid}) was written {age:.0f}s after the round opened — too fast to be a real review. "
                "Launch the reviewer and let it do the work.")
        if r.get("omitted_files"):  # whatever its findings, the risk or the round: it never saw the whole fix
            die(f"{rp} ({rid}) is a review of a fix that was too large to show it whole: it never saw "
                f"{', '.join(sorted(r['omitted_files'])[:8])}. Such a review never counts, even with findings. "
                "Re-review the fix with a reviewer that can read all of it.")
        if not r.get("findings"):
            seen = set(r.get("files_reviewed") or [])
            changed = scoped_changed if scoped_changed is not None else \
                (set(changed_files(ctx.root, {"kind": "git-tree", "id": cps.get("base_tree")}, fp))
                 if cps.get("base_tree") else set())
            if not seen or (changed and not (seen & changed)):
                die(f"{rp} ({rid}) approves without listing the changed files it reviewed (files_reviewed). "
                    f"Changed in this checkpoint: {', '.join(sorted(changed)[:8]) or '(none recorded)'}.")
        reviews[rid] = (rpath, r, raw, fst, origin)
    missing = [i for i in required if i not in reviews]
    if missing:
        die(f"{args.cp} (risk={cp.get('risk', 'normal')}) needs reviews from {required}; missing {missing}. "
            f"Run `ratchet.py reviewers {args.cp}` to see how to launch each one.")
    key_file = review_key_file(ctx.root, st, args.cp, "adv", rnd["round"])  # dropped once the round is saved
    rnd["recorded"] = now()
    dest = ctx.evidence(args.cp) / "adversarial" / f"round-{rnd['round']:02d}"
    dest.mkdir(parents=True, exist_ok=True)
    all_findings, verdicts = [], []
    unconfirmed = []
    for rid in required:
        rp, r, raw, fst, (origin, why) = reviews[rid]
        spec = _roster_spec(cfg, rid) or {}
        findings = _dedupe_finding_ids(r.get("findings", []) or [])
        all_findings += [dict(f, reviewer=rid) for f in findings]
        how = {"script-signed": "signed by external_review.py",
               "confirmed": "written by the ratchet-adversary sub-agent, confirmed by the guard hook"}.get(origin, UNCONFIRMED)
        verdicts.append({"reviewer": rid, "vendor": spec.get("vendor"), "claimed": r.get("verdict"),
                         "findings": len(findings), "origin": how})
        if origin == "unconfirmed":
            verdicts[-1]["unconfirmed_because"] = why
            unconfirmed.append(f"{rid}: {UNCONFIRMED} ({why})")
        if rp.parent != dest.resolve():
            _write_review_evidence(dest / f"{rid}.json", raw, fst)
    need = len(required)
    if unconfirmed:
        g["unconfirmed"] = unconfirmed
    else:
        g.pop("unconfirmed", None)
    record_kinds(st, args.cp, rnd["round"], all_findings, ctx.root, fp["id"], cp.get("risk", "normal"))
    covered = enforced_kinds(cfg)
    escaped = sorted({finding_kind(f) for f in all_findings if finding_kind(f) in covered
                      and str(f.get("severity", "")).strip().lower() not in MINOR_SEVERITIES})
    for kind in escaped:
        _auto_strengthen(ctx, st, cfg, kind, args.cp)
    # CP3: a finding that names a done-means line blocks at any severity, round or scope, but only for a plan
    # approved since that rule exists (`_dm_findings_block`); an older plan keeps the rules it was approved under
    # and gets a plain note (DM_LEGACY_FINDINGS_NOTE) instead of a surprise block.
    dm_blocks = _dm_findings_block(ctx, st, ctx.plan())
    dm_named = [f for f in all_findings if names_done_means(f)]
    legacy_note = f"Note: {DM_LEGACY_FINDINGS_NOTE}." if dm_named and not dm_blocks else ""
    covered_minor = [dict(f, deferred_because=f"an automatic check already covers '{finding_kind(f)}'")
                     for f in all_findings if finding_kind(f) in covered
                     and str(f.get("severity", "")).strip().lower() in MINOR_SEVERITIES
                     and not (dm_blocks and names_done_means(f))]
    # only MINOR findings of a covered kind step aside (their check runs at the behavior gate); blocker and major
    # findings always block, whatever label they carry, and so does a minor one that names a done-means line
    # (CP3, `names_done_means`): a check covering its kind does not prove the line is met
    all_findings = [f for f in all_findings if not any(f is c or (f.get("id"), f.get("reviewer")) == (c.get("id"), c.get("reviewer"))
                                                       for c in covered_minor)]
    # Realistic-use bar: a blocker, major or unknown-severity finding that does not say who is hurt and how
    # (user_impact) never blocks, at any round and any risk. It is recorded for the final review instead. This
    # is narrower than the existing minor-severity rules below: minor findings keep following those, whether or
    # not they carry a user_impact. A finding that names a done-means line (CP3, `names_done_means`) is exempt:
    # the named line stands in for user_impact, since the plan's objective already says who is hurt when that
    # line is not met.
    no_impact = [f for f in all_findings
                 if str(f.get("severity", "")).strip().lower() not in MINOR_SEVERITIES
                 and not str(f.get("user_impact") or "").strip()
                 and not (dm_blocks and names_done_means(f))]
    if no_impact:
        all_findings = [f for f in all_findings if not any(f is n for n in no_impact)]
    no_impact_deferred = [dict(f, deferred_because="no user impact stated") for f in no_impact]
    changed_since = _changed_since_last_round(ctx, cfg, g, fp["id"])
    raw_count = len(all_findings)
    all_findings, deferred = split_findings(cfg, cp.get("risk", "normal"), all_findings, changed_since, ctx.root,
                                             round_no=rnd["round"], dm_blocks=dm_blocks)
    deferred = covered_minor + no_impact_deferred + deferred
    if deferred:
        write_json(dest / "deferred-findings.json", deferred)
        keep = [x for x in cps.get("deferred") or [] if x.get("round") != rnd["round"]]
        cps["deferred"] = keep + [dict(x, round=rnd["round"]) for x in deferred]
    approved = not all_findings
    # "round" is stamped on the entry itself (not left to list position) so it is found by identity later
    # (cmd_accept_finding marks it accepted): a round `reviewers` opens and then replaces before recording (the
    # fingerprint changed) advances rnd['round'] without adding an entry here, so position alone drifts from it.
    g["rounds"] = g.get("rounds", []) + [{"round": rnd["round"], "at": now(), "fingerprint": fp["id"], "verdicts": verdicts,
                                          "findings": len(all_findings), "deferred": len(deferred),
                                          "raw_findings": raw_count, "substitutions": subs,
                                          "blocking_files": sorted({_norm_path(f.get("file") or f.get("path") or f.get("location"), ctx.root)
                                                                    for f in all_findings} - {""}),
                                          "reviewers": [{"id": rr["id"], "vendor": rr.get("vendor"),
                                                         "model": rr.get("model"), "slot": rr.get("slot")}
                                                        for rr in rnd.get("resolved") or []]}]
    if _is_fix_after_block(rnd):  # CP5: what this fix round was and who reviewed it, blocked or approved
        _record_fix_round(cps, rnd, approved)
    if not approved:
        g["status"] = "failed"
        ci_note = _checkin_trigger(ctx, st, args.cp, cps, g, rnd, all_findings)
        if g["attempts"] >= _adv_round_cap(cfg, cps):
            _set_blocked(st, f"{args.cp}: adversarial review still has {len(all_findings)} finding(s) after "
                             f"{g['attempts']} rounds — needs a human/director decision.")
        ctx.log(st, "adversarial_changes_requested", cp=args.cp, findings=len(all_findings))
        ctx.save_state(st)
        drop_review_key(key_file)  # this round is recorded and saved: its secret goes
        build_viewer(ctx)
        write_json(dest / "open-findings.json", all_findings)
        _announce_repeats(ctx, st)
        if legacy_note:
            print(legacy_note)
        open_named = sum(1 for f in all_findings if names_done_means(f))
        die(f"Gate 3 (adversarial) NOT approved: {len(all_findings)} blocking finding(s)"
            + (f", {open_named} of them naming a done-means line (these block at any severity)" if open_named and dm_blocks else "")
            + (f" ({len(deferred)} minor ones recorded for later)" if deferred else "") + " → "
            f"{(dest / 'open-findings.json').relative_to(ctx.root)}. Decide fix or rebut for each (`ratchet.py "
            f"triage {args.cp} <id>=fix:\"reason\"` or `=rebut:\"reason\"`), then spawn ratchet-fixer with "
            "fix-list.json, re-run behavior (and UI if visible code changed), then re-run the adversaries."
            + (f" {ci_note}" if ci_note else ""), 2)
    g.update(status="passed", fingerprint=fp, passed_at=now(), evidence=str(dest.relative_to(ctx.root)))
    if rnd.get("small_fix"):  # CP3: approved as a one-reviewer small-fix round -- named for the commit/status
        if not _is_fix_after_block(rnd):  # CP5's post-block fix round has its own record (`fix_rounds`)
            cps["small_fix_review"] = {"round": rnd["round"], "reviewer": (rnd.get("reviewers") or [None])[0]}
    else:
        # CP3: anchor for `_is_small_fix_round` -- only a FULL round's approval moves this, so a run of small
        # fixes keeps measuring against the same baseline and their sizes add up.
        cps["last_full_review_fingerprint"] = fp
        # CP5: this full round's own approval supersedes every lighter-review note recorded before it.
        _clear_lighter_review_records(cps)
    cps["step"] = _earliest_open_step(cps)
    ctx.log(st, "adversarial_approved", cp=args.cp, round=g["attempts"])
    ctx.save_state(st)
    drop_review_key(key_file)
    build_viewer(ctx)
    note = (f" {len(deferred)} minor finding(s) were recorded for later instead of blocking (`ratchet.py deferred`)."
            if deferred else "")
    _announce_repeats(ctx, st)
    if legacy_note:
        print(legacy_note)
    ok(f"Gate 3 (adversarial) APPROVED by all {need} reviewer(s) for {args.cp}.{note} Next: ratchet.py complete {args.cp}")


def _adv_round_dir(ctx, cp_id: str, round_no: int) -> Path:
    return ctx.evidence(cp_id) / "adversarial" / f"round-{round_no:02d}"


def _read_findings_file(p: Path) -> list:
    """Reads an evidence findings file (a JSON list) through `_read_record`, the one reader: a damaged one is
    treated as empty, never a crash, like every other Ratchet record."""
    data, why = _read_record(p, kind=list, missing=[])
    if why is not None:
        _note_unreadable(p, why, "Ratchet treats a damaged findings file as empty")
        return []
    return data if isinstance(data, list) else []


def _adv_open_findings(ctx, cp_id: str, rnd, cps=None) -> list:
    """The findings still open (blocking) in a checkpoint's recorded adversarial round, or [] when the round never
    blocked (or never recorded). State, not the evidence file, is the one authoritative record of what was
    accepted (standards #12): open-findings.json is only a mirror. `adv-record` writes it once, when it records a
    round (never rewriting an EARLIER round's own file), and `accept-finding` rewrites its own round's file as its
    own last write; a process killed between the state commit and that last write can leave this one round's file
    stale (still listing an id state already marked accepted), possibly for good if that was the final
    acceptance — the gate has already passed, so nothing ever revisits that file again. When `cps` (the
    checkpoint's own state dict) is given, any finding already
    recorded accepted in cps['deferred'] for this round is filtered out here regardless of what the stale file
    still says, so every caller -- ask accept-finding, accept-finding's own checks -- sees the same, correct,
    state-derived answer. Pass cps whenever it is available; omit it only for callers that merely mirror the
    file's raw contents."""
    if not rnd or not rnd.get("recorded"):
        return []
    raw = _read_findings_file(_adv_round_dir(ctx, cp_id, rnd["round"]) / "open-findings.json")
    if cps is None:
        return raw
    accepted_keys = {_finding_key(f) for f in _round_deferred(cps, rnd["round"]) if f.get("accepted")}
    return [f for f in raw if _finding_key(f) not in accepted_keys]


# --------------------------------------------------------------------------- scoped diff & timing (lane H CP6)
# A fix round, and a small fix opened after an approval, show their one reviewer only what changed since the
# last round actually reviewed -- never the whole checkpoint diff -- plus, for a fix round, the specific
# findings still open in the round it answers (full details: id, reviewer, severity, location, description,
# suggested fix, and any rebuttal reason already recorded for it). A first round, a narrowed round (the old
# convergence fallback), and any full round (including a fix over small_edit_lines after an approval, and every
# high-risk step's own full round) are never scoped this way: they keep the whole step diff exactly as CP5 left
# it. `prev_round_tree` (already set to the last round adv-record actually recorded -- see cmd_reviewers) is
# reused as-is for the scope boundary, so a second fix round in a row scopes to just that second fix, and a round
# that replaces one adv-record never recorded (never reviewed, or reviewed but refused) scopes to everything
# since the last round adv-record recorded, not just the latest edit.

def _scope_for_round(ctx: "Ctx", cp_id: str, rnd: dict | None, cps: dict, fp_id: str) -> dict | None:
    """The CP6 scope for `rnd`, or None when it keeps the whole step diff. Returns {"since_tree", "changed_files",
    "findings"}: `since_tree` is the tree id the diff is scoped since (the last round actually reviewed, or the
    checkpoint's own base_tree if that is somehow unset); `changed_files` is sorted; `findings` is the full
    finding dicts still open in the round a fix round answers (each with "rebuttal_reason" added when that
    round's own triage rebutted it), or [] for a small fix after a clean approval -- nothing to re-check."""
    if not rnd or not rnd.get("small_fix"):  # both kinds of fix round are small_fix rounds; `kind` tells them apart
        return None
    since_tree = rnd.get("prev_round_tree") or cps.get("base_tree")
    if not since_tree:
        return None
    changed = sorted(changed_files(ctx.root, {"kind": "git-tree", "id": since_tree},
                                   {"kind": "git-tree", "id": fp_id}))
    findings = []
    ff = rnd.get("fix_round") if _is_fix_after_block(rnd) else None  # the pick: {"round", "reviewer", "slot"}
    if ff and ff.get("round"):
        raw = _adv_open_findings(ctx, cp_id, {"round": ff["round"], "recorded": True}, cps)
        triage = _read_triage(_adv_round_dir(ctx, cp_id, ff["round"]))
        for f in raw:
            entry = dict(f)
            dec = triage.get(_finding_key(f)) or {}
            if dec.get("decision") == "rebut":
                entry["rebuttal_reason"] = dec.get("reason")
            findings.append(entry)
    return {"since_tree": since_tree, "changed_files": changed, "findings": findings}


def _render_finding_line(f: dict) -> str:
    """One plain line naming a finding's id, reviewer, severity, location, description, suggested fix and any
    rebuttal reason -- used both in a host sub-agent's launch instructions and in an external reviewer's prompt,
    so the two ways a fix round's reviewer is told about an open finding always say the same things about it."""
    loc = str(f.get("file") or f.get("path") or f.get("location") or "(no file)")
    if f.get("line"):
        loc = f"{loc}:{f['line']}"
    line = (f"finding id={f.get('id', '?')} reviewer={f.get('reviewer', '?')} severity={f.get('severity', '?')} "
            f"location={loc} description={json.dumps(str(f.get('description') or ''))} "
            f"fix={json.dumps(str(f.get('fix') or ''))}")
    if f.get("rebuttal_reason"):
        line += f" rebuttal={json.dumps(str(f['rebuttal_reason']))}"
    return line


_FIX_ROUND_MIN_REVIEW_FLOOR_SEC = 1       # never below this once ANY code changed, so a 0-second review always fails
_FIX_ROUND_MIN_REVIEW_SEC_PER_LINE = 0.05  # 20 changed lines/second: a ~400-line fix reaches a 20s minimum


def _scoped_min_review_seconds(ctx: "Ctx", cfg: dict, since_tree: str, fp_id: str, files: list[str]) -> int | float:
    """The minimum age a scoped round's (lane H CP6: fix_round or small_fix) review must have, scaled down from
    the configured `min_review_seconds` by how much actually changed in its own scope -- a tiny fix is never
    held to the same wait as a full review, while a fix large enough to approach the configured minimum still
    gets it in full. Never exceeds the configured minimum, whatever it is (a config of 5, or even 0, seconds is
    still the hard ceiling). A change of unknown size (a binary file) gets the full configured minimum, never a
    shortcut -- there is nothing here to measure it against."""
    configured = cfg.get("min_review_seconds", 20)
    lines, unknown = _code_size(ctx, since_tree, fp_id, files) if files else (0, [])
    if unknown or lines is None:
        return configured  # size can't be measured (a binary file): no shortcut, the full configured minimum applies
    if lines <= 0:
        return min(configured, 0)  # nothing to measure; never above the configured ceiling either
    scaled = max(_FIX_ROUND_MIN_REVIEW_FLOOR_SEC, round(lines * _FIX_ROUND_MIN_REVIEW_SEC_PER_LINE))
    return min(configured, scaled)


def _open_blocking_lenses(ctx, cfg, cp_id: str, rnd, cps=None, dm_blocks: bool = True) -> set:
    """Lenses with a still-open BLOCKER or MAJOR finding, or a still-open finding of any severity that names a
    done-means line (CP3, `names_done_means`; only while `dm_blocks`, i.e. `_dm_findings_block` for this plan),
    in a checkpoint's latest recorded adversarial round. `reviewers` narrows the next round to just these
    lenses; a lens whose only open finding was a plain minor (naming no line) doesn't keep it in the loop, and
    a lens that approved isn't in here at all."""
    out = set()
    for f in _adv_open_findings(ctx, cp_id, rnd, cps):
        if str(f.get("severity", "")).strip().lower() in MINOR_SEVERITIES and not (dm_blocks and names_done_means(f)):
            continue
        spec = _roster_spec(cfg, f.get("reviewer")) if f.get("reviewer") else None
        if spec and spec.get("lens"):
            out.add(spec["lens"])
    return out


def _round_deferred(cps, round_no) -> list:
    """The step's deferred findings belonging to one round (cps['deferred'] entries are tagged with their round)."""
    return [f for f in cps.get("deferred") or [] if f.get("round") == round_no]


def _learnings_text(ctx) -> str:
    p = ctx.ratchet / "learnings.md"
    try:
        return p.read_text()
    except OSError:
        return ""


MINOR_SEVERITIES = {"minor", "nit", "nitpick", "trivial", "info", "suggestion", "low", "style"}


def _dm_line_number(x) -> bool:
    """`x` is a line number as a reviewer writes one: an int (not a bool), a float with an integer value (3.0),
    or a string with a run of digits in it ("3", "3, 4", "line 3", "#3"). A string with no digit ("none",
    "N/A", "") is not one."""
    if isinstance(x, bool):
        return False
    if isinstance(x, int) or (isinstance(x, float) and x.is_integer()):
        return True
    return isinstance(x, str) and re.search(r"\d", x) is not None


def _dm_line_values(x) -> list[int]:
    """The line numbers one `done_means` value carries (`_dm_line_number`): [3] for 3, "3" or 3.0; every run of
    digits for a string such as "3, 4" or "line 3"; [] for a value that names none."""
    if not _dm_line_number(x):
        return []
    if isinstance(x, (int, float)):
        return [int(x)]
    return [int(m) for m in re.findall(r"\d+", x)]


def names_done_means(f) -> bool:
    """True when a finding names the done-means line(s) it contradicts in its optional `done_means` field (CP3,
    schemas.md section 7): a line number (`_dm_line_number`: an int, a float with an integer value, or a string
    with a run of digits in it such as "3", "3, 4" or "line 3"; never a bool) or a list holding at least one. A
    value with no number in it (`false`, `"none"`, `"N/A"`, `[null]`, `[""]`, `[]`, `null`) names nothing, so a
    reviewer that fills the field with a "no line" value does not turn every plain finding into a blocking one,
    while a value that does carry a number never slips through as a plain minor. A number is taken exactly as the reviewer wrote it: a bare number, or one that is not a real
    line of the plan's objective (0, past the end), names a line too and the finding is shown as written; the
    engine never judges the number here, so a reviewer's miscount still blocks rather than slipping through.
    `_finding_dm_lines` is the other reader of the field: the final review's done-means table keeps only real
    line numbers and ignores the rest, while this blocking rule does not. `cmd_adv_record` (covered-kind and
    no-user_impact set-asides), `split_findings` (risk bar, converge round, later-round scope),
    `_open_blocking_lenses` and `_docs_only_review_skip` all read it, each only while `_dm_findings_block` says
    the rule applies to this plan: such a finding blocks at any severity and any round, and its lens is asked
    again next round. The display readers (`_checkin_brief`'s per-finding `done_means`, `_dm_named_text` for
    `ask accept-finding`'s question and the check-in brief, and `adv-record`'s open count) read it whether or
    not `_dm_findings_block` applies: the line a finding names is always shown."""
    dm = f.get("done_means") if isinstance(f, dict) else None
    vals = dm if isinstance(dm, list) else [dm]
    return any(_dm_line_number(x) for x in vals)


DM_LEGACY_FINDINGS_NOTE = ("this plan was approved before a finding naming a done-means line always blocked; "
                           "such findings follow the older severity, round and scope rules here")

# The done-means rules a plan was approved under. `approve-plan` writes this version into the approval snapshot
# (`st["approved"]["done_means_rules"]`, schemas.md section 7) once, at approval; `plan-extend`, `approve-changes`
# and `merged` keep the value the snapshot already has and never add one to a run approved without it. A snapshot
# with no such key was approved before this change (older rules, a plain note); approve-plan also withholds it from a
# plan whose done-means lines no case links at all (one submitted before plan-submit required a link per line, so an
# older plan however it was approved). Two readers: `_approved_after_dm`
# (does the rule apply?) and `_approval_snapshot_keeping_dm` (the carry-forward plan-extend and approve-changes use).
DM_RULES_VERSION = 1


def _approved_after_dm(st) -> bool:
    """True when the run's plan was approved since the done-means rules exist: the approval snapshot carries the
    `done_means_rules` marker `approve-plan` writes (DM_RULES_VERSION). False for a run with no approval yet or
    one approved before this change (the snapshot has no marker; nothing infers the era from today's links).
    The marker's one reader that judges it; `_dm_findings_block` (CP3), `_finish_blockers` / `_finish_legacy_note`
    (CP4), `_ask_accept_line` (CP5: an older run gets a plain note, never an accept question) and cmd_plan_extend's
    append-only check on the approved lines share it. Its other reader,
    `_approval_snapshot_keeping_dm`, only copies it forward."""
    return bool((st.get("approved") or {}).get("done_means_rules"))


def _approval_snapshot_keeping_dm(ctx, st, keep_objective: bool = True) -> dict:
    """A fresh `approval_snapshot` that keeps the `done_means_rules` marker the run's current snapshot already
    carries, and adds none when it has none: the one carry-forward `plan-extend` and `approve-changes` share, so a
    run approved under the done-means rules stays under them and a run approved before them never gains the
    marker (`merged` does not rewrite the snapshot, so it needs no carry). With `keep_objective` (the default,
    `approve-changes`) the approved objective's done_means lines are carried forward too, whatever checkpoints.json
    says now: confirming some other plan change can never slip in an edited done-means line (CP4). `plan-extend`
    passes keep_objective=False after checking the approved lines are an unchanged prefix of the new ones, so the
    lines feedback appended become approved."""
    old = st.get("approved") or {}
    dm_rules = old.get("done_means_rules")
    snap = approval_snapshot(ctx, st)
    if dm_rules:
        snap["done_means_rules"] = dm_rules
    old_obj = old.get("objective")
    if keep_objective and isinstance(old_obj, dict) and isinstance(old_obj.get("done_means"), list):
        new_obj = snap.get("objective") if isinstance(snap.get("objective"), dict) else {}
        snap["objective"] = {**old_obj, **new_obj, "done_means": list(old_obj["done_means"])}
    return snap


def _stamp_legacy_round_baselines(st, plan):
    """Gives every checkpoint's open, unrecorded, pin-less adversarial round (one that predates reviewers-pin
    tracking: no `reviewers_pin` key) its one-time migration stamp before an approval snapshot is written that
    would otherwise bake the checkpoint's live `reviewers` pin in as that round's first baseline with no chance
    to reopen. Must run, over EVERY checkpoint, before any of the three commands that call `approval_snapshot`
    (`approve-plan`, `plan-extend`, `approve-changes`) write `st["approved"]`: that snapshot records every
    checkpoint's live `reviewers` pin unconditionally, so whichever of the three is first to run after an
    upgrade is the one that would otherwise silently bake in a pre-upgrade run's checkpoints with no stamp
    (CP4 round 5, omp-glm-correctness/X1 -- found only guarded in approve-changes, the same gap at the other
    two). `cmd_reviewers` itself also calls this, unconditionally, before it decides whether to replace the open
    round (CP4 round 6, host-alt-correctness/A1): the common upgraded shape is a checkpoint whose pin was already
    edited and approved entirely under the old engine, so `approved.cps`'s hash already matches the live
    checkpoint and `approve-changes` finds nothing pending ("Nothing has changed since approval.") -- the only
    command left that always runs, with no "something changed" precondition, is `reviewers`, so it must be able
    to stamp and reopen the round on its own, on this same call, rather than wait on an approval event that would
    never come. approve-plan never sees a checkpoint with an `adv_round` at all (no round has opened before the
    plan is first approved), so the loop is a no-op there. plan-extend's existing checkpoints DO already carry an
    `adv_round` -- they are the ones `complete` already closed out -- but every one of those rounds is
    `recorded`, so it is the loop's own `not rnd.get("recorded")` guard that skips them, not the absence of a
    round; it stays a no-op there only for that reason, and would stop being one if a recorded round's
    `recorded` flag were ever cleared.

    With a prior `approved.reviewers` baseline already on record for a checkpoint, this stamps the OLD baseline
    only when it genuinely differs from the live pin (the precise, zero-false-reopen path). With no such
    baseline at all (a pre-upgrade run's first encounter with this code), there is no fixed guess at the prior
    pin that is correct in every direction (a narrowed round's own reviewers can look "unchanged" under
    containment even when the pin actually grew or swapped -- CP4 round-3 codex-standards/X3's counter-example
    -- and pin removal is undetectable no matter what is guessed, since a never-pinned round's own reviewers are
    structurally identical to a pinned-then-removed round's), so the safe default fires whenever the live pin is
    non-empty: treat the prior pin as unknown and stamp None unconditionally, so the very next `reviewers` call
    re-evaluates the round against the live pin. Replacing an unrecorded round this way is free only while its
    folder holds no review file yet (CP2-T07's own scope); "unrecorded" does not by itself guarantee
    "unreviewed" (a reviewer's output file can land on disk before `adv-record` ever runs or refuses it, for
    example a round `adv-record` already refused for `omitted_files`): a round whose folder already holds a
    review file costs an attempt to replace, the same as any other reviewed round, legacy or not.

    Returns True when it actually stamped at least one checkpoint's round (so a caller with no other reason to
    save state, such as `cmd_reviewers` on a call that ends up re-showing the SAME round, still persists the
    stamp instead of leaving it computed only in memory)."""
    old_reviewers = (st.get("approved") or {}).get("reviewers")
    stamped = False
    for cid, cp_state in st["checkpoints"].items():
        rnd = cp_state.get("adv_round")
        if rnd and not rnd.get("recorded") and "reviewers_pin" not in rnd:
            live_cp = next((c for c in plan["checkpoints"] if c.get("id") == cid), {})
            if isinstance(old_reviewers, dict) and cid in old_reviewers:
                old_pin = old_reviewers[cid]
                if sorted(old_pin or []) != sorted(live_cp.get("reviewers") or []):
                    rnd["reviewers_pin"] = old_pin
                    stamped = True
            elif live_cp.get("reviewers"):
                rnd["reviewers_pin"] = None
                stamped = True
    return stamped


def _dm_findings_block(ctx, st, plan) -> bool:
    """CP3: whether a finding that names a done-means line (`names_done_means`) blocks at any severity, round and
    scope for this run. True for a plan with done-means lines whose approval snapshot carries the
    `done_means_rules` marker (`_approved_after_dm`), i.e. one approved since that rule exists. False for a plan
    approved without the marker (before this change), and for one with no objective or no done_means lines at
    all (nothing to contradict): line-naming findings then follow exactly the older rules (`blocking_severities`,
    `converge_after_round`, `scope_later_rounds`, covered kinds, `user_impact`), with no crash, and `adv-record`
    prints DM_LEGACY_FINDINGS_NOTE instead of blocking. Never inferred from today's "proves" links: an older
    plan with every line linked stays older, and a newer plan whose approved test-plan change dropped a link
    stays newer. Read by `cmd_adv_record`, `review_rules`, `cmd_reviewers` (for `_open_blocking_lenses`) and
    `_docs_only_review_skip`."""
    obj = plan.get("objective") if isinstance(plan, dict) else None
    dm = obj.get("done_means") if isinstance(obj, dict) else None
    if not isinstance(dm, list) or not dm:
        return False
    return _approved_after_dm(st)


def _dm_named_text(dm_lines: list, f) -> str:
    """' [contradicts done-means line 3: "<line text>"]' for a finding that names a line (number and the line's
    own text from `dm_lines`, the plan's objective.done_means; a number that is not a real line is shown as
    written, with no text), '' for a finding that names none. Shown wherever a decision is made on the finding:
    `ask accept-finding`'s question and the check-in brief."""
    if not names_done_means(f):
        return ""
    dm = f.get("done_means")
    parts = []
    for n in [n for x in (dm if isinstance(dm, list) else [dm]) for n in _dm_line_values(x)]:
        text = dm_lines[n - 1] if 1 <= n <= len(dm_lines) and isinstance(dm_lines[n - 1], str) else None
        parts.append(f"{n}: \"{text}\"" if text is not None else f"{n} (not a line of this plan, shown as written)")
    return f" [contradicts done-means line{'s' if len(parts) > 1 else ''} {'; '.join(parts)}]"


def _norm_path(p, root=None) -> str:
    """A finding's file as a repo-relative path: './', backslashes, absolute paths inside the repo, a drive letter,
    and line suffixes (':12', ':12:3', '#L12', ' (line 12)') are all handled."""
    p = str(p or "").strip().replace("\\", "/")
    p = re.sub(r"\s*\((?:line|lines|l\.)\s*[\d\-– ,]+\)\s*$", "", p, flags=re.I)
    p = re.sub(r"#L\d+(-L?\d+)?$", "", p)
    p = re.sub(r":\d+(:\d+)?(-\d+)?$", "", p)
    if root is not None:
        r = str(Path(root).resolve()).replace("\\", "/").rstrip("/") + "/"
        low = p.lower()
        if re.match(r"^[a-z]:/", low) or p.startswith("/"):
            idx = low.find(r.lower()) if r.lower() in low else -1
            if idx >= 0:
                p = p[idx + len(r):]
            else:
                tail = r.rstrip("/").rsplit("/", 1)[-1] + "/"  # the repo's own folder name, e.g. C:/work/app/src/a.js
                if ("/" + tail.lower()) in low:
                    p = p[low.rfind("/" + tail.lower()) + len(tail) + 1:]
    while p.startswith("./"):
        p = p[2:]
    return p


def _in_scope(path: str, scope: set) -> bool:
    if not path:
        return True  # no file given: can't tell where it is, so it counts as in scope (it blocks)
    if path in scope:
        return True
    base = path.rsplit("/", 1)[-1]
    if "/" not in path:  # a bare file name: in scope if any scoped file has that name
        return any(x.rsplit("/", 1)[-1] == base for x in scope)
    return False


def split_findings(cfg, risk: str, findings: list, changed_since: set | None, root=None,
                    round_no: int | None = None, dm_blocks: bool = True) -> tuple[list, list]:
    """(blocking, deferred). Severities not known to be minor always block (a reviewer can't escape the bar by
    inventing a severity name). `changed_since` is the round's scope: files changed since the previous round plus
    files that had a blocking finding last round (a finding the fixer ignored can't be waved through). `round_no`
    is this round's own number; from round `converge_after_round` + 1 (config, default 2, so round 3 by default)
    a minor finding never blocks any more, whatever its scope — blocker and major findings keep blocking at every
    round. While `dm_blocks` (the caller's `_dm_findings_block` answer for this plan; False for a plan approved
    before CP3), a finding that names a done-means line (CP3, `names_done_means`) is never deferred here,
    whatever its severity, round or scope: a line of the objective not met in normal use blocks until it is
    fixed or the user accepts it. Findings that name no line follow exactly the rules above."""
    bar = (cfg.get("blocking_severities") or {}).get(risk, "all")
    bar_l = [str(x).strip().lower() for x in (bar or [])] if bar != "all" else None
    converge_after = int(cfg.get("converge_after_round", 2))
    blocking, deferred = [], []
    for f in findings:
        sev = str(f.get("severity", "")).strip().lower()
        minor = sev in MINOR_SEVERITIES and not (dm_blocks and names_done_means(f))
        where = _norm_path(f.get("file") or f.get("path") or f.get("location"), root)
        if minor and bar_l is not None and sev not in bar_l:
            deferred.append(dict(f, deferred_because=f"{risk}-risk step: only {' and '.join(bar)} findings block"))
        elif minor and round_no is not None and round_no > converge_after:
            deferred.append(dict(f, deferred_because=f"round {round_no}: minor findings stop blocking from round "
                                                       f"{converge_after + 1} on (config converge_after_round)"))
        elif minor and changed_since is not None and not _in_scope(where, changed_since):
            deferred.append(dict(f, deferred_because="later round: not in code changed since the previous round"))
        else:
            blocking.append(f)
    return blocking, deferred


def _changed_since_last_round(ctx, cfg, g, fp_id) -> set | None:
    """The round's scope: files changed since the previous round, plus every file that had a blocking finding in the
    previous round (so a finding the fixer didn't fix is still judged in full)."""
    if not cfg.get("scope_later_rounds", True) or not g.get("rounds"):
        return None
    last = g["rounds"][-1]
    prev = last.get("fingerprint")
    if not prev:
        return None
    scope = {_norm_path(x) for x in changed_files(ctx.root, {"kind": "git-tree", "id": prev}, {"kind": "git-tree", "id": fp_id})}
    scope |= set(last.get("blocking_files") or [])
    return scope


def norm_kind(k) -> str | None:
    k = re.sub(r"[^a-z0-9]+", "-", str(k or "").strip().lower()).strip("-")[:60]
    return k or None


def finding_kind(f) -> str | None:
    """The reviewer's own label for the TYPE of mistake. Only an explicit `kind` counts: a cited rule is too broad to
    stand for one checkable mistake."""
    return norm_kind(f.get("kind"))


def enforced_kinds(cfg) -> set:
    return {norm_kind(c.get("kind")) for c in (cfg.get("checks") or []) if isinstance(c, dict) and c.get("kind")}


def record_kinds(st, cp_id, round_no, findings, root=None, tree=None, risk=None):
    seen = st.setdefault("finding_kinds", {})
    for f in findings:
        k = finding_kind(f)
        if k:
            seen.setdefault(k, []).append({"cp": cp_id, "round": round_no,
                                           "file": _norm_path(f.get("file") or f.get("path") or f.get("location"), root),
                                           "what": str(f.get("description", ""))[:160], "tree": tree, "risk": risk,
                                           "severity": str(f.get("severity", "")).strip().lower()})


def kind_is_high_risk(st, kind) -> bool:
    """Found on a high-risk checkpoint, or ever rated a blocker."""
    return any(h.get("risk") == "high" or h.get("severity") == "blocker"
               for h in (st.get("finding_kinds") or {}).get(kind, []))


def _next_tree(st, h) -> str | None:
    """The code version after the one this finding was raised on, for the same checkpoint."""
    g = (((st.get("checkpoints") or {}).get(h["cp"]) or {}).get("gates") or {}).get("adversarial") or {}
    fps = [r.get("fingerprint") for r in g.get("rounds") or []]
    if h.get("tree") in fps:
        later = [x for x in fps[fps.index(h["tree"]) + 1:] if x and x != h["tree"]]
        if later:
            return later[0]
    done = (g.get("fingerprint") or {}).get("id")
    return done if done and done != h.get("tree") else None


def _acted_on(ctx, st, h) -> bool:
    """Was this finding acted on, i.e. did the flagged file change in the next version of the code? A finding the
    fixer disproved (no change) isn't evidence that the mistake was really there."""
    nxt = _next_tree(st, h)
    if not nxt:
        return False
    changed = changed_files(ctx.root, {"kind": "git-tree", "id": h["tree"]}, {"kind": "git-tree", "id": nxt})
    if not h.get("file"):
        return bool(changed)
    return _norm_path(h["file"]) in {_norm_path(x) for x in changed}


def kind_occurrences(st, kind, limit=None, ctx=None) -> list[dict]:
    """The real places a kind was found, newest first, one per reviewed code version. Only blocking findings
    (blocker/major) count, and, when `ctx` is given, only ones that were acted on (the flagged file changed next)."""
    out, trees = [], set()
    for h in reversed((st.get("finding_kinds") or {}).get(kind, [])):
        if h.get("severity") in MINOR_SEVERITIES or not h.get("tree") or h["tree"] in trees:
            continue
        if ctx is not None and not _acted_on(ctx, st, h):
            continue
        trees.add(h["tree"])
        out.append(h)
        if limit and len(out) >= limit:
            break
    return out


def kind_places(st, kind) -> set:
    """Distinct places a kind was found: (checkpoint, file). The same unfixed finding raised again in a later round is
    one place, not a repeat."""
    return {(h["cp"], h.get("file") or "") for h in (st.get("finding_kinds") or {}).get(kind, [])}


def repeat_candidates(ctx, st, cfg=None) -> list[dict]:
    """Kinds of mistake found in two or more places that no automatic check covers yet and that the user hasn't been
    asked about. Offer each one as a guardrail as soon as it shows up."""
    cfg = cfg or ctx.config()
    done = enforced_kinds(cfg) | {norm_kind(k) for k in st.get("guardrails_offered") or []}
    out = []
    for k, hits in (st.get("finding_kinds") or {}).items():
        places = kind_places(st, k)
        if len(places) >= 2 and k not in done:
            out.append({"kind": k, "times": len(places), "checkpoints": sorted({h["cp"] for h in hits}),
                        "example": hits[-1]["what"]})
    return sorted(out, key=lambda x: -x["times"])


def cmd_occurrences(args):
    """The real code where reviewers found a kind of mistake, as they saw it (for a variant writer)."""
    ctx = Ctx(find_root())
    st = ctx.state()
    kind = norm_kind(args.kind)
    occ = [h for h in kind_occurrences(st, kind, limit=5) if h.get("file")]
    if not occ:
        die(f"No recorded occurrences of '{kind}' with code to show.")
    for h in occ:
        r = subprocess.run(["git", "show", f"{h['tree']}:{h['file']}"], cwd=ctx.root, capture_output=True, text=True)
        body = r.stdout if r.returncode == 0 else "(file not in that version)"
        lines = body.splitlines()
        print(f"=== {h['cp']} round {h['round']}: {h['file']} — {h['what']}")
        print("\n".join(lines[:200]) + ("\n… (cut)" if len(lines) > 200 else ""))


def cmd_repeats(args):
    ctx = Ctx(find_root())
    st = ctx.state()
    if args.offered:
        k = norm_kind(args.offered)
        offered = st.setdefault("guardrails_offered", [])
        if k and k not in offered:
            offered.append(k)
        ctx.save_state(st)
        ok(f"'{k}' marked as offered; it won't be suggested again.")
        return
    rows = repeat_candidates(ctx, st)
    if args.json:
        print(json.dumps(rows, indent=2))
        return
    if not rows:
        print("No repeated kind of finding waiting for a decision.")
        return
    for r in rows:
        print(f"- {r['kind']}: found {r['times']} times ({', '.join(r['checkpoints'])}); e.g. {r['example']}")


def review_rules(ctx, cfg, cp, g, rnd, fp_id, cps=None) -> tuple[set | None, list[str], dict | None]:
    """What the reviewers of this round are told about the severity bar, the round's focus and (lane H CP6) its
    scope. CP3: when the plan's done-means lines are under the always-block rule (`_dm_findings_block`), every
    rule that sets a minor finding aside carries the exception (a finding naming a done-means line always
    blocks), and one rule says so outright; for a plan approved before that rule the older wording stands, no
    exception is claimed, and one rule says plainly that this plan predates the rule (the qualifier the reviewer
    role brief, agents/ratchet-adversary.md and the external prompt point at). `cps` (the checkpoint's own state
    dict) is needed to compute the CP6 scope; omit it only for a caller that only wants the pre-CP6 fields
    (focus, rules) and is not itself a fix_round/small_fix round, since `_scope_for_round` needs it to find
    `base_tree`."""
    scope = _scope_for_round(ctx, cp["id"], rnd, cps or {}, fp_id) if cps is not None else None
    # `focus_files` is kept as compatibility metadata on every round > 1, scoped or not (older callers, and
    # `status`/the viewer, read it regardless of scope) -- but the "look hardest" RULE TEXT below is given only
    # on an unscoped round; a scoped round gets the CP6 scope text instead, never both.
    focus = _changed_since_last_round(ctx, cfg, g, fp_id) if rnd["round"] > 1 else None
    bar = (cfg.get("blocking_severities") or {}).get(cp.get("risk", "normal"), "all")
    dm_blocks = _dm_findings_block(ctx, ctx.state(), ctx.plan() or {})
    dm_x = " (unless one names a done-means line in done_means, which always blocks)" if dm_blocks else ""
    rules = []
    if bar != "all":
        rules.append(f"This is a {cp.get('risk', 'normal')}-risk step: only {' and '.join(bar)} findings block; "
                     f"report minor ones too, they are recorded for later{dm_x}.")
    kinds = sorted(enforced_kinds(cfg))
    if kinds:
        rules.append("These kinds of mistake are already caught by automatic checks that run with the tests: "
                     + ", ".join(kinds) + ". Still report a blocker or major problem of these kinds (it still blocks); "
                     f"minor ones of these kinds are noted, not fixed{dm_x}.")
    if scope is None and focus is not None:
        rules.append("Round " + str(rnd["round"]) + ": look hardest at the code changed since the last round ("
                     + (", ".join(sorted(focus)[:20]) or "nothing changed") + "). Re-raise any earlier finding that "
                     "still isn't fixed, wherever it is. Beyond that, a new minor problem outside those files is "
                     f"recorded, not fixed{dm_x}; blocker and major problems count anywhere.")
    elif scope is not None:
        since_short = scope["since_tree"][:10]
        if scope["findings"]:
            rules.append(f"This is a fix round: you are shown ONLY what changed since the last round actually "
                         f"reviewed ({since_short}), never the whole checkpoint, plus the open finding(s) "
                         "below from the round you are fixing. Judge only this diff and these findings: re-check "
                         "whether each one is actually fixed, re-raising any that isn't. A new problem outside "
                         "this diff is out of scope for this round.")
            for f in scope["findings"]:
                rules.append(_render_finding_line(f))
        else:
            rules.append(f"This is a small fix made after an approval: you are shown ONLY the lines that changed "
                         f"since the last round actually reviewed ({since_short}), never the whole "
                         "checkpoint. There are no open findings to re-check for this round; judge only this diff.")
    if dm_blocks:
        rules.append("A finding that names a done-means line it contradicts (done_means, the numbers in front of "
                     "the objective's Done means lines above) always blocks, at any severity, round or scope, and "
                     "needs no separate user_impact; raise it wherever you find it, and name a line only when that "
                     "line is not met in normal use.")
    elif (ctx.plan() or {}).get("objective"):
        rules.append(f"This plan was approved before a finding naming a done-means line always blocked: "
                     f"{DM_LEGACY_FINDINGS_NOTE}. Still fill in done_means when a line is not met in normal use.")
    if rnd["round"] > 1 and scope is None:
        # A scoped round's own rebuttal info (if any) is already attached to each finding in `scope["findings"]`
        # above (its "rebuttal_reason"), so this generic, round-number-based block would only ever duplicate it;
        # it stays only for a narrowed or full round, exactly as before CP6.
        prev_triage = _read_triage(_adv_round_dir(ctx, cp["id"], rnd["round"] - 1))
        for ref, dec in prev_triage.items():
            if dec.get("decision") == "rebut":
                rules.append(f"Rebuttal from the last round on {ref}: {dec.get('reason', '')} — withdraw this "
                             "finding if the rebuttal holds up, or re-raise it with a stronger user_impact if it "
                             "doesn't.")
    return focus, rules, scope


def _announce_repeats(ctx, st):
    director = approval_mode(ctx) == "director"
    for r in repeat_candidates(ctx, st):
        if director:
            print(f"REPEAT: reviewers have now found '{r['kind']}' in {r['times']} places. This lane is "
                  f"director-enrolled: tell the director, who can approve a guardrail with "
                  f"`director-sign guardrail --kind {r['kind']}`; then run ratchet.py repeats --offered {r['kind']}.")
            continue
        print(f"REPEAT: reviewers have now found '{r['kind']}' {r['times']} times (e.g. {r['example']}). Offer the user "
              f"a guardrail now: ratchet.py ask choice --options A,B,C --guardrail \"A={r['kind']}\" "
              "(see 'When the same mistake repeats' in the orchestrator skill).")


def cmd_guardrail(args):
    """Insert a guardrail step right after the current checkpoint: an automatic check (lint rule, architecture test,
    type rule...) that makes a repeated mistake fail fast. Needs the user's pick of the guardrail option (or, in a
    director lane, a director token). The step proves the check red/green and goes through every gate; when it
    completes, the check joins config `checks` and runs with the tests from then on."""
    ctx = Ctx(find_root())
    st = ctx.state()
    if st["phase"] not in ("building", "blocked"):
        die(f"A guardrail can only be added while building (phase {st['phase']}).")
    kind = norm_kind(args.kind)
    token = getattr(args, "director_token", None)
    allow = st.get("choice_allow") or {}
    cfg = ctx.config()
    if not kind or len(kind_places(st, kind)) < 2:
        die(f"'{kind}' hasn't been found in two places by the reviewers, so it isn't a repeated mistake. Guardrails are "
            "only for kinds of finding that keep coming back (`ratchet.py repeats`).")
    if kind in enforced_kinds(cfg):
        die(f"An automatic check for '{kind}' already exists. Changing or replacing it is a rule change the user must "
            "confirm (show them the change, then `ratchet.py ask approve-changes`).")
    if "{target}" not in args.check_command:
        die("--check-command must contain {target}, where Ratchet puts what to check: the project's code "
            "(--target, default .) or the bad example (--bad-example). E.g. --check-command \"npx eslint {target}\".")
    bad = (ctx.root / args.bad_example).resolve()
    try:
        bad.relative_to(ctx.root.resolve())
    except ValueError:
        die("--bad-example must be inside the project (a test fixture).")
    if token:
        _require_approval(ctx, st, f"guardrail:{kind}", token)
    elif allow.get("guardrail") != kind or allow.get("cp") != st.get("current"):
        die(f"The user hasn't picked a guardrail option for '{kind}' at this step. Offer it first: ratchet.py ask "
            f"choice --options A,B,C --guardrail \"A={kind}\", then ratchet.py choice after they reply.")
    high = kind_is_high_risk(st, kind)
    gr = {"kind": kind, "check_command": args.check_command, "target": args.target,
          "bad_example": args.bad_example, "why": args.why or "", "test_command": args.test_command,
          "test_files": args.test_file or [], "high_risk": high,
          "variants_dir": (args.variants_dir or f"tests/fixtures/guardrails/{kind}/variants") if high else None}
    gid, title = _insert_guardrail_step(ctx, st, gr, f"Guardrail: {args.title}",
                                        f"Add an automatic check that fails fast on '{kind}', a mistake reviewers kept finding.")
    cur = st.get("current")
    if not token:
        allow["guardrail"] = None
        if not allow.get("files") and not allow.get("unblock"):
            st.pop("choice_allow", None)
    ctx.log(st, "guardrail_added", cp=gid, kind=kind)
    ctx.save_state(st)
    build_viewer(ctx)
    ok(f"Added {gid} ({title}) right after {cur}. It is built next, through every gate; its check then runs with the "
       "tests at every later step.")


GUARDRAIL_NOTES = ("Prefer a check that understands the code over one that matches text: an import-graph rule "
                   "(dependency-cruiser, import-linter, ArchUnit), a syntax-aware lint rule (ESLint, Semgrep, Ruff) or a "
                   "type rule, using the project's existing tools first; you may add such a tool as a dev dependency. "
                   "Keep bad examples in test fixtures, never in shipped code. Ratchet will also run the check on the "
                   "real code where the mistake was found, so it must catch those, not only your fixture.")


def _insert_guardrail_step(ctx, st, gr: dict, title: str, summary: str, extra_case: dict | None = None):
    """Put a guardrail (or strengthen) step right after the current checkpoint, with its own red/green test plan.
    The user's pick (or the automatic strengthening rule) is the approval for this one step."""
    plan = ctx.plan()
    ids = [int(c["id"][2:]) for c in plan["checkpoints"] if re.fullmatch(r"CP\d+", c["id"])]
    gid = f"CP{max(ids) + 1}"
    title = " ".join(title.split()[:8])
    kind = gr["kind"]
    done_when = [f"The check fails on a deliberately bad example of {kind} ({gr['bad_example']})",
                 "The check fails on the real code where reviewers found the mistake",
                 f"The check passes on the project's current code ({gr['target']})",
                 "The check runs with the tests at every later step"]
    if gr.get("high_risk"):
        done_when.insert(2, f"It catches every disguised bad variant in {gr['variants_dir']}/bad and none of the "
                            f"look-alike good code in {gr['variants_dir']}/good")
    entry = {"id": gid, "title": title, "summary": summary, "done_when": done_when,
             "gates": {"behavior": True, "ui": False, "adversarial": True},
             "risk": "high" if gr.get("high_risk") else "normal",
             "ui_skip_reason": "an automatic code check, nothing visible changes",
             "tests": {"files": gr.get("test_files") or [], "command": gr["test_command"]},
             "guardrail": gr, "notes": GUARDRAIL_NOTES}
    cur = st.get("current")
    order = [c["id"] for c in plan["checkpoints"]]
    at = order.index(cur) + 1 if cur in order else len(order)
    plan["checkpoints"].insert(at, entry)
    errs = validate_plan(plan)
    if errs:
        die("Guardrail step invalid:\n  - " + "\n  - ".join(errs))
    write_json(ctx.run_dir() / "checkpoints.json", plan)
    cases = [{"id": f"{gid}-T01", "layer": "code", "title": f"the check catches {kind}",
              "given": f"the fixture {gr['bad_example']}, which contains the mistake ({gr.get('why') or kind})",
              "when": f"the check runs on it ({gr['check_command'].replace('{target}', gr['bad_example'])})",
              "then": "it fails and names the problem"},
             {"id": f"{gid}-T02", "layer": "code", "title": "the check passes on the current code",
              "given": "the project as it is now",
              "when": f"the check runs ({gr['check_command'].replace('{target}', gr['target'])})", "then": "it passes"}]
    if extra_case:
        cases.append(dict(extra_case, id=f"{gid}-T03", layer="code"))
    write_json(ctx.run_dir() / "tests" / f"{gid}.json", {"checkpoint": gid, "cases": cases})
    st["checkpoints"][gid] = new_cp_state(entry)
    st["plan_hash"] = _plan_hash(plan, ctx)
    snap = st.get("approved") or {}
    snap.setdefault("cps", {})[gid] = _sha(entry)
    snap.setdefault("tests", {})[gid] = _sha(test_plan(ctx, gid))
    return gid, title


def _auto_strengthen(ctx, st, cfg, kind, cp_id):
    """A reviewer found a blocker/major mistake of a kind an automatic check covers: the check let it through. Add a
    step that strengthens the check (no question: the user asked for this to happen automatically)."""
    plan = ctx.plan()
    pending = [c for c in plan["checkpoints"] if (c.get("guardrail") or {}).get("kind") == kind
               and st["checkpoints"].get(c["id"], {}).get("status") != "done"]
    chk = next((c for c in cfg.get("checks") or [] if isinstance(c, dict) and norm_kind(c.get("kind")) == kind), {})
    occ = kind_occurrences(st, kind, limit=1)
    where = (occ[0].get("file") or occ[0]["cp"]) if occ else "a later step"
    ctx.log(st, "check_missed", kind=kind, cp=cp_id, file=where)
    if pending:
        print(f"STRENGTHEN: the check for '{kind}' missed a case in {where}; step {pending[0]['id']} will cover it too.")
        return
    if not chk.get("template") or not chk.get("test_command"):
        print(f"STRENGTHEN: the check for '{kind}' missed a case in {where}, but it was added without the details "
              "needed to strengthen it automatically. Tell the user in one line.")
        return
    gr = {"kind": kind, "check_command": chk["template"], "target": chk.get("target") or ".",
          "bad_example": chk.get("bad_example") or "", "why": chk.get("why") or "", "strengthen": True,
          "test_command": chk["test_command"], "test_files": chk.get("test_files") or [],
          "high_risk": bool(chk.get("high_risk")), "variants_dir": chk.get("variants_dir")}
    gid, _ = _insert_guardrail_step(
        ctx, st, gr, f"Strengthen check: {kind}",
        f"The automatic check for '{kind}' let a case through in {where}. Make it catch that case too, without "
        "losing any it already catches.",
        {"title": f"the check now catches the case it missed in {where}",
         "given": f"a fixture with the code reviewers flagged in {where}", "when": "the check runs on it",
         "then": "it fails and names the problem"})
    ctx.log(st, "guardrail_strengthen_added", cp=gid, kind=kind)
    print(f"STRENGTHEN: the automatic check for '{kind}' missed a case in {where}. Step {gid} was added right after "
          f"{st.get('current')} to strengthen it (no question needed). Tell the user in one line.")


def _materialize(ctx, tree: str, overlay: list[str]) -> Path | None:
    """A throwaway copy of an earlier reviewed version of the code, with this step's own files (the check, its config,
    fixtures) laid over it and the project's installed dependencies linked in."""
    import io
    import tarfile
    tmp = Path(tempfile.mkdtemp(prefix="ratchet-occurrence-"))
    r = subprocess.run(["git", "archive", "--format=tar", tree], cwd=ctx.root, capture_output=True)
    if r.returncode != 0:
        shutil.rmtree(tmp, ignore_errors=True)
        return None
    try:
        with tarfile.open(fileobj=io.BytesIO(r.stdout)) as tf:
            for m in tf.getmembers():
                name = m.name
                if name.startswith("/") or ".." in Path(name).parts:
                    continue  # never write outside the throwaway folder
                if m.issym() or m.islnk():
                    continue  # links are skipped: a link could point anywhere
                if not (m.isfile() or m.isdir()):
                    continue
                tf.extract(m, tmp, set_attrs=False)
    except (tarfile.TarError, OSError):
        shutil.rmtree(tmp, ignore_errors=True)
        return None
    for rel in overlay:
        src, dst = ctx.root / rel, tmp / rel
        if src.is_file():
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src, dst)
        elif dst.exists() and dst.is_file():
            dst.unlink()
    for dep in DEP_DIRS:
        if (ctx.root / dep).exists() and not (tmp / dep).exists():
            (tmp / dep).symlink_to(ctx.root / dep)
    return tmp


DEP_DIRS = ("node_modules", ".venv", "venv", "vendor", ".bundle", "target")


def _deps_snapshot(root: Path) -> dict:
    """A cheap picture of the installed-dependency folders (names, sizes and times of their top two levels), to
    notice a check that writes into them through the links."""
    snap = {}
    for dep in DEP_DIRS:
        d = root / dep
        if not d.is_dir():
            continue
        for p in [d] + [x for x in d.iterdir()][:5000]:
            try:
                st_ = p.stat()
                snap[str(p.relative_to(root))] = (st_.st_mtime_ns, st_.st_size)
            except OSError:
                continue
    return snap


def _run_check_in(cwd: Path, command: str, log: Path, timeout: int) -> tuple[int, str]:
    try:
        r = subprocess.run(command, shell=True, cwd=cwd, capture_output=True, text=True, timeout=timeout,
                           env=dict(os.environ, CI="1", FORCE_COLOR="0"))
        code, out = r.returncode, (r.stdout or "") + "\n" + (r.stderr or "")
    except subprocess.TimeoutExpired:
        code, out = 124, f"TIMEOUT after {timeout}s"
    log.parent.mkdir(parents=True, exist_ok=True)
    log.write_text(f"$ (in {cwd}) {command}\n# exit={code}\n\n{out}")
    return code, out


def verify_guardrail(ctx, st, cp, cps, fp, cfg) -> list[str]:
    """Ratchet runs the real check itself. It must fail on the bad example, on the real code where the mistake was
    found, and (high-risk kinds) on every disguised bad variant; and pass on today's code and on look-alike good code.
    No run may change a project file."""
    import shlex
    gr = cp["guardrail"]
    ev = ctx.evidence(cp["id"]) / "guardrail"
    t = cfg["test_timeout_sec"]
    probs = []
    bad = ctx.root / (gr.get("bad_example") or "")
    if not gr.get("bad_example") or not bad.exists() or (bad.is_dir() and not any(bad.rglob("*"))):
        return [f"its bad example ({gr.get('bad_example')}) is missing or empty"]
    code, _, _ = _run_cmd(ctx, _check_cmd(gr, gr["bad_example"]), ev / "bad-example.log", t)
    if code == 0:
        probs.append(f"it passes on the bad example ({gr['bad_example']}), so it doesn't catch the mistake")
    code, _, _ = _run_cmd(ctx, _check_cmd(gr, gr.get("target") or "."), ev / "today.log", t)
    if code != 0:
        probs.append("it fails on the current code; it must pass on today's code")
    if gr.get("high_risk"):
        vd = ctx.root / (gr.get("variants_dir") or "")
        bads = sorted(p for p in (vd / "bad").rglob("*") if p.is_file()) if (vd / "bad").is_dir() else []
        goods = sorted(p for p in (vd / "good").rglob("*") if p.is_file()) if (vd / "good").is_dir() else []
        if len(bads) < 3 or len(goods) < 2:
            probs.append(f"a high-risk kind needs at least 3 disguised bad variants and 2 look-alike good examples in "
                         f"{gr.get('variants_dir')}/bad and /good (found {len(bads)} and {len(goods)})")
        for i, v in enumerate(bads):
            rel = str(v.relative_to(ctx.root))
            if _run_cmd(ctx, _check_cmd(gr, rel), ev / f"variant-bad-{i:02d}.log", t)[0] == 0:
                probs.append(f"it misses the disguised bad variant {rel}")
        for i, v in enumerate(goods):
            rel = str(v.relative_to(ctx.root))
            if _run_cmd(ctx, _check_cmd(gr, rel), ev / f"variant-good-{i:02d}.log", t)[0] != 0:
                probs.append(f"it wrongly flags the look-alike good code {rel}")
    if _is_git(ctx.root):
        overlay = changed_files(ctx.root, {"kind": "git-tree", "id": cps.get("base_tree")}, fp) if cps.get("base_tree") else []
        cases = proof_cases(ctx, st, gr)
        cps["guardrail_cases"] = cases
        deps_before = _deps_snapshot(ctx.root)
        for i, h in enumerate(cases):
            where = f"{h['cp']} round {h['round']}" + (f", {h['file']}" if h.get("file") else "")
            tmp = _materialize(ctx, h["tree"], overlay)
            if tmp is None:
                probs.append(f"Ratchet couldn't rebuild the past code it must be proven on ({where}); it won't skip a "
                             "case, so this needs a look")
                continue
            try:
                cmd = gr["check_command"].replace("{target}", shlex.quote(gr.get("target") or "."))
                code, _ = _run_check_in(tmp, cmd, ev / f"real-occurrence-{i:02d}.log", t)
                if code == 0:
                    probs.append(f"it passes on the real code where reviewers found the mistake ({where}), so it would "
                                 "not have caught it")
            finally:
                shutil.rmtree(tmp, ignore_errors=True)
        if _deps_snapshot(ctx.root) != deps_before:
            probs.append("running it on past code changed the project's installed dependencies; a check must only "
                         "read the code")
    if fingerprint(ctx.root)["id"] != fp["id"]:
        probs.append("running it changed files in the project; a check must only read the code")
    return probs


def proof_cases(ctx, st, gr) -> list[dict]:
    """Every past case the check must catch: all cases an earlier version of this check was proven on (kept on the
    check, so strengthening can never drop one), plus every acted-on blocking finding of the kind."""
    cfg = ctx.config()
    old = next((c for c in cfg.get("checks") or [] if isinstance(c, dict) and norm_kind(c.get("kind")) == gr["kind"]), {})
    cases, trees = [], set()
    for h in list(old.get("cases") or []) + kind_occurrences(st, gr["kind"], ctx=ctx):
        if h.get("tree") and h["tree"] not in trees:
            trees.add(h["tree"])
            cases.append({k: h.get(k) for k in ("cp", "round", "file", "tree")})
    return cases


def _check_cmd(gr: dict, target: str) -> str:
    import shlex
    return gr["check_command"].replace("{target}", shlex.quote(target))


# --------------------------------------------------------------------------- shortcut tables
# A guard-like part of the code (one the table names in "watches") has a fixed table of shortcut commands in
# tests/shortcuts/<name>.json: {"name", "watches": [files], "runner": "<command>", "rows": [{"id", "command",
# "expect": "refused"|"allowed"}]}. `ratchet.py shortcuts` runs each table whose watched files this run changed,
# once per row against the code the run started from and once against the current code, and says which rows got
# worse, stayed open, got fixed or errored. It only shows the result: nothing here ever blocks a finish.

SHORTCUT_DIR = "tests/shortcuts"
SHORTCUT_TIMEOUT_SEC = 60
SC_ZERO = {"worse": 0, "still_open": 0, "fixed": 0, "held": 0, "errored": 0, "unknown": 0}
SC_HEADINGS = (("worse", "got worse"), ("still_open", "still open"), ("fixed", "fixed"), ("errored", "errored"),
               ("unknown", "unknown"))


_SC_PATH_RE = re.compile(r"[A-Za-z0-9_.@+-]+(/[A-Za-z0-9_.@+-]+)*")


def _sc_canonical(p: str) -> bool:
    """A plain project-relative path: no leading ./ or /, no .. or . segment, no empty segment, no glob, no
    backslash, no space (one trailing / is allowed for a folder by the caller)."""
    return bool(_SC_PATH_RE.fullmatch(p)) and not any(seg in (".", "..") for seg in p.split("/"))


def _sc_runner_argv(runner: str):
    """(argument list, None) for an allowed runner, else (None, why). Exactly one shape is allowed:
    `python3 <path to a file under tests/shortcuts/>`. It is run as an argument list, never through a shell."""
    parts = runner.split(" ")
    path = parts[-1]
    if len(parts) == 1 and path.startswith(SHORTCUT_DIR + "/"):
        return None, (f"its runner {runner!r} is not allowed: write `python3 {path}` (the copy the rows run in has "
                      "no exec bit, so a bare file cannot run)")
    if len(parts) != 2 or parts[0] != "python3":
        return None, (f"its runner {runner!r} is not allowed: use `python3 {SHORTCUT_DIR}/<file>` (no other "
                      "interpreter, no arguments, no shell)")
    if not path.startswith(SHORTCUT_DIR + "/") or not _sc_canonical(path):
        return None, (f"its runner {runner!r} is not allowed: the file must be a plain relative path under "
                      f"{SHORTCUT_DIR}/ (no .., absolute path, glob or shell syntax)")
    return [parts[0], "./" + path], None


def _sc_watch_why(w: str):
    """None for a canonical watch entry, else why it is refused. Entries are never normalised."""
    if not _sc_canonical(w[:-1] if w.endswith("/") else w):
        return (f"its watch {w!r} is not a canonical project path (no leading ./ or /, no .., no glob, no "
                "backslash, no empty part)")
    return None


def _sc_watch_missing(ctx, tree, watches):
    """The watches that exist in neither the starting tree nor the current folder."""
    out = []
    for w in watches:
        p = w.rstrip("/")
        if (ctx.root / p).exists():
            continue
        if tree and subprocess.run(["git", "cat-file", "-e", f"{tree}:{p}"], cwd=ctx.root,
                                   capture_output=True).returncode == 0:
            continue
        out.append(w)
    return out


def _sc_parse(text: str):
    """(table definition, None) for a readable table file, else (None, why it is unreadable)."""
    raw = text if isinstance(text, bytes) else text.encode("utf-8", "replace")
    d, bad = _read_record(Path("shortcut-table.json"), kind=None, data=raw)  # a people-written file, parsed from text
    if bad:
        return None, f"unreadable: not valid JSON ({bad.split(': ', 1)[-1][:80]})"
    if not isinstance(d, dict):
        return None, "unreadable: the file is not a JSON object"
    rows, watches, runner = d.get("rows"), d.get("watches"), d.get("runner")
    if not isinstance(runner, str) or not runner.strip():
        return None, "unreadable: it has no \"runner\" command"
    _argv, why = _sc_runner_argv(runner)
    if why:
        return None, f"unreadable: {why}"
    if not isinstance(watches, list) or not watches or not all(isinstance(w, str) and w for w in watches):
        return None, "unreadable: \"watches\" must list at least one file"
    for w in watches:
        why = _sc_watch_why(w)
        if why:
            return None, f"unreadable: {why}"
    if not isinstance(rows, list) or not rows or not all(
            isinstance(r, dict) and isinstance(r.get("id"), str) and isinstance(r.get("command"), str) for r in rows):
        return None, "unreadable: \"rows\" must be a list of {id, command, expect}"
    for r in rows:
        if r.get("expect") not in ("allowed", "refused") or not isinstance(r.get("expect"), str):
            return None, (f"unreadable: row {r['id']!r} has expect {json.dumps(r.get('expect'))[:40]}; "
                          "expect must be the string \"allowed\" or \"refused\"")
    return {"watches": watches, "runner": runner, "rows": rows}, None


def _sc_start_tree(st):
    """The tree this run recorded at its start (run_start.tree, else its first step's starting tree), or None. It
    is where the starting copy of every table (rows, expectations, runner) is read, whatever the comparison
    version turns out to be."""
    rs = st.get("run_start") if isinstance(st.get("run_start"), dict) else {}
    first = next(iter((st.get("checkpoints") or {}).values()), None) or {}
    return rs.get("tree") or first.get("base_tree") or None


def _sc_merge_tree(ctx, a, b):
    """(exit code, tree id or "", set of conflicted paths) of `git merge-tree --write-tree a b`. A conflicted merge
    still writes a tree (the conflicted files hold markers), so only its conflicted paths are unusable."""
    r = subprocess.run(["git", "merge-tree", "--write-tree", "--name-only", "--no-messages", "-z", a, b],
                       cwd=ctx.root, capture_output=True)
    parts = r.stdout.decode("utf-8", "surrogateescape").split("\0") if r.returncode in (0, 1) else []
    tree = parts[0].strip() if parts else ""
    paths = set(x for x in parts[1:] if x) if r.returncode == 1 else set()
    return r.returncode, tree, paths


def _sc_old_version(ctx, st):
    """(tree id of the code this run started from, None, paths that conflicted laying main on the start, paths that
    conflicted redoing the lane/main merge), or (None, a plain note, set(), set()) when it
    cannot be worked out. run_start.tree (written once at plan approval; `merged` never rewrites it) while main was
    never merged in. After a merge, main's side laid onto the run's starting commit (`git merge-tree --write-tree
    <run_start.head> M^2` for the latest merged_main commit M), so main's own changes are not counted as this run's.
    A conflict there, or in redoing the lane/main merge itself (a hand-made resolution mixes the run's lines with
    main's), does not make the whole version unknown: the tree is still built and the conflicted paths are returned
    (the two causes apart, so a note names the merge that conflicted),
    so only a table that watches one of them is unknown. A run approved before run_start existed falls back to its
    first step's starting tree, unless main was merged in."""
    merges = [e for e in (st.get("history") or []) if e.get("event") == "merged_main" and e.get("commit")]
    rs = st.get("run_start") if isinstance(st.get("run_start"), dict) else {}
    if not merges:
        tree = _sc_start_tree(st)
        if not tree:
            return None, "The starting version cannot be worked out: this run recorded no starting tree.", set(), set()
        return tree, None, set(), set()
    if not rs.get("head"):
        return None, ("The starting version cannot be worked out: this run began before starting versions were "
                      "recorded and main was merged into it."), set(), set()
    m = merges[-1]["commit"]
    side = m + "^2"
    if subprocess.run(["git", "rev-parse", "-q", "--verify", side], cwd=ctx.root, capture_output=True).returncode != 0:
        side = m  # a fast-forward: the commit is main's tip itself
    code, tree, conflicts = _sc_merge_tree(ctx, rs["head"], side)
    conflicts2 = set()
    if side != m:  # the same merge as git made it: a hand-made resolution shows up as a conflict here
        code2, _t2, conflicts2 = _sc_merge_tree(ctx, m + "^1", side)
        if code2 not in (0, 1):
            return None, "The starting version cannot be worked out: git could not redo the merge of main.", set(), set()
    if code not in (0, 1) or not tree:
        return None, "The starting version cannot be worked out: git could not build main's side onto the start.", set(), set()
    return tree, None, conflicts, conflicts2


def _sc_old_files(ctx, tree: str) -> dict:
    """{table name: file text} for every tests/shortcuts/*.json in the starting tree."""
    r = subprocess.run(["git", "ls-tree", "-r", "--name-only", "-z", tree, "--", SHORTCUT_DIR], cwd=ctx.root,
                       capture_output=True)
    out = {}
    for path in r.stdout.decode("utf-8", "surrogateescape").split("\0") if r.returncode == 0 else []:
        rest = path[len(SHORTCUT_DIR) + 1:] if path.startswith(SHORTCUT_DIR + "/") else ""
        if rest.endswith(".json") and "/" not in rest:
            s = subprocess.run(["git", "show", f"{tree}:{path}"], cwd=ctx.root, capture_output=True)
            if s.returncode == 0:
                out[rest[:-5]] = s.stdout.decode("utf-8", "replace")
    return out


def _sc_run_row(runner: str, cwd: Path, root: Path, command: str):
    """(ALLOWED | REFUSED | error, note): run in `cwd` (the version's own folder, the same as `root`); the runner's whole trimmed output must be exactly ALLOWED or REFUSED and
    its exit code 0; anything else (a crash, a timeout, a runner that cannot start) is an error, never refused."""
    argv, why = _sc_runner_argv(runner)
    if why:
        return "error", why
    try:
        r = subprocess.run(argv, cwd=cwd, capture_output=True, text=True, errors="replace",
                           timeout=SHORTCUT_TIMEOUT_SEC,
                           env=dict(os.environ, RATCHET_SHORTCUT_ROOT=str(root), RATCHET_SHORTCUT_COMMAND=command))
    except subprocess.TimeoutExpired:
        return "error", f"the runner timed out after {SHORTCUT_TIMEOUT_SEC}s"
    except (OSError, ValueError) as e:  # ValueError: a NUL byte in the runner or the row's command
        return "error", f"the runner could not be started ({e})"
    out = (r.stdout or "").strip()
    if r.returncode == 0 and out in ("ALLOWED", "REFUSED"):
        return out, None
    if r.returncode == 0:
        return "error", f"the runner printed {out[:60]!r}, not exactly ALLOWED or REFUSED"
    lines = [x for x in ((r.stderr or "") + "\n" + (r.stdout or "")).splitlines() if x.strip()]
    err = (r.stderr or "").strip().splitlines()
    return "error", f"the runner exited {r.returncode}: {(err[-1] if err else (lines[-1] if lines else 'no output'))[:160]}"


def _sc_verdict(expect, old, new):
    want = {"refused": "REFUSED", "allowed": "ALLOWED"}.get(expect)
    if want is None or old == "error" or new == "error":
        return "errored"
    if old == "unknown":
        return "unknown"
    if old == want:
        return "held" if new == want else "worse"
    return "fixed" if new == want else "still_open"


def _sc_table(ctx, name, old_def, cur_def, cur_why, old_root, new_root, old_note):
    """One table's result: its rows run on the starting code and the current code. The rows, expectations and
    runner of a table that existed at the start always come from its starting copy (a row cannot be dropped or
    flipped by editing or deleting the file); rows added since run too and are marked new_row."""
    notes = []
    if old_note:
        notes.append(old_note)
    base = old_def or cur_def
    rows = [dict(r, new_row=False) for r in (old_def["rows"] if old_def else [])]
    if old_def:
        cur_rows = {r["id"]: r for r in (cur_def["rows"] if cur_def else [])}
        if cur_def is None and cur_why is None:
            notes.append(f"The table file for {name} was deleted since the run started; its starting copy was used.")
        elif cur_def is None:
            notes.append(f"The current {name} table file is unreadable ({cur_why}); its starting copy was used.")
        else:
            gone = [r["id"] for r in rows if r["id"] not in cur_rows]
            changed = [r["id"] for r in rows if r["id"] in cur_rows and (
                cur_rows[r["id"]].get("command") != r["command"] or cur_rows[r["id"]].get("expect") != r.get("expect"))]
            if gone:
                notes.append(f"Row(s) {', '.join(gone)} no longer in the {name} table file (removed since the run "
                             "started); they still run from the starting copy.")
            if changed:
                notes.append(f"Row(s) {', '.join(changed)} changed since the run started; the starting version "
                             "of each was used.")
            have = {r["id"] for r in rows}
            rows += [dict(r, new_row=True) for r in cur_def["rows"] if r["id"] not in have]
    elif cur_def:
        rows = [dict(r, new_row=old_root is not None) for r in cur_def["rows"]]
    out_rows, counts = [], dict(SC_ZERO)
    for r in rows:
        expect = r.get("expect")
        if old_root is None:
            old, onote = "unknown", None
        else:
            old, onote = _sc_run_row(base["runner"], old_root, old_root, r["command"])
        new, nnote = _sc_run_row(base["runner"], new_root, new_root, r["command"])
        verdict = _sc_verdict(expect, old, new)
        if old_def is None and old == "error" and new != "error" and expect in ("refused", "allowed"):
            # a table added during the run has no old side (its runner may not exist there): the row is new and is
            # judged on the current code only
            old, onote = "none", None
            verdict = "held" if new == {"refused": "REFUSED", "allowed": "ALLOWED"}[expect] else "still_open"
        row = {"id": r["id"], "command": r["command"], "expect": expect, "old": old, "new": new,
               "verdict": verdict, "new_row": bool(r.get("new_row"))}
        why = "; ".join(x for x in (onote, nnote) if x)
        if verdict == "errored" and not why:
            why = f"expect must be \"refused\" or \"allowed\", not {expect!r}"
        if why:
            row["note"] = why
        counts[verdict] += 1
        out_rows.append(row)
    return {"name": name, "ran": True, "stale": False, "note": notes[0] if notes else None, "notes": notes,
            "counts": counts, "rows": out_rows, "watches": base["watches"]}


def _sc_not_run(name, note, failed=False):
    """A table that did not run. `failed`: it should have (unreadable file, code could not be rebuilt), so the
    result is saved and shown; otherwise it was skipped on purpose (its watched files did not change)."""
    return {"name": name, "ran": False, "failed": failed, "stale": False, "note": note, "notes": [note],
            "counts": dict(SC_ZERO), "rows": [], "watches": []}


def _sc_lay_runner(src: Path, dst: Path):
    """Lays the starting copy of tests/shortcuts (runner scripts and helpers) over the current copy, so a runner the
    builder edited or deleted still runs as it was at the start; the code under test is untouched."""
    sdir = src / SHORTCUT_DIR
    if sdir.is_dir():
        shutil.copytree(sdir, dst / SHORTCUT_DIR, dirs_exist_ok=True, symlinks=False, ignore_dangling_symlinks=True)


def _sc_hits(paths, watches) -> bool:
    return any(c == w.rstrip("/") or c.startswith(w.rstrip("/") + "/") for c in paths for w in watches)


def _sc_compute(ctx, st, only=None) -> dict:
    """Runs every shortcut table whose watched files this run changed (all of them when the starting code cannot
    be worked out); returns {"tables": [...]}. Changes nothing in the project: both versions are throwaway copies."""
    if not _is_git(ctx.root):
        return {"tables": [], "notes": ["Shortcut tables need a git project, so none were run."]}
    old_tree, old_note, conflicts, conflicts_redo = _sc_old_version(ctx, st)
    # the starting rows and expectations always come from the run's starting tree, never from the comparison
    # version (main's own edits to a table must not drop or flip a row); only the code compared comes from old_tree
    start_tree = _sc_start_tree(st) or old_tree
    old_files = _sc_old_files(ctx, start_tree) if start_tree else {}
    cmp_files = _sc_old_files(ctx, old_tree) if old_tree and old_tree != start_tree else {}
    cur_dir = ctx.root / SHORTCUT_DIR
    cur_files = {p.stem: p for p in sorted(cur_dir.glob("*.json")) if p.is_file()} if cur_dir.is_dir() else {}
    names = sorted(set(old_files) | set(cur_files))
    if only:
        names = [n for n in names if n == only]
    if not names:
        return {"tables": []}
    fp = fingerprint(ctx.root)
    changed = changed_files(ctx.root, {"kind": "git-tree", "id": old_tree}, fp) if old_tree else None
    old_root = new_root = start_root = None
    laid = False
    tables = []
    try:
        for name in names:
            old_def = old_why = cur_def = cur_why = None
            if name in old_files:
                old_def, old_why = _sc_parse(old_files[name])
            if name in cur_files:
                try:
                    cur_def, cur_why = _sc_parse(cur_files[name].read_text(errors="replace"))
                except OSError as e:
                    cur_why = f"unreadable: {e}"
            if old_def and name in cmp_files:  # rows main added are extra rows; they never replace a starting row
                main_def, _w = _sc_parse(cmp_files[name])
                if main_def:
                    have = {r["id"] for r in old_def["rows"]}
                    old_def = dict(old_def, rows=old_def["rows"] + [r for r in main_def["rows"] if r["id"] not in have])
            base = old_def or cur_def
            if base is None:
                tables.append(_sc_not_run(name, f"Not run: the {name} table file is {old_why or cur_why}.", True))
                continue
            gone = _sc_watch_missing(ctx, start_tree, base["watches"])
            if gone:
                tables.append(_sc_not_run(name, f"Not run: the {name} table watches {', '.join(gone)}, which exists "
                                                "neither in the starting code nor in the current code.", True))
                continue
            if changed is not None and not _sc_hits(changed, base["watches"]):
                tables.append(_sc_not_run(name, f"{name} was not run: the files it watches "
                                                f"({', '.join(base['watches'])}) did not change in this run."))
                continue
            if new_root is None:
                new_root = _materialize(ctx, fp["id"], [])
                old_root = _materialize(ctx, old_tree, []) if old_tree else None
                if new_root is None or (old_tree and old_root is None):
                    tables.append(_sc_not_run(name, "Not run: Ratchet could not rebuild the code to run it on.", True))
                    for d in (old_root, new_root):
                        if d is not None:
                            shutil.rmtree(d, ignore_errors=True)
                    new_root = old_root = None
                    continue
            if old_def and not laid:  # a table that existed at the start keeps its starting runner files
                src = old_root if old_tree == start_tree else None
                if src is None and start_tree:
                    src = start_root = _materialize(ctx, start_tree, [])
                if src is not None:
                    _sc_lay_runner(src, new_root)
                    if old_root is not None and src is not old_root:
                        _sc_lay_runner(src, old_root)
                laid = True
            t_old, t_note = old_root, old_note
            for cset, cwhy in ((conflicts, "laying main's side onto the code this run started from hit a conflict there"),
                               (conflicts_redo, "main's merge into this lane had a conflict resolved by hand in a "
                                                "file this table watches")):
                if t_old is not None and _sc_hits(cset, base["watches"]):  # only this table's watched files conflict
                    t_old = None
                    t_note = f"The starting version of the files this table watches cannot be worked out: {cwhy}."
            res = _sc_table(ctx, name, old_def, cur_def, cur_why, t_old, new_root, t_note)
            res["fingerprint"] = fp["id"]
            tables.append(res)
    finally:
        for d in (old_root, new_root, start_root):
            if d is not None:
                shutil.rmtree(d, ignore_errors=True)
    return {"tables": tables}


def _has_shortcut_case(ctx, plan) -> bool:
    """True when some test-plan case has layer "shortcuts": status --json then carries `done_means_table` at any
    phase, so the agent can see mid-run whether a line linked to a shortcut table is proven."""
    return any(c.get("layer") == "shortcuts" for cp in (plan or {}).get("checkpoints") or []
               if isinstance(cp, dict) and cp.get("id")
               for c in (test_plan(ctx, cp["id"]) or {}).get("cases") or [])


def _sc_dir(ctx) -> Path:
    return ctx.run_dir() / "evidence" / "shortcuts"


def _sc_save(ctx, result: dict):
    """Saves each table that ran, and each that failed to run (unreadable file, code that could not be rebuilt:
    shown as a failure, its linked line stays unproven), as evidence/shortcuts/<name>.json with the code
    fingerprint it ran on. A table skipped because its watched files did not change writes nothing and never deletes
    an earlier saved result (a valid result is not thrown away)."""
    d = _sc_dir(ctx)
    for t in result["tables"]:
        p = d / f"{t['name']}.json"
        if not t.get("ran") and not t.get("failed"):
            continue
        d.mkdir(parents=True, exist_ok=True)
        _write_record(p, dict(t, saved_at=now()), pretty=True)


def _sc_saved(ctx) -> dict:
    """The saved table results (no running), each with `stale`: true when the code changed since it ran."""
    d = _sc_dir(ctx)
    files = sorted(d.glob("*.json")) if d.is_dir() else []
    tables = []
    for p in files:
        t, bad = _read_record(p, kind=dict)
        if bad:
            continue
        if isinstance(t, dict) and isinstance(t.get("rows"), list) and (t.get("ran") or t.get("failed")):
            tables.append(t)
    if tables:
        now_id = fingerprint(ctx.root)["id"]
        for t in tables:
            t["stale"] = t.get("fingerprint") != now_id
    return {"tables": tables}


def _sc_counts_line(t: dict) -> str:
    if t.get("failed"):
        return f"Shortcut table {t['name']}: could not run. {t.get('note') or ''}".rstrip()
    c = t.get("counts") or {}
    return (f"Shortcut table {t['name']}: {c.get('worse', 0)} worse, {c.get('still_open', 0)} still open, "
            f"{c.get('fixed', 0)} fixed, {c.get('held', 0)} held, {c.get('errored', 0)} errored"
            + (f", {c['unknown']} unknown (the starting version could not be run)" if c.get("unknown") else ""))


def _sc_table_lines(t: dict) -> list[str]:
    """One table's block, shared by `shortcuts`, `status` (the final review), and the receipt: its counts, its
    notes, then a heading per verdict that has rows (got worse, still open, fixed, errored, unknown) with each
    row's command. Held rows are only counted."""
    out = [_sc_counts_line(t)]
    if t.get("stale"):
        out.append("  This saved result is out of date: the code changed after it ran. Run `ratchet.py "
                   "shortcuts` again.")
    if not t.get("failed"):  # a failed table's one note is already in its first line
        out += [f"  Note: {n}" for n in t.get("notes") or []]
    for verdict, heading in SC_HEADINGS:
        rows = [r for r in t.get("rows") or [] if r.get("verdict") == verdict]
        if not rows:
            continue
        out.append(f"  {heading} ({len(rows)}):")
        for r in rows:
            tail = f" [{r['note']}]" if r.get("note") else ""
            new = " (added since the run started)" if r.get("new_row") else ""
            out.append(f"    {r['id']}: {r['command']}   expected {r.get('expect')}; at the start {r.get('old')}, "
                       f"now {r.get('new')}{new}{tail}")
    return out


def _sc_block_lines(saved: dict) -> list[str]:
    out = []
    for t in saved.get("tables") or []:
        out += _sc_table_lines(t)
    return out


def cmd_shortcuts(args):
    """`ratchet.py shortcuts [<name>] [--json]`: runs the shortcut tables whose watched files this run changed,
    against the code the run started from and the current code, and saves each result under the run's
    evidence/shortcuts. Shows rows that got worse, stayed open, got fixed or errored; changes no project file."""
    ctx = Ctx(find_root())
    st = ctx.state()
    result = _sc_compute(ctx, st, getattr(args, "name", None))
    _sc_save(ctx, result)
    if getattr(args, "json", False):
        print(json.dumps(result, indent=2))
        return
    if not result["tables"]:
        print("There are no shortcut tables in this project (tests/shortcuts/*.json)."
              if not result.get("notes") else result["notes"][0])
        return
    for t in result["tables"]:
        if not t.get("ran"):
            print(t["note"])
            continue
        for line in _sc_table_lines(t):
            print(line)
        print("")


def _sc_case_status(ctx, case: dict) -> str:
    """A 'shortcuts'-layer case's own state for the done-means table: "passed" only when a saved result for its
    table, made on the current code, has every row right on the current code (the starting side never matters);
    otherwise the table's wrong rows by id, or that the saved result is out of date, or DM_NO_RESULT."""
    name = case.get("table")
    p = _sc_dir(ctx) / f"{name}.json" if isinstance(name, str) and name else None
    if p is None or not p.is_file():
        return DM_NO_RESULT
    saved = _sc_saved(ctx)
    t = next((x for x in saved["tables"] if x.get("name") == name), None)
    if t is None:
        return DM_NO_RESULT
    if t.get("failed"):
        return f"shortcut table {name}: could not run ({t.get('note')})"
    if t.get("stale"):
        return f"shortcut table {name}: the saved result is out of date (the code changed since it ran)"
    want = {"refused": "REFUSED", "allowed": "ALLOWED"}
    wrong = [r["id"] for r in t["rows"] if r.get("verdict") == "errored" or r.get("new") != want.get(r.get("expect"))]
    if wrong:
        return f"shortcut table {name}: rows wrong on the current code: {', '.join(wrong)}"
    return "passed"


def _sc_run_at_finish(ctx, st) -> list[str]:
    """Called when the last step completes: runs and saves the tables; the lines to print. Never blocks a finish:
    a failure here is a plain note."""
    try:
        result = _sc_compute(ctx, st)
        _sc_save(ctx, result)
    except Exception as e:  # shows a note, never refuses the finish
        return [f"The shortcut tables could not be run ({str(e)[:160]}); run `ratchet.py shortcuts` to see why."]
    return [_sc_counts_line(t) for t in result["tables"] if t.get("ran") or t.get("failed")]


def _finish_guardrail(ctx, st, cp):
    """A guardrail step passed every gate: its check becomes permanent (config `checks`) and is noted in learnings."""
    gr = cp.get("guardrail") or {}
    if not gr.get("check_command"):
        return
    user = read_json(ctx.config_path, {}) or {}
    checks = [c for c in (user.get("checks") or []) if isinstance(c, dict)]
    existing = [c for c in checks if norm_kind(c.get("kind")) == gr["kind"]]
    if any(c.get("from") == f"{st['slug']}/{cp['id']}" for c in existing):
        return  # an earlier run of `complete` for this step added it, then failed before it could save
    if existing and not gr.get("strengthen"):
        die(f"An automatic check for '{gr['kind']}' already exists; it is never replaced silently.")
    # a strengthen step replaces its own kind's check, after proving it still catches every past case
    checks = [c for c in checks if norm_kind(c.get("kind")) != gr["kind"]]
    command = _check_cmd(gr, gr.get("target") or ".")
    checks.append({"kind": gr["kind"], "command": command, "title": cp["title"],
                   "template": gr["check_command"], "target": gr.get("target") or ".",
                   "bad_example": gr.get("bad_example"), "why": gr.get("why"), "test_command": gr.get("test_command"),
                   "test_files": gr.get("test_files"), "high_risk": bool(gr.get("high_risk")),
                   "variants_dir": gr.get("variants_dir"),
                   "cases": (st["checkpoints"].get(cp["id"]) or {}).get("guardrail_cases") or [],
                   "added": _dt.date.today().isoformat(), "from": f"{st['slug']}/{cp['id']}"})
    user["checks"] = checks
    write_json(ctx.config_path, user)
    if st.get("approved"):
        st["approved"].setdefault("rules", {})["checks"] = _sha(ctx.config().get("checks"))
    _append_learning(ctx, f"{gr.get('why') or gr['kind']}: enforced by `{command}`", f"guardrail {cp['id']}")


# ---- spec tools: OpenSpec, Spec Kit, BMAD ---------------------------------------------------------------------
# The team's spec says WHAT to build; Ratchet proves it was built. A run can start from a spec item: its scenarios /
# acceptance criteria each need a planned test (case "spec_ref"), its tasks each belong to a step ("spec_refs"),
# and when a step passes every gate Ratchet ticks those tasks in the spec tool's own files.

TOOL_PLAIN = {"openspec": "OpenSpec change", "speckit": "Spec Kit feature", "bmad": "BMAD story"}


def _spec_source_path(ctx) -> Path:
    return ctx.run_dir() / "reference" / "spec-source.json"


def spec_source(ctx) -> dict | None:
    try:
        src = read_json(_spec_source_path(ctx))
    except SystemExit:
        return None
    return src if isinstance(src, dict) and src.get("items") else None


def spec_items(ctx, src=None) -> list[dict]:
    """The spec items this run was built from, read fresh from the tool's files."""
    src = src or spec_source(ctx)
    out = []
    for ref in (src or {}).get("items") or []:
        try:
            out.append(specsrc.load(ctx.root, ref["tool"], ref["id"]))
        except (FileNotFoundError, ValueError) as e:
            out.append({"tool": ref["tool"], "id": ref["id"], "title": ref["id"], "missing": str(e),
                        "requirements": [], "tasks": [], "standards": []})
    return out


def _spec_label(it) -> str:
    return f"{TOOL_PLAIN.get(it['tool'], it['tool'])} {it['id']}" + (f" ({it['title']})" if it.get("title") not in (None, it["id"]) else "")


def _as_list(v) -> list:
    return [x for x in (v if isinstance(v, list) else [v]) if isinstance(x, str) and x]


def spec_coverage(ctx, plan, items) -> dict:
    """Which spec refs the plan covers: scenarios need a test case (or a UI-reviewed step), tasks need a step."""
    tests_need = specsrc.scenario_refs(items)
    task_refs = [t["ref"] for it in items for t in it["tasks"] if not t.get("subtask")]
    done_tasks = {t["ref"] for it in items for t in it["tasks"] if t["done"]}
    known = set(tests_need) | {t["ref"] for it in items for t in it["tasks"]} | \
        {r["ref"] for it in items for r in it["requirements"]}
    unmapped, bad_unmapped = {}, []
    for u in plan.get("spec_unmapped") or []:
        ref = u.get("ref") if isinstance(u, dict) else None
        if not ref:
            bad_unmapped.append(str(u)[:80])
        elif not str(u.get("reason") or "").strip():
            bad_unmapped.append(ref)
        else:
            unmapped[ref] = u["reason"].strip()
    by_case, by_step, ui_steps, unknown = {}, {}, {}, set()
    for cp in plan.get("checkpoints") or []:
        if not isinstance(cp, dict) or not cp.get("id"):
            continue  # a malformed step is refused by plan validation; this table just skips it
        for ref in _as_list(cp.get("spec_refs") or []):
            by_step.setdefault(ref, []).append(cp["id"])
            if (cp.get("gates") or {}).get("ui"):
                ui_steps.setdefault(ref, []).append(cp["id"])
            if ref not in known:
                unknown.add(ref)
        for case in (test_plan(ctx, cp["id"]) or {}).get("cases") or []:
            for ref in _as_list(case.get("spec_ref")):
                by_case.setdefault(ref, []).append({"case": case.get("id"), "checkpoint": cp["id"]})
                if ref not in known:
                    unknown.add(ref)
    unknown |= {r for r in unmapped if r not in known}
    no_test = [r for r in tests_need if r not in by_case and r not in ui_steps and r not in unmapped]
    no_step = [r for r in task_refs if r not in by_step and r not in done_tasks and r not in unmapped]
    return {"scenarios": tests_need, "tasks": task_refs, "by_case": by_case, "by_step": by_step,
            "ui_steps": ui_steps, "unmapped": unmapped, "no_test": no_test, "no_step": no_step,
            "unknown": sorted(unknown), "bad_unmapped": bad_unmapped, "done_tasks": sorted(done_tasks),
            "unclear": [r for it in items for r in it.get("unclear") or []],
            "missing": [f"{it['tool']} {it['id']}" for it in items if it.get("missing")]}


def spec_plan_problems(ctx, plan) -> list[str]:
    src = spec_source(ctx)
    if not src:
        return []
    items = spec_items(ctx, src)
    cov = spec_coverage(ctx, plan, items)
    errs = [f"the spec item {m} can't be read any more" for m in cov["missing"]]
    if cov["no_test"]:
        errs.append("no planned test covers these spec scenarios/criteria (give a test case \"spec_ref\", or list "
                    "them in the plan's spec_unmapped with a reason): " + ", ".join(cov["no_test"][:20]))
    if cov["no_step"]:
        errs.append("these spec tasks aren't in any step's spec_refs (add them, or list them in spec_unmapped with "
                    "a reason): " + ", ".join(cov["no_step"][:20]))
    if cov["unknown"]:
        errs.append("these refs aren't in the spec (typo, or the spec changed?): " + ", ".join(cov["unknown"][:20]))
    if cov["bad_unmapped"]:
        errs.append("every spec_unmapped entry needs a ref and a reason: " + ", ".join(cov["bad_unmapped"][:10]))
    return errs


def _spec_snapshot(ctx) -> str | None:
    src = spec_source(ctx)
    return _sha(specsrc.spec_digest(spec_items(ctx, src))) if src else None


def _spec_standards(items) -> list[str]:
    seen = []
    for it in items:
        for s in it.get("standards") or []:
            if s not in seen:
                seen.append(s)
    return seen


def _pick_spec_items(ctx, tool, ids) -> list[tuple[str, str]]:
    found = specsrc.detect(ctx.root)
    if tool == "auto":
        cands = [(t, x["id"]) for t, xs in found.items() for x in xs]
        if ids:
            cands = [c for c in cands if c[1] in ids]
        if len(cands) != 1:
            names = "; ".join(f"{TOOL_PLAIN[t]} {i}" for t, i in cands) or "none"
            die(f"Can't pick a spec item automatically ({len(cands)} open: {names}). Name the tool and item.")
        return cands
    if tool not in TOOL_PLAIN:
        die(f"Unknown spec tool '{tool}'. Use openspec, speckit, bmad or auto.")
    if not ids:
        die(f"Name the {TOOL_PLAIN[tool]} to build (see `ratchet.py spec detect`).")
    return [(tool, i) for i in ids]


def cmd_spec(args):
    ctx = Ctx(find_root())
    if args.spec_cmd == "detect":
        found = specsrc.detect(ctx.root)
        if args.json:
            print(json.dumps(found, indent=2))
            return
        if not found:
            print("No OpenSpec, Spec Kit or BMAD files found in this project.")
            return
        if not any(found.values()):
            print("This project uses " + ", ".join(TOOL_PLAIN[t].rsplit(" ", 1)[0] for t in found) +
                  ", but nothing is open to build right now.")
            return
        for tool, xs in found.items():
            if not xs:
                continue
            print(f"{TOOL_PLAIN[tool]}s still open: {len(xs)}")
            for x in xs:
                bits = [x.get("status") or ""]
                if "scenarios" in x:
                    bits.append(f"{x['scenarios']} scenarios")
                if "criteria" in x:
                    bits.append(f"{x['criteria']} acceptance criteria")
                bits.append(f"{x.get('tasks', 0)} tasks")
                if x.get("current"):
                    bits.append("current feature")
                if x.get("unclear"):
                    bits.append(f"{len(x['unclear'])} requirement(s) marked NEEDS CLARIFICATION")
                if tool == "bmad" and not x.get("approved"):
                    bits.append("not approved yet")
                print(f"  - {x['id']}: {x['title']} ({', '.join(b for b in bits if b)})")
        return
    if args.spec_cmd == "import":
        st = ctx.state()
        if st["phase"] not in ("planning", "awaiting_plan_approval"):
            die(f"Import a spec while planning (phase is {st['phase']}).")
        picks = _pick_spec_items(ctx, args.tool, args.items or [])
        items = []
        for tool, iid in picks:
            try:
                items.append(specsrc.load(ctx.root, tool, iid))
            except (FileNotFoundError, ValueError) as e:
                die(str(e))
        rd = ctx.run_dir()
        (rd / "reference").mkdir(parents=True, exist_ok=True)
        write_json(_spec_source_path(ctx), {"items": [{"tool": it["tool"], "id": it["id"], "path": it["path"]}
                                                       for it in items], "imported_at": now()})
        plan, tests = specsrc.draft_plan(items, st.get("feature") or items[0]["title"])
        wrote_plan = args.force or not (rd / "checkpoints.json").exists()
        if wrote_plan:
            write_json(rd / "checkpoints.json", plan)
            for cid, tp in tests.items():
                if args.force or not (rd / "tests" / f"{cid}.json").exists():
                    write_json(rd / "tests" / f"{cid}.json", tp)
        stds = _spec_standards(items)
        user = read_json(ctx.config_path, {}) or {}
        cur = list(ctx.config().get("standards") or [])
        add = [s for s in stds if s not in cur]
        if add:
            user["standards"] = cur + add
            write_json(ctx.config_path, user)
        ctx.log(st, "spec_imported", items=[f"{it['tool']}:{it['id']}" for it in items])
        ctx.save_state(st)
        cov_scen = sum(len(specsrc.scenario_refs([it])) for it in items)
        out = {"items": [{"tool": it["tool"], "id": it["id"], "title": it["title"], "status": it.get("status"),
                          "approved": it.get("approved"), "unclear": it.get("unclear") or [],
                          "removed": [r["ref"] for r in it.get("removed") or []]} for it in items],
               "scenarios": cov_scen, "tasks": sum(len(it["tasks"]) for it in items),
               "draft_steps": len(plan["checkpoints"]) if wrote_plan else None, "standards_added": add}
        if args.json:
            print(json.dumps(out, indent=2))
            return
        for it in items:
            ok(f"Imported {_spec_label(it)}: {len(specsrc.scenario_refs([it]))} scenario(s) to test, "
               f"{len(it['tasks'])} task(s).")
            if not it.get("approved"):
                print(f"  Note: its status is '{it.get('status')}', so the team may not have approved it yet.")
            if not specsrc.scenario_refs([it]):
                print("  Note: no requirements, scenarios or acceptance criteria could be read from it, so nothing in it "
                      "would need a test. Check how it is written before relying on the coverage check.")
            if it.get("unclear"):
                print(f"  Note: {len(it['unclear'])} requirement(s) are marked NEEDS CLARIFICATION: "
                      + ", ".join(it["unclear"]))
            if it.get("removed"):
                print(f"  Removes {len(it['removed'])} requirement(s): " + ", ".join(r["title"] for r in it["removed"]))
        if wrote_plan:
            print(f"Draft plan written: {len(plan['checkpoints'])} step(s) in checkpoints.json and tests/. "
                  "The planner fills in test commands, files, risk and UI checks, and keeps every spec ref.")
        else:
            print("checkpoints.json already exists, so it was left alone (use --force to replace it with a draft).")
        if add:
            print("Added to the standards reviewers enforce: " + ", ".join(add))
        return
    if args.spec_cmd == "keep":
        user = read_json(ctx.config_path, {}) or {}
        user["spec_keep"] = args.choice == "on"
        write_json(ctx.config_path, user)
        if args.choice == "off":
            ok("Noted: no running spec for this project. You won't be asked again.")
            return
        ok("Noted: Ratchet keeps a running spec for this project, updated at the end of every run.")
        try:
            st = ctx.state()
        except SystemExit:
            return
        if st.get("phase") == "done" and not spec_source(ctx):
            print(write_living_spec(ctx, st))
            ctx.save_state(st)
        return
    if args.spec_cmd == "status":
        src = spec_source(ctx)
        if not src:
            print("This run wasn't started from a spec.")
            return
        st = ctx.state()
        items = spec_items(ctx, src)
        plan = ctx.plan() or {"checkpoints": []}
        cov = spec_coverage(ctx, plan, items)
        done = {cid for cid, c in (st.get("checkpoints") or {}).items() if c.get("status") == "done"}
        rows = []
        for ref in cov["scenarios"]:
            cases = cov["by_case"].get(ref) or []
            steps = sorted({c["checkpoint"] for c in cases} | set(cov["ui_steps"].get(ref) or []))
            state = "not planned" if not steps else ("proven" if all(s in done for s in steps) else "planned")
            if ref in cov["unmapped"]:
                state = "left out: " + cov["unmapped"][ref]
            rows.append({"ref": ref, "tests": [c["case"] for c in cases], "steps": steps, "state": state})
        ticked = set(cov["done_tasks"])
        trows = [{"ref": r, "steps": cov["by_step"].get(r) or [], "ticked": r in ticked} for r in cov["tasks"]]
        if args.json:
            print(json.dumps({"items": [{"tool": it["tool"], "id": it["id"], "title": it.get("title"),
                                         "status": it.get("status")} for it in items],
                              "scenarios": rows, "tasks": trows, "problems": spec_plan_problems(ctx, plan)}, indent=2))
            return
        proven = sum(1 for r in rows if r["state"] == "proven")
        print("Built from: " + "; ".join(_spec_label(it) for it in items))
        print(f"Scenarios proven by passing tests: {proven} of {len(rows)}; tasks ticked: "
              f"{sum(1 for t in trows if t['ticked'])} of {len(trows)}")
        for r in rows:
            print(f"  - {r['ref']}: {r['state']}" + (f" ({', '.join(r['tests'])})" if r["tests"] else ""))
        return


def spec_summary_lines(ctx, plan) -> list[str]:
    src = spec_source(ctx)
    if not src:
        return []
    items = spec_items(ctx, src)
    cov = spec_coverage(ctx, plan, items)
    approved = all(it.get("approved") for it in items)
    lines = ["Built from: " + "; ".join(_spec_label(it) for it in items) +
             (" (already agreed by the team)" if approved else " (not marked approved yet)")]
    n = len(cov["scenarios"])
    lines.append(f"Spec coverage: {n - len(cov['no_test']) - sum(1 for r in cov['scenarios'] if r in cov['unmapped'])}"
                 f" of {n} scenario(s) have a planned test; {len(cov['tasks']) - len(cov['no_step'])} of "
                 f"{len(cov['tasks'])} task(s) are in a step.")
    for ref, why in cov["unmapped"].items():
        lines.append(f"Left out on purpose: {ref} ({why})")
    if cov["unclear"]:
        lines.append("Still marked NEEDS CLARIFICATION in the spec: " + ", ".join(cov["unclear"]))
    return lines


def _step_spec_line(cp) -> str | None:
    refs = _as_list(cp.get("spec_refs") or [])
    if not refs:
        return None
    tasks = [r.split("#", 1)[1] for r in refs if "#task:" in r or re.search(r"#T\d+$", r)]
    scen = [r for r in refs if r not in tasks and not ("#task:" in r or re.search(r"#T\d+$", r))]
    bits = []
    if scen:
        bits.append(f"{len(scen)} requirement(s)/criteria")
    if tasks:
        bits.append("tasks " + ", ".join(t.replace("task:", "") for t in tasks[:8]) + ("…" if len(tasks) > 8 else ""))
    return ", ".join(bits)


def _compose(fns):
    def run(text):
        for fn in fns:
            text = fn(text)
        return text
    return run


def _spec_write_back(ctx, st, cp, fp, base_tree=None) -> tuple[dict, list[str]]:
    """After a step passes every gate: tick its tasks in the spec files, and finish a BMAD story whose steps are all
    done. The working files are updated, and the same edits are applied to the reviewed version of each file for the
    commit, so the user's own unrelated edits to a spec file never ride along. Returns ({file: text to commit},
    plain notes)."""
    src = spec_source(ctx)
    refs = set(_as_list(cp.get("spec_refs") or []))
    if not src or not refs:
        return {}, []
    items = [it for it in spec_items(ctx, src) if not it.get("missing")]
    edits, notes = {}, []
    for rel, (iid, style) in specsrc.task_files(ctx.root, items, refs).items():
        edits.setdefault(rel, []).append(lambda t, iid=iid, style=style: specsrc.tick_text(t, iid, style, refs))
    fresh_ticks = sum(1 for it in items for t in it["tasks"] if t["ref"] in refs and not t["done"])
    plan = ctx.plan() or {"checkpoints": []}
    for it in items:
        if it["tool"] != "bmad":
            continue
        mine = [c for c in plan["checkpoints"] if any(r.startswith(it["id"] + "#") for r in _as_list(c.get("spec_refs") or []))]
        if not mine or cp["id"] not in [c["id"] for c in mine] or \
                any(c["id"] != cp["id"] and st["checkpoints"][c["id"]]["status"] != "done" for c in mine):
            continue
        lines = [f"Built and checked by Ratchet (run {st['slug']}). Every step passed its tests and an independent "
                 "code review before it was committed."]
        for c in mine:
            commit = st["checkpoints"][c["id"]].get("commit")
            lines.append(f"- {c['id']} {c['title']}" + (f" (commit {commit})" if commit else ""))
        for ac in it["requirements"]:
            proof = [x["id"] for c in mine for x in (test_plan(ctx, c["id"]) or {}).get("cases") or []
                     if ac["ref"] in _as_list(x.get("spec_ref"))]
            lines.append(f"- {ac['title']}: " + (", ".join(proof) if proof else "no automated test (see the plan)"))
        evidence, version = "\n".join(lines), it.get("version", "v4")
        edits.setdefault(it["path"], []).append(lambda t, e=evidence, v=version: specsrc.bmad_finish_text(t, v, e)[0])
        ss = specsrc.sprint_status_path(it)
        if ss and (ctx.root / ss).exists():
            key = Path(it["path"]).stem
            edits.setdefault(ss, []).append(lambda t, k=key: specsrc.sprint_done_text(t, k))
        if it.get("status_line"):
            notes.append(f"marked BMAD story {it['id']} done and added Ratchet's evidence to it")
        else:
            notes.append(f"added Ratchet's evidence to BMAD story {it['id']}, but couldn't find its Status line to mark "
                         "it done")
    changed = [rel for rel, fns in edits.items()
               if (ctx.root / rel).is_file() and specsrc._edit_file(ctx.root / rel, _compose(fns))]
    if fresh_ticks:
        notes.insert(0, f"ticked {fresh_ticks} task(s) in " + ", ".join(sorted(changed) or sorted(edits)))
    blobs = {}
    if fp.get("kind") == "git-tree":
        # the version to tick: the reviewed one if this step changed the file, else the committed one (so edits the
        # user had made to it before the step started stay theirs, uncommitted, like any other file)
        stepped = set(changed_files(ctx.root, {"kind": "git-tree", "id": base_tree}, fp)) if base_tree else set()
        for rel, fns in edits.items():
            r = None
            if rel not in stepped:
                r = subprocess.run(["git", "cat-file", "blob", f"HEAD:{rel}"], cwd=ctx.root, capture_output=True)
            if r is None or r.returncode != 0:
                r = subprocess.run(["git", "cat-file", "blob", f"{fp['id']}:{rel}"], cwd=ctx.root, capture_output=True)
            if r.returncode == 0:  # in neither (e.g. ignored by git): nothing to commit
                blobs[rel] = specsrc._edit_text(specsrc._decode(r.stdout), _compose(fns))
    return blobs, notes


def _openspec_files(root: Path) -> dict:
    out = {}
    base = root / "openspec"
    for dp, dns, fns in os.walk(base) if base.is_dir() else []:
        for fn in fns:
            f = Path(dp) / fn
            try:
                out[str(f.relative_to(root))] = hashlib.sha1(f.read_bytes()).hexdigest()
            except OSError:
                continue
    return out


def _commit_paths(root: Path, paths: list[str], msg: str) -> str | None:
    """Commit exactly these paths as they are in the working tree (deleted ones removed), and nothing else: e.g. the
    files an OpenSpec archive moved and merged. The user's other changes and staged files stay as they were."""
    head = subprocess.run(["git", "rev-parse", "-q", "--verify", "HEAD^{commit}"], cwd=root, capture_output=True,
                          text=True).stdout.strip()
    if not head or not paths:
        return None
    info = []
    for rel in paths:
        f = root / rel
        if f.is_file() and not f.is_symlink():
            oid = subprocess.run(["git", "hash-object", "-w", "--", str(f)], cwd=root, capture_output=True,
                                 text=True).stdout.strip()
            info.append(f"{'100755' if os.access(f, os.X_OK) else '100644'} {oid}\t{rel}")
        else:
            info.append(f"0 {'0' * 40}\t{rel}")
    with tempfile.TemporaryDirectory() as td:
        env = dict(os.environ, GIT_INDEX_FILE=str(Path(td) / "index"), GIT_LITERAL_PATHSPECS="1")
        subprocess.run(["git", "read-tree", head], cwd=root, env=env, capture_output=True)
        subprocess.run(["git", "update-index", "-z", "--index-info"], cwd=root, env=env, capture_output=True,
                       input="\0".join(info).encode("utf-8", "surrogateescape") + b"\0")
        tree = subprocess.run(["git", "write-tree"], cwd=root, env=env, capture_output=True, text=True).stdout.strip()
        if not tree or tree == subprocess.run(["git", "rev-parse", f"{head}^{{tree}}"], cwd=root, capture_output=True,
                                              text=True).stdout.strip():
            return None
        new = subprocess.run(["git", "commit-tree", tree, "-p", head, "-m", msg], cwd=root, capture_output=True,
                             text=True).stdout.strip()
    if not new:
        return None
    subprocess.run(["git", "update-ref", "HEAD", new, head], cwd=root, capture_output=True)
    subprocess.run(["git", "reset", "-q", "--pathspec-from-file=-", "--pathspec-file-nul"], cwd=root,
                   capture_output=True, input="\0".join(paths).encode("utf-8", "surrogateescape"),
                   env=dict(os.environ, GIT_LITERAL_PATHSPECS="1"))
    return new[:7]


OFFER_KEEP = ("Offer: this project doesn't use a spec tool. Ask the user once, in plain words, whether you should keep "
              "a running spec of what has been built: a plain Markdown file per feature saying what the app does, each "
              "rule linked to the test that proves it, written at the end of each run and committed with it (it follows "
              "OpenSpec's file layout, so they could adopt OpenSpec later without losing anything). Then run "
              "`ratchet.py spec keep on` or `spec keep off` with their answer; it is remembered and never asked again.")


def wants_keep_offer(ctx) -> bool:
    return ctx.config().get("spec_keep") is None and not spec_source(ctx) and not specsrc.detect(ctx.root)


def living_spec_text(ctx, st) -> str:
    """The finished run as an OpenSpec-format capability spec: a requirement per step, a scenario per planned test."""
    plan = ctx.plan() or {"checkpoints": []}
    out = [f"# {plan.get('feature') or st.get('feature') or st['slug']}", "", "## Purpose",
           f"What this feature does, as built and checked by Ratchet (run {st['slug']}, {now()[:10]}). Each scenario "
           "names the test that proves it.", "", "## Requirements", ""]
    for cp in plan["checkpoints"]:
        if cp.get("guardrail") or (st.get("checkpoints") or {}).get(cp["id"], {}).get("status") != "done":
            continue  # automatic checks are about the code, not what the app does
        commit = st["checkpoints"][cp["id"]].get("commit")
        files = ", ".join((cp.get("tests") or {}).get("files") or [])
        out += [f"### Requirement: {cp['title']}", f"The system SHALL do this: {cp['summary']}", ""]
        out += [f"- {d}" for d in cp.get("done_when") or []] + [""]
        for c in (test_plan(ctx, cp["id"]) or {}).get("cases") or []:
            out.append(f"#### Scenario: {c.get('title') or c['id']}")
            if c.get("given"):
                out.append(f"- **GIVEN** {c['given']}")
            out.append(f"- **WHEN** {c.get('when') or 'this behaviour is exercised'}")
            out.append(f"- **THEN** {c.get('then') or c.get('title') or 'it works as described'}")
            how = "checked by the UI review" if c.get("layer") == "browser" else f"shortcut table {c.get('table')}" if c.get("layer") == "shortcuts" else f"test {c['id']}" + (f" in {files}" if files else "")
            out += [f"<!-- proven by {how}" + (f", commit {commit}" if commit else "") + " -->", ""]
    return "\n".join(out).rstrip() + "\n"


def write_living_spec(ctx, st) -> str:
    rel = f"openspec/specs/{st['slug']}/spec.md"
    p = ctx.root / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(living_spec_text(ctx, st), encoding="utf-8")
    commit = None
    cfg = ctx.config()
    if cfg.get("commit_per_checkpoint") and _is_git(ctx.root):
        paths = [rel] + ([f"{RATCHET_DIR}/config.json"] if ctx.config_path.exists() else [])
        commit = _commit_paths(ctx.root, paths, f"ratchet({st['slug']}): record what was built in {rel}")
    st["living_spec"] = rel
    ctx.log(st, "living_spec_written", path=rel, commit=commit)
    return f"Recorded what was built in {rel}" + (f" (commit {commit})." if commit else ".")


def _spec_finish(ctx, st) -> list[str]:
    """When the whole run is approved: archive OpenSpec changes (merging their deltas into the living specs). With no
    spec tool: keep the running spec if the user asked for one, or say to offer it once."""
    src = spec_source(ctx)
    if not src:
        keep = ctx.config().get("spec_keep")
        if keep is True:
            return [write_living_spec(ctx, st)]
        return [OFFER_KEEP] if keep is None and wants_keep_offer(ctx) else []
    if st.get("spec_finished"):
        return []
    cfg = ctx.config()
    notes = []
    for it in spec_items(ctx, src):
        if it["tool"] != "openspec" or it.get("missing") or it.get("archived"):
            continue
        if not cfg.get("spec_archive", True):
            notes.append(f"OpenSpec change {it['id']} is built; archiving is turned off (spec_archive), so it stays open.")
            continue
        open_tasks = [t["ref"] for t in it["tasks"] if not t["done"]]
        if open_tasks:
            notes.append(f"OpenSpec change {it['id']} still has {len(open_tasks)} unticked task(s), so it wasn't archived.")
            continue
        before = _openspec_files(ctx.root)
        done, why = specsrc.openspec_archive(ctx.root, it["id"])
        after = _openspec_files(ctx.root)
        moved = sorted(k for k in set(before) | set(after) if before.get(k) != after.get(k))
        if not done:
            notes.append(f"OpenSpec change {it['id']} is built but wasn't archived: {why}.")
            continue
        commit = None
        if cfg.get("commit_per_checkpoint") and _is_git(ctx.root):
            commit = _commit_paths(ctx.root, moved, f"ratchet({st['slug']}): archive OpenSpec change {it['id']}")
        notes.append(f"Archived OpenSpec change {it['id']}: its spec changes are now part of the main specs"
                     + (f" (commit {commit})." if commit else "."))
    st["spec_finished"] = notes or True
    ctx.log(st, "spec_finished", notes="; ".join(notes)[:400])
    return notes


_SEVERITY_RANK = {"blocker": 0, "major": 1, "minor": 2, "nit": 2, "nitpick": 2, "trivial": 2, "low": 2, "style": 2,
                   "info": 3, "suggestion": 3}


def _accepted_findings_lines(st) -> list[str]:
    """Findings the user accepted with `ratchet.py ask accept-finding` / `accept-finding`, blockers and majors
    first, for `status`, `plan-summary` and `deferred` (the final review's own command) to show in their own
    section: they were reviewed and agreed to on purpose, with a reason and who accepted them, so they must never
    read as a finding that simply 'did not block'."""
    rows = [(cp, f) for cp, c in (st.get("checkpoints") or {}).items() for f in c.get("deferred") or []
            if f.get("accepted")]
    if not rows:
        return []
    rows.sort(key=lambda cf: _SEVERITY_RANK.get(str(cf[1].get("severity", "")).strip().lower(), 4))
    lines = ["Findings accepted by you (blockers and majors first; they no longer block):"]
    for cp, f in rows:
        desc = str(f.get("description", "")).strip()[:200]
        who = f.get("accepted_by") or "human"
        lines.append(f"  {cp} {_finding_key(f)} ({f.get('severity', '?')}): {desc}  -  reason: {f.get('reason', '')}"
                     f"  -  accepted by: {who}")
    return lines


def _checkin_decisions_lines(st) -> list[str]:
    """Check-in decisions recorded so far (a simplify's reasoning, or a stop), for `plan-summary` to show next to
    the findings the user accepted: the orchestrator's own reasoning for narrowing scope is on the record too.
    Never shown by plain `status` (an open check-in prints its own brief instead; a past decision must never make
    `status` look like one is open again when it isn't)."""
    rows = [(cp, d) for cp, c in (st.get("checkpoints") or {}).items() for d in (c.get("checkin") or {}).get("decided") or []]
    if not rows:
        return []
    lines = ["Check-in decisions along the way:"]
    for cp, d in rows:
        if d.get("decision") == "simplify":
            lines.append(f"  {cp} round {d.get('round')}: simplify - {d.get('why', '')}")
        else:
            lines.append(f"  {cp} round {d.get('round')}: {d.get('decision')}")
    return lines


def _deferred_groups(cps) -> dict:
    """Groups one checkpoint's own deferred findings (never accepted ones) by `_finding_key` (reviewer/id, or the
    bare id when no reviewer is given), keeping only the LATEST round's own copy for each key: the same reviewer
    re-raising the same id in a later round overwrites its own earlier, stale copy here. Two findings that merely
    share a `kind` and `file` -- a different reviewer, or a different id -- are different keys and are never
    merged into one; each keeps its own entry."""
    groups: dict = {}
    for f in cps.get("deferred") or []:
        if f.get("accepted"):
            continue
        k = _finding_key(f)
        if k not in groups or (f.get("round") or 0) >= (groups[k].get("round") or 0):
            groups[k] = f
    return groups


def left_for_later(cps) -> list:
    """A checkpoint's deferred findings still left for later at the end of the run: `_deferred_groups`'s one entry
    per finding, minus any `ratchet.py mark-fixed` has since recorded fixed. Used by `deferred`, `deferred --json`
    and the final-review count in `status`, so all three always agree on what is still left for later."""
    return [f for f in _deferred_groups(cps).values() if not f.get("fixed")]


def _fixed_later(cps) -> list:
    """The companion list to `left_for_later`: the same deduped findings, kept only when `mark-fixed` marked them
    fixed."""
    return [f for f in _deferred_groups(cps).values() if f.get("fixed")]


def cmd_deferred(args):
    """Findings that were recorded instead of blocking (minor ones, and any blocker/major/unknown-severity
    finding with no user_impact), for the user to decide on at the end, PLUS, in their own section first,
    findings the user accepted while a round was blocked: these were shown to the user and agreed to on purpose,
    with a reason and who accepted them, so they are never mixed in with ones that simply never blocked. A finding
    `ratchet.py mark-fixed` recorded fixed prints in its own 'fixed later in the run' section instead of under
    'left for later' (both sections are deduped per `left_for_later`/`_fixed_later`: a finding re-raised in a
    later round by the same reviewer with the same id shows once, as that later round's own copy)."""
    ctx = Ctx(find_root())
    st = ctx.state()
    cps_map = st.get("checkpoints") or {}
    accepted = [(cp, f) for cp, c in cps_map.items() for f in c.get("deferred") or [] if f.get("accepted")]
    fixed = [(cp, f) for cp, c in cps_map.items() for f in _fixed_later(c)]
    other = [(cp, f) for cp, c in cps_map.items() for f in left_for_later(c)]
    if getattr(args, "json", False):
        rows = accepted + fixed + other
        print(json.dumps([dict(f, checkpoint=cp) for cp, f in rows], indent=2))
        return
    if not (accepted or fixed or other):
        print("No findings were left for later.")
        return
    acc_lines = _accepted_findings_lines(st)
    if acc_lines:
        for line in acc_lines:
            print(line)
        if fixed or other:
            print("")
    if fixed:
        print(f"{len(fixed)} finding(s) were fixed later in the run (a later round reviewed the change):")
        for cp, f in fixed:
            where = f" ({f['file']}{':' + str(f['line']) if f.get('line') else ''})" if f.get("file") else ""
            fx = f.get("fixed") or {}
            print(f"- {cp} {_finding_key(f)}{where}: {f.get('description', '').strip()[:240]} "
                  f"[fixed in round {fx.get('round')}: {fx.get('how', '')}]")
        if other:
            print("")
    if other:
        print(f"{len(other)} finding(s) were left for later (they did not block):")
        for cp, f in other:
            where = f" ({f['file']}{':' + str(f['line']) if f.get('line') else ''})" if f.get("file") else ""
            why = f" [{f['deferred_because']}]" if f.get("deferred_because") else ""
            print(f"- {cp} {_finding_key(f)}{where}: {f.get('description', '').strip()[:240]}{why}")


def cmd_mark_fixed(args):
    """`ratchet.py mark-fixed CPn <ref>="<how>"`: records that a finding left for later (`ratchet.py deferred`)
    was really fixed, so the final review's own left-for-later list stops showing it (`deferred` moves it under
    'fixed later in the run' instead). Refused outright, with nothing changed, unless BOTH: (1) the finding's own
    file has changed since the LATEST round that raised it (same reviewer/id) -- the baseline round is the
    highest of every round among this checkpoint's own non-accepted deferred entries for that key AND every
    recorded adversarial round whose own open-findings.json (the round's blocking findings, read fresh off disk,
    not just this checkpoint's deferred list) lists that same key, so a round that re-raises the finding as
    BLOCKING, not only one that defers it again, also becomes the new baseline -- that round itself can never
    serve as its own proof -- and (2) a later adversarial round has since been recorded whose own fingerprint
    already matches today's version of that file -- a fix nobody reviewed again does not count, and a file that
    never moved does not either. Also refused for a finding the user already accepted (a separate decision,
    `ratchet.py ask accept-finding`) or a reference naming no deferred finding at all."""
    ctx = Ctx(find_root())
    st = ctx.state()
    cps = (st.get("checkpoints") or {}).get(args.cp)
    if cps is None:
        die(f"No such checkpoint {args.cp}.")
    ref, sep, rest = args.decision.partition("=")
    ref = ref.strip()
    how = rest.strip()
    if len(how) >= 2 and how[0] == how[-1] and how[0] in ("'", '"'):
        how = how[1:-1].strip()
    if not sep or not how:
        die(f"{args.decision!r}: use `mark-fixed {args.cp} <ref>=\"how it was fixed\"`. Nothing was recorded.")
    all_deferred = cps.get("deferred") or []
    open_deferred = [d for d in all_deferred if not d.get("accepted")]
    found, err = _resolve_finding_ref(ref, open_deferred)
    if err:
        die(f"{err} Nothing was recorded.")
    if found is None:
        accepted = [d for d in all_deferred if d.get("accepted")]
        acc, _ = _resolve_finding_ref(ref, accepted)
        if acc is not None:
            die(f"{ref} was accepted by the user, not deferred (see `ratchet.py ask accept-finding`); mark-fixed "
                "does not apply to it. Nothing was recorded.")
        die(f"{ref} does not exist among {args.cp}'s deferred findings (`ratchet.py deferred` lists them). "
            "Nothing was recorded.")
    key = _finding_key(found)
    entries = [d for d in open_deferred if _finding_key(d) == key]
    file = found.get("file")
    rounds = ((cps.get("gates") or {}).get("adversarial") or {}).get("rounds") or []
    raised_rounds = [d.get("round") for d in entries if d.get("round") is not None]
    for rr in rounds:
        rno = rr.get("round")
        if rno is None:
            continue
        raw = _read_findings_file(_adv_round_dir(ctx, args.cp, rno) / "open-findings.json")
        if any(_finding_key(f) == key for f in raw):
            raised_rounds.append(rno)
    raised_round = max(raised_rounds, default=None)
    raised_rec = next((rr for rr in rounds if rr.get("round") == raised_round), None) \
        if raised_round is not None else None
    if raised_round is None or not file or not raised_rec or not raised_rec.get("fingerprint"):
        die(f"{ref} has no recorded round or file on record to check whether it was really fixed. Nothing was "
            "recorded.")
    cur_fp = fingerprint(ctx.root)
    raised_fp = {"kind": "git-tree", "id": raised_rec["fingerprint"]}
    file_norm = _norm_path(file)
    changed_since_raise = {_norm_path(x) for x in changed_files(ctx.root, raised_fp, cur_fp)}
    if file_norm not in changed_since_raise:
        die(f"{ref}'s file ({file}) has not changed since round {raised_round}, the round that raised it. "
            "mark-fixed only applies once the file has really changed. Nothing was recorded.")
    later_round = None
    for rr in sorted(rounds, key=lambda r: r.get("round", 0)):
        if rr.get("round", 0) <= raised_round or not rr.get("fingerprint"):
            continue
        rec_fp = {"kind": "git-tree", "id": rr["fingerprint"]}
        if file_norm not in {_norm_path(x) for x in changed_files(ctx.root, rec_fp, cur_fp)}:
            later_round = rr["round"]
            break
    if later_round is None:
        die(f"{ref}: no later review round has been recorded on the changed code since round {raised_round}. Run "
            f"`ratchet.py reviewers {args.cp}` and record a new round first. Nothing was recorded.")
    latest_entry = max(entries, key=lambda d: d.get("round") or 0)
    latest_entry["fixed"] = {"round": later_round, "how": how}
    ctx.log(st, "finding_marked_fixed", cp=args.cp, ref=key, round=later_round)
    ctx.save_state(st)
    ok(f"Marked {key} fixed for {args.cp} (a later round, {later_round}, reviewed the changed code). Run "
       "`ratchet.py deferred` to see it under 'fixed later in the run'.")


# ---- receipt: one honest proof receipt to paste into the pull request, at the end of a run -----------------

def _plain_duration(seconds) -> str:
    """A wall-clock span as a plain duration ('4h 17m', '38m'): never cost, never tokens, just time."""
    seconds = max(0, int(seconds or 0))
    days, rem = divmod(seconds, 86400)
    hours, rem = divmod(rem, 3600)
    minutes, _ = divmod(rem, 60)
    parts = []
    if days:
        parts.append(f"{days}d")
    if days or hours:
        parts.append(f"{hours}h")
    parts.append(f"{minutes}m")
    return " ".join(parts)


def _elapsed_seconds(a_iso, b_iso) -> int:
    return max(0, int(_iso(b_iso) - _iso(a_iso)))


def _step_reviewed_tree(cps) -> str | None:
    """The git-tree id Ratchet recorded as reviewed for this checkpoint: its adversarial gate's own `fingerprint`
    once that gate has passed, else the last adversarial round's own `fingerprint` (what that round actually
    looked at), else None when no round has ever opened."""
    g = (cps.get("gates") or {}).get("adversarial") or {}
    fp = g.get("fingerprint")
    if isinstance(fp, dict) and fp.get("id"):
        return fp["id"]
    rounds = g.get("rounds") or []
    if rounds:
        last_fp = rounds[-1].get("fingerprint")
        if isinstance(last_fp, dict):
            return last_fp.get("id")
        if last_fp:
            return last_fp
    return None


def _step_commit(ctx, cps) -> str | None:
    """The short commit id to show for a checkpoint: its own recorded `commit` field (the one `complete` makes)
    when there is one, else the one commit -- if any -- whose own git tree is exactly the tree Ratchet recorded
    as reviewed for this step (`_step_reviewed_tree`: the step's passed adversarial gate, or else its last
    adversarial round). Covers the one case `complete` itself leaves with no `commit` of its own even though
    commit_per_checkpoint is on: the code was already committed by some other means (directly, by the user or
    agent -- the accepted same-user limit) before `complete` ran, so there was nothing left for Ratchet's own
    commit to add. Never guesses from commit dates or a time window (an ordinary manual commit made mid-step
    that the reviewed tree does not match is never shown), so a step with no recorded commit and no commit whose
    tree matches what was actually reviewed still says 'no commit recorded'."""
    commit = cps.get("commit")
    if commit:
        return commit
    tree = _step_reviewed_tree(cps)
    if not tree or not _is_git(ctx.root):
        return None
    r = subprocess.run(["git", "log", "--format=%H %T"], cwd=ctx.root, capture_output=True, text=True)
    if r.returncode != 0:
        return None
    for line in r.stdout.splitlines():
        sha, _, cur_tree = line.partition(" ")
        if cur_tree == tree:
            return sha[:7]
    return None


def _step_elapsed(cps) -> tuple:
    """(status, seconds) for one checkpoint: 'finished' (started_at..completed_at), 'not finished' (started_at..now,
    the step is still mid-build) or 'not started' (no started_at yet: this step was never reached)."""
    started = cps.get("started_at")
    completed = cps.get("completed_at")
    if not started:
        return "not started", 0
    if completed:
        return "finished", _elapsed_seconds(started, completed)
    return "not finished", _elapsed_seconds(started, now())


def _run_elapsed(st) -> tuple:
    """(status, seconds) for the whole run: 'finished' once the run-level 'approved' history event exists
    (created_at..that event's own timestamp, the latest one if it is ever logged more than once), else 'not
    finished' (created_at..now: time so far, never a final total presented as if the run had ended)."""
    created = st.get("created_at")
    if not created:
        return "not finished", 0
    approved_at = None
    for h in st.get("history") or []:
        if h.get("event") == "approved":
            approved_at = h.get("at")  # the latest one wins when logged more than once
    if approved_at:
        return "finished", _elapsed_seconds(created, approved_at)
    return "not finished", _elapsed_seconds(created, now())


def _round_reviewer_entries(cfg, rnd_record: dict) -> list:
    """One entry per reviewer this round actually recorded (the round's own 'reviewers' list, the final set after
    any mid-round swap): {"round", "id", "host_fallback", "replaced", "reason"}. A host sub-agent reviewer
    ('kind': 'agent' on the roster) is always marked `host_fallback`; its `reason` comes from the round's own
    `substitutions` (cmd_reviewers' fallback record, fresh-round or the same-round re-resolve this checkpoint also
    fills in) when one names it, else 'reason not recorded' -- never invented, never left blank -- including when
    the round carries no `substitutions` key at all (a round recorded before that field existed). When today's
    roster has nothing for this id (removed or renamed since this round ran), `host_fallback` is decided from the
    recorded id's own naming convention (every host sub-agent id starts with "host-") instead of defaulting to
    false, so a roster edit made later in the run never hides a real host-company fallback or its reason.

    `reviewers` holds plain string ids while a round is still open (cmd_reviewers' own shape, including its
    same-round re-resolve branch, before adv-record ever runs) and dicts ({"id", "vendor", "model"}) once that
    round is recorded; either shape is accepted here. `substitutions` already carries the same `{"used",
    "instead_of", "why"}` records for a pending round (built from its own `resolved` list) as for a recorded one,
    so the lookup below needs no separate pending-round path."""
    subs = rnd_record.get("substitutions")
    by_used: dict = {}
    if isinstance(subs, list):
        for s in subs:
            by_used.setdefault(s.get("used"), []).append(s)
    out = []
    for r in rnd_record.get("reviewers") or []:
        rid = r if isinstance(r, str) else r.get("id")
        spec = _roster_spec(cfg, rid) or {}
        if spec:
            host_fallback = spec.get("kind") == "agent"
        else:
            # Today's roster has nothing for this id (a custom host-agent reviewer renamed or removed since
            # this round ran): fall back to the recorded id's own naming convention instead of calling it an
            # outside reviewer. Every host sub-agent id this engine ever hands out starts with "host-".
            host_fallback = bool(rid) and rid.startswith("host-")
        replaced, reason = [], None
        if host_fallback:
            why = {}
            for m in by_used.get(rid) or []:
                for x in m.get("instead_of") or []:
                    if x not in replaced:
                        replaced.append(x)
                why.update(m.get("why") or {})
            if why:
                reason = next(iter(why.values())) if len(why) == 1 else \
                    "; ".join(f"{k}: {v}" for k, v in why.items())
            else:
                reason = "reason not recorded"
        out.append({"round": rnd_record.get("round"), "id": rid, "host_fallback": host_fallback,
                    "replaced": replaced, "reason": reason})
    return out


def _step_reviewer_entries(cfg, cps) -> list:
    """Every recorded round's reviewers, plus the checkpoint's own currently-open round (`adv_round`) when one
    exists and adv-record has not recorded it yet -- so a receipt asked for while a round is pending (or just
    re-resolved mid-round) still honestly names its reviewers instead of silently omitting the step's own
    in-progress round."""
    rounds = ((cps.get("gates") or {}).get("adversarial") or {}).get("rounds") or []
    out = []
    for rnd_record in rounds:
        out += _round_reviewer_entries(cfg, rnd_record)
    pending = cps.get("adv_round")
    if pending and not pending.get("recorded"):
        out += _round_reviewer_entries(cfg, pending)
    return out


def _reviewer_line(e: dict) -> str:
    if not e["host_fallback"]:
        return f"  - round {e['round']}: {e['id']}"
    if e["replaced"]:
        return (f"  - round {e['round']}: {e['id']} - host's own company standing in, instead of "
                f"{', '.join(e['replaced'])} ({e['reason']})")
    return f"  - round {e['round']}: {e['id']} - host's own company fallback ({e['reason']})"


def _receipt_accepted(st) -> list:
    # "id" stays the finding's own bare id (the --json contract); "reviewer" is carried alongside it so two
    # reviewers who independently picked the same bare id within one checkpoint can still be told apart
    # (the qualified `_finding_key(f)` form the markdown prints uses exactly these two fields).
    return [{"checkpoint": cp, "id": f.get("id"), "reviewer": f.get("reviewer"), "severity": f.get("severity"),
             "description": f.get("description"), "reason": f.get("reason"),
             "accepted_by": f.get("accepted_by") or "human"}
            for cp, c in (st.get("checkpoints") or {}).items() for f in c.get("deferred") or [] if f.get("accepted")]


def _receipt_left_for_later(st) -> list:
    return [{"checkpoint": cp, "id": f.get("id"), "reviewer": f.get("reviewer"), "description": f.get("description"),
             "deferred_because": f.get("deferred_because")}
            for cp, c in (st.get("checkpoints") or {}).items() for f in left_for_later(c)]


def _receipt_fixed_later(st) -> list:
    out = []
    for cp, c in (st.get("checkpoints") or {}).items():
        for f in _fixed_later(c):
            fx = f.get("fixed") or {}
            out.append({"checkpoint": cp, "id": f.get("id"), "reviewer": f.get("reviewer"),
                        "description": f.get("description"), "round": fx.get("round"), "how": fx.get("how")})
    return out


DM_NO_UI_GATE = "not checked by any UI gate"
DM_NO_RESULT = "no result recorded yet"
DM_NO_TESTS_NOTE = ("No tests are linked to any of these lines (an older plan, from before tests could be linked "
                    "to a done-means line), so there is no result to show for them.")
DM_NO_LINES_NOTE = "no done-means lines were stated for this run's objective"


def _dm_case_status(ctx, cp_id: str, case: dict, behavior_status: str | None = None,
                    ui_status: str | None = None) -> str:
    """One linked test case's own state for the receipt's and the final review's done-means section. A
    browser-layer case is never run by `ratchet.py behavior`, so it reads "checked by the UI gate" when this
    checkpoint's UI gate (`ui_status`, passed by the caller) passed, and DM_NO_UI_GATE when it did not (never
    required, skipped, failed or still pending: nothing checked it). Otherwise, this checkpoint's
    latest per-case test report in evidence (whatever report format is actually on disk, read directly rather
    than only when the approved plan names one, so a report already written always counts) decides passed vs
    failed vs error vs skipped. With no report, or no result for this case in it, a supported exit-code-only
    step (tests.report none or missing) still has a recorded result at the step level: `behavior_status` (the
    checkpoint's own gates.behavior status, passed by the caller) says so, checked by exit code only rather
    than per case, so a developer never sees a passing step's linked line read "no result recorded yet". With
    no per-case report and no recorded behavior-gate status either (never run), that honest "no result
    recorded yet" still stands. A case can have more than one matching report entry (a parameterized test, or
    repeated runs); it counts as passed only when every matching entry passed, so one failed, errored or
    skipped instance among several still shows as failed."""
    if case.get("layer") == "browser":
        return "checked by the UI gate" if ui_status == "passed" else DM_NO_UI_GATE
    if case.get("layer") == "shortcuts":  # never run by `behavior`: its saved shortcut-table result decides
        return _sc_case_status(ctx, case)
    case_id = case.get("id") or ""
    pat = _case_id_re(case_id) if case_id else None
    for name in ("test-report.json", "test-report.xml"):
        p = ctx.evidence(cp_id) / name
        if p.exists():
            pairs, why = _read_test_report(ctx, p)
            if pairs and pat:
                statuses = [s for n, s in pairs if pat.search(n)]
                if statuses:
                    # a case passes only when every matching entry passed; any failed, errored or
                    # skipped entry means the case shows as failed, however many entries it has
                    return "passed" if all(s == "passed" for s in statuses) else "failed"
    if behavior_status == "passed":
        return "step tests passed, by exit code only (not checked per case)"
    if behavior_status == "failed":
        return "step tests failed, by exit code only (not checked per case)"
    return DM_NO_RESULT


def _finding_dm_lines(f: dict, n: int) -> set:
    """The 1-based done-means line numbers a review finding names in its optional "done_means" field: one
    number or a list of them (the shapes "proves" takes). Anything that is not a real line of this plan (a
    string, a bool, 0, a number past the last line) names nothing here and is ignored by the final review's
    done-means table; the blocking rule in `names_done_means` (CP3) does not ignore such a number, so that
    finding still blocks its round and is shown as written."""
    v = f.get("done_means")
    vals = v if isinstance(v, list) else [v]
    return {x for x in vals if isinstance(x, int) and not isinstance(x, bool) and 1 <= x <= n}


def _dm_case_reason(c: dict) -> str | None:
    """Why one linked case does not prove its line, or None when it does (passed, passed by exit code only, or
    checked by a passed UI gate). A failed case says failed (by exit code only when that is all that is known),
    a case with nothing recorded says it has no result, a browser case no UI gate passed for says so."""
    st, cid = c.get("status") or "", c.get("id")
    if st in ("passed", "checked by the UI gate") or st.startswith("step tests passed"):
        return None
    if st.startswith("shortcut table"):
        return f"{cid}: {st}"
    if st == DM_NO_UI_GATE:
        return f"{cid} is a browser test and no UI gate checked it"
    if st.startswith("step tests failed"):
        return f"{cid} failed, by exit code only (the step's tests were not checked per case)"
    if st == "failed":
        return f"{cid} failed"
    return f"{cid} has no result"  # DM_NO_RESULT, or any status this function does not know


def _done_means_proof(ctx, plan, cps_map: dict | None = None, older_plan_note: bool = True) -> dict | None:
    """None when the plan has no objective.done_means at all (an older plan, approved before either existed):
    the receipt prints a plain note instead of this section (`_dm_none_note`: NO_OBJECTIVE_NOTE for a plan with
    no objective, DM_NO_LINES_NOTE for an objective with no done_means lines). Otherwise {"lines": [{"number", "text",
    "cases": [{"id", "title", "file", "status", "result"}], "verdict", "reasons"}], "any_proves": bool}; "any_proves"
    is False only when not one case anywhere in the plan names a "proves" line (an old test plan from before that
    field existed), so the receipt and the final review can add one plain note instead of pretending they
    checked. "result" is the same text as "status". `verdict` is the one verdict every consumer shares (the
    final review's table in `status` and `status --json`'s "done_means_table", and the receipt): "proven" when
    the line has at least one linked case, every linked case passed (per case, or by exit code only, or checked
    by a passed UI gate) and no open finding names the line; otherwise "unproven", with one plain string in
    `reasons` for each cause (`done_means_table` and cmd_receipt then turn an unproven line the user accepted
    into "accepted" through `_apply_accepted_lines`, CP5; this function never reads state's `accepted_lines`):
    "no test linked", a linked case that failed / has no result / is a browser case no UI gate checked, and each
    open finding that names the line in its "done_means" field. When "any_proves" is
    False and `older_plan_note` is True (the default) every line's `verdict` is None and `reasons` is [] (an older
    plan is not "unproven", it was never linked), so no consumer reads a verdict that was never computed. With
    `older_plan_note=False` (a plan approved under the done-means rules, `_approved_after_dm`: `done_means_table`
    and the receipt pass it) the verdicts stay, so every line with no case is "unproven" ("no test linked") even
    when no case anywhere links a line any more (links removed after approval, CP4 round 2). An open finding is
    exactly an entry `left_for_later` lists (so this agrees with `ratchet.py deferred`). `cps_map` (the run
    state's own checkpoint-by-id dict, passed by the caller) feeds each case's checkpoint's recorded behavior-
    and UI-gate status into _dm_case_status, and supplies the findings."""
    obj = plan.get("objective") if isinstance(plan, dict) else None
    dm = obj.get("done_means") if isinstance(obj, dict) else None
    if not isinstance(dm, list) or not dm:
        return None
    lines = [{"number": i, "text": t, "cases": []} for i, t in enumerate(dm, 1)]
    any_proves = False
    cps_map = cps_map or {}
    for cp in plan.get("checkpoints") or []:
        gates = (cps_map.get(cp["id"]) or {}).get("gates") or {}
        behavior_status = (gates.get("behavior") or {}).get("status")
        ui_status = (gates.get("ui") or {}).get("status")
        for case in (test_plan(ctx, cp["id"]) or {}).get("cases") or []:
            for p in _proves_values(case):
                if isinstance(p, int) and not isinstance(p, bool) and 1 <= p <= len(dm):
                    any_proves = True
                    status = _dm_case_status(ctx, cp["id"], case, behavior_status, ui_status)
                    lines[p - 1]["cases"].append({"id": case.get("id"), "title": case.get("title", ""),
                                                  "file": case.get("file", ""), "status": status,
                                                  "result": status})
    findings = [f for c in cps_map.values() for f in left_for_later(c)]
    for line in lines:
        reasons = [r for r in (_dm_case_reason(c) for c in line["cases"]) if r] or (
            [] if line["cases"] else ["no test linked"])
        for f in findings:
            if line["number"] in _finding_dm_lines(f, len(dm)):
                reasons.append(f"open finding {_finding_key(f)}: {(f.get('description') or '').strip()[:240]}")
        line["verdict"], line["reasons"] = ("unproven" if reasons else "proven"), reasons
        if not any_proves and older_plan_note:
            # an older test plan (no case names a line): nothing was checked, so no line is proven or unproven;
            # every output (status, the receipt, receipt --json) then shows the one older-plan note instead
            line["verdict"], line["reasons"] = None, []
    return {"lines": lines, "any_proves": any_proves}


def _dm_none_note(plan) -> str:
    """The plain note for a plan _done_means_proof returns None for: NO_OBJECTIVE_NOTE when the plan states no
    objective at all, DM_NO_LINES_NOTE when it has an objective with no done_means lines."""
    obj = plan.get("objective") if isinstance(plan, dict) else None
    return DM_NO_LINES_NOTE if isinstance(obj, dict) and obj else NO_OBJECTIVE_NOTE


def _plan_as_approved(plan, st) -> dict:
    """`plan` with its objective replaced by the one the user approved (st["approved"]["objective"], written by
    approve-plan and refreshed only by plan-extend), when that snapshot has a done_means list. The final review's
    table (`done_means_table`), the finish check (`_finish_blockers`), `_final_review_lines` and the receipt all
    read the done-means lines through this, so an edit to checkpoints.json after approval (a line dropped,
    reworded or reordered) changes nothing they show or decide. A run with no approval yet, or whose approved plan
    had no objective or no done_means list, reads the plan as it is."""
    obj = (st.get("approved") or {}).get("objective")
    if not isinstance(plan, dict) or not isinstance(obj, dict) or not isinstance(obj.get("done_means"), list):
        return plan
    return {**plan, "objective": obj}


def _plan_for_briefs(plan, st) -> dict:
    """The plan whose objective `plan-summary`, `brief`, the adversarial `how` prompt and the sub-agent launch guard
    render (through `objective_brief`): once the plan is approved and the run is building or pausing, the APPROVED
    done-means lines (`_plan_as_approved`), so a brief or reviewer prompt never shows an edited checkpoints.json
    line under a number the final review's table and `_finish_blockers` read differently (a finding's
    `done_means: [2]` then names the same line everywhere). While planning (no approval yet) or in
    `planning_feedback` (the planner appends lines that plan-extend has not approved yet) it is the plan as it is,
    so a brief for the extend planner and plan-summary show the new lines. `st` may be {} or None."""
    st = st or {}
    if st.get("phase") in ("planning", "awaiting_plan_approval", "planning_feedback"):
        return plan
    return _plan_as_approved(plan, st)


def _lines_word(nums) -> str:
    """'line 2' or 'lines 2, 3': the plain words for a list of 1-based done-means line numbers."""
    nums = list(nums)
    return "line" + ("s " if len(nums) != 1 else " ") + ", ".join(str(x) for x in nums)


def _accepted_lines(st) -> dict:
    """CP5: the done-means lines the user (or the director, in an enrolled lane) accepted as unproven with
    `accept-line`, by 1-based line number: {n: {"number", "text", "reason", "accepted_by", "accepted_at",
    "covered"}} ("covered": the line's `reasons` at the moment it was accepted, what the acceptance covered), read
    from state.json's `accepted_lines` (a dict keyed by the line number as a string, written by cmd_accept_line
    only). {} when none, or when the key has some other shape. Read by `_apply_accepted_lines` and
    `_ask_accept_line` (a line that reads "accepted" cannot be asked about again; one held again can)."""
    acc = st.get("accepted_lines")
    out = {}
    if not isinstance(acc, dict):
        return out
    for k, v in acc.items():
        try:
            n = int(k)
        except (TypeError, ValueError):
            continue
        if isinstance(v, dict):
            out[n] = v
    return out


HELD_AGAIN_PREFIX = "held again: "


def _apply_accepted_lines(st, lines: list) -> list:
    """CP5: marks the accepted lines in a `_done_means_proof` lines list, in place, and returns it. An entry whose
    verdict is "unproven" and whose number the user accepted (`_accepted_lines`) gets verdict "accepted" and an
    "accepted" record {"reason", "accepted_by", "accepted_at", "covered"} ONLY while every one of its current
    `reasons` is in the record's "covered" list (the reasons at accept time): its `reasons` stay (what the
    acceptance covered, printed by `_accepted_line_text`). A line that is unproven for a reason the acceptance did
    not cover (a linked test that failed since, a NEW open finding naming the line, a link removed) is HELD AGAIN:
    it keeps verdict "unproven", gets an "accepted_earlier" record and one more plain reason string starting with
    HELD_AGAIN_PREFIX that names the earlier acceptance, what it covered and what is new, so status, status --json,
    the receipt, `_finish_blockers` and every refusal built on them show it, and `ask accept-line` may be run for
    it again. A record without "covered" (none is written any more) covers whatever holds the line. A line that is
    proven stays "proven" even when it was accepted earlier (the tests prove it now), and a line never accepted is
    untouched, so acceptance is per line and never a blanket flag. The one place the verdict "accepted" is made:
    `done_means_table` (status, status --json, `_finish_blockers`, which then no longer holds the finish on that
    line) and cmd_receipt both call it."""
    acc = _accepted_lines(st)
    for e in lines:
        rec = acc.get(e.get("number"))
        if not rec or e.get("verdict") != "unproven":
            continue
        record = {k: rec.get(k) for k in ("reason", "accepted_by", "accepted_at", "covered")}
        covered = rec.get("covered")
        reasons = e.get("reasons") or []
        new = [r for r in reasons if r not in covered] if isinstance(covered, list) else []
        if not new:
            e["verdict"] = "accepted"
            e["accepted"] = record
            continue
        who = "the director" if rec.get("accepted_by") == "director" else "the user"
        e["accepted_earlier"] = record
        why = " ".join(str(rec.get("reason") or "").split())
        e["reasons"] = list(reasons) + [
            f"{HELD_AGAIN_PREFIX}{who} accepted this line on {rec.get('accepted_at') or '?'} (reason: {why}) when "
            f"it was held by: {'; '.join(covered) or 'nothing'}; that acceptance does not cover what holds it now: "
            f"{'; '.join(new)}"]
    return lines


def done_means_table(ctx, plan, st):
    """The final review's done-means table, one source for plain `status`, `status --json`'s "done_means_table",
    the receipt and the finish check (`_finish_blockers`): the list of per-line entries from _done_means_proof
    ("number", "text", "verdict", "cases", "reasons"; verdict "accepted" with an "accepted" record for an unproven
    line the user accepted, `_apply_accepted_lines`, CP5), or one plain note string instead of a list when there is
    nothing to tabulate (no objective at all: NO_OBJECTIVE_NOTE; an objective with no done-means lines:
    DM_NO_LINES_NOTE; no test linked to any line on an OLDER plan: DM_NO_TESTS_NOTE). The lines are the
    APPROVED ones (`_plan_as_approved`), never a later edit of checkpoints.json. A plan approved under the
    done-means rules (`_approved_after_dm`) always gets the list: when no case links a line any more (every
    `proves` link removed after approval) each line is "unproven" with "no test linked", so the finish check
    (`_unproven_finish_lines`) holds on every line instead of reading a note as nothing to block."""
    plan = _plan_as_approved(plan, st)
    marked = _approved_after_dm(st)
    dm = _done_means_proof(ctx, plan, st.get("checkpoints") or {}, older_plan_note=not marked)
    if dm is None:
        return _dm_none_note(plan)
    return _apply_accepted_lines(st, dm["lines"]) if dm["any_proves"] or marked else DM_NO_TESTS_NOTE


def _finish_pending(st) -> bool:
    """True at the pause whose approval would mark the run done: the final review (`awaiting_final_review`), or a
    step review in human_review `each` mode when no step is left to build (that approval finishes the run, see
    cmd_human_approve). False at every other pause, so a step review mid-run, a blocked round or a building run
    is never judged by the finish rule."""
    phase = st.get("phase")
    if phase == "awaiting_final_review":
        return True
    if phase == "awaiting_checkpoint_review":
        cps = st.get("checkpoints") or {}
        return bool(cps) and all((c or {}).get("status") == "done" for c in cps.values())
    return False


def _unproven_finish_lines(ctx, st) -> list:
    """The final review table's entries whose verdict is "unproven" (a linked test failed or has no result, a
    browser case no UI gate checked, no test linked, or an open finding names the line), read from the approved
    lines (`done_means_table`); a line the user accepted reads "accepted" there (CP5), so it is not in this list,
    while a line held again after its acceptance (a reason the acceptance did not cover) is. [] when the table is
    a plain note instead (no objective, no done-means lines, or
    an OLDER plan whose tests link to no line; a plan under the done-means rules whose links were all removed
    gets every line as unproven instead, never a note) or every line is proven. Shared by `_finish_blockers` and
    `_finish_legacy_note`, so the block and the older-run note judge the same lines."""
    table = done_means_table(ctx, ctx.plan() or {"checkpoints": []}, st)
    if not isinstance(table, list):
        return []
    return [e for e in table if e.get("verdict") == "unproven"]


def _finish_blockers(ctx, st) -> list:
    """CP4: the done-means lines that hold the finish, one table entry each ("number", "text", "cases",
    "reasons"), or [] when the run may be marked done. Non-empty only for a plan approved under the done-means
    rules (`_approved_after_dm`) with at least one unproven line; a run approved before this change
    (no marker) never blocks here and gets `_finish_legacy_note` instead. A line the user accepted with
    `accept-line` (CP5, verdict "accepted") no longer holds the finish; every other unproven line still does,
    including an accepted line held again by a reason the acceptance did not cover (`_apply_accepted_lines`: its
    entry carries the "held again" reason). One verdict, read at the moment it
    matters and never cached: cmd_human_approve (a chat yes and a director token alike, before any counter, gate
    or round changes, and only where the approval would finish the run: `_finish_pending`; its one state change
    is dropping a pending human-approve question, so a yes given before the line went unproven never finishes
    the run later), `_approval_question` (so `ask human-approve` prints no question while blocked), next_action,
    cmd_status_text / status_json (the lines and the ways forward), `plain_now` (the held-finish sentence),
    `waiting_question` (a pending human-approve question no longer waits), the prompt hook (`decide_prompt`:
    never a hint to ask or run human-approve while held) and cmd_complete's last-step move in human_review `none`
    mode (which then stops at the final review instead of finishing). The review-limit unblock path (phase
    `blocked`) never reads it."""
    if not _approved_after_dm(st):
        return []
    return _unproven_finish_lines(ctx, st)


def _finish_integrity_lines(ctx, st) -> list[str]:
    """CP4: what the agent is told at the finish pause (`_finish_pending`) when a file that decides the done-means
    verdicts changed after the user approved the plan: a test plan (tests/CPn.json, whose `proves` links the
    table reads as they are on disk, so an edit after approval could re-point a line at a passed case) or a
    checkpoint in checkpoints.json (the step the cases belong to). Compared through the approval snapshot's own
    "cps" and "tests" hashes against `approval_snapshot`, and NOTHING else `integrity_problems` watches: an edit
    to standards.md or the design file, a config rule, a custom reviewer, the spec, the host agent CLI or the
    review mode cannot change a verdict, so none of them holds the finish (they were never checked at this pause
    before CP4, and the building-phase `verify_integrity` still catches them where they matter). Only for a plan
    approved under the done-means rules (`_approved_after_dm`): a run approved before this change is never held
    here, so it finishes as before (objective line 7). Until the user confirms the change (`approve-changes`,
    after which the table reads the links they confirmed) or it is undone, the run cannot be marked done and the
    approval question is not asked. [] when nothing relevant changed, or for a run with no approval yet. Printed by
    cmd_status_text and next_action; the same text is the refusal in cmd_human_approve and `_approval_question`;
    `_finish_held` folds it into the one held-finish verdict plain_now, waiting_question and the prompt hook
    read."""
    snap = st.get("approved")
    if not snap or not _approved_after_dm(st):
        return []
    now_ = approval_snapshot(ctx, st)
    probs = [f"checkpoint {cid} in checkpoints.json" for cid, h in snap.get("cps", {}).items()
             if now_["cps"].get(cid) != h]
    probs += [f"test plan tests/{cid}.json" for cid, h in snap.get("tests", {}).items()
              if now_["tests"].get(cid) != h]
    if not probs:
        return []
    return ["The run cannot be marked done yet: these changed after the user approved the plan: " + "; ".join(probs)
            + ". The done-means table reads each test plan's `proves` links and its step as they are now, so the "
            "approval question is not asked until the change is settled.",
            "Ways forward: undo the change, or show the user exactly what changed and run `ratchet.py ask "
            "approve-changes`; run `ratchet.py approve-changes` only if their first reply after it is a listed yes. "
            "Never ask them to approve the finish while this stands."]


def _finish_held(ctx, st) -> bool:
    """CP4: True when the finish pause (`_finish_pending`) is held for either reason: an unproven done-means line
    (`_finish_blockers`) or a checkpoint or test plan edited after approval (`_finish_integrity_lines`). The one
    verdict `plain_now` (the held sentence instead of an invitation to approve), `waiting_question` (a pending
    human-approve question no longer waits), the prompt hook (`decide_prompt`: never a hint to ask for or run the
    approval) and cmd_human_approve's pending-question drop read, so no output invites an approval that
    `human-approve` would refuse. False at every other pause."""
    return _finish_pending(st) and bool(_finish_blockers(ctx, st) or _finish_integrity_lines(ctx, st))


def _finish_legacy_note(ctx, st) -> str:
    """The plain note for a run approved before unproven lines blocked the finish: when its plan has no
    `done_means_rules` marker and at least one line is unproven, the one sentence `status` (at the finish
    pause) and `complete` (human_review `none`, last step) print instead of a block. "" for a plan under the
    done-means rules, or with nothing unproven."""
    if _approved_after_dm(st) or not _unproven_finish_lines(ctx, st):
        return ""
    return ("Note: this run's plan was approved before unproven done-means lines blocked the finish, so its "
            "unproven lines are shown but do not stop the run from being marked done.")


def _finish_block_lines(ctx, st, blockers: list) -> list[str]:
    """What the agent is told while `_finish_blockers` holds the finish (the human-approve and ask refusals,
    next_action, status and complete all print these same lines): that the run cannot be marked done yet, each
    blocking line by number and its approved text with its reasons (the table's own: "<id> failed", "<id> has no
    result", "open finding <key>: ..."), for each open finding the step it belongs to and the mark-fixed command
    that closes it once a clean review round confirms the fix, and the ways forward, one per kind of reason, each
    a path that really clears it: an open finding is closed with mark-fixed; a line with no test linked gets a
    step through feedback whose tests prove it; a linked test that failed, has no result, or is a browser case no
    UI gate checked sits in a step that is already done, whose tests are not re-run, so no new step can clear it
    (every test linked to a line must pass) and the agent is told to say so plainly instead of being sent down
    that path. Never an instruction to put the approval question to the user: that question is not asked while a
    line is unproven. CP5: also the one way the user themselves can release a line (`ask accept-line <n>`, their
    own `accept: <reason>` reply, or a director token in an enrolled lane) and, while that question is waiting
    (`waiting_question`), one line saying so, so `next` and `status` name what the run waits for; once the reply
    has landed (the question no longer waits, `pending` still accept-line), one line pointing at `accept-line` to
    record it, never back at `ask accept-line`."""
    n = len(blockers)
    out = [f"The run cannot be marked done yet: {n} done-means line{'s are' if n != 1 else ' is'} unproven, so the "
           "finish is held and the approval question is not asked."]
    q = waiting_question(ctx, st)
    p = st.get("pending") if isinstance(st.get("pending"), dict) else {}
    if q and q.get("kind") == "accept-line":
        out.append(f"A question to accept {q.get('about') or 'a line'} as unproven is waiting for the user's reply "
                   "(exactly `accept: <reason>`, their first reply after it); when it arrives, run `ratchet.py "
                   "accept-line`.")
    elif p.get("action") == "accept-line" and not p.get("overtook"):
        # the reply landed (so the question no longer "waits") but accept-line has not read it yet: keep pointing
        # at the command that records it, never back at `ask accept-line` (a re-ask would ask the user again)
        about = _lines_word([i for i in (p.get("ids") or []) if isinstance(i, int)]) or "a line"
        out.append(f"The user has replied to your question to accept {about} as unproven: run `ratchet.py "
                   "accept-line` now to record it (it accepts only a first reply in the exact form "
                   "`accept: <reason>`; any other first reply closes the question). Do not ask it again first.")
    cps = st.get("checkpoints") or {}
    dm_n = len(_approved_done_means(st)) or max((int(e.get("number") or 0) for e in blockers), default=0)
    unlinked, stuck = [], []
    for e in blockers:
        reasons = e.get("reasons") or []
        out.append(f"  - line {e['number']}: \"{e['text']}\": {'; '.join(reasons) or 'unproven'}")
        for cid, c in cps.items():
            for f in left_for_later(c):
                if e["number"] in _finding_dm_lines(f, dm_n):
                    key = _finding_key(f)
                    out.append(f"    finding {key} on {cid} is open: fix it, get a clean review round, then run "
                               f"`ratchet.py mark-fixed {cid} {key}=\"<how it was fixed>\"`.")
        if "no test linked" in reasons:
            unlinked.append(e["number"])
        if any(not r.startswith(("open finding ", HELD_AGAIN_PREFIX)) and r != "no test linked" for r in reasons):
            stuck.append(e["number"])

    _lines = _lines_word
    out.append("Ways forward: tell the user plainly which lines are unproven and why. An open finding is closed with "
               "mark-fixed as above. If the user asks for changes, `ratchet.py feedback` is still open. A line is "
               "proven only when every test linked to it passed and no open finding names it.")
    if unlinked:
        out.append(f"  {_lines(unlinked)}: no test is linked, so if the user asks for the work, run `ratchet.py "
                   "feedback` and plan a step whose tests prove the line.")
    if stuck:
        out.append(f"  {_lines(stuck)}: a linked test failed, has no result or is a browser test no UI gate checked, "
                   "in a step that is already done. A done step's tests are not re-run and every test linked to a "
                   "line must pass, so a new step cannot clear this: do not offer one for it. Say so plainly.")
    out.append("  If the user decides a line may stay unproven, run `ratchet.py ask accept-line <n>[,<n>]` and show the "
               "question it prints; only their own first reply `accept: <reason>` (in a director-enrolled lane, a "
               "director token with --reason) accepts it, and an accepted line no longer holds the finish. You "
               "cannot accept a line yourself.")
    return out


def cmd_receipt(args):
    """`ratchet.py receipt` (plain markdown, or `--json`): one honest proof receipt to paste into the pull
    request. Each step's title, short commit and elapsed time, the whole run's own elapsed time (wall-clock,
    including any time spent waiting on you; never cost or tokens), who reviewed each step (a host-company
    fallback marked as such, with why when Ratchet recorded it), the findings you accepted with their reason, and
    findings left for later or fixed later in the run (CP1's own `left_for_later`/`_fixed_later` rule, so this
    always agrees with `ratchet.py deferred` and `status`). Also the done-means proof (`_done_means_proof`): every
    objective line with the tests linked to it and their results, a proven / unproven verdict and a "Why
    unproven:" line per unproven line, the same verdicts `status` shows; a line the user accepted
    (`_apply_accepted_lines`, CP5) reads "accepted" with who accepted it, what held it and their reason in place
    of its tests (`_accepted_line_text`), and one held again after its acceptance reads unproven with the "held
    again" reason. A plan whose tests link to no line
    (an older plan) gets one plain note instead of verdicts (`--json` then carries `verdict: null` on each
    line); a plan with no objective, or an objective with no done-means lines, gets its own plain note."""
    ctx = Ctx(find_root())
    st = ctx.state()
    cfg = ctx.config()
    plan = ctx.plan() or {"checkpoints": []}
    cps_map = st.get("checkpoints") or {}
    run_status, run_seconds = _run_elapsed(st)
    steps = []
    for cp in plan.get("checkpoints") or []:
        cid = cp.get("id")
        cps = cps_map.get(cid) or {}
        status, seconds = _step_elapsed(cps)
        steps.append({"id": cid, "title": cp.get("title", "?"), "commit": _step_commit(ctx, cps),
                      "finished": status == "finished", "status": status, "elapsed_seconds": seconds,
                      "reviewers": _step_reviewer_entries(cfg, cps)})
    accepted, left, fixed = _receipt_accepted(st), _receipt_left_for_later(st), _receipt_fixed_later(st)
    # the approved lines, as status shows them; a plan under the done-means rules keeps its verdicts even with
    # no link left anywhere (every line then reads "unproven", as the finish check judges it)
    judged = _approved_after_dm(st)
    dm = _done_means_proof(ctx, _plan_as_approved(plan, st), cps_map, older_plan_note=not judged)
    judged = judged or bool(dm and dm["any_proves"])
    if dm is not None and judged:
        _apply_accepted_lines(st, dm["lines"])
    labels = {"changes_approved": lambda e: "approve-changes",
              "round_limit_raised": lambda e: f"raise-limit {e.get('cp')}",
              "choice_made": lambda e: f"choice {e.get('letter')}",
              "finding_accepted": lambda e: f"accept-finding {e.get('cp')} ({', '.join(e.get('ids') or [])})"}
    policy_signed = [{"approval": labels.get(e["event"], lambda x: e["event"])(e), "policy_rule": e["policy_rule"]}
                     for e in st.get("history") or [] if e.get("policy_rule")]
    if getattr(args, "json", False):
        data = {"run": {"elapsed_seconds": run_seconds, "finished": run_status == "finished"},
                "steps": [{k: s[k] for k in ("id", "title", "commit", "finished", "elapsed_seconds", "reviewers")}
                         for s in steps],
                "accepted": accepted, "left_for_later": left, "fixed_later": fixed, "done_means": dm,
                "shortcut_tables": _sc_saved(ctx)["tables"]}
        if policy_signed:
            data["policy_approvals"] = policy_signed
        print(json.dumps(data, indent=2))
        return
    print(f"# Proof receipt: {plan.get('feature') or st.get('feature') or st.get('slug')}")
    print("")
    print("Steps (time is wall-clock, including any time spent waiting on you):")
    for s in steps:
        commit_txt = s["commit"] or "no commit recorded"
        dur_txt = _plain_duration(s["elapsed_seconds"])
        time_txt = dur_txt if s["finished"] else (
            "not started" if s["status"] == "not started" else f"not finished (time so far: {dur_txt})")
        print(f"- {s['id']} {s['title']}: commit {commit_txt}, time {time_txt}")
        for e in s["reviewers"]:
            print(_reviewer_line(e))
    print("")
    run_dur = _plain_duration(run_seconds)
    run_txt = run_dur if run_status == "finished" else f"run not finished (time so far: {run_dur})"
    print(f"Whole run time: {run_txt}")
    print("")
    if dm is None:
        print(f"Done-means proof: {_dm_none_note(plan)}.")
    else:
        print("Done-means proof (which tests prove each objective line):")
        for i, line in enumerate(dm["lines"], 1):
            print(f"{i}. {line['text']}" + (f" - {line['verdict']}" if judged else ""))
            if judged and line["verdict"] == "accepted":
                print(f"   {_accepted_line_text(line, with_ids=False)}")
                continue
            if not line["cases"]:
                print("   - no test linked")
            else:
                for c in line["cases"]:
                    print(f"   - {c['id']} {c['title']} ({c['file']}): {c['status']}")
            if judged and line["reasons"]:
                print(f"   Why unproven: {'; '.join(line['reasons'])}")
        if not judged:
            print("Note: this plan's tests were never linked to done_means lines (an older test plan, "
                  "approved before the \"proves\" field existed).")
    if policy_signed:
        print("")
        print("Approvals the director signed under the developer's policy:")
        for pa in policy_signed:
            print(f"- {pa['approval']}: {pa['policy_rule']}")
    sc_lines = _sc_block_lines(_sc_saved(ctx))
    if sc_lines:
        print("")
        for line in sc_lines:
            print(line)
    acc_lines = _accepted_findings_lines(st)
    if acc_lines:
        print("")
        for line in acc_lines:
            print(line)
    if fixed:
        print("")
        print(f"{len(fixed)} finding(s) fixed later in the run (a later round reviewed the change):")
        for f in fixed:
            print(f"- {f['checkpoint']} {_finding_key(f)}: {(f.get('description') or '').strip()[:240]} "
                  f"[fixed in round {f.get('round')}: {f.get('how', '')}]")
    if left:
        print("")
        print(f"{len(left)} finding(s) left for later (they did not block):")
        for f in left:
            why = f" [{f['deferred_because']}]" if f.get("deferred_because") else ""
            print(f"- {f['checkpoint']} {_finding_key(f)}: {(f.get('description') or '').strip()[:240]}{why}")
    if not (acc_lines or fixed or left):
        print("")
        print("No findings were accepted, left for later or fixed later in this run.")


def _warn_if_foreground(ctx, cfg, what="complete", rerun=True):
    """`what` (complete, or integrate) runs the whole regression suite. Unless the guard hook noted that the host runs
    this exact call in the background, say first (stderr, flushed) that a tool timeout could cut it off. No note, or
    a note that does not say, counts as foreground. `rerun`: complete may run the suite a second time after a failure.
    Never changes what the command does."""
    note = _noted_session(ctx.root, what, whole=True)
    if not note and what == "integrate":
        # the guard notes the call under the folder it was run from (a director's own folder, reaching main with
        # --root), not under main
        here = find_root(Path.cwd())
        if here.resolve() != ctx.root.resolve():
            note = _noted_session(here, what, whole=True)
    if note and note.get("bg") is True:
        return
    secs = int(cfg.get("test_timeout_sec") or DEFAULT_CONFIG["test_timeout_sec"])
    span = f"{secs // 60} minutes" if secs >= 120 else f"{secs} seconds"
    stretch = _load_stretch_max(cfg)
    again = (", and after a failure it may run the suite a second time, so up to about twice that" if rerun else "")
    print(f"WARNING: a tool timeout could cut this {what} call off. It runs the whole regression suite, which "
          f"can take up to {span} (up to {_secs(stretch)} times that on a heavily loaded machine, load_stretch_max){again}. "
          f"Run it in the background instead (run_in_background), then wait for it to finish.",
          file=sys.stderr, flush=True)


def cmd_complete(args):
    ctx = Ctx(find_root())
    st = ctx.state()
    cps = _cur(ctx, st, args.cp)
    _expect_step(cps, ["complete"], args.cp)
    cp = cp_by_id(ctx.plan(), args.cp)
    cfg = ctx.config()
    if cfg.get("regression_command"):
        _warn_if_foreground(ctx, cfg)
    fp = fingerprint(ctx.root)
    problems, stale = [], []
    doc_edits = set()  # CP2 doc quick path: files found doc-only since behavior or adversarial passed, used only
    # to pick which doc tests replace the staleness check -- never, on its own, a "not re-reviewed" record.
    doc_edits_unreviewed_now = set()  # only files the ADVERSARIAL gate's own diff found doc-only: that gate's
    # approval is the review the commit message/status/final review claim, so only this set is ever folded into
    # cps["doc_edits_unreviewed"]. A file the behavior branch finds doc-only (to avoid the staleness block and
    # help pick doc tests) is never added here on its own -- the adversarial round may since have reviewed and
    # approved that exact edit (behavior always passes before the adversarial round opens). When the
    # adversarial gate isn't required, this set stays empty and nothing is recorded as unreviewed from here.
    for name in ["behavior", "ui", "adversarial"]:
        g = cps["gates"][name]
        if not g["required"]:
            continue
        if g["status"] != "passed":
            problems.append(f"{name} gate is {g['status']}")
            stale.append(name)
            continue
        gfp = g.get("fingerprint") or {}
        if gfp.get("id") == fp["id"]:
            continue
        # The fingerprint never reads Ratchet's folder from the working tree, only from HEAD: a difference there alone
        # is a checkpoint commit (its shared .ratchet files) made by an earlier `complete` that failed before it
        # could save, not a change to the reviewed code. The rerun then finds that commit instead of making another.
        chat_paths = _chat_transcript_paths(ctx, g.get("passed_at"))
        changed = [f for f in changed_files(ctx.root, gfp, fp) if f != RATCHET_DIR and not f.startswith(RATCHET_DIR + "/")
                  and f not in chat_paths]
        if not changed:
            continue
        if name == "behavior":
            doc_files, code_files = _classify_doc_code(cfg, changed)
            if not code_files and cfg.get("doc_test_command"):
                doc_edits.update(doc_files)
                continue
            problems.append(f"code changed since behavior passed ({len(changed)} files) → re-run ratchet.py behavior {args.cp}")
            stale.append(name)
        elif name == "ui":
            ui_changed = touches_ui(changed, cfg["ui_globs"])
            if ui_changed:
                problems.append(f"UI files changed since UI review ({', '.join(ui_changed[:5])}) → re-run ratchet-ui-compare")
                stale.append(name)
        elif name == "adversarial":
            doc_files, code_files = _classify_doc_code(cfg, changed)
            if not code_files and cfg.get("doc_test_command"):
                doc_edits.update(doc_files)
                doc_edits_unreviewed_now.update(doc_files)
                continue
            problems.append("code changed since adversarial approval → adversaries must review the final code")
            stale.append(name)
    if problems:
        for name in stale:
            if cps["gates"][name]["status"] == "passed":
                cps["gates"][name]["status"] = "stale"
        cps["step"] = stale[0]  # behavior < ui < adversarial order is preserved
        ctx.log(st, "complete_rejected", cp=args.cp, stale=stale)
        ctx.save_state(st)
        die(f"{args.cp} cannot complete:\n  - " + "\n  - ".join(problems), 2)
    if doc_edits:
        # CP2 doc quick path: every file changed since behavior/adversarial passed is a doc, so neither gate was
        # marked stale above. Run only the test files that name those docs (never the full suite for this); a
        # failure here leaves the gates' status exactly as it was and commits nothing, same as any other failed
        # check below.
        doc_test_files = _tests_naming(ctx, cfg, fp, sorted(doc_edits))
        if doc_test_files:
            dcode, dout = _run_doc_test_command(ctx, cfg, doc_test_files, ctx.evidence(args.cp) / "doc-tests.log")
            if dcode != 0:
                die(f"{args.cp} cannot complete: a doc test failed for the doc edit(s) made after review "
                    f"({', '.join(sorted(doc_edits))}):\n  - " + "\n  - ".join(doc_test_files) + f"\n{_tail(dout)}", 2)
            if fingerprint(ctx.root)["id"] != fp["id"]:
                die("The doc test command changed files in the project. Those changes were never reviewed — find "
                    "out what wrote them (generated files? snapshots?) and either add them to .gitignore or "
                    "re-run the gates.", 2)
        # Only files the ADVERSARIAL gate's own diff found doc-only (`doc_edits_unreviewed_now`) are ever
        # recorded as "not re-reviewed": a file the behavior branch alone found doc-only may since have been
        # reviewed and approved in the adversarial round itself, so it is never recorded here just for that.
        if doc_edits_unreviewed_now:
            cps["doc_edits_unreviewed"] = sorted(set(cps.get("doc_edits_unreviewed") or []) | doc_edits_unreviewed_now)
        ctx.log(st, "doc_quick_path", cp=args.cp, files=sorted(doc_edits), tests=doc_test_files)
    skip_full, full_doc_files = _skip_full_suite(ctx, cfg, st, fp) if cfg.get("regression_command") else (False, [])
    if skip_full:
        # Already passed on a tree that differs from now only in docs: run just those docs' naming tests
        # instead of the full suite again. `full_doc_files` only selects which tests replace the full suite; it
        # is never added to `doc_edits_unreviewed` (a file here may already have gone through, and passed, its
        # own gate's normal adversarial round, so it was never actually skipped from review).
        full_doc_tests = _tests_naming(ctx, cfg, fp, full_doc_files) if full_doc_files else []
        if full_doc_tests:
            dcode, dout = _run_doc_test_command(ctx, cfg, full_doc_tests,
                                                ctx.evidence(args.cp) / "doc-tests-full-suite.log")
            if dcode != 0:
                die(f"{args.cp} cannot complete: the full suite already passed on a tree that differs only in "
                    f"docs, but a doc test failed for {', '.join(full_doc_tests)}:\n{_tail(dout)}", 2)
            if fingerprint(ctx.root)["id"] != fp["id"]:
                die("The doc test command changed files in the project. Those changes were never reviewed — find "
                    "out what wrote them (generated files? snapshots?) and either add them to .gitignore or "
                    "re-run the gates.", 2)
    if cfg.get("regression_command") and not skip_full:
        # The related pass runs only here, when the full suite is about to run: a break in the step's own,
        # changed or naming test files stops the step in seconds, before the suite; it never replaces the suite.
        # the code under the run: an edit to it while the related pass, the suite or its re-run runs stops that
        # command and ends here with nothing saved (see _run_cmd); the gates above were checked against `fp`
        watch = _Watch(ctx, fp, _watch_every(cfg), f"complete {args.cp}", extra=cfg.get("fingerprint_include") or [])
        _run_related_tests(ctx, cfg, cp, cps, fp, watch)
        code, out, _ = _run_cmd(ctx, cfg["regression_command"], ctx.evidence(args.cp) / "regression.log",
                                cfg["test_timeout_sec"], watch=watch)
        if code != 0 and not st.get("regression_flaky_used"):
            # The run's own one-time allowance (not per-step): a regression failure that passes on one
            # immediate automatic re-run is flaky, never spending this; a second one anywhere is never
            # forgiven. Spent the moment this retry is attempted, win or lose, so a later failed complete call
            # never gets its own free retry just because this one's retry also failed.
            st["regression_flaky_used"] = True
            code2, out2, _ = _run_cmd(ctx, cfg["regression_command"],
                                      ctx.evidence(args.cp) / "regression-retry.log", cfg["test_timeout_sec"],
                                      watch=watch)
            if code2 == 0:
                code, out = code2, out2
                cps["regression_flaky"] = True
        if code != 0:
            print(_tail(out))
            die(f"Regression suite failed (exit {code}) — an earlier behaviour broke. Fix before completing.", 2)
        if fingerprint(ctx.root)["id"] != fp["id"]:
            die("The regression command changed files in the project. Those changes were never reviewed — find out "
                "what wrote them (generated files? snapshots?) and either add them to .gitignore or re-run the gates.", 2)
        st["regression_passed_fp"] = fp
    if cp.get("guardrail"):
        probs = verify_guardrail(ctx, st, cp, cps, fp, cfg)
        if probs:
            cps["guardrail_tries"] = int(cps.get("guardrail_tries", 0)) + 1
            if cps["guardrail_tries"] >= cfg["max_behavior_attempts"]:
                _set_blocked(st, f"{args.cp}: the new automatic check still fails Ratchet's own proof after "
                                 f"{cps['guardrail_tries']} tries — needs a human decision.")
            for g_ in ("behavior", "adversarial"):
                if cps["gates"][g_]["status"] == "passed":
                    cps["gates"][g_]["status"] = "stale"
            cps["step"] = "behavior"
            ctx.log(st, "guardrail_proof_failed", cp=args.cp, problems="; ".join(probs)[:400])
            ctx.save_state(st)
            die(f"{args.cp} cannot complete: Ratchet ran the new check itself and " + "; ".join(probs) + ". Give this "
                "to ratchet-implementer to fix the check (evidence/" + args.cp + "/guardrail has every run), then "
                "re-run the gates.", 2)
        _finish_guardrail(ctx, st, cp)  # before the commit, so the new check's config entry is committed with it
    spec_files, spec_notes = _spec_write_back(ctx, st, cp, fp, cps.get("base_tree"))  # tick the step's tasks in the spec tool's own files
    commit = None
    if cfg.get("commit_per_checkpoint") and _is_git(ctx.root):
        msg = f"ratchet({st['slug']}): {args.cp} {cp['title']}\n\n{cp['summary']}\n\nGates: " + ", ".join(
            f"{n}={cps['gates'][n]['status']}" for n in ["behavior", "ui", "adversarial"])
        if cp.get("spec_refs"):
            msg += "\nSpec: " + ", ".join(_as_list(cp["spec_refs"]))[:600]
        if cps.get("doc_edits_unreviewed"):
            msg += ("\nDocs edited after review and not re-reviewed (doc quick path): "
                    + ", ".join(cps["doc_edits_unreviewed"]))
        small_fix_line = _small_fix_review_line(args.cp, cps)
        if small_fix_line:
            msg += "\n" + small_fix_line
        for fix_round_line in _fix_round_lines_for(args.cp, cps):
            msg += "\n" + fix_round_line
        docs_only_skip_line = _docs_only_skip_line(args.cp, cps)
        if docs_only_skip_line:
            msg += "\n" + docs_only_skip_line
        commit = _commit_reviewed(ctx.root, cps.get("base_tree"), fp, msg, extra=spec_files)
        if not commit:  # nothing new to commit: a run of complete that failed after its commit left it at HEAD
            commit = _head_commit_named(ctx.root, msg)
    cps.update(status="done", completed_at=now(), commit=commit)
    # With no commit made, the reviewed tree (after the spec ticks) is what `merged` compares the lane's own commits with.
    reviewed = fingerprint(ctx.root) if not commit and _is_git(ctx.root) else {}
    # HEAD is recorded with it: `merged` uses it to tell a file that was never committed (untracked, then deleted)
    # from a file a lane commit removed.
    head_now = _head_sha(ctx.root) if reviewed.get("kind") == "git-tree" else ""
    ctx.log(st, "checkpoint_complete", cp=args.cp, commit=commit,
            **({"tree": reviewed["id"], **({"head": head_now} if head_now else {})}
               if reviewed.get("kind") == "git-tree" else {}))
    order = [c["id"] for c in ctx.plan()["checkpoints"]]
    remaining = [c for c in order if st["checkpoints"][c]["status"] != "done"]
    mode = st.get("human_review", "end")
    finish_lines: list[str] = []  # CP4: the held-finish lines or the older-run note, printed after the ok line
    if not remaining:  # CP6: the last step is done: run the shortcut tables (shown, never blocking)
        finish_lines += _sc_run_at_finish(ctx, st)
    if mode == "each":
        st["phase"] = "awaiting_checkpoint_review"
        st["awaiting_since"] = now()
        st["review_target"] = args.cp
    elif remaining:
        _advance(st, remaining[0], fingerprint(ctx.root)["id"], _head_sha(ctx.root))
    else:
        st["current"] = None
        # CP4: in human_review `none` the run finishes here, unless an approved done-means line is unproven: then
        # it stops at the final review like every other mode (a plan approved before this rule finishes with a
        # plain note instead). Read with the step already marked done, so this step's own results count.
        held = _finish_blockers(ctx, st) if mode == "none" else []
        st["phase"] = "awaiting_final_review" if mode != "none" or held else "done"
        st["awaiting_since"] = now()
        if st["phase"] == "done":
            spec_notes += _spec_finish(ctx, st)
            register_active(ctx.root, None)
            legacy = _finish_legacy_note(ctx, st) if mode == "none" else ""
            if legacy:
                finish_lines.append(legacy)
        if held:
            finish_lines.append("All steps are complete, but the run is not finished:")
            finish_lines += _finish_block_lines(ctx, st, held)
    ctx.save_state(st)
    if st["phase"] == "done":
        _ci_export_hint(ctx)
    build_viewer(ctx)
    ok(f"{args.cp} complete{f' (commit {commit})' if commit else ''}.")
    for n_ in spec_notes:
        print(n_ if n_.startswith("Offer:") else f"Spec: {n_}")
    for n_ in finish_lines:
        print(n_)
    print(json.dumps(next_action(ctx, st), indent=2))


def cmd_merged(args):
    """`merged`: between steps, after the agent merged main into the lane with git. Re-runs the earlier steps' checks
    on the merged code and, when they pass, moves the run's and the next step's starting tree to the merge commit (so
    reviewers and the step's commit see only that step's own changes) and makes standards, design-file and config-rule
    changes that are exactly main's version the new approved baseline. Anything else that changed stays unapproved.
    Approves nothing and asks nothing; ratchet never runs the merge itself."""
    ctx = Ctx(find_root())
    st = ctx.state()
    root, phase, cur = ctx.root, st.get("phase"), st.get("current")
    if phase == "building" and cur:
        if st["checkpoints"][cur].get("step") != "tests":
            die(f"{cur} is in the middle of its work (step '{st['checkpoints'][cur].get('step')}'). Finish {cur} "
                f"first (run it through complete), then merge main and run merged. Nothing was changed.")
    elif phase not in ("awaiting_checkpoint_review", "awaiting_final_review"):
        die(f"merged runs between steps, after a step is complete and before the next one starts (the run is in "
            f"phase '{phase}'). Nothing was changed.")
    if not _is_git(root):
        die("merged needs a git project: it checks the merge commit. Nothing was changed.")

    def git(*a):
        return subprocess.run(["git", *a], cwd=root, capture_output=True, text=True, timeout=60)

    if git("rev-parse", "-q", "--verify", "MERGE_HEAD").returncode == 0:
        die("A merge is not finished. Resolve the conflicts, finish the merge with a commit, then run merged. "
            "Nothing was changed.")
    sp = git("rev-parse", "--show-prefix")
    tl = git("rev-parse", "--show-toplevel")
    if sp.returncode != 0 or tl.returncode != 0:
        die("merged could not read where the project folder sits in the git repository "
            f"({(sp.stderr + tl.stderr).strip()[:200] or 'no answer'}). Nothing was changed.")
    # Paths here are repo-root-relative (the project folder may sit below the git root), the way git's index takes them.
    # Every git call below that takes or returns such paths runs from the repo top through tgit, so none of them
    # mixes them with project-relative ones. The two calls that take project-relative input (git here, git add of the
    # fingerprint_include names) say so.
    prefix, top = sp.stdout.strip(), Path(tl.stdout.strip())
    run_dir = prefix + RATCHET_DIR

    def tgit(*a, inp=None, env=None, text=True):
        return subprocess.run(["git", *a], cwd=top, capture_output=True, text=text and inp is None, input=inp, env=env,
                              timeout=60)

    def nul_paths(r):   # git's path lists come NUL-separated (-z): names with spaces or non-ASCII letters stay whole
        return [x.decode("utf-8", "surrogateescape") for x in r.stdout.split(b"\0") if x]

    dirty = [x[3:] for x in nul_paths(tgit("status", "--porcelain", "-z", "--no-renames", "--untracked-files=no", "--",
                                           prefix or ".", f":(exclude){run_dir}", text=False))]
    if dirty:
        die(f"Tracked files have edits that are not committed ({', '.join(dirty[:5])}). Undo them, or finish the "
            "step they belong to first (committing them now would be lane work no one reviewed), then run merged. "
            "Nothing was changed.")

    parents = git("rev-list", "--parents", "-n", "1", "HEAD").stdout.split()
    if len(parents) != 3:
        die("HEAD is not a finished merge of main into this lane. Merge main first (git merge --no-ff main), "
            "finish the merge, then run merged. Nothing was changed.")
    head, p1, p2 = parents
    tree = git("rev-parse", f"{head}^{{tree}}").stdout.strip()
    last = next((e for e in reversed(st.get("history") or [])
                 if e.get("event") in ("checkpoint_complete", "merged_main")), None)
    if last and last["event"] == "merged_main" and last.get("commit") == head:
        ok("This merge was already checked and accepted. Nothing to do.")
        return
    # Nothing may sit between the step's starting tree and the merge's first parent: that would be lane work no one
    # reviewed, and moving the starting tree would hide it from the reviewers.
    # While building, the step's starting tree is a fingerprint tree (it also holds the gitignored files named in
    # fingerprint_include, which no commit can hold). After an earlier merge accepted in this step, compare with that
    # merge's commit instead: its tree is what the lane's next merge starts from, hand-resolved files included.
    from_merge = bool(phase == "building" and cur and last and last["event"] == "merged_main" and last.get("commit"))
    if from_merge and last.get("by_hand"):
        die("An earlier merge in this step was resolved by hand, and that resolution is still waiting for this step's "
            "review. A second merge now would fold it into the starting tree and hide it from the reviewers. Finish "
            f"{cur} first (run it through complete), then merge main again and run merged. To get out now, undo the "
            f"second merge with `git reset --keep {p1[:7]}` (its first parent). Nothing was changed.")
    ref = st["checkpoints"][cur].get("base_tree") if phase == "building" and cur and not from_merge else (
        git("rev-parse", f"{last['commit']}^{{tree}}").stdout.strip() if last and last.get("commit") else None)
    fp_ref = bool(ref and phase == "building" and cur and not from_merge)  # a fingerprint tree, not a commit's tree
    if not ref and last and re.fullmatch(r"[0-9a-f]{40,64}", str(last.get("tree") or "")):
        ref, fp_ref = last["tree"], True   # complete made no commit (commit_per_checkpoint is false): the reviewed tree
    if not ref:
        undo = f"Run `git reset --keep {p1[:7]}` (the merge's first parent) to undo the merge. "
        die("merged cannot tell which work the last step's reviewers saw: that step finished without a commit and "
            "no reviewed tree was recorded for it (it finished before Ratchet recorded one). So it cannot check that "
            "the lane has no commits no step reviewed. Nothing was changed. " + undo
            + ("Then ask the user for a step of its own through feedback, and merge main once that step has started."
               if phase == "awaiting_final_review" else
               "Then get the waiting review approved, and merge main again once the next step has started."
               if phase == "awaiting_checkpoint_review" else
               "Then finish this step (complete), and merge main again once the next step has started."))
    loose = nul_paths(tgit("ls-files", "-z", "--others", "--exclude-standard", "--", prefix or ".",
                           f":(exclude){run_dir}", *JUNK_PATHSPECS, text=False))
    if phase == "building" and ref:   # the step's own new files (its tests) are its own changes; older ones are not
        in_ref = set(nul_paths(tgit("ls-tree", "-r", "-z", "--name-only", ref, text=False)))
        loose = [f for f in loose if f in in_ref]
    if loose:
        die(f"There are files git does not track yet ({', '.join(loose[:5])}). Commit them in a reviewed step, "
            "delete them, or add them to .git/info/exclude (not .gitignore: a new or edited .gitignore is itself "
            "an untracked file or lane work), then run merged: otherwise the next step's reviewers and commit "
            "would pick them up as its own changes. Nothing was changed.")
    if ref:
        own = [f for f in nul_paths(tgit("diff-tree", "-r", "-z", "--no-renames", "--name-only", ref,
                                         f"{p1}^{{tree}}", text=False))
               if f != run_dir and not f.startswith(run_dir + "/")]
        if own and fp_ref:   # a fingerprint tree also holds files no commit ever held (untracked, ignored ones)
            # Only a path some commit since the step's starting commit touched is a lane commit's work; the rest
            # (a stray untracked file, a gitignored file named in fingerprint_include) is not.
            if phase == "building":
                start = str(st["checkpoints"][cur].get("base_head") or "")
            else:
                start = str((last or {}).get("head") or "") if (last or {}).get("event") == "checkpoint_complete" else ""
            undo = f"Undo the merge with `git reset --keep {p1[:7]}` (the merge's first parent). "
            if not re.fullmatch(r"[0-9a-f]{40,64}", start) or git("cat-file", "-e", f"{start}^{{commit}}").returncode != 0:
                die("merged cannot tell which commits the lane made since the last step: this step's starting commit "
                    "was not recorded (the run began before Ratchet recorded it) or is gone. So it cannot check that "
                    "the lane has no commits no step reviewed. Nothing was changed. " + undo
                    + ("Then ask the user for a step of its own through feedback, and merge main once that step has "
                       "started." if phase == "awaiting_final_review" else
                       "Then get the waiting review approved, and merge main again once the next step has started."
                       if phase == "awaiting_checkpoint_review" else
                       "Then finish this step (complete), and merge main again once the next step has started."))
            anc = git("merge-base", "--is-ancestor", start, p1)
            if anc.returncode == 1:
                die(f"The lane's history no longer includes the commit this step started from ({start[:7]}): commits "
                    "were reset or rebased away since then, so merged cannot tell what the lane changed. Nothing was "
                    "changed. Undo the merge with git, put the lane's history back, then merge main and run merged.")
            if anc.returncode != 0:
                die(f"git could not compare the lane with the step's starting commit ({anc.stderr.strip()[:200]}). "
                    "Nothing was changed.")
            touched = []
            for f in own:
                r = tgit("rev-list", "-1", "--full-history", f"{start}..{p1}", "--", f":(literal){f}")
                if r.returncode != 0:
                    die(f"git could not list the lane's commits that touch {f} ({r.stderr.strip()[:200]}). "
                        "Nothing was changed.")
                if r.stdout.strip():
                    touched.append(f)
            own = touched
        if own:
            die(f"The lane has commits since the last step finished that never went through the gates "
                f"({', '.join(own[:5])}; added, changed or removed), so merged cannot hide them from the reviewers. "
                "Undo those commits (and the merge) with git, then merge main into the lane right after the last "
                "step's own commit. Nothing was changed.")

    # Files the agent changed while making the merge (a conflict resolved by hand, or anything the merge commit added
    # or removed on its own) are not main's or the lane's reviewed work. They are the paths whose merged mode and
    # content differ from git's own clean merge of the two parents. A clean automatic merge of a file both sides
    # edited in different places is not among them. A merge made with -X or -s options may show up here too; that is
    # safe (the files just go to the next step's review).
    def entries(rev):
        r = tgit("ls-tree", "-r", "-z", "--full-tree", rev, text=False)
        if r.returncode != 0:
            die(f"git ls-tree failed on the merge ({r.stderr.decode('utf-8', 'replace').strip()[:200]}). "
                "Nothing was changed.")
        out = {}
        for rec in r.stdout.split(b"\0"):
            if rec:
                meta, _, path = rec.partition(b"\t")
                mode, _, oid = meta.split(b" ")
                out[path] = (mode, oid)
        return out

    def in_run_dir(f):
        t = f.decode("utf-8", "replace")
        return t == run_dir or t.startswith(run_dir + "/")

    mt = git("merge-tree", "--write-tree", "--no-messages", p1, p2)
    clean = mt.stdout.split("\n")[0].strip() if mt.returncode in (0, 1) else ""
    if not re.fullmatch(r"[0-9a-f]{40}|[0-9a-f]{64}", clean):
        die("merged could not work out git's own clean merge of the two parents (`git merge-tree --write-tree` "
            f"needs git 2.38 or newer; this one said: {(mt.stderr or mt.stdout).strip()[:200] or 'nothing'}). "
            "Update git, then run merged. Nothing was changed.")
    e_m, e_c, e_2 = entries(head), entries(clean), entries(p2)
    by_hand = sorted(f for f in set(e_m) | set(e_c) if e_m.get(f) != e_c.get(f) and not in_run_dir(f))
    if by_hand and phase != "building":
        names = ", ".join(f.decode("utf-8", "replace") for f in by_hand[:10]) + (" and more" if len(by_hand) > 10 else "")
        die(f"This merge changed files beyond what git merges on its own ({names}): a conflict resolved by hand, or "
            "a merge made with -X or -s options. That code has to be reviewed with a step, and none is starting "
            f"(the run is in phase '{phase}'). Undo the merge with `git reset --keep {p1[:7]}` (not ORIG_HEAD, "
            "which later git commands can overwrite; --keep refuses instead of discarding edits to the run's files). "
            + ("Then get the waiting review approved, and merge main again once the next step has started. "
               if phase == "awaiting_checkpoint_review" else
               "Then either merge main again in a way git merges on its own, or ask the user for a step of its own "
               "for the resolution through feedback, and merge once that step has started. ")
            + "Nothing was changed.")
    # The step's starting tree is built the way every step's is (a fingerprint tree): the merge's tree plus the
    # git-ignored files named in fingerprint_include, so those never show up as the step's own change. The paths the
    # agent resolved by hand go back to main's version on top, so they stay in the step's review.
    base = tree
    extra = ctx.config().get("fingerprint_include") or []
    if by_hand or extra:
        index_info = b"".join(b"%s %s\t%s\0" % ((e_2[f][0], e_2[f][1], f) if f in e_2 else (b"0", b"0" * len(tree), f))
                              for f in by_hand)
        with tempfile.TemporaryDirectory() as td:
            env = dict(os.environ, GIT_INDEX_FILE=str(Path(td) / "index"))
            steps = [(["git", "read-tree", tree], None, True, top)]
            if extra:   # the names in fingerprint_include are project-relative, so this one runs from the project folder
                steps.append((["git", "add", "-f", "--", *extra], None, False, root))   # may match nothing
            if by_hand:
                steps.append((["git", "update-index", "-z", "--index-info"], index_info, True, top))
            steps.append((["git", "write-tree"], None, True, top))
            for cmd, inp, must, cwd in steps:
                r = subprocess.run(cmd, cwd=cwd, env=env, capture_output=True, input=inp, timeout=60)
                if r.returncode != 0 and must:
                    die(f"git {cmd[1]} failed while preparing the next step's starting tree "
                        f"({r.stderr.decode('utf-8', 'replace').strip()[:200]}). Nothing was changed.")
            base = r.stdout.decode().strip()

    cfg = ctx.config()
    sha = head[:7]
    failure = None
    if cfg.get("regression_command"):
        rlog = ctx.evidence("merged") / f"regression-{sha}.log"
        code, out, _ = _run_cmd(ctx, cfg["regression_command"], rlog, cfg["test_timeout_sec"])
        if code != 0:
            failure = (f"The regression command ({cfg['regression_command']}) failed on the code merged from main "
                       f"(exit {code}): an earlier behaviour broke.", out, rlog)
    else:
        for c in ctx.plan()["checkpoints"]:
            if st["checkpoints"][c["id"]]["status"] != "done" or not (c.get("tests") or {}).get("command"):
                continue
            tlog = ctx.evidence(c["id"]) / f"merged-{sha}.log"
            code, out, _ = _run_cmd(ctx, c["tests"]["command"], tlog, cfg["test_timeout_sec"])
            if code != 0:
                failure = (f"{c['id']} ({c['title']}): its tests ({c['tests']['command']}) fail on the code merged "
                           f"from main (exit {code}).", out, tlog)
                break
    if failure:
        reason, out, log = failure
        _set_blocked(st, reason)
        ctx.save_state(st)
        build_viewer(ctx)
        print(_tail(out))
        die(f"{reason} Log: {log.relative_to(root)}. The run is stopped. To recover: undo the merge with git "
            f"(`git reset --keep {p1[:7]}`, the merge's first parent; --keep refuses instead of discarding edits to "
            "the run's files), fix what broke on "
            "main or in the lane, and once the user lets the run go on (tell them; the stopped-run options apply), "
            "merge main again and run merged. A fix committed on top of this merge does not work: merged only "
            "accepts a merge that is HEAD. Or give the user's feedback with `ratchet.py feedback` to add a fix step.",
            2)

    # Accepted from main only where the merged file or rule is exactly main's version.
    def main_blob(rel):
        r = tgit("show", f"{p2}:{prefix}{rel}", text=False)
        return r.stdout if r.returncode == 0 else None

    now_, snap, accepted, still = approval_snapshot(ctx, st), st.get("approved") or {}, [], []
    for f, h in (snap.get("files") or {}).items():
        if now_["files"].get(f) == h:
            continue
        theirs, mine = main_blob(f), _file_bytes(root / f)
        if theirs is not None and theirs == mine:
            snap["files"][f] = now_["files"][f]
            accepted.append(f)
        else:
            still.append(f"reference file {f}")
    main_cfg = main_blob(f"{RATCHET_DIR}/config.json")
    main_cfg = _read_record(root, data=main_cfg)[0] if main_cfg is not None else None
    main_cfg = config_from_user(main_cfg) if main_cfg is not None else None
    for k, h in (snap.get("rules") or {}).items():
        if now_["rules"].get(k) == h:
            continue
        if main_cfg is not None and _sha(main_cfg.get(k)) == now_["rules"].get(k):
            snap["rules"][k] = now_["rules"][k]
            accepted.append(f"config rule '{k}'")
        else:
            still.append(f"config rule '{k}'")
    if "custom_providers" in snap and snap["custom_providers"] != now_["custom_providers"]:
        still.append("custom review commands in config 'providers'")
    if snap.get("spec") and snap["spec"] != now_.get("spec"):
        still.append("the spec this run was built from")
    st["base_tree"] = base
    if phase == "building":
        st["checkpoints"][cur]["base_tree"] = base
        st["checkpoints"][cur]["base_head"] = head
    ctx.log(st, "merged_main", commit=head, tree=tree, accepted=accepted,
            by_hand=[f.decode("utf-8", "replace") for f in by_hand] if phase == "building" else [])
    ctx.save_state(st)
    build_viewer(ctx)
    ok(f"Merge of main ({sha}) checked and accepted: earlier steps still pass on the merged code"
       + (f"; {cur} starts from the merge, so its reviewers see only its own changes." if phase == "building"
          else "; the next step will start from the merge."))
    if by_hand:
        names = [f.decode("utf-8", "replace") for f in by_hand]
        print(f"Resolved by hand in the merge, will be reviewed with the next step: {', '.join(names[:10])}"
              + (" and more" if len(names) > 10 else ""))
    for a in accepted:
        print(f"Accepted from main as the new baseline: {a}")
    for s_ in still:
        print(f"Still changed after approval (not exactly main's version): {s_}. Show the user what changed; "
              "the lane cannot go on past it without their yes.")
    print(json.dumps(next_action(ctx, st), indent=2))


def _file_bytes(p: Path):
    try:
        return p.read_bytes()
    except OSError:
        return None


def _earliest_open_step(cps):
    for name in ["behavior", "ui", "adversarial"]:
        g = cps["gates"][name]
        if g["required"] and g["status"] != "passed":
            return name
    return "complete"


def _advance(st, cp_id, base_tree=None, base_head=None):
    st["current"] = cp_id
    st["phase"] = "building"
    st["checkpoints"][cp_id]["status"] = "in_progress"
    st["checkpoints"][cp_id]["started_at"] = now()
    if base_tree:
        st["checkpoints"][cp_id]["base_tree"] = base_tree  # what reviewers diff against
        st["checkpoints"][cp_id]["base_head"] = base_head or ""  # HEAD then: where `merged` starts counting lane commits


def cmd_human_approve(args):
    ctx = Ctx(find_root())
    st = ctx.state()
    if st["phase"] not in ("awaiting_checkpoint_review", "awaiting_final_review", "blocked"):
        die(f"Nothing awaiting human approval (phase {st['phase']})")
    if _finish_pending(st):
        # CP4: judged here, at the moment of approval, before the reply or token is read and before any state
        # changes (counters, pending, gates): a yes or a director token cannot finish a run past an unproven line.
        # Only where this approval would mark the run done; the review-limit unblock path (phase blocked) and a
        # step review with steps left are not finishes.
        blockers = _finish_blockers(ctx, st)
        changed = [] if blockers else _finish_integrity_lines(ctx, st)
        if (blockers or changed) and (st.get("pending") or {}).get("action") == "human-approve":
            # a question asked before the finish was held is withdrawn: a yes given to it can never finish the
            # run once the hold clears without the question being put again (status and the prompt hook stop
            # treating it as waiting)
            st.pop("pending", None)
            ctx.save_state(st)
        if blockers:
            die("\n".join(_finish_block_lines(ctx, st, blockers)), 2)
        if changed:  # a checkpoint or test plan edited after approval must be confirmed (approve-changes) first
            die("\n".join(changed), 2)
    allow = st.get("choice_allow") or {}
    if st["phase"] == "blocked" and allow.get("unblock") and not getattr(args, "director_token", None) \
            and allow.get("by", "human") == "human" and approval_mode(ctx) != "director":
        # a human's recorded pick at a block is the approval. A director-signed pick never is: resuming a block
        # (and the run-wide budget reset that comes with it) takes its own director token, so one signed letter
        # can never do more than record the letter (CP4: the run-wide review budget is never reset by a pick).
        msg = {"by": "human", "prompt": f"picked option {allow['letter']}: {allow.get('reply', '')}"}
    else:
        msg = _require_human(ctx, st, "human-approve", getattr(args, "director_token", None))
    if (st.get("pending") or {}).get("action") == "human-approve":
        st.pop("pending", None)  # answered (or overtaken by the user's pick at a block)
    order = [c["id"] for c in (ctx.plan() or {"checkpoints": []})["checkpoints"]]
    if st["phase"] == "blocked":
        _unblock(ctx, st, msg["by"], msg.get("prompt", "")[:200])
    else:
        target = st.get("review_target")
        done_ids = [target] if target else [c for c in order if st["checkpoints"][c]["status"] == "done"]
        for cid in done_ids:
            st["checkpoints"][cid]["gates"]["human"].update(status="passed", passed_at=now(), by=msg["by"])
        remaining = [c for c in order if st["checkpoints"][c]["status"] != "done"]
        st["review_target"] = None
        if remaining:
            _advance(st, remaining[0], fingerprint(ctx.root)["id"], _head_sha(ctx.root))
        else:
            st["phase"] = "done"
            st["current"] = None
            for n_ in _spec_finish(ctx, st):
                print(n_ if n_.startswith("Offer:") else f"Spec: {n_}")
            register_active(ctx.root, None)
            _stop_server(ctx.ratchet / "viewer.json")
        ctx.log(st, "approved", by=msg["by"], note=msg.get("prompt", "")[:200])
    # "done" still accepts later feedback, so it keeps a pause marker
    st["awaiting_since"] = now() if st["phase"] in ("done", "awaiting_final_review") else None
    ctx.save_state(st)
    if st["phase"] == "done":
        _ci_export_hint(ctx)
    build_viewer(ctx)
    ok(f"Human approval recorded. Phase → {st['phase']}")
    print(json.dumps(next_action(ctx, st), indent=2))


def cmd_feedback(args):
    """Human gave change requests at a review point: record learnings, then planner adds checkpoints."""
    ctx = Ctx(find_root())
    st = ctx.state()
    if st["phase"] not in ("awaiting_checkpoint_review", "awaiting_final_review", "done"):
        die(f"feedback is for review points (phase {st['phase']})")
    msg = _require_human(ctx, st, "feedback", getattr(args, "director_token", None))
    if (st.get("pending") or {}).get("action") == "human-approve":
        st.pop("pending", None)  # their reply asked for changes, which answers the approval question
    for line in args.learning or []:
        _append_learning(ctx, line, source=f"human review of {st['slug']}")
    st["phase"] = "planning_feedback"
    st["feedback"] = st.get("feedback", []) + [{"at": now(), "text": args.text or msg.get("prompt", "")}]
    ctx.log(st, "human_feedback", text=(args.text or msg.get("prompt", ""))[:300])
    ctx.save_state(st)
    ok("Feedback recorded. Spawn ratchet-checkpoint-planner in EXTEND mode to append new checkpoints, "
       "ratchet-test-planner for each new one, then run ratchet.py plan-extend.")


def _validate_new_checkpoints(ctx, plan, new_ids):
    """New checkpoints appended to the plan, whether by plan-extend's feedback or a hand-edited approve-changes,
    must be well-formed and have a test plan before they are registered; a malformed or missing-test checkpoint
    is refused here, not registered and left to crash later (standards #3). Shared by both call sites so a future
    change to what a new checkpoint requires only needs to be made once. Both callers already run validate_plan
    on this same `plan` before reaching here, so it is not repeated."""
    missing = [c for c in new_ids if cp_by_id(plan, c)["gates"].get("behavior") and not test_plan(ctx, c)]
    if missing:
        die(f"Test plans missing for new checkpoints {missing}")


def cmd_plan_extend(args):
    ctx = Ctx(find_root())
    st = ctx.state()
    if st["phase"] != "planning_feedback":
        die("plan-extend is only valid after ratchet.py feedback")
    plan = ctx.plan()
    errs = validate_plan(plan)  # before any code below indexes a checkpoint's "id": a malformed plan is a
    if errs:                    # named plan problem, never a bare KeyError.
        die("Plan invalid:\n  - " + "\n  - ".join(errs))
    had_objective = (st.get("approved") or {}).get("objective")
    if had_objective and not objective_problems({"objective": had_objective}) and objective_problems(plan):
        die("Feedback cannot drop the objective the approved plan had (" + "; ".join(objective_problems(plan)) + ").")
    approved_dm = _approved_done_means(st)
    if approved_dm and _approved_after_dm(st):
        # CP4: the approved done-means lines are what the finish is judged against, so feedback may only APPEND
        # lines: a dropped, reworded or reordered approved line is refused by number and approved text. A plan
        # approved before the done-means rules keeps today's behavior (its objective is re-read, never blocks).
        now_dm = (plan.get("objective") or {}).get("done_means") if isinstance(plan.get("objective"), dict) else None
        now_dm = now_dm if isinstance(now_dm, list) else []
        changed = [(i, t) for i, t in enumerate(approved_dm, 1) if i > len(now_dm) or now_dm[i - 1] != t]
        if changed:
            die("Feedback cannot remove, reword or reorder an approved done-means line; it may only append new lines "
                "at the end. Restore these lines as approved (same text, same position):\n  - "
                + "\n  - ".join(f"done_means line {i}: \"{t}\"" for i, t in changed), 2)
    new_ids = [c["id"] for c in plan["checkpoints"] if c["id"] not in st["checkpoints"]]
    if not new_ids:
        die("No new checkpoints were appended to checkpoints.json")
    for cid in st["checkpoints"]:
        if cid not in [c["id"] for c in plan["checkpoints"]]:
            die(f"Existing checkpoint {cid} was removed from the plan — completed work is append-only.")
    approved_cps = (st.get("approved") or {}).get("cps", {})
    edited = [c["id"] for c in plan["checkpoints"] if c["id"] in approved_cps and _sha(c) != approved_cps[c["id"]]]
    if edited:
        die(f"Existing checkpoint(s) {edited} were edited. Feedback only APPENDS new checkpoints; restore the originals.")
    appended = [cp_by_id(plan, cid) for cid in new_ids]
    # Only the APPENDED checkpoints are judged here: an existing high-risk step predating the risk_reason rule,
    # or an existing case whose "proves" plan-submit already accepted, keeps working untouched. The appended
    # cases' "proves" get plan-submit's own shape and range check, and the done-means lines feedback ADDED must
    # be proved (a line the approved plan already had keeps working unlinked: it predates the rule). One refusal
    # names everything, the bad "proves" first so the agent sees the real cause before the unproved line.
    errs = (proves_problems(ctx, {"objective": plan.get("objective"), "checkpoints": appended})
            + risk_reason_problems(appended)
            + unlinked_done_means_problems(ctx, plan, approved_lines=_approved_done_means(st)))
    if errs:
        die("Plan invalid:\n  - " + "\n  - ".join(errs))
    _validate_new_checkpoints(ctx, plan, new_ids)
    for cid in new_ids:
        st["checkpoints"][cid] = new_cp_state(cp_by_id(plan, cid))
    st["plan_hash"] = _plan_hash(plan, ctx)
    _advance(st, new_ids[0], fingerprint(ctx.root)["id"], _head_sha(ctx.root))
    # the user's feedback is the approval for the appended checkpoints and the appended done-means lines (the
    # approved lines were checked above to be an unchanged prefix)
    _stamp_legacy_round_baselines(st, plan)
    st["approved"] = _approval_snapshot_keeping_dm(ctx, st, keep_objective=False)
    register_active(ctx.root, st["slug"])
    ctx.log(st, "plan_extended", added=new_ids)
    ctx.save_state(st)
    build_viewer(ctx)
    ok(f"Added {', '.join(new_ids)}. Building {new_ids[0]} through all gates.")


def _append_learning(ctx, text, source):
    p = ctx.ratchet / "learnings.md"
    with p.open("a") as f:
        f.write(f"- ({_dt.date.today().isoformat()}, {source}) {text.strip()}\n")


def cmd_learn(args):
    ctx = Ctx(find_root())
    _append_learning(ctx, args.text, args.source or "orchestrator")
    ok("Learning recorded in .ratchet/learnings.md")


def _enter_pause(st, reason):
    """Park the run: `paused_from` keeps the phase to come back to, and a blocked run's own reason is kept in
    `paused_block_reason` (the pause reason takes `blocked_reason` meanwhile) so the block reads the same after."""
    if st["phase"] == "blocked":
        st["paused_block_reason"] = st.get("blocked_reason")
    st["paused_from"] = st["phase"]
    st["phase"] = "paused"
    st["blocked_reason"] = reason


def _lift_pause(st) -> dict:
    """Put a paused run back in the phase it paused from, in memory; returns the pause reason for _enter_pause,
    so a command that only works through the pause (director-sign --apply) can park the run again as it was."""
    reason = st.get("blocked_reason")
    st["phase"] = st.pop("paused_from", None) or "building"
    st["blocked_reason"] = st.pop("paused_block_reason", None) if st["phase"] == "blocked" else None
    return {"reason": reason}


def cmd_pause(args):
    ctx = Ctx(find_root())
    st = ctx.state()
    if st["phase"] in ("paused", "done", "cancelled"):
        ok(f"Nothing to pause (phase {st['phase']}).")
        return
    _enter_pause(st, args.reason or "paused")
    ctx.log(st, "paused", reason=args.reason)
    ctx.save_state(st)
    ok("Paused. The Stop hook now lets the agent stop. Resume with ratchet.py resume.")


def live_wait(st) -> dict | None:
    """The run's wait (`ratchet.py wait`) while it still applies, else None. It applies only while the run is being
    built or planned (not paused, blocked, done or cancelled), to the chat that set it while that chat still owns the
    run, before its `until` time, and until any gate progress is logged after it was set. A record that does not have
    this shape (missing fields, a set time in the future, a window longer than WAIT_MAX_MINUTES) does not apply."""
    w = st.get("wait")
    if not isinstance(w, dict) or st.get("phase") in ("blocked", "paused", "done", "cancelled"):
        return None
    reason, set_at, until, sess = w.get("reason"), w.get("set_at"), w.get("until"), w.get("session")
    if not all(isinstance(v, str) and v for v in (reason, set_at, until, sess)) or sess != st.get("owner_session"):
        return None
    t_set, t_until, t_now = _iso(set_at), _iso(until), time.time()
    if not t_set or not t_until or t_set > t_now + 60 or t_until <= t_now or t_until - t_set > WAIT_MAX_MINUTES * 60 + 60:
        return None
    ends = PROGRESS_EVENTS | WAIT_ENDING_EVENTS
    if any(e.get("event") in ends and _iso(e.get("at", "")) > t_set for e in st.get("history") or []
           if isinstance(e, dict)):
        return None
    return {"reason": reason, "set_at": set_at, "until": until, "session": sess}


def cmd_wait(args):
    """The owner chat says it is waiting on background work (reviewers, sub-agents), so the stop hook lets it end its
    turn until `until` without counting a blocked stop. Any gate progress ends the wait early."""
    ctx = Ctx(find_root())
    st = ctx.state()
    if st["phase"] in ("blocked", "paused", "done", "cancelled"):
        die(f"Nothing to wait for: run '{st['slug']}' is {st['phase']}, so the stop hook already lets you stop.")
    reason = " ".join(str(args.reason or "").split())[:300]
    if not reason:
        die('Say what you are waiting on, e.g. `ratchet.py wait --for "the codex review of CP2" --minutes 20`.')
    # The chat running this command is one Ratchet saw itself, never a value the caller supplies: the chat the guard
    # hook noted for this exact call, else (a host whose guard hook can't see the call) the chat the user typed in
    # last, as `ask claim` does. `--session` is only a cross-check: `owner_session` is plain text any local process
    # can read, so a bare --session proves nothing.
    noted = _noted_session(ctx.root, "wait")
    who = noted or _latest_session(ctx)
    owner = st.get("owner_session")
    if not owner:
        die("No chat owns this Ratchet run yet, so Ratchet can't tell whose turn may end. Nothing was recorded; "
            "carry on with `ratchet.py next`.")
    if not who:
        die("Ratchet could not tell which chat ran this command (its guard hook did not see the call, and it has "
            "recorded no message from the user), so nothing was recorded. --session alone is not proof of which chat "
            "this is. Keep working on `ratchet.py next`.")
    if args.session and args.session != who:
        die("The chat named by --session is not the one Ratchet sees running this command ("
            + ("the chat its guard hook noted for this call" if noted else
               "its guard hook did not see the call, so that is the chat the user typed in last")
            + "). --session alone is not proof of which chat this is. Nothing was recorded.")
    if who != owner:
        die(f"Only the chat that owns run '{st['slug']}' may wait on background work; this one does not, and its "
            "stops are not held by this run anyway. Nothing was recorded.")
    try:
        minutes = float(WAIT_DEFAULT_MINUTES if args.minutes is None else args.minutes)
    except (TypeError, ValueError):
        die("--minutes must be a number of minutes, e.g. --minutes 20.")
    if minutes != minutes:  # NaN
        minutes = WAIT_DEFAULT_MINUTES
    minutes = int(round(min(max(minutes, 1), WAIT_MAX_MINUTES)))
    t0 = _dt.datetime.now(_dt.timezone.utc)
    until = (t0 + _dt.timedelta(minutes=minutes)).isoformat(timespec="microseconds")
    st["wait"] = {"reason": reason, "set_at": t0.isoformat(timespec="microseconds"), "until": until,
                  "session": who, "minutes": minutes}
    ctx.log(st, "wait_set", reason=reason, until=until, minutes=minutes)
    ctx.save_state(st)
    ok(f"Waiting on: {reason}. Until {until[:16].replace('T', ' ')} UTC ({minutes} min) the stop hook lets this chat "
       "end its turn, and those stops do not count as blocked stops. Any gate progress ends the wait early. When the "
       "background work reports back, carry on with `ratchet.py next`.")


CONSUMING_EVENTS = {"plan_approved", "approved", "unblocked", "changes_approved", "review_mode_changed",
                    "cancelled", "human_feedback", "resumed"}


def _decision_window(st) -> str:
    """For decisions taken mid-build (approve-changes, cancel, set-review): messages after the user's last decision."""
    times = [e["at"] for e in st.get("history", []) if e.get("event") in CONSUMING_EVENTS]
    return max(times) if times else st.get("created_at", "0")


def _latest_session(ctx):
    human = [e for e in _human_since(ctx, "0") if e.get("session")]
    return human[-1]["session"] if human else None


def cmd_resume(args):
    """Resume a paused run, or claim an active run for THIS session (the Stop hook binds to the owner session)."""
    ctx = Ctx(find_root())
    st = ctx.state()
    if st["phase"] in ("done", "cancelled"):
        die(f"Run '{st['slug']}' is {st['phase']}; start a new one with init.")
    if args.claim:
        _require_pending(st, "claim")
        msg = _require_human(ctx, st, "claim")
        st["owner_session"] = msg.get("session") or st.get("owner_session")
        _clear_pending(st)
    if st["phase"] == "paused":
        _lift_pause(st)
    register_active(ctx.root, st["slug"])
    ctx.log(st, "resumed")  # also restarts the stop hook's count of stops without progress
    ctx.save_state(st)
    ok(f"Resumed '{st['slug']}' in phase {st['phase']}" + (" — this chat now owns the run." if args.claim else "."))
    print(json.dumps(next_action(ctx, st), indent=2))


ASKABLE = {"approve-plan": "start building the plan as it is",
           "human-approve": "mark this as approved and carry on",
           "approve-changes": "accept the changes listed above as the new baseline",
           "cancel": "cancel this Ratchet run (commits already made are kept)",
           "set-review": "change how often you review",
           "claim": "continue this Ratchet run in THIS chat",
           "hooks-waive": "build without the Ratchet hooks (the checks then only advise; nothing enforces them)",
           "ui-respec": "change what the UI check compares for this step (its capture steps or scope), as explained above",
           "choice": "go with one of the lettered options you listed",
           "accept-finding": "accept the open finding(s) named above as a known limit, with your own reason, instead "
                             "of running another review round",
           "raise-limit": "raise this step's review-round limit by one round, with your own reason, so the "
                          "reviewers can keep going (offered at most once per step, ever)",
           "accept-line": "accept the done-means line(s) named above as unproven, with your own reason, so they no "
                          "longer hold the finish",
           "paid-provider": "use a provider that costs money per use (or whose cost is unknown, treated the "
                            "same way) for reviews, named above, instead of only flat-rate ones"}
# the command that carries out a "yes" to each question
PENDING_COMMAND = {"approve-plan": "approve-plan", "human-approve": "human-approve", "approve-changes": "approve-changes", "cancel": "cancel", "set-review": "set-review",
                   "claim": "resume --claim", "hooks-waive": "hooks-waive", "ui-respec": "ui-respec", "choice": "choice",
                   "accept-finding": "accept-finding", "raise-limit": "raise-limit", "accept-line": "accept-line"}
REVIEW_MODE_WORDS = {"end": "only at the end", "each": "after every step", "none": "never (fully autonomous)"}


def _pending_followup(action, mode=None) -> str:
    """The real command that carries out a developer's yes to a waiting question, for the re-ask/overtaken
    hints that build it from PENDING_COMMAND and the question's mode. paid-provider's mode is "tool:model"
    (joined only for display/comparison); its real follow-up needs them as separate --preset/--model flags
    and an id for the new provider, not PENDING_COMMAND's plain command-plus-mode form. The follow-up takes only
    the question's `mode` (the argument its command takes), never its `target` (what it is about, e.g. accept-line's
    line numbers, which `accept-line` reads from `pending`), so accept-line's is the bare command."""
    if action == "paid-provider" and mode and ":" in mode:
        tool, model = mode.split(":", 1)
        return f"providers --add <id> --preset {tool} --model {model}"
    cmd = PENDING_COMMAND.get(action, action)
    return cmd + (f" {mode}" if mode else "")


def cmd_ask(args):
    """Record (and print) the question the agent is about to ask the user. Only the user's FIRST reply after it
    answers it, and only a listed yes approves (APPROVAL_REPLIES; hooks-waive and choice have their own replies)."""
    ctx = Ctx(find_root())
    st = ctx.state()
    asker = _noted_session(ctx.root, "ask")  # the chat running this command, when the guard hook saw it
    if args.action == "withdraw":
        p = st.get("pending")
        if not p:
            ok("No question is waiting.")
            return
        _clear_pending(st)
        ctx.log(st, "question_withdrawn", action=p.get("action"))
        ctx.save_state(st)
        ok(f"Withdrew the waiting question ({p.get('action')}). Nothing was changed.")
        return
    if args.action == "set-review" and args.mode not in ("end", "each", "none"):
        die("ask set-review needs the mode: end | each | none")
    if args.action == "ui-respec" and not (args.mode and args.mode in (st.get("checkpoints") or {})):
        die("ask ui-respec needs the checkpoint id, e.g. `ratchet.py ask ui-respec CP2`")
    if args.action == "accept-finding" and not (args.mode and args.mode in (st.get("checkpoints") or {})):
        die("ask accept-finding needs the checkpoint id, e.g. `ratchet.py ask accept-finding CP2 F1,F2`")
    if args.action == "accept-finding" and not getattr(args, "ids", None):
        die("ask accept-finding needs the finding ids to accept, e.g. `ratchet.py ask accept-finding CP2 F1,F2`")
    if args.action == "raise-limit" and not (args.mode and args.mode in (st.get("checkpoints") or {})):
        die("ask raise-limit needs the checkpoint id, e.g. `ratchet.py ask raise-limit CP2`")
    if args.action == "paid-provider" and not (args.mode and getattr(args, "ids", None)):
        die("ask paid-provider needs the tool and model, e.g. `ratchet.py ask paid-provider opencode "
            "openrouter/z-ai/glm-5`")
    if args.action not in ("set-review", "ui-respec", "accept-finding", "raise-limit", "paid-provider",
                           "accept-line") and args.mode:
        die(f"ask {args.action} takes no extra value")
    _bind_owner(ctx, st, args.action, asker)
    if args.action == "raise-limit":
        return _ask_raise_limit(ctx, st, args)
    if args.action == "accept-line":
        return _ask_accept_line(ctx, st, args)
    if args.action == "choice":
        return _ask_choice(ctx, st, args)
    if args.action == "accept-finding":
        return _ask_accept_finding(ctx, st, args)
    if args.action == "paid-provider":
        return _ask_paid_provider(ctx, st, args)
    detail = ""
    if args.action == "approve-changes":
        # integrity_problems (via approval_snapshot/_plan_hash) no longer raises KeyError for a checkpoint
        # missing "id": it falls back to its position, so this stays a question, not a crash (CP6-X04). The
        # mutating command (`ratchet.py approve-changes`) is what validates the plan's shape and refuses.
        probs = integrity_problems(ctx, st)
        if not probs:
            ok("Nothing has changed since approval — no question needed.")
            return
        detail = "Changed since you approved the plan: " + "; ".join(probs) + "."
    if args.action == "set-review":
        detail = {"end": "I'll only check in with you at the end.", "each": "I'll check in after every step.",
                  "none": "I'll build every step without checking in; the checks still run."}[args.mode]
    what = ASKABLE[args.action]
    if args.action in ("approve-plan", "human-approve"):
        what = _approval_question(ctx, st, args.action)
    old = st.get("pending") or {}
    if args.action == "hooks-waive" and old.get("action") not in (None, "hooks-waive"):
        die(f"A different question ({old.get('action')}) is still waiting for the user's answer. Get that answered "
            "first; a hooks question must not take over their reply.")
    overtook = _overtake(ctx, st, args.action, args.mode, asker)
    asked = now()
    st["pending"] = {"action": args.action, "mode": args.mode, "asked_at": asked, "prev_awaiting": st.get("awaiting_since"),
                     "session": _asking_session(ctx, st, args.action, asker), **overtook}
    if args.action in ("approve-plan", "human-approve"):
        st["pending"]["phase"] = st["phase"]  # the answer only counts at the pause it was asked at
    if args.action != "hooks-waive":  # a hooks question must not open (or reset) any approval window
        st["awaiting_since"] = asked
    ctx.log(st, "question_asked", action=args.action, mode=args.mode)
    ctx.save_state(st)
    if overtook:
        print(_not_asked_text(_ask_cmd(args.action, args.mode), overtook))
        return
    if args.action == "hooks-waive":
        print(f"ASK THE USER: Shall I build without the Ratchet hooks? The checks would then only advise; nothing "
              f"enforces them. To agree, reply exactly \"{HOOKS_WAIVE_REPLY}\". Any other reply means no.")
        return
    if args.action == "set-review":
        what = f"change how often you review to: {REVIEW_MODE_WORDS[args.mode]}"
    q = (f"{detail} Shall I {what}? To say yes, reply with just one of these: {listed_yes_text()}. Only your first "
         "reply counts, and any other reply approves nothing.")
    print(f"ASK THE USER: {q.strip()}")
    print(ASK_ALONE)


# Ratchet can't see what the agent shows the user, so it can't tell a yes to this question from a yes to another
# question or offer in the same message. The agent keeps the message to this one question.
ASK_ALONE = ("NEXT: end your message with that question, word for word, as the only question in it: settle any other "
             "question or offer first, in an earlier turn. Then end your turn. Ratchet can't see what you showed, so "
             "a yes meant for something else in the same message would still count.")


def _asking_session(ctx, st, action, asker=None):
    """The chat whose first reply will answer a question being asked now. A claim belongs to the chat that ran
    `ask claim` (`asker`, noted by the guard hook for this exact call); every other question belongs to the run's
    owner chat. None while no chat owns the run (see _bind_owner). Only a claim with no note (an agent CLI whose guard
    hook doesn't run, or a call the guard couldn't read) falls back to the chat the user typed in last."""
    if not st.get("owner_session"):
        return None
    if action != "claim":
        return st["owner_session"]
    return asker or _latest_session(ctx)


def _bind_owner(ctx, st, action, asker):
    """A question needs a chat to answer it. Before any chat owns the run, the chat that runs `ask` (noted by the
    guard hook) becomes the owner, so only its replies answer the question and the run can't be taken by a reply in
    another chat. With no note (an agent CLI whose guard hook doesn't run) the question waits unbound, and the first
    chat the prompt hook records for the run owns it (decide_prompt)."""
    if st.get("owner_session"):
        return
    if action == "claim":
        die("No chat owns this Ratchet run yet, so there is nothing to take over and nothing was asked. Run "
            "`ratchet.py resume` (without --claim) and carry on in this chat.")
    if asker:
        st["owner_session"] = asker
        ctx.log(st, "owner_recorded", session=asker, via="ask")


def _overtake(ctx, st, action, mode, asker=None, target=None) -> dict:
    """A new question while a DIFFERENT one still waits for the user's first reply: the user may see both, and one
    reply can't answer two questions. Plan and step approvals are refused until the waiting one is answered or
    withdrawn. Any other question is recorded but marked as overtaking, so no reply approves it; the agent asks it
    again on its own. Either way the replaced question is logged. Returns the marker to store on the new question."""
    old = st.get("pending") or {}
    oa = old.get("action")
    if not oa:
        return {}  # nothing waiting
    om, ot = _pq(old)
    first = _replies(ctx, st, old.get("asked_at"), old)[:1]
    answered = bool(first)
    new_sess = _asking_session(ctx, st, action, asker)
    if not answered and old.get("session") and new_sess != old.get("session"):
        # the waiting question belongs to another chat: a question asked here (even the same one) must not drop it
        die(f"A question is waiting for the user's first reply in another chat (shall I {_question_what(oa, om, ot)}?), "
            "so nothing was asked here. Try again after it is answered there. If the user tells you that chat is "
            "gone, run `ratchet.py ask withdraw` first (that drops its question; it is logged, and that chat has to "
            "ask it again).")
    if oa == action and om == (mode or None) and ot == (target or None):
        return {}  # the same question printed again in its own chat
    if oa == "hooks-waive" and (not answered or hooks_waive_intent(first[0].get("prompt", "")) == "approve"):
        # `hooks-waive` reads its answer from this question: replacing it before the reply, or after the user agreed,
        # would hide that reply from it. A first reply that is not the waiver phrase is a no, so it can be replaced.
        if answered:
            die(f"The user agreed to build without the Ratchet hooks (their reply to the hooks question was "
                f"\"{first[0].get('prompt', '')[:80]}\"), so nothing was asked. Run `ratchet.py hooks-waive` to record "
                "it first, or `ratchet.py ask withdraw` if they have since changed their mind. Then ask this question "
                "on its own.")
        die("The hooks question (shall I build without the Ratchet hooks?) is still waiting for the user's reply, so "
            "nothing was asked. Wait for their reply: if it is exactly \"" + HOOKS_WAIVE_REPLY + "\", run "
            "`ratchet.py hooks-waive`. If you no longer need it, run `ratchet.py ask withdraw`. Then ask this question "
            "on its own.")
    if not answered and action in ("approve-plan", "human-approve"):
        die(f"A different question is still waiting for the user's first reply: shall I "
            f"{_question_what(oa, om, ot)}? One reply can't answer two questions. Get that one answered "
            f"(if they say yes, run `ratchet.py {_pending_followup(oa, om)}`"
            ") or run `ratchet.py ask withdraw` if you no longer need it, then ask this question on its own.")
    ctx.log(st, "question_overtaken", action=oa, mode=om, target=ot, by=action, answered=answered)
    if answered:
        return {}  # the old question already had its one reply; this one starts clean
    return {"overtook": oa, "overtook_mode": om, "overtook_target": ot}


def _not_asked_text(again, overtook) -> str:
    return (f"NOT ASKED: a different question (shall I {_question_what(overtook['overtook'], overtook.get('overtook_mode'), overtook.get('overtook_target'))}"
            "?) was still waiting for the user's first reply. It is now withdrawn, and this question is recorded as "
            "overtaking it, so no reply approves it: if the user saw both, their reply could be meant for either. Do "
            f"not show it. Run {again} again to ask it on its own, then show the user only that "
            "question.")


def _approval_question(ctx, st, action) -> str:
    """The question `ask approve-plan` / `ask human-approve` puts to the user at this pause, or die when there is
    nothing to approve here."""
    if approval_mode(ctx) == "director":
        die("This lane is director-enrolled: a chat reply can't approve anything here. The director signs this "
            f"approval instead (director-sign {action}).")
    phase = st["phase"]
    if action == "approve-plan":
        if phase != "awaiting_plan_approval":
            die(f"There is no plan waiting for approval (the run is {PHASE_PLAIN.get(phase, phase)}).")
        return "start building the plan shown above, as it is"
    if _finish_pending(st):
        blockers = _finish_blockers(ctx, st)  # CP4: no approval question while a done-means line is unproven
        if blockers:
            die("\n".join(_finish_block_lines(ctx, st, blockers)), 2)
        changed = _finish_integrity_lines(ctx, st)  # nor while a checkpoint or test plan changed after approval
        if changed:
            die("\n".join(changed), 2)
    if phase == "awaiting_checkpoint_review":
        titles = {c["id"]: c.get("title", c["id"]) for c in (ctx.plan() or {}).get("checkpoints", [])}
        left = [c for c, s in (st.get("checkpoints") or {}).items() if s.get("status") != "done"]
        t = titles.get(st.get("review_target"), "the last step")
        return f"mark the step \"{t}\" as approved and " + ("go on to the next step" if left else "finish the run")
    if phase == "awaiting_final_review":
        return "mark the finished work as approved and close this run"
    if phase == "blocked":
        return "carry on past the problem explained above"
    die(f"Nothing is waiting for the user's approval (the run is {PHASE_PLAIN.get(phase, phase)}).")


def _ask_choice(ctx, st, args):
    """A lettered-options question. An option may approve a change to locked files: then picking it is the approval.
    In a director-enrolled lane the question is recorded the same way, but it waits for the director (who signs a
    letter with `director-sign choice <L>`), not for a chat reply: it is not shown to the user as a question."""
    director = approval_mode(ctx) == "director"
    opts = [o.strip().upper() for o in (args.options or "").split(",") if o.strip()]
    if len(opts) < 2 or len(set(opts)) != len(opts) or not all(re.fullmatch(r"[A-Z]", o) for o in opts):
        die("ask choice needs --options with two or more single letters, e.g. --options A,B,C")
    lockable = set(_reference_files(ctx))
    cur = st.get("current")
    lockable |= set(((st.get("checkpoints") or {}).get(cur) or {}).get("red_tests") or [])
    locked = {}
    for spec in args.locked or []:
        letter, _, files = spec.partition("=")
        letter = letter.strip().upper()
        if letter not in opts:
            die(f"--locked {spec}: {letter} is not one of the options {','.join(opts)}")
        paths = [f.strip() for f in files.split(",") if f.strip()]
        bad = [f for f in paths if f not in lockable]
        if not paths or bad:
            die(f"--locked {spec}: name the locked files exactly as Ratchet lists them. Locked now: "
                f"{', '.join(sorted(lockable)) or '(none)'}")
        locked[letter] = paths
    guards = {}
    for spec in getattr(args, "guardrail", None) or []:
        letter, _, kind = spec.partition("=")
        letter, kind = letter.strip().upper(), norm_kind(kind)
        if letter not in opts or not kind:
            die(f"--guardrail {spec}: use LETTER=<kind>, with LETTER one of {','.join(opts)}")
        guards[letter] = kind
        offered = st.setdefault("guardrails_offered", [])
        if kind not in offered:
            offered.append(kind)  # asked once; not offered again whatever the answer
    overtook = _overtake(ctx, st, "choice", None)
    asked = now()
    st["pending"] = {"action": "choice", "mode": None, "options": opts, "locked": locked, "guardrail": guards,
                     "asked_at": asked, "prev_awaiting": st.get("awaiting_since"),
                     "session": _asking_session(ctx, st, "choice"), **overtook}
    st["awaiting_since"] = asked
    ctx.log(st, "question_asked", action="choice", options=opts, locked=locked)
    ctx.save_state(st)
    if overtook:
        print(_not_asked_text("the same `ratchet.py ask choice ...` command", overtook))
        return
    if director:
        lines = [f"FOR THE DIRECTOR (this lane is director-enrolled, so a chat reply picks nothing): options "
                 f"{', '.join(opts)} are recorded as waiting. Do not put them to the user as a chat question; say in "
                 "one line what each option is, with your recommendation, and that the director picks one with "
                 "`director-sign choice <letter> --apply` (or signs it with `director-sign choice <letter>` for a "
                 "token you apply)."]
        for letter, paths in locked.items():
            lines.append(f"  Option {letter} approves changing {', '.join(paths)} (locked since the plan was approved).")
        for letter, kind in guards.items():
            lines.append(f"  Option {letter} adds an automatic check for '{kind}' as its own step right after the "
                         "current one.")
        lines.append("Apply the director's pick with `ratchet.py choice <letter> --director-token <t>`.")
        print("\n".join(lines))
        return
    lines = [f"ASK THE USER: give them options {', '.join(opts)} in your own words, with your recommendation, and ask "
             f"them to reply with just the letter."]
    for letter, paths in locked.items():
        lines.append(f"  In option {letter}, say plainly that choosing it approves changing {', '.join(paths)} "
                     f"(locked since they approved the plan), and what the change is. Their pick of {letter} is then "
                     "the approval: no second yes is needed.")
    for letter, kind in guards.items():
        lines.append(f"  Option {letter} adds an automatic check for '{kind}' as its own step right after the current "
                     "one (it may add a lint or architecture-test tool to the project). Say so in the option.")
    lines.append(f"After they reply, run `ratchet.py choice`. It records which option they picked.")
    print("\n".join(lines))


ACCEPT_FINDING_RE = re.compile(r"^accept:\s*(.+)$", re.I | re.S)


def _accept_reply_reason(text: str) -> str | None:
    """The reason in a reply of the exact form `accept: <reason>`, or None when the reply is not that form (or
    gives no reason). Read by cmd_accept_finding and cmd_accept_line (CP5): the one reply form that accepts."""
    m = ACCEPT_FINDING_RE.match((text or "").strip())
    if not m:
        return None
    reason = m.group(1).strip()
    return reason or None


def _finding_key(f) -> str:
    """The identity shown and recorded for a finding: 'reviewer/id' (e.g. 'codex-correctness/A1') when it carries a
    reviewer (every finding cmd_adv_record records does, tagged there), else the bare id. A finding's own `id` field
    is only unique per reviewer, not per round: two independent reviewers routinely pick the same id (their shared
    prompt gives every one of them the identical example "id":"A1"), so the bare id alone is never enough on its own
    to say WHICH finding is meant."""
    fid = f.get("id") or "?"
    rev = f.get("reviewer")
    return f"{rev}/{fid}" if rev else fid


def _resolve_finding_ref(ref: str, findings: list):
    """The finding `ref` (a bare id, or 'reviewer/id') names among `findings`. Returns (finding, error): `finding`
    is the single match, or None when `ref` names none of them. `error` is set instead, only for a bare id that
    matches more than one reviewer's finding here (normal in any round with more than one reviewer: nothing stops
    two of them picking the same id) — it names the colliding reviewers so the agent can ask again precisely, as
    'reviewer/id'. A qualified ref ('reviewer/id') is never ambiguous: it is matched exactly or not at all."""
    if "/" in ref:
        rev, _, fid = ref.partition("/")
        for f in findings:
            if f.get("id") == fid and str(f.get("reviewer") or "") == rev:
                return f, None
        return None, None
    matches = [f for f in findings if f.get("id") == ref]
    reviewers = sorted({str(f.get("reviewer")) for f in matches})
    if len(reviewers) > 1:
        return None, (f"\"{ref}\" is ambiguous: {', '.join(reviewers)} each reported a finding with id \"{ref}\" "
                      f"here. Say which one, e.g. `{reviewers[0]}/{ref}`.")
    return (matches[0] if matches else None), None


def _why_not_open(f) -> str:
    """The real reason a non-open (deferred) finding doesn't block, for a refusal message (standards #11: name the
    actual reason, not a guess): its own `deferred_because` when cmd_adv_record recorded one (covered by an
    automatic check, or no user_impact stated), else 'deferred as minor' only when its severity really is minor."""
    why = str(f.get("deferred_because") or "").strip()
    if why:
        return why
    if str(f.get("severity", "")).strip().lower() in MINOR_SEVERITIES:
        return "deferred as minor, not blocking"
    return "deferred, not blocking"


def _ask_raise_limit(ctx, st, args):
    """`ask raise-limit CPn`: refused outright, before anything is asked, once this checkpoint's one raise is
    already spent (`gates.adversarial.cap_raised_to` set) — a step's raise is offered, and spent, at most once,
    ever, whatever `config.json`'s `max_adversarial_rounds` is edited to afterward. Also refused outright, before
    anything is asked, unless `_adv_block_kind(st, cp)` is "own" or "run_wide": the one-time raise exists for a
    step genuinely stuck at its adversarial round limit, never for a step still building or already done, where
    this question's own fixed wording ("reviewers have used all the review rounds allowed and are still
    blocked") would be false."""
    cp = args.mode
    cps = (st.get("checkpoints") or {}).get(cp)
    if cps is None:
        die(f"No such checkpoint {cp}.")
    g = (cps.get("gates") or {}).get("adversarial") or {}
    if g.get("cap_raised_to"):
        die(f"{cp}'s review-round limit was already raised once (to {g['cap_raised_to']} rounds); it is never "
            "offered a second time. Nothing was asked.")
    if _adv_block_kind(st, cp) not in ("own", "run_wide"):
        die(f"{cp} is not blocked on an adversarial review-round limit right now; raise-limit only applies then. "
            "Nothing was asked.")
    overtook = _overtake(ctx, st, "raise-limit", cp)
    asked = now()
    st["pending"] = {"action": "raise-limit", "mode": cp, "asked_at": asked, "prev_awaiting": st.get("awaiting_since"),
                     "session": _asking_session(ctx, st, "raise-limit"), **overtook}
    st["awaiting_since"] = asked
    ctx.log(st, "question_asked", action="raise-limit", cp=cp)
    ctx.save_state(st)
    if overtook:
        print(_not_asked_text(f"`ratchet.py ask raise-limit {cp}`", overtook))
        return
    print(f"ASK THE USER: {cp}'s reviewers have used all the review rounds allowed and are still blocked. Shall I "
          "raise this step's review-round limit by one round (its one and only raise) so they can keep going? To "
          "agree, their reply must be exactly: raise: <their reason>. Only their first reply counts, and only "
          "that exact form (starting with \"raise: \") raises it; any other reply raises nothing.")
    print(ASK_ALONE)


def _ask_accept_finding(ctx, st, args):
    """`ask accept-finding CPn F1,F2` (or 'reviewer/F1' when a bare id is ambiguous): only when that checkpoint's
    latest adversarial round blocked, and only for ids that are still open (blocking) findings of that round. An id
    that never existed, or that was only ever deferred (set aside, never blocking; a minor that names a done-means
    line is open, not deferred, so it can be asked here), is refused here; an id already accepted is left to
    `accept-finding` itself to refuse (so this can be asked again without first re-deriving which ids are already
    done). A bare id matching more than one reviewer's finding here is refused too, naming the colliding
    reviewers: say which one as 'reviewer/id'. CP3: a finding that names a done-means line is shown in the
    question with the line's number and text (`_dm_named_text`), never as a bare severity, so the user knows the
    accept closes a miss against what done means."""
    cp = args.mode
    ids = list(dict.fromkeys(i.strip() for i in (args.ids or "").split(",") if i.strip()))  # de-dupe repeated ids
    if not ids:
        die("ask accept-finding needs the finding ids to accept, e.g. `ratchet.py ask accept-finding CP2 F1,F2`")
    cps = (st.get("checkpoints") or {}).get(cp)
    if cps is None:
        die(f"No such checkpoint {cp}.")
    rnd = cps.get("adv_round")
    if rnd and _code_changed_since_round(ctx, rnd):
        die(f"{cp}: the code changed since this review round; run a new review round first. Nothing was asked.")
    open_findings = _adv_open_findings(ctx, cp, rnd, cps)  # state-filtered: a stale file can't un-accept an id
    if not open_findings:
        die(f"There are no open findings to accept for {cp} - the review already passed (or no round has blocked "
            "there yet). Nothing was asked.")
    deferred = _round_deferred(cps, rnd["round"])
    open_now = ', '.join(sorted(_finding_key(f) for f in open_findings)) or '(none)'
    resolved = []  # [(canonical key, finding shown in the question)], in ids' own order
    for ref in ids:
        f, err = _resolve_finding_ref(ref, open_findings)
        if err:
            die(f"{err} Nothing was asked.")
        if f is not None:
            resolved.append((_finding_key(f), f))
            continue
        d, derr = _resolve_finding_ref(ref, deferred)
        if derr:
            die(f"{derr} Nothing was asked.")
        if d is not None and d.get("accepted"):
            resolved.append((_finding_key(d), d))  # already accepted earlier: `accept-finding` refuses this clearly
            continue
        if d is not None:
            die(f"{ref} is not an open finding of this round for {cp}; it was already {_why_not_open(d)} "
                f"(open now: {open_now}). Nothing was asked.")
        die(f"{ref} is unknown: not an open finding of this round for {cp} (open now: {open_now}). Nothing was "
            "asked.")
    by_key = {}
    for key, f in resolved:
        by_key.setdefault(key, f)
    canon_ids = list(by_key)
    overtook = _overtake(ctx, st, "accept-finding", cp)
    asked = now()
    st["pending"] = {"action": "accept-finding", "mode": cp, "ids": canon_ids, "round": rnd["round"],
                     "fingerprint": rnd["fingerprint"], "asked_at": asked, "prev_awaiting": st.get("awaiting_since"),
                     "session": _asking_session(ctx, st, "accept-finding"), **overtook}
    st["awaiting_since"] = asked
    ctx.log(st, "question_asked", action="accept-finding", cp=cp, ids=canon_ids)
    ctx.save_state(st)
    if overtook:
        print(_not_asked_text(f"`ratchet.py ask accept-finding {cp} {','.join(canon_ids)}`", overtook))
        return
    obj = (ctx.plan() or {}).get("objective")
    dm_lines = obj.get("done_means") if isinstance(obj, dict) else None
    dm_lines = dm_lines if isinstance(dm_lines, list) else []
    named = "; ".join(f"{key} ({by_key[key].get('severity', '?')}): "
                      f"{str(by_key[key].get('description', '')).strip()[:160]}"
                      f"{_dm_named_text(dm_lines, by_key[key])}" for key in canon_ids)
    print(f"ASK THE USER: {cp}'s review is blocked on: {named}. Shall I accept {', '.join(canon_ids)} as a known "
          "limit, with their reason, instead of running another review round? To accept them, their reply must be "
          "exactly: accept: <their reason>. Only their first reply counts, and only that exact form (starting with "
          "\"accept: \") accepts them; any other reply accepts nothing.")
    print(ASK_ALONE)


def _ask_accept_line(ctx, st, args):
    """`ask accept-line <n>[,<n>...]` (CP5; `args.mode` carries the 1-based numbers of the approved done-means
    lines, as the final review's table numbers them): the one way a line that holds the finish can be released
    without proving it. Only at the finish pause (`_finish_pending`) of a plan approved under the done-means rules
    (`_approved_after_dm`; an older run gets a plain note and nothing is asked, since nothing holds its finish),
    and only for lines the table (`done_means_table`) reads as "unproven" right now: a line that is proven, not a
    real line (0, past the last line, not a number, an empty entry), or already accepted is refused naming it,
    and a mixed list is refused whole, so no line slips past the check; a line accepted earlier but held again
    (`_apply_accepted_lines`: unproven for a reason that acceptance did not cover) reads unproven and can be
    asked about again, the question naming the earlier acceptance. Repeated numbers count once. Records the
    question (`pending`: action accept-line, `target` the line numbers sorted and comma-joined ("2,3" whether typed
    as 2,3 or 3,2; what the question is about, `mode` stays null, so `_overtake` treats a question about other lines as a different
    question, a re-print in another order as the same one, and NOT ASKED names the lines; two space-separated
    values are refused rather than one being dropped),
    `ids` the numbers parsed, `covered` the reasons the question showed per line (what a reply accepts; a
    reason that appears later is not accepted unseen, cmd_accept_line), `phase`) through the same `_overtake` /
    `_asking_session` rules as every other `ask`, and prints it with the only reply that counts: the user's own
    FIRST reply, exactly `accept: <reason>`; the listed yes words are never offered. `accept-line` reads the
    reply."""
    phase = st.get("phase")
    if not _finish_pending(st):
        die("A done-means line can be accepted only at the final review, when an unproven line holds the finish; the "
            f"run is {PHASE_PLAIN.get(phase, phase)} (not at the final review). Nothing was asked.")
    if not _approved_after_dm(st):
        ok("This run's plan was approved before unproven done-means lines held the finish, so no line needs "
           "accepting: its unproven lines are shown but do not stop the run from being marked done. Nothing was "
           "asked; ask for the final approval as usual (`ratchet.py ask human-approve`).")
        return
    table = done_means_table(ctx, ctx.plan() or {"checkpoints": []}, st)
    if not isinstance(table, list):
        die(f"There is no done-means table to accept a line from ({table}). Nothing was asked.")
    n = len(table)
    unproven = [e["number"] for e in table if e.get("verdict") == "unproven"]
    none_left = ("Nothing is unproven: every done-means line is proven or already accepted, so the finish is not held "
                 "and there is nothing to accept.")
    spec = (args.mode or "").strip()
    if getattr(args, "ids", None):
        die(f"ask accept-line takes the line numbers as one comma-separated value, e.g. `ratchet.py ask accept-line "
            f"{spec},{args.ids}`, not `{spec} {args.ids}` (the second value would be dropped). Nothing was asked.")
    if not spec and not unproven:
        die(f"{none_left} Nothing was asked.")
    if not spec:
        die("ask accept-line needs the line numbers to accept, e.g. `ratchet.py ask accept-line 2` or `ratchet.py ask "
            f"accept-line 2,3` (the numbers the final review's table shows; unproven now: {_lines_word(unproven)}). "
            "Nothing was asked.")
    nums, bad = [], []
    for tok in spec.split(","):
        t = tok.strip()
        try:
            v = int(t)
        except ValueError:
            bad.append(t)
            continue
        if not 1 <= v <= n:
            bad.append(t)
            continue
        if v not in nums:
            nums.append(v)
    if bad:
        shown = ", ".join(f'"{b}"' if b else "an empty entry" for b in bad)
        die(f"{shown} is not a done-means line of this plan: the real line numbers are 1 to {n} (unproven now: "
            f"{_lines_word(unproven)}). Nothing was asked.")
    by_num = {e["number"]: e for e in table}
    acc = _accepted_lines(st)
    probs = []
    for v in nums:
        verdict = by_num[v].get("verdict")
        if verdict == "accepted":
            rec = by_num[v].get("accepted") or acc.get(v) or {}
            probs.append(f"line {v} is already accepted (by {rec.get('accepted_by', '?')}: "
                         f"{' '.join(str(rec.get('reason') or '').split())[:120]})")
        elif verdict == "proven":
            probs.append(f"line {v} is already proven")
        elif verdict != "unproven":
            probs.append(f"line {v} is {verdict or 'not judged'}")
    if probs:
        die(f"{'; '.join(probs)}. " + (none_left if not unproven else "Only a line that is unproven right now can be "
            f"accepted (unproven now: {_lines_word(unproven)}).") + " Nothing was asked.")
    nums.sort()  # "3,2" and "2,3" are the same question, so a re-print in another order is not an overtake
    spec_txt = ",".join(str(i) for i in nums)
    # the lines are the question's target (what it is about), not a mode (the argument `accept-line` takes: none), so
    # `_overtake` tells a question about other lines from this one printed again, and NOT ASKED names its lines
    overtook = _overtake(ctx, st, "accept-line", None, target=spec_txt)
    asked = now()
    shown = {str(v): [r for r in (by_num[v].get("reasons") or []) if not str(r).startswith(HELD_AGAIN_PREFIX)]
             for v in nums}
    st["pending"] = {"action": "accept-line", "mode": None, "target": spec_txt, "ids": nums, "covered": shown, "asked_at": asked,
                     "phase": phase, "prev_awaiting": st.get("awaiting_since"),
                     "session": _asking_session(ctx, st, "accept-line"), **overtook}
    st["awaiting_since"] = asked
    ctx.log(st, "question_asked", action="accept-line", ids=nums)
    ctx.save_state(st)
    if overtook:
        print(_not_asked_text(f"`ratchet.py ask accept-line {spec_txt}`", overtook))
        return
    named = "; ".join(f"line {v}: \"{by_num[v]['text']}\" ({'; '.join(by_num[v].get('reasons') or []) or 'unproven'})"
                      for v in nums)
    them, hold = ("them", "hold") if len(nums) != 1 else ("it", "holds")
    print(f"ASK THE USER: The finish is held because {'these done-means lines are' if len(nums) != 1 else 'this done-means line is'} "
          f"unproven: {named}. Shall I accept {_lines_word(nums)} as unproven, with your own reason, so {'they' if len(nums) != 1 else 'it'} "
          f"no longer {hold} the finish? To accept, your reply must be exactly: accept: <your reason>. Only your first "
          f"reply counts, and only that exact form (starting with \"accept: \") accepts {them}; any other reply accepts "
          "nothing.")
    print(ASK_ALONE)


def _ask_paid_provider(ctx, st, args):
    """`ask paid-provider <tool> <model>`: the developer's OK to spend money on this one model, through
    `providers --add`, the next time it is run for this exact tool and model. This spends real money (a
    per-use request, or an unknown-cost one treated the same way), so it needs its own exact reply naming the
    model (_paid_provider_reply), never the generic listed-yes words used for every other question."""
    tool, model = args.mode, args.ids
    overtook = _overtake(ctx, st, "paid-provider", f"{tool}:{model}")
    asked = now()
    st["pending"] = {"action": "paid-provider", "mode": f"{tool}:{model}", "tool": tool, "model": model,
                     "asked_at": asked, "prev_awaiting": st.get("awaiting_since"),
                     "session": _asking_session(ctx, st, "paid-provider"), **overtook}
    st["awaiting_since"] = asked
    ctx.log(st, "question_asked", action="paid-provider", mode=f"{tool}:{model}")
    ctx.save_state(st)
    if overtook:
        print(_not_asked_text(f"`ratchet.py ask paid-provider {tool} {model}`", overtook))
        return
    exact = _paid_provider_reply(model)
    print(f"ASK THE USER: {tool}'s model {model} costs money per use (or its cost is unknown, which Ratchet "
          "treats the same way), including one small test request right now to check it works, before it is "
          f"ever used for a review. Shall I use it? Only one exact reply agrees: reply exactly \"{exact}\". Any "
          "other reply means no.")
    print(ASK_ALONE)


def cmd_choice(args):
    """Record which lettered option the user picked, from their first reply after `ask choice`. In a
    director-enrolled lane a chat reply picks nothing (the same rule as every other approval there): the letter
    comes from `choice <L> --director-token <t>`, where the token was signed for exactly that letter
    (`director-sign choice <L>`, after the lane's own `ask choice`); it is recorded exactly as a user's pick,
    including what the option unlocks."""
    ctx = Ctx(find_root())
    st = ctx.state()
    _require_pending(st, "choice", ctx=ctx)
    p = st["pending"]
    if p.get("overtook"):
        _clear_pending(st)
        ctx.log(st, "choice_unclear", reply="(asked while another question was waiting)")
        ctx.save_state(st)
        die("These options were printed while another question was still waiting for the user's first reply, so their "
            "reply could be meant for either. Nothing was recorded. Run `ratchet.py ask choice ...` again on its own "
            "and wait for their pick.")
    opts = p.get("options") or []
    token = getattr(args, "director_token", None)
    given = (getattr(args, "letter", None) or "").strip().upper()
    if token or approval_mode(ctx) == "director":
        if token and given not in opts:
            die(f"choice needs the signed letter with a director token (one of {', '.join(opts)}): "
                "`ratchet.py choice <letter> --director-token <t>`. Nothing was recorded.")
        # _require_approval's own director check and token verification (the letter is bound into the token, so a
        # token for another letter, lane, question or pause is refused): dies here when this lane is
        # director-enrolled and no (or a bad) director token was given; a chat letter is never enough in that lane.
        by = _require_approval(ctx, st, "choice", token, bind=(given,))["by"]
        _policy_apply(args, ctx, st, "choice", given)
        letter, reply = given, f"director-signed choice {given}"
    else:
        msgs = _replies(ctx, st, p.get("asked_at"), p)  # only the chat the options were put to can pick one
        if not msgs:
            die("No reply from the user yet. End your turn and wait for them to pick an option.")
        entry = msgs[0]  # the first reply answers the question
        letter = choice_letter(entry.get("prompt", ""), opts)
        if ctx.config().get("verify_transcripts", True) and not human_override(
                "record the option the user picked", ctx, "choice (recorded without the transcript check)"):
            good, why = _transcript_ok(entry, p.get("asked_at"))
            if not good:
                die(f"Couldn't confirm that reply came from the user ({why}). Ask them to reply again in this chat.")
        if not letter:
            _clear_pending(st)
            ctx.log(st, "choice_unclear", reply=entry.get("prompt", "")[:200])
            ctx.save_state(st)
            die(f"The user's reply isn't a clear pick of one option: \"{entry.get('prompt', '')[:120]}\". Nothing was "
                "recorded. Answer what they said; if you still need a decision, ask again (`ratchet.py ask choice ...`).")
        if given and given != letter:
            die(f"The user's reply picked option {letter}, not {given}. Nothing was recorded; run `ratchet.py choice` "
                "with no letter (or with theirs) to record their pick.")
        by, reply = "human", entry.get("prompt", "")[:200]
    files = (p.get("locked") or {}).get(letter) or []
    guard = (p.get("guardrail") or {}).get(letter)
    unblock = st["phase"] == "blocked"
    if files or unblock or guard:
        st["choice_allow"] = {"letter": letter, "files": files, "cp": st.get("current"), "at": now(),
                              "reply": reply, "unblock": unblock, "guardrail": guard, "by": by}
    _clear_pending(st)
    ctx.log(st, "choice_made", letter=letter, approves=files, by=by, **_policy_field(args))
    ctx.save_state(st)
    msg = f"The {'director' if by == 'director' else 'user'} picked option {letter}."
    if files:
        msg += (f" That approves changing {', '.join(files)}: make that change (through the sub-agent that owns it), "
                "then run `ratchet.py approve-changes`. No further question is needed.")
    if guard:
        msg += (f" That adds a guardrail step for '{guard}': run `ratchet.py guardrail --kind {guard} --title \"...\" "
                "--why \"...\" --check-command \"<check> {target}\" --bad-example <fixture path> "
                "--test-command \"...\" --test-file <path>`.")
    if unblock:
        msg += (" The run is blocked: run `ratchet.py human-approve`"
                + (" with a director token (`director-sign human-approve`)" if by == "director" else "")
                + " to resume it, then act on the choice.")
    ok(msg)


def _choice_covers(allow: dict, probs: list[str]) -> bool:
    files = allow.get("files") or []
    if not files:
        return False
    return bool(probs) and all(any(pr == f"reference file {f}" or pr.startswith(f"test file {f} ")
                                   or pr.startswith(f"test file {f}:") for f in files) for pr in probs)


def _require_pending(st, action, mode=None, ctx=None):
    """Die unless the question for `action` is the one waiting. With `ctx`, in a director-enrolled lane the refusal
    names the director's one-step command instead of a chat question: nobody there answers one."""
    p = st.get("pending") or {}
    if p.get("action") != action or (mode and p.get("mode") != mode):
        if ctx is not None and action in DIRECTOR_APPLY_ACTIONS and approval_mode(ctx) == "director":
            if action == "choice":
                die("No lettered question is waiting, and in this director-enrolled lane a chat reply picks nothing. "
                    "Run `ratchet.py ask choice --options ...` to register the options, then the director picks one "
                    f"with `{_director_apply_cmd(ctx, 'choice')}` (or signs it with `director-sign choice <letter>` "
                    "and you apply the token with `ratchet.py choice <letter> --director-token <t>`). Nothing was changed.")
            die("This lane is director-enrolled, so there is no question to put in chat for this: the director "
                f"approves it in one step with `{_director_apply_cmd(ctx, action, mode)}` (or signs it after this "
                f"lane's `ask` with `director-sign {action}`, and you apply the token with `ratchet.py {action}"
                f"{' ' + mode if mode else ''} --director-token <t>`). Nothing was changed; end your turn saying "
                "what you are waiting for.")
        die(f"First run {_ask_now(ctx, st, action) if ctx and not mode else _ask_cmd(action, mode)}, show the user the question it prints, "
            "and wait for their reply. Replies from before the question don't count.")


def _clear_pending(st):
    p = st.pop("pending", None) or {}
    if st["phase"] in ("awaiting_plan_approval", "awaiting_checkpoint_review", "awaiting_final_review", "blocked", "done"):
        st["awaiting_since"] = now()
    else:
        st["awaiting_since"] = None


def cmd_cancel(args):
    """Abandon the active run — only after the user confirms. Commits already made are kept."""
    ctx = Ctx(find_root())
    st = ctx.state()
    if st["phase"] in ("done", "cancelled"):
        ok(f"Run '{st['slug']}' is already {st['phase']}.")
        return
    _require_pending(st, "cancel")
    msg = _require_human(ctx, st, "cancel", getattr(args, "director_token", None))
    st.pop("pending", None)
    st["cancelled_from"] = st["phase"]
    st["phase"] = "cancelled"
    st["current"] = None
    st["blocked_reason"] = args.reason or "cancelled by the user"
    ctx.log(st, "cancelled", by=msg["by"], note=msg.get("prompt", "")[:200])
    ctx.save_state(st)
    register_active(ctx.root, None)
    stopped = _stop_server(ctx.ratchet / "viewer.json")
    commits = [c.get("commit") for c in st["checkpoints"].values() if c.get("commit")]
    ok(f"Run '{st['slug']}' cancelled." + (" Viewer server stopped." if stopped else "")
       + (f" Checkpoint commits kept: {', '.join(commits)} — ask the user whether to keep or revert them."
          if commits else ""))


def cmd_set_review(args):
    """Change how often the user reviews (end | each | none) — the user's call, so it needs their confirmation."""
    ctx = Ctx(find_root())
    st = ctx.state()
    _require_pending(st, "set-review", args.mode)
    msg = _require_human(ctx, st, "set-review", getattr(args, "director_token", None))
    old = st.get("human_review")
    st["human_review"] = args.mode
    if st.get("approved"):
        st["approved"]["human_review"] = args.mode
    _clear_pending(st)
    ctx.log(st, "review_mode_changed", by=msg["by"], old=old, new=args.mode)
    ctx.save_state(st)
    ok(f"Review mode {old} → {args.mode}.")


def cmd_approve_changes(args):
    """The user confirmed a change to the plan, test plans or rules after approval: accept it as the new baseline."""
    ctx = Ctx(find_root())
    st = ctx.state()
    errs = validate_plan(ctx.plan())  # before integrity_problems/approval_snapshot/_plan_hash trust any
    if errs:                         # checkpoint's "id": a malformed plan is a named plan problem, never a
        die("Plan invalid:\n  - " + "\n  - ".join(errs))  # bare KeyError.
    probs = integrity_problems(ctx, st)
    if not probs:
        ok("Nothing has changed since approval.")
        return
    allow = st.get("choice_allow") or {}
    if allow and allow.get("cp") == st.get("current") and not getattr(args, "director_token", None) \
            and _choice_covers(allow, probs):
        # the recorded pick is the approval (a director-signed pick counts as the director's)
        msg = {"by": allow.get("by", "human"), "prompt": f"picked option {allow['letter']}: {allow.get('reply', '')}"}
        allow["files"] = []
        if not allow.get("unblock") and not allow.get("guardrail"):
            st.pop("choice_allow", None)
    else:
        if allow.get("files") and allow.get("cp") == st.get("current") \
                and (st.get("pending") or {}).get("action") != "approve-changes":
            extra = [pr for pr in probs if not _choice_covers(allow, [pr])]
            if approval_mode(ctx) == "director":
                die(f"The director's pick of option {allow['letter']} approved changing {', '.join(allow['files'])}, "
                    f"but these changed too: {_problems_for_director(extra)}. Undo them, or have the director approve them all "
                    f"with `{_director_apply_cmd(ctx, 'approve-changes')}`. Nothing was changed.")
            die(f"The user's pick of option {allow['letter']} approved changing {', '.join(allow['files'])}, but these "
                f"changed too: {'; '.join(extra)}. Undo them, or show the user exactly what changed and ask "
                "(`ratchet.py ask approve-changes`).")
        _require_pending(st, "approve-changes", ctx=ctx)
        msg = _require_human(ctx, st, "approve-changes", getattr(args, "director_token", None))
        if msg["by"] == "director":
            _policy_apply(args, ctx, st, "approve-changes", "")
    plan = ctx.plan()
    new_ids = [c["id"] for c in plan["checkpoints"] if c["id"] not in st["checkpoints"]]
    if new_ids:
        _validate_new_checkpoints(ctx, plan, new_ids)
    for cid in new_ids:
        st["checkpoints"][cid] = new_cp_state(cp_by_id(plan, cid))
    cur = st.get("current")
    if cur and (st["checkpoints"].get(cur) or {}).get("red_tests") is not None:
        st["checkpoints"][cur]["red_tests"] = _snapshot_tests(ctx, cp_by_id(ctx.plan(), cur))
    # Every checkpoint's open, unrecorded, pin-less legacy round gets its one-time migration stamp here, not only
    # the ones named in this approval's `probs`: the snapshot rewrite below (_approval_snapshot_keeping_dm) records
    # every checkpoint's live reviewers unconditionally, so a checkpoint left out here would have its pre-upgrade
    # pin silently baked into the new baseline the first time ANY checkpoint is approved, losing its one-time
    # migration reopen for good. See _stamp_legacy_round_baselines for the full rule.
    _stamp_legacy_round_baselines(st, plan)
    st["approved"] = _approval_snapshot_keeping_dm(ctx, st)  # after the red baseline moved, so the snapshot records it
    _clear_pending(st)
    ctx.log(st, "changes_approved", by=msg["by"], changed="; ".join(probs)[:400], **_policy_field(args))
    ctx.save_state(st)
    build_viewer(ctx)
    ok("Accepted as the new baseline: " + "; ".join(probs))


def hooks_view(ctx, st=None) -> dict:
    """hooks_status plus `waived`: the user chose to build without hooks and nothing enforces the gates yet."""
    hs = hooks_status(ctx.root, ctx.config())
    st = st or ctx.state()
    if _waiver_applies(ctx.root, ctx.config(), st):
        hs["waived"] = True
    return hs


def _enforcement_beats(root: Path, cfg) -> list:
    """Timestamps of guard/stop heartbeats from this host. The prompt hook is only the consent channel."""
    host = VENDOR_TO_HOST.get(detect_host(cfg or {}), "unknown")
    hb = read_heartbeat(root)
    out = []
    for ev in ("guard", "stop"):
        e = hb.get(ev)
        if isinstance(e, dict) and (host == "unknown" or e.get("host") == host):
            t = _parse_iso(e.get("at"))
            if t and t <= _dt.datetime.now(_dt.timezone.utc) + _dt.timedelta(minutes=5):
                out.append(t)
    return out


def _enforcement_active(root: Path, cfg) -> bool:
    cutoff = _dt.datetime.now(_dt.timezone.utc) - _dt.timedelta(hours=24)
    return bool(hooks_status(root, cfg)["installed"]) or any(t > cutoff for t in _enforcement_beats(root, cfg))


def _waiver_applies(root: Path, cfg, st) -> bool:
    """A recorded waiver counts only while the enforcement hooks (guard/stop) are neither installed nor seen firing
    since it was given, so it cannot resurface after an uninstall without new consent."""
    w = st.get("hooks_waived")
    if not w or _enforcement_active(root, cfg):
        return False
    since = _parse_iso(w.get("at")) if isinstance(w, dict) else None
    return not (since and any(t > since for t in _enforcement_beats(root, cfg)))


def cmd_hooks_waive(args):
    """Record that the USER chose to build without hooks (after `ask hooks-waive` and their clear yes)."""
    ctx = Ctx(find_root())
    st = ctx.state()
    token = getattr(args, "director_token", None)
    if not token:
        _require_pending(st, "hooks-waive")
    if _enforcement_active(ctx.root, ctx.config()):
        st.pop("pending", None)
        ctx.save_state(st)
        ok("Ratchet hooks are already active here, so there is nothing to waive; nothing was recorded.")
        return
    # only a reply typed after the hooks question counts, and it is spent on this question alone
    view = dict(st, awaiting_since=st["pending"]["asked_at"]) if not token else st
    msg = _require_human(ctx, view, "hooks-waive", token)
    already = bool(st.get("hooks_waived"))
    if token:
        st["hooks_waive_n"] = int(st.get("hooks_waive_n", 0)) + 1  # spend the token
    if not already:
        st["hooks_waived"] = {"at": now(), "by": msg["by"], "prompt": msg.get("prompt", "")[:200]}
        ctx.log(st, "hooks_waived", by=msg["by"], note=msg.get("prompt", "")[:200])
    _clear_pending(st)
    ctx.save_state(st)
    build_viewer(ctx)
    ok("Already recorded: the user chose to build without hooks." if already else
       "Recorded: the user chose to build without hooks. The checks are advice only; missing hooks never block work.")


def _adv_block_kind(st, cp_id) -> str | None:
    """Classifies the adversarial block the run is in for `cp_id`, when any: "own" when `cp_id` is current and
    `blocked` on its OWN round limit (`cmd_adv_record`'s 'still has N finding(s) after R rounds', or
    `cmd_reviewers`'s 'R adversarial rounds used without approval') -- the same classification `blocked_options`
    uses to put simplify/change/stop ahead of raise in its menu, and the one state where `check-in --decision
    simplify|change` reuses check-in's own simplify record to grant this step one more review round (the soft
    check-in trigger, an open `ci['open']`, and this hard block never coincide, because `reviewers` refuses to
    open a further round while a check-in sits open, so the hard cap is only ever reached after any earlier
    check-in was already resolved); "run_wide" when `cp_id` is current and blocked instead on the run-wide round
    cap (`cmd_reviewers`), which also blocks before a new round opens while `cp_id`'s last recorded round still
    has open findings of its own. None for any other block (behavior, UI, a different checkpoint's reason, or no
    block at all): accepting a finding or raising `cp_id`'s own cap does not fix those, so the run should stay
    exactly as blocked as it was."""
    if st.get("phase") != "blocked" or st.get("current") != cp_id:
        return None
    r = (st.get("blocked_reason") or "")
    rl = r.lower()
    if "rounds used" in rl or ("adversarial" in rl and re.search(r"after \d+ rounds", rl) is not None):
        return "own"
    if r.startswith("Run-wide adversarial round cap reached"):
        return "run_wide"
    return None


def _code_changed_since_round(ctx, rnd) -> bool:
    """True when the code has changed since this adversarial round's own fingerprint was captured, excluding
    `.ratchet/` and any chat transcript recorded since the round opened (the same exclusions `complete` applies
    to its own gates): `ask accept-finding` and `accept-finding` must refuse once this is true, rather than act
    on a round that no longer matches the code (the round's own `fingerprint`/`round` identity check only catches
    a NEW round having opened since the question was asked; it says nothing about code edited while the stale
    round just sits there, still the current one, still blocked)."""
    fp = fingerprint(ctx.root)
    if fp["id"] == rnd["fingerprint"]:
        return False
    chat_paths = _chat_transcript_paths(ctx, rnd.get("opened_at"))
    changed = [f for f in changed_files(ctx.root, {"kind": fp.get("kind", "git-tree"), "id": rnd["fingerprint"]}, fp)
               if f != RATCHET_DIR and not f.startswith(RATCHET_DIR + "/") and f not in chat_paths]
    return bool(changed)


def _unblock(ctx, st, by, note) -> str:
    """Resolves a `blocked` run back to the phase it was blocked from (building, or the review phase it reaches
    when nothing is left to build), exactly as `human-approve`'s own unblock does: resets the run-wide
    adversarial round budget when that cap was the cause ("the user chose to continue: the run's budget starts
    again"), resets the current checkpoint's own failing-gate attempt counters, picks up the next unfinished
    checkpoint when none is current, and consumes any stored `choice_allow['unblock']` so a stale pick from an
    earlier block can never unblock a LATER one without a fresh question. The one place both `human-approve` and
    `accept-finding` resolve a block, so a fix to how unblocking works is made once, not twice. Returns the phase
    the run is in afterward."""
    allow = st.get("choice_allow") or {}
    if allow.get("unblock"):
        allow["unblock"] = False
        if not allow.get("files") and not allow.get("guardrail"):
            st.pop("choice_allow", None)
    order = [c["id"] for c in (ctx.plan() or {"checkpoints": []})["checkpoints"]]
    back = st.pop("blocked_from", None) or "building"
    if back == "blocked":
        back = "building"
    cur = st.get("current")
    preserve_adv = (_adv_block_kind(st, cur) == "own") if cur else False  # read before phase/blocked_reason are
    # cleared below: True exactly when CUR's OWN adversarial round limit caused this block -- not the run-wide
    # cap, not any other checkpoint's reason -- in which case its attempts must NOT be reset below (CP1: only
    # raise-limit, with the user's own reason, ever grants a step more review rounds; this generic unblock must
    # not do it for free, whether reached via human-approve directly, via accept-finding, or via a lettered
    # block-menu choice that calls it). A run-wide-cap block (which is not cur's own round limit) still resets
    # cur's adversarial attempts here, same as every other failing gate.
    st["phase"] = back
    st["blocked_reason"] = None
    cfg = ctx.config()
    if int(st.get("adv_rounds_total", 0)) >= cfg["max_adversarial_rounds_run"]:
        st["adv_rounds_total"] = 0  # the user chose to continue: the run's budget starts again
    if back == "building" and not cur:  # nothing current: pick up the next unfinished checkpoint
        pending = [c for c in order if st["checkpoints"][c]["status"] != "done"]
        if pending:
            _advance(st, pending[0], fingerprint(ctx.root)["id"], _head_sha(ctx.root))
        else:
            st["phase"] = "awaiting_final_review"
    elif cur:
        # resets the attempt counters on the current checkpoint's other failing gates
        for name, g in st["checkpoints"][cur]["gates"].items():
            if g["status"] != "passed" and not (preserve_adv and name == "adversarial"):
                g["attempts"] = 0
        st["checkpoints"][cur]["guardrail_tries"] = 0
    ctx.log(st, "unblocked", by=by, note=note, back_to=st["phase"])
    return st["phase"]


def cmd_accept_finding(args):
    """Record the open findings the user accepted: only their FIRST reply after `ask accept-finding`, from the
    owning chat, in the exact form `accept: <reason>`, accepts them (reuses the same consent machinery and rules
    as every other approval: _require_pending, _replies, the transcript check). In a director-enrolled lane a chat
    reply never counts (same rule as every other approval here): a director token signed for this action is
    required instead, with --reason carrying the director's own reason since there is no chat reply to read one
    from. When every open finding of that round is then accepted, the adversarial gate passes for that round's
    fingerprint without another round; a later code change (a new fingerprint) brings back the normal review
    rules. When no open finding remains, an open check-in for this step (reviews dragging) is also cleared: it had
    nothing left to pause on."""
    ctx = Ctx(find_root())
    st = ctx.state()
    _require_pending(st, "accept-finding", args.cp, ctx=ctx)
    p = st["pending"]
    cp = p["mode"]
    ids = p.get("ids") or []
    if p.get("overtook"):
        _clear_pending(st)
        ctx.log(st, "accept_finding_unclear", cp=cp, ids=ids)
        ctx.save_state(st)
        die(f"This question was printed while another one (shall I {_question_what(p['overtook'], p.get('overtook_mode'), p.get('overtook_target'))}"
            "?) was still waiting for the user's first reply, so their reply could be meant for either. Nothing was "
            f"accepted. Run `ratchet.py ask accept-finding {cp} {','.join(ids)}` again on its own.")
    token = getattr(args, "director_token", None)
    if token or approval_mode(ctx) == "director":
        # --reason is checked BEFORE the token is verified or anything is cleared (standards #11): a token is not
        # a one-time secret by itself here (unlike a chat reply), but _require_approval's own verification is
        # bound to st['awaiting_since'], which _clear_pending resets once the question is answered, so clearing
        # pending over a merely-forgotten --reason would make the director's own still-valid token stale, costing
        # a second signature for one missing flag. Dying here first, with the question still pending and nothing
        # saved, means the SAME command with --reason added simply works.
        reason = (getattr(args, "reason", None) or "").strip()
        if not reason:
            die(f"accept-finding needs --reason \"...\" when a director token approves it (there is no chat reply "
                f"to read a reason from). Nothing was accepted, and the question is still waiting: run the same "
                f"command again with --reason \"...\" added.")
        # Reuses _require_approval's own director check and token verification (standards #2/#19: don't re-implement
        # the same gate): dies here, exactly as every other approval does, when this lane is director-enrolled and
        # no (or a bad) director token was given; a chat "accept: ..." reply is never enough in that lane.
        appr = _require_approval(ctx, st, "accept-finding", token)
        by = appr["by"]
        _policy_apply(args, ctx, st, "accept-finding", cp, ids)
    else:
        msgs = _replies(ctx, st, p.get("asked_at"), p)  # only the chat the question was asked in can answer it
        if not msgs:
            die("No reply has been recorded in the owning chat since this question was asked. End your turn and wait "
                "for the user's reply, exactly `accept: <reason>`; a reply typed in another chat does not count.")
        entry = msgs[0]  # the first reply answers the question; later messages never do
        reply = entry.get("prompt", "")
        reason = _accept_reply_reason(reply)
        if reason is None:
            _spend_question(ctx, st, reply)
            die(f"The user's first reply after the question was not the exact form `accept: <reason>`: \"{reply[:120]}\". "
                "Nothing was accepted, and the question is closed, so a later reply in that form does not count. Run "
                f"`ratchet.py ask accept-finding {cp} {','.join(ids)}` again if they still want to accept them.")
        if ctx.config().get("verify_transcripts", True):
            good, why = _transcript_ok(entry, p.get("asked_at"))
            if not good:
                _spend_question(ctx, st, reply)
                die(f"Couldn't confirm that reply came from the user ({why}). Nothing was accepted. Run `ratchet.py ask "
                    f"accept-finding {cp} {','.join(ids)}` again and ask them to reply in this chat.")
        by = "human"
    cps = (st.get("checkpoints") or {}).get(cp)
    if cps is None:
        _clear_pending(st)
        ctx.save_state(st)
        die(f"No such checkpoint {cp} any more. Nothing was accepted.")
    rnd = cps.get("adv_round")
    if not rnd or rnd.get("round") != p.get("round") or rnd.get("fingerprint") != p.get("fingerprint"):
        # the round itself moved on (a new one was opened, e.g. after a real code change): `reviewers` already
        # re-checks the fingerprint when that happens, so this is never fooled by anything that only touches the
        # chat transcript (a reply does not change the code, so it never opens a new round on its own)
        _clear_pending(st)
        ctx.save_state(st)
        die(f"The review round for {cp} has moved on since this question was asked (a new round opened, most "
            "likely because the code changed). Nothing was accepted. Run "
            f"`ratchet.py ask accept-finding {cp} ...` again against the current round.")
    if _code_changed_since_round(ctx, rnd):
        _clear_pending(st)
        ctx.save_state(st)
        die(f"{cp}: the code changed since this review round; run a new review round first. Nothing was accepted.")
    g = cps["gates"]["adversarial"]
    # State-filtered (not the raw file): a crash between the state commit and the evidence-file writes of an
    # earlier accept-finding call can leave open-findings.json stale, still listing an id state already marked
    # accepted. Checking the state-derived list (and deferred_by_key) rather than the raw file means a retry of
    # that same id is always caught as already-accepted here, never re-recorded as a second acceptance.
    open_findings = _adv_open_findings(ctx, cp, rnd, cps)
    open_by_key = {_finding_key(f): f for f in open_findings}
    deferred_by_key = {_finding_key(f): f for f in _round_deferred(cps, rnd["round"])}
    already = [i for i in ids if (deferred_by_key.get(i) or {}).get("accepted")]
    if already:
        _clear_pending(st)
        ctx.save_state(st)
        die(f"{', '.join(already)} already closed/accepted earlier for {cp}; nothing new to do. Nothing was changed.")
    missing = [i for i in ids if i not in open_by_key]
    if missing:
        _clear_pending(st)
        ctx.save_state(st)
        die(f"{', '.join(missing)} is not an open finding of {cp}'s current round. Nothing was accepted.")
    at = now()
    accepted_entries = [dict(open_by_key[i], accepted=True, reason=reason, accepted_at=at, accepted_by=by,
                            round=rnd["round"], **_policy_field(args)) for i in ids]
    remaining_open = [f for f in open_findings if _finding_key(f) not in ids]
    dest = _adv_round_dir(ctx, cp, rnd["round"])

    # Simplified write order (no "heal from state" machinery): everything below the state commit (c) is written
    # BEFORE it, so a crash before (c) leaves AT MOST a harmless extra learnings.md note or an un-committed
    # deferred-findings.json write -- the accept itself never happened (state still shows every id open), so a
    # plain retry (the question is still pending) starts clean and finishes once. A crash can never leave a
    # COMMITTED accept without its own notes, because both are written first.
    # (a) .ratchet/learnings.md: one line per accepted entry, keyed by a marker unique to this run, checkpoint,
    # round AND reviewer/id (never just reviewer/id, which repeats across rounds and checkpoints) so a retry
    # after an earlier crash that already wrote the line never duplicates it, and two DIFFERENT findings that
    # happen to share a reviewer/id (a later round, or a later checkpoint) both get their own line.
    learnings = _learnings_text(ctx)
    for i in ids:
        f = open_by_key[i]
        marker = f"Accepted finding {st['slug']}/{cp}/round-{rnd['round']}/{_finding_key(f)} ("
        if marker in learnings:
            continue
        # One learnings.md bullet is one line: a multi-line description or reason (the reason especially, since
        # ACCEPT_FINDING_RE accepts one spanning several lines) is collapsed to a single line here, in the
        # learnings text only; the reason kept verbatim everywhere else (accepted_entries, round_rec, state) is
        # untouched.
        desc_line = " ".join(str(f.get("description", "")).split())[:200]
        reason_line = " ".join(reason.split())
        _append_learning(ctx, f"{marker}{cp}, {f.get('severity', '?')}): "
                               f"{desc_line}. Reason: {reason_line}",
                          f"{by}, accept-finding")
        learnings += marker  # a second id accepted in this same call never duplicates its own line either
    # (b) the round's own deferred-findings.json, written WHOLE for this round (never appended) from the list
    # state is about to commit.
    new_deferred = (cps.get("deferred") or []) + accepted_entries
    round_deferred = [f for f in new_deferred if f.get("round") == rnd["round"]]
    dest.mkdir(parents=True, exist_ok=True)
    write_json(dest / "deferred-findings.json", round_deferred)
    cps["deferred"] = new_deferred
    rounds = g.get("rounds") or []
    # Found by the round number stamped on the entry, not by list position: a round `reviewers` opens and then
    # replaces before recording (the fingerprint changed) advances rnd['round'] without adding an entry, so
    # position alone can name the wrong entry, or none. A round recorded before that stamp existed falls back to
    # position for that one entry only.
    round_rec = next((rr for rr in rounds if rr.get("round") == rnd["round"]), None)
    if round_rec is None and rounds and 0 < rnd["round"] <= len(rounds):
        round_rec = rounds[rnd["round"] - 1]
    if round_rec is not None:
        round_rec.setdefault("accepted", []).extend(
            [{"id": i, "reason": reason, "at": at, "by": by} for i in ids])
    ctx.log(st, "finding_accepted", cp=cp, ids=ids, reason=reason[:200], by=by, **_policy_field(args))
    unblocked_to = None
    if not remaining_open:
        g["status"] = "passed"
        # stamped with the round's OWN fingerprint (what was actually reviewed), not a fresh one: a reply itself
        # changes nothing in the code, but recomputing now would still pick up whatever it touched meanwhile
        # (e.g. the chat transcript, if the agent CLI keeps it inside the project).
        g["fingerprint"] = {"kind": fingerprint(ctx.root).get("kind", "git-tree"), "id": rnd["fingerprint"]}
        # the round's OWN opened_at, not now(): that is when this fingerprint was actually captured, so `complete`
        # correctly looks for chat replies (never the code) from then on, the ask/reply this acceptance needed
        # included, when it decides whether anything that matters has changed since.
        g["passed_at"] = rnd.get("opened_at") or at
        cps["step"] = _earliest_open_step(cps)
        # The user's accept IS their decision on the block when the run is stuck here only because of this
        # checkpoint's own adversarial round limit OR the run-wide round cap (never a lettered option: the only
        # way here is the plain accept_note line `next`/`status` print, pointing at `ask accept-finding` plus the
        # user's own `accept: <reason>` reply): the gate just passed, so there is nothing left to be stuck on.
        # Leaving phase at "blocked" would make `complete` refuse ("Not building") and `status`/`next` keep
        # showing a block whose cause, the open findings, is already resolved. Any OTHER block reason (behavior,
        # UI, a different checkpoint) is left exactly as it was: accepting a finding here does not resolve it.
        # `_unblock` is the same helper `human-approve` uses to resolve a block: it resets the run-wide round
        # budget when that cap was the cause, resets this checkpoint's own gate attempt counters, and consumes
        # any stored choice_allow so a later, unrelated block can't be unblocked by this same stale pick.
        if _adv_block_kind(st, cp) in ("own", "run_wide"):
            unblocked_to = _unblock(ctx, st, by, "accept-finding resolved the round limit")
        # No open blocking finding remains for this step, so any check-in paused on this gate dragging has nothing
        # left to pause on: clear it the same as `reviewers` requires it resolved before another round, otherwise
        # it would sit open forever (check-in only ever clears itself through `check-in --decision simplify/stop`,
        # never through acceptance) and `status`/`next` would keep reporting one that is already moot.
        ci = _checkin_state(cps)
        if ci.get("open"):
            ctx.log(st, "checkin_resolved_by_accept", cp=cp, round=ci["open"]["round"], ids=ids)
            ci["open"] = None
    _clear_pending(st)
    # (c) commit state: the one atomic, authoritative write (standards #12) that says these findings are accepted.
    ctx.save_state(st)

    build_viewer(ctx)
    # (d) open-findings.json last: the file that says these findings still block, now rewritten to drop them.
    # Readers never need this file alone to know what is open: `_adv_open_findings` always computes it as the
    # file's own contents minus whatever state already records accepted for that round, so a stale copy left by a
    # crash between (c) and (d) is never mistaken for a reopened finding.
    write_json(dest / "open-findings.json", remaining_open)

    msg = f"Accepted {', '.join(ids)} for {cp} with reason: {reason}."
    if remaining_open:
        left = sorted(_finding_key(f) for f in remaining_open)
        msg += f" Still open: {', '.join(left)} - {cp} remains blocked until those are resolved or accepted too."
    else:
        msg += f" No open findings remain for {cp}: the adversarial gate is now passed without another round."
        if unblocked_to:
            msg += " The run is no longer blocked."
        if st.get("phase") == "building" and st.get("current") == cp and cps.get("step") == "complete":
            msg += f" Next: ratchet.py complete {cp}"
        elif st.get("phase") == "blocked":
            msg += (f" {cp}'s review now passes, but the run is still blocked "
                    f"({plain_reason(st.get('blocked_reason')) or st.get('blocked_reason')}); resolve that first "
                    "(see `ratchet.py next`).")
        else:
            msg += " Run `ratchet.py next` to see what happens now."
    ok(msg)


RAISE_LIMIT_RE = re.compile(r"^raise:\s*(.+)$", re.I | re.S)


def _raise_reply_reason(text: str) -> str | None:
    """The reason in a reply of the exact form `raise: <reason>`, or None when the reply is not that form (or
    gives no reason)."""
    m = RAISE_LIMIT_RE.match((text or "").strip())
    if not m:
        return None
    reason = m.group(1).strip()
    return reason or None


def cmd_raise_limit(args):
    """CP1: raise ONE checkpoint's adversarial round-limit cap by one round — only after `ask raise-limit CPn`
    and the owning chat's own FIRST reply after it, exactly `raise: <reason>` (never a lettered pick, never
    `human-approve`, which never raises anything). Only once per step, ever: once raised, the step records its
    own cap (`gates.adversarial.cap_raised_to`), so `cmd_reviewers`/`cmd_adv_record` compare attempts against
    THAT, not `cfg['max_adversarial_rounds']`, and a later `config --set max_adversarial_rounds=...` can never
    lift it again. The reason is appended to `.ratchet/learnings.md`: a standing instruction for later rounds
    and agents, exactly like any other human-review learning. Refuses outright, before recording anything,
    unless `_adv_block_kind(st, cp)` is "own" or "run_wide": the one-time raise only ever applies while the step
    is genuinely blocked on an adversarial round limit, the same precondition `_ask_raise_limit` enforces before
    asking. In a director-enrolled lane a chat `raise:` reply never counts (same rule as every other approval
    there): a director token signed for this step and this reason is required (`director-sign raise-limit CPn
    --reason "..."`, after the lane's own `ask raise-limit CPn`), with `--reason` repeating the signed reason since
    there is no chat reply to read one from; every other check (one raise per step, the block kind, the attempt
    count kept, the run-wide budget never reset) is the same as for a chat raise."""
    ctx = Ctx(find_root())
    st = ctx.state()
    _require_pending(st, "raise-limit", args.cp, ctx=ctx)
    p = st["pending"]
    cp = p["mode"]
    cps = (st.get("checkpoints") or {}).get(cp)
    if cps is None:
        _clear_pending(st)
        ctx.save_state(st)
        die(f"No such checkpoint {cp} any more. Nothing was raised.")
    if p.get("overtook"):
        _clear_pending(st)
        ctx.log(st, "raise_limit_unclear", cp=cp)
        ctx.save_state(st)
        die(f"This question was printed while another one (shall I {_question_what(p['overtook'], p.get('overtook_mode'), p.get('overtook_target'))}"
            "?) was still waiting for the user's first reply, so their reply could be meant for either. Nothing was "
            f"raised. Run `ratchet.py ask raise-limit {cp}` again on its own.")
    g = cps["gates"]["adversarial"]
    if g.get("cap_raised_to"):
        _clear_pending(st)
        ctx.save_state(st)
        die(f"{cp}'s review-round limit was already raised once (to {g['cap_raised_to']} rounds); it is never "
            "offered a second time. Nothing was changed.")
    if _adv_block_kind(st, cp) not in ("own", "run_wide"):
        _clear_pending(st)
        ctx.save_state(st)
        die(f"{cp} is not blocked on an adversarial review-round limit right now; raise-limit only applies then. "
            "Nothing was changed.")
    token = getattr(args, "director_token", None)
    if token or approval_mode(ctx) == "director":
        reason = (getattr(args, "reason", None) or "").strip()
        if not token:  # enrolled lane, no token: the missing token is the cause, named first (a chat reply is nothing)
            _require_approval(ctx, st, "raise-limit", None, bind=(cp,))
        # With a token, --reason is checked BEFORE the token is verified or anything is cleared (as accept-finding
        # does): the question stays pending and nothing is saved, so the SAME token with --reason added works.
        if not reason:
            die(f"raise-limit needs --reason \"...\" when a director token approves it (the reason the director "
                f"signed; there is no chat reply to read one from). Nothing was raised, and the question is still "
                f"waiting: run the same command again with --reason \"...\" added.")
        # _require_approval's own director check and token verification (the step and the reason are bound into
        # the token, so a token for another step, reason, lane or pause is refused): dies here when this lane is
        # director-enrolled and no (or a bad) director token was given; a chat `raise:` reply is never enough there.
        by = _require_approval(ctx, st, "raise-limit", token, bind=(cp, reason))["by"]
        _policy_apply(args, ctx, st, "raise-limit", cp)
    else:
        msgs = _replies(ctx, st, p.get("asked_at"), p)  # only the chat the question was asked in can answer it
        if not msgs:
            die("No reply has been recorded in the owning chat since this question was asked. End your turn and wait "
                "for the user's reply, exactly `raise: <reason>`; a reply typed in another chat does not count.")
        entry = msgs[0]  # the first reply answers the question; later messages never do
        reply = entry.get("prompt", "")
        reason = _raise_reply_reason(reply)
        if reason is None:
            _spend_question(ctx, st, reply)
            die(f"The user's first reply after the question was not the exact form `raise: <reason>`: \"{reply[:120]}\". "
                "Nothing was raised, and the question is closed, so a later reply in that form does not count. Run "
                f"`ratchet.py ask raise-limit {cp}` again if they still want to raise it.")
        if ctx.config().get("verify_transcripts", True):
            good, why = _transcript_ok(entry, p.get("asked_at"))
            if not good:
                _spend_question(ctx, st, reply)
                die(f"Couldn't confirm that reply came from the user ({why}). Nothing was raised. Run `ratchet.py ask "
                    f"raise-limit {cp}` again and ask them to reply in this chat.")
        by = "human"
    cfg = ctx.config()
    prev_attempts = g.get("attempts", 0)  # preserved across _unblock below so the raise grants exactly one more
    # round, not a fresh budget: _unblock() resets failing-gate attempt counters to 0 for every other unblock path,
    # but here that would hand back `cap` whole rounds instead of the one the user just approved.
    cap = _adv_base_cap(cfg, g) + 1  # based on the CONFIGURED cap, never on any round_limit_grants already used,
    # so a raise always adds exactly one round on top of config, whichever order it and a check-in round-limit
    # grant happen in, instead of compounding on top of each other (see _adv_base_cap/_adv_round_cap).
    g["cap_raised_to"] = cap
    _clear_pending(st)
    ctx.log(st, "round_limit_raised", cp=cp, cap=cap, reason=reason[:300], by=by, **_policy_field(args))
    _append_learning(ctx, f"{cp}'s review-round limit was raised to {cap} rounds: {reason}", source="raise-limit")
    unblocked_to = None
    if _adv_block_kind(st, cp) == "own":  # raise-limit only ever lifts CP's own step cap, so it only ever
        # unblocks CP's own round-limit block, never the run-wide cap (raising one step's cap does not touch
        # the run-wide budget; that needs a plain human-approve, same as any other failing gate).
        unblocked_to = _unblock(ctx, st, by, f"raised {cp}'s round limit to {cap}")
        g["attempts"] = prev_attempts
    ctx.save_state(st)
    build_viewer(ctx)
    msg = f"{cp}'s review-round limit raised to {cap} rounds, with reason: {reason}."
    if unblocked_to:
        msg += " The run is no longer blocked."
        msg += f" Next: `ratchet.py reviewers {cp}` can open another round now."
    else:
        msg += f" `ratchet.py reviewers {cp}` can open another round for this step once it is blocked there again."
    ok(msg)


def cmd_accept_line(args):
    """CP5: record the unproven done-means lines the user accepted, with their reason: only their FIRST reply
    after `ask accept-line`, from the owning chat, in the exact form `accept: <reason>`, accepts them (the same
    consent machinery as cmd_accept_finding: _require_pending, _replies, _accept_reply_reason, _spend_question, the
    transcript check); a reply from another chat, from before the question, or a host-generated turn never counts,
    and a first reply in any other form closes the question. `--reason` on its own never stands in for the reply.
    In a director-enrolled lane a chat reply never counts: a director token signed for this action after the ask
    (`director-sign accept-line`, bound to `awaiting_since`, which `ask` moves) is required, with --reason carrying
    the director's own reason, checked before the token so a forgotten flag costs no second signature. The lines
    are re-judged at accept time (`done_means_table`): a line that is not unproven any more clears the question
    and accepts nothing, and so does a line whose reasons differ from the ones the question showed (`pending`'s
    `covered`, recorded by `_ask_accept_line`): the reply accepts exactly what the user saw, never a reason that
    appeared between the question and the reply, so the agent asks again with the current reasons. Then, in this
    order: one `.ratchet/learnings.md` line per line (keyed by a marker unique
    to this run, line and what held the line, so a retry after a crash never duplicates it while a re-accept of a
    line held again for a new reason gets its own line; the reason collapsed to one line there, kept verbatim in
    state), the `accepted_lines` record in state ({"<n>": {"number", "text", "reason", "accepted_by",
    "accepted_at", "covered"}}, "covered" being the line's reasons right now, what this acceptance covers; a
    re-accept replaces the line's record), `pending` cleared, and the state commit last, so a crash before it
    leaves the accept not made and a plain retry finishes once. Never finishes the run, never touches a review
    counter, a gate or a stored choice: the accepted line simply reads "accepted" in the table and no longer holds
    the finish (`_finish_blockers`) until a reason the acceptance did not cover appears (`_apply_accepted_lines`);
    the agent still asks for the final approval afterwards. The closing line reads the whole finish verdict
    (`_finish_blockers` and `_finish_integrity_lines`, as `_finish_held` does): it never says the finish is free
    while a checkpoint or test plan edited after approval still holds it."""
    ctx = Ctx(find_root())
    st = ctx.state()
    _require_pending(st, "accept-line", ctx=ctx)
    p = st["pending"]
    ids = [i for i in (p.get("ids") or []) if isinstance(i, int) and not isinstance(i, bool)]
    again = _ask_cmd("accept-line", target=",".join(str(i) for i in ids))
    them = "them" if len(ids) != 1 else "it"
    if p.get("overtook"):
        _clear_pending(st)
        ctx.log(st, "accept_line_unclear", ids=ids)
        ctx.save_state(st)
        die(f"This question was printed while another one (shall I {_question_what(p['overtook'], p.get('overtook_mode'), p.get('overtook_target'))}"
            "?) was still waiting for the user's first reply, so their reply could be meant for either. Nothing was "
            f"accepted. Run {again} again on its own.")
    token = getattr(args, "director_token", None)
    reason_flag = (getattr(args, "reason", None) or "").strip()
    if token or approval_mode(ctx) == "director":
        if token and not reason_flag:
            # checked BEFORE the token is verified or anything is cleared, as cmd_accept_finding does: the same
            # command with --reason added then simply works
            die("accept-line needs --reason \"...\" when a director token accepts the line (there is no chat reply to "
                "read a reason from). Nothing was accepted, and the question is still waiting: run the same command "
                "again with --reason \"...\" added.")
        # _require_approval's own checks: a token in a human lane, no (or a bad) token in a director lane
        appr = _require_approval(ctx, st, "accept-line", token)
        by, reason = appr["by"], reason_flag
    else:
        if reason_flag:
            die("--reason is only for a director token in a director-enrolled lane. Here the reason must come from the "
                "user's own reply in the owning chat, exactly `accept: <reason>`, as their first reply after the "
                "question; nothing else stands in for that reply. Nothing was accepted; the question is still waiting.")
        msgs = _replies(ctx, st, p.get("asked_at"), p)  # only the chat the question was asked in can answer it
        if not msgs:
            die("No reply has been recorded in the owning chat since this question was asked (a reply typed in another "
                "chat, or before the question, does not count). End your turn and wait for the user's reply, exactly "
                "`accept: <reason>`.")
        entry = msgs[0]  # the first reply answers the question; later messages never do
        reply = entry.get("prompt", "")
        reason = _accept_reply_reason(reply)
        if reason is None:
            _spend_question(ctx, st, reply)
            die(f"The user's first reply after the question was not the exact form `accept: <reason>`: \"{reply[:120]}\". "
                "Nothing was accepted, and the question is closed, so a later reply in that form does not count. Run "
                f"{again} again if they still want to accept {them}.")
        if ctx.config().get("verify_transcripts", True):
            good, why = _transcript_ok(entry, p.get("asked_at"))
            if not good:
                _spend_question(ctx, st, reply)
                die(f"Couldn't confirm that reply came from the user ({why}). Nothing was accepted. Run {again} again "
                    "and ask them to reply in this chat.")
        by = "human"
    if not _finish_pending(st):
        _clear_pending(st)
        ctx.save_state(st)
        die(f"The run is no longer at the final review ({PHASE_PLAIN.get(st.get('phase'), st.get('phase'))}), so this "
            "question no longer applies. Nothing was accepted.")
    table = done_means_table(ctx, ctx.plan() or {"checkpoints": []}, st)
    by_num = {e["number"]: e for e in table} if isinstance(table, list) else {}
    stale = [i for i in ids if (by_num.get(i) or {}).get("verdict") != "unproven"]
    if stale or not ids:
        _clear_pending(st)
        ctx.save_state(st)
        what = "; ".join(f"line {i} is not unproven any more (it is "
                         f"{(by_num.get(i) or {}).get('verdict') or 'not in the table'})" for i in stale) or "no line is named"
        die(f"{what}, so this question no longer applies and nothing was accepted. If another line still holds the "
            "finish, run `ratchet.py ask accept-line <n>` again for it.")
    covered = {i: [r for r in (by_num[i].get("reasons") or []) if not str(r).startswith(HELD_AGAIN_PREFIX)]
               for i in ids}
    shown = p.get("covered") if isinstance(p.get("covered"), dict) else {}
    moved = [i for i in ids if isinstance(shown.get(str(i)), list) and sorted(shown[str(i)]) != sorted(covered[i])]
    if moved:
        # the user accepts exactly what the question showed; what holds a line changed since, so the reply covers
        # something they never saw (or less than they were shown): ask again with the current reasons
        _clear_pending(st)
        ctx.log(st, "accept_line_unclear", ids=ids, moved=moved)
        ctx.save_state(st)
        what = "; ".join(f"line {i} is held by: {'; '.join(covered[i]) or 'nothing'} (the question showed: "
                         f"{'; '.join(shown[str(i)]) or 'nothing'})" for i in moved)
        die(f"What holds {_lines_word(moved)} changed after the question was shown: {what}. The user's reply covers "
            f"only what they were shown, so nothing was accepted and the question is closed. Run {again} again to "
            "ask with what holds it now.")
    at = now()
    reason_line = " ".join(reason.split())
    # (a) learnings first, keyed by a marker unique to this run and line: a retry after a crash never duplicates it
    learnings = _learnings_text(ctx)
    for i in ids:
        e = by_num[i]
        marker = (f"Accepted done-means line {i} of run {st['slug']} (\"{e['text']}\"; "
                  f"{'; '.join(e.get('reasons') or []) or 'unproven'}) as unproven.")
        if marker in learnings:
            continue
        _append_learning(ctx, f"{marker} Reason: {reason_line}", f"{by}, accept-line")
        learnings += marker
    # (b) the per-line record, then (c) the one state commit
    acc = st.get("accepted_lines")
    if not isinstance(acc, dict):
        acc = {}
    for i in ids:
        acc[str(i)] = {"number": i, "text": by_num[i]["text"], "reason": reason, "accepted_by": by, "accepted_at": at,
                       "covered": covered[i]}
    st["accepted_lines"] = acc
    ctx.log(st, "line_accepted", lines=ids, reason=reason[:200], by=by)
    _clear_pending(st)
    ctx.save_state(st)
    build_viewer(ctx)
    left = _finish_blockers(ctx, st)
    changed = [] if left else _finish_integrity_lines(ctx, st)
    if left:
        tail = f"Still unproven and holding the finish: {_lines_word(e['number'] for e in left)}."
    elif changed:
        tail = ("No done-means line holds the finish now, but it is still held: a checkpoint or test plan changed "
                "after the user approved the plan. Run `ratchet.py status` for what changed and settle it (undo it, "
                "or `ratchet.py ask approve-changes`) before asking for the final approval.")
    else:
        tail = "The finish is no longer held: ask for the final approval (`ratchet.py ask human-approve`)."
    ok(f"Accepted {_lines_word(ids)} as unproven, by {by}: {reason_line}. {tail}")


def cmd_next(args):
    ctx = Ctx(find_root())
    st = ctx.state()
    na = next_action(ctx, st)
    na["question"] = waiting_question(ctx, st)
    na["wait"] = live_wait(st)  # what the owner chat said it is waiting on (`ratchet.py wait`), until when
    hs = hooks_view(ctx)
    hw = hooks_warning(ctx, hs)
    if hw and na.get("phase") not in ("planning",):
        na["warning"] = hw
    na["hooks"] = hs
    na["hook_errors"] = hook_errors_view(ctx.root, hs.get("host", "unknown"))
    note = exit_code_only_note(ctx.plan(), ctx.state())
    if note:
        na["test_check"] = note
    print(json.dumps(na, indent=2))


def cmd_status(args):
    ctx = Ctx(find_root())
    if getattr(args, "json", False):
        print(json.dumps(status_json(ctx), indent=2))
        return
    cmd_status_text(ctx)


def cmd_reviewers(args):
    """Open (or show) the adversarial review round for a checkpoint. Opening a round is what counts toward the
    retry caps, so re-rolling reviewers until one approves still costs rounds."""
    ctx = Ctx(find_root())
    cfg = ctx.config()
    st = ctx.state()
    cps = _cur(ctx, st, args.cp)
    _expect_step(cps, ["adversarial", "complete"], args.cp)
    plan = ctx.plan()
    cp = cp_by_id(plan, args.cp)
    shown = _plan_for_briefs(plan, st)  # the approved done-means lines (CP4), the same ones brief prints
    obj = shown.get("objective") if isinstance(shown, dict) else None
    # the same rendering brief prints and the launch guard expects (with the Proved by / Heads up notes), so a
    # prompt that starts with this `how` objective passes the guard once the orchestrator pastes it
    obj_oneline = re.sub(r"\s*\n\s*", " ", objective_brief(shown, _done_means_proof_notes(ctx, shown, st)))
    fp = fingerprint(ctx.root)["id"]
    g = cps["gates"]["adversarial"]
    if g["status"] != "passed" and _docs_only_review_skip(ctx, st, cfg, cp, cps, args.cp, json_out=args.json):
        return
    rnd = cps.get("adv_round")
    # A round opened before this field existed has no "reviewers_pin" key at all (not even None). Its resolved
    # reviewers can legitimately differ from the pin (narrowing, substitution), so they are never compared here:
    # such a round never triggers pin_changed by itself. _stamp_legacy_round_baselines (run from approve-plan,
    # plan-extend and approve-changes, before each writes its approval snapshot, AND run right here, unconditionally,
    # before this very comparison) decides whether to stamp one of two ways, and the two ways leave this legacy
    # round in different states, not the same one: when the last approval snapshot already recorded this
    # checkpoint's own reviewers field, it diffs that stored field directly against the live pin and stamps the
    # OLD pin only on a genuine difference -- an UNCHANGED reviewers field leaves the round legacy here, same as
    # before. When the snapshot predates that field for this checkpoint (no stored baseline at all), there is no
    # fixed guess at the prior pin that is correct in every direction (CP4 round-3 codex-standards/X3), so it
    # unconditionally stamps None whenever the live pin is non-empty -- here ANY approval event while the live pin
    # is non-empty stamps and reopens, an unchanged pin included; only an EMPTY live pin leaves a no-baseline
    # round legacy. Calling it here too (not only from the three approval-writing commands) is what closes CP4
    # round-6 host-alt-correctness/A1: the common upgraded shape is a checkpoint whose pin was already edited and
    # approved entirely under the old engine, so `approve-changes` finds nothing pending and never reaches its own
    # call -- `reviewers` is the only command left that always runs, with no "something changed" precondition, so
    # it stamps and reopens the round on this same call instead of waiting on an approval event that would never
    # come. `stamped_legacy` is threaded through below so a call that stamps some OTHER checkpoint's round (this
    # loop runs over every checkpoint, not only args.cp) still persists that stamp even when args.cp's own round
    # takes the "same round" branch below and would otherwise have no other reason to save state.
    stamped_legacy = _stamp_legacy_round_baselines(st, plan)
    if not rnd or "reviewers_pin" not in rnd:
        pin_changed = False
    else:
        pin_changed = sorted(rnd.get("reviewers_pin") or []) != sorted(cp.get("reviewers") or [])
    if not rnd or rnd.get("recorded") or rnd["fingerprint"] != fp or pin_changed:
        ci = _checkin_state(cps)
        if ci.get("open"):
            die(f"{args.cp}: a check-in is open from round {ci['open']['round']} (reviews have been dragging). "
                f"Run `ratchet.py check-in {args.cp}` to see it, then `ratchet.py check-in {args.cp} --decision "
                "simplify --why \"...\"` or `--decision stop` to resolve it before another round opens.")
        if rnd and rnd.get("recorded"):
            open_findings = _adv_open_findings(ctx, args.cp, rnd, cps)
            if open_findings:  # every remaining blocking finding needs its own fix-or-rebut decision, even one
                triage = _read_triage(_adv_round_dir(ctx, args.cp, rnd["round"]))
                missing = sorted({_finding_key(f) for f in open_findings} - set(triage))
                if missing:
                    die(f"{args.cp} round {rnd['round']} still has blocking finding(s) with no fix-or-rebut "
                        f"decision: {', '.join(missing)}. Run `ratchet.py triage {args.cp} "
                        f"{missing[0]}=fix:\"reason\"` (or `=rebut:\"reason\"`) for each, then try again.")
        if g["attempts"] >= _adv_round_cap(cfg, cps):
            _set_blocked(st, f"{args.cp}: {g['attempts']} adversarial rounds used without approval — needs a "
                             "human/director decision.")
            ctx.save_state(st)
            die(st["blocked_reason"], 2)
        if int(st.get("adv_rounds_total", 0)) >= cfg["max_adversarial_rounds_run"]:
            _set_blocked(st, f"Run-wide adversarial round cap reached ({st.get('adv_rounds_total')}/"
                             f"{cfg['max_adversarial_rounds_run']}). Raising it is the user's call "
                             "(config change + approve-changes).")
            ctx.save_state(st)
            die(st["blocked_reason"], 2)
        provider_share(cfg)  # a bad provider_share setting stops here, before anything is opened or reserved
        # Narrow after round 1: when the round being replaced was recorded (it blocked) and was itself NOT
        # narrowed, the next round only asks the lens(es) that still had an open blocker/major finding, or an
        # open finding of any severity that names a done-means line (CP3, `names_done_means`, while
        # `_dm_findings_block` applies to this plan) — a lens that approved isn't re-run. A narrowed round whose
        # fix still left a blocker open brings back the full set for the round after it (narrow_now stays
        # False), rather than narrowing further.
        was_narrowed = bool(rnd.get("narrowed")) if rnd else False
        open_lenses = (_open_blocking_lenses(ctx, cfg, args.cp, rnd, cps, dm_blocks=_dm_findings_block(ctx, st, plan))
                       if rnd and rnd.get("recorded") and not was_narrowed else set())
        narrow_now = False
        # CP3: a small fix made since the checkpoint's last FULL review opens with exactly one reviewer, told
        # (via review_rules' existing focus_files, below) to look only at what changed since that approval. That
        # one reviewer must still cover both lenses, so it is resolved the same way a low-risk step's single
        # reviewer is (review_depth["low"], an any-both/host-both slot), never the step's own (possibly
        # single-lens) first slot. The override is only used, and small_fix only set, when that resolution
        # actually comes back as exactly one both-lens reviewer -- a customized review_depth["low"] (two slots,
        # or a single-lens id) falls back to the step's normal full round instead of mislabeling it. It is picked
        # and reserved through the same share-aware pick as a full round (pick_round below).
        # CP5 (lane H): the second trigger on that same one-reviewer round. A round that follows a blocked round,
        # once the fixer has run, opens with exactly one reviewer whatever the fix's size and whatever the step's
        # risk: the reviewer whose blocking finding was fixed (same provider, same lens), never
        # review_depth["low"]'s catch-all. `kind` says which of the two triggers opened the round. A fix round
        # replaced before anyone reviewed it stays one (its reviewer and slot are carried forward), since the
        # blocked round it follows is no longer the latest recorded one once this round has advanced past it.
        fix_pick = _fix_round_pick(ctx, cfg, args.cp, cp, cps, g, fp)
        # A pin now set on the checkpoint beats a carried fix pick too (the same guard `_fix_round_pick` applies
        # to a fresh pick), so a pin edit on an open fix round opens with the pinned reviewer, not the one the
        # open fix round carried.
        if (fix_pick is None and not cp.get("reviewers") and _is_fix_after_block(rnd) and not rnd.get("recorded")
                and rnd.get("fix_round")):
            fix_pick = rnd["fix_round"]
        kind = FIX_AFTER_BLOCK if fix_pick else None
        small_fix = bool(fix_pick)
        if not small_fix:
            small_fix = _is_small_fix_round(ctx, cfg, args.cp, cp, cps, g)
            if small_fix and _small_fix_reviewers(ctx, cfg, cp) is None:
                small_fix = False
            kind = FIX_AFTER_APPROVAL if small_fix else None

        def pick_round(share):
            nonlocal narrow_now
            if fix_pick:
                narrow_now = False
                return _fix_round_reviewers(ctx, cfg, cp, fix_pick, share=share)
            if small_fix:
                low_resolved = _small_fix_reviewers(ctx, cfg, cp, share=share)
                if low_resolved is not None:
                    narrow_now = False
                    return low_resolved
            # Decide which slots survive narrowing first (without the share), then rank and reserve only those: a slot
            # narrowing drops must not use up a start of the provider's share and push a kept slot to the host.
            full = resolve_reviewers(ctx, cfg, cp)
            keep_slots = {r["slot"] for r in full if (_roster_spec(cfg, r["id"]) or {}).get("lens") in open_lenses}
            narrow_now = bool(open_lenses and keep_slots)
            return resolve_reviewers(ctx, cfg, cp, only_slots=keep_slots if narrow_now else None, share=share)
        # A round replaced before anyone reviewed it (the code changed again before any review was written) gives its
        # reservations back in the same locked step that reserves the new round's; one with a review file keeps them
        # (a reviewer that was cut off or failed on its own ran, so it keeps its start too).
        old_nonce = rnd["nonce"] if rnd else None
        give_old = []
        if rnd and not rnd.get("recorded"):
            old_dir = _review_round_dir(ctx, args.cp, "adv", rnd["round"])
            if not any(p for p in old_dir.glob("*.json") if not p.name.endswith(".cutoff.json")):
                ran = {p.name[:-len(".cutoff.json")] for p in old_dir.glob("*.cutoff.json")} | set(rnd.get("failed_reviewers") or [])
                give_old = [x for x in rnd.get("reviewers") or [] if x not in ran]
        new_nonce = secrets.token_hex(8)
        ignore_old = {_start_id(old_nonce, x) for x in give_old}
        reserved, tries = False, 0
        while True:  # test the providers we are about to rely on; a failing one hands its slot on
            tries += 1
            # who would review, with the share applied (read, not reserved): a provider the locked pick will skip for
            # being at its share gets no test request
            resolved = pick_round({"data": provider_health(), "ignore": set(ignore_old)})
            due = {(_roster_spec(cfg, r["id"]) or {}).get("provider") for r in resolved}
            due = [pid for pid in due if pid and probe_due(ctx, cfg, pid)] if tries < 6 else []
            if not due:
                got = _reserve_under_lock(cfg, ignore_old, pick_round, lambda _r: [(x, old_nonce) for x in give_old],
                                          lambda picked: [(r["id"], new_nonce) for r in picked], keep_picked=True)
                if got is None:  # the record's lock was busy: go on with the unreserved picks (starts recorded below)
                    break
                resolved = got
                give_old = []  # given back with the reservation
                due = {(_roster_spec(cfg, r["id"]) or {}).get("provider") for r in resolved}
                due = [pid for pid in due if pid and probe_due(ctx, cfg, pid)] if tries < 6 else []
                if not due:
                    reserved = True
                    break
                update_review_starts(cfg, new_nonce, give_back=[r["id"] for r in resolved])  # not tested yet: release
            for pid in due:
                good, detail = probe_shared(ctx, cfg, provider_by_id(cfg, pid))
                print(f"  checked {pid}: {'working' if good else 'not usable now (' + detail + ')'}", file=sys.stderr)
        if fix_pick:
            if len(resolved) != 1:
                # The fix round's one slot did not come back as exactly one reviewer (resolve_reviewers never
                # returns an empty set for a round, so this is a guard, not a path a working setup reaches):
                # open a normal round, RE-RESOLVED, so a round can never open with no reviewer at all. The
                # starts already reserved for the abandoned pick go back and the new picks' are recorded here,
                # outside the lock, best effort, the same way a lock-busy round records its own.
                abandoned = [r["id"] for r in resolved]
                fix_pick, small_fix, kind = None, False, None
                resolved = pick_round({"data": provider_health(), "ignore": set(ignore_old)})
                if reserved:
                    update_review_starts(cfg, new_nonce, add=[r["id"] for r in resolved], give_back=abandoned)
        elif small_fix and not (len(resolved) == 1 and (_roster_spec(cfg, resolved[0]["id"]) or {}).get("lens") == "both"):
            small_fix = False  # the share-aware pick fell back to a normal round: never label it a small fix
            kind = None
        g["attempts"] += 1
        st["adv_rounds_total"] = int(st.get("adv_rounds_total", 0)) + 1
        prev = rnd["round"] if rnd else 0
        # A round that WAS reviewed but adv-record refused it (omitted_files, too fast, no files_reviewed) is
        # charged on purpose: only a round nobody reviewed yet is free (below). A refused round never moves the
        # baseline (below), so the next round still shows the fix, and running out of rounds still stops at the
        # usual blocked-for-human/director-decision message.
        # `free_replace` is kept only as CP1-T15's structural anchor for the refund block below; nothing else reads it.
        free_replace = False
        if rnd and not rnd.get("recorded"):
            # Replacing a round nobody reviewed yet (the code changed again before any review was written) costs
            # nothing: refund this round-opening's own increment back out, never below zero.
            prev_dir = _review_round_dir(ctx, args.cp, "adv", prev)
            if not any(p for p in prev_dir.glob("*.json") if not p.name.endswith(".cutoff.json")):
                free_replace = True
                g["attempts"] = max(0, g["attempts"] - 1)
                st["adv_rounds_total"] = max(0, int(st.get("adv_rounds_total", 0)) - 1)
        old_key = review_key_file(ctx.root, st, args.cp, "adv", prev) if prev else None
        # The new round's baseline is the last round adv-record actually RECORDED (g["rounds"], append-only,
        # written only at a successful cmd_adv_record, approved or blocked) -- never the discarded round's own
        # fingerprint, and never a field carried forward from it: a round adv-record refused (or never ran on)
        # never moves the baseline, however it is replaced, and this heals an already-open round that still
        # carries a wrong baseline from an earlier refusal, with no hand edit of state.json.
        last_rec = (g.get("rounds") or [])[-1:]
        prev_round_tree = last_rec[0].get("fingerprint") if last_rec else None
        rnd = {"round": prev + 1, "nonce": new_nonce, "fingerprint": fp, "opened_at": now(),
               "reviewers_pin": cp.get("reviewers"),
               "reviewers": [r["id"] for r in resolved], "narrowed": narrow_now, "small_fix": small_fix,
               "kind": kind, "fix_round": fix_pick,
               "prev_round_tree": prev_round_tree,
               "substitutions": [{"used": r["id"], "instead_of": r["fallback_for"], "why": r["reasons"]}
                                 for r in resolved if r["fallback_for"]],
               "resolved": resolved}
        cps["adv_round"] = rnd
        ctx.log(st, "reviewers_launched", cp=args.cp, round=rnd["round"], reviewers=",".join(rnd["reviewers"]))
        if rnd["substitutions"]:
            ctx.log(st, "reviewer_fallback", cp=args.cp, detail="; ".join(
                f"{x['used']} instead of {', '.join(x['instead_of'])}" for x in rnd["substitutions"]))
        ctx.save_state(st)
        if not reserved:  # the record's lock was busy: record this round's starts now, best effort
            if give_old:
                update_review_starts(cfg, old_nonce, give_back=give_old)
            update_review_starts(cfg, rnd["nonce"], rnd["reviewers"])
        drop_review_key(old_key)  # the replaced round (now saved as replaced) stops counting
    else:
        # same round: if a listed reviewer has become unavailable (its CLI failed), give its slot to the next
        # choice. A review file already written in this round's own folder is never discarded or re-resolved,
        # even for a slot that otherwise looks replaceable. A reply cut off mid-answer twice (external_review.py's
        # own retry already tried once) falls its own slot back for this round only — read from the round's
        # folder, never the long-lived unavailable_ttl_hours store, so the rest of this reviewer's slots, and
        # every other reviewer on the same CLI, keep running.
        out_dir_now = _review_round_dir(ctx, args.cp, "adv", rnd["round"])
        round_cutoff = {p.name[:-len(".cutoff.json")] for p in out_dir_now.glob("*.cutoff.json")}
        # A provider that failed a review in this round stays out of it, even if a later test request passes (the
        # exclusion lives in this round's own record, so the next round starts clean).
        own_failed = set(rnd.get("failed_reviewers") or [])  # reviewers whose own run failed (external_review.py)
        failed_now = set(rnd.get("failed_providers") or [])
        for r in rnd["resolved"]:
            if not (out_dir_now / f"{r['id']}.json").exists() and not reviewer_availability(ctx, cfg, r["id"])[0]:
                failed_now.add(_reviewer_health_key(cfg, r["id"]) or r["id"])
        failed_ids = {r for r in roster(cfg) if (_reviewer_health_key(cfg, r) or r) in failed_now}
        changed, swapped_in, dropped, started, given_back = False, [], set(), [], []
        refill_reserved = False

        def never_used(x):  # a slot given up before its reviewer ran: its start goes back (not after its own run)
            if x not in round_cutoff and x not in own_failed:  # a sibling swapped out by that failure never ran
                given_back.append(x)
        newly_failed = sorted(failed_now) != sorted(rnd.get("failed_providers") or [])
        if newly_failed:
            rnd["failed_providers"] = sorted(failed_now)
        if rnd.get("small_fix") and not _is_fix_after_block(rnd):
            # A small-fix round's one reviewer must always cover both lenses, so re-resolve it the same way
            # the round was opened (_small_fix_reviewers), never via the step's own (possibly single-lens)
            # risk. When that can't produce a both-lens replacement, this stops being a small-fix round. A
            # reviewer that failed earlier this round stays out, and starts are recorded like any other refill.
            cur = rnd["resolved"][0]
            if not (out_dir_now / f"{cur['id']}.json").exists():  # a finished review is kept untouched
                okay, _why = reviewer_availability(ctx, cfg, cur["id"])
                if not okay or cur["id"] in round_cutoff or cur["id"] in failed_ids:
                    replacement = _small_fix_reviewers(ctx, cfg, cp, exclude=round_cutoff | failed_ids)
                    if replacement is not None:
                        if replacement[0]["id"] != cur["id"]:
                            rnd["resolved"] = replacement
                            changed = True
                            started.append(replacement[0]["id"])
                            never_used(cur["id"])
                            if replacement[0]["fallback_for"]:
                                swapped_in.append({"used": replacement[0]["id"], "instead_of": replacement[0]["fallback_for"],
                                                    "why": replacement[0]["reasons"]})
                    else:
                        rnd["small_fix"] = False
                        rnd["resolved"] = resolve_reviewers(ctx, cfg, cp, exclude=round_cutoff | failed_ids)
                        changed = True
                        never_used(cur["id"])
                        started.extend(r["id"] for r in rnd["resolved"])
                        swapped_in.extend({"used": r["id"], "instead_of": r["fallback_for"], "why": r["reasons"]}
                                           for r in rnd["resolved"] if r["fallback_for"])
        else:
            # A slot is refilled when it has no finished review and its reviewer is out of the round or no longer
            # available; every other slot keeps its reviewer, and the refill never repeats one of those (same id, or the
            # same company, model and lens under another id). A post-block fix round (CP5) is refilled here too: its
            # one slot gets that slot's own same-lens stand-in, and the round stays a one-reviewer fix round.
            replace = [i for i, r in enumerate(rnd["resolved"])
                       if not (out_dir_now / f"{r['id']}.json").exists()
                       and (not reviewer_availability(ctx, cfg, r["id"])[0] or r["id"] in round_cutoff
                            or r["id"] in failed_ids)]
            keep = {r["id"] for i, r in enumerate(rnd["resolved"]) if i not in replace}
            replaced_slots = {rnd["resolved"][i]["slot"] for i in replace}

            def pick_refill(share):
                return resolve_reviewers(ctx, cfg, cp, exclude=round_cutoff | failed_ids, taken=keep,
                                         only_slots=replaced_slots, share=share)
            # A replaced slot whose reviewer never ran gives its start back, and its replacement reserves one, in the same
            # locked step that checks the share (the start about to be given back is not counted against it).
            idle = {rnd["resolved"][i]["slot"]: rnd["resolved"][i]["id"] for i in replace
                    if rnd["resolved"][i]["id"] not in round_cutoff and rnd["resolved"][i]["id"] not in own_failed}
            nonce_now = rnd["nonce"]
            got = None
            if replace:
                got = _reserve_under_lock(
                    cfg, {_start_id(nonce_now, x) for x in idle.values()}, pick_refill,
                    lambda picked: [(x, nonce_now) for sl, x in idle.items()
                                    if next((p["id"] for p in picked if p["slot"] == sl), None) != x],
                    lambda picked: [(p["id"], nonce_now) for p in picked
                                    if p["id"] != next((rnd["resolved"][i]["id"] for i in replace
                                                        if rnd["resolved"][i]["slot"] == p["slot"]), None)])
            if got is not None:
                refill_reserved = True
            fresh = {r["slot"]: r for r in (got if got is not None else pick_refill(None))}
            for i in replace:
                r = rnd["resolved"][i]
                if r["slot"] in fresh and fresh[r["slot"]]["id"] != r["id"]:
                    new_r = fresh[r["slot"]]
                    if r["id"] not in new_r["fallback_for"]:  # the reviewer it replaces is always named, wherever it ranks
                        new_r["fallback_for"] = [r["id"]] + list(new_r["fallback_for"])
                        new_r["reasons"].setdefault(r["id"], "failed a review earlier this round" if r["id"] in failed_ids
                                                    else "no longer available")
                    rnd["resolved"][i] = new_r
                    started.append(new_r["id"])
                    never_used(r["id"])
                    changed = True
                    if new_r["fallback_for"]:
                        swapped_in.append({"used": new_r["id"], "instead_of": new_r["fallback_for"], "why": new_r["reasons"]})
                elif r["slot"] not in fresh:
                    # Every alternative is taken, down or a duplicate: the slot may not keep its failed reviewer. A host
                    # reviewer no other slot runs fills it; when none is free the slot is dropped (it runs once elsewhere).
                    busy = {x["id"] for j, x in enumerate(rnd["resolved"]) if j != i and j not in dropped}
                    host = next((h for h in _host_fallbacks(cfg, r["id"])
                                 if h not in busy and reviewer_availability(ctx, cfg, h)[0]), None)
                    changed = True
                    never_used(r["id"])
                    if host is None:
                        dropped.add(i)
                    else:
                        spec_h = _roster_spec(cfg, host)
                        why = "failed a review earlier this round" if r["id"] in failed_ids else "no longer available"
                        rnd["resolved"][i] = {"id": host, "slot": r["slot"], "vendor": spec_h.get("vendor"),
                                              "model": ("a different model: " + " or ".join(host_model_map(cfg).get("alternates") or [])
                                                        if spec_h.get("alt") else role_model(cfg, "ratchet-adversary")),
                                              "fallback_for": [r["id"]], "reasons": {r["id"]: why}}
                        swapped_in.append({"used": host, "instead_of": [r["id"]], "why": {r["id"]: why}})
            if dropped:
                rnd["resolved"] = [x for j, x in enumerate(rnd["resolved"]) if j not in dropped]
        if changed:
            rnd["reviewers"] = [r["id"] for r in rnd["resolved"]]
            if swapped_in:  # record the same-round swap the same shape a fresh round's own substitutions use
                rnd["substitutions"] = (rnd.get("substitutions") or []) + swapped_in
            ctx.log(st, "reviewer_fallback", cp=args.cp, detail="re-resolved within round " + str(rnd["round"]))
        if changed or newly_failed or stamped_legacy:
            # stamped_legacy: this round wasn't replaced (pin_changed stayed False for args.cp itself), but the
            # same call may have stamped some OTHER checkpoint's legacy round above; that mutation needs saving
            # too, or it is computed only in memory and lost.
            ctx.save_state(st)
        if not refill_reserved:  # the record's lock was busy (or nothing was replaced): starts recorded now
            update_review_starts(cfg, rnd["nonce"], started, given_back)
    _key, why = open_review_key(ctx, args.cp, "adv", rnd["round"], st)
    if _key is None:
        die(review_key_problem(why, f"run `ratchet.py reviewers {args.cp}` again"))
    out_dir = _review_round_dir(ctx, args.cp, "adv", rnd["round"])
    out_dir.mkdir(parents=True, exist_ok=True)
    fixes = ctx.run_dir() / "reviews" / args.cp / f"adv-round-{rnd['round'] - 1:02d}" / "fixes.md"
    fixes_arg = f" --fixes {fixes}" if rnd["round"] > 1 else ""
    ext_script = SKILL_DIR.parent / "ratchet-adversarial-loop" / "scripts" / "external_review.py"
    focus, rules, scope = review_rules(ctx, cfg, cp, g, rnd, fp, cps)
    rows = []
    for res_r in rnd["resolved"]:
        rid = res_r["id"]
        spec = dict(_roster_spec(cfg, rid) or {}, id=rid, output=str(out_dir / f"{rid}.json"),
                    slot=res_r["slot"], fallback_for=res_r["fallback_for"], reasons=res_r["reasons"])
        if spec["kind"] == "agent":
            want = ("a model DIFFERENT from yours: " + " or ".join(host_model_map(cfg).get("alternates") or [])
                    if spec.get("alt") else role_model(cfg, "ratchet-adversary"))
            # Lane H CP6: a scoped round (fix_round or small_fix) tells the host sub-agent the SAME scope an
            # external reviewer's own prompt gets -- the prior reviewed tree, this round's fingerprint (already
            # above), and the files changed since then; the open findings themselves (or "no open findings") are
            # already in `rules` below (review_rules appends one line per finding via _render_finding_line).
            scope_note = (f", since {scope['since_tree'][:10]}, changed files: "
                         f"{', '.join(scope['changed_files']) or '(none)'}" if scope is not None else "")
            spec["how"] = (f"Objective: {obj_oneline} | Spawn a ratchet-adversary sub-agent (model: {want}): "
                           f"lens={spec['lens']}, reviewer id '{rid}', "
                           f"fingerprint {fp}, round_nonce {rnd['nonce']}, checkpoint {args.cp}, output {spec['output']}"
                           + scope_note
                           + (f", fixes.md {fixes}" if rnd["round"] > 1 else "")
                           + ("" if not rules else ". Review rules for this round (tell it): " + " ".join(rules)))
        else:
            spec["how"] = f"python3 {ext_script} --reviewer {rid} --cp {args.cp} --out {spec['output']}{fixes_arg}"
        rows.append(spec)
    res = {"checkpoint": args.cp, "objective": obj if isinstance(obj, dict) and obj else NO_OBJECTIVE_NOTE,
           "risk": cp.get("risk", "normal"), "round": rnd["round"], "fingerprint": fp,
           "review_rules": rules, "focus_files": sorted(focus) if focus is not None else None,
           "scope": scope,
           "round_nonce": rnd["nonce"], "output_dir": str(out_dir), "narrowed": rnd.get("narrowed", False),
           "small_fix": rnd.get("small_fix", False), "kind": rnd.get("kind"),
           "fix_round": rnd.get("fix_round"),
           "fixes_md": str(fixes) if rnd["round"] > 1 else None,
           "run_rounds_used": st.get("adv_rounds_total", 0), "run_rounds_cap": cfg["max_adversarial_rounds_run"],
           "reviewers": rows}
    # A legacy round with no reviewers_pin key at all (no recorded pin baseline) re-shown while the checkpoint
    # currently has a pin set. Computed from the FINAL round object (after any replacement
    # above has happened), so a round just opened/replaced -- which does store reviewers_pin -- never gets this
    # stale warning; it only fires when a legacy round is actually the one being re-shown right now.
    legacy_pin_note = not rnd.get("recorded") and "reviewers_pin" not in rnd and bool(cp.get("reviewers"))
    # Whether a baseline is on record for this checkpoint under the live `reviewers` field decides which promise
    # is true (see _stamp_legacy_round_baselines): with no stored baseline yet, this very call already stamped
    # and reopened it above when the live pin is non-empty (the legacy_pin_note computed here, on the FINAL round
    # object, is already False in that case) -- the only command left able to leave this note showing in that
    # shape is the next `approve-changes` call, even one that only touches a different checkpoint (the loop runs
    # over every checkpoint unconditionally), once it runs. approve-plan and plan-extend never apply here: a
    # checkpoint with an open adv_round is mid-run, and neither of those two can run while it is. Once a baseline
    # IS on record for this checkpoint, only a genuine, approved change to THIS checkpoint's own reviewers field
    # makes the next approval stamp it; an edit to some other checkpoint, or an approval that leaves this
    # checkpoint's reviewers field unchanged, stamps nothing here.
    has_baseline = isinstance((st.get("approved") or {}).get("reviewers"), dict) \
        and args.cp in (st.get("approved") or {}).get("reviewers")
    if legacy_pin_note and has_baseline:
        legacy_pin_msg = (f"Round {rnd['round']} predates reviewers-pin tracking (no reviewers_pin on this round), "
                          f"so it has no recorded pin baseline and is shown as-is; a baseline is already on record "
                          f"for this checkpoint's reviewers field, so only an approved change to this checkpoint's "
                          f"own reviewers field will stamp a baseline here and make the next reviewers call "
                          f"re-evaluate it against the live pin.")
    elif legacy_pin_note:
        legacy_pin_msg = (f"Round {rnd['round']} predates reviewers-pin tracking (no reviewers_pin on this round), so "
                          f"it has no recorded pin baseline and is shown as-is; running `reviewers` again resolves "
                          f"this itself (it runs the same stamp before this check), and the next `approve-changes` "
                          f"call -- even one that edits a different checkpoint -- also stamps a baseline here, once; "
                          f"after that, only a genuine change to this checkpoint's own reviewers field reopens it. "
                          f"Never `approve-plan` or `plan-extend`: neither can run while this checkpoint's round is "
                          f"open and current.")
    else:
        legacy_pin_msg = None
    if legacy_pin_msg:
        res["legacy_pin_note"] = legacy_pin_msg
    if args.json:
        print(json.dumps(res, indent=2))
        return
    print(f"{args.cp} risk={res['risk']} round={rnd['round']} fingerprint={fp[:12]} nonce={rnd['nonce']} "
          f"(run rounds {res['run_rounds_used']}/{res['run_rounds_cap']})")
    if _is_fix_after_block(rnd):
        fr = rnd.get("fix_round") or {}
        print(f"Fix round after a block: one reviewer re-checks the fix, {rnd['reviewers'][0]}"
              + (f" (the reviewer whose blocking finding was fixed in round {fr.get('round')})"
                 if fr.get("reviewer") == rnd["reviewers"][0] else
                 f" (standing in for {fr.get('reviewer')}, the reviewer whose blocking finding was fixed in "
                 f"round {fr.get('round')})")
              + ". It counts toward the round limits like any other round.")
    elif res["small_fix"]:
        print(f"Small fix since approval (at or under {cfg.get('small_edit_lines', 20)} changed code lines): "
              "one reviewer, scoped to the files changed since approval.")
    off_note = _docs_only_quick_path_off_note(ctx, cfg, cp, cps)
    if off_note:
        print(off_note)
    if legacy_pin_msg:
        print(legacy_pin_msg)
    if isinstance(obj, dict) and obj:
        print(f"Who it's for: {obj.get('users', '')}")
        print(f"What they want: {obj.get('goal', '')}")
    else:
        print(f"Note: {NO_OBJECTIVE_NOTE}.")
    for r in rows:
        print(f"  - {r['id']:<22} [{r['vendor']}/{r['lens']}] {r['how']}")
        for skipped in r["fallback_for"]:
            print(f"      (instead of {skipped}: {r['reasons'][skipped]})")
    for rule in rules:
        print(f"  rule: {rule}")
    print(f"Reviews must be written in this round's folder: {out_dir} (adv-record refuses a file from anywhere else)")
    print(f"Then: ratchet.py adv-record {args.cp} --reviews {out_dir}/*.json")


def cmd_reviewer_status(args):
    ctx = Ctx(find_root())
    cfg = ctx.config()
    if args.reset:
        key = _reviewer_health_key(cfg, args.reset)
        if key and _update_health(lambda data: phealth.clear(data, key), note=False) == "busy":
            _die_record_busy(_health_path(), f"{args.reset}'s shared bench was not cleared")
        p = _unavailable_path(ctx)
        if _update_unavailable(ctx, lambda live: live.pop(args.reset, None), note=False) == "busy":
            _die_record_busy(p, f"{args.reset} was not reset")
        ok(f"{args.reset} will be tried again")
    if args.mark:
        until = mark_unavailable(ctx, args.mark, args.reason or "marked unavailable", note=False)
        if until is None:
            p = _unavailable_path(ctx)
            _die_record_busy(p, f"{args.mark} was not marked unavailable")
        ok(f"{args.mark} skipped until {until[:16]}Z; the next provider, or the host's sub-agents, fill its slot")
    print(f"Host provider: {detect_host(cfg)}")
    for rid, spec in roster(cfg).items():
        okay, why = reviewer_availability(ctx, cfg, rid)
        print(f"  {'✓' if okay else '·'} {rid:<22} {str(spec.get('vendor') or '?'):<10} {why}")


def status_json(ctx: Ctx) -> dict:
    st = ctx.state()
    plan = ctx.plan() or {"checkpoints": []}
    cps = []
    for i, cp in enumerate(plan["checkpoints"]):
        # A checkpoint missing "id" (a malformed hand-edit) is a plan problem, not a reason for `status` to
        # crash: fall back to its position so the run stays visible; validate_plan names the real problem.
        cid = cp.get("id", f"#{i}")
        s = st["checkpoints"].get(cid) or {}
        cps.append({"id": cid, "title": cp.get("title", "?"), "risk": cp.get("risk", "normal"),
                    "status": s.get("status", "unsubmitted"), "step": s.get("step"), "commit": s.get("commit"),
                    "gates": {n: {k: g.get(k) for k in ("status", "attempts", "by", "unconfirmed", "flaky") if g.get(k) is not None}
                              for n, g in (s.get("gates") or {}).items()}})
    na = next_action(ctx, st)
    hs = hooks_view(ctx, st)
    hw = hooks_warning(ctx, hs)
    waiting_on = None
    if st["phase"] in ("awaiting_plan_approval", "awaiting_checkpoint_review", "awaiting_final_review", "blocked"):
        waiting_on = "director" if approval_mode(ctx) == "director" else "human"
    obj = plan.get("objective") if isinstance(plan, dict) else None
    return {"root": str(ctx.root), "slug": st["slug"], "feature": st["feature"], "phase": st["phase"],
            "current": st.get("current"), "step": na.get("step"), "next": na["action"], "stop_ok": na["stop_ok"],
            "objective": obj if isinstance(obj, dict) and obj else NO_OBJECTIVE_NOTE,
            "waiting_on": waiting_on, "blocked_reason": st.get("blocked_reason"),
            "blocked_reason_plain": plain_reason(st.get("blocked_reason")),
            "accept_note": na.get("accept_note"),
            "awaiting_since": st.get("awaiting_since"), "approval_mode": approval_mode(ctx),
            "wait": live_wait(st), "question": waiting_question(ctx, st),
            "adv_rounds_used": st.get("adv_rounds_total", 0),
            "unavailable_reviewers": {**shared_unavailable(ctx.config()), **unavailable_reviewers(ctx)},
            "host_provider": detect_host(ctx.config()),
            "hooks_warning": hw, "hook_heartbeat": read_heartbeat(ctx.root),
            "hooks": hs, "hook_errors": hook_errors_view(ctx.root, hs.get("host", "unknown")),
            "viewer_url": viewer_link(ctx)["url"], "viewer_live": viewer_link(ctx)["live"],
            "done": sum(1 for c in cps if c["status"] == "done"), "total": len(cps),
            "done_means_table": (done_means_table(ctx, plan, st)
                                 if _finish_pending(st) or _has_shortcut_case(ctx, plan) else None),
            "shortcuts": _sc_saved(ctx),
            "finish_blockers": ([{k: e.get(k) for k in ("number", "text", "reasons")} for e in _finish_blockers(ctx, st)]
                                if _finish_pending(st) else None),
            "small_fix_reviews": _small_fix_review_lines(st), "fix_rounds": _fix_round_lines(st),
            "docs_only_review_skips": _docs_only_skip_lines(st),
            "checkpoints": cps, "updated_at": st.get("updated_at")}


def _lanes_request(args):
    """`lanes --request NAME [--json]`: every lane of a request made by lanes-start, in the request's order, with its
    phase, steps done, who it waits on and since when, whether its branch is merged into main, and, for a finished lane
    not merged yet, `integrate` as the director's next action. Reads only (the same run reads plain `lanes` makes),
    needs no director, and works from the main checkout or from inside any lane's worktree: the request record is read
    from the main checkout. merged is git's answer alone: the lane branch's tip is an ancestor of main's HEAD AND the
    branch has a commit of its own (its tip is not the commit it was created at, read from the branch's oldest reflog
    entry; a branch with no reflog counts as having one). integrations.jsonl never changes it."""
    def git(d, *a):
        return subprocess.run(["git", "--no-optional-locks", *a], cwd=d, capture_output=True, text=True, timeout=60)

    here = find_root()
    wl = git(here, "worktree", "list", "--porcelain")
    first = next((ln[9:] for ln in wl.stdout.splitlines() if ln.startswith("worktree ")), None)
    main = Path(first) if wl.returncode == 0 and first else here
    name = args.request
    rdir = main / RATCHET_DIR / "requests"
    rec, why = None, "missing"
    if re.fullmatch(r"[a-z0-9]+(-[a-z0-9]+)*", name or ""):
        rec, why = _read_record(rdir / f"{name}.json", missing=None)
        if rec is None and why is None:
            why = "missing"
    if why:
        if why != "missing":
            die(f"The request record for '{name}' in {main} can't be read ({why}). Restore "
                f".ratchet/requests/{name}.json there.")
        known = sorted(p.stem for p in rdir.glob("*.json")) if rdir.is_dir() else []
        die(f"There is no request named '{name}' recorded in {main}; "
            + (f"recorded requests: {', '.join(known)}." if known else "no requests are recorded there."))
    lanes_in = rec.get("lanes")
    if not isinstance(lanes_in, list):
        die(f"The request record for '{name}' in {main} has no lane list, so there is nothing to show.")
    ok_main = git(main, "rev-parse", "--verify", "-q", "HEAD").returncode == 0
    out = []
    for x in lanes_in:
        if not isinstance(x, dict):
            continue
        lane, branch, wt = str(x.get("name")), str(x.get("branch") or x.get("name")), str(x.get("worktree") or "")
        missing = not (wt and os.path.isdir(wt))
        phase, done, total, waiting, since = "not_started", 0, 0, None, None
        if not missing:
            lctx = Ctx(Path(wt))
            slug = lctx.active_slug()
            if slug and lctx.state_path(slug).is_file():
                try:
                    sj = status_json(lctx)
                    phase, done, total = sj["phase"], sj["done"], sj["total"]
                    waiting, since = sj["waiting_on"], sj["awaiting_since"]
                except SystemExit:
                    phase = "unreadable"
        merged = False
        tip = git(main, "rev-parse", "--verify", "-q", f"refs/heads/{branch}").stdout.strip()
        if tip and ok_main and git(main, "merge-base", "--is-ancestor", tip, "HEAD").returncode == 0:
            made = git(main, "reflog", "show", "--format=%H", f"refs/heads/{branch}").stdout.split()
            merged = not made or made[-1] != tip
        out.append({"lane": lane, "branch": branch, "worktree": wt, "worktree_missing": missing, "phase": phase,
                    "done": done, "total": total, "waiting_on": waiting, "awaiting_since": since, "merged": merged,
                    "next_director_action": "integrate" if phase == "done" and not merged and not missing else None})
    if args.json:
        print(json.dumps({"request": name, "lanes": out}, indent=2))
        return
    print(f"Request '{name}': {len(out)} lane(s)")
    for l in out:
        print(f"{l['lane']}: {l['phase']}, {l['done']}/{l['total']} steps, "
              + ("merged into main" if l["merged"] else "not merged into main"))
        if l["waiting_on"]:
            print(f"  waiting on the {l['waiting_on']} since {l['awaiting_since']}")
        if l["phase"] == "not_started" and not l["worktree_missing"]:
            print("  not started: the lane's agent has not run init yet")
        if l["worktree_missing"]:
            print(f"  worktree gone ({l['worktree']})" + (": the work is in main, nothing to do" if l["merged"] else
                  f": recreate it with git worktree add {l['worktree']} {l['branch']}, or drop the lane"))
        if l["next_director_action"]:
            print("  next: integrate this lane")


def cmd_lanes(args):
    if args.request:
        return _lanes_request(args)
    base = Path(args.scan).resolve()
    state_file = base / ".ratchet-lanes.json"
    if args.stop:
        ok("Lanes dashboard stopped" if _stop_server(state_file) else "No lanes dashboard was running")
        return
    if args.serve and args.foreground:
        token = os.environ.get("RATCHET_VIEWER_TOKEN") or None
        srv = _http_server(args.bind, args.port, _make_handler(_dashboard_routes(base), token))
        srv.serve_forever()
        return
    if args.serve:
        info, started = _start_server("lanes", base, state_file, args.bind, args.port, args.token or "auto",
                                      args.public_host, extra=("--scan", str(base)))
        print(f"Lanes dashboard {'started' if started else 'already running'}: {info['url']}")
        if args.open:
            webbrowser.open(info["url"])
        return
    out = []
    for helper in sorted(base.rglob(f"{RATCHET_DIR}/active.json")):
        root = helper.parent.parent
        if any(part in FINGERPRINT_EXCLUDES - {RATCHET_DIR} for part in root.relative_to(base).parts):
            continue
        try:
            out.append(status_json(Ctx(root)))
        except SystemExit:
            out.append({"root": str(root), "error": "unreadable state"})
    if args.json:
        print(json.dumps(out, indent=2))
        return
    for l in out:
        if "error" in l:
            print(f"{l['root']}: {l['error']}")
            continue
        flag = f"  ⚑ waiting on {l['waiting_on']}" if l["waiting_on"] else ""
        print(f"{l['slug']:<28} {l['phase']:<26} {l['done']}/{l['total']}  {l['current'] or '-':<5} {l['root']}{flag}")
        print(f"{'':<28} viewer: {l['viewer_url']}")


def cmd_fingerprint(args):
    print(json.dumps(fingerprint(find_root())))


def cmd_config(args):
    ctx = Ctx(find_root())
    if args.set:
        user = read_json(ctx.config_path, {}) or {}
        for kv in args.set:
            k, _, v = kv.partition("=")
            try:
                val = json.loads(v)
            except json.JSONDecodeError:
                val = v
            if k == "quota_retest_minutes":
                quota_retest_minutes({k: val})
            if k == "related_test_command" and val and "{files}" not in str(val):
                die(_NO_FILES_PLACEHOLDER_MSG, 2)
            if k == "suite_watch_seconds" and _suite_watch_seconds({k: val}) is None:
                die(f"suite_watch_seconds must be a number of seconds above 0 (got {v!r}); the value was not changed.", 2)
            cur = user
            parts = k.split(".")
            for p in parts[:-1]:
                cur = cur.setdefault(p, {})
            cur[parts[-1]] = val
        if any(kv.partition("=")[0].split(".")[0] == "provider_share" for kv in args.set):
            share = user.get("provider_share")  # as it will read once merged over the defaults
            provider_share({"provider_share": {**DEFAULT_CONFIG["provider_share"], **share} if isinstance(share, dict) else share})
        write_json(ctx.config_path, user)
        cfg = ctx.config()
        for kv in args.set:
            k = kv.partition("=")[0]
            cur = cfg
            for part in k.split("."):
                cur = cur.get(part) if isinstance(cur, dict) else None
            ok(f"Set {k} = {json.dumps(cur)}")
        return
    print(json.dumps(ctx.config(), indent=2))


# --------------------------------------------------------------------------- viewer

def viewer_data(ctx: Ctx):
    st = ctx.state()
    plan = ctx.plan() or {"checkpoints": []}
    tests = {}
    for cp in plan.get("checkpoints", []):
        tp = test_plan(ctx, cp["id"])
        if tp:
            tests[cp["id"]] = tp
    learn = ctx.ratchet / "learnings.md"
    cfg = ctx.config()
    reviews = {}
    for cp in plan.get("checkpoints", []):
        g = ((st.get("checkpoints") or {}).get(cp["id"]) or {}).get("gates", {}).get("adversarial") or {}
        rounds = []
        for i, rd in enumerate(g.get("rounds") or [], 1):
            who = [plain_reviewer(cfg, x["id"], x.get("model")) for x in rd.get("reviewers") or []] or \
                  [plain_reviewer(cfg, v["reviewer"]) for v in rd.get("verdicts") or []]
            own = all((_roster_spec(cfg, x["id"]) or {}).get("kind") == "agent" for x in rd.get("reviewers") or []) \
                if rd.get("reviewers") else None
            rounds.append({"round": i, "who": who, "blocking": rd.get("findings", 0),
                           "deferred": rd.get("deferred", 0), "own_company_only": own,
                           "unconfirmed": [v["reviewer"] for v in rd.get("verdicts") or []
                                           if v.get("origin") == UNCONFIRMED]})
        if rounds:
            reviews[cp["id"]] = {"rounds": rounds, "deferred_total": len(((st.get("checkpoints") or {}).get(cp["id"]) or {}).get("deferred") or [])}
    spec = None
    src = spec_source(ctx)
    if src:
        items = spec_items(ctx, src)
        cov = spec_coverage(ctx, plan, items)
        done = {cid for cid, c in (st.get("checkpoints") or {}).items() if c.get("status") == "done"}
        rows = []
        for it in items:
            for r in it["requirements"]:
                for sc in r.get("scenarios") or [{"ref": r["ref"], "name": r["title"]}]:
                    steps = sorted({c["checkpoint"] for c in cov["by_case"].get(sc["ref"]) or []} |
                                   set(cov["ui_steps"].get(sc["ref"]) or []))
                    rows.append({"ref": sc["ref"], "requirement": r["title"], "name": sc.get("name"),
                                 "tests": [c["case"] for c in cov["by_case"].get(sc["ref"]) or []], "steps": steps,
                                 "state": "left out" if sc["ref"] in cov["unmapped"] else
                                 ("not planned" if not steps else ("proven" if all(x in done for x in steps) else "planned"))})
        spec = {"items": [{"tool": it["tool"], "label": _spec_label(it), "status": it.get("status")} for it in items],
                "rows": rows, "tasks_total": len(cov["tasks"]), "tasks_ticked": len(cov["done_tasks"]),
                "unmapped": cov["unmapped"]}
    return {"reviews": reviews, "spec": spec,
            "state": dict({k: v for k, v in st.items() if k not in ("history", "approved")},
                         blocked_reason_plain=plain_reason(st.get("blocked_reason"))),
            "prototype": (ctx.run_dir() / "reference" / "prototype.html").exists(),
            "history": st.get("history", [])[-40:], "plan": plan, "tests": tests,
            "learnings": learn.read_text() if learn.exists() else "",
            # compute_accept_note=False: the viewer never shows accept_note from this "next" object (only `label`
            # and `action`), so it must not pay _blocked_accept_note's working-tree fingerprint on every rebuild.
            "next": dict(next_action(ctx, st, compute_accept_note=False), label=plain_now(ctx, st, plan)),
            "hooks": hooks_view(ctx, st), "generated_at": now()}


def build_viewer(ctx: Ctx) -> Path:
    rd = ctx.run_dir()
    data = viewer_data(ctx)
    write_json(rd / "viewer-data.json", data)
    if not VIEWER_TEMPLATE.exists():
        return rd / "viewer-data.json"
    html = VIEWER_TEMPLATE.read_text(encoding="utf-8")
    payload = json.dumps(data, ensure_ascii=False).replace("</", "<\\/")
    html = html.replace("/*__RATCHET_DATA__*/null", payload)
    out = rd / "viewer.html"
    out.write_text(html, encoding="utf-8")
    return out


def open_viewer(path: Path):
    try:
        if sys.platform == "darwin":
            subprocess.Popen(["open", str(path)])
        elif os.name == "nt":
            os.startfile(str(path))  # type: ignore[attr-defined]
        elif shutil.which("xdg-open"):
            subprocess.Popen(["xdg-open", str(path)], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        else:
            webbrowser.open(path.as_uri())
    except Exception as e:
        print(f"(could not open browser automatically: {e}) Open {path} manually.")


# ---- viewer delivery ---------------------------------------------------------------------
# `view`            print the viewer link (live URL if a server is running, else file:// link)
# `view --serve`    start a live server IN THE BACKGROUND on a free port; URL saved to
#                   .ratchet/viewer.json and shown by `status --json` (viewer_url)
# `view --bind 0.0.0.0`  reachable from other machines; a random token is added to the URL
# `view --stop`     stop this project's server
# `lanes --serve`   one dashboard for every lane under a folder, each lane's viewer proxied under /lane/<n>/

VIEWER_PORT_BASE = 4477
LOOPBACK = ("127.0.0.1", "localhost", "::1")


def _free_port(bind: str, start: int) -> int:
    import socket
    for port in range(start, start + 200):
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            try:
                s.bind((bind if bind != "localhost" else "127.0.0.1", port))
                return port
            except OSError:
                continue
    die(f"No free port found from {start}")


def _pid_alive(pid) -> bool:
    try:
        os.kill(int(pid), 0)
        return True
    except (OSError, ValueError, TypeError):
        return False


def _port_open(port, host="127.0.0.1") -> bool:
    import socket
    try:
        with socket.create_connection((host, int(port)), timeout=0.5):
            return True
    except OSError:
        return False


def _public_host(bind: str, override: str | None) -> str:
    if override:
        return override
    if bind in LOOPBACK:
        return "127.0.0.1"
    import socket
    try:  # the address other machines on the network would use
        with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as s:
            s.connect(("10.255.255.255", 1))
            return s.getsockname()[0]
    except OSError:
        return socket.gethostname()


def server_info(state_file: Path) -> dict | None:
    info = read_json(state_file, None, record="Ratchet treats it as naming no running server")
    if info and _pid_alive(info.get("pid")) and _port_open(info.get("port")):
        return info
    return None


def viewer_link(ctx) -> dict:
    live = server_info(ctx.ratchet / "viewer.json")
    path = ctx.run_dir() / "viewer.html"
    return {"url": live["url"] if live else path.resolve().as_uri(), "live": bool(live),
            "file": str(path), "remote": bool(live and live.get("bind") not in LOOPBACK)}


def _spawn_background(argv: list, log: Path, env_extra=None) -> int:
    kw = {"stdout": open(log, "a"), "stderr": subprocess.STDOUT, "stdin": subprocess.DEVNULL,
          "env": dict(os.environ, **(env_extra or {}))}
    if os.name == "nt":
        kw["creationflags"] = 0x00000008 | 0x00000200  # DETACHED_PROCESS | CREATE_NEW_PROCESS_GROUP
    else:
        kw["start_new_session"] = True
    return subprocess.Popen([sys.executable, str(Path(__file__).resolve()), *argv], **kw).pid


def _start_server(kind, root: Path, state_file: Path, bind, port, token_mode, public_host, extra=()):
    info = server_info(state_file)
    if info and info.get("bind") == bind:
        return info, False
    if info:
        _stop_server(state_file)
    port = port or _free_port(bind, VIEWER_PORT_BASE)
    token = None
    if token_mode == "on" or (token_mode == "auto" and bind not in LOOPBACK):
        token = secrets.token_urlsafe(16)
    argv = ["--root", str(root), kind, "--serve", "--foreground", "--port", str(port), "--bind", bind, *extra]
    log = state_file.parent / f"{state_file.stem}.log"
    # the token travels by environment, not argv, so it never shows up in `ps`
    pid = _spawn_background(argv, log, {"RATCHET_VIEWER_TOKEN": token or ""})
    for _ in range(50):
        if _port_open(port):
            break
        import time
        time.sleep(0.1)
    else:
        try:  # don't leave a half-started server behind
            import signal
            os.kill(pid, signal.SIGTERM)
        except OSError:
            pass
        die(f"Viewer server did not start — see {log}")
    host = _public_host(bind, public_host)
    url = f"http://{host}:{port}/" + (f"?t={token}" if token else "")
    info = {"url": url, "pid": pid, "port": port, "bind": bind, "token": token, "started_at": now()}
    _write_record(state_file, info, pretty=True)
    return info, True


def _stop_server(state_file: Path) -> bool:
    info = read_json(state_file, None, record="Ratchet treats it as naming no running server")
    if not info:
        return False
    try:
        import signal
        import time
        os.kill(int(info["pid"]), signal.SIGTERM)
        for _ in range(30):  # wait for the port to be released
            if not _pid_alive(info["pid"]):
                break
            time.sleep(0.1)
    except (OSError, ValueError, KeyError):
        pass
    state_file.unlink(missing_ok=True)
    return True


def _http_server(bind, port, handler):
    """ThreadingHTTPServer without its reverse-DNS lookup of the bind address. That lookup can take
    5s or more (0.0.0.0 on a machine with slow DNS), long enough to outlast the start-up wait."""
    import http.server
    import socketserver

    class Server(http.server.ThreadingHTTPServer):
        def server_bind(self):
            socketserver.TCPServer.server_bind(self)
            self.server_name, self.server_port = str(self.server_address[0]), self.server_address[1]
    return Server((bind, port), handler)


def _make_handler(routes, token):
    """routes(path) -> (status, content_type, bytes) or None."""
    import http.server
    from urllib.parse import urlparse, parse_qs

    class H(http.server.BaseHTTPRequestHandler):
        def do_GET(self):
            u = urlparse(self.path)
            if token:
                given = (parse_qs(u.query).get("t") or [""])[0]
                if not hmac.compare_digest(given.encode("utf-8", "replace"), token.encode()):
                    return self._send(403, "text/plain", b"Missing or wrong access token (?t=...) for this Ratchet viewer.")
            elif self.server.server_address[0] in ("127.0.0.1", "::1"):
                host = (self.headers.get("Host") or "").rsplit(":", 1)[0].strip("[]").lower()
                if host not in ("127.0.0.1", "localhost", "::1"):  # blocks DNS-rebinding reads of the plan
                    return self._send(403, "text/plain", b"Unexpected Host header.")
            res = routes(u.path)
            if res is None:
                return self._send(404, "text/plain", b"Not found")
            self._send(*res)

        def _send(self, code, ctype, body):
            self.send_response(code)
            self.send_header("Content-Type", ctype)
            self.send_header("Cache-Control", "no-store")
            self.send_header("X-Content-Type-Options", "nosniff")
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, *a):
            pass
    return H


def _viewer_routes(ctx_factory, prefix=""):
    def routes(path):
        ctx = ctx_factory()
        if ctx is None:
            return None
        rel = path[len(prefix):] if path.startswith(prefix) else None
        if rel is None:
            return None
        if rel in ("", "/", "/viewer.html"):
            build_viewer(ctx)
            return 200, "text/html; charset=utf-8", (ctx.run_dir() / "viewer.html").read_bytes()
        if rel == "/viewer-data.json":
            return 200, "application/json", json.dumps(viewer_data(ctx)).encode()
        if rel == "/reference/prototype.html":
            p = ctx.run_dir() / "reference" / "prototype.html"
            return (200, "text/html; charset=utf-8", p.read_bytes()) if p.exists() else None
        return None  # nothing else in the run folder is served
    return routes


def cmd_view(args):
    ctx = Ctx(find_root())
    state_file = ctx.ratchet / "viewer.json"
    if args.stop:
        ok("Viewer server stopped" if _stop_server(state_file) else "No viewer server was running")
        return
    if args.serve and args.foreground:
        token = os.environ.get("RATCHET_VIEWER_TOKEN") or None
        handler = _make_handler(_viewer_routes(lambda: Ctx(find_root())), token)
        srv = _http_server(args.bind, args.port, handler)
        srv.serve_forever()
        return
    path = build_viewer(ctx)
    if args.serve:
        info, started = _start_server("view", ctx.root, state_file, args.bind, args.port, args.token or "auto",
                                      args.public_host)
        print(f"Ratchet viewer {'started' if started else 'already running'}: {info['url']}")
        if info.get("token"):
            print("  (reachable from other machines on this network; the ?t= token is required — share the whole URL)")
        if args.open:
            webbrowser.open(info["url"])
        return
    link = viewer_link(ctx)
    print(link["url"])
    if not link["live"]:
        print(f"  (static snapshot — for a live, auto-refreshing page run: ratchet.py view --serve)")
    if args.open:
        webbrowser.open(link["url"]) if link["live"] else open_viewer(path)


