def _scan_lanes(base: Path) -> list[Path]:
    roots = []
    for helper in sorted(base.rglob(f"{RATCHET_DIR}/active.json")):
        root = helper.parent.parent
        if any(part in FINGERPRINT_EXCLUDES - {RATCHET_DIR} for part in root.relative_to(base).parts):
            continue
        roots.append(root)
    return roots


def _dashboard_routes(base: Path):
    def routes(path):
        if path in ("", "/"):
            return 200, "text/html; charset=utf-8", DASHBOARD_HTML.encode()
        if path == "/lanes.json":
            out = []
            for root in _scan_lanes(base):
                try:
                    out.append(status_json(Ctx(root)))
                except SystemExit:
                    out.append({"root": str(root), "error": "unreadable state"})
            return 200, "application/json", json.dumps(out).encode()
        m = re.match(r"^/lane/(\d+)(/.*)?$", path)
        if m:
            lanes = _scan_lanes(base)
            i = int(m.group(1))
            if i >= len(lanes):
                return None
            sub = m.group(2) or "/"
            return _viewer_routes(lambda: Ctx(lanes[i]), "")(sub)
        return None
    return routes


# --------------------------------------------------------------------------- hooks (provider-agnostic)
#
# Ratchet needs three things from whatever agent CLI hosts the loop:
#   stop   — refuse to let the agent end its turn while gates are open
#   prompt — record that a real person typed a message (approvals depend on it)
#   guard  — refuse tool calls that would tamper with gate state or director material
# Every host has these hooks under different names, payload shapes and reply formats.
# `ratchet.py hook <stop|prompt|guard> --host auto|claude|codex|gemini|copilot` normalizes the
# payload, runs ONE shared decision, and answers in the host's dialect.
#
#   host     stop event     prompt event          guard event   block reply
#   claude   Stop           UserPromptSubmit      PreToolUse    exit 2 + stderr
#   codex    Stop           UserPromptSubmit      PreToolUse    exit 2 + stderr
#   gemini   AfterAgent     BeforeAgent           BeforeTool    exit 2 + stderr (AfterAgent retries the turn)
#   copilot  agentStop      userPromptSubmitted   preToolUse    JSON on stdout ({"decision":"block"} /
#                                                               {"permissionDecision":"deny"})
#
# Hooks fail OPEN on internal errors (logged to .ratchet/hook-errors.log): Copilot denies every
# tool call when a preToolUse hook crashes, and a crashing guard must never brick a session.

HOOK_HOSTS = ("claude", "codex", "gemini", "copilot")
HOOK_EVENTS = {  # host -> (stop, prompt, guard) event names in that host's config
    "claude": ("Stop", "UserPromptSubmit", "PreToolUse"),
    "codex": ("Stop", "UserPromptSubmit", "PreToolUse"),
    "gemini": ("AfterAgent", "BeforeAgent", "BeforeTool"),
    "copilot": ("agentStop", "userPromptSubmitted", "preToolUse"),
}
VENDOR_TO_HOST = {"anthropic": "claude", "openai": "codex", "google": "gemini", "github": "copilot"}

# What Ratchet enforces on each host CLI today. This is the one source for the per-CLI table in README.md
# ("Using it with Codex, Gemini or Copilot"); tests/test_docs.py renders that table from it cell by cell and
# checks every fact against the code that does the work:
#   records   the guard hook blocks hand-edits to .ratchet/ state and evidence (build_hook_config, decide_guard)
#   identity  the host names the acting sub-agent, so review files are checked against their owner (decide_guard)
#   stop      the stop hook keeps the agent from ending its turn early (build_hook_config, emit_hook)
#   replies   the prompt hook records what the user typed (decide_prompt)
#   guidance  the prompt hook's message reaches the agent (emit_hook; Copilot drops it)
HOST_ENFORCEMENT = {
    "claude": {"records": True, "identity": True, "stop": True, "replies": True, "guidance": True},
    "codex": {"records": True, "identity": False, "stop": True, "replies": True, "guidance": True},
    "gemini": {"records": True, "identity": False, "stop": True, "replies": True, "guidance": True},
    "copilot": {"records": True, "identity": False, "stop": True, "replies": True, "guidance": False},
}


def _host_names_subagent(host: str) -> bool:
    return bool(HOST_ENFORCEMENT.get(host, {}).get("identity"))


TOOL_KINDS = {
    "shell": {"bash", "powershell", "run_shell_command", "shell", "exec_command", "local_shell",
              "container.exec", "terminal", "run_in_terminal"},
    "write": {"write", "edit", "multiedit", "notebookedit", "apply_patch", "write_file", "replace", "create",
              "str_replace_editor", "str_replace_based_edit_tool", "create_file", "edit_file", "insert"},
    "read": {"read", "grep", "glob", "ls", "read_file", "read_many_files", "view", "search_file_content",
             "list_directory", "find_files"},
}
PATCH_FILE_RE = re.compile(r"^\*\*\* (?:Add|Update|Delete) File: (.+)$|^\*\*\* Move to: (.+)$", re.M)


def _hook_input():
    try:
        raw = sys.stdin.read()
        return json.loads(raw) if raw.strip() else {}
    except Exception:
        return {}


def detect_hook_host(data: dict, explicit: str | None = None) -> str:
    if explicit and explicit != "auto":
        return explicit
    if any(k in data for k in ("toolName", "toolArgs", "sessionId", "stopReason")):
        return "copilot"
    if data.get("hook_event_name") in ("AfterAgent", "BeforeAgent", "BeforeTool", "AfterTool", "BeforeModel"):
        return "gemini"
    if "turn_id" in data:
        return "codex"
    return VENDOR_TO_HOST.get(detect_host({}), "claude")


def _tool_kind(name: str) -> str:
    n = (name or "").lower()
    for kind, names in TOOL_KINDS.items():
        if n in names:
            return kind
    if n.startswith("mcp__") or n.startswith("mcp_"):
        return "mcp"
    return "other"


def normalize_hook(data: dict, host: str) -> dict:
    tool = data.get("tool_name") or data.get("toolName") or ""
    ti = data.get("tool_input", data.get("toolArgs", {}))
    if isinstance(ti, str):
        try:
            ti = json.loads(ti)
        except json.JSONDecodeError:
            ti = {"raw": ti}
    if not isinstance(ti, dict):
        ti = {"value": ti}
    cmd = ti.get("command") or ti.get("cmd") or ti.get("script") or ""
    if isinstance(cmd, list):
        cmd = [str(c) for c in cmd]
        # An argv-list Bash call some hosts send (Codex: ["bash", "-lc", "<script>"]) names its script as one
        # argument; joining the list with spaces would run the script's own text (quotes, heredocs and all)
        # through the word-by-word join, splitting it up and changing what the guard sees. Read the script as
        # the command itself instead, exactly as a plain string Bash call would send it.
        if (len(cmd) == 3 and re.fullmatch(r"[A-Za-z0-9_./-]*(bash|sh|zsh|dash|ksh)", cmd[0]) and
                re.fullmatch(r"-[a-z]*c[a-z]*", cmd[1])):
            cmd = cmd[2]
        else:
            cmd = " ".join(cmd)
    paths = [str(ti[k]) for k in ("file_path", "path", "absolute_path", "notebook_path", "filePath", "target_file")
             if isinstance(ti.get(k), str)]
    patch = ""
    for k in ("patch", "input", "raw"):
        if isinstance(ti.get(k), str) and "*** " in ti[k]:
            patch = ti[k]
            paths += [a or b for a, b in PATCH_FILE_RE.findall(patch)]
    kind = _tool_kind(tool)
    if kind in ("other", "mcp"):
        kind = "shell" if cmd else ("write" if paths or patch else kind)
    return {"host": host, "tool": tool, "kind": kind, "input": ti, "command": str(cmd), "paths": paths,
            "patch": patch, "cwd": data.get("cwd") or os.getcwd(),
            "prompt": data.get("prompt") or "", "session": data.get("session_id") or data.get("sessionId"),
            "agent_type": data.get("agent_type") or "", "agent_id": data.get("agent_id") or "",
            "transcript_path": data.get("transcript_path") or data.get("transcriptPath")}


def _heartbeat_path(root: Path) -> Path:
    return root / RATCHET_DIR / "hook-heartbeat.json"


def _heartbeat(root: Path, event: str, host: str):
    """Record that a hook fired (liveness only). It never carries crash state: crash records live only in per-run
    marker files and appended lines (see _record_hook_run). Concurrent hooks rewrite this shared file only through
    update_record, under its own lock, so none drops another's entry; a beat skipped because the lock could not be
    had within a second only makes a hook look less healthy until its next run.
    The rewrite goes to a per-process temp file that then replaces the heartbeat in one rename, so a concurrent
    hook never reads a truncated, half-written heartbeat (that read would fail and crash the reading hook)."""
    p = _heartbeat_path(root)

    def beat(hb):
        hb[event] = {"at": now(), "host": host}
        return hb
    try:  # every hook rewrites it: under its own lock (a second at most: a hook never waits long), so a concurrent
        # hook never drops this hook's entry; when the lock can't be had, this beat is skipped (liveness only)
        _ = update_record(p, beat, wait=1.0,
                          damaged="Ratchet treats it as recording no hook run and replaces it now")  # writes use open()
    except Exception:
        pass


ENGINE_PATH = str(Path(__file__).resolve())

# The prompt and stop hooks keep their own append-only records in the run folder (never state.json, which only a
# command holding the state lock writes): the engine reads them.
PROMPT_CHATS_FILE = "prompt-chats.jsonl"  # a chat the user typed in while no chat owned the run: {"at", "session"}
STOP_BLOCKS_FILE = "stop-blocks.jsonl"  # each stop the stop hook refused {"at", "phase"}, or a reset {"at", "reset"}


def _jsonl(p: Path) -> list:
    """The JSON objects on the lines of one of the run's .jsonl records ([] when it is missing or can't be read;
    a line that is not one is skipped, so a damaged line grants nothing)."""
    recs, _why = _read_record(p, lines=True)
    return recs or []


def _append_jsonl(p: Path, rec: dict) -> bool:
    try:
        _append_record(p, json.dumps(rec, ensure_ascii=False) + "\n")
        return True
    except OSError:
        return False


def _prompt_owner(ctx, st):
    """(session, at, records read) for the first chat the prompt hook recorded for this run while no chat owned it,
    after the records already used (`prompt_chats_seen`). Only a record matching a message in human_log.jsonl (same
    time, same chat) counts. None when there is none."""
    recs = _jsonl(ctx.run_dir(st["slug"]) / PROMPT_CHATS_FILE)
    fresh = recs[int(st.get("prompt_chats_seen") or 0):]
    if not fresh:
        return None
    typed = {(e.get("at"), e.get("session")) for e in _human_since(ctx, "0") if e.get("session")}
    for r in fresh:
        if isinstance(r.get("session"), str) and r["session"] and (r.get("at"), r["session"]) in typed:
            return r["session"], r.get("at"), len(recs)
    return None


def _bind_prompt_owner(ctx, st) -> bool:
    """Make the chat the prompt hook recorded (see _prompt_owner) the owner of a run no chat owns yet. Each record
    is used once, so an owner set later is never replaced from an old record. True when the state changed."""
    if st.get("owner_session") or st.get("phase") in ("done", "cancelled"):
        return False
    got = _prompt_owner(ctx, st)
    if not got:
        return False
    st["owner_session"], typed_at, st["prompt_chats_seen"] = got
    ctx.log(st, "owner_recorded", session=got[0], via="prompt", typed_at=typed_at)
    return True


def _last_human_at(ctx) -> str:
    """When the user last typed a message (human_log.jsonl's last chat line; an override audit line is not one)."""
    recs, _why = _read_record(ctx.ratchet / "human_log.jsonl", lines=True, tail=65536)
    for e in reversed(recs or []):
        if not e.get("override") and isinstance(e.get("at"), str):
            return e["at"]
    return ""


def _stop_blocks(ctx, st) -> int:
    """How many stops the stop hook refused since the run last made progress: a PROGRESS_EVENTS or `resumed` entry
    in its history, a message the user typed, or a stop the hook allowed (a reset line)."""
    since = max([e.get("at", "") for e in st.get("history", [])
                 if e.get("event") in PROGRESS_EVENTS or e.get("event") == "resumed"] + [_last_human_at(ctx), ""])
    n = 0
    for r in _jsonl(ctx.run_dir(st["slug"]) / STOP_BLOCKS_FILE):
        if str(r.get("at", "")) <= since:
            continue
        n = 0 if r.get("reset") else n + 1
    return n


def _settle_waiver(ctx):
    """The enforcement hooks fired after the user chose to build without them: record the waiver's end in state.json
    now (Ctx.save_state drops it and counts the clearing), so hooks that later go silent can't bring it back. One
    try at the state lock, never a wait: if a command holds it, that command's own save clears the waiver."""
    lock = _StateLock(ctx.root, wait=0, cmd="the stop hook")
    if lock.acquire() or not lock.held:
        return
    try:
        st = ctx.state()
        if st.get("hooks_waived"):
            ctx.save_state(st)
    except (Exception, SystemExit):
        pass  # the next command's save clears it instead; the stop decision goes on from what was read
    finally:
        lock.release()


def decide_stop(n: dict) -> tuple[bool, str]:
    root = find_root(Path(n["cwd"]))
    ctx = Ctx(root)
    marker = _active_marker(root)
    if not ctx.ratchet.is_dir() or not ctx.active_slug():
        if marker:  # .ratchet/ vanished under an active run: never let that end the loop silently
            return _stop_error(root, f"Ratchet run '{marker['slug']}' was active here but its .ratchet/ state is gone. "
                                     "Tell the user; restore it (e.g. from git history or backup) or ask them to cancel.")
        return False, ""
    _heartbeat(root, "stop", n["host"])
    # Reading state.json needs no lock (it is replaced in one rename); this hook never waits on, or writes, the
    # state a command holds: its count of refused stops is its own file (STOP_BLOCKS_FILE).
    st, why = _read_record(ctx.state_path(), missing=None)
    if why is not None:
        # A damaged run state breaks this hook's check: logged to hook-errors.log like a crash (status, next and
        # doctor show it, and the hook does not count as working until it runs cleanly), and the stop fails closed a
        # few times. No crash marker: it is not this hook's own failure, so the commands that repair the run (accept-
        # state, init --force) are never locked out behind it.
        try:
            _append_record(root / RATCHET_DIR / "hook-errors.log",
                           f"{now()} {n['host']} stop: StateUnreadable: {ctx.state_path()}: {why}\n")
        except OSError:
            pass
        return _stop_error(root, f"Ratchet could not read its run state ({ctx.state_path()}: {why}).")
    if not st:
        return _stop_error(root, "Ratchet's state.json for the active run is missing or unreadable.")
    owner = st.get("owner_session") or (_prompt_owner(ctx, st) or (None,))[0]
    if owner and n.get("session") and n["session"] != owner:
        _reset_stop_errors(root)
        return False, ""  # another session in the same repo: not bound by this run (the prompt hook tells it)
    holder = _StateLock(root).live_holder()
    if holder:  # a Ratchet command is changing the run right now: what it leaves is not known yet
        return _stop_error(root, f"Ratchet is busy running {holder}, so this stop could not be checked. Wait for it "
                                 "to finish.")
    _reset_stop_errors(root)
    if st.get("hooks_waived") and not _waiver_applies(root, ctx.config(), st):
        _settle_waiver(ctx)
    blocks_file = ctx.run_dir(st["slug"]) / STOP_BLOCKS_FILE
    na = next_action(ctx, st)
    if na.get("stop_ok"):
        if _stop_blocks(ctx, st):
            _append_jsonl(blocks_file, {"at": now(), "reset": True})
        return False, ""
    w = live_wait(st)
    if w:  # the owner chat said it is waiting on background work (`ratchet.py wait`): this stop is not counted
        return False, (f"RATCHET: waiting on {w['reason']} until {w['until'][:16].replace('T', ' ')} UTC, so this "
                       "stop is allowed and not counted. When the background work reports back, carry on with "
                       "`ratchet.py next`.")
    cfg = ctx.config()
    count = _stop_blocks(ctx, st) + 1
    _append_jsonl(blocks_file, {"at": now(), "phase": st.get("phase")})
    if count > cfg["max_stop_blocks"]:
        reason = (f"The agent tried to stop {count} times without any gate progress — loop halted for the user to "
                  "look at.")
        lock = _StateLock(root, wait=0, cmd="the stop hook")  # one try: never waits behind a command
        if not lock.acquire():
            try:
                st = ctx.state()
                _set_blocked(st, reason)
                ctx.save_state(st)
            except (Exception, SystemExit):
                pass  # state Ratchet won't trust (Ctx.state refused it): the stop is still let through, said below
            finally:
                lock.release()
        return False, f"RATCHET: safety valve — {reason}"
    return True, ("RATCHET GATE: the work is not done, so you may not stop yet.\n"
                  f"Run: {st['slug']}  phase={na['phase']}"
                  + (f"  checkpoint={na.get('checkpoint')}  step={na.get('step')}" if na.get("checkpoint") else "")
                  + f"\nNext required action: {na['action']}\n"
                  f"(Engine: python3 \"{ENGINE_PATH}\" — load the ratchet-orchestrator skill if you haven't.)\n"
                  "Gates cannot be skipped or argued past. If the user asked you to stop, or you are genuinely "
                  "stuck, run `ratchet.py pause --reason \"...\"` and tell the user why.")


def _stop_errors_path() -> Path:
    return ratchet_home() / "stop-errors.json"


def _reset_stop_errors(root: Path):
    """Forget this project's count of refused stops on unreadable state. A damaged per-user file holds no count and
    is replaced now (it only lets a session stop sooner, after a few refusals, so it grants nothing)."""
    p = _stop_errors_path()
    key = str(root.resolve())
    data, why = _read_record(p)  # a quick look first: nothing to forget, nothing to lock or write
    if why is None and key not in data:
        return

    def forget(data):
        return data if data.pop(key, None) is not None or bad else KEEP
    bad = why is not None
    try:  # shared by every project: under its own lock, so no other project's count is dropped
        _ = update_record(p, forget, damaged="Ratchet treats it as holding no count and replaces it now", pretty=True)
    except OSError:
        pass


def _stop_error(root: Path, why: str) -> tuple[bool, str]:
    """Fail CLOSED for stop when state is unreadable — but only a few times, so a broken install can't trap a session.
    A damaged per-user count reads as no count (one more refusal at most) and is replaced."""
    p = _stop_errors_path()
    key = str(root.resolve())
    count = [1]  # when the count can't be read or saved, this is one refusal more (fail closed)

    def bump(data):
        n = data.get(key)
        count[0] = data[key] = (n if isinstance(n, int) and not isinstance(n, bool) else 0) + 1
        return data
    try:  # shared by every project: under its own lock, so no other project's count is dropped
        _ = update_record(p, bump, damaged="Ratchet treats it as holding no count and replaces it now", pretty=True)
    except Exception:
        pass
    if count[0] > 5:
        return False, f"RATCHET: {why} (letting you stop after repeated failures — tell the user.)"
    return True, f"RATCHET: {why} You may not stop silently: explain this to the user first."


# Turns an agent CLI sends through the prompt hook on its own, not typed by the user: a background sub-agent's
# hand-back, a background task's notice. A prompt where one of these exact markers STARTS any line of it is never
# recorded as the user's message, so it answers no waiting question and approves nothing. Before a line is checked,
# any leading whitespace (Unicode and zero-width included) and any leading HOST_TURN_WRAPPER_TAGS (opening or
# closing, repeated in any mix) are set aside on that line alone. A marker only mentioned mid-line changes nothing.
# A real reply with a marker at the start of one of its lines is dropped too (the safe side): the user sends it
# again. Every line of the text is checked, in one linear pass, so no amount of ordinary preamble text ahead of the
# marker line changes the answer: there is no fixed line count, block count or blank-line cap to tune or bypass.
HOST_TURN_MARKERS = ("Another Claude session sent a message:",   # Claude Code's ON-SCREEN RENDERING of a hand-back
                                                                   # (kept too: an older run or a differently-
                                                                   # rendering host may still only show this text)
                     "[SYSTEM NOTIFICATION - NOT USER INPUT]",    # a host notice about background work
                     "<task-notification>")                       # Claude Code: a background task finished
# The real bytes the UserPromptSubmit hook receives for a sub-agent hand-back: wrapped as
# `<agent-message from="...">...</agent-message>` (the attribution value is not fixed). Matched by the opening
# tag alone, so any attribute content or closing-tag spelling still counts.
HOST_TURN_MARKER_RE = re.compile(r"\A<agent-message\b")
HOST_TURN_WRAPPER_TAGS = ("system-reminder",)
_HOST_TURN_SPACE = "[\\s\\u180e\\u200b\\u200c\\u200d\\u2060\\ufeff]"  # \s is Unicode-aware; plus the zero-width ones
_HOST_TURN_TAGS = "|".join(map(re.escape, HOST_TURN_WRAPPER_TAGS))
HOST_TURN_PAD_RE = re.compile(r"\A(?:%s|</?(?:%s)\b[^>]*>)+" % (_HOST_TURN_SPACE, _HOST_TURN_TAGS), re.I)
_HOST_TURN_EOL_RE = re.compile("\r\n|[\n\r\v\f\x1c\x1d\x1e\x85  ]")  # the breaks str.splitlines uses


def host_generated_turn(prompt) -> bool:
    """Is this prompt one the agent CLI generated itself: does a HOST_TURN_MARKERS entry, or the real
    `<agent-message ...>` wrapper (HOST_TURN_MARKER_RE), start any line of it, once that line's own leading
    whitespace and leading wrapper tags are set aside? One linear pass over the text, line by line; no fixed
    line count, block count or blank-line cap, so no amount of preamble text ahead of the marker line changes
    the answer. A marker only mentioned mid-line (not at the start of any line) changes nothing."""
    text = prompt if isinstance(prompt, str) else ""
    pos = 0
    while True:
        m = _HOST_TURN_EOL_RE.search(text, pos)
        end = m.start() if m else len(text)
        line = text[pos:end]
        pad = HOST_TURN_PAD_RE.match(line)
        if pad:
            line = line[pad.end():]
        if line.startswith(HOST_TURN_MARKERS) or HOST_TURN_MARKER_RE.match(line):
            return True
        if not m:
            return False
        pos = m.end()


def decide_prompt(n: dict) -> tuple[bool, str]:
    if os.environ.get("RATCHET_NESTED_REVIEW") == "1":
        return False, ""
    root = find_root(Path(n["cwd"]))
    rdir = root / RATCHET_DIR
    if not rdir.is_dir():
        return False, ""
    if host_generated_turn(n.get("prompt")):  # nothing is recorded: not the user's message, not a chat they typed in
        _heartbeat(root, "prompt", n["host"])
        return False, ("[ratchet] This turn was sent by the agent CLI itself (a background sub-agent's hand-back or "
                       "a task notice), not typed by the user, so Ratchet did not record it: it answers no waiting "
                       "question and approves nothing. Carry on; if it was really the user's reply, ask them to send "
                       "it again.")
    # This hook never takes the state lock and never writes state.json, so it never waits behind a long command
    # (a test run) and can't undo what a command wrote. It only appends to its own records: the message to
    # human_log.jsonl (with its hash, as one step), and, while no chat owns the run, this chat to PROMPT_CHATS_FILE;
    # the next command reads them (Ctx.state). A user message also restarts the stop hook's count (_stop_blocks).
    _heartbeat(root, "prompt", n["host"])
    log = rdir / "human_log.jsonl"
    problem = chain_problem(log, "human_log.jsonl")
    if problem:  # never a crash: the message is not recorded, so it approves and answers nothing
        return False, ("[ratchet] Ratchet did not record this message, so it approves nothing and answers no waiting "
                       f"question. {problem}")
    at = now()
    append_recorded(log, json.dumps({"at": at, "prompt": n["prompt"][:2000], "session": n["session"],
                                     "host": n["host"], "transcript_path": n.get("transcript_path")},
                                    ensure_ascii=False) + "\n")
    ctx = Ctx(root)
    if ctx.active_slug():
        st, why = _read_record(ctx.state_path(), missing=None)
        if why is not None:  # never a crash: say what is wrong (every command refuses until the file is fixed)
            return False, (f"[ratchet] Ratchet can't read the active run's state.json ({why}), so it can't say "
                           "what this message means for the run, and its commands refuse until the file is fixed. "
                           "Tell the user; restore the file from a backup or their git history, or, to start the "
                           "feature over, they can run `RATCHET_HUMAN_OVERRIDE=1 ratchet.py init --force "
                           "\"<feature>\"` from their own terminal.")
        if st and st.get("phase") not in ("done", "cancelled"):
            here = n.get("session")
            if not st.get("owner_session"):
                # no chat owned the run yet (the first run in a repo starts before the prompt hook can log anything):
                # the first chat the user types in for this run owns it, and only `resume --claim` moves it later
                st["owner_session"] = (_prompt_owner(ctx, st) or (None,))[0]
                if here and not st["owner_session"]:
                    _append_jsonl(ctx.run_dir(st["slug"]) / PROMPT_CHATS_FILE, {"at": at, "session": here})
                    st["owner_session"] = here  # this copy only: the hints below treat it as the owner
            eng = f'python3 "{ENGINE_PATH}"'
            p = st.get("pending") or {}
            claim_here = p.get("action") == "claim" and here and p.get("session") == here
            if st.get("owner_session") and here and here != st["owner_session"] and not claim_here:
                return False, (f"[ratchet] This repo has an unfinished Ratchet run '{st['slug']}' (phase {st['phase']}) "
                               "started in another chat. If the user wants to continue it here, run "
                               f"{_ask_cmd('claim', eng=eng)}, end your message with the question it prints, word for "
                               "word, as the only question in it, and end your turn; run "
                               f"`{eng} resume --claim` only if their first reply after it is one of the listed yes "
                               "replies. Otherwise leave the run alone and do what they asked.")
            if p.get("action") and p["action"] != "hooks-waive":
                p_mode, p_target = _pq(p)
                cmd = _pending_followup(p["action"], p_mode)
                what = _question_what(p["action"], p_mode, p_target)
                again = _ask_cmd(p["action"], p_mode, eng=eng, target=p_target)
                asked_in = _question_session(st, p)
                if asked_in and here and here != asked_in:
                    return False, (f"[ratchet] A Ratchet question (shall I {what}?) is waiting for a reply in another "
                                   "chat. This message does not answer it and approves nothing; do what the user asked "
                                   "here.")
                if p.get("overtook"):
                    return False, (f"[ratchet] Your waiting question (shall I {what}?) was printed while another one was "
                                   "still waiting, so this reply approves nothing, whatever it says. Answer what they "
                                   f"said; if you still need their answer, run {again} again and show them only that "
                                   "question.")
                if p["action"] == "choice":
                    letter = choice_letter(n["prompt"], p.get("options") or [])
                    if _question_waiter(ctx) == "director":  # read-only: never exits or writes from a hook
                        return False, (f"[ratchet] Your lettered question ({', '.join(p.get('options') or [])}) is "
                                       "waiting on the director: this lane is director-enrolled, so a letter typed "
                                       "in chat picks nothing. Do not run `choice` on it. The director signs a "
                                       f"letter with `director-sign choice <letter>`; apply it with `{eng} choice "
                                       "<letter> --director-token <t>`.")
                    return False, (f"[ratchet] This reply answers your lettered question ({', '.join(p.get('options') or [])}). "
                                   + (f"It reads as option {letter}. " if letter else "It is NOT a clear pick of one option. ")
                                   + f"Run `{eng} choice` to record it, then continue. It does NOT approve the plan or a "
                                   "checkpoint.")
                try:
                    first = len(_replies(ctx, st, p.get("asked_at"), p)) <= 1
                except (Exception, SystemExit):
                    first = True
                if not first:
                    return False, (f"[ratchet] The user's first reply after your waiting question (shall I {what}?) "
                                   "already answered it, so this later message is not their answer: it does NOT "
                                   "approve the plan, a checkpoint or anything else. If you still need their yes, "
                                   f"print the question again ({again}).")
                if p["action"] == "paid-provider":
                    # This question's own exact reply (never the generic listed-yes words: it spends money).
                    exact = _paid_provider_reply(p.get("model") or "")
                    matched = n["prompt"].strip().casefold() == exact.strip().casefold()
                    verdict = (f"It is the exact reply (\"{exact}\")" if matched
                               else f"It is NOT the exact reply (\"{exact}\"), so it approves nothing")
                    return False, (f"[ratchet] This reply answers your waiting question: shall I {what}? {verdict}. "
                                   f"Only after that exact reply run `{eng} {cmd}` (pick an id for the new provider); "
                                   f"otherwise run `{eng} ask withdraw` and do what they asked. This reply does NOT "
                                   "approve the plan, a checkpoint or anything else.")
                if p["action"] == "accept-line":
                    # CP5: this question's own exact reply form, `accept: <reason>` (never a listed yes: the user
                    # gives their own reason), and `accept-line` takes no argument: it reads the lines from pending
                    reason = _accept_reply_reason(n["prompt"])
                    verdict = ("It is in the exact form `accept: <reason>`, the one reply that accepts" if reason
                               else "It is NOT in the exact form `accept: <reason>`, so it accepts nothing")
                    return False, (f"[ratchet] This reply answers your waiting question: shall I {what}? {verdict}. "
                                   f"Run `{eng} {cmd}` now to record it: it accepts the line only after that exact "
                                   "form, and a first reply in any other form closes the question (ask again with "
                                   f"{again} if the user still wants it). Do NOT run `ask withdraw` for a reply in "
                                   "that form. This reply does NOT approve the finish or anything else.")
                verdict = ("It is one of the listed yes replies" if is_listed_yes(n["prompt"])
                           else "It is NOT one of the listed yes replies, so it approves nothing")
                if p["action"] == "human-approve" and _finish_held(ctx, st):
                    # CP4: the question was asked before a line went unproven or a checkpoint or test plan changed;
                    # it no longer counts and the agent is never told to run human-approve while the finish is held
                    return False, (f"[ratchet] This reply does NOT approve the finish: a done-means line went unproven "
                                   "or a checkpoint or test plan changed after your question, so the run cannot be "
                                   "marked done and that question is withdrawn; do not record it as an approval. Run "
                                   f"`{eng} status`, tell the user which lines are unproven and why (or what changed "
                                   "after approval), and follow the ways forward it names; record change requests "
                                   f"with `{eng} feedback`.")
                if p["action"] in ("approve-plan", "human-approve"):
                    return False, (f"[ratchet] This reply answers your waiting question: shall I {what}? {verdict}. "
                                   f"Only if it is a listed yes, run `{eng} {cmd}`. Otherwise answer what they said or "
                                   f"make their change"
                                   + (f" (at a review, record change requests with `{eng} feedback`)"
                                      if p["action"] == "human-approve" else "")
                                   + f", and ask again later with {again}.")
                return False, (f"[ratchet] This reply answers your waiting question: shall I {what}? {verdict}. "
                               f"Only after a listed yes run `{eng} {cmd}`; otherwise run `{eng} ask withdraw` and do "
                               "what they asked. This reply does NOT approve the plan, a checkpoint or anything else.")
            if st["phase"] == "building" and re.match(r"^\s*(stop|pause|hold on|wait|halt|cancel)\b", n["prompt"], re.I):
                return False, (f"[ratchet] The user asked you to stop. Run `{eng} pause --reason \"user asked\"`, "
                               "confirm in one line, and ask whether they want to resume later or cancel the run.")
            if st["phase"] in ("awaiting_plan_approval", "awaiting_checkpoint_review",
                               "awaiting_final_review", "blocked"):
                if CANCEL_HINT_RE.search(n["prompt"]):
                    hint = (f"This may be a request to cancel the run — run {_ask_cmd('cancel', eng=eng)}, end your "
                            "message with the question it prints, word for word, as the only question in it, and end "
                            f"your turn; run `{eng} cancel` only if their first reply after it is one of the listed "
                            "yes replies.")
                elif _finish_held(ctx, st):
                    # CP4: the finish is held (an unproven done-means line, or a checkpoint or test plan changed
                    # after approval): never a hint to ask for or run the approval
                    hint = ("The run cannot be marked done yet, so this reply approves nothing"
                            + (" even though it reads like a yes. " if message_intent(n["prompt"]) == "approve"
                               else ". ")
                            + "Do not put the approval question to them and do not record an approval. Run "
                            f"`{eng} status`: it names the unproven done-means lines (or what changed after approval) "
                            "and the ways forward; tell the user plainly, and record change requests with "
                            f"`{eng} feedback`.")
                else:
                    ask = {"awaiting_plan_approval": "approve-plan"}.get(st["phase"], "human-approve")
                    hint = ("Ratchet has not asked its approval question yet, so this reply approves nothing"
                            + (" even though it reads like a yes. " if message_intent(n["prompt"]) == "approve"
                               else ". Answer it or make the requested change. ")
                            + "When you need their approval, "
                            f"run {_ask_cmd(ask, eng=eng)}"
                            + (" (or offer the lettered options from `next` with `ask choice`)"
                               if st["phase"] == "blocked" else "")
                            + ", end your message with the question it prints, word for word, as the only question "
                            "in it, and end your turn; only their first reply after that question counts.")
                return False, (f"[ratchet] Run '{st['slug']}' is waiting on the user (phase {st['phase']}). {hint} "
                               f"(Engine: {eng})")
    return False, ""


# Inside .ratchet/, agents may only write these (everything else is written by ratchet.py itself).
ALLOWED_RATCHET_WRITES = re.compile(
    r"^runs/[^/]+/(reviews|states|reference|tests)(/.*)?$|^runs/[^/]+/(checkpoints|app-scout)\.json$"
    r"|^(standards\.md|learnings\.md|app\.log)$", re.I)
READ_ONLY_PROGRAMS = {"cat", "less", "more", "head", "tail", "grep", "egrep", "fgrep", "rg", "jq", "ls", "wc",
                      "stat", "file", "diff", "cmp", "md5sum", "sha1sum", "sha256sum", "cd", "pushd", "popd", "pwd",
                      "true", "tree", "du"}
READ_ONLY_GIT = {"diff", "log", "show", "status", "ls-files", "blame", "rev-parse", "cat-file"}
RATCHET_TOKEN_RE = re.compile(r"""[^\s'"<>|;&()`]*\.ratchet(?:[/\\][^\s'"<>|;&()`]*)?""", re.I)
REDIRECT_RE = re.compile(r"(?<![0-9&])>>?\s*(?!&)(\S+)")
# sed's w/W command writes to a filename that can sit right against the command letter with no space
# (`1w.ratchet/x`, a real GNU sed form) -- RATCHET_TOKEN_RE's mention then glues the address/letter onto the
# path, so `_ratchet_rel` (which needs a path separator right before `.ratchet`) misses it for a relative
# target. This recovers the real filename so it's checked too.
SED_W_TARGET_RE = re.compile(r"(?:^|[;{}\s]|[0-9]|\$)[wW]\s*(\S+)")
# CP4: every OUTPUT redirect operator form bash recognises -- `>`, `>>`, `N>`, `N>>`, `&>`, `&>>`, `>|`,
# `N>|`, and `>&word` (word not a digit or `-`, which is fd duplication, not a file) -- unlike REDIRECT_RE
# above, which a negative lookbehind keeps from ever matching a `>` right after a digit or `&` (so `2>`,
# `&>`, `1>`, `>&word` were invisible to it entirely). This is the one shared helper both the fast path
# (`_provably_read_only`) and the strict path (`_guard_shell`) use to find a command's real write targets.
OUTPUT_REDIRECT_RE = re.compile(r"(?:\d+|&)?>>?\|?(&?)\s*([^\s;&|()<>]*)")


def _redirect_targets(seg: str, masked: str | None = None) -> list[str]:
    """Every real (unquoted) output-redirect target named in `seg`, for every form `OUTPUT_REDIRECT_RE`
    recognises. `masked` -- the same text with every separator character that sits inside quotes replaced
    (see `_mask_quoted_seps`), same length and character positions as `seg` -- is scanned for the operators
    themselves, so a `>` sitting inside a quoted jq filter, grep alternation or awk/sed script is never
    mistaken for a real redirect; the real (unmasked) target text is always sliced back out of `seg` itself.
    When `masked` is omitted, `seg` is scanned directly. fd duplication (`2>&1`, `>&2`) and
    /dev/null|/dev/stdout|/dev/stderr are never targets; a `>(` process substitution's own target position
    is always empty here (its argument characters are excluded by the target's own character class), so it
    never appears in this list -- see `_proc_subst_targets` for that case."""
    base = masked if masked is not None else seg
    out = []
    for m in OUTPUT_REDIRECT_RE.finditer(base):
        t = seg[m.start(2):m.end(2)].strip("'\"")
        if m.group(1) == "&" and re.fullmatch(r"\d+|-", t):
            continue  # fd duplication: no file
        if not t or t in ("/dev/null", "/dev/stdout", "/dev/stderr"):
            continue
        out.append(t)
    return out


PROC_SUBST_RE = re.compile(r">\(([^()]*)\)")


def _proc_subst_targets(seg: str, masked: str | None = None) -> list[str]:
    """Every bare (non-flag) argument of the program inside each `>(...)` process substitution in `seg`,
    treated as that program's own write target (CP4 design item 2: `cat x > >(tee <file>)` makes `tee`'s own
    argument `<file>` a write target exactly as a bare `tee <file>` would). Only a single, non-nested
    substitution body is read (no parens inside it); a substitution this can't read this simply contributes
    no targets here, which sends the whole command to the slow, fail-safe mention checks that already run
    beside this -- never narrowing what they refuse.

    `masked` -- the same quote-aware mask `_redirect_targets` takes -- is scanned for `PROC_SUBST_RE` itself,
    exactly like that sibling function, so a `>(...)` shape sitting inside an ordinary quoted string (a note
    or commit message quoting this very example) is never mistaken for a real process substitution (CP4
    round-04 host-alt-standards A1); the real (unmasked) text is always sliced back out of `seg` itself."""
    base = masked if masked is not None else seg
    out = []
    for m in PROC_SUBST_RE.finditer(base):
        toks = seg[m.start(1):m.end(1)].strip().split()
        out += [t.strip("'\"") for t in toks[1:] if not t.startswith("-")]
    return out
ENGINE_CALL_RE = re.compile(r"""^\s*(?:(?:\S*python3?(?:\.\d+)?|py)\s+(?:-\S+\s+)*["']?\S*(ratchet|external_review|ui_review)\.py\b"""
                            r"""|\S*node\s+(?:-\S+\s+)*["']?\S*capture\.mjs\b)""")
NESTED_AGENT_RE = re.compile(r"(^|[\s;&|(/])(claude|gemini|copilot)(?![\w.-])[^;&|\n]*\s(-p|--print|--prompt)\b"
                             r"|(^|[\s;&|(/])codex(?![\w.-])[^;&|\n]*\sexec\b")
SELF_HOOK_RE = re.compile(r"\bhook\b[\s'\",]+(stop|prompt|guard)\b|\bhook-(stop|prompt|guard)\b")
# For a command the shell-word reader can't follow at all (a command substitution, a heredoc, $'...'): only refuse
# it as a hook call when a hook word directly follows `ratchet.py` or a $VAR/${VAR} token, never on the hook words
# alone -- that's what let a plain mention ("hook guard" inside a grep pattern or comment, with an unrelated $(...)
# or "$f" elsewhere in the same unreadable command) get refused before. The separator between `hook` and its
# subcommand also allows a quote or comma, so an argv-style call spelled out as separate quoted words
# (`subprocess.run(['ratchet.py','hook','guard'])`) still counts, not just a literal space.
UNREADABLE_HOOK_RE = re.compile(
    r"(?:\bratchet\.py\b|\$\{?[A-Za-z_]\w*\}?)[^;&|\n]*?(?:" + SELF_HOOK_RE.pattern + ")", re.I)


def _redact_literal_quotes(cmd: str) -> str:
    """For UNREADABLE_HOOK_RE only: blank single-quoted text and the literal parts of double-quoted text (a
    commit message, a note) so a mention saved as data there (`git commit -m 'document ratchet.py hook guard'`)
    isn't mistaken for a call. A live command substitution inside double quotes ($(...) or `...`) is left in
    place, since the shell still runs it. Everything else -- unquoted text, $'...', anything this can't account
    for -- is left exactly as is and still fails safe."""
    out, i, n = list(cmd), 0, len(cmd)
    while i < n:
        c = cmd[i]
        if c == "\\":
            i += 2
        elif c == "'":
            j = cmd.find("'", i + 1)
            if j < 0:
                break
            for k in range(i, j + 1):
                out[k] = "x"
            i = j + 1
        elif c == '"':
            j = i + 1
            while j < n and cmd[j] != '"':
                if cmd[j] == "\\" and j + 1 < n:
                    out[j] = out[j + 1] = "x"
                    j += 2
                    continue
                if cmd[j] == "`" or cmd.startswith("$(", j):
                    if cmd[j] == "`":
                        k = cmd.find("`", j + 1)
                        j = (k + 1) if k >= 0 else n
                    else:
                        depth, k = 1, j + 2
                        while k < n and depth:
                            if cmd[k] == "(":
                                depth += 1
                            elif cmd[k] == ")":
                                depth -= 1
                            k += 1
                        j = k
                    continue
                out[j] = "x"
                j += 1
            i = j + 1 if j < n else j
        else:
            i += 1
    return "".join(out)


ASSIGN_RE = re.compile(r"""(?:^|[\s;&|(])(?:export\s+)?([A-Za-z_]\w*)=("[^"]*"|'[^']*'|[^\s;&|]+)""")
HEREDOC_RE = re.compile(r"""<<-?\s*(['"]?)(\w+)\1([^\n]*)\n.*?\n\s*\2\s*(?=\n|$)""", re.S)


def _unbalanced_subst(val: str) -> bool:
    """True when `val` holds a truncated `$(...)` capture: ASSIGN_RE's unquoted value stops at the first
    whitespace, so an unquoted multi-word substitution (`RUN=$(find .ratchet/runs -maxdepth 1 -type d)`) is
    captured as just `$(find`, an unbalanced fragment. Backticks must also come in pairs."""
    if val.count("`") % 2:
        return True
    depth = 0
    i = 0
    while i < len(val):
        if val[i] == "$" and val[i + 1:i + 2] == "(":
            depth += 1
            i += 2
            continue
        if val[i] == ")" and depth:
            depth -= 1
        i += 1
    return depth != 0


def _expand(cmd: str) -> str:
    """Drop heredoc bodies (they're data, not commands) and expand shell variables assigned in the same command,
    so `RUN=.ratchet/runs/x; echo > $RUN/state.json` is judged as what it really writes. A value that is a
    truncated `$(...)` capture (see `_unbalanced_subst`) is left alone -- `$VAR` stays raw rather than being
    replaced by that garbage fragment -- so `RUN=$(find .ratchet/runs -maxdepth 1 -type d) && cat "$RUN/x"`
    isn't corrupted into an unparseable command; a value with no substitution, or a fully-captured one (no
    internal space, or quoted), still expands normally."""
    cmd = HEREDOC_RE.sub(lambda m: "<<" + m.group(3), cmd)
    for name, val in ASSIGN_RE.findall(cmd):
        val = val.strip("\"'")
        if _unbalanced_subst(val):
            continue
        cmd = re.sub(r"\$\{" + name + r"\}|\$" + name + r"(?![A-Za-z0-9_])", lambda _m: val, cmd)
    return cmd
DIRECTOR_CALL_RE = re.compile(r"""ratchet\.py["']?\s+(?:--root\s+\S+\s+)?(?:director-(?:sign|key|enroll|policy)|integrate|lanes-start)\b""")
# Variables a builder session may read but never set. Each is matched however it is set: VAR=, export/declare/
# typeset/local/readonly/setenv/fish `set -x`, a dict or kwargs entry (python3 -c os.environ / env=...), putenv-style
# calls, or indirectly (the name stored in another variable, or built from pieces, then used by eval, env -S,
# printf -v, ${!v}, sourcing, or an os.environ write). A plain read ($VAR, printenv VAR, grep VAR docs) is fine.
RESERVED_ENV = (
    ("RATCHET_HUMAN_OVERRIDE", "RATCHET GUARD: RATCHET_HUMAN_OVERRIDE is for a person at their own terminal, not "
                               "for agents."),
    ("RATCHET_DIRECTOR_KEY_FILE", "RATCHET GUARD: the director key path (RATCHET_DIRECTOR_KEY_FILE) cannot be "
                                  "redirected by a builder session."),
    ("RATCHET_ROLE", "RATCHET GUARD: RATCHET_ROLE and the director commands are reserved for the director session."),
    ("RATCHET_HOME", "RATCHET GUARD: Ratchet's per-user folder (RATCHET_HOME) is off-limits to builder sessions; it "
                     "cannot be redirected from here."),
)
RESERVED_PIECES_MSG = ("RATCHET GUARD: this command builds one of Ratchet's reserved variable names "
                       "(RATCHET_HUMAN_OVERRIDE, RATCHET_ROLE, RATCHET_HOME, RATCHET_DIRECTOR_KEY_FILE) from pieces "
                       "and sets it indirectly. Builder sessions may read those variables but never set them.")
ENV_INDIRECT_RE = re.compile(
    r"\beval\b|\benv\b[^;&|\n]*\s(-[A-Za-z]*S|--split-string)|\b(export|declare|typeset|local|readonly|setenv)\b"
    r"|\bset\s+-[A-Za-z]*x|\bprintf\s+-v\b|\$\{!|\bsource\s|(^|[;&|(]\s*)\.\s+\S"
    r"|environ\s*\[[^\]]*\]\s*\|?=(?!=)|environ\s*\.\s*(update|setdefault|__setitem__)\b|environ\s*\|?=(?!=)"
    r"|\b(putenv|setenv|Setenv|SetEnvironmentVariable)\s*\(|process\.env\s*\[[^\]]*\]\s*=(?!=)"
    r"|Object\.assign\s*\(\s*process\.env|\bENV\s*\[[^\]]*\]\s*=(?!=)|\$ENV\{[^}]*\}\s*=(?!=)|--(set)?env\b")
ENV_TOKEN_RE = re.compile(r"(?<![\w$])(?<!\$\{)(?<!\$\{!)(?<!\$\{#)RATCHET\w*", re.I)
LEADING_ASSIGN_TOKEN_RE = re.compile(r"^([A-Za-z_]\w*)=")


def _leading_assign_names(seg: str) -> list[str]:
    """Every name in `seg`'s leading assignment sequence: a run of bare `VAR=value` words before the actual
    command, optionally after `export` (one) or `env` and its own no-argument options (`-i`, `-0`, ...). Checks
    the whole sequence, not just the first assignment, so `FOO=1 RATCHET_ROLE=director ls` and
    `env FOO=1 RATCHET_HOME=x ls` are seen whatever program (even a read-only one) follows them."""
    toks = seg.strip().split()
    if toks and toks[0] == "export":
        toks = toks[1:]
    elif toks and toks[0] == "env":
        toks = toks[1:]
        while toks and toks[0].startswith("-"):
            toks.pop(0)
    names = []
    while toks:
        m = LEADING_ASSIGN_TOKEN_RE.match(toks[0])
        if not m:
            break
        names.append(m.group(1))
        toks.pop(0)
    return names
PRINTF_V_RE = re.compile(r"(?:^|\s)-v\b")
# Programs that take their own argument as code, not a note or a message, so that argument's quotes must stay
# visible (`export "NAME=1"`, `env NAME="$(x)"`, `printf -v 'NAME' x`): everything else gets the literal-quote
# redaction below.
EXCEPT_PROGS = {"export", "declare", "typeset", "local", "readonly", "env", "set", "setenv"}
_INTERPRETER_NAMES = r"python[\d.]*|py|node|deno|bun|bash|sh|zsh|dash|ksh|perl|ruby|php|osascript"
# An interpreter given inline code to run, rather than a script file: -c/-e/-lc/a bare "-", nothing else on the
# command line (reads from stdin), a here-string (`<<<`), or the target of a pipe (`echo ... | bash`), the
# inline-code option itself possibly coming after a run of ordinary interpreter options first (`python3 -u -c`,
# `python3 -X dev -c`, `bash -x -c`, `node --no-warnings -e`). A script FILE with its own arguments
# (`python3 -u /path/ratchet.py learn "..."`) is not inline.
INLINE_CODE_RE = re.compile(
    r"(^|[\s;&|(/])(?:" + _INTERPRETER_NAMES + r")\b(?:"
    r"\s+(?:-\S+(?:\s+[^-\s;&|()][^\s;&|()]*)?\s+)*(?:-[A-Za-z]*[ce][A-Za-z]*|-)(?=\s|$)"
    r"|\s+<<<|\s*(?:[;&|)\n]|$))"
    r"|(?<!\|)\|(?!\|)\s*(?:(?:sudo|env|command|exec|time|nice|nohup|timeout|xargs|stdbuf)\s+(?:-\S+\s+)*)?"
    r"(?:" + _INTERPRETER_NAMES + r")\b")
# eval, source or a dot command run whatever text they're given as code; so does `env -S`/`--split-string`.
INLINE_RUNS_RE = re.compile(r"\beval\b|\bsource\s|(^|[;&|(]\s*)\.\s+\S|\benv\b[^;&|\n]*\s(-[A-Za-z]*S|--split-string)")


def _leading_word(seg: str) -> str:
    toks = seg.strip().split()
    return os.path.basename(toks[0]) if toks else ""


def _reserved_env_problem(cmd: str) -> str | None:
    """The guard message when a shell command sets (directly or indirectly) a variable only a person or the
    director may set; None otherwise. The one detector for every reserved variable (plain reads stay allowed,
    and so is a heredoc body that only writes a file -- it's data, not code, unless the same command actually
    feeds it to a shell or an interpreter).

    A reserved name inside a program's own quoted text (a commit message, an echo/printf note, a heredoc note
    saved to a file) sets nothing and is allowed, UNLESS the command also runs code inline -- an interpreter
    given `-c`/`-e`/a bare `-`/nothing/a pipe/a here-string, `eval`, `source`, a dot command, or `env -S` -- in
    which case every word is scanned exactly as written, with no exemption at all, since that quoted text is
    then the code. Known limit: a reserved name quoted in the SAME command as inline interpreter code is refused
    even when it sits in an unrelated argument, since this can't tell the two apart; it fails safe.

    Best-effort: a script written to a file first and run later is not seen here, which is why the engine also
    distrusts these values on its own (terminal code, hook-recorded folder, key file and director role)."""
    heredoc_run = bool(INTERPRETER_RE.search(cmd) and HEREDOC_RE.search(cmd))
    expanded = _expand(cmd)  # heredoc bodies not run as code are dropped here; variable assignments are substituted
    raw_texts = [expanded] + ([cmd] if heredoc_run and cmd != expanded else [])
    indirect = any(ENV_INDIRECT_RE.search(t) for t in raw_texts)
    code = _redact_literal_quotes(expanded)  # literal quoted text blanked; a live $(...) or backtick stays visible
    runs_inline = heredoc_run or bool(INLINE_CODE_RE.search(code) or INLINE_RUNS_RE.search(code))

    if runs_inline:
        seg_pairs = [(seg, seg) for text in raw_texts for seg in _segments(text)]
    else:
        code_segs, raw_segs = _segments(code), _segments(expanded)
        if len(code_segs) != len(raw_segs):  # a quoted delimiter desynced the split: fail safe with raw text
            code_segs = raw_segs
        seg_pairs = list(zip(code_segs, raw_segs))

    for scan_seg, raw_seg in seg_pairs:
        for lead_name in _leading_assign_names(raw_seg):
            full = next((msg for n, msg in RESERVED_ENV if lead_name.upper() == n), None)
            if full:  # a leading reserved assignment (bare or after `env`), anywhere in that leading sequence,
                return full  # is refused whatever follows it, read-only programs included
        prog, sub = _program(raw_seg)
        if prog in READ_ONLY_PROGRAMS:
            continue  # grep/cat/ls/.../ only read; a name there sets nothing
        if not runs_inline:
            leading = _leading_word(raw_seg)
            printf_v = leading == "printf" and bool(PRINTF_V_RE.search(raw_seg))
            if leading in EXCEPT_PROGS or printf_v:
                scan_seg = raw_seg  # this program's own argument is code: keep its quotes visible
        for m in ENV_TOKEN_RE.finditer(scan_seg):
            tok = m.group(0)
            full = next(((n, msg) for n, msg in RESERVED_ENV if tok.upper() == n), None)
            if full:
                name, msg = full
                after = scan_seg[m.end():]
                before = scan_seg[:m.start()]
                if re.match(r"""['"\]}]*\s*\+?=(?!=)|['"]\s*:""", after) or \
                        re.search(r"""(?:^|[\s;&|(])[A-Za-z_]\w*=\s*['"]?$""", before) or \
                        re.search(r"\b(export|declare|typeset|local|readonly|setenv)\b|\bset\s+-[A-Za-z]*x",
                                  before) or \
                        re.search(r"\b(putenv|setenv|Setenv|SetEnvironmentVariable|setdefault|update|"
                                  r"__setitem__)\s*\(\s*['\"]?$", before) or indirect:
                    return msg
            elif tok.upper() != "RATCHET" and tok.startswith("RATCHET") and indirect and \
                    any(n.startswith(tok) and n != tok for n, _m in RESERVED_ENV):
                return RESERVED_PIECES_MSG
    return None


DANGEROUS_GIT_RE = re.compile(r"\bgit\s+(clean\b[^;&|\n]*\s-[a-zA-Z]*[xX]|stash\b[^;&|\n]*(\s--all\b|\s-a\b))")


def _segments(cmd: str) -> list[str]:
    """`cmd` split on top-level `;`/`&&`/`||`/`|`/newline -- never inside a single- or double-quoted span, the
    same quote masking `_mask_quoted_seps` gives the fast path, so a `;` inside a python one-liner's own code
    or a `|` inside a jq filter is never mistaken for a statement boundary and split away from the mention it
    sits next to (CP3 round-01: a python -c argument's own `;` used to split `pathlib.Path(x).open('w')` into
    its own segment, which then read as a bare `VAR=value` shell assignment with no spaces in it and was
    skipped by `_guard_shell`'s own-nothing-to-check rule, missing the `.ratchet` mention inside it entirely).
    Falls back to the old, quote-blind split only when `_mask_quoted_seps` gives up (a double-quoted span
    holding a live $(...)/backtick -- see its own docstring); every caller already treats more segments as
    fail-safe, never fewer, so that fallback never allows something this quote-aware split would have caught."""
    masked = _mask_quoted_seps(cmd)
    if masked is None:
        return [p for p in re.split(r"\|\||&&|;|\||\n", cmd) if p.strip()]
    parts, pos = [], 0
    for sm in re.finditer(r"\|\||&&|;|\||\n", masked):
        parts.append(cmd[pos:sm.start()])
        pos = sm.end()
    parts.append(cmd[pos:])
    return [p for p in parts if p.strip()]


def _program(seg: str) -> tuple[str, str]:
    toks = seg.strip().split()
    while toks and re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", toks[0]):  # leading VAR=value
        toks.pop(0)
    while toks and toks[0] in ("sudo", "env", "command", "exec", "time", "nice", "nohup"):
        toks.pop(0)
    if not toks:
        return "", ""
    return os.path.basename(toks[0]), (toks[1] if len(toks) > 1 else "")


def _ratchet_rel(path: str, cwd: str) -> str | None:
    """Path relative to the nearest .ratchet/ it lies in (case-insensitive), or None if it isn't inside one."""
    full = os.path.normpath(os.path.join(cwd, os.path.expanduser(path))).replace("\\", "/")
    m = re.search(r"(^|[/=:])\.ratchet(/|$)(.*)$", full, re.I)
    if not m:
        return None
    return m.group(3)


# Review files that only their reviewer may write (checked where the host says which sub-agent is acting: Claude
# Code puts agent_type on every tool call a sub-agent makes). An empty owner set means "only the script writes it".
REVIEW_OWNERS = [
    (ADV_REVIEW_RE, {"ratchet-adversary"}),  # one pattern with the writer record (_note_review_writer)
    # a UI round's per-role reviews (the guard also records their writer; named groups as in ADV_REVIEW_RE)
    (re.compile(r"^runs/(?P<slug>[^/]+)/reviews/(?P<cp>[^/]+)/round-(?P<n>\d+)/(?P<name>visual\.json)$", re.I),
     {"ratchet-visual-reviewer"}),
    (re.compile(r"^runs/(?P<slug>[^/]+)/reviews/(?P<cp>[^/]+)/round-(?P<n>\d+)/(?P<name>behavior\.json)$", re.I),
     {"ratchet-behavior-reviewer"}),
    (re.compile(r"^runs/[^/]+/reviews/[^/]+/round-\d+/combined\.json$", re.I), set()),
    (re.compile(r"^runs/[^/]+/reviews/[^/]+/capture[^/]*/manifest\.json$", re.I), set()),
]
INTERPRETER_RE = re.compile(r"(^|[\s;&|(/])(python[\d.]*|py|node|deno|bun|bash|sh|zsh|dash|ksh|perl|ruby|php|osascript)(?=\s|$)")


def _owner_problem(path: str, cwd: str, who: dict | None) -> str | None:
    """Why this acting agent may not write this review file, or None."""
    rel = _ratchet_rel(path, cwd)
    if not rel or not who or not who.get("enforce"):
        return None
    for rx, owners in REVIEW_OWNERS:
        if rx.match(rel):
            actor = (who.get("agent_type") or "").split(":")[-1]
            if actor and actor in owners:
                return None
            if not owners:
                return (f"RATCHET GUARD: {rel} is written by ui_review.py only. Run the script (combine) instead of "
                        "writing the file yourself.")
            return (f"RATCHET GUARD: {rel} is a reviewer's own output. Only a {' or '.join(sorted(owners))} sub-agent "
                    "may write it: launch that reviewer and let it write its file. Never write or edit a review "
                    "yourself, not even to copy what the reviewer said.")
    return None


WRITE_CODE_RE = re.compile(r"""open\([^)]*,\s*['"][wax]|write_text\(|write_bytes\(|writeFileSync|appendFileSync|\.write\(""")
ORCH_EDIT_MSG = ("RATCHET GUARD: during the build, project files are changed by Ratchet's sub-agents (implementer, fixer, "
                 "test writer, design system), not by the orchestrator, so that every change goes through the gates by "
                 "the role that owns it. Spawn ratchet-implementer (code or UI fixes), ratchet-fixer (review findings) "
                 "or ratchet-design-system (DESIGN.md) with the change you want. Files under .ratchet/ that you own "
                 "(checkpoints, capture specs, reference) are fine. If the user asked for something unrelated to the build, "
                 "pause the run first (ratchet.py pause), make the change, then resume.")


def _in_project_outside_ratchet(path: str, cwd: str, root: Path) -> bool:
    full = Path(os.path.normpath(os.path.join(cwd, os.path.expanduser(path))))
    try:
        full.relative_to(root.resolve())
    except ValueError:
        return False  # /tmp, /dev/null, another folder: not the project
    return _ratchet_rel(str(full), cwd) is None


def _orchestrator_edit(n: dict, root: Path) -> bool:
    """Is the main session (not a sub-agent) about to change a project file outside .ratchet/?"""
    cwd = n["cwd"]
    if n["kind"] == "write":
        return any(_in_project_outside_ratchet(p, cwd, root) for p in n["paths"])
    if n["kind"] != "shell" or not n["command"]:
        return False
    raw = n["command"]
    if INTERPRETER_RE.search(raw):
        for m in HEREDOC_RE.finditer(raw):
            body = m.group(0)
            if WRITE_CODE_RE.search(body) and not RATCHET_TOKEN_RE.search(body):
                return True
    cmd = _expand(raw)
    for seg in _segments(cmd):
        if ENGINE_CALL_RE.match(seg):
            continue
        targets = [t for t in REDIRECT_RE.findall(seg) if not t.startswith("&")]
        prog, _ = _program(seg)
        if prog == "sed" and re.search(r"\s-[a-zA-Z]*i", seg):
            targets += [t for t in seg.split()[1:] if not t.startswith("-") and ("/" in t or "." in t)][-1:]
        if prog == "tee":
            targets += [t for t in seg.split()[1:] if not t.startswith("-")]
        if any(_in_project_outside_ratchet(t.strip("'\""), cwd, root) for t in targets):
            return True
    return False


def _write_allowed(path: str, cwd: str) -> bool:
    rel = _ratchet_rel(path, cwd)
    return rel is None or bool(rel and ALLOWED_RATCHET_WRITES.match(rel))


_WRAPPERS = {"sudo", "env", "command", "exec", "time", "nice", "nohup", "timeout", "xargs", "stdbuf"}
_SHELLS = {"bash", "sh", "zsh", "dash", "ksh"}
_HOOK_SUBCOMMANDS = ("hook", "hook-stop", "hook-prompt", "hook-guard")


def _calls_own_hook(cmd: str, depth: int = 0) -> bool:
    """True when `cmd` really runs `ratchet.py hook ...` (directly, through python, a wrapper such as env or
    timeout, an unknown $PROGRAM, `bash -c` or eval). Text that only mentions a hook (a grep pattern, an echo, a
    commit message, a comment) is not a call. A command the shell-word reader can't follow (a command substitution,
    a heredoc, $'...') is blocked only when a hook word directly follows `ratchet.py` or a `$VAR`/`${VAR}` token in
    it, not when the hook words merely appear somewhere else (a grep pattern inside it, say); a mention saved as
    literal data in a single-quoted argument, or the literal part of a double-quoted one (a commit message, a
    note), doesn't count even when an unrelated command substitution sits elsewhere in the same command. What
    can't be read this far still fails safe."""
    words = _shell_words(cmd)
    if words is None:
        # Same rule as _reserved_env_problem: quoted text is data unless the command also runs inline code
        # (an interpreter given -c/-e/a pipe/here-string, eval, source, a dot command, env -S); then every word,
        # quoted or not, is scanned, since that quoted text is the code actually being run.
        redacted = _redact_literal_quotes(cmd)
        runs_inline = bool(INLINE_CODE_RE.search(redacted) or INLINE_RUNS_RE.search(redacted))
        return bool(UNREADABLE_HOOK_RE.search(cmd if runs_inline else redacted))
    for w in _simple_commands(words):
        while w and _ASSIGNMENT_RE.match(w[0]):
            w = w[1:]
        while w and Path(w[0]).name in _WRAPPERS:
            w = w[1:]
            while w and (w[0].startswith("-") or _ASSIGNMENT_RE.match(w[0]) or re.fullmatch(r"[0-9.]+[smhd]?", w[0])):
                w = w[1:]
        if not w:
            continue
        prog = Path(w[0]).name
        if prog == "eval" or prog in _SHELLS:
            code = [" ".join(w[1:])] if prog == "eval" else \
                [w[i + 1] for i in range(1, len(w) - 1) if re.fullmatch(r"-[a-z]*c[a-z]*", w[i])]
            if depth < 3 and any(_calls_own_hook(c, depth + 1) for c in code):
                return True
            continue
        if re.fullmatch(r"python[0-9.]*|py", prog):
            w = w[1:]
            while w and w[0].startswith("-"):
                w = w[1:]
            if not w:
                continue
            prog = Path(w[0]).name
        if (prog == "ratchet.py" or "$" in w[0]) and _engine_subcommand(w[1:]) in _HOOK_SUBCOMMANDS:
            return True
    return False


# CP2: a narrow fast path for shell commands this guard can PROVE touch nothing but reads -- cat/grep/jq-style
# filters, cd/pushd/popd (tracked so a later ordinary command in the same line after `cd .ratchet/...` isn't
# refused), and a short list of other programs only when used in a form that cannot write (sort without -o,
# uniq with at most one file, sed/awk without their in-place flag, find without a write action, xargs running
# one of these programs, cp with no destination-directory flag). Anything this can't prove read-only (an
# unrecognised program, a write flag, a redirect it can't resolve) returns False so the caller falls back to
# the slower, fail-safe mention check below unchanged -- this never WIDENS what that check refuses, it only
# narrows how often an agent has to detour around it for an ordinary read.
# One allow-list for both paths: every program READ_ONLY_PROGRAMS already trusts (rg, less, more, egrep,
# fgrep, file, cmp, md5sum, sha1sum, sha256sum, tree, du, ...) plus the few extra programs this fast path can
# only prove read-only by checking their OWN argument shape.
RO_TABLE = READ_ONLY_PROGRAMS | {"cut", "tr", "echo", "printf", "test", "[", "read", "basename", "dirname",
                                  "realpath", "sort", "uniq", "awk", "sed", "find", "xargs", "cp"}
# sort/uniq/awk/sed/find/xargs/cp only prove read-only by checking their OWN argument shape (an -o, a file
# count, an -i flag, a write action, a destination argument); run as xargs's inner program, that shape isn't
# the whole story -- xargs appends more arguments from stdin that this guard can't see, which could change
# what they write to. Only a program whose read-only-ness never depends on argument shape at all is safe there.
RO_XARGS_INNER_OK = RO_TABLE - {"sort", "uniq", "awk", "sed", "find", "xargs", "cp"}
RO_KEYWORDS = {"while", "until", "if", "then", "else", "elif", "do", "done", "fi", "!", "{", "}"}
RO_WRAP = {"sudo", "env", "command", "exec", "time", "nice", "nohup"}
RO_FIND_WRITE_RE = re.compile(r"(?:^|\s)-(?:delete|fprint0?|fprintf|fls|ok|okdir)\b")
RO_FIND_EXEC_RE = re.compile(r"(?:^|\s)-(?:exec|execdir)\s+(\S+)")
RO_SEP_RE = re.compile(r"\$\(|<\(|>\(|`|\(|\)|(?<!\\);|&&|\|\||\||\n|&")
GIT_CMD_START_RE = re.compile(r"\bgit\s+(?:commit|tag|notes|merge)\b")
# -m/--message, or a combined short-flag cluster ending in m (-am, -qm, -sm, ...): git commit takes several
# single-letter flags (-a, -q, -s, ...) that are routinely combined with -m on one dash. The negative
# lookbehind keeps this from matching the second dash of --message as if it were its own "-m" cluster.
# \s* is part of the match so its end lands right on a following quote, the same way the old single-flag
# regex did.
GIT_MSG_FLAG_RE = re.compile(r"(?:--message=?|(?<!-)-[A-Za-z]*m\b)\s*")
# sed: only -n (optionally combined with -E/-r) and a single print-only address script -- no write command
# (w/W/e/r), no -i/--in-place/-f/-e beyond that.
RO_SED_OPT_RE = re.compile(r"^-[nEr]+$")
RO_SED_PRINT_RE = re.compile(r"^(\d+|\$|/[^/]*/)(,(\d+|\$|/[^/]*/))?p$")
# awk: a script with no redirect, pipe or process/stream side effect.
RO_AWK_BAD_SCRIPT_RE = re.compile(r">|\||\bsystem\b|\bgetline\b|\bclose\b|\bfflush\b")


def _git_stmt_end(cmd: str, start: int) -> int:
    """End offset of the git statement beginning at `start`: the next ;, &, | or newline that isn't inside a
    single- or double-quoted span, or len(cmd). Keeps a later -m's search from running past this git call
    into unrelated, later commands."""
    i, n = start, len(cmd)
    while i < n:
        c = cmd[i]
        if c == "\\":
            i += 2
        elif c == "'":
            j = cmd.find("'", i + 1)
            i = (j + 1) if j >= 0 else n
        elif c == '"':
            j = i + 1
            while j < n and cmd[j] != '"':
                j += 2 if cmd[j] == "\\" and j + 1 < n else 1
            i = (j + 1) if j < n else n
        elif c in ";&|\n":
            return i
        else:
            i += 1
    return n


def _blank_commit_messages(cmd: str) -> str:
    """Blank the quoted value of every -m/--message (and combined short flag ending in m, like -am) on a git
    commit/tag/notes/merge command (quote-aware), on the whole command before any later split -- so a
    message that merely names a run path (`git commit -m 'guard: block writes to .ratchet/runs/x/state.json'`,
    or a two-part `-m subject -m body`, or `-am`) is data, not a path mention, and the message's own
    punctuation (;, &&, |) never desyncs the segmentation that follows. A value holding a live command
    substitution ($(...) or a backtick) is left visible, since the shell still runs it."""
    out, n = list(cmd), len(cmd)
    for gm in GIT_CMD_START_RE.finditer(cmd):
        end = _git_stmt_end(cmd, gm.end())
        pos = gm.end()
        while pos < end:
            fm = GIT_MSG_FLAG_RE.search(cmd, pos, end)
            if not fm:
                break
            j = fm.end()
            if j >= end or cmd[j] not in "'\"":
                pos = fm.end() + 1
                continue
            if cmd[j] == "'":
                k = cmd.find("'", j + 1, end)
                if k < 0:
                    pos = j + 1
                    continue
                for p in range(j, k + 1):
                    out[p] = "x"
                pos = k + 1
                continue
            k, live = j + 1, False
            while k < end and cmd[k] != '"':
                if cmd[k] == "\\" and k + 1 < end:
                    k += 2
                    continue
                if cmd[k] == "`" or cmd.startswith("$(", k):
                    live = True
                    if cmd[k] == "`":
                        k2 = cmd.find("`", k + 1, end)
                        k = (k2 + 1) if k2 >= 0 else end
                    else:
                        depth, k2 = 1, k + 2
                        while k2 < end and depth:
                            if cmd[k2] == "(":
                                depth += 1
                            elif cmd[k2] == ")":
                                depth -= 1
                            k2 += 1
                        k = k2
                    continue
                k += 1
            if not live and k < end:
                for p in range(j, k + 1):
                    out[p] = "x"
            pos = (k + 1) if k < end else end
    return "".join(out)


def _ro_bad_target(t: str, cwd: str, cmd_unsafe: bool) -> bool:
    """True when a redirect or cp destination argument `t` can't be proven to land outside .ratchet/: empty,
    a live substitution ($ or a backtick), a relative path while `cmd_unsafe` is set (the session cwd is
    inside .ratchet/, or this command carries a cd/pushd/popd `_cmd_only_safe_cds` can't fully vouch for --
    see its own comment), or a path that does resolve into .ratchet/."""
    t = t.strip("'\"")
    if not t or "$" in t or "`" in t:
        return True
    if not os.path.isabs(os.path.expanduser(t)) and cmd_unsafe:
        return True
    return _ratchet_rel(t, cwd) is not None


def _ro_strip_words(words: list) -> list:
    """`words` with any leading shell keyword, `VAR=value` assignment or wrapper word (sudo, env, ...)
    removed, the same stripping both `_ro_prog_ok` and `_provably_read_only`'s own cd-tracking need."""
    while words and words[0] in RO_KEYWORDS:
        words = words[1:]
    while words and re.match(r"^[A-Za-z_]\w*=", words[0]):
        words = words[1:]
    while words and words[0] in RO_WRAP:
        words = words[1:]
    return words


def _ro_awk_script(raw: str) -> str | None:
    """awk's own script argument (the first non -F-option bare word after its own name), read with the
    proper shell-word tokenizer (`_shell_words`/`_simple_commands`) rather than the plain whitespace split
    this fast path otherwise works from, so a script that itself holds whitespace
    (`'BEGIN{f=".ratchet/x"; print "{}" > f}'`) comes back whole and unmangled -- never split on that
    internal whitespace, and never first corrupted by the generic, quote-blind redirect-removal regex this
    module's per-piece word-building applies before this would otherwise see it. None when `raw` can't be
    read this way (a command substitution, an unbalanced quote) or its leading program isn't awk."""
    words = _shell_words(raw)
    if words is None:
        return None
    cmds = _simple_commands(words)
    if not cmds or not cmds[0]:
        return None
    toks = _ro_strip_words(cmds[0])
    if not toks or os.path.basename(toks[0]) != "awk":
        return None
    args, i = toks[1:], 0
    while i < len(args):
        a = args[i]
        if a == "-F":
            i += 2
            continue
        if re.match(r"^-F.+$", a):
            i += 1
            continue
        if a.startswith("-"):
            i += 1
            continue
        return a
    return None


def _uniq_operands(args: list) -> list:
    """uniq's own positional operands from `args` (its arguments, program name already removed): a bare
    `-` (the conventional stdin/stdout placeholder) counts as one even though it starts with "-"; -f/-s/-w
    (skip-fields/skip-chars/check-chars) and their attached/`=`/separate numeric values are skipped, not
    counted. Shared by the fast path's `_ro_prog_ok` and the loop check's `_loop_body_stage_writes` so both
    treat uniq's arguments the same way (CP4 round-02 X2/A2/C3: a second, drifted copy had dropped the bare
    `-` fix in the loop check)."""
    bare, i = [], 0
    while i < len(args):
        a = args[i]
        if a in ("-f", "-s", "-w"):
            i += 2
        elif re.match(r"^--(skip-fields|skip-chars|check-chars)=", a):
            i += 1
        elif re.fullmatch(r"--(skip-fields|skip-chars|check-chars)", a):
            i += 2
        else:
            if not a.startswith("-") or a == "-":
                bare.append(a)
            i += 1
    return bare


_REDIR_OP_RE = re.compile(r"^(?:\d*|&)(?:<<<|<<|<|>>|>\||>)$")
_REDIR_ATTACHED_RE = re.compile(r"^(?:\d*|&)(?:<<<|<<|<|>>|>\||>)\S+$")


def _strip_redirect_args(args: list) -> list:
    """`args` (already whitespace-split shell words) with every input/output redirection removed: a bare
    operator token (`<`, `<<`, `<<<`, `>`, `>>`, `>|`, with an optional leading fd digits or `&`) together
    with the word right after it, and an operator glued directly onto its own target in one token
    (`<file`, `2>file`). Without this, a redirect sharing a statement with a program's own operands (`uniq
    - "$f" < /tmp/new.json`) gets its target miscounted as one of that program's positional arguments (CP4
    round-02 A2: `<` was being read as uniq's second operand instead of `"$f"`)."""
    out, i = [], 0
    while i < len(args):
        a = args[i]
        if _REDIR_OP_RE.match(a):
            i += 2
            continue
        if _REDIR_ATTACHED_RE.match(a):
            i += 1
            continue
        out.append(a)
        i += 1
    return out


def _ro_prog_ok(words: list, cwd: str, maybe_inside: bool, has_subst: bool = False, raw: str | None = None) -> bool:
    """Is this one piece's leading program (after stripping shell keywords, a leading VAR=, and a wrapper
    word) one this fast path can prove reads only, used in a form with no write flag or unresolved
    destination. `raw` (when given) is this piece's own unaltered text, used only to re-derive awk's script
    argument properly (see `_ro_awk_script`)."""
    words = _ro_strip_words(words)
    if not words:
        return True
    if words[0] == "for":
        return True  # `for X in LIST` runs nothing by itself; LIST is never executed here
    p, args = os.path.basename(words[0]), words[1:]
    s = " ".join(args)
    if p not in RO_TABLE:
        return False
    if p == "sort":
        return not any(re.match(r"^-[A-Za-z]*o|^--o", a) for a in args)
    if p == "uniq":
        # CP4: a bare `-` (the conventional stdin/stdout placeholder) counts as an operand too, even though
        # it starts with "-" -- without this, `uniq - <target>` looked like a single-operand (read-only)
        # call. `_uniq_operands` is shared with the loop check so both count uniq's arguments the same way.
        return len(_uniq_operands(args)) <= 1
    if p == "awk":
        # only -F<sep> (attached, or as its own argument with the separator in the next one); no -i/-f/-v/
        # --inplace or any other option; no bare `var=value` operand; the script itself (the first bare
        # argument) must hold no redirect, pipe or process/stream side effect.
        i, parts = 0, []
        while i < len(args):
            a = args[i]
            if a == "-F":
                i += 2
                continue
            if re.match(r"^-F.+$", a):
                i += 1
                continue
            if a.startswith("-"):
                return False
            parts.append(a)
            i += 1
        if not parts:
            return False
        script = parts[0].strip("\"'")
        if any(re.match(r"^[A-Za-z_]\w*=", a) for a in parts[1:]):
            return False
        if raw is not None:
            full_script = _ro_awk_script(raw)
            if full_script is not None:
                script = full_script
        return not RO_AWK_BAD_SCRIPT_RE.search(script)
    if p == "sed":
        # only -n (optionally combined with -E/-r) and a single print-only address script; no -i/--in-place/
        # -f/-e beyond that, no w/W/e/r commands.
        opts = [a for a in args if a.startswith("-")]
        bare = [a for a in args if not a.startswith("-")]
        if not opts or "n" not in "".join(opts) or not all(RO_SED_OPT_RE.match(o) for o in opts):
            return False
        if not bare:
            return False
        return bool(RO_SED_PRINT_RE.match(bare[0].strip("\"'")))
    if p == "find":
        if RO_FIND_WRITE_RE.search(" " + s):
            return False
        return all(os.path.basename(m.group(1)) in RO_XARGS_INNER_OK
                   for m in RO_FIND_EXEC_RE.finditer(" " + s))
    if p == "xargs":
        i = 0
        while i < len(args) and args[i].startswith("-"):
            i += 2 if args[i] in ("-I", "-n", "-P", "-L", "-s", "-d", "-a", "-E") else 1
        if i >= len(args):
            return True
        return os.path.basename(args[i]) in RO_XARGS_INNER_OK and _ro_prog_ok(args[i:], cwd, maybe_inside, has_subst)
    if p == "cp":
        # only a plain `cp SOURCE DEST`: no options at all, no command substitution anywhere in the command,
        # and DEST a literal absolute path outside .ratchet/.
        if has_subst or any(a.startswith("-") for a in args) or len(args) != 2:
            return False
        dest = args[1].strip("\"'")
        return os.path.isabs(os.path.expanduser(dest)) and not _ro_bad_target(dest, cwd, maybe_inside)
    return True


def _mask_quoted_seps(s: str) -> str | None:
    """`s` with every | ; & ( ) ` $ > and newline that sits inside a single-quoted span, or inside a
    double-quoted span that holds no live substitution, replaced by 'x', so the statement split and redirect
    scan below can keep using plain regexes without themselves being quote-aware, yet a quoted pipe,
    ampersand, `>` (a jq filter, a grep alternation, an awk -F separator, a `>` inside a single-quoted
    awk/sed script) or a newline (a python -c argument's own code spread over several lines, CP3 round-02) is
    never mistaken for a statement separator or a real redirect. Length and every other character's position
    are unchanged, so offsets found in the result line up exactly with `s` and the real (unmasked) text can
    still be sliced out of `s` itself.

    A double-quoted span may itself hold a live `$(...)` or backtick substitution, which the shell still runs
    at the time this statement executes -- its own `|`/`;`/`&`/`>` are real shell syntax for that inner
    command, not inert quoted text, so masking them (or just leaving them be and risking a false split) would
    either hide a real write or desync the split. Returns None for the whole string in that case, so the
    caller gives up on the fast path and falls back to the slow, fail-safe mention check instead of guessing."""
    out, i, n = list(s), 0, len(s)
    while i < n:
        c = s[i]
        if c == "\\":
            i += 2
            continue
        if c == "'":
            j = i + 1
            while j < n and s[j] != "'":
                if s[j] in "|;&()`$>\n":
                    out[j] = "x"
                j += 1
            i = j + 1
        elif c == '"':
            j, has_live = i + 1, False
            while j < n and s[j] != '"':
                if s[j] == "\\" and j + 1 < n:
                    # CP4 round-05 B1: a backslash-escaped separator (`\|` in a grep/sed BRE alternation) is
                    # still inert quoted text, not live shell syntax, so mask BOTH the backslash and the
                    # escaped character itself (not skip past them unmasked) when the escaped character is
                    # one of the separator set -- otherwise a double-quoted `"a\|b"` left its own `|`
                    # unmasked and got split like a real pipe.
                    if s[j + 1] in "|;&()`$>\n":
                        out[j] = "x"
                        out[j + 1] = "x"
                    j += 2
                    continue
                if s[j] == "`" or s.startswith("$(", j):
                    has_live = True
                if s[j] in "|;&()`$>\n":
                    out[j] = "x"
                j += 1
            if has_live:
                return None
            i = j + 1
        else:
            i += 1
    return "".join(out)


def _mask_quoted_text(s: str) -> str | None:
    """Like `_mask_quoted_seps`, but blanks EVERY character inside a quoted span (not only the separator set),
    so a whole-word search for a shell keyword -- `_loop_write_problem`'s search for the loop-closing `done`
    -- never matches that word sitting inside a quoted jq filter or echoed string (CP4 round-04 A1: `jq
    '.phase="done"' "$f"` or `echo "all done" > "$f"` used to end the loop body early, right at the quoted
    `done`, before the real write that follows it). Same length/position contract and the same None-on-live-
    double-quoted-substitution escape as `_mask_quoted_seps`; see that function's own docstring."""
    out, i, n = list(s), 0, len(s)
    while i < n:
        c = s[i]
        if c == "\\":
            i += 2
            continue
        if c == "'":
            j = i + 1
            while j < n and s[j] != "'":
                out[j] = "x"
                j += 1
            i = j + 1
        elif c == '"':
            j, has_live = i + 1, False
            while j < n and s[j] != '"':
                if s[j] == "\\" and j + 1 < n:
                    # CP4 round-05 B1: blank the escaped pair too (this function blanks everything inside
                    # quotes anyway), matching `_mask_quoted_seps`'s own fix for the same escape-skip gap.
                    out[j] = "x"
                    out[j + 1] = "x"
                    j += 2
                    continue
                if s[j] == "`" or s.startswith("$(", j):
                    has_live = True
                out[j] = "x"
                j += 1
            if has_live:
                return None
            i = j + 1
        else:
            i += 1
    return "".join(out)


def _mask_quoted_text_coarse(s: str) -> str:
    """Like `_mask_quoted_text`, but never gives up: a double-quoted span that holds a live `$(...)`/backtick
    substitution is blanked right along with the rest of that span's characters instead of making the whole
    call return None. Same length/position contract (every character inside a single- or double-quoted span
    becomes 'x', the quote characters themselves stay put) -- this is the coarse stand-in the loop checks
    (`_normalize_loop_seps`, `_loop_write_problem`'s own loop-head match) fall back to precisely when
    `_mask_quoted_text`/`_mask_quoted_seps` bail on that live substitution, so a loop whose body merely
    stamps a `$(date)`/`$(basename ...)` into its own output is still structurally recognised as a loop (CP4
    round-06 A1/C1/X1/X2: the old `_loop_write_problem_fallback` gave up on this entirely and scanned raw,
    unmasked text for writer-program words instead, which both missed real writes like a quoted-substitution
    `sed -i`/`uniq`/python write and flagged quoted DATA -- a writer-program word sitting inside a grep
    pattern or echoed string -- as if it were a command)."""
    out, i, n = list(s), 0, len(s)
    while i < n:
        c = s[i]
        if c == "\\":
            i += 2
            continue
        if c == "'":
            j = i + 1
            while j < n and s[j] != "'":
                out[j] = "x"
                j += 1
            i = j + 1
        elif c == '"':
            j = i + 1
            while j < n and s[j] != '"':
                if s[j] == "\\" and j + 1 < n:
                    out[j] = "x"
                    out[j + 1] = "x"
                    j += 2
                    continue
                out[j] = "x"
                j += 1
            i = j + 1
        else:
            i += 1
    return "".join(out)


def _strip_group_prefix(tok: str) -> str:
    """`tok` with any leading subshell/grouping/negation characters (`(`, `{`, `!`) removed, so the common
    `(cd DIR && ...)` subshell idiom's first word reads as `cd`, not `(cd`. Shared by every cd/pushd/popd
    tracker below (CP4 round-04 A3: all of them missed this form, a regression from main)."""
    return tok.lstrip("({!")


def _cmd_only_safe_cds(cmd: str) -> bool:
    """True when `cmd` carries no cd/pushd/popd this fast path can't fully account for: no popd at all (its
    target directory depends on an earlier pushd this function doesn't track), and every cd/pushd target is a
    literal path (no $, backtick, bare `-`, or option) that, once `~` is expanded, is absolute and resolves
    outside .ratchet/. Vacuously true when `cmd` has no cd/pushd/popd at all. A single all-or-nothing fact
    about the whole command, not a position-by-position walk: CP2 round-06 found that walking cd state and
    judging each redirect against only the FINAL state let `cd .ratchet/runs/hk && echo '{}' > state.json; cd
    /tmp` through, since the trailing `cd /tmp` cleared the flag before the redirect was ever judged. Any cd
    this function can't vouch for this way makes the whole command fall back to the slow, fail-safe path."""
    for seg in _segments(cmd):
        toks = _ro_strip_words(seg.strip().split())
        if toks:
            toks[0] = _strip_group_prefix(toks[0])
        if not toks or toks[0] not in ("cd", "pushd", "popd"):
            continue
        if toks[0] == "popd":
            return False
        target = toks[1].strip("'\"") if len(toks) > 1 else ""
        if not target or target == "-" or target.startswith("-") or "$" in target or "`" in target:
            return False
        target = os.path.expanduser(target)
        if not os.path.isabs(target) or _ratchet_rel(target, "") is not None:
            return False
    return True


# CP3: python/python3 is a reader too, but only in a few forms this fast path can prove never write -- a
# `-c` one-liner, a bare-interpreter heredoc, or `-m json.tool` with at most one input file and no output
# file -- and only when the code/body itself holds none of PY_WRITE_MARKER_RE's markers and no write-mode
# open call. A write-mode open call is judged by one simple, fail-safe, whole-code rule rather than by
# parsing any call's argument positions (round-03 found that position-aware parsing missed a mode sitting
# next to a nested call, such as `open(Path('.ratchet/runs/x/state.json'), 'w')`, because excluding
# parentheses from the matched arguments text also excluded the nested call's own parentheses, hiding the
# mode that followed them): if the code contains an open-style call opener at all (`open(`, `.open(`,
# `io.open(`, `codecs.open(`, `os.open(`, `os.fdopen(`) and anywhere in the code there is a quoted string
# literal (a single or double quote, an optional one- or two-character b/r/f prefix, closed by the same
# quote) whose whole content is made only of the characters r, w, a, x, b, t and + and holds at least one w,
# a, x or +, the code counts as a write -- fail-safe, so a mode-shaped literal is enough by itself, even one
# that is only assigned to a variable rather than proven to be that particular call's own mode argument. A
# `mode=` keyword followed by something other than a quote (a variable, an expression) counts as a write
# too, the same fail-safe way. A read with no mode, or with a mode literal made only of r/b/t characters
# (`'r'`, `'rb'`, `'rt'`), still passes. This intentionally no longer tracks which argument of which call a
# mode literal belongs to (the argument-splitting code that did this is gone with it): a non-literal,
# non-`mode=` positional mode argument (`open(file, some_var)`) is not specially caught here any more and
# relies on this same literal/opener rule and on PY_WRITE_MARKER_RE instead -- see CP3 round-03's fixes.md
# for why this is the accepted, documented trade for closing the nested-call gap with the smallest change.
# Anything this rule doesn't resolve as a write simply isn't flagged by it, which sends the whole command to
# the slow, fail-safe path below exactly as before this checkpoint -- never widening what that path refuses.
PY_PROG_RE = re.compile(r"^python[0-9.]*$|^py$")
PY_SAFE_FLAGS = {"-B", "-E", "-I", "-s", "-u"}
PY_HEREDOC_PREFIX_RE = re.compile(r"^(?:\S*/)?(?:python[0-9.]*|py)(?:\s*-)?$")
PY_WRITE_MARKER_RE = re.compile(
    r"\.write\(|\.writelines\(|write_text\(|write_bytes\(|json\.dump\(|pickle\.dump|"
    r"os\.remove|os\.unlink|os\.rename|os\.replace|os\.rmdir|os\.removedirs|os\.makedirs|"
    r"os\.mkdir|os\.truncate|os\.system|os\.popen|os\.exec|os\.spawn|os\.fdopen|shutil\.|subprocess|"
    r"\.touch\(|\.unlink\(|\.rename\(|\.replace\(|\.mkdir\(|\.rmdir\(|\.symlink_to\(|\.hardlink_to\(|"
    r"\.writerow\(|\.writerows\(|"
    r"\bexec\(|\beval\(|__import__|importlib|getattr\(\s*os\b|sys\.stdout\s*=|\bfile\s*=|"
    r"fileinput|inplace\s*=|os\.chmod|\.chmod\(|os\.(?:sym)?link\(|"
    r"O_(?:WRONLY|RDWR|TRUNC|CREAT|APPEND)"
)
PY_OPEN_CALL_OPENER_RE = re.compile(
    r"(?<![\w.])open\(|\bio\.open\(|\bcodecs\.open\(|\bos\.open\(|\bos\.fdopen\(|\.open\("
)
PY_MODE_LITERAL_RE = re.compile(r"""(?<![\w])[bBrRfF]{0,2}(['"])([rwaxbt+]+)\1""")
PY_MODE_KWARG_NONLITERAL_RE = re.compile(r"""mode\s*=\s*(?!['"])""")
# round-05: PY_WRITE_MARKER_RE only matched dotted uses (`os.remove`, `shutil.`, ...), so importing one of
# these modules under a plain or aliased name and calling it undotted (`from os import remove; remove(...)`,
# `import os as o; o.remove(...)`) passed this fast path. These two checks close that class, staying a text
# deny-list and fail-safe like the rest of this file. PY_FROM_IMPORT_RE finds every `from <module> import
# <names>` clause naming one of os/os.path/shutil/subprocess/pathlib/io/fileinput/tempfile; is_write below
# treats each as a write except the four read-only shapes named in CP3 round-05's finding: `from os import
# path`, `from os.path import ...` (any names), `from pathlib import Path` alone, and `from pathlib import
# PurePath` alone. PY_IMPORT_AS_WRITE_RE and PY_IMPORT_PLAIN_WRITE_RE cover `import os/shutil/subprocess as
# ...` (aliased, so the module's own dotted name never appears again) and bare `import shutil`/`import
# subprocess` (so an unused or not-yet-dotted import of either is still a write); plain `import os` with no
# alias stays a read, since `os.path...` usage is already a dotted marker on its own.
PY_FROM_IMPORT_RE = re.compile(
    r"\bfrom\s+(os\.path|os|shutil|subprocess|pathlib|io|fileinput|tempfile)\s+import\s+([^\n;#]+)"
)
PY_IMPORT_AS_WRITE_RE = re.compile(r"\bimport\s+(?:os|shutil|subprocess)\s+as\b")
PY_IMPORT_PLAIN_WRITE_RE = re.compile(r"\bimport\s+(?:shutil|subprocess)\b")


def _py_from_import_is_write(module: str, names: str) -> bool:
    """True when a `from <module> import <names>` clause (matched by PY_FROM_IMPORT_RE) counts as a write for
    this fast path. `from os.path import ...` is always a read, whatever names it imports. `from os import
    path` (that single name, alone) is a read; any other name or combination from `os` is a write. `from
    pathlib import Path` or `from pathlib import PurePath` (either, alone) is a read; any other name or
    combination from `pathlib` is a write. Everything from shutil, subprocess, io, fileinput or tempfile is a
    write, with no exemption."""
    names = names.strip()
    if module == "os.path":
        return False
    if module == "os":
        return names != "path"
    if module == "pathlib":
        return names not in ("Path", "PurePath")
    return True


def _py_code_has_write_marker(code: str) -> bool:
    """True when `code` (a python -c argument or heredoc body) holds any marker this fast path treats as a
    write: see PY_WRITE_MARKER_RE's own comment for the full list, plus (only when the code also holds an
    open-style call opener: `open(`, `.open(`, `io.open(`, `codecs.open(`, `os.open(`, `os.fdopen(`) either a
    quoted mode literal made only of r/w/a/x/b/t/+ characters that holds a w, a, x or +, found anywhere in
    the code, or a `mode=` keyword whose value is not a quoted literal at all; plus any `from <module>
    import <names>` clause PY_FROM_IMPORT_RE finds that _py_from_import_is_write judges a write, any aliased
    `import os/shutil/subprocess as ...` (PY_IMPORT_AS_WRITE_RE), and any bare `import shutil`/`import
    subprocess` (PY_IMPORT_PLAIN_WRITE_RE). See the block comment above PY_PROG_RE for why this is a
    whole-code, fail-safe rule rather than an argument-position-aware one."""
    if PY_WRITE_MARKER_RE.search(code):
        return True
    if PY_IMPORT_AS_WRITE_RE.search(code) or PY_IMPORT_PLAIN_WRITE_RE.search(code):
        return True
    for m in PY_FROM_IMPORT_RE.finditer(code):
        if _py_from_import_is_write(m.group(1), m.group(2)):
            return True
    if not PY_OPEN_CALL_OPENER_RE.search(code):
        return False
    if PY_MODE_KWARG_NONLITERAL_RE.search(code):
        return True
    for m in PY_MODE_LITERAL_RE.finditer(code):
        if any(ch in m.group(2) for ch in "wax+"):
            return True
    return False


def _ro_python_ok(piece: str) -> bool:
    """Is this one piece's python/python3 call one of the forms this fast path can prove reads only: `-c` with
    exactly one code argument (and no options besides -B/-E/-I/-s/-u), or `-m json.tool` with at most one
    input file and no output-file argument -- and only when that code holds no PY_WRITE_MARKER_RE / open()-
    mode marker. Any other shape (another module, extra args, an unreadable quote) returns False."""
    words = _shell_words(piece)
    if words is None:
        return False
    cmds = _simple_commands(words)
    if len(cmds) != 1:
        return False
    toks = _ro_strip_words(cmds[0])
    if not toks or not PY_PROG_RE.match(os.path.basename(toks[0])):
        return False
    args = toks[1:]
    i = 0
    while i < len(args) and args[i] in PY_SAFE_FLAGS:
        i += 1
    args = args[i:]
    if args[:1] == ["-c"]:
        return len(args) == 2 and not _py_code_has_write_marker(args[1])
    if args[:2] == ["-m", "json.tool"]:
        return len(args) - 2 <= 1
    return False


def _heredoc_py_pieces(cmd: str):
    """Yield (match, sep_pos, prefix, body) for every heredoc in `cmd`, where `prefix` is the command text
    immediately before it (back to the previous statement separator) and `body` is its text between the
    opening and closing markers. Shared by `_strip_safe_python_heredocs` and `_guard_shell`'s own-run-state
    check, so both agree on what "fed to a bare python/python3 invocation" means."""
    pos = 0
    for m in HEREDOC_RE.finditer(cmd):
        sep_pos = pos - 1
        for c in ";&|\n(":
            p = cmd.rfind(c, pos, m.start())
            if p > sep_pos:
                sep_pos = p
        prefix = cmd[sep_pos + 1:m.start()].strip()
        lines = m.group(0).split("\n")
        body = "\n".join(lines[1:-1])
        yield m, sep_pos, prefix, body
        pos = m.end()


def _is_ro_python_heredoc(prefix: str, body: str) -> bool:
    """True when `prefix` (the command text right before a heredoc) is a bare python/python3 invocation (no
    other option, no script file) and `body` holds no PY_WRITE_MARKER_RE / open()-mode marker -- the rule
    that lets a heredoc be treated as a proven read, shared by `_strip_safe_python_heredocs` and
    `_guard_shell`'s own-run-state check below."""
    return bool(PY_HEREDOC_PREFIX_RE.match(prefix)) and not _py_code_has_write_marker(body)


def _strip_safe_python_heredocs(cmd: str) -> str:
    """`cmd` with every heredoc fed to a bare `python3`/`python3 -` invocation (no other option, no script
    file) replaced by a harmless `true` when its body holds no PY_WRITE_MARKER_RE / open()-mode marker, so the
    piece-by-piece scan below never has to treat that body's own lines as separate shell statements. A
    heredoc fed to anything else, or whose body does hold a marker, is left completely untouched here -- it
    falls through to the existing, unchanged strict checks exactly as it did before this checkpoint."""
    out, pos = [], 0
    for m, sep_pos, prefix, body in _heredoc_py_pieces(cmd):
        if not _is_ro_python_heredoc(prefix, body):
            continue  # not a bare, proven-read-only python heredoc: leave it (and its body) for the strict checks
        out.append(cmd[pos:sep_pos + 1])
        out.append(" true")
        pos = m.end()
    out.append(cmd[pos:])
    return "".join(out)


def _provably_read_only(cmd: str, cwd: str) -> bool:
    """True only when every statement in `cmd` can be PROVEN to write nothing. Anything this can't account for
    returns False, so the caller falls back to the slower, fail-safe mention check that follows -- this never
    allows a command that check would refuse, it only skips that check for commands proven safe here."""
    # a command substitution or backtick ANYWHERE in the command can smuggle a .ratchet path into an
    # unrecognised program's argument as plain output text (`unknown_cmd "$(echo .ratchet/x)"`), split away
    # from the piece that names it by the separator split below; the unrecognised-program exemption in the
    # loop must never fire on a command like that, so this is checked once, command-wide.
    has_subst = bool(re.search(r"\$\(|`", cmd))
    # `masked` keeps `cmd`'s own length and every character's position, with every | ; & ( ) ` $ > that sits
    # inside quotes replaced -- so both the redirect scan and the statement split below can use plain regexes
    # on it without being quote-aware themselves, yet a `>`, `|` or `;` sitting inside a quoted awk/sed
    # script, a jq filter or a note is never mistaken for a real redirect or a statement boundary. A double-
    # quoted span holding a live `$(...)`/backtick can't be masked this way (the shell still runs it), so
    # `_mask_quoted_seps` returns None then and this whole command is left to the slow, fail-safe path.
    masked = _mask_quoted_seps(cmd)
    if masked is None:
        return False
    # CP4 round-04 host-alt-standards A1: a `>(` process substitution OUTSIDE quotes anywhere makes this
    # command not provably read-only, whatever program sits inside it or where its target resolves -- the
    # slow, fail-safe mention check judges it instead (see `_proc_subst_targets`). Checked on `masked`, not
    # raw `cmd`, so a `>(...)` shape sitting inside an ordinary quoted string (a note or commit message
    # quoting this very example) is never mistaken for a real one and sent needlessly to that slower path.
    if ">(" in masked:
        return False
    # One all-or-nothing fact about the whole command (never a position-by-position walk -- see
    # `_cmd_only_safe_cds`'s own comment for why): a relative redirect, cp destination, or unrecognised
    # program's piece can only be proven to run outside .ratchet/ when the session's own cwd already is, AND
    # every cd/pushd/popd in `cmd` is one `_cmd_only_safe_cds` can fully vouch for. Otherwise this whole
    # command is "unsafe" for every relative target in it, command-wide, and falls back to the slow,
    # fail-safe mention check below.
    cmd_unsafe = _ratchet_rel(cwd, "") is not None or not _cmd_only_safe_cds(cmd)
    # CP4: `_redirect_targets` (shared with the strict path's own scan in `_guard_shell`) replaces this
    # function's own former inline use of RO_REDIRECT_RE, so both paths recognise every redirect operator
    # form (`>`, `>>`, `N>`, `N>>`, `&>`, `&>>`, `>|`, `N>|`, `>&word`) the same way.
    for t in _redirect_targets(cmd, masked):
        if _ro_bad_target(t, cwd, cmd_unsafe):
            return False
    # Split on statement separators only outside quotes: a pipe inside a jq filter, a grep -E alternation or
    # an awk -F'|' separator is quoted text, not a boundary between statements. `masked` finds those
    # boundaries (it never changes length or position), and the pieces are then sliced from `cmd` itself so
    # the quoted text (and any redirect) each piece carries stays intact, exactly as if the split had never
    # touched it.
    parts, pos = [], 0
    for sm in RO_SEP_RE.finditer(masked):
        parts.append(cmd[pos:sm.start()])
        pos = sm.end()
    parts.append(cmd[pos:])
    # Iterate `parts` directly -- do not rejoin with "\n" and re-split, which used to be a no-op (every
    # separator, including a quoted newline, used to end a part) but would now re-shred a part that carries a
    # real newline preserved from inside its own quotes (CP3 round-02: a python -c argument's own line
    # breaks), undoing the quote-aware split just performed above.
    for piece in parts:
        words = re.sub(r"(\d*|&)>>?\|?&?\s*\S*|<\s*\S*", " ", piece).split()
        words = [w for w in words if w.strip("'\"")]
        if not words:
            continue
        words2 = _ro_strip_words(words)
        if not words2:
            continue  # only keywords/assignments/wrappers survived stripping; nothing left runs
        prog = os.path.basename(words2[0])
        if prog in ("cd", "pushd", "popd"):
            continue  # already accounted for, command-wide, in `cmd_unsafe` above
        if PY_PROG_RE.match(prog):
            # python's own read-only-ness never depends on cwd/cd (it's proven from the code/args alone), so
            # this is judged on its own, same as the cd/pushd/popd branch above -- see `_ro_python_ok`.
            if not _ro_python_ok(piece):
                return False
            continue
        if prog != "for" and prog not in RO_TABLE:
            # an unrecognised program: only provably safe when this piece is a plain top-level statement (no
            # keyword/assignment/wrapper stripped off it -- a loop or conditional body can carry an unseen
            # .ratchet path through its own variable, the same blind spot xargs has), holds no live
            # substitution, names no .ratchet path itself, and the whole command isn't "unsafe" above
            if words2 != words or has_subst or cmd_unsafe or "$" in piece or "`" in piece or \
                    RATCHET_TOKEN_RE.search(piece):
                return False
            continue
        if not _ro_prog_ok(words, cwd, cmd_unsafe, has_subst, piece):
            return False
    return True


def _cmd_has_unresolved_cd(cmd: str) -> bool:
    """True when some cd/pushd segment's target can't be resolved at all (a variable, a command substitution,
    a backtick, a bare '-', or an option). Used only to judge a redirect's OWN relative target below -- never
    to gate whether a whole segment with no .ratchet mention is looked at at all, which is what caused the
    false refusals on ordinary commands (npm test, make, git push) after an everyday `cd "$REPO"`/`cd -`."""
    for seg in _segments(cmd):
        toks = _ro_strip_words(seg.strip().split())
        if toks:
            toks[0] = _strip_group_prefix(toks[0])
        if not toks or toks[0] not in ("cd", "pushd"):
            continue
        target = toks[1].strip("'\"") if len(toks) > 1 else ""
        if not target or target == "-" or target.startswith("-") or "$" in target or "`" in target:
            return True
    return False


def _cmd_cd_names_ratchet(cmd: str) -> bool:
    """True when some cd/pushd segment in `cmd` has a literal (resolvable) target whose text names
    .ratchet/. Used only by the loop-write check's own narrow 'inside .ratchet' signal (CP4 round-02
    X1/A3/C1): an ordinary relative cd to an unrelated directory (`cd docs`) must not count as inside, so
    this never reuses `_cmd_only_safe_cds`'s broader 'this fast path can't fully vouch for this cd' signal,
    which is also False for that harmless case."""
    for seg in _segments(cmd):
        toks = _ro_strip_words(seg.strip().split())
        if toks:
            toks[0] = _strip_group_prefix(toks[0])
        if not toks or toks[0] not in ("cd", "pushd"):
            continue
        target = toks[1].strip("'\"") if len(toks) > 1 else ""
        if target and _ratchet_rel(target, "") is not None:
            return True
    return False


# CP4 design item 4: a `while`/`until ...; do ... done` or `for VAR in LIST; do ... done` loop whose own
# input (a pipe into the while/until, a `< file`/`< <(...)` redirect after its `done`, or the for-list
# itself) names a .ratchet path, or whose session's/command's own cd state is already inside .ratchet/, and
# whose body (any stage, see `_loop_body_segments`) writes anything at all, is refused -- whatever the
# writer program, whatever its arguments, and whether or not it even touches a loop variable. Check-in
# decision (CP4 round 2): the earlier per-argument, loop-variable-as-destination analysis (`_loop_vars`,
# `_loop_var_is_destination`, `_loop_body_writes_via_var`) kept leaking narrower and narrower cases each
# review round, so this is deliberately simpler and stricter -- a loop that reads run files in its input and
# writes ANYTHING in its body is refused; there is no longer a "this write's source/destination happens not
# to be the loop variable" exemption. Narrow and line-shaped on purpose (a single, non-nested loop per
# match, `do`/`done` as plain words, a loop header's own newline before `do` normalised to a `;` first) --
# not a general shell parser; a loop shaped some other way simply isn't matched here and is left to the rest
# of this guard's existing mention-based checks.
LOOP_HEAD_RE = re.compile(
    r"(?P<sep>^|[;&|\n])\s*(?:(?:while|until)\s+(?P<cond>.+?)|"
    r"for\s+(?P<fvar>[A-Za-z_]\w*)\s+in\s+(?P<flist>[^;\n]+?))\s*;\s*do\b", re.S)
# writer programs: whatever arguments they're given, each of these changes a file it's pointed at, so any of
# them appearing in a loop body stage (see `_loop_body_stage_writes`) is a write, with no per-argument
# source/destination analysis.
LOOP_WRITER_PROGS = {"rm", "rmdir", "touch", "truncate", "tee", "chmod", "chown", "cp", "mv", "ln", "install",
                      "dd", "sponge"}


def _normalize_loop_seps(cmd: str) -> str:
    """`cmd` with every newline that sits outside single/double quotes replaced by `;`, same length and
    position as `cmd` (see `_mask_quoted_seps`, whose masked newlines mark exactly the ones inside quotes),
    so `LOOP_HEAD_RE` only ever has to recognise a `;`-separated loop header, whether the agent wrote
    `while ...; do` on one line or `while ...`/`do` split across several. Falls back to the coarse mask
    (`_mask_quoted_text_coarse`, which never gives up) when `_mask_quoted_seps` itself gives up (a
    double-quoted span with a live substitution) -- CP4 round-06: giving up here used to mean "skip the
    whole loop check, hand the command to a crude raw-text fallback instead", which both missed real writes
    and flagged quoted writer-program words as if they were commands. The coarse mask still tells us exactly
    which newlines sit inside a quoted span (blanked, so no longer `\\n`) versus outside it (left alone), so
    this never needs to give up at all.

    A newline that follows an unquoted trailing `|`, `&` or `&&`/`||` (skipping only spaces/tabs in between)
    feeds the next line into the SAME statement -- it is not a new statement at all, so it is left as plain
    whitespace instead (CP4 round-04 A2: converting it to `;` turned `find ... |\\nwhile read f; do ... done`
    into `... |;while ...`, which made `;`, not `|`, the separator `LOOP_HEAD_RE` captured, so the pipe-input
    test below never saw the pipe)."""
    masked = _mask_quoted_seps(cmd)
    if masked is None:
        masked = _mask_quoted_text_coarse(cmd)
    out = list(cmd)
    for i, ch in enumerate(masked):
        if ch == "\n":  # an outside-quotes newline: _mask_quoted_seps leaves these alone, masking only ones
            j = i - 1
            while j >= 0 and masked[j] in " \t":
                j -= 1
            if j >= 0 and masked[j] in "|&":
                out[i] = " "  # feeds the next line into this same pipeline/list: not a statement separator
                continue
            out[i] = ";"  # that sit inside quotes (to "x") -- see that function's own docstring.
    return "".join(out)


_LOOP_BODY_SEP_RE = re.compile(r"\|\||&&|;|\||&|\n")


def _loop_body_segments(body: str) -> list:
    """`body` split on every top-level `;`, `&&`, `||`, `|`, bare `&`, or newline -- quote-aware via
    `_mask_quoted_seps` (same split `_segments` already gives the rest of this guard, with a bare `&` added
    too), so every pipeline/statement stage of a loop body is checked on its own, not just the first stage
    before a `|` (CP4 round-02 A1/C2: `cat /tmp/new.json | tee "$f"` is two stages; the first is read-only,
    the second is the real write, and the old `[;\\n]`-only split never looked past the first)."""
    masked = _mask_quoted_seps(body)
    if masked is None:
        return [p for p in _LOOP_BODY_SEP_RE.split(body) if p.strip()]
    # CP4 round-04 minor A4: a `>|` (or `N>|`) clobber redirect is a single operator, not a pipe into a
    # second stage -- mask its own `|` character here the same way a quoted one already is (same length, so
    # positions stay aligned), so the split below never splits a write like `echo x >| "$f"` into a harmless-
    # looking `echo x >` stage and a second stage that loses the operator and its own real target.
    masked = re.sub(r">\|", ">x", masked)
    parts, pos = [], 0
    for sm in _LOOP_BODY_SEP_RE.finditer(masked):
        parts.append(body[pos:sm.start()])
        pos = sm.end()
    parts.append(body[pos:])
    return [p for p in parts if p.strip()]


def _loop_body_stage_writes(seg: str) -> bool:
    """True when loop body stage `seg` writes anything, whatever its own arguments (CP4 round-02 check-in
    SIMPLIFY decision: the earlier per-argument, loop-variable-as-destination analysis kept leaking narrower
    cases every round, so this no longer asks whether a write's source or destination happens to be the
    loop's own variable -- any writer program or any output redirect in the stage is enough). An output
    redirect is safe only when its target is a literal absolute path outside .ratchet/ with no `$` (fd
    duplication and /dev/null are never targets at all -- see `_redirect_targets`)."""
    masked = _mask_quoted_seps(seg)
    # CP4 round-03 A1: a `>(...)` process substitution hides its own write target from `_redirect_targets`
    # by design (its argument characters are excluded from the target's own character class -- see that
    # function's docstring), so `cat SRC > >(tee "$f")` inside a loop body was judged read-only. Any `>(`
    # outside quotes in a loop body stage counts as a write outright, the same rule `_provably_read_only`
    # already applies at the top level.
    if ">(" in (masked if masked is not None else seg):
        return True
    # CP4 round-03 X1: pass the quote-aware mask into `_redirect_targets`, matching the other two call
    # sites (`_provably_read_only` and the strict path in `_guard_shell`), so a `>` sitting inside a quoted
    # jq filter or grep pattern (`jq '.count > 0'`, `grep -c 'a=>b'`) is never mistaken for a real redirect.
    for t in _redirect_targets(seg, masked):
        tt = t.strip("'\"")
        if "$" in tt or "`" in tt or not os.path.isabs(os.path.expanduser(tt)) or _ratchet_rel(tt, "") is not None:
            return True
    prog, _ = _program(seg)
    if prog in LOOP_WRITER_PROGS:
        return True
    if prog in ("sed", "perl") and re.search(r"(?:^|\s)(-[A-Za-z]*i\b|--in-place\b)", seg):
        return True
    if prog in ("awk", "gawk") and re.search(r"(?:^|\s)-i\b", seg):
        return True
    if re.fullmatch(r"python[0-9.]*|py|node", prog) and WRITE_CODE_RE.search(seg):
        return True
    if prog == "uniq":
        # CP4 round-02 A2/C3: strip any redirect sharing this statement (`uniq - "$f" < /tmp/new.json`)
        # before counting uniq's own operands with the same shared helper `_ro_prog_ok` uses, so a bare
        # `-` is counted and a redirect target is never mistaken for uniq's own second operand.
        return len(_uniq_operands(_strip_redirect_args(seg.split()[1:]))) >= 2
    return False


def _loop_write_problem(cmd: str, cwd: str) -> bool:
    """True when `cmd` holds a loop `LOOP_HEAD_RE` recognises whose input/list names a .ratchet path (or
    whose own cd state is already inside .ratchet/) and whose body (any stage `_loop_body_segments` finds)
    writes anything at all (see `_loop_body_stage_writes`). Check-in decision (CP4 round 2): there is no
    longer any "this write doesn't touch the loop variable" exemption -- a loop proven to read run files is
    refused the moment any stage of its body writes anything.

    CP4 round-06 SIMPLIFY (deletes the old `_loop_write_problem_fallback`): a live `$(...)`/backtick
    substitution inside a double-quoted span anywhere in `cmd` no longer sends this whole check to a crude,
    unmasked text scan for writer-program words -- that scan both missed real writes (a `sed -i`/`uniq`/
    python write paired with an unrelated `$(date)` stamp elsewhere in the same loop) and flagged quoted DATA
    as if it were a command (a writer-program word sitting inside a grep pattern or echoed string). Instead,
    `_normalize_loop_seps` and the loop-head match below fall back to the coarse mask
    (`_mask_quoted_text_coarse`, which never gives up) so this one loop checker always runs the same
    structural walk; only the quote mask gets cruder when a live substitution is present."""
    norm = _normalize_loop_seps(cmd)
    # CP4 round-02 X1/A3/C1: "inside .ratchet" here means only the session's own cwd is inside .ratchet/,
    # or this command carries a cd/pushd whose literal target names .ratchet, or one whose target can't be
    # resolved at all ($var, `-`, a substitution) -- never "any cd `_cmd_only_safe_cds` can't fully prove
    # absolute-and-safe", which is also true of a perfectly ordinary relative cd to an unrelated directory
    # (`cd docs`) and would refuse that loop for no reason connected to .ratchet/ at all.
    cwd_inside = (_ratchet_rel(cwd, "") is not None or _cmd_cd_names_ratchet(cmd) or _cmd_has_unresolved_cd(cmd))
    # CP4 round-05 A2: match the loop head on a fully quote-blanked copy of `norm` (same contract
    # `_redirect_targets`/`_proc_subst_targets` already use elsewhere), not on `norm` itself -- otherwise a
    # `|`/`while ... do ... done` shape sitting inside a quoted echo/printf argument (plain documentation
    # text, never real shell syntax) was read as a genuine loop header and body. Real text for every group is
    # still sliced out of `norm` itself by position, since masking never changes length or position.
    head_mask = _mask_quoted_text(norm)
    if head_mask is None:
        # CP4 round-06: `norm` itself still carries the live substitution verbatim (masking never changes
        # the real text, only normalizes separators), so the precise mask gives up here too -- fall back to
        # the coarse one (never None) instead of scanning raw, unmasked text.
        head_mask = _mask_quoted_text_coarse(norm)
    for m in LOOP_HEAD_RE.finditer(head_mask):
        rest = norm[m.end():]
        # CP4 round-04 A1: find the loop's closing `done` on quote-masked text (see `_mask_quoted_text`), and
        # only as a whole word right after a statement separator (`;`, `&`, a newline -- already normalised
        # to `;` above -- or the very start of `rest`), so a `done` sitting inside a quoted jq filter or
        # echoed string (`jq '.phase="done"' "$f"`, `echo "all done" > "$f"`) is never mistaken for the real
        # loop end. Falls back to the plain (unmasked) text only when masking itself gives up (a double-
        # quoted span with a live substitution), same fail-safe default as every other caller of the mask.
        rest_masked = _mask_quoted_text(rest)
        hay = rest_masked if rest_masked is not None else rest
        done_m = re.search(r"(?:^|[;&\n])\s*(done)\b", hay, re.S)
        if not done_m:
            continue
        body = rest[:done_m.start(1)]
        if m.group("fvar"):
            flist = norm[m.start("flist"):m.end("flist")] if m.group("flist") is not None else ""
            input_ok = cwd_inside or bool(RATCHET_TOKEN_RE.search(flist))
        else:
            before = norm[:m.start("sep")]
            input_ok = cwd_inside or (m.group("sep") == "|" and bool(RATCHET_TOKEN_RE.search(before)))
            if not input_ok:
                tail = rest[done_m.end(1):]
                redir_m = re.match(r"\s*<\s*(<\(.*?\)|\S+)", tail)
                input_ok = bool(redir_m and RATCHET_TOKEN_RE.search(redir_m.group(1)))
        if input_ok and any(_loop_body_stage_writes(seg) for seg in _loop_body_segments(body)):
            return True
    return False


def _mask_subst_free_spans(raw: str) -> str:
    """`raw` with the spans a `$(`/backtick substitution check should ignore replaced by inert text: every
    single-quoted span (`_mask_quoted_seps` already blanks a backtick/$ there, since bash never expands
    either inside single quotes) and the body of any heredoc whose delimiter is itself quoted (`<<'EOF'`,
    `<<"EOF"`, `<<-'EOF'`) -- bash never expands that body either. A Markdown backtick in a quoted brief or
    heredoc, or a literal `$(...)` example quoted in a commit message, is therefore not a real command
    substitution. A double-quoted span and an unquoted-delimiter heredoc body are left exactly as they are:
    the shell still expands those, so a `$(`/backtick there must still count.

    Falls back to `raw` itself when `_mask_quoted_seps` gives up (a double-quoted span elsewhere in the
    command holds a live substitution) -- that case is still refused correctly, because `raw` itself still
    carries the unmasked `$(`/backtick. Same length and position as `raw`, so the mention test run against
    `raw` and the substitution test run against this result always agree on where each character sits."""
    masked = _mask_quoted_seps(raw)
    out = list(masked if masked is not None else raw)
    for m in HEREDOC_RE.finditer(raw):
        if not m.group(1):
            continue  # unquoted delimiter: bash still expands this body
        lines = m.group(0).split("\n")
        body = "\n".join(lines[1:-1])
        body_start = m.start(0) + len(lines[0]) + 1
        for k in range(body_start, body_start + len(body)):
            out[k] = "x"
    return "".join(out)


def _guard_shell(cmd: str, cwd: str, who: dict | None = None) -> str | None:
    raw = cmd
    if HEREDOC_RE.search(raw):
        for m, _sep_pos, prefix, body in _heredoc_py_pieces(raw):
            # CP4 round-05 B2/S1: a heredoc is also code when the INTERPRETER it's fed to comes AFTER the
            # heredoc operator on the same opening line (`cat <<'EOF' | python3`, `cat <<'EOF' | bash`), not
            # only when it comes before (`python3 <<EOF`). `m.group(3)` is `HEREDOC_RE`'s own capture of the
            # rest of that opening line (already holds the `| python3`/`| bash`); check it the same way as
            # `prefix`, the text before the heredoc.
            trailer = m.group(3) or ""
            if not INTERPRETER_RE.search(prefix) and not INTERPRETER_RE.search(trailer):
                # CP4 round-04 host-alt-correctness A1: this heredoc's own feeding program (`prefix`, the
                # command text right before it, or `trailer`, the text piping it onward) isn't an
                # interpreter, so its body is data, not code -- even when some OTHER word in the command
                # (including a bare interpreter name sitting inside this same heredoc's own body, which is
                # plain prose) happens to match INTERPRETER_RE. A `cat > file << EOF` heredoc whose body
                # merely mentions "sh"/"python"/... in prose stays data here.
                continue
            if _is_ro_python_heredoc(prefix, body):
                # same rule `_strip_safe_python_heredocs` uses below to prove this heredoc reads only: a bare
                # python/python3 invocation whose body holds no write marker. Let it skip this earlier
                # run-state refusal so a read-only full-path open() on a run file isn't blocked before that
                # pass-through ever runs. A write marker, or any other interpreter (bash, node, ...), still
                # falls through to the checks below exactly as before.
                continue
            for t in RATCHET_TOKEN_RE.findall(m.group(0)):
                if not _write_allowed(t, cwd):
                    return ("RATCHET GUARD: this script touches Ratchet's run state (.ratchet/). Gate state, evidence, "
                            "approvals and config are owned by ratchet.py — use its commands instead. To read those "
                            "files, use cat or jq.")
                why = _owner_problem(t, cwd, who)
                if why:
                    return why
    # CP3: a bare python3/python3 - heredoc whose body holds no write marker is swapped for a harmless `true`
    # here, before `_expand` below drops every heredoc body as data -- `_provably_read_only` never sees the
    # original heredoc syntax at all, so this must run first. The RATCHET_TOKEN mention check just above now
    # skips the same proven-read-only heredocs (see `_is_ro_python_heredoc`), so a full-path read of a run
    # file in one of those heredocs reaches this substitution instead of being refused there; any heredoc
    # that doesn't qualify (a write marker, or fed to bash/sh/node/...) is still refused there first, exactly
    # as before.
    cmd = _strip_safe_python_heredocs(cmd)
    cmd = _expand(cmd)
    cmd = _blank_commit_messages(cmd)
    if NESTED_AGENT_RE.search(cmd):
        return ("RATCHET GUARD: launching another agent session (claude -p, codex exec, gemini -p, copilot -p) from "
                "the shell is blocked while Ratchet is active — it could impersonate the user. Use sub-agents, "
                "external_review.py for adversarial reviews, or ui_review.py for UI reviews.")
    if _calls_own_hook(cmd):
        return ("RATCHET GUARD: Ratchet's hooks are called by your agent CLI, not by you. Calling `ratchet.py hook` "
                "yourself would forge a user message or a gate event.")
    if DANGEROUS_GIT_RE.search(cmd):
        return "RATCHET GUARD: this git command would delete or stash Ratchet's run state (ignored files)."
    # CP4 (director decision, round 6): a command substitution ($(...) or a backtick, quoted or not) can hide a
    # write inside what looks like a read, and this guard does not parse shells well enough to see through it.
    # Fail closed with no parsing: a command that names Ratchet's run folder at all (the same RATCHET_TOKEN_RE
    # mention test used elsewhere, applied to the raw, untouched command text) and contains `$(` or a backtick
    # anywhere is refused outright, before the loop check and the read-only fast path below ever run. A command
    # that never mentions .ratchet is untouched by this check.
    # CP4 round 7 (director decision): bash never expands a `$(`/backtick that sits inside a single-quoted
    # span, or inside the body of a heredoc whose own delimiter is quoted (<<'EOF', <<"EOF", <<-'EOF') -- so a
    # Markdown brief, a quoted heredoc example or a single-quoted commit message that merely mentions a run
    # path in backticks is not a real substitution. `_mask_subst_free_spans` blanks exactly those two inert
    # spans (and only falls back to `raw` unmasked when it can't, which still refuses correctly); a `$(` or
    # backtick that is unquoted, inside double quotes, or inside an unquoted-delimiter heredoc body still
    # counts. The mention test above still runs on `raw` itself, unchanged.
    subst_text = _mask_subst_free_spans(raw)
    if RATCHET_TOKEN_RE.search(raw) and ("$(" in subst_text or "`" in subst_text):
        return ("RATCHET GUARD: this command names Ratchet's run folder and contains a command substitution "
                "($(...) or backticks). Run the substitution as its own command first, then use its result in "
                "a separate command.")
    if _loop_write_problem(cmd, cwd):
        return ("RATCHET GUARD: this loop reads Ratchet's run files and writes inside its own body. Gate "
                "state, evidence, approvals and config are owned by ratchet.py — use its commands instead. "
                "Inside such a loop, only a redirect to a literal absolute path outside .ratchet/ with no $ "
                "is safe, for example cat \"$f\" >> /tmp/summary.txt; tee, cp, mv, rm, sponge and other "
                "writer programs are refused in the body whatever their arguments.")
    if _provably_read_only(cmd, cwd):
        return None
    base_deny = ("RATCHET GUARD: this command could change Ratchet's run state (.ratchet/). Gate state, evidence, "
                 "approvals and config are owned by ratchet.py — use its commands (behavior / ui-record / "
                 "adv-record / complete / config) instead. To read run files, use cat, jq, grep, head/tail, "
                 "sed -n or awk without -i; python and other programs that name a run path are refused.")
    cwd_inside = _ratchet_rel(cwd, "") is not None
    cmd_inside = any(re.match(r"^\s*[({!]*\s*(cd|pushd)\s+\S*\.ratchet", seg, re.I) for seg in _segments(cmd))
    if cwd_inside:
        # the fast path above already let through anything it can prove reads only, cd included; reaching
        # here means this command isn't provably read-only, and the session's shell is already inside
        # .ratchet/, so a bare relative argument (rm state.json, echo x > state.json) could land on a run
        # file with no .ratchet token anywhere in the command text for the mention checks below to catch.
        return ("RATCHET GUARD: your shell is inside .ratchet/; cd back to the project root first, then run "
                "the command. To read run files from here, use cat, jq, grep, head/tail, sed -n or awk "
                "without -i; everything else needs the shell back at the project root.")
    deny = base_deny if not cmd_inside else (
        base_deny + " Run commands that change files in a separate call, after cd-ing back out of .ratchet/.")
    inside = cmd_inside
    any_mention = any(RATCHET_TOKEN_RE.search(s) for s in _segments(cmd))
    cd_unresolved = _cmd_has_unresolved_cd(cmd)
    for seg in _segments(cmd):
        if re.fullmatch(r"\s*(export\s+)?[A-Za-z_]\w*=\S*\s*", seg):
            continue  # a bare assignment writes nothing; its uses were expanded above
        prog, sub = _program(seg)
        # CP4 round-06: `for X in LIST` runs nothing by itself (LIST is never executed here) -- the same rule
        # `_ro_prog_ok` already gives the precise path. Reached only when this command's own live substitution
        # elsewhere (not in this segment) sent the whole command to this slow path; without this, a for-loop
        # whose list names a run path (an ordinary read-only diagnostic) was refused on that mention alone.
        if prog == "for":
            continue
        mentions = RATCHET_TOKEN_RE.findall(seg)
        if prog == "sed":
            mentions += [t.strip("'\"") for t in SED_W_TARGET_RE.findall(seg) if ".ratchet" in t.lower()]
        if prog == "xargs" and not mentions and any_mention:
            # the write program's real targets come from an earlier pipeline stage's output, which this guard
            # can't see; that earlier stage (anywhere in the command) named a .ratchet path, so fail safe
            # unless the program xargs runs is itself read-only (closes `find .ratchet | xargs rm`)
            inner = [t for t in seg.strip().split()[1:] if not t.startswith("-")]
            inner_prog = os.path.basename(inner[0]) if inner else ""
            if inner_prog and inner_prog not in READ_ONLY_PROGRAMS:
                return deny
        # a redirect target can be quoted ('...' or "..."); unquote it before resolving/checking it below, so a
        # quoted literal path into a run file (`jq ... > ".ratchet/runs/hk/state.json"`) is judged on its real
        # path, not left unresolved by the quote characters. A target that still holds `$` or a backtick after
        # unquoting stays unresolvable, same as before (it never matched a literal .ratchet path either way).
        # CP4: `_redirect_targets` recognises every operator form (`>`, `>>`, `N>`, `N>>`, `&>`, `&>>`, `>|`,
        # `N>|`, `>&word`), not just the plain `>`/`>>` the old REDIRECT_RE-based list caught; `_proc_subst_targets`
        # adds a `>(...)` process substitution's own inner program's arguments (`tee <file>`) as write targets
        # too, exactly as a bare call to that program would get.
        seg_masked = _mask_quoted_seps(seg)
        targets = _redirect_targets(seg, seg_masked) + _proc_subst_targets(seg, seg_masked)
        # an earlier cd/pushd in this command whose target can't be resolved at all leaves this redirect's own
        # relative target unproven -- but only the target itself is judged on that, never the broad mentions/
        # inside skip below (that broad use is what caused ordinary commands with no .ratchet mention at all,
        # such as `cd "$REPO" && npm test`, to be refused; see CP2 round-05 finding A1).
        unresolved_target = cd_unresolved and any(not os.path.isabs(os.path.expanduser(t.strip("'\"")))
                                                   for t in targets)
        if not mentions and not inside and not unresolved_target:
            continue
        if ENGINE_CALL_RE.match(seg):
            if not targets:
                continue  # ratchet.py / reviewer scripts write their own files
        for t in mentions + targets:
            if prog in READ_ONLY_PROGRAMS and t not in targets:
                continue  # reading a review is fine
            why = _owner_problem(t, cwd, who)
            if why:
                return why
        read_only = prog in READ_ONLY_PROGRAMS or (prog == "git" and sub in READ_ONLY_GIT) or \
            (prog == "find" and not re.search(r"\s-(delete|exec|execdir|ok|fprint)\b", seg)) or \
            (prog in ("mkdir",) and all(_write_allowed(t, cwd) for t in mentions))
        if read_only and not targets:
            continue
        if read_only and targets and all(_write_allowed(t, cwd) and not inside and not unresolved_target
                                          for t in targets):
            continue
        if not inside and not unresolved_target and mentions and all(_write_allowed(t, cwd) for t in mentions) and \
                all(_write_allowed(t, cwd) for t in targets):
            continue  # e.g. writing a review JSON or a capture spec
        return deny
    return None


def _run_phase(root: Path) -> str | None:
    try:
        ctx = Ctx(root)
        if not (ctx.ratchet / "active.json").exists():
            return None
        st, _why = _read_record(ctx.state_path())
        return (st or {}).get("phase")
    except (Exception, SystemExit):
        return None


SUBAGENT_LAUNCH_TOOLS = {"task", "agent"}  # Claude Code's PreToolUse tool_name for a sub-agent launch (Agent on
                                            # current builds, or Task on older ones); no other host is checked by
                                            # this guard (CP3).


def _subagent_role(subagent_type) -> str | None:
    """The Ratchet role name for a Task/Agent launch's `subagent_type` ('ratchet-implementer',
    'ratchet-loop:ratchet-fixer', with or without a plugin prefix before the last ':'), or None when it does not
    name a Ratchet sub-agent at all -- a non-Ratchet agent such as 'general-purpose' or 'Explore' is never checked
    by this guard."""
    tok = str(subagent_type or "")
    if ":" in tok:
        tok = tok.rsplit(":", 1)[1]
    if not tok.startswith("ratchet-"):
        return None
    return _normalize_role(tok)


def _brief_guard(n: dict, root: Path) -> str | None:
    """CP3: on Claude Code only, refuse (with a plain message) a Task/Agent launch of a Ratchet sub-agent during a
    build (phase 'building' or 'blocked') whose prompt does not carry the plan's objective -- the exact text
    `objective_brief` renders (the same text `brief` prints), compared with runs of whitespace collapsed so
    re-wrapping, doubled spaces or a tab/space mix never cause a false refusal. A non-Ratchet sub-agent, any launch
    while no run is building, and any non-Claude-Code host are never checked here (None: allow). Reading the plan
    can raise (an unreadable checkpoints.json calls `die`, a SystemExit) -- deliberately not caught here, since
    `run_hook`'s own fail-open handling turns that into an allowed launch with a recorded crash, exactly like any
    other guard crash."""
    if n["host"] != "claude" or n["tool"].lower() not in SUBAGENT_LAUNCH_TOOLS:
        return None
    role = _subagent_role(n["input"].get("subagent_type"))
    if role is None:
        return None
    if _run_phase(root) not in ("building", "blocked"):
        return None
    ctx = Ctx(root)
    st, _why = _read_record(ctx.state_path())
    plan = _plan_for_briefs(ctx.plan(), st)  # the approved done-means lines (CP4), the same ones brief prints
    expected = re.sub(r"\s+", " ", objective_brief(plan, _done_means_proof_notes(ctx, plan, st))).strip()
    got = re.sub(r"\s+", " ", str(n["input"].get("prompt") or n["prompt"] or "")).strip()
    if expected and expected in got:
        return None
    cp = (st or {}).get("current") or "CPn"
    return (f"RATCHET GUARD: this sub-agent's prompt is missing the plan's objective. Start its prompt with the "
            f"output of `$RATCHET brief {cp} --role {role}`, then the rest of the prompt.")


MERGE_SHARED = {f"{RATCHET_DIR}/{f}" for f in ("config.json", "standards.md", "learnings.md", ".gitignore")}
MERGE_MID_STEP = ("RATCHET GUARD: finish this step before merging main. A merge in the middle of a step would mix "
                  "main's changes into the step's own work and into what its reviewers see. Run the step through "
                  "`complete`, then merge main, then run `ratchet.py merged`.")

MERGE_AGAIN = ("RATCHET GUARD: finish this step before merging main again. An earlier merge in this step was resolved "
               "by hand and its resolution is still waiting for this step's review, so Ratchet cannot accept a second "
               "merge yet. Run the step through `complete`, then merge main, then run `ratchet.py merged`.")


def _between_steps(st, root: Path, merging: bool = False) -> bool:
    """Whether a run is between steps: waiting for a review, or building at step 'tests' with a clean tree (while a
    merge is in progress, only untracked files count as not clean). Used by the merge rule and by integrate."""
    phase, cur = (st or {}).get("phase"), (st or {}).get("current")
    if phase in ("awaiting_checkpoint_review", "awaiting_final_review"):
        return True
    if phase == "building" and cur and st["checkpoints"][cur].get("step") == "tests":
        r = subprocess.run(["git", "--no-optional-locks", "status", "--porcelain", "--", ".", f":(exclude){RATCHET_DIR}",
                            *JUNK_PATHSPECS],
                           cwd=root, capture_output=True, text=True, timeout=20)
        return r.returncode == 0 and not any(ln for ln in r.stdout.splitlines()
                                             if not merging or ln.startswith("??"))
    return False


def _merge_rule(cmd: str, cwd: str, root: Path) -> tuple[str, str | None]:
    """The merge rule, as (command for the other guard checks, refusal or None). In the middle of a step `git merge`
    and `git pull` are refused (finishing or aborting a merge already begun is not). Between steps, while a merge is in
    progress, a plain git add / checkout / commit that touches only Ratchet's shared files is let through by handing
    the other checks `true` in its place. Any other command is returned unchanged. Fails open to 'unchanged'."""
    try:
        segs = _segments(cmd)
        info = [_program(s) for s in segs]
        merge = [i[0] == "git" and i[1] in ("merge", "pull") and not re.search(r"--(abort|continue|quit)\b", s)
                 for s, i in zip(segs, info)]
        shared = [i[0] == "git" and i[1] in ("add", "checkout", "commit") and not re.search(r"[<>$`()]", s)
                  and bool(RATCHET_TOKEN_RE.search(s)) for s, i in zip(segs, info)]
        if not any(merge) and not any(shared):
            return cmd, None
        ctx = Ctx(root)
        if not (ctx.ratchet / "active.json").exists():
            return cmd, None
        st, _why = _read_record(ctx.state_path())
        phase, cur = (st or {}).get("phase"), (st or {}).get("current")
        g = lambda *a: subprocess.run(["git", *a], cwd=root, capture_output=True, text=True, timeout=20)
        merging = g("rev-parse", "-q", "--verify", "MERGE_HEAD").returncode == 0
        between = _between_steps(st, root, merging)
        if phase == "building" and not between and any(merge):
            return cmd, MERGE_MID_STEP
        last = next((e for e in reversed((st or {}).get("history") or [])
                     if e.get("event") in ("checkpoint_complete", "merged_main")), None)
        if phase == "building" and any(merge) and last and last["event"] == "merged_main" and last.get("by_hand"):
            return cmd, MERGE_AGAIN
        if not (between and merging and any(shared)):
            return cmd, None
        out, changed = [], False
        for s, sh in zip(segs, shared):
            rel = [os.path.relpath(os.path.normpath(os.path.join(cwd, t.strip("'\""))), root).replace("\\", "/")
                   for t in RATCHET_TOKEN_RE.findall(s)]
            if sh and rel and all(r in MERGE_SHARED for r in rel):
                out, changed = out + ["true"], True
            else:
                out.append(s)
        return (" ; ".join(out) if changed else cmd), None
    except Exception:
        return cmd, None


def decide_guard(n: dict) -> tuple[bool, str]:
    cmd, cwd = n["command"], n["cwd"]
    if not _is_director_session():
        if n["kind"] == "shell" and cmd:
            why = _reserved_env_problem(cmd)
            if why:
                return True, why
        key_bits = [str(director_key_path()), str(ratchet_home()), "director.key", ".config/ratchet", ".config/rat"]
        scan = cmd + " " + " ".join(n["paths"]) + " " + json.dumps({k: v for k, v in n["input"].items()
                                                                     if k in ("path", "pattern", "glob", "file_path",
                                                                              "absolute_path", "dir_path")})
        wide = n["kind"] in ("read", "shell", "other", "mcp") and ".config" in scan and re.search(r"\brat", scan)
        if any(b in scan for b in key_bits) or wide:
            return True, ("RATCHET GUARD: the director's key and Ratchet's per-user files are off-limits to builder "
                          "sessions. Wait for the director to approve this lane.")
        if n["kind"] == "shell" and DIRECTOR_CALL_RE.search(cmd):
            return True, "RATCHET GUARD: director commands and RATCHET_ROLE are reserved for the director session."
        if n["kind"] == "shell" and re.search(r"reviewer-status\b[^;&|\n]*--mark", cmd):
            return True, ("RATCHET GUARD: only the director (or the user, in their own terminal) can switch a "
                          "reviewer off. Reviewers that genuinely fail are marked unavailable automatically.")
    root = find_root(Path(cwd))
    why = _brief_guard(n, root)
    if why:
        return True, why
    marks = False
    if (root / RATCHET_DIR).is_dir():
        _heartbeat(root, "guard", n["host"])
        if n.get("agent_type") and _host_names_subagent(n["host"]):
            _heartbeat(root, "agent_marks", n["host"])  # this CLI names the sub-agent on its tool calls
        marks = isinstance(read_heartbeat(root).get("agent_marks"), dict)
    who = {"enforce": marks and _host_names_subagent(n["host"]), "agent_type": n.get("agent_type")}
    if n["kind"] == "shell" and cmd:
        gcmd, why = _merge_rule(cmd, cwd, root)
        why = why or _guard_shell(gcmd, cwd, who)
        if why:
            return True, why
        _note_engine_call(root, cmd, n.get("session"), n.get("input"))  # which chat runs `init` / `ask` / `wait` / `complete` here (_noted_session)
    if who["enforce"] and not n.get("agent_type") and _run_phase(root) == "building" and _orchestrator_edit(n, root):
        return True, ORCH_EDIT_MSG
    if n["kind"] == "write":
        for p in n["paths"]:
            why = _owner_problem(p, cwd, who)
            if why:
                return True, why
        bad = [p for p in n["paths"] if not _write_allowed(p, cwd)]
        if n["patch"] and not bad:
            bad = [p for p in re.findall(r"^\*\*\* (?:Add|Update|Delete) File: (.+)$", n["patch"], re.M)
                   if not _write_allowed(p, cwd)]
        if bad:
            return True, ("RATCHET GUARD: gate state, evidence, approvals and config under .ratchet/ are written by "
                          "ratchet.py only (you may write reviews/, states/, tests/, reference/, checkpoints.json, "
                          f"app-scout.json, standards.md, learnings.md). Blocked: {bad[0]}")
        _note_review_writer(n)
    return False, ""


def emit_hook(host: str, event: str, block: bool, message: str) -> int:
    """Answer in the host's dialect. Returns the process exit code."""
    if host == "copilot":
        if block and event == "guard":
            print(json.dumps({"permissionDecision": "deny", "permissionDecisionReason": message}))
        elif block and event == "stop":
            print(json.dumps({"decision": "block", "reason": message}))
        elif message and event != "prompt":
            print(message, file=sys.stderr)
        return 0
    if block:
        print(message, file=sys.stderr)
        return 2
    if message:
        if host == "claude" and event == "prompt":
            print(message)  # Claude Code adds UserPromptSubmit stdout to the model's context
        else:
            print(message, file=sys.stderr)
    return 0


def _hook_record_failed(n: dict, host: str, event: str, detail: str) -> str:
    """A hook could not save its hook-env record (or a director's folder record). Record it the way a hook crash is
    recorded (a crash marker, or the unsaved-crash fallback, plus a hook-errors.log line), so the hook counts as
    broken until a later run saves the record cleanly, and return the plain line the host shows."""
    saved = False
    root = _ratchet_root_of(n.get("cwd"))
    if root is not None:
        try:
            saved = _record_hook_run(root, host, event, crashed=True) or _record_unsaved_crash(root, host, event)
            _append_record(root / RATCHET_DIR / "hook-errors.log", f"{now()} {host} {event}: HookRecordError: {detail}\n")
        except Exception:
            pass
    line = (f"RATCHET: the {event} hook could not save which per-user folder, director key file and session role "
            f"this agent CLI uses ({detail}). Until a hook saves it, Ratchet refuses director commands here and "
            "won't trust a per-user folder it can't confirm. Make that file's folder writable; the next hook run "
            "writes it again.")
    if root is not None and not saved:
        line += (f" Ratchet could not save this failure either (it cannot write to {RATCHET_DIR}/{HOOK_CRASHES}/), "
                 "so run the doctor command.")
    return line


def run_hook(event: str, host_arg: str | None) -> int:
    data = _hook_input()
    host = detect_hook_host(data, host_arg)
    started = now()  # a clean run resolves only crashes recorded before it began
    global _IN_HOOK
    _IN_HOOK = True  # this process has the agent CLI's own environment: it is the one the engine compares against
    try:
        n = normalize_hook(data, host)
        record_failed = None  # remembering the folder must never break the hook itself, nor fail silently
        try:
            env_root = _ratchet_root_of(n.get("cwd"))
            if env_root is not None:
                if not record_hook_env(env_root, host, event, started):
                    record_failed = f"could not save {_hook_env_path(env_root)}"
            elif event == "guard" and _hook_role() == "director" and n.get("cwd"):
                if not record_director_folder(Path(str(n["cwd"]))):
                    record_failed = f"could not save {_director_folders_path()}"
        except Exception as e:
            record_failed = f"{type(e).__name__}: {e}"
        block, msg = {"stop": decide_stop, "prompt": decide_prompt, "guard": decide_guard}[event](n)
        if record_failed:  # the decision above still stands; the failure is recorded and said, never swallowed
            note = _hook_record_failed(n, host, event, record_failed)
            msg = f"{msg}\n{note}" if msg else note
        rc = emit_hook(host, event, block, msg)
        clean_root = _ratchet_root_of(n.get("cwd"))
        if clean_root is not None and not record_failed:
            _record_hook_run(clean_root, host, event, crashed=False, started=started)  # a clean run resolves this hook's crash
        return rc
    except (Exception, SystemExit) as e:  # guard/prompt fail OPEN — never brick the host session
        root, saved = None, True
        try:
            root = find_root(Path(data.get("cwd") or os.getcwd()))
            if (root / RATCHET_DIR).is_dir():
                saved = False
                saved = (_record_hook_run(root, host, event, crashed=True)  # first: an unwritable log must not hide it
                         or _record_unsaved_crash(root, host, event))  # durable fallback: unresolved, whatever its age
                _append_record(root / RATCHET_DIR / "hook-errors.log", f"{now()} {host} {event}: {type(e).__name__}: {e}\n")
        except Exception:
            pass
        if event == "stop" and root is not None and (root / RATCHET_DIR / "active.json").exists():
            try:  # stop fails CLOSED (a few times) — a corrupted state file must not end the loop quietly
                block, msg = _stop_error(root, f"Ratchet could not read its run state ({type(e).__name__}: {e}).")
                return emit_hook(host, event, block, msg)
            except Exception:
                pass
        if not saved:  # say it plainly where the host shows hook output; never block (fail open)
            try:
                return emit_hook(host, event, False, (
                    f"RATCHET: the {event} hook failed ({type(e).__name__}) and Ratchet could not save that failure "
                    f"(it cannot write to {RATCHET_DIR}/{HOOK_CRASHES}/), so its checks are not enforced. Make that "
                    "folder writable and run the doctor command."))
            except Exception:
                pass
        return 0


# ---- installing the hooks into each host ------------------------------------------------

def _hook_cmd(host, event):
    return f'python3 "{Path(__file__).resolve()}" hook {event} --host {host}'


def hook_config_path(host: str, scope: str, root: Path) -> Path:
    home = Path.home()
    return {
        ("claude", "project"): root / ".claude" / "settings.json",
        ("claude", "user"): home / ".claude" / "settings.json",
        ("codex", "project"): root / ".codex" / "hooks.json",
        ("codex", "user"): Path(os.environ.get("CODEX_HOME", home / ".codex")) / "hooks.json",
        ("gemini", "project"): root / ".gemini" / "settings.json",
        ("gemini", "user"): home / ".gemini" / "settings.json",
        ("copilot", "project"): root / ".github" / "hooks" / "ratchet.json",
        ("copilot", "user"): Path(os.environ.get("COPILOT_HOME", home / ".copilot")) / "hooks" / "ratchet.json",
    }[(host, scope)]


def _strip_ratchet(entries: list) -> list:
    def is_ours(e):
        return "ratchet.py" in json.dumps(e)
    out = []
    for e in entries or []:
        if isinstance(e, dict) and isinstance(e.get("hooks"), list):
            e = dict(e, hooks=[h for h in e["hooks"] if not is_ours(h)])
            if e["hooks"]:
                out.append(e)
        elif not is_ours(e):
            out.append(e)
    return out


def build_hook_config(host: str, existing: dict | None) -> dict:
    cfg = json.loads(json.dumps(existing or {}))
    stop_ev, prompt_ev, guard_ev = HOOK_EVENTS[host]
    if host == "copilot":
        cfg.setdefault("version", 1)
        hooks = cfg.setdefault("hooks", {})
        for ev, kind in ((stop_ev, "stop"), (prompt_ev, "prompt"), (guard_ev, "guard")):
            cmd = _hook_cmd(host, kind)
            hooks[ev] = _strip_ratchet(hooks.get(ev)) + [{
                "type": "command", "bash": cmd, "powershell": cmd.replace("python3 ", "python ", 1),
                "timeoutSec": 30}]
        return cfg
    hooks = cfg.setdefault("hooks", {})
    timeout = 30000 if host == "gemini" else 30  # Gemini counts milliseconds
    for ev, kind in ((stop_ev, "stop"), (prompt_ev, "prompt"), (guard_ev, "guard")):
        entry = {"hooks": [{"type": "command", "command": _hook_cmd(host, kind), "timeout": timeout}]}
        if host == "gemini":
            entry["hooks"][0]["name"] = f"ratchet-{kind}"
            if kind == "guard":
                entry["matcher"] = ".*"
        elif kind == "guard" and host == "claude":
            entry["matcher"] = ".*"
        hooks[ev] = _strip_ratchet(hooks.get(ev)) + [entry]
    return cfg


def cmd_install_hooks(args):
    root = find_root()
    hosts = HOOK_HOSTS if args.host == "all" else [
        VENDOR_TO_HOST.get(detect_host({}), "claude") if args.host == "auto" else args.host]
    for host in hosts:
        path = hook_config_path(host, args.scope, root)
        existing = read_json(path, {}) or {}
        if args.uninstall:
            new = json.loads(json.dumps(existing))
            for ev in list((new.get("hooks") or {}).keys()):
                new["hooks"][ev] = _strip_ratchet(new["hooks"][ev])
                if not new["hooks"][ev]:
                    del new["hooks"][ev]
        else:
            new = build_hook_config(host, existing)
        if args.dry_run:
            print(f"# {host}: {path}\n{json.dumps(new, indent=2)}")
            continue
        if host == "copilot" and args.uninstall and not (new.get("hooks")):
            if path.exists():
                path.unlink()
            ok(f"{host}: removed {path}")
            continue
        write_json(path, new)
        ok(f"{host}: {'removed Ratchet hooks from' if args.uninstall else 'hooks written to'} {path}")
        if host == "codex" and not args.uninstall:
            for toml in (root / ".codex" / "config.toml", Path.home() / ".codex" / "config.toml"):
                if toml.exists() and re.search(r"^\s*hooks\s*=\s*false", toml.read_text(), re.M):
                    print(f"  ! {toml} sets hooks = false — Codex will ignore these hooks until you remove it.")


def cmd_doctor(args):
    root = find_root()
    if getattr(args, "json", False):
        print(json.dumps({"hooks": hooks_status(root, _safe_config(root))}, indent=2))
        return
    cfg = _safe_config(root)
    hs = hooks_status(root, cfg)
    print(f"Host running this command: {hs['host']} (provider {detect_host(cfg)})")
    for h in HOOK_HOSTS:
        found = [f"{scope}: {p}" for scope, p in installed_hook_files(h, root)]
        if h in ("claude", "codex"):
            found.append("(or installed as a plugin — hooks/hooks.json)")
        print(f"  {h:<8} " + ("; ".join(found) if found else "not installed"))
    hb = read_heartbeat(root)
    hb_file = root / RATCHET_DIR / "hook-heartbeat.json"
    try:
        hb_raw = hb_file.read_text(errors="ignore").strip() if hb_file.exists() else ""
    except OSError:
        hb_raw = "?"  # directory / permission problem: report as unreadable below
    if not hb and hb_raw not in ("", "{}"):
        print("  hook-heartbeat.json unreadable (corrupt or not a JSON object) - delete it; the next hook run rewrites it.")
    elif hb:
        now = _dt.datetime.now(_dt.timezone.utc)
        for ev in ("guard", "prompt", "stop"):
            e = hb.get(ev)
            if isinstance(e, dict) and isinstance(e.get("at"), str) and isinstance(e.get("host"), str):
                t = _parse_iso(e["at"])
                fut = "  (future-dated: clock skew or bad entry; not counted as fresh)" if t and t > now + _dt.timedelta(minutes=5) else ""
                print(f"  last {ev:<6} hook: {e['at'][:19]}Z via {e['host']}{fut}")
            elif ev in hb:
                print(f"  last {ev:<6} hook: unreadable entry in hook-heartbeat.json")
            else:
                print(f"  last {ev:<6} hook: never fired in this project")
    else:
        print("  No Ratchet hook has fired in this project yet. Until one does, the gates are only advice:"
              " offer to set up the hooks for the user's agent CLI (ask first; a restart is needed afterwards).")
    if not _enforcement_active(root, cfg):
        print("  For the agent: offer to set up the hooks for the user's agent CLI (ask first; a restart is needed "
              "afterwards). Do not ask the user to run commands.")
    recent = hook_errors_view(root, hs["host"])
    if recent:
        broken = {h: crashed_hook_events(root, h) for h in {e["host"] for e in recent}}  # judged per host
        print("  recent hook errors, last 24 hours, newest first (hooks failed open):")
        for e in recent:
            still = "  (still broken: no clean run since)" if e["event"] in broken[e["host"]] else ""
            print(f"    {e['at'][:19]}Z {e['host']} {e['event']}: {e['message']}{still}")
    shown = {(e["host"], e["event"]) for e in recent}
    for e in unresolved_hook_crashes(root, hs["host"]):
        if (e["host"], e["event"]) not in shown:
            print(f"  {e['host']} {e['event']} hook crashed at {e['at'][:19]}Z and has not run cleanly since "
                  "(not among the recent errors listed); the next clean run of that hook on that host clears this.")
    problem = hook_crash_state_problem(root)
    if problem:
        print(f"  hook crash records: {problem}. Until it is fixed every hook counts as not working; fix its "
              "permissions (it must be readable and writable), or remove it if it is not a folder of crash markers.")
    elif any(((read_hook_crashes(root).get(h) or {}).get(ev) or {}).get("unresolved")
             for h, ev, _ in _unsaved_crashes(root) or []):
        print(f"  some hook crashes could not be saved in {RATCHET_DIR}/{HOOK_CRASHES}/ and were kept in "
              f"{RATCHET_DIR}/{HOOK_CRASHES_UNSAVED}; make that folder writable. Each clears on that hook's next "
              "clean run.")
    for rp, repair in ((_markers_path(), _active_runs_repair), (_enrolled_path(), _enrolled_repair)):
        _rd, rwhy = _read_record(rp)
        if rwhy is not None:  # per-user records that hold restrictions: never written over (_restriction_record_damaged)
            print(f"  {rp} can't be read ({rwhy}). It holds restrictions for other projects or lanes too, so Ratchet "
                  f"won't write over it. To repair it: {repair(rp)}.")


def _safe_config(root: Path) -> dict:
    """Config for read-only diagnostics: a corrupt config.json (read_json dies) counts as empty."""
    _cfg, why = _read_record(root / RATCHET_DIR / "config.json", kind=None)  # quiet pre-check: read_json die()s
    if why is not None:
        return {}
    try:
        return Ctx(root).config()
    except (Exception, SystemExit):
        return {}


def installed_hook_files(host: str, root: Path) -> list:
    """[(scope, path)] of config files that already contain Ratchet hooks for `host`. Single definition of 'installed'."""
    out = []
    if host not in HOOK_HOSTS:
        return out
    for scope in ("project", "user"):
        try:
            p = hook_config_path(host, scope, root)
            if p.exists() and "ratchet.py" in p.read_text(errors="ignore"):
                out.append((scope, p))
        except OSError:
            pass
    return out


def read_heartbeat(root: Path) -> dict:
    """Tolerant read: a corrupt or odd heartbeat file counts as empty."""
    hb, _why = _read_record(root / RATCHET_DIR / "hook-heartbeat.json")
    return hb or {}


def _parse_iso(v):
    try:
        t = _dt.datetime.fromisoformat(str(v).replace("Z", "+00:00"))
        return t if t.tzinfo else t.replace(tzinfo=_dt.timezone.utc)
    except Exception:
        return None


HOOK_ERROR_RE = re.compile(r"^(\S+) (\S+) (\w+): (.*)$")  # run_hook's line: "<iso time> <host> <event>: <detail>"
HOOK_ERRORS_SHOWN = 3


def read_hook_errors(root: Path, host: str = "unknown", hours: int = 24) -> list:
    """Hook crashes from .ratchet/hook-errors.log in the last `hours` (not more than 5 minutes in the future), for
    `host` (every host when 'unknown'), newest first: [{event, host, at, message}]. Tolerant: a missing, unreadable
    or garbage file, or any line that is not run_hook's format, counts as no error."""
    p = root / RATCHET_DIR / "hook-errors.log"
    try:
        with p.open("rb") as f:
            f.seek(0, os.SEEK_END)
            size = f.tell()
            f.seek(max(0, size - 65536))
            raw = f.read()
    except OSError:
        return []
    lines = raw.decode("utf-8", errors="replace").splitlines()
    if size > 65536 and lines:
        lines = lines[1:]  # the first line may be cut in half by the seek
    now_t = _dt.datetime.now(_dt.timezone.utc)
    cutoff, latest = now_t - _dt.timedelta(hours=hours), now_t + _dt.timedelta(minutes=5)
    out = []
    for line in lines:
        m = HOOK_ERROR_RE.match(line.strip())
        if not m:
            continue
        at, h, ev, msg = m.groups()
        t = _parse_iso(at) if "T" in at else None
        if not t or not (cutoff < t <= latest) or (host != "unknown" and h != host):
            continue
        out.append({"event": ev, "host": h, "at": at, "message": msg[:300], "_t": t})
    out.sort(key=lambda e: e["_t"], reverse=True)
    for e in out:
        e.pop("_t")
    return out


def hook_errors_view(root: Path, host: str) -> list:
    """The newest few recent hook errors, as carried by `next` and `status --json` (key `hook_errors`)."""
    return read_hook_errors(root, host)[:HOOK_ERRORS_SHOWN]


HOOK_CRASHES = "hook-crashes"  # a folder of empty marker files: one per recorded crash or clean run of a hook
HOOK_CRASHES_UNSAVED = "hook-crashes-unsaved.log"  # fallback, one line per crash whose marker could not be saved
_UNSAVED_RE = re.compile(r"^(\S+) ([A-Za-z0-9_-]+) (guard|stop|prompt)$")
_HOOK_MARK_RE = re.compile(r"^([A-Za-z0-9_-]+)\.(guard|stop|prompt)\.(crash|clean)\.(\d+)\.[A-Za-z0-9_-]+$")
_EPOCH = _dt.datetime(1970, 1, 1, tzinfo=_dt.timezone.utc)


def _iso_us(v) -> int:
    """An ISO time as whole microseconds since 1970 (exact; 0 when unreadable)."""
    t = _parse_iso(v)
    return (t - _EPOCH) // _dt.timedelta(microseconds=1) if t else 0


def _hook_marks(root: Path):
    """[(host, event, kind, microseconds, path)] for every marker in .ratchet/hook-crashes/; other names are ignored.
    The time lives in the name, so reading never opens a file another process may be creating or deleting.
    A missing folder means no crash was ever recorded ([]); a folder that cannot be listed gives None."""
    folder = root / RATCHET_DIR / HOOK_CRASHES
    try:
        names = os.listdir(folder)
    except FileNotFoundError:
        return []
    except OSError:
        return None
    out = []
    for n in names:
        m = _HOOK_MARK_RE.match(n)
        if m:
            out.append((m.group(1), m.group(2), m.group(3), int(m.group(4)), folder / n))
    return out


def _unsaved_crashes(root: Path):
    """[(host, event, microseconds)] from .ratchet/hook-crashes-unsaved.log: crashes whose marker could not be saved
    in hook-crashes/. [] when the file is missing; None when it exists but cannot be read."""
    try:
        text = (root / RATCHET_DIR / HOOK_CRASHES_UNSAVED).read_text(errors="replace")
    except FileNotFoundError:
        return []
    except OSError:
        return None
    out = []
    for line in text.splitlines():
        m = _UNSAVED_RE.match(line.strip())
        if m and _iso_us(m.group(1)):
            out.append((m.group(2), m.group(3), _iso_us(m.group(1))))
    return out


def _record_unsaved_crash(root: Path, host: str, event: str) -> bool:
    """Fallback when run_hook cannot save a crash marker: append one line (no read-modify-write), so the crash still
    counts as unresolved after its log line ages out. Returns False when this fails too: run_hook then tells the
    host, and readers count every hook as broken while the crash store refuses writes (_crash_store_unwritable)."""
    try:
        _append_record(root / RATCHET_DIR / HOOK_CRASHES_UNSAVED, f"{now()} {_mark_host(host)} {event}\n")
        return True
    except Exception:
        return False


def hook_crash_state_unreadable(root: Path):
    """Why the recorded crash state cannot be read (None when it can)."""
    if _hook_marks(root) is None:
        return f"{RATCHET_DIR}/{HOOK_CRASHES}/ cannot be read (not a folder, or no permission)"
    if _unsaved_crashes(root) is None:
        return f"{RATCHET_DIR}/{HOOK_CRASHES_UNSAVED} cannot be read"
    return None


def _crash_store_unwritable(root: Path):
    """Why Ratchet could not save a hook crash right now (None when it can), proven with a real write: create and
    delete a probe file where run_hook saves crash markers (in .ratchet/ itself, where that folder would be made,
    before the first crash). The probe name never matches a marker, so readers ignore it."""
    rdir = root / RATCHET_DIR
    if not rdir.is_dir():
        return None  # no Ratchet state here: nothing to record
    folder = rdir / HOOK_CRASHES
    where = folder if folder.is_dir() else rdir
    probe = where / f".write-probe.{os.getpid()}-{secrets.token_hex(4)}"
    try:
        with open(probe, "x"):
            pass
    except OSError:
        return f"{RATCHET_DIR}/{HOOK_CRASHES}/ cannot be written (no permission, read-only or full disk)"
    try:
        probe.unlink()
    except OSError:
        pass
    return None


def hook_crash_state_problem(root: Path):
    """Why Ratchet cannot trust its crash records (None when it can). Fail closed: a hook counts as working only while
    Ratchet can both read and save its crash state, so while either fails every hook counts as broken: the records
    cannot be read, or they cannot be written right now (a crash would be lost). Known limit (schemas.md section 10):
    a crash at a moment when neither crash store can be written leaves no lasting record, so it counts as broken
    only while the writes are refused; no shared file is ever rewritten to remember it."""
    return hook_crash_state_unreadable(root) or _crash_store_unwritable(root)


def read_hook_crashes(root: Path) -> dict:
    """{host: {event: {crashed_at?, clean_at?, unresolved}}} from the markers run_hook leaves in
    .ratchet/hook-crashes/ (plus the fallback hook-crashes-unsaved.log): the newest crash and the newest clean run of
    each hook on each host. A crash is unresolved until a clean run that started after it. Missing or unreadable
    files count as empty here; hook_crash_state_problem reports unreadable ones, and they make every hook broken."""
    newest: dict = {}
    marks = [m[:4] for m in _hook_marks(root) or []]
    marks += [(h, ev, "crash", us) for h, ev, us in _unsaved_crashes(root) or []]
    for h, ev, kind, us in marks:
        rec = newest.setdefault(h, {}).setdefault(ev, {})
        rec[kind] = max(rec.get(kind, 0), us)

    def iso(us):
        return (_EPOCH + _dt.timedelta(microseconds=us)).isoformat(timespec="microseconds")
    out: dict = {}
    for h, evs in newest.items():
        for ev, rec in evs.items():
            crash, clean = rec.get("crash"), rec.get("clean")
            r = {"unresolved": bool(crash) and not (clean and clean > crash)}
            if crash:
                r["crashed_at"] = iso(crash)
            if clean:
                r["clean_at"] = iso(clean)
            out.setdefault(h, {})[ev] = r
    return out


def _mark_host(host) -> str:
    return re.sub(r"[^A-Za-z0-9_-]", "_", str(host)) or "unknown"


def _record_hook_run(root: Path, host: str, event: str, crashed: bool, started: str | None = None) -> bool:
    """Crash state per (host, event), kept apart from the 24-hour log window: a crash stays unresolved until that
    same hook, on that same host, runs cleanly in a call that started after it. No file is ever read, changed and
    written back, so concurrent hooks cannot erase each other's records: each run only creates its own uniquely
    named empty marker (exclusive create, the same on every OS), then deletes markers it supersedes, which never
    changes the outcome: a crash removes that hook's older crash markers; a clean run removes that hook's older
    crash and clean markers. `started` is when the clean run began, so a crash recorded while it ran stays
    unresolved. A clean run writes only when it resolves a recorded crash (the hot path stays read-only otherwise).
    Returns False when the record could not be saved (run_hook then falls back to hook-crashes-unsaved.log)."""
    try:
        h = _mark_host(host)
        at = _iso_us(started or now())
        if not at:
            return False
        if not crashed:
            rec = (read_hook_crashes(root).get(h) or {}).get(event) or {}
            if not rec.get("unresolved") or _iso_us(rec.get("crashed_at")) >= at:
                return True  # nothing to resolve, or that crash came after this run started
        kind = "crash" if crashed else "clean"
        folder = root / RATCHET_DIR / HOOK_CRASHES
        folder.mkdir(parents=True, exist_ok=True)
        with open(folder / f"{h}.{event}.{kind}.{at}.{os.getpid()}-{secrets.token_hex(4)}", "x"):
            pass
        for mh, mev, mkind, us, path in _hook_marks(root) or []:
            if (mh, mev) == (h, event) and us < at and (mkind == "crash" or not crashed):
                try:
                    path.unlink()
                except OSError:
                    pass  # another run removed it first, or (Windows) it is busy: a stale marker changes nothing
        return True
    except Exception:
        return False


def _ratchet_root_of(cwd) -> Path | None:
    """The nearest ancestor of `cwd` holding .ratchet (no git call: this runs on every clean hook)."""
    try:
        p = Path(str(cwd or os.getcwd())).resolve()
        return next((c for c in [p, *p.parents] if (c / RATCHET_DIR).is_dir()), None)
    except Exception:
        return None


def unresolved_hook_crashes(root: Path, host: str, crashes=None) -> list:
    """Crashes run_hook recorded that the same hook on the same host has not yet run cleanly after, whatever their
    age, for `host` (every host when 'unknown'), newest first: [{event, host, at}]."""
    crashes = read_hook_crashes(root) if crashes is None else crashes
    out = [{"event": ev, "host": h, "at": str(r.get("crashed_at") or "")}
           for h, evs in crashes.items() if host in ("unknown", h)
           for ev, r in evs.items() if r.get("unresolved") is True]
    old = _dt.datetime.min.replace(tzinfo=_dt.timezone.utc)
    return sorted(out, key=lambda e: _parse_iso(e["at"]) or old, reverse=True)


def broken_hooks(root: Path, host: str, hb=None, errors=None, crashes=None) -> list:
    """Hooks that broke on their last run, judged per (host, event) so one host never clears another's crash:
    (a) a crash recorded by run_hook with no clean run of that hook on that host since, however old; or (b) a recent
    logged crash with no later clean run (hook-crashes/) or heartbeat from that same host (the heartbeat is
    written before the decision, so a crash in the same call is logged after it). Newest first: [{event, host, at}],
    `at` being its latest known crash."""
    hb = read_heartbeat(root) if hb is None else hb
    errors = read_hook_errors(root, host) if errors is None else errors
    crashes = read_hook_crashes(root) if crashes is None else crashes
    old = _dt.datetime.min.replace(tzinfo=_dt.timezone.utc)
    out = {(e["host"], e["event"]): e for e in unresolved_hook_crashes(root, host, crashes)}
    done = set()
    for e in errors:  # newest first, so the first error per (host, event) is its latest
        h, ev = e["host"], e["event"]
        if (h, ev) in done:
            continue
        done.add((h, ev))
        et = _parse_iso(e["at"])
        ct = _parse_iso(((crashes.get(h) or {}).get(ev) or {}).get("clean_at"))
        if ct and et and ct > et:
            continue  # that hook ran cleanly on that host after this crash
        beat = hb.get(ev)
        bt = _parse_iso(beat.get("at")) if isinstance(beat, dict) and beat.get("host") == h else None
        if not bt or (et and et >= bt):
            prev = out.get((h, ev))
            if not prev or (et or old) > (_parse_iso(prev["at"]) or old):
                out[(h, ev)] = {"event": ev, "host": h, "at": e["at"]}
    return sorted(out.values(), key=lambda e: _parse_iso(e["at"]) or old, reverse=True)


def crashed_hook_events(root: Path, host: str, hb=None, errors=None, crashes=None) -> set:
    """Events whose hook broke on its last run (see broken_hooks). Fail safe: while the recorded crash state cannot
    be read, every hook counts as broken."""
    if hook_crash_state_problem(root):
        return set(HOOK_EVENT_PLAIN)
    return {b["event"] for b in broken_hooks(root, host, hb, errors, crashes)}


def hooks_status(root: Path, cfg=None) -> dict:
    """Read-only: {host, installed, heartbeat_seen, fresh, missing} for the CLI running this command."""
    # Unknown host (e.g. unrecognised host_provider): we cannot tell which CLI this is, so a heartbeat from ANY
    # host counts as evidence that hooks run in this project. Documented; doctor prints the host as "unknown".
    host = VENDOR_TO_HOST.get(detect_host(cfg or {}), "unknown")
    installed = bool(installed_hook_files(host, root))
    hb = read_heartbeat(root)
    entries = [e for e in hb.values()
               if isinstance(e, dict) and (host == "unknown" or e.get("host") == host)]
    now = _dt.datetime.now(_dt.timezone.utc)
    cutoff, latest = now - _dt.timedelta(hours=24), now + _dt.timedelta(minutes=5)  # future-dated is not fresh
    fresh = False
    for e in entries:
        t = _parse_iso(e.get("at"))
        if t and cutoff < t <= latest:
            fresh = True

    def _fresh(ev):
        e = hb.get(ev)
        if not (isinstance(e, dict) and (host == "unknown" or e.get("host") == host)):
            return False
        t = _parse_iso(e.get("at"))
        return bool(t and cutoff < t <= latest)
    # enforcing: the guard or stop hook fired recently (these are what enforce the gates) and neither broke on its
    # last run; prompt_hook: the prompt hook fired recently and did not break (it only records the user's replies)
    crashed = crashed_hook_events(root, host, hb)
    enforcing = (_fresh("guard") or _fresh("stop")) and not (crashed & {"guard", "stop"})
    return {"host": host, "installed": installed, "heartbeat_seen": bool(entries), "fresh": fresh,
            "enforcing": enforcing, "prompt_hook": _fresh("prompt") and "prompt" not in crashed,
            "missing": not installed and not enforcing}


def hooks_warning(ctx, hs=None) -> str | None:
    """Used by `next`/status: gates without hooks are just advice. Phrased for the agent, not the user."""
    hs = hs or hooks_status(ctx.root, ctx.config())
    if hs.get("waived"):
        return None  # the user already chose to build without hooks; do not re-offer
    if hs.get("enforcing"):
        return None  # only guard/stop heartbeats count: the prompt hook alone enforces nothing
    problem = hook_crash_state_problem(ctx.root)
    if problem and hook_crash_state_unreadable(ctx.root):
        return (f"Ratchet cannot read its hook crash records ({problem}), so it counts the safety hooks as not "
                "working and the gates as not enforced. Run the doctor command, fix or remove that file, and tell "
                "the user in one plain sentence.")
    if problem:
        return (f"Ratchet cannot save its hook crash records ({problem}), so a hook crash could go unrecorded and it "
                "counts the safety hooks as not working and the gates as not enforced. Run the doctor command, make "
                "that folder writable, and tell the user in one plain sentence.")
    if crashed_hook_events(ctx.root, hs.get("host", "unknown")) & {"guard", "stop"}:
        return ("A Ratchet safety hook broke on its last run and let the action through (see hook_errors), so the "
                "gates are not enforced right now. Run the doctor command to see the error, fix the cause, and tell "
                "the user in one plain sentence. The next clean hook run restores enforcement.")
    if hs["installed"]:
        return ("Ratchet hooks are installed for this agent CLI but none has fired recently. Tell the user the "
                "agent CLI probably needs a restart (and, for Codex, hooks enabled) so the gates are enforced.")
    return ("No Ratchet hook has fired in this project yet, so the gates are only advice. Offer to set up the "
            "hooks for this agent CLI (the install-hooks command), ask the user first, and tell them a restart "
            "is needed afterwards. If they would rather not, ask the hooks-waive question, tell them in one plain "
            "sentence that the gates would then only be advice, and after their clear yes record it with the "
            "hooks-waive command. The doctor command shows the details.")



# --------------------------------------------------------------------------- main

# Every command that changes a run holds one exclusive lock file, state.lock in the Ratchet folder, for its WHOLE run:
# from before its first read of state.json to after its last write, its test runs, checks, regression suite and
# provider probes included. So two commands never interleave and none can overwrite what another wrote meanwhile (a
# double submit, an approval made during a test run): the second one waits for a short command to finish
# (STATE_LOCK_WAIT_SECONDS), then reads what it wrote; behind a long one (LONG_LOCKED_CMDS) it refuses after a moment
# (STATE_LOCK_BUSY_WAIT_SECONDS) with "Ratchet is busy running <command>; try again when it finishes" and changes
# nothing. The lock file names the command holding it. The hooks never wait on it and never write state.json.
# A lock not refreshed for STATE_LOCK_STALE_SECONDS (more than the longest test run, test_timeout_sec, plus a margin)
# is left over from a crashed command and is removed; a live command refreshes its lock while it runs.
STATE_LOCKED_CMDS = ("init", "plan-submit", "approve-plan", "tests-written", "red", "implemented", "behavior",
                     "ui-record", "adv-record", "complete", "human-approve", "feedback", "plan-extend", "pause",
                     "resume", "ask", "accept-state", "hooks-waive", "cancel", "set-review", "choice", "ui-respec",
                     "approve-changes", "guardrail", "reviewers", "repeats", "spec", "wait", "accept-finding",
                     "raise-limit", "check-in", "triage", "merged", "accept-line", "shortcuts")
LONG_LOCKED_CMDS = ("red", "behavior", "complete", "reviewers", "providers", "merged", "shortcuts")  # tests, checks, a regression
                                                                                          # suite, provider probes (--add included)
# The commands that may take a person's RATCHET_HUMAN_OVERRIDE code: asked BEFORE the lock, so nothing waits on them.
OVERRIDE_CMDS = ("approve-plan", "human-approve", "approve-changes", "cancel", "set-review", "resume", "hooks-waive",
                 "ui-respec", "choice", "feedback", "accept-state", "init")
STATE_LOCK_WAIT_SECONDS = 30
STATE_LOCK_BUSY_WAIT_SECONDS = 2
STATE_LOCK_STALE_MARGIN_SECONDS = 300
STATE_LOCK_STALE_SECONDS = DEFAULT_CONFIG["test_timeout_sec"] + STATE_LOCK_STALE_MARGIN_SECONDS
STATE_LOCK_REFRESH_SECONDS = 30


def _changes_state(args) -> bool:
    """Whether this command may change the run (and so runs under the state lock)."""
    if args.cmd == "repeats":
        return bool(getattr(args, "offered", None))
    if args.cmd == "spec":
        return getattr(args, "spec_cmd", None) in ("import", "keep")
    if args.cmd == "director-sign":
        # --apply asks, signs and applies in one call: locked for the whole of it, so the token it signs cannot go
        # stale between the ask and the apply, and two applies at once never both apply. Signing alone reads only.
        return bool(getattr(args, "apply", False))
    if args.cmd == "providers":
        # --add is the only form that can consume the developer's one-time paid-provider OK (_consume_paid_ok)
        # and send a real test request; locking it the same way every other question-consuming command is
        # locked means two `providers --add` calls for the same tool/model never both spend that one OK.
        return bool(getattr(args, "add", None))
    return args.cmd in STATE_LOCKED_CMDS


def _lock_stale_seconds(root: Path) -> float:
    """A live command can hold the lock through a whole test run (test_timeout_sec): only a lock older than that,
    plus a margin, is stale."""
    cfg, _why = _read_record(root / RATCHET_DIR / "config.json")  # a damaged config: the default stale age
    try:
        t = float((cfg or {}).get("test_timeout_sec") or 0)
    except (TypeError, ValueError):
        t = 0
    return max(STATE_LOCK_STALE_SECONDS, t + STATE_LOCK_STALE_MARGIN_SECONDS)


def _lock_pause():
    time.sleep(0.05)


def _lock_host() -> str:
    """This machine's name as written into a state lock ('' when it has none or has a space in it: such a lock is
    written without it and keeps the timed rule)."""
    try:
        host = socket.gethostname()
    except OSError:
        return ""
    return "" if not host or re.search(r"\s", host) else host


def _lock_where() -> tuple[str, str]:
    """(pid namespace, boot id) of this process as written into a state lock: 'pid:[4026531836]' from
    /proc/self/ns/pid and the contents of /proc/sys/kernel/random/boot_id. A process id means something only inside
    one pid namespace on one boot (an agent's sandbox on Linux has its own namespace but the same machine name), so
    a part that can't be read comes back '' and the lock is written without it (it keeps the timed rule)."""
    if not sys.platform.startswith("linux"):
        return "", ""
    try:
        ns = os.readlink("/proc/self/ns/pid")
    except OSError:
        ns = ""
    try:
        boot = Path("/proc/sys/kernel/random/boot_id").read_text(encoding="ascii").strip()
    except (OSError, ValueError):
        boot = ""
    return ("" if re.search(r"\s", ns) else ns), ("" if re.search(r"\s", boot) else boot)


def _lock_fields(parts: list[str]) -> tuple[str, str, str, list[str]]:
    """Split lock text words `<pid> <token> [@host] [pidns=..] [boot=..] <command...>` into (host, pid namespace,
    boot id, the command's words); a missing field is ''."""
    host = ns = boot = ""
    rest = parts[2:]
    if rest and rest[0].startswith("@"):
        host, rest = rest[0][1:], rest[1:]
        if rest and rest[0].startswith("pidns="):
            ns, rest = rest[0][6:], rest[1:]
        if rest and rest[0].startswith("boot="):
            boot, rest = rest[0][5:], rest[1:]
    return host, ns, boot, rest


def _pid_is_ratchet(pid: int) -> bool | None:
    """Whether process `pid` on this machine is a live ratchet.py command: False when it is gone (or a zombie) or is a
    non-python program that was handed the same id; None when that can't be told (not Linux, /proc can't be read or is
    another namespace's, an empty command line, or any python process that is not running ratchet.py: python -c,
    python -m, a copy of the script under another name)."""
    if pid == os.getpid():
        return True
    try:
        # a mounted /proc that is another pid namespace's (a bound host /proc) says nothing about our process ids
        if not sys.platform.startswith("linux") or int(os.readlink("/proc/self")) != os.getpid():
            return None
    except (OSError, ValueError):
        return None
    try:
        argv = [a for a in Path(f"/proc/{pid}/cmdline").read_bytes().split(b"\0") if a]
        if not argv:  # a zombie is gone; a process that is not yet or no longer showing its arguments is not judged
            return False if Path(f"/proc/{pid}/stat").read_bytes().rpartition(b")")[2].split()[:1] == [b"Z"] else None
    except (FileNotFoundError, ProcessLookupError):
        return False
    except OSError:
        return None
    if any(os.path.basename(a) == b"ratchet.py" for a in argv):
        return True
    return None if re.match(rb"python[0-9.]*(\.exe)?$", os.path.basename(argv[0])) else False


class _StateLock(_BreakerLock):
    """O_CREAT|O_EXCL lock file, state.lock in the Ratchet folder (works the same on POSIX and Windows), around one
    command. Every failure to take it (another command holds it, the folder can't be written, something other than a
    lock file sits at that path) is retried after a pause until the wait runs out, then refused with a plain message;
    behind a long command the wait is cut short. The breaker protocol is _BreakerLock's, shared with the per-user locks: the lock file is only ever removed
    (a stale one, or an owner releasing its own) while holding a second O_EXCL file, state.lock.break, so the file
    judged stale is the file removed: two waiters can't both clear it, and none can remove a newer, live lock; a
    breaker file left by a process that died is cleared after BREAKER_STALE seconds. With `refresh`, the holder
    touches its lock while it runs, so a long, live command is never judged stale. With `create_dir` (init: the
    first command of a project), the Ratchet folder is made first, so two first inits are serialised like every
    other command instead of both running unlocked. The lock text is `<pid> <token> @<machine> pidns=<pid namespace>
    boot=<boot id> <command>`; on Linux, a lock whose machine, boot and pid namespace are this process's and whose
    process is gone (or is some other non-python program) is stale at once, not after the timed limit. An older lock
    text, one from another machine, another system than Linux, or a process that can't be told keeps the timed rule."""

    def __init__(self, root: Path, wait: float | None = None, cmd: str | None = None, refresh: bool = False,
                 create_dir: bool = False):
        host = _lock_host()  # "@<this machine's name>": what lets a later command judge whether this process is gone
        ns, boot = _lock_where() if host else ("", "")  # ... but only in the same pid namespace on the same boot
        super().__init__(root / RATCHET_DIR / "state.lock",
                         f"{os.getpid()} {secrets.token_hex(8)}" + (f" @{host}" if host else "")
                         + (f" pidns={ns}" if ns else "") + (f" boot={boot}" if boot else "") + (f" {cmd}" if cmd else ""))
        self.root = root
        self.create_dir = create_dir
        self.wait = wait
        self.refresh = refresh
        self._beat = None
        self.holder = None  # the command holding the lock at the last try (None: not known)
        self._cleared = False  # the last try cleared a leftover lock, so the next try need not wait

    def _stale_after(self) -> float:
        return _lock_stale_seconds(self.root)

    def _pause(self):
        _lock_pause()

    def _cant(self, e: OSError) -> str:
        return (f"Ratchet could not use its lock file {self.path} ({type(e).__name__}: {e.strerror or e}), so nothing "
                f"was done. Check that {self.path.parent} is a folder you can write to, then run this command again.")

    def _holder_cmd(self) -> str | None:
        """The command named in the lock file (None for a lock that names none, or no regular lock file)."""
        try:
            if not stat.S_ISREG(os.lstat(self.path).st_mode):
                return None
            parts = self.path.read_text(encoding="utf-8", errors="replace").split()
        except OSError:
            return None
        rest = _lock_fields(parts)[3]  # the machine's name, pid namespace and boot id are not part of the command
        return " ".join(rest) if rest else None

    def _owner_alive(self) -> bool | None:
        """Whether the process named in the lock text is a live ratchet.py command: False when the text says this
        machine and that process is provably gone, True when it is live, None when that can't be told (older text,
        another machine, not Linux, unreadable): the timed rule."""
        try:
            parts = self.path.read_text(encoding="utf-8", errors="replace").split()
        except OSError:
            return None
        host = _lock_host()
        ns, boot = _lock_where()
        lhost, lns, lboot, _rest = _lock_fields(parts)
        # the id means something only on the same machine, same boot and same pid namespace; any other or missing: unknown
        if (len(parts) < 3 or not host or lhost != host or not ns or lns != ns or not boot or lboot != boot
                or not parts[0].isdigit() or int(parts[0]) <= 0):
            return None
        return _pid_is_ratchet(int(parts[0]))

    def _owner_gone(self) -> bool:
        return self._owner_alive() is False

    def live_holder(self) -> str | None:
        """Who holds a live (not stale) lock right now, without waiting or changing anything; None when no command
        does."""
        try:
            st = os.lstat(self.path)
        except OSError:
            return None
        if not stat.S_ISREG(st.st_mode) or self._is_stale(st):
            return None
        return self._holder_cmd() or "another Ratchet command"

    def _why_busy(self) -> str:
        """Why the lock file exists. A stale lock is cleared first (under the breaker file); the caller retries."""
        self.holder = self._holder_cmd()
        stale_after = _lock_stale_seconds(self.root)
        busy = (f"Ratchet is busy running {self.holder or 'another command'}; try again when it finishes. Nothing was "
                f"done: another Ratchet command is still changing this run (lock file {self.path}).")
        if self._owner_alive() is not True:  # its owner can't be checked: say how an old lock goes away
            busy += (f" If no Ratchet command is running, the lock clears itself {int(stale_after // 60)} minutes "
                     f"after its command last refreshed it, or remove {self.path}.")
        try:
            st = os.lstat(self.path)
        except FileNotFoundError:
            return busy  # released just now: the next try takes it
        except OSError as e:
            return self._cant(e)
        if not stat.S_ISREG(st.st_mode):
            return (f"Ratchet's lock file {self.path} is not a file Ratchet made (a folder or a link sits there), so "
                    "nothing was done. Remove it, then run this command again.")
        if not self._is_stale(st):
            return busy
        try:  # judged again while holding the breaker file: nobody else can remove it meanwhile
            if self._clear_stale():
                self._cleared = True  # gone now: the caller takes the lock at once
                return busy
        except OSError as e:
            return self._cant(e)
        return (f"A lock file left by a Ratchet command that stopped ({self.path}) could not be cleared, so nothing "
                f"was done. If no other Ratchet command is running, remove {self.path} and {self.breaker} (if it "
                "is there), then run this command again.")

    def acquire(self) -> str | None:
        """None once the lock is held (or there is no Ratchet folder, so no state to protect); otherwise, once the
        wait runs out, the reason it could not be taken. Never raises for a file-system error."""
        if self.create_dir:
            try:
                self.path.parent.mkdir(exist_ok=True)
            except OSError as e:
                return self._cant(e)
        if not self.path.parent.is_dir():
            return None  # no Ratchet folder: there is no state to protect (the command says so itself)
        start = time.monotonic()
        deadline = start + (STATE_LOCK_WAIT_SECONDS if self.wait is None else self.wait)
        while True:
            try:
                self._create(self.path)
                self.held = True
                self._start_refresh()
                return None
            except FileExistsError:
                self._cleared = False
                why = self._why_busy()
                if self._cleared:
                    continue  # a leftover lock was just removed: take it now, whatever the wait
                if self.holder in LONG_LOCKED_CMDS:  # it may run for many minutes: refuse rather than wait it out
                    deadline = min(deadline, start + STATE_LOCK_BUSY_WAIT_SECONDS)
            except OSError as e:
                why = self._cant(e)
            if time.monotonic() >= deadline:
                return why
            _lock_pause()

    def _start_refresh(self):
        if not self.refresh:
            return
        import threading
        done = threading.Event()

        def beat():
            while not done.wait(STATE_LOCK_REFRESH_SECONDS):
                try:
                    if self.path.read_text(encoding="utf-8") == self.token:
                        os.utime(self.path, None)
                except OSError:
                    pass
        threading.Thread(target=beat, daemon=True).start()
        self._beat = done

    def release(self):
        """Remove the lock file if it is still this command's own, under the breaker file. When the breaker can't be
        had within a few seconds the lock is left in place (it goes stale and is cleared later): a lock that might
        not be ours is never removed."""
        if self._beat is not None:
            self._beat.set()
            self._beat = None
        if not self.held:
            return
        self.held = False
        self._release_own(5)

    def __enter__(self):
        why = self.acquire()
        if why:
            die(why)
        return self

    def __exit__(self, *exc):
        self.release()
        return False


class _IntegrateLock(_StateLock):
    """The one-integrate-at-a-time lock: a lock file in the repository's git common dir (shared by the main checkout and
    every lane worktree), built like the state lock so it is cleared at once when the integrate that made it was
    killed (_StateLock's dead-owner check), and refused quickly as busy while a live one runs."""

    def __init__(self, main: Path, common: Path, cmd: str):
        super().__init__(main, wait=STATE_LOCK_BUSY_WAIT_SECONDS, cmd=cmd, refresh=True)
        self.path = common / "ratchet-integrate.lock"


def _may_use_override(args) -> bool:
    """Whether this command may ask for the RATCHET_HUMAN_OVERRIDE code (it reaches human_override): it is asked
    before the state lock is taken."""
    if os.environ.get("RATCHET_HUMAN_OVERRIDE") != "1" or args.cmd not in OVERRIDE_CMDS:
        return False
    if args.cmd == "init":  # only replacing a run that is still active asks for it
        return bool(getattr(args, "force", False)) and bool(Ctx(find_root()).active_slug())
    return not getattr(args, "director_token", None) and not (args.cmd == "resume" and not args.claim)


# --------------------------------------------------------------------------- CI export

CI_WORKFLOW_HEADER = (
    "# Generated by Ratchet (ratchet.py ci-export)\n"
    "#\n"
    "# This workflow runs the mechanical checks this project's Ratchet run relied on: the regression\n"
    "# command (or, lacking one, completed steps' own test commands) and every automatic check saved\n"
    "# from a guardrail step.\n"
    "#\n"
    "# It does not run Ratchet's AI review gates (adversarial review, UI review, human review). CI\n"
    "# machines don't have the agent CLIs and credentials those gates need, so those gates stay a\n"
    "# step a person or an agent runs, not a CI job.\n"
    "#\n"
    "# To regenerate this file, ask your agent to run Ratchet's CI export; don't edit it by hand.\n"
)


_NOTED_BAD_SHAPE = set()


def _note_bad_shape(path: Path, why: str, outcome: str):
    """Say plainly, on stderr, that one of Ratchet's own records held the wrong JSON shape and what
    ci-export did instead (once per file and cause in a process). Worded like read_json's record= notes,
    but for a file that parsed fine yet doesn't hold the shape expected at that point."""
    key = (str(path), why, outcome)
    if key in _NOTED_BAD_SHAPE:
        return
    _NOTED_BAD_SHAPE.add(key)
    print(f"ratchet: {path} {why}; {outcome}", file=sys.stderr)


def _ci_step_tests(ctx: Ctx) -> list:
    """Completed steps' own tests.command, across every run under runs/, ordered by that run's created_at
    (not its folder name) and then by the checkpoint order its own checkpoints.json saved. Each run's
    checkpoints.json gives a checkpoint's tests.command; its state.json says which checkpoints are done.
    A run folder whose state.json or checkpoints.json doesn't hold the shape expected is skipped whole, with
    a plain stderr note naming the file; a single malformed checkpoint entry or item inside an otherwise
    well-shaped run is skipped on its own, with its own note, leaving the run's other checkpoints intact."""
    runs_dir = ctx.ratchet / "runs"
    if not runs_dir.is_dir():
        return []
    runs = []
    for run_dir in sorted(p for p in runs_dir.iterdir() if p.is_dir()):
        state_path = run_dir / "state.json"
        plan_path = run_dir / "checkpoints.json"
        state = read_json(state_path, {},
                           record="ci-export skips this run folder's step tests") or {}
        plan = read_json(plan_path, {},
                          record="ci-export skips this run folder's step tests") or {}
        if not isinstance(state, dict) or not isinstance(plan, dict):
            continue
        if "checkpoints" not in state:
            done = {}
        else:
            done = state.get("checkpoints")
            if not isinstance(done, dict):
                _note_bad_shape(state_path, "holds a \"checkpoints\" value that isn't an object",
                                 "ci-export skips this run folder's step tests")
                continue
        if "checkpoints" not in plan:
            plan_checkpoints = []
        else:
            plan_checkpoints = plan.get("checkpoints")
            if not isinstance(plan_checkpoints, list):
                _note_bad_shape(plan_path, "holds a \"checkpoints\" value that isn't a list",
                                 "ci-export skips this run folder's step tests")
                continue
        runs.append((str(state.get("created_at") or ""), run_dir.name, done, plan_checkpoints, state_path,
                     plan_path))
    runs.sort(key=lambda r: (r[0], r[1]))
    out = []
    for _created, slug, done, plan_checkpoints, state_path, plan_path in runs:
        for cp in plan_checkpoints:
            if not isinstance(cp, dict):
                _note_bad_shape(plan_path, "has a \"checkpoints\" item that isn't an object",
                                 "ci-export skips that checkpoint's step test")
                continue
            cp_id = cp.get("id")
            if not isinstance(cp_id, str) or not cp_id:
                _note_bad_shape(plan_path, "has a \"checkpoints\" item whose \"id\" isn't a nonempty string",
                                 "ci-export skips that checkpoint's step test")
                continue
            if cp_id not in done:
                continue
            entry = done[cp_id]
            if not isinstance(entry, dict):
                _note_bad_shape(state_path, f"has a \"{cp_id}\" checkpoint entry that isn't an object",
                                 "ci-export skips that checkpoint's step test")
                continue
            if entry.get("status") != "done":
                continue
            if "tests" not in cp:
                continue
            tests = cp["tests"]
            if not isinstance(tests, dict):
                _note_bad_shape(plan_path, f"has a \"{cp_id}\" checkpoint whose \"tests\" value isn't an object",
                                 "ci-export skips that checkpoint's step test")
                continue
            command = tests.get("command") or ""
            command = command.strip() if isinstance(command, str) else ""
            if command:
                out.append({"name": f"{slug} {cp_id} tests", "command": command})
    return out


def ci_commands(ctx: Ctx) -> list:
    """The platform-neutral, ordered, deduplicated list of commands a CI workflow should run: the project's
    regression command first, then every saved automatic check (config `checks`, in saved order); a
    completed step's own tests.command (gathered by _ci_step_tests, run order then saved checkpoint order)
    is added only when there is no regression command. Exact duplicate command text collapses to its first
    occurrence. Each entry: {"name", "command", "note"} where `note` is a short comment for a command that
    may need a running app/service CI does not start, or None."""
    cfg = ctx.config()
    app = cfg.get("app") or {}
    app_note = ("this command may need a running app or service (config app.start_command/app.url is "
                "set); CI does not start it") if (app.get("start_command") or app.get("url")) else None
    regression = cfg.get("regression_command")
    regression = regression.strip() if isinstance(regression, str) else ""
    entries = []
    if regression:
        entries.append({"name": "Regression", "command": regression, "note": app_note})
    for chk in cfg.get("checks") or []:
        command = chk.get("command") if isinstance(chk, dict) else None
        if not isinstance(command, str) or not command.strip():
            continue
        entries.append({"name": (chk.get("title") or chk.get("kind") or "Check") if isinstance(chk, dict) else "Check",
                         "command": command, "note": app_note})
    if not regression:
        for e in _ci_step_tests(ctx):
            entries.append({"name": e["name"], "command": e["command"], "note": app_note})
    seen = set()
    out = []
    for e in entries:
        if e["command"] in seen:
            continue
        seen.add(e["command"])
        out.append(e)
    return out


def _ci_setup_steps(ctx: Ctx, commands: list) -> str:
    """Setup steps chosen from the project's own files: Python (actions/setup-python) when there is a
    pyproject.toml, requirements*.txt, setup.py, or a command starting with python/python3; Node
    (actions/setup-node plus npm ci, pnpm or yarn by lockfile) when there is a package.json. Either, both
    or neither may apply; this never guesses a language the project has no sign of.

    Dependency installation, each independent of the others (neither suppresses the other):
    - requirements.txt (that exact name) installs with `python -m pip install -r requirements.txt`. Any
      other requirements*.txt files are named in a YAML comment instead of installed.
    - a pyproject.toml containing a `[build-system]` table installs with `python -m pip install -e .`,
      after the requirements line when both are present. A pyproject.toml without `[build-system]` (for
      example one holding only tool config such as pytest or Ruff settings) installs nothing from it.
    - when neither of the above emits an install, a plain comment says to add dependency setup, naming
      any pyproject.toml, setup.py, uv.lock or poetry.lock found, since guessing one would be wrong as
      often as right.

    Node: `npm ci` when a package-lock.json or npm-shrinkwrap.json is present; `npm install` when
    package.json has no lockfile at all. `pnpm-lock.yaml` gets pnpm/action-setup@v4 plus `pnpm install
    --frozen-lockfile` only when package.json's `packageManager` field starts with `pnpm@` (the version
    that action needs); otherwise just setup-node plus a comment to add the project's own pnpm setup.
    `yarn.lock` gets setup-node plus a comment (yarn 1 and yarn berry differ), no corepack."""
    root = ctx.root
    req_files = sorted(root.glob("requirements*.txt"))
    has_requirements_txt = (root / "requirements.txt").exists()
    other_req_files = [f for f in req_files if f.name != "requirements.txt"]
    pyproject_path = root / "pyproject.toml"
    has_pyproject = pyproject_path.exists()
    has_build_system = False
    if has_pyproject:
        try:
            pyproject_text = pyproject_path.read_text()
        except OSError:
            pyproject_text = ""
        has_build_system = any(re.match(r"^\[build-system\]", line) for line in pyproject_text.splitlines())
    is_python = (has_pyproject or (root / "setup.py").exists() or req_files
                 or any(re.match(r"\s*python3?\b", e["command"]) for e in commands))
    is_node = (root / "package.json").exists()
    out = ""
    if is_python:
        out += '      - uses: actions/setup-python@v5\n        with:\n          python-version: "3.x"\n'
        emitted = False
        if has_requirements_txt:
            out += "      - run: python -m pip install -r requirements.txt\n"
            emitted = True
        if other_req_files:
            names = ", ".join(f.name for f in other_req_files)
            out += f"      # also found: {names}; add it if CI needs it\n"
        if has_build_system:
            out += "      - run: python -m pip install -e .\n"
            emitted = True
        if not emitted:
            extras = [n for n, present in [
                ("pyproject.toml", has_pyproject),
                ("setup.py", (root / "setup.py").exists()),
                ("uv.lock", (root / "uv.lock").exists()),
                ("poetry.lock", (root / "poetry.lock").exists()),
            ] if present]
            suffix = (": " + ", ".join(extras)) if extras else ""
            out += f"      # no dependency setup found{suffix}: add this project's dependency setup here\n"
    if is_node:
        install = None
        comment = None
        if (root / "pnpm-lock.yaml").exists():
            package_manager = ""
            pkg_data = read_json(root / "package.json", {},
                                  record="Ratchet treats a damaged or non-object package.json as having no "
                                         "packageManager field")
            if isinstance(pkg_data, dict):
                package_manager = pkg_data.get("packageManager") or ""
            if isinstance(package_manager, str) and package_manager.startswith("pnpm@"):
                out += "      - uses: pnpm/action-setup@v4\n"
                install = "pnpm install --frozen-lockfile"
            else:
                comment = ("      # pnpm-lock.yaml found but package.json has no packageManager field "
                           "starting with pnpm@: add this project's pnpm setup here\n")
        elif (root / "yarn.lock").exists():
            comment = "      # yarn.lock found: add this project's yarn setup here (yarn 1 and yarn berry differ)\n"
        elif (root / "package-lock.json").exists() or (root / "npm-shrinkwrap.json").exists():
            install = "npm ci"
        else:
            install = "npm install"
        out += '      - uses: actions/setup-node@v4\n        with:\n          node-version: "20"\n'
        if install:
            out += f"      - run: {install}\n"
        if comment:
            out += comment
    return out


CI_RUN_INDENT = "          "  # content indent for a `run: |` block scalar: 2 more than "run:"'s own 8 spaces


def render_github_actions(ctx: Ctx, commands: list) -> str:
    """Deterministic GitHub Actions YAML text for `commands` (ci_commands(ctx)'s ordered, deduplicated
    list): one job that checks out the code, sets up the project's own language, then runs every command
    in order as its own step. Each command is written into a `run: |` block scalar exactly as given (every
    quote, $ sign and line kept, never re-escaped or collapsed to one line); every line of the command is
    indented by CI_RUN_INDENT so the whole block stays inside the scalar (a continuation line left at
    column 0 would end the block early and corrupt the workflow). When the command's first line itself
    starts with a space, an explicit indentation indicator (`|2`) is added so the parser can't mistake that
    leading space for part of the block's own indentation. Chomping is clip (plain `|`/`|2`): the command is
    normalized to exactly one trailing newline before rendering, which is what clip chomping hands back on
    parse, so the command round-trips exactly. Step names are JSON-quoted strings so a command's own text
    never has to be escaped into them. Nothing here is timestamped or otherwise non-deterministic: the same
    inputs always render the same text."""
    cfg = ctx.config()
    timeout_sec = cfg.get("test_timeout_sec") or DEFAULT_CONFIG["test_timeout_sec"]
    timeout_min = max(1, -(-int(timeout_sec) // 60))
    out = (
        CI_WORKFLOW_HEADER
        + "name: Ratchet checks\n"
        + "on:\n"
        + "  push:\n"
        + "  pull_request:\n"
        + "jobs:\n"
        + "  ratchet:\n"
        + "    runs-on: ubuntu-latest\n"
        + "    steps:\n"
        + "      - uses: actions/checkout@v4\n"
    )
    out += _ci_setup_steps(ctx, commands)
    for e in commands:
        out += f"      - name: {json.dumps(e['name'])}\n"
        if e.get("note"):
            out += f"        # {e['note']}\n"
        out += f"        timeout-minutes: {timeout_min}\n"
        cmd_text = (e["command"].rstrip("\n") + "\n") if e["command"].strip("\n") else "\n"
        body_lines = cmd_text.split("\n")[:-1]  # drop the "" artifact after the final newline
        indicator = "|2" if body_lines and body_lines[0].startswith(" ") else "|"
        out += f"        run: {indicator}\n"
        for line in body_lines:
            out += (CI_RUN_INDENT + line + "\n") if line else "\n"
    return out


CI_WORKFLOW_MARKER = CI_WORKFLOW_HEADER.split("\n", 1)[0] + "\n"  # the fixed first line that marks a file as Ratchet's
_UTF8_BOM = b"\xef\xbb\xbf"


def _normalized_for_marker_check(data: bytes) -> bytes:
    """`data` with an optional leading UTF-8 BOM stripped and CRLF normalized to LF, so a file Ratchet wrote
    that git's core.autocrlf (or a BOM-writing editor) converted on checkout is still recognized as Ratchet's
    own. Used only to decide ownership; the byte-equality check against the canonical (no-BOM, LF-only) text
    still uses the raw bytes, so a converted file is treated as needing an update back to that canonical text,
    not as already up to date."""
    if data.startswith(_UTF8_BOM):
        data = data[len(_UTF8_BOM):]
    return data.replace(b"\r\n", b"\n")


def _ci_workflow_bytes(text: str) -> bytes:
    """The exact bytes ci-export writes, compares and prints for workflow text `text` (backslashreplace,
    matching _write_record's own error handler), computed once so the up-to-date check, the file write and
    --stdout can never disagree, even when a check command holds a lone surrogate or other unencodable char."""
    return text.encode("utf-8", "backslashreplace")


def cmd_ci_export(args):
    ctx = Ctx(find_root())
    commands = ci_commands(ctx)
    if not commands:
        die("nothing to run: no regression command, no saved checks, and no completed step has its own "
            "test command. Set one (for example `ratchet.py config --set regression_command=...`) and "
            "run this again.")
    text = render_github_actions(ctx, commands)
    data = _ci_workflow_bytes(text)
    if getattr(args, "stdout", False):
        buf = getattr(sys.stdout, "buffer", None)
        if buf is not None:
            sys.stdout.flush()
            buf.write(data)
            buf.flush()
        else:  # no underlying byte stream (e.g. stdout replaced in a test harness): fall back to text
            print(text, end="")
        return
    path = ctx.root / ".github" / "workflows" / "ratchet.yml"
    cant_replace = ("won't replace it. Run `ratchet.py ci-export --stdout` to print the workflow instead, "
                     "so you can show it to the developer.")
    for parent in (ctx.root / ".github", ctx.root / ".github" / "workflows"):
        if parent.is_symlink():
            die(f"{parent} is a symlink: {cant_replace}")
    if path.is_symlink():
        die(f"{path} is a symlink, not a workflow Ratchet wrote: {cant_replace}")
    if path.is_dir():
        die(f"{path} is a directory, not a file: {cant_replace}")
    if path.exists():
        try:
            existing = path.read_bytes()
        except OSError as e:
            die(f"could not read {path}: {e}. Fix the permission or ownership problem, then run this again.")
        if not _normalized_for_marker_check(existing).startswith(CI_WORKFLOW_MARKER.encode()):
            die(f"{path} already exists and was not written by Ratchet (it doesn't start with Ratchet's "
                f"marker line): {cant_replace}")
        if existing == data:
            ok(f"{path} is already up to date.")
            return
    else:
        for parent in (ctx.root / ".github", ctx.root / ".github" / "workflows"):
            if parent.exists() and not parent.is_dir():
                die(f"{parent} already exists and is not a directory, so Ratchet can't write the workflow "
                    "there. Remove or rename it, then run this again.")
    try:
        _write_record(path, data, raw=True)
    except OSError as e:
        die(f"could not write {path}: {e}. Fix the permission or ownership problem, then run this again.")
    ok(f"wrote {path}")


def _ci_export_hint(ctx: Ctx) -> None:
    """Printed once by whichever command finishes a run (cmd_complete when human_review is none, the
    final cmd_human_approve otherwise): one line telling the agent it can keep this run's mechanical
    checks running on every push and pull request with `ratchet.py ci-export`, and asking it to mention
    that to the developer in plain words. Asks nothing new (no pending question) and stays silent when
    there is nothing to export, or .github/workflows/ratchet.yml already matches what ci-export would
    write -- reusing ci-export's own helpers (ci_commands, render_github_actions) so this can never
    disagree with what `ratchet.py ci-export` itself would decide."""
    try:
        commands = ci_commands(ctx)
        if not commands:
            return
        data = _ci_workflow_bytes(render_github_actions(ctx, commands))
        path = ctx.root / ".github" / "workflows" / "ratchet.yml"
        if path.exists() and not path.is_dir() and not path.is_symlink() and path.read_bytes() == data:
            return
    except Exception:
        return
    print("You can keep these checks running on every push and pull request: run `ratchet.py ci-export` "
          "to write a GitHub Actions workflow for them, and mention this to the developer in plain words.")


