    a.add_argument("--foreground", action="store_true", help=argparse.SUPPRESS)
    a.set_defaults(fn=cmd_lanes)
    a = sp.add_parser("director-key"); a.add_argument("--rotate", action="store_true"); a.set_defaults(fn=cmd_director_key)
